SC.data.de.l12n = [{"id": "L12-8T1-01", "loai": "khoi", "khoi": 12, "hoc_ki": 1, "bo": "8T1", "ten_bo": "8 tuần học kì I", "so_de": 1, "ten": "Lớp 12 · 8 tuần học kì I · Đề 1", "pham_vi": "Bài 1–4 (đề nguồn «8 TUẦN KÌ 1») · file nguồn: Đề 1.docx", "thoi_gian": 50, "cau_truc": "24 câu trắc nghiệm + 4 câu đúng/sai (mỗi câu 4 ý)", "status": "cho_duyet", "khoa": {"1 nguồn": 28}, "sua": "", "cau": [{"id": "L12-8T1-01-C01", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Bảo hiểm y tế là hình thức bảo hiểm thuộc lĩnh vực chăm sóc sức khỏe cộng đồng do", "o": ["đoàn thể thực hiện.", "Nhà nước thực hiện.", "Công đoàn thực hiện", "người dân thực hiện."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: Đề 1.docx · Phần I câu 1 · khoá: gạch chân"}, {"id": "L12-8T1-01-C02", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Theo quy định của pháp luật, người tham gia bảo hiểm xã hội bắt buộc nếu đủ điều kiện có thể được hưởng chế độ", "o": ["trợ cấp đi lại.", "trợ cấp thất nghiệp.", "trợ cấp lưu trú.", "trợ cấp thai sản."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: Đề 1.docx · Phần I câu 2 · khoá: gạch chân"}, {"id": "L12-8T1-01-C03", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Loại hình bảo hiểm do Nhà nước tổ chức mà người lao động và người sử dụng lao động thuộc đối tượng theo quy định phải tham gia là", "o": ["bảo hiểm thân thể.", "bảo hiểm xã hội tự nguyện.", "bảo hiểm xã hội bắt buộc.", "bảo hiểm tài sản."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: Đề 1.docx · Phần I câu 3 · khoá: gạch chân"}, {"id": "L12-8T1-01-C04", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Loại hình bảo hiểm do Nhà nước tổ chức nhằm bảo đảm thay thế hoặc bù đắp một phần thu nhập của người lao động khi họ bị giảm hoặc mất thu nhập do ốm, đau, thai sản, tai nạn lao động, bệnh nghề nghiệp, hết tuổi lao động dựa trên cơ sở mức đóng vào quỹ bảo hiểm xã hội của người lao động trước đó là loại hình bảo hiểm nào dưới đây?", "o": ["Bảo hiểm xã hội.", "Bảo hiểm dân sự.", "Bảo hiểm con người.", "Bảo hiểm thương mại."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: Đề 1.docx · Phần I câu 4 · khoá: gạch chân"}, {"id": "L12-8T1-01-C05", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Một trong những vai trò của an sinh xã hội là góp phần giúp các đối tượng được hưởng chính sách an sinh xã hội có thể chủ động, ngăn ngừa và giảm bớt", "o": ["phạm tội.", "rủi ro.", "quyền lợi.", "lợi nhuận."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: Đề 1.docx · Phần I câu 5 · khoá: gạch chân"}, {"id": "L12-8T1-01-C06", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Việc làm nào dưới đây góp phần thực hiện tốt chính sách an sinh xã hội về vấn đề giải quyết việc làm?", "o": ["Chia đều các nguồn thu nhập.", "Đẩy mạnh xuất khẩu lao động.", "Chấp hành quy tắc công cộng.", "Bảo trợ hoạt động truyền thông."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: Đề 1.docx · Phần I câu 6 · khoá: gạch chân"}, {"id": "L12-8T1-01-C07", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Một trong những mục tiêu của chính sách an sinh xã hội về bảo hiểm nhằm giúp người dân", "o": ["xóa đói giảm nghèo.", "xóa bỏ nhà tạm.", "phòng ngừa rủi ro.", "phòng ngừa thất nghiệp."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: Đề 1.docx · Phần I câu 7 · khoá: gạch chân"}, {"id": "L12-8T1-01-C08", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đối với đối tượng được hưởng chính sách an sinh xã hội, việc thực hiện tốt chính sách an sinh xã hội đem lại lợi ích nào dưới đây?", "o": ["Hưởng thu nhập vô điều kiện", "Được hoàn trả lại lợi ích đã mất.", "Khắc phục và giảm thiếu rủi ro.", "Được hỗ trợ miễn phí trọn đời."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: Đề 1.docx · Phần I câu 8 · khoá: gạch chân"}, {"id": "L12-8T1-01-C09", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Trong các quan hệ kinh tế quốc tế, việc tham gia của mỗi quốc gia không được thực hiện ở cấp độ nào dưới đây?", "o": ["Quy chế miễn thị thực.", "Liên minh kinh tế.", "Thị trường chung.", "Liên minh thuế quan."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: Đề 1.docx · Phần I câu 9 · khoá: gạch chân"}, {"id": "L12-8T1-01-C10", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Ngày 14/1/1998, tại Thủ đô Kuala Lumpur, Malaysia, Việt Nam đã chính thức trở thành thành viên của Diễn đàn hợp tác kinh tế châu Á – Thái Bình Dương (APEC). Việc gia nhập ASEAN là biểu hiện của hình thức hội nhập kinh tế quốc tế nào dưới đây?", "o": ["Toàn quốc.", "Toàn cầu.", "Song phương.", "Khu vực."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: Đề 1.docx · Phần I câu 10 · khoá: gạch chân"}, {"id": "L12-8T1-01-C11", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Hội nhập kinh tế là quá trình một quốc gia thực hiện việc gắn kết nền kinh tế của mình với", "o": ["người đứng đầu chính thủ.", "nguyên thủ của một nước.", "một nhóm người.", "các quốc gia khác."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: Đề 1.docx · Phần I câu 11 · khoá: gạch chân"}, {"id": "L12-8T1-01-C12", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Nội dung nào dưới đây không thể hiện vai trò và tác dụng to lớn của hội nhập kinh tế quốc tế đối với mỗi quốc gia?", "o": ["Thu hút vốn đầu tư.", "Mở rộng thị trường.", "Mở rộng biên giới.", "Tạo nhiều việc làm."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: Đề 1.docx · Phần I câu 12 · khoá: gạch chân"}, {"id": "L12-8T1-01-C13", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Tăng trưởng và phát triển kinh tế không có vai trò nào dưới đây?", "o": ["Thực hiện phân phối công bằng.", "Nâng cao mức sống người dân.", "Gia tăng khoảng cách giàu nghèo.", "Thu hẹp khoảng cách các vùng."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: Đề 1.docx · Phần I câu 13 · khoá: gạch chân"}, {"id": "L12-8T1-01-C14", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đối với mỗi quốc gia, chuyển dịch cơ cấu kinh tế nào dưới đây là tiêu chí đánh giá sự phát triển kinh tế?", "o": ["Cơ cấu vùng kinh tế.", "Cơ cấu lãnh thổ.", "Cơ cấu ngành kinh tế.", "Cơ cấu thu nhập."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: Đề 1.docx · Phần I câu 14 · khoá: gạch chân"}, {"id": "L12-8T1-01-C15", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Nội dung nào dưới đây không phải là tiêu chí thể hiện sự tăng trưởng kinh tế của một quốc gia?", "o": ["Sự gia tăng thu nhập của người dân.", "Sự gia tăng của dân số.", "Sự gia tăng của hàng hóa.", "Sự gia tăng mức sống của người dân."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: Đề 1.docx · Phần I câu 15 · khoá: gạch chân"}, {"id": "L12-8T1-01-C16", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Quá trình tăng trưởng kinh tế gắn liền với sự chuyển dịch cơ cấu kinh tế và đảm bảo tiến bộ xã hội là nội dung của khái niệm nào dưới đây?", "o": ["Phát triển kinh tế.", "Tăng trưởng kinh tế.", "Hội nhập kinh tế.", "Kinh tế đối ngoại."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: Đề 1.docx · Phần I câu 16 · khoá: gạch chân"}, {"id": "L12-8T1-01-C17", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đọc thông tin và trả lời câu hỏi 17, 18, 19\nBà H là lao động tự do sống trên địa bàn tỉnh Y. Sau một thời gian khám bệnh và điều trị tại bệnh viện K, bà H cầm trên tay hóa đơn, chứng từ thanh toán bảo hiểm y tế với số tiền 80 triệu đồng. Kết quả sau khi điều trị, bà đã được thanh toán gần một nửa chi phí điều trị gần 50 triệu đồng, thuộc đối tượng đồng chi trả 20%. Bà xúc động nói thêm: “Nhờ có sự tư vấn của cán bộ bảo hiểm xã hội, cách đây 5 tháng tôi có mua một tấm thẻ bảo hiểm y tế nay nhờ có tấm thẻ BHYT này mà tôi không trở thành gánh nặng tài chính của các con khi ốm đau, đến bây giờ bản thân tôi mới thắm thía  cái câu khẩu hiệu: “BHYT đóng góp khi lành để dành khi ốm. Có thẻ BHYT, mình được lợi rất nhiều về viện phí, chất lượng khám chữa bệnh cũng tương đương với dịch vụ, tôi mong rằng mọi người nên tham gia BHYT để được bảo vệ và chăm sóc sức khỏe, bản thân, gia đình một cách tốt nhất”.\nLoại hình bảo hiểm mà bà H tham gia có đặc điểm là", "o": ["bắt buộc.", "được tài trợ.", "được vĩnh viễn.", "tự nguyện."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: Đề 1.docx · Phần I câu 17 · khoá: gạch chân"}, {"id": "L12-8T1-01-C18", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đọc thông tin và trả lời câu hỏi 17, 18, 19\nBà H là lao động tự do sống trên địa bàn tỉnh Y. Sau một thời gian khám bệnh và điều trị tại bệnh viện K, bà H cầm trên tay hóa đơn, chứng từ thanh toán bảo hiểm y tế với số tiền 80 triệu đồng. Kết quả sau khi điều trị, bà đã được thanh toán gần một nửa chi phí điều trị gần 50 triệu đồng, thuộc đối tượng đồng chi trả 20%. Bà xúc động nói thêm: “Nhờ có sự tư vấn của cán bộ bảo hiểm xã hội, cách đây 5 tháng tôi có mua một tấm thẻ bảo hiểm y tế nay nhờ có tấm thẻ BHYT này mà tôi không trở thành gánh nặng tài chính của các con khi ốm đau, đến bây giờ bản thân tôi mới thắm thía  cái câu khẩu hiệu: “BHYT đóng góp khi lành để dành khi ốm. Có thẻ BHYT, mình được lợi rất nhiều về viện phí, chất lượng khám chữa bệnh cũng tương đương với dịch vụ, tôi mong rằng mọi người nên tham gia BHYT để được bảo vệ và chăm sóc sức khỏe, bản thân, gia đình một cách tốt nhất”.\nNhờ có tham gia loại hình bảo hiểm đã mang lại lợi ích gì dưới đây cho bà H khi gặp rủi ro về ốm đau?", "o": ["Khám chữa bệnh chất lượng cao.", "Giảm gánh nặng tài chính gia đình.", "Được hỗ trợ tiền sau khi ra viện.", "Được khám miễn phí suốt đời."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: Đề 1.docx · Phần I câu 18 · khoá: gạch chân"}, {"id": "L12-8T1-01-C19", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đọc thông tin và trả lời câu hỏi 17, 18, 19\nBà H là lao động tự do sống trên địa bàn tỉnh Y. Sau một thời gian khám bệnh và điều trị tại bệnh viện K, bà H cầm trên tay hóa đơn, chứng từ thanh toán bảo hiểm y tế với số tiền 80 triệu đồng. Kết quả sau khi điều trị, bà đã được thanh toán gần một nửa chi phí điều trị gần 50 triệu đồng, thuộc đối tượng đồng chi trả 20%. Bà xúc động nói thêm: “Nhờ có sự tư vấn của cán bộ bảo hiểm xã hội, cách đây 5 tháng tôi có mua một tấm thẻ bảo hiểm y tế nay nhờ có tấm thẻ BHYT này mà tôi không trở thành gánh nặng tài chính của các con khi ốm đau, đến bây giờ bản thân tôi mới thắm thía  cái câu khẩu hiệu: “BHYT đóng góp khi lành để dành khi ốm. Có thẻ BHYT, mình được lợi rất nhiều về viện phí, chất lượng khám chữa bệnh cũng tương đương với dịch vụ, tôi mong rằng mọi người nên tham gia BHYT để được bảo vệ và chăm sóc sức khỏe, bản thân, gia đình một cách tốt nhất”.\nLoại hình bảo hiểm mà bà H tham gia là", "o": ["Bảo hiểm thất nghiệp.", "Bảo hiểm y tế.", "Bảo hiểm xã hội.", "Bảo hiểm thương mại."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: Đề 1.docx · Phần I câu 19 · khoá: gạch chân"}, {"id": "L12-8T1-01-C20", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đọc thông tin và trả lời câu hỏi 20,21,22\nVề kinh tế, từng bước thực hiện tăng trưởng xanh, phát triển năng lượng sạch; thực hiện sản xuất và tiêu dùng bền vững. Tăng trưởng kinh tế giai đoạn 2016 - 2020 đạt trung bình 7%/năm, nâng mức thu nhập bình quân đầu người hằng năm tính theo GDP tăng lên 3.200 - 3.500 USD (so với mức 2.100 USD năm 2015). Lạm phát giữ ở mức dưới 5%. Thực hiện tiến bộ và công bằng xã hội; thực hiện tốt các chính sách an sinh xã hội; năm 2014 đã có 1,4 triệu người tham gia bảo hiểm xã hội, trên 8,5 triệu người tham gia bảo hiểm thất nghiệp, trên 72% dân số tham gia bảo hiểm y tế. Đời sống nhân dân được cải thiện. Thu nhập bình quân đầu người đạt 2.052 USD/người (2014). Tuổi thọ trung bình đạt 73,5 tuổi (2015). Hoàn thành nhiều mục tiêu Thiên niên kỷ.\nNội dung nào dưới đây không phải là chỉ tiêu để đánh giá sự phát triển kinh tế của Việt Nam trong thông tin trên?", "o": ["Thực hiện chính sách an sinh xã hội.", "Công tác giải quyết việc làm, bảo hiểm.", "Thu nhập bình quân đầu người (GNI/người)", "Tỷ lệ lạm phát và tăng giá hàng tiêu dùng."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: Đề 1.docx · Phần I câu 20 · khoá: gạch chân"}, {"id": "L12-8T1-01-C21", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đọc thông tin và trả lời câu hỏi 20,21,22\nVề kinh tế, từng bước thực hiện tăng trưởng xanh, phát triển năng lượng sạch; thực hiện sản xuất và tiêu dùng bền vững. Tăng trưởng kinh tế giai đoạn 2016 - 2020 đạt trung bình 7%/năm, nâng mức thu nhập bình quân đầu người hằng năm tính theo GDP tăng lên 3.200 - 3.500 USD (so với mức 2.100 USD năm 2015). Lạm phát giữ ở mức dưới 5%. Thực hiện tiến bộ và công bằng xã hội; thực hiện tốt các chính sách an sinh xã hội; năm 2014 đã có 1,4 triệu người tham gia bảo hiểm xã hội, trên 8,5 triệu người tham gia bảo hiểm thất nghiệp, trên 72% dân số tham gia bảo hiểm y tế. Đời sống nhân dân được cải thiện. Thu nhập bình quân đầu người đạt 2.052 USD/người (2014). Tuổi thọ trung bình đạt 73,5 tuổi (2015). Hoàn thành nhiều mục tiêu Thiên niên kỷ.\nNội dung nào dưới đây về phát triển kinh tế không được đề cập trong thông tin trên?", "o": ["Thu nhập bình quân đầu người (GNI/người).", "Tổng sản phẩm quốc dân (GDP).", "Tốc độ tăng dân số hàng năm.", "Thu nhập quốc nội theo đầu người (GDP/người)."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: Đề 1.docx · Phần I câu 21 · khoá: gạch chân"}, {"id": "L12-8T1-01-C22", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đọc thông tin và trả lời câu hỏi 20,21,22\nVề kinh tế, từng bước thực hiện tăng trưởng xanh, phát triển năng lượng sạch; thực hiện sản xuất và tiêu dùng bền vững. Tăng trưởng kinh tế giai đoạn 2016 - 2020 đạt trung bình 7%/năm, nâng mức thu nhập bình quân đầu người hằng năm tính theo GDP tăng lên 3.200 - 3.500 USD (so với mức 2.100 USD năm 2015). Lạm phát giữ ở mức dưới 5%. Thực hiện tiến bộ và công bằng xã hội; thực hiện tốt các chính sách an sinh xã hội; năm 2014 đã có 1,4 triệu người tham gia bảo hiểm xã hội, trên 8,5 triệu người tham gia bảo hiểm thất nghiệp, trên 72% dân số tham gia bảo hiểm y tế. Đời sống nhân dân được cải thiện. Thu nhập bình quân đầu người đạt 2.052 USD/người (2014). Tuổi thọ trung bình đạt 73,5 tuổi (2015). Hoàn thành nhiều mục tiêu Thiên niên kỷ.\nTốc độ tăng trưởng kinh tế giai 2016 - 2020 đạt trung bình 7%/năm có vai trò như thế nào đối với sự phát triển kinh tế của nước ta trong giai đoạn này?", "o": ["Quyết định nhất.", "Không đáng kể.", "Kìm hãm.", "Động lực."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: Đề 1.docx · Phần I câu 22 · khoá: gạch chân"}, {"id": "L12-8T1-01-C23", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đọc thông tin và trả lời câu hỏi 23,24\nTheo thống kê, hiện nước ta có khoảng hơn 20% dân số là những đối tượng yếu thế trong xã hội, trong đó khoảng trên 12 triệu người cao tuổi, gần 7 triệu người khuyết tật, người có vấn đề sức khỏe tâm thần, 2 triệu trẻ em có hoàn cảnh đặc biệt, khoảng 2 triệu lượt hộ gia đình cần được trợ giúp đột xuất hàng năm, 234.000 người nhiễm HIV được phát hiện, khoảng 30.000 nạn nhân bị bạo lực, bạo hành trong gia đình. Ngoài ra, còn các đối tượng là phụ nữ, trẻ em bị ngược đãi, bị mua bán, bị xâm hại, hoặc lang thang kiếm sống trên đường phố cần được sự trợ giúp của Nhà nước và xã hội.\nViệc thực hiện tốt các chính sách an sinh xã hội đối với các đối tượng là người yếu thế trong xã hội có vai trò nào dưới đây?", "o": ["Tạo bình đẳng trong xã hội.", "Giúp họ bớt tự ti, mặc cảm.", "Tạo gánh nặng cho xã hội.", "Gia tăng khoảng cách giàu nghèo."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: Đề 1.docx · Phần I câu 23 · khoá: gạch chân"}, {"id": "L12-8T1-01-C24", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đọc thông tin và trả lời câu hỏi 23,24\nTheo thống kê, hiện nước ta có khoảng hơn 20% dân số là những đối tượng yếu thế trong xã hội, trong đó khoảng trên 12 triệu người cao tuổi, gần 7 triệu người khuyết tật, người có vấn đề sức khỏe tâm thần, 2 triệu trẻ em có hoàn cảnh đặc biệt, khoảng 2 triệu lượt hộ gia đình cần được trợ giúp đột xuất hàng năm, 234.000 người nhiễm HIV được phát hiện, khoảng 30.000 nạn nhân bị bạo lực, bạo hành trong gia đình. Ngoài ra, còn các đối tượng là phụ nữ, trẻ em bị ngược đãi, bị mua bán, bị xâm hại, hoặc lang thang kiếm sống trên đường phố cần được sự trợ giúp của Nhà nước và xã hội.\nNội dung nào dưới đây không góp phần vào việc hỗ trợ, trợ giúp các lực lượng yếu thế trong xã hội với hệ thống chính sách an sinh xã hội của nước ta?", "o": ["Hỗ trợ về y tế và bảo hiểm.", "Ngăn cản họ tiếp cận dịch vụ xã hội.", "Xây dựng trung tâm bảo trợ xã hội.", "Trợ cấp kinh phí hàng tháng."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: Đề 1.docx · Phần I câu 24 · khoá: gạch chân"}, {"id": "L12-8T1-01-C25", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "dung_sai", "status": "cho_duyet", "q": "Theo Tổng cục Thống kê công bố, tốc độ tăng trưởng GDP năm 2023 đạt 5,05% và có xu hướng tăng dần theo thời gian, quý IV đạt 6,72%, cao nhất so với quý III, II và quý 1 (tương ứng đạt 5,47, 4,25% và 3,41%), cao hơn mức trung bình của thế giới và khu vực cũng như nhiều nước trong giai đoạn tăng trưởng nhanh.", "o": ["Tốc độ tăng trưởng GDP của Việt Nam năm 2023 đạt mức cao nhất so với các năm trước đó.", "Tốc độ tăng trưởng GDP của Việt Nam năm 2023 sẽ tỉ lệ thuận với mức thu nhập và đời sống của người dân.", "Tốc độ tăng trưởng GDP của Việt Nam năm 2023 cho thấy Việt Nam là quốc gia có mức sống cao.", "Tốc độ tăng trưởng GDP của Việt Nam năm 2023 là căn cứ để so sánh với sự tăng trưởng kinh tế của năm 2024."], "a": [true, true, false, true], "e": "Đáp án: a) Đúng; b) Đúng; c) Sai; d) Đúng.", "nguon": "Đề nguồn: Đề 1.docx · Phần II câu 1 · khoá: chữ Đúng/Sai trong ý · đề bài lấy lại từ bản gốc cùng câu"}, {"id": "L12-8T1-01-C26", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "dung_sai", "status": "cho_duyet", "q": "Đến nay, nước ta đã có quan hệ chính thức với 189/193 quốc gia và vùng lãnh thổ (trong đó có 4 đối tác chiến lược toàn diện, 17 đối tác chiến lược, 13 đối tác toàn diện); có quan hệ thương mại với 224 đối tác và quan hệ hợp tác với hơn 300 tổ chức quốc tế; đã ký hơn 90 hiệp định thương mại song phương, gần 60 hiệp định khuyến khích và bảo hộ đầu tư; đàm phán, ký kết và thực thi 19 Hiệp định thương mại tự do (FTA) song phương và đa phương với hầu hết các nền kinh tế lớn trên thế giới; trong đó 16 FTA đã có hiệu lực với hơn 60 đối tác, phủ rộng khắp các châu lục với tổng GDP chiếm gần 90% GDP toàn cầu, đưa Việt Nam trở thành một trong những nước dẫn đầu khu vực về tham gia các khuôn khổ hợp tác kinh tế song phương và đa phương.", "o": ["Nước ta có quan hệ hợp tác kinh tế với 189/193 quốc gia và vùng lãnh thổ.", "Việc ký kết các hiệp định thương mại song phương và đa phương giúp Việt Nam mở rộng hoạt động kinh tế đối ngoại.", "Kinh tế đối ngoại là yếu tố giữ vai trò quan trọng góp phần thúc đẩy tăng trưởng và phát triển kinh tế.", "Hoạt động kinh tế đối ngoại là một bộ phận cấu thành chính sách đối ngoại của Việt Nam."], "a": [false, true, true, true], "e": "Đáp án: a) Sai; b) Đúng; c) Đúng; d) Đúng.", "nguon": "Đề nguồn: Đề 1.docx · Phần II câu 2 · khoá: chữ Đúng/Sai trong ý · đề bài lấy lại từ bản gốc cùng câu"}, {"id": "L12-8T1-01-C27", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "dung_sai", "status": "cho_duyet", "q": "Chia sẻ về việc quyết định tham gia BHXH tự nguyện, chị D cho biết, trước đây chị làm công nhân đã có 10 năm tham gia BHXH bắt buộc và sau khi nghỉ việc chị không còn được tham gia nữa. Nghỉ việc ở nhà, chị chuyển sang bán hàng ăn để mưu sinh hàng ngày. Công việc vất vả, thức khuya dậy sớm khiến sức khỏe chị ngày một yếu đi. Lúc này chị bắt đầu nghĩ tới và tham gia BHXH tự nguyện. Tính đến nay chị đã đóng được 5 năm, mỗi lần đều đóng theo quý, mỗi quý hơn 600 ngàn đồng. Không những tham gia BHXH tự nguyện, chị còn tham gia cả BHYT hộ gia đình. Nói về lợi ích của việc tham gia những loại hình bảo hiểm trên, chị D xúc động cho hay: Tôi cũng vừa mới mổ u được vài tháng. Đến khi bị bệnh tôi mới thấy sự hữu ích của những loại hình bảo hiểm này. Cứ hoàn cảnh như hiện nay, khi hết tuổi lao động mà không tham gia các loại hình bảo hiểm của nhà nước sẽ không biết lấy gì nuôi thân nếu như không có nguồn thu ổn định.", "o": ["Chị D tham gia bảo hiểm bắt buộc 10 năm sau đó bỏ không tham gia vì đã nghỉ việc là hợp lý.", "Người lao động tự do nên tham gia bảo hiểm xã hội tự nguyện.", "Vì đã tham gia bảo hiểm xã hội nên khi nhập viện mổ khối u chị sẽ được hưởng trợ cấp ốm đau.", "Loại hình bảo hiểm y tế mà chị D tham gia là loại hình bảo hiểm y tế bắt buộc đối với mọi gia đình."], "a": [false, true, false, false], "e": "Đáp án: a) Sai; b) Đúng; c) Sai; d) Sai.", "nguon": "Đề nguồn: Đề 1.docx · Phần II câu 3 · khoá: chữ Đúng/Sai trong ý · đề bài lấy lại từ bản gốc cùng câu"}, {"id": "L12-8T1-01-C28", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "dung_sai", "status": "cho_duyet", "q": "Nhà nước đã dành 21% ngân sách cho phúc lợi xã hội, là mức cao nhất trong số các nước ASEAN, nhờ đó đã cơ bản thực hiện thành công các mục tiêu, nhiệm vụ đặt ra. Trong bối cảnh đại dịch COVID-19, thông qua chính sách hỗ trợ trực tiếp của Chính phủ và chính sách bảo hiểm xã hội, bảo hiểm thất nghiệp, đã hỗ trợ hơn 14,4 triệu người với tổng kinh phí hơn 33.000 tỷ đồng. Trong 5 năm qua, đời sống người có công không ngừng được nâng lên; hằng năm ngân sách Nhà nước dành hơn 32.000 tỷ đồng để thực hiện các chế độ ưu đãi người có công và thân nhân. Chính sách bảo hiểm xã hội, bảo hiểm y tế từng bước trở thành trụ cột chính trong hệ thống an sinh xã hội.", "o": ["Việc hỗ trợ kinh phí với các đối tượng là người có công và thân nhân là thực hiện chính sách trợ giúp xã hội.", "Tăng trưởng kinh tế đóng vai trò quan trọng trong việc thực hiện các chính sách an sinh xã hội.", "Việt Nam vừa chú trọng phát triển kinh tế vừa quan tâm thực hiện chính sách an sinh xã hội.", "Ngân sách nhà nước là nguồn lực duy nhất để thực hiện các chính sách an sinh."], "a": [true, true, true, false], "e": "Đáp án: a) Đúng; b) Đúng; c) Đúng; d) Sai.", "nguon": "Đề nguồn: Đề 1.docx · Phần II câu 4 · khoá: chữ Đúng/Sai trong ý · đề bài lấy lại từ bản gốc cùng câu"}]}, {"id": "L12-8T1-02", "loai": "khoi", "khoi": 12, "hoc_ki": 1, "bo": "8T1", "ten_bo": "8 tuần học kì I", "so_de": 2, "ten": "Lớp 12 · 8 tuần học kì I · Đề 2", "pham_vi": "Bài 1–4 (đề nguồn «8 TUẦN KÌ 1») · file nguồn: Đề 3.docx", "thoi_gian": 50, "cau_truc": "24 câu trắc nghiệm + 4 câu đúng/sai (mỗi câu 4 ý)", "status": "cho_duyet", "khoa": {"1 nguồn": 28}, "sua": "", "cau": [{"id": "L12-8T1-02-C01", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Tăng trưởng kinh tế không hợp lí tạo ra hậu quả gì đối với nền kinh tế", "o": ["cản trở quá trình phát triển bền vững.", "nâng cao chất lượng tăng trưởng.", "giữ vững ổn định chính trị.", "góp phần thúc đẩy tăng trưởng kinh tế"], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: Đề 3.docx · Phần I câu 1 · khoá: gạch chân"}, {"id": "L12-8T1-02-C02", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Điều kiện tiên quyết để khắc phục tình trạng tụt hậu đối với nước đang phát triển như Việt Nam là", "o": ["tăng trưởng kinh tế.", "phát triển con người.", "phát triển kinh tế.", "phát triển bền vững."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: Đề 3.docx · Phần I câu 2 · khoá: gạch chân"}, {"id": "L12-8T1-02-C03", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "“Duy trì tăng trưởng kinh tế bền vững đi đôi với thực hiện tiến bộ, công bằng xã hội và bảo vệ môi trường sinh thái, quản lí và sử dụng hiệu quả tài nguyên, chủ động ứng phó với biến đổi khí hậu” là nội dung của khái niệm nào sau đây?", "o": ["Tăng trưởng kinh tế.", "Phát triển bền vững.", "Phát triển kinh tế.", "Tiến bộ xã hội."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: Đề 3.docx · Phần I câu 3 · khoá: gạch chân"}, {"id": "L12-8T1-02-C04", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Thước đo tổng hợp phản ánh sự phát triển của con người trên các phương diện (sức khoẻ, tri thức, thu nhập) là nói đến chỉ số phát triển", "o": ["quốc gia.", "khu vực.", "kinh tế.", "con người."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: Đề 3.docx · Phần I câu 4 · khoá: gạch chân"}, {"id": "L12-8T1-02-C05", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Quá trình một quốc gia thực hiện gắn kết nền kinh tế của mình với nền kinh tế các quốc gia khác trong khu vực và trên thế giới dựa trên cơ sở cùng có lợi và tuân thủ các quy định chung là", "o": ["Hội nhập kinh tế quốc tế.", "Liên kết kinh tế quốc tế.", "Kết nối kinh tế quốc tế.", "Tích hợp kinh tế quốc tế."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: Đề 3.docx · Phần I câu 5 · khoá: gạch chân"}, {"id": "L12-8T1-02-C06", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đâu không phải cấp độ của hội nhập kinh tế quốc tế?", "o": ["Hội nhập kinh tế song phương.", "Hội nhập kinh tế khu vực.", "Hội nhập với nền kinh tế thế giới.", "Hội nhập kinh tế tự động."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: Đề 3.docx · Phần I câu 6 · khoá: gạch chân"}, {"id": "L12-8T1-02-C07", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Thế nào là hội nhập kinh tế song phương?", "o": ["Là sự liên kết đa quốc gia trong cùng khu vực.", "Là sự liên kết và hợp tác giữa năm quốc gia.", "Là sự liên kết, hợp tác giữa hai quốc gia.", "Là sự hợp tác giữa ba quốc gia."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: Đề 3.docx · Phần I câu 7 · khoá: gạch chân"}, {"id": "L12-8T1-02-C08", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Phát biểu nào sau đây là sai về quan điểm định hướng hội nhập kinh tế ở Việt Nam?", "o": ["Tích cực hội nhập kinh tế quốc tế toàn diện.", "Tích cực hội nhập kinh tế quốc tế sâu rộng.", "Hạn chế tham gia thoả thuận thương mại quốc tế.", "Đa phương hoá, đa dạng hoá quan hệ quốc tế."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: Đề 3.docx · Phần I câu 8 · khoá: gạch chân"}, {"id": "L12-8T1-02-C09", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Người lao động được bù đắp một phần thu nhập, hỗ trợ nghề, duy trì và tìm kiếm việc làm khi bị mất việc làm nếu tham gia", "o": ["bảo hiểm xã hội.", "bảo hiểm y tế.", "bảo hiểm thất nghiệp.", "bảo hiểm thương mại."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: Đề 3.docx · Phần I câu 9 · khoá: gạch chân"}, {"id": "L12-8T1-02-C10", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Phát biểu nào sau đây không phải là vai trò của bảo hiểm đối với xã hội?", "o": ["Góp phần tạo công ăn việc làm, giảm thất nghiệp trong nền kinh tế.", "Đảm bảo an toàn cho cuộc sống con người.", "Góp phần hình thành lối sống tiết kiệm trên phạm vi toàn xã hội.", "Góp phần ổn định tài chính, đảm bảo an toàn cho các khoản đầu tư."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: Đề 3.docx · Phần I câu 10 · khoá: gạch chân"}, {"id": "L12-8T1-02-C11", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Tổ chức, cá nhân giao kết hợp đồng bảo hiểm với tổ chức bảo hiểm và đóng phí bảo hiểm được gọi là", "o": ["người thụ hưởng.", "bên thứ ba.", "người được bảo hiểm.", "bên mua bảo hiểm."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: Đề 3.docx · Phần I câu 11 · khoá: gạch chân"}, {"id": "L12-8T1-02-C12", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Loại hình bảo hiểm do Nhà nước tổ chức mà người lao động và người sử dụng lao động thuộc đối tượng theo quy định phải tham gia là", "o": ["bảo hiểm thân thể.", "bảo hiểm xã hội tự nguyện.", "bảo hiểm xã hội bắt buộc.", "bảo hiểm tài sản."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: Đề 3.docx · Phần I câu 12 · khoá: gạch chân"}, {"id": "L12-8T1-02-C13", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Một trong những mục tiêu của việc thực hiện chính sách trợ giúp xã hội là nhằm giúp các đối tượng yếu thế trong xã hội có thể", "o": ["ổn định cuộc sống.", "mặc cảm và tự ti.", "từ bỏ cuộc sống.", "gia tăng giàu nghèo."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: Đề 3.docx · Phần I câu 13 · khoá: gạch chân"}, {"id": "L12-8T1-02-C14", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Trong hệ thống chính sách an sinh xã hội ở nước ta hiện nay, một trong những chính sách dịch vụ xã hội cơ bản là dịch vụ", "o": ["việc làm tối thiểu.", "thu nhập tối đa.", "y tế tối thiểu.", "bảo hiểm tối thiểu."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: Đề 3.docx · Phần I câu 14 · khoá: gạch chân"}, {"id": "L12-8T1-02-C15", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Việc nhà nước có chính sách hỗ trợ gạo từ nguồn ngân sách nhà nước cho nhân dân các vùng khó khăn dịp Tết nguyên đán là thực hiện chính sách an sinh xã hội nào dưới đây?", "o": ["Chính sách hỗ trợ bảo hiểm.", "Chính sách trợ giúp xã hội.", "Chính sách trợ giúp việc làm.", "Chính sách hỗ trợ thu nhập."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: Đề 3.docx · Phần I câu 15 · khoá: gạch chân"}, {"id": "L12-8T1-02-C16", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đối với sự phát triển kinh tế - xã hội, việc thực hiện tốt chính sách an sinh xã hội sẽ góp phần", "o": ["thúc đẩy sự phân hóa giàu nghèo.", "thúc đẩy phát triển kinh tế - xã hội.", "thúc đẩy tình trạng thất nghiệp.", "thúc đẩy tình trạng lạm phát."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: Đề 3.docx · Phần I câu 16 · khoá: gạch chân"}, {"id": "L12-8T1-02-C17", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đọc thông tin và trả lời câu hỏi 17, 18\nPhát triển vì con người là mô hình được Đảng và Nhà nước lựa chọn trong quá trình vận hành nền kinh tế thị trường định hướng xã hội chủ nghĩa ở Việt Nam. Theo đó, yêu cầu đặt ra là tăng trưởng và phát triển kinh tế hiệu quả phải gắn với việc phát triển con người. Trong thời gian qua, tăng trưởng kinh tế tuy đã có tác động tích cực đến phát triển con người, nhưng hiệu ứng tác động tích cực đang có xu hướng giảm dần. Do đó, định hướng và những giải pháp cần thiết để hướng thành quả tăng trưởng kinh tế vào phát triển con người một cách hiệu quả nhất là cần thiết hiện nay để nhằm mục tiêu hướng đến các giá trị phát triển con người.\n(Theo: Tạp chí Cộng sản, “Tác động của phát triển kinh tế đến phát triển con người ở Việt Nam: Vấn đề và giải pháp”, ngày 29/8/2019)\nĐể tạo điều kiện cho mọi người đều có việc làm và thu nhập ổn định, có cuộc sống ấm no, có điều kiện chăm sóc sức khoẻ, nâng cao tuổi thọ..., Nhà nước kiên trì theo đuổi mục tiêu", "o": ["đa phương hoá trong quan hệ quốc tế.", "đẩy mạnh nghiên cứu khoa học, công nghệ.", "ưu tiên, đầu tư phát triển giáo dục và đào tạo.", "tăng trưởng và phát triển kinh tế."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: Đề 3.docx · Phần I câu 17 · khoá: gạch chân"}, {"id": "L12-8T1-02-C18", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đọc thông tin và trả lời câu hỏi 17, 18\nPhát triển vì con người là mô hình được Đảng và Nhà nước lựa chọn trong quá trình vận hành nền kinh tế thị trường định hướng xã hội chủ nghĩa ở Việt Nam. Theo đó, yêu cầu đặt ra là tăng trưởng và phát triển kinh tế hiệu quả phải gắn với việc phát triển con người. Trong thời gian qua, tăng trưởng kinh tế tuy đã có tác động tích cực đến phát triển con người, nhưng hiệu ứng tác động tích cực đang có xu hướng giảm dần. Do đó, định hướng và những giải pháp cần thiết để hướng thành quả tăng trưởng kinh tế vào phát triển con người một cách hiệu quả nhất là cần thiết hiện nay để nhằm mục tiêu hướng đến các giá trị phát triển con người.\n(Theo: Tạp chí Cộng sản, “Tác động của phát triển kinh tế đến phát triển con người ở Việt Nam: Vấn đề và giải pháp”, ngày 29/8/2019)\nĐặc trưng của mô hình Phát triển vì con người là hướng thành quả của tăng trưởng kinh tế vào phát triển", "o": ["văn hoá.", "xã hội.", "con người.", "khoa học."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: Đề 3.docx · Phần I câu 18 · khoá: gạch chân"}, {"id": "L12-8T1-02-C19", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đọc thông tin và trả lời câu hỏi 19, 20\nNăm 2023 đã chứng kiến nhiều cột mốc quan trọng trong quá trình hội nhập kinh tế quốc tế của Việt Nam. Ngoài việc thực hiện 15 Hiệp định thương mại  tự do (FTA), Việt Nam còn kí kết FTA song phương với Israel (VIFTA) và hoàn tất đàm phán với UAE mở ra cánh cửa thị trường Trung Đông, với quy mô GDP khoảng 2 000 tỉ USD.\n(Theo: Báo Mới, “Dấu ấn hội nhập kinh tế quốc tế năm 2023”, ngày 02/01/2024)\nViệc Việt Nam tham gia hợp tác kinh tế quốc tế với Israel (VIFTA) thể hiện cấp độ nào của hội nhập kinh tế quốc tế?", "o": ["Cấp độ song phương.", "Cấp độ đa phương.", "Cấp độ khu vực.", "Cấp độ toàn cầu."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: Đề 3.docx · Phần I câu 19 · khoá: gạch chân"}, {"id": "L12-8T1-02-C20", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đọc thông tin và trả lời câu hỏi 19, 20\nNăm 2023 đã chứng kiến nhiều cột mốc quan trọng trong quá trình hội nhập kinh tế quốc tế của Việt Nam. Ngoài việc thực hiện 15 Hiệp định thương mại  tự do (FTA), Việt Nam còn kí kết FTA song phương với Israel (VIFTA) và hoàn tất đàm phán với UAE mở ra cánh cửa thị trường Trung Đông, với quy mô GDP khoảng 2 000 tỉ USD.\n(Theo: Báo Mới, “Dấu ấn hội nhập kinh tế quốc tế năm 2023”, ngày 02/01/2024)\nViệc Việt Nam tham gia các Hiệp định thương mại tự do (FTA) sẽ đem lại lợi ích gì?", "o": ["Thu hẹp thị trường xuất, nhập khẩu.", "Tách biệt mối quan hệ kinh tế.", "Giảm nguy cơ cạnh tranh.", "Mở rộng thị trường xuất khẩu."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: Đề 3.docx · Phần I câu 20 · khoá: gạch chân"}, {"id": "L12-8T1-02-C21", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đọc thông tin và trả lời câu hỏi 21, 22\nBà H là lao động tự do sống trên địa bàn tỉnh Y. Sau một thời gian khám bệnh và điều trị tại bệnh viện K, bà H cầm trên tay hóa đơn, chứng từ thanh toán bảo hiểm y tế với số tiền 80 triệu đồng. Kết quả sau khi điều trị, bà đã được thanh toán gần một nửa chi phí điều trị gần 50 triệu đồng, thuộc đối tượng đồng chi trả 20%. Bà xúc động nói thêm: “Nhờ có sự tư vấn của cán bộ bảo hiểm xã hội, cách đây 5 tháng tôi có mua một tấm thẻ bảo hiểm y tế nay nhờ có tấm thẻ BHYT này mà tôi không trở thành gánh nặng tài chính của các con khi ốm đau, đến bây giờ bản thân tôi mới thắm thía  cái câu khẩu hiệu: “BHYT đóng góp khi lành để dành khi ốm. Có thẻ BHYT, mình được lợi rất nhiều về viện phí, chất lượng khám chữa bệnh cũng tương đương với dịch vụ, tôi mong rằng mọi người nên tham gia BHYT để được bảo vệ và chăm sóc sức khỏe, bản thân, gia đình một cách tốt nhất”.\nLoại hình bảo hiểm mà bà H tham gia có đặc điểm là", "o": ["bắt buộc.", "được tài trợ.", "được vĩnh viễn.", "tự nguyện."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: Đề 3.docx · Phần I câu 21 · khoá: gạch chân"}, {"id": "L12-8T1-02-C22", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đọc thông tin và trả lời câu hỏi 21, 22\nBà H là lao động tự do sống trên địa bàn tỉnh Y. Sau một thời gian khám bệnh và điều trị tại bệnh viện K, bà H cầm trên tay hóa đơn, chứng từ thanh toán bảo hiểm y tế với số tiền 80 triệu đồng. Kết quả sau khi điều trị, bà đã được thanh toán gần một nửa chi phí điều trị gần 50 triệu đồng, thuộc đối tượng đồng chi trả 20%. Bà xúc động nói thêm: “Nhờ có sự tư vấn của cán bộ bảo hiểm xã hội, cách đây 5 tháng tôi có mua một tấm thẻ bảo hiểm y tế nay nhờ có tấm thẻ BHYT này mà tôi không trở thành gánh nặng tài chính của các con khi ốm đau, đến bây giờ bản thân tôi mới thắm thía  cái câu khẩu hiệu: “BHYT đóng góp khi lành để dành khi ốm. Có thẻ BHYT, mình được lợi rất nhiều về viện phí, chất lượng khám chữa bệnh cũng tương đương với dịch vụ, tôi mong rằng mọi người nên tham gia BHYT để được bảo vệ và chăm sóc sức khỏe, bản thân, gia đình một cách tốt nhất”.\nNhờ có tham gia loại hình bảo hiểm đã mang lại lợi ích gì dưới đây cho bà H khi gặp rủi ro về ốm đau?", "o": ["Khám chữa bệnh chất lượng cao.", "Giảm gánh nặng tài chính gia đình.", "Được hỗ trợ tiền sau khi ra viện.", "Được khám miễn phí suốt đời."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: Đề 3.docx · Phần I câu 22 · khoá: gạch chân"}, {"id": "L12-8T1-02-C23", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đọc thông tin và trả lời câu hỏi 23, 24\nTrong năm 2023 toàn tỉnh M đã giải quyết việc làm mới cho hơn 8.000 lao động, trong 5 năm  đã tạo việc làm cho 41.394 lao động, đạt 103% so với kế hoạch. Tỉ lệ thất nghiệp ở khu vực thành thị giảm từ 5,2% năm xuống còn 4,54%. Tỉ lệ sử dụng thời gian lao động ở khu vực nông thôn tăng dần, đạt 75% tăng lên 85%. Chương trình mục tiêu giảm nghèo của tỉnh triển khai có hiệu quả các chính sách, chương trình hỗ trợ người nghèo, hộ nghèo, vùng nghèo. Đa số hộ nghèo được nâng cao nhận thức, cố gắng tìm tòi học tập kinh nghiệm trong sản xuất, tự tạo việc làm để vươn lên thoát nghèo, cải thiện điều kiện sống và sinh hoạt. Kết quả giảm nghèo của toàn tỉnh trong 5 năm đã vượt mục tiêu đề ra, giảm từ 38.085 hộ nghèo, chiếm tỉ lệ 28,4% xuống còn 18.048 hộ nghèo.\nViệc giảm tỷ lệ thất nghiệp ở khu vực thành thị đã phản ánh hiệu quả của chính sách an sinh xã hội nào dưới đây mà tỉnh M đã thực hiện?", "o": ["Chính sách bảo hiểm.", "Chính sách giảm nghèo.", "Chính sách việc làm.", "Chính sách thu nhập."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: Đề 3.docx · Phần I câu 23 · khoá: gạch chân"}, {"id": "L12-8T1-02-C24", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đọc thông tin và trả lời câu hỏi 23, 24\nTrong năm 2023 toàn tỉnh M đã giải quyết việc làm mới cho hơn 8.000 lao động, trong 5 năm  đã tạo việc làm cho 41.394 lao động, đạt 103% so với kế hoạch. Tỉ lệ thất nghiệp ở khu vực thành thị giảm từ 5,2% năm xuống còn 4,54%. Tỉ lệ sử dụng thời gian lao động ở khu vực nông thôn tăng dần, đạt 75% tăng lên 85%. Chương trình mục tiêu giảm nghèo của tỉnh triển khai có hiệu quả các chính sách, chương trình hỗ trợ người nghèo, hộ nghèo, vùng nghèo. Đa số hộ nghèo được nâng cao nhận thức, cố gắng tìm tòi học tập kinh nghiệm trong sản xuất, tự tạo việc làm để vươn lên thoát nghèo, cải thiện điều kiện sống và sinh hoạt. Kết quả giảm nghèo của toàn tỉnh trong 5 năm đã vượt mục tiêu đề ra, giảm từ 38.085 hộ nghèo, chiếm tỉ lệ 28,4% xuống còn 18.048 hộ nghèo.\nChính sách an sinh xã hội nào dưới đây mà tỉnh M triển khai đã giúp các hộ nghèo từng bước ổn định cuộc sống?", "o": ["Chính sách dịch vụ xã hội.", "Chính sách xóa đói, giảm nghèo.", "Chính sách trợ giúp xã hội.", "Chính sách bảo hiểm xã hội."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: Đề 3.docx · Phần I câu 24 · khoá: gạch chân"}, {"id": "L12-8T1-02-C25", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "dung_sai", "status": "cho_duyet", "q": "Chỉ số phát triển con người (HDI) các nước và vùng lãnh thổ trên thế giới được chia thành 4 nhóm: nhóm 1 - nhóm rất cao, có HDI từ 0,800 trở lên; nhóm 2 - nhóm cao, có HDI từ 0,400 đến dưới 0,800; nhóm 3 - nhóm trung bình, có HDI từ 0,550 đến dưới 0,400; nhóm 4 - nhóm thấp, có HDI dưới 0,550. HDI của Việt Nam đã liên tục tăng lên trong những năm gần đây, theo đó, Việt Nam đã chuyển từ nhóm trung bình lên nhóm cao từ năm 2019 đến nay. Việt Nam có vị trí về HDI cao hơn vị trí về thu nhập - tức là thứ bậc về HDI cao hơn thứ bậc về thu nhập. Điều đó là phù hợp với nền kinh tế mà Việt Nam lựa chọn là nền kinh tế thị trường theo định hướng vì con người. Tuy nhiên, về HDI, Việt Nam vẫn còn đứng ở thứ bậc thấp. (Theo Báo Đầu tư)", "o": ["HDI là chỉ tiêu phản ánh về 3 mặt: thu nhập, sức khỏe, giáo dục.", "Việt Nam nằm trong nhóm các quốc gia có chỉ số phát triển con người thấp.", "Chỉ số phát triển con người tăng thể hiện xã hội có tiến bộ.", "HDI là chỉ tiêu đánh giá tăng trưởng kinh tế."], "a": [true, false, true, false], "e": "Đáp án: a) Đúng; b) Sai; c) Đúng; d) Sai.", "nguon": "Đề nguồn: Đề 3.docx · Phần II câu 1 · khoá: chữ Đúng/Sai trong ý"}, {"id": "L12-8T1-02-C26", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "dung_sai", "status": "cho_duyet", "q": "Trong bối cảnh khu vực hóa, toàn cầu hóa, Việt Nam đã trở thành thành viên tích cực và có trách nhiệm của cộng đồng quốc tế. Quan hệ song phương và đa phương ngày càng được củng cố, phát triển và dần đi vào chiều sâu. Chúng ta đã xác lập quan hệ đối tác chiến lược, đối tác toàn diện với nhiều nước, trong đó với tất cả 5 nước Ủy viên thường trực Hội đồng bảo an Liên hợp quốc tạo ra chuyển biến mới về chất trong hoạt động đối ngoại. Việt Nam ngày càng thực sự phát huy vai trò của mình trong việc tham gia ngày càng sâu rộng vào quá trình liên kết khu vực và thế giới. Là thành viên của Hiệp hội các quốc gia Đông Nam Á (ASEAN) từ năm 1995, nước ta tham gia tích cực và đóng góp vào quá trình xây dựng Cộng đồng ASEAN, tham gia các tổ chức và diễn đàn khác như Diễn đàn An ninh khu vực (ARF), Cộng đồng kinh tế châu Á - Thái bình dương (APEC) Diễn đàn cấp cao Đông Á (EAS), Cộng đồng Pháp ngữ, Phong trào không liên kết... Nước ta đã tham gia nhiều Hiệp định thương mại tự do song phương và khu vực và đang đàm phán các Hiệp định thương mại tự do thế hệ mới, trong đó có Hiệp định đối tác xuyên Thái Bình Dương (TPP) và Hiệp định đối tác hợp tác kinh tế khu vực (RCEP). (Nguồn: Bài viết đăng tải trên Ấn phẩm Tạp chí Nghiên cứu lập pháp số 18(298), tháng 9/2015)", "o": ["Việt Nam hội nhập kinh tế với nhiều cấp độ: song phương, khu vực và quốc tế.", "Việt Nam chỉ chú trọng hội nhập kinh tế khu vực vì các nước trong khu vực có đặc điểm, vị trí địa lí tương đồng sẽ thuận lợi cho quá trình hợp tác.", "Việt Nam là một thành viên tích cực trong hoạt động hội nhập kinh tế quốc tế.", "Hội nhập kinh tế sẽ làm giảm vị thế của Việt Nam trên trường quốc tế."], "a": [true, false, true, false], "e": "Đáp án: a) Đúng; b) Sai; c) Đúng; d) Sai.", "nguon": "Đề nguồn: Đề 3.docx · Phần II câu 2 · khoá: chữ Đúng/Sai trong ý"}, {"id": "L12-8T1-02-C27", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "dung_sai", "status": "cho_duyet", "q": "Chị N làm việc tại Doanh nghiệp Y theo hợp đồng không xác định thời hạn. Trong quá trình làm việc tại doang nghiệp, chị N và Doanh nghiệp Y đã tham gia và đóng các loại bảo hiểm bắt buộc cho chị N đúng quy định của Luật Bảo hiểm xã hội, Luật Bảo hiểm y tế và Luật Việc làm. Sau một thời gian làm việc, chị N đã bị chấm dứt hợp đồng lao động do doanh nghiệp làm ăn thua lỗ dẫn đến phá sản. Sau khi bị chấm dứt hợp đồng, chị N bị mất việc nên cuộc sống gặp nhiều khó khăn. Sau 3 tháng kể từ khi mất việc chị nhận được khoản tiền trợ cấp thất nghiệp nên chị có thể đảm bảo được cuộc sống hiện tại của mình.", "o": ["Chị N thuộc diện tham gia bảo hiểm thất nghiệp, bảo hiểm xã hội và bảo hiểm y tế bắt buộc.", "Chị N thuộc đối tượng tham gia bảo hiểm xã hội, bảo hiểm y tế tự nguyện.", "Bảo hiểm thất nghiệp là bảo hiểm thuộc lĩnh vực chăm sóc sức khỏe.", "Bảo hiểm thất nghiệp đã thể hiện vai trò giảm tổn thất, góp phần ổn định cuộc sống chị N khi mất việc."], "a": [true, false, false, true], "e": "Đáp án: a) Đúng; b) Sai; c) Sai; d) Đúng.", "nguon": "Đề nguồn: Đề 3.docx · Phần II câu 3 · khoá: chữ Đúng/Sai trong ý"}, {"id": "L12-8T1-02-C28", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "dung_sai", "status": "cho_duyet", "q": "Nhà nước đã dành 21% ngân sách cho phúc lợi xã hội, là mức cao nhất trong số các nước ASEAN, nhờ đó đã cơ bản thực hiện thành công các mục tiêu, nhiệm vụ đặt ra. Trong bối cảnh đại dịch COVID-19, thông qua chính sách hỗ trợ trực tiếp của Chính phủ và chính sách bảo hiểm xã hội, bảo hiểm thất nghiệp, đã hỗ trợ hơn 14,4 triệu người với tổng kinh phí hơn 33.000 tỷ đồng. Trong 5 năm qua, đời sống người có công không ngừng được nâng lên; hằng năm ngân sách Nhà nước dành hơn 32.000 tỷ đồng để thực hiện các chế độ ưu đãi người có công và thân nhân. Chính sách bảo hiểm xã hội, bảo hiểm y tế từng bước trở thành trụ cột chính trong hệ thống an sinh xã hội.", "o": ["Việc hỗ trợ kinh phí với các đối tượng là người có công và thân nhân là thực hiện chính sách trợ giúp xã hội.", "Tăng trưởng kinh tế đóng vai trò quan trọng trong việc thực hiện các chính sách an sinh xã hội.", "Việt Nam vừa chú trọng phát triển kinh tế vừa quan tâm thực hiện chính sách an sinh xã hội.", "Ngân sách nhà nước là nguồn lực duy nhất để thực hiện các chính sách an sinh."], "a": [true, true, true, false], "e": "Đáp án: a) Đúng; b) Đúng; c) Đúng; d) Sai.", "nguon": "Đề nguồn: Đề 3.docx · Phần II câu 4 · khoá: chữ Đúng/Sai trong ý"}]}, {"id": "L12-8T1-03", "loai": "khoi", "khoi": 12, "hoc_ki": 1, "bo": "8T1", "ten_bo": "8 tuần học kì I", "so_de": 3, "ten": "Lớp 12 · 8 tuần học kì I · Đề 3", "pham_vi": "Bài 1–4 (đề nguồn «8 TUẦN KÌ 1») · file nguồn: Đề 4.docx", "thoi_gian": 50, "cau_truc": "24 câu trắc nghiệm + 4 câu đúng/sai (mỗi câu 4 ý)", "status": "cho_duyet", "khoa": {"1 nguồn": 27, "đã tự giải lại": 1}, "sua": "Câu 11: tổ chức, cá nhân giao kết hợp đồng bảo hiểm và đóng phí là «bên mua bảo hiểm» (D). Đề 8T1-02 có cùng câu và khoá D; khoá C («người được bảo hiểm») trong đề này sai.", "cau": [{"id": "L12-8T1-03-C01", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Quá trình tăng tiến về mọi mặt của nền kinh tế trong một thời gian nhất định là", "o": ["phát triển sản xuất.", "tiến bộ xã hội.", "phát triển kinh tế.", "tăng trưởng kinh tế."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: Đề 4.docx · Phần I câu 1 · khoá: gạch chân"}, {"id": "L12-8T1-03-C02", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Nội dung nào dưới đây không phải là chỉ tiêu về tiến bộ xã hội?", "o": ["Chỉ số phát triển con người.", "Chỉ số đói nghèo.", "Chỉ số bất bình đẳng xã hội.", "Chỉ số chi tiêu."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: Đề 4.docx · Phần I câu 2 · khoá: gạch chân"}, {"id": "L12-8T1-03-C03", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Phát triển kinh tế không bao gồm nội dung nào dưới đây?", "o": ["Tăng trưởng kinh tế.", "Chuyển dịch cơ cấu kinh tế", "Tiến bộ công bằng xã hội.", "Tốc độ tăng trưởng kinh tế."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: Đề 4.docx · Phần I câu 3 · khoá: gạch chân"}, {"id": "L12-8T1-03-C04", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Chỉ số HDI bao gồm các chỉ số nào sau đây?", "o": ["Sức khỏe, thông minh và dân số.", "Thông minh, dân số, giới tính.", "Sức khỏe, giáo dục và thu nhập.", "Giới tính, thông minh, hạnh phúc."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: Đề 4.docx · Phần I câu 4 · khoá: gạch chân"}, {"id": "L12-8T1-03-C05", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Quá trình hội nhập kinh tế quốc tế của mỗi quốc gia phải dựa trên cơ sở nào sau đây?", "o": ["Cùng có lợi và tuân thủ các quy định chung.", "Cùng có lợi, và tuân thủ các lợi ích.", "Vì lợi ích chung và cùng thoả hiệp chung.", "Cùng thỏa thuận chung, đặt lợi ích kinh tế lên trên."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: Đề 4.docx · Phần I câu 5 · khoá: gạch chân"}, {"id": "L12-8T1-03-C06", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Quá trình một quốc gia thực hiện gắn kết nền kinh tế cuả mình với nền kinh tế các quốc gia khác được gọi là", "o": ["Tăng trưởng kinh tế.", "Xuất khẩu quốc tế.", "Hội nhập kinh tế.", "Phát triển kinh tế."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: Đề 4.docx · Phần I câu 6 · khoá: gạch chân"}, {"id": "L12-8T1-03-C07", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Hội nhập kinh tế quốc tế dược thực hiện theo những cấp độ nào dưới đây?", "o": ["Đối thoại đa phương, đối thoại khu vực và đối thoại toàn cầu.", "Hội nhập khu vực, hội nhập song phương, hội nhập toàn quốc.", "Hội nhập khu vực, hội nhập song phương, hội nhập toàn cầu.", "Kết nối toàn diện, kết nối song phương, kết nối toàn cầu."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: Đề 4.docx · Phần I câu 7 · khoá: gạch chân"}, {"id": "L12-8T1-03-C08", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Trong hội nhập kinh tế quốc tế, quá trình liên kết, hợp tác giữa các quốc gia thông qua việc tham gia các tổ chức toàn cầu được gọi là", "o": ["hội nhập toàn cầu.", "hợp tác khu vực.", "hội nhập song phương.", "hội nhập đa phương."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: Đề 4.docx · Phần I câu 8 · khoá: gạch chân"}, {"id": "L12-8T1-03-C09", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Hoạt động dịch vụ tài chính thông qua đó người tham gia bảo hiểm đóng một khoản phí cho tổ chức bảo hiểm để được bồi thường hoặc chi trả bảo hiểm khi xảy ra sự kiện bảo hiểm là nội dung của khái niệm nào sau đây?", "o": ["Bảo tức.", "Tín dụng.", "Bảo hiểm.", "Tài chính."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: Đề 4.docx · Phần I câu 9 · khoá: gạch chân"}, {"id": "L12-8T1-03-C10", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Nhận định nào dưới đây đúng khi nói về vai trò của bảo hiểm đối với việc quản lí rủi ro cá nhân?", "o": ["Chuyển rủi ro từ người tham gia bảo hiểm sang công ty bảo hiểm.", "Tăng khoản tiết kiệm và đầu tư cho người tham gia bảo hiểm.", "Thay thế nhu cầu về quỹ dự trữ khẩn cấp cho cá nhân và gia đình.", "Hạn chế quyền lợi của người tham gia bảo hiểm khi xảy ra tổn thất."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: Đề 4.docx · Phần I câu 10 · khoá: gạch chân"}, {"id": "L12-8T1-03-C11", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Tổ chức cá nhân giao kết hợp đồng bảo hiểm với tổ chức bảo hiểm và đóng phí bảo hiểm được gọi là", "o": ["Người thụ hưởng.", "Bên thứ ba.", "Người được bảo hiểm.", "Bên mua bảo hiểm."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: Đề 4.docx · Phần I câu 11 · khoá: ĐÃ TỰ GIẢI LẠI (đối chiếu SGK)"}, {"id": "L12-8T1-03-C12", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Bảo hiểm là hoạt động chuyển giao rủi ro giữa bên tham gia bảo hiểm và tổ chức bảo hiểm thông qua", "o": ["thỏa thuận", "giao kết.", "cam kết.", "xác nhận"], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: Đề 4.docx · Phần I câu 12 · khoá: gạch chân"}, {"id": "L12-8T1-03-C13", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Hệ thống các chính sách can thiệp của nhà nước và các lực lượng xã hội thực hiện nhằm giảm mức độ nghèo đói là gì?", "o": ["Bảo hiểm xã hội.", "An sinh xã hội.", "Trợ giúp xã hội.", "Bảo vệ xã hội."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: Đề 4.docx · Phần I câu 13 · khoá: gạch chân"}, {"id": "L12-8T1-03-C14", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Chính sách nào sau đây thuộc chính sách an sinh xã hội?", "o": ["Điều tiết thị trường.", "Dịch vụ thu ngoại tệ.", "Dịch vụ xã hội.", "Điều tiết xã hội."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: Đề 4.docx · Phần I câu 14 · khoá: gạch chân"}, {"id": "L12-8T1-03-C15", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Chính sách hỗ trợ người dân phòng ngừa, giảm thiểu rủi ro khi bị giảm hoặc mất thu nhập là nội dung của chính sách an sinh xã hội nào sau đây?", "o": ["Chính sách dịch vụ xã hội cơ bản", "Chính sách việc làm và giảm nghèo", "Chính sách bảo hiểm xã hội", "Chính sách trợ giúp xã hội"], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: Đề 4.docx · Phần I câu 15 · khoá: gạch chân"}, {"id": "L12-8T1-03-C16", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Nhà nước trợ cấp thường xuyên cho những người có hoàn cảnh đặc biệt khó khăn và trợ cấp đột xuất cho người dân gặp rủi ro để họ ổn định cuộc sống là nội dung của chính sách an sinh xã hội nào sau đây?", "o": ["Chính sách dịch vụ xã hội cơ bản", "Chính sách việc làm và giảm nghèo", "Chính sách bảo hiểm xã hội", "Chính sách trợ giúp xã hội"], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: Đề 4.docx · Phần I câu 16 · khoá: gạch chân"}, {"id": "L12-8T1-03-C17", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Quá trình kinh doanh trong đó vốn đầu tư được di chuyển từ quốc gia này sang quốc gia khác với mục đích sinh lời được gọi là", "o": ["Thương mại quốc tế.", "Đầu tư quốc tế.", "Dịch vụ thu ngoại tệ.", "Xuất nhập hàng hóa."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: Đề 4.docx · Phần I câu 17 · khoá: gạch chân"}, {"id": "L12-8T1-03-C18", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Ngày 15/3/2022, anh T có tham gia hợp đồng bảo hiểm tại công ty bảo hiểm Manulfie Việt Nam. Tháng 2/2023, anh T có xảy ra tai nạn và bị đơn vị Đội Cảnh sát giao thông phường B xử lý. Với việc mua bảo hiểm, tháng 3/2023 anh T được công ty bảo hiểm thanh toán bồi thường quyền lợi tai nạn theo đúng hợp đồng bảo hiểm sau khi nhận được yêu cầu bồi thường tai nạn từ anh T.", "o": ["Bảo hiểm thương mại", "Bảo hiểm y tế", "Bảo hiểm xã hội", "Bảo hiểm thân thể"], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: Đề 4.docx · Phần I câu 18 · khoá: gạch chân"}, {"id": "L12-8T1-03-C19", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Việc công ty bảo hiểm sử dụng nguồn vốn nhàn rỗi của mình để mua cổ phiếu, trái phiếu doanh nghiệp thể hiện vai trò nào sau đây của bảo hiểm?", "o": ["Góp phần chuyển giao rủi ro", "Là một kênh huy động vốn cho nền kinh tế", "Ổn định và tăng thu ngân sách nhà nước.", "Thúc đẩy hội nhập kinh tế quốc tế."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: Đề 4.docx · Phần I câu 19 · khoá: gạch chân"}, {"id": "L12-8T1-03-C20", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Các dịch vụ quốc tế như du lịch, giao thông vận tải, xuất nhập khẩu lao động… có vai trò tạo nguồn thu ngoại tệ được gọi là", "o": ["Thương mại quốc tế.", "Đầu tư quốc tế.", "Dịch vụ thu ngoại tệ.", "Xuất nhập hàng hóa."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: Đề 4.docx · Phần I câu 20 · khoá: gạch chân"}, {"id": "L12-8T1-03-C21", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đọc thông tin sau và trả lời câu hỏi 21, 22\nSau 40 năm đổi mới và thực hiện đường lối công nghiệp hóa- hiện đại hóa đất nước, nền kinh tế nước ta có nhiều chuyển biến tích cực. Tỉ trọng ngành nông nghiệp giảm từ 38,08%( năm 1986) xuống 11,96%( năm 2023), ngành công nghiệp xây dựng tăng từ 28,88%( năm 1986) lên 37,12%( năm 2023) và ngành dịch vụ tăng từ 33,06%( năm 1986) lên 42,54%( năm 2023). GDP bình quân đầu người của Việt Nam năm 2006 là 1.650,63USD, năm 2021 là 3.373,08USD. Từ năm 1990 đến năm 2022, giá trị HDI của Việt Nam thay đổi từ 0,492 lên 0,726.\nNội dung “Tỉ trọng ngành nông nghiệp giảm từ 38,08%( năm 1986) xuống 11,96%( năm 2023), ngành công nghiệp xây dựng tăng từ 28,88%( năm 1986) lên 37,12%( năm 2023) và ngành dịch vụ tăng từ 33,06%( năm 1986) lên 42,54%( năm 2023) phản ánh tiêu chí nào trong phát triển kinh tế", "o": ["Cơ cấu kinh tế đã chuyển dịch tích cực theo hướng công nghiệp hóa- hiện đại hóa.", "Sự thay đổi về cơ cấu GNP, hướng đến đô thị hóa.", "Sự thay đổi về chỉ sốphát triển con người.", "Sự thay đổi về chỉ số tiêu dùng."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: Đề 4.docx · Phần I câu 21 · khoá: gạch chân"}, {"id": "L12-8T1-03-C22", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đọc thông tin sau và trả lời câu hỏi 21, 22\nSau 40 năm đổi mới và thực hiện đường lối công nghiệp hóa- hiện đại hóa đất nước, nền kinh tế nước ta có nhiều chuyển biến tích cực. Tỉ trọng ngành nông nghiệp giảm từ 38,08%( năm 1986) xuống 11,96%( năm 2023), ngành công nghiệp xây dựng tăng từ 28,88%( năm 1986) lên 37,12%( năm 2023) và ngành dịch vụ tăng từ 33,06%( năm 1986) lên 42,54%( năm 2023). GDP bình quân đầu người của Việt Nam năm 2006 là 1.650,63USD, năm 2021 là 3.373,08USD. Từ năm 1990 đến năm 2022, giá trị HDI của Việt Nam thay đổi từ 0,492 lên 0,726.\nThông tin trên chưa đề cập đến chỉ tiêu nào trong phát triển kinh tế ở Việt Nam?", "o": ["Sự gia tăng của các chỉ tiêu tăng trưởng kinh tế.", "Sự chuyển dịch cơ cấu kinh tế theo hướng hiệu quả.", "Sự gia tăng chỉ số phát triển con người.", "Sự thay đổi chỉ số bất bình đẳng xã hội."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: Đề 4.docx · Phần I câu 22 · khoá: gạch chân"}, {"id": "L12-8T1-03-C23", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đọc thông tin sau và trả lời câu hỏi 23, 24\nHệ thống chính sách an sinh xã hội ở Việt Nam ngày càng thể hiện được bản chất tốt đẹp, pahts huy vai trò của mình, với nhiều chính sách như chính sách việc làm, thu nhập, giảm nghèo; chính sách trợ giúp xã hội; chính sách dịch vụ xã hội cơ bản…. Hiện nay, Nhà nước đã thực hiện trợ cấp xã hội cho hơn 3,35 triệu người hàng tháng. Bên cạnh đó, cũng thực hiện hỗ trợ thường xuyên và hỗ trợ đột xuất cho người dân khi gặp rủi ro do thiên tai, dịch bệnh như gói hỗ trợ 26000 tỷ đồng cho người dân bị ảnh hưởng bởi dịch bệnh Covid 19, hỗ trợ người dân bị ảnh hưởng bởi siêu bão Yagi. Để giải quyết vấn đề nhà ở cho người có thu nhập thấp nhà nước đã dành gói hỗ trợ hàng trăm nghìn tỷ đồng cho các đối tượng có thu nhập  thấp vay để mua nhà\nNội dung: “Nhà nước đã thực hiện trợ cấp xã hội cho hơn 3,35 triệu người hàng tháng. Bên cạnh đó, cũng thực hiện hỗ trợ thường xuyên và hỗ trợ đột xuất cho người dân khi gặp rủi ro do thiên tai, dịch bệnh.” Là thể hiện chính sách an sinh xã hội nào sau đây?", "o": ["Chính sách dịch vụ xã hội cơ bản", "Chính sách việc làm và giảm nghè", "Chính sách bảo hiểm xã hội", "Chính sách trợ giúp xã hội"], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: Đề 4.docx · Phần I câu 23 · khoá: gạch chân"}, {"id": "L12-8T1-03-C24", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đọc thông tin sau và trả lời câu hỏi 23, 24\nHệ thống chính sách an sinh xã hội ở Việt Nam ngày càng thể hiện được bản chất tốt đẹp, pahts huy vai trò của mình, với nhiều chính sách như chính sách việc làm, thu nhập, giảm nghèo; chính sách trợ giúp xã hội; chính sách dịch vụ xã hội cơ bản…. Hiện nay, Nhà nước đã thực hiện trợ cấp xã hội cho hơn 3,35 triệu người hàng tháng. Bên cạnh đó, cũng thực hiện hỗ trợ thường xuyên và hỗ trợ đột xuất cho người dân khi gặp rủi ro do thiên tai, dịch bệnh như gói hỗ trợ 26000 tỷ đồng cho người dân bị ảnh hưởng bởi dịch bệnh Covid 19, hỗ trợ người dân bị ảnh hưởng bởi siêu bão Yagi. Để giải quyết vấn đề nhà ở cho người có thu nhập thấp nhà nước đã dành gói hỗ trợ hàng trăm nghìn tỷ đồng cho các đối tượng có thu nhập  thấp vay để mua nhà\nNội dung “ Nhà nước đã dành gói hỗ trợ hàng trăm nghìn tỷ đồng cho các đối tượng có thu nhập thấp vay để mua nhà” là thể hiện chính sách an sinh xã hội nào dưới đây", "o": ["Chính sách dịch vụ xã hội cơ bản", "Chính sách việc làm và giảm nghèo", "Chính sách bảo hiểm xã hội", "Chính sách trợ giúp xã hội"], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: Đề 4.docx · Phần I câu 24 · khoá: gạch chân"}, {"id": "L12-8T1-03-C25", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "dung_sai", "status": "cho_duyet", "q": "Tăng trưởng kinh tế và phát triển con người là hai mặt của quá trình phát triển nền kinh tế.Trong đó, tăng trưởng kinh tế được thể hiện qua tiêu chí tốc độ tăng trưởng thu nhập bình quân đầu người(GNI/người), là điều kiện cần để thực hiện phát triển con người. Phát triển con người được phản ánh qua chỉ số phát triển con người HDI là một trong những mục tiêu cuối cùng của phát triển.Con người ngày càng phát triển, sẽ có tác động ngược trở lại thúc đẩy tăng trưởng kinh tế. (Theo Tạp chí cộng sản, “Tác động của tăng trưởng kinh tế đến phát triển con người ở Việt Nam: Vấn đề và giải pháp”", "o": ["Chỉ số HDI là một trong những chỉ tiêu của tăng trưởng kinh tế.", "Phát triển con người sẽ thúc đẩy nền kinh tế phát triển.", "Tổng thu nhập GNI /người là biểu hiện của phát triên kinh tế.", "Nhà nước tìm mọi cách tăng trưởng kinh tế để phát triển chỉ số con người(HDI)."], "a": [false, true, false, true], "e": "Đáp án: a) Sai; b) Đúng; c) Sai; d) Đúng.", "nguon": "Đề nguồn: Đề 4.docx · Phần II câu 1 · khoá: chữ Đúng/Sai trong ý"}, {"id": "L12-8T1-03-C26", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "dung_sai", "status": "cho_duyet", "q": "Năm nay do ảnh hưởng của siêu bão Yagi mà nhiều hộ dân thôn làng X bị sạt lở nghiêm trọng, làm thiệt hại về người và tài sản. Nhà nước cùng với chính quyền địa phương sẽ bố trí chỗ ở ổn định cho nhiều hộ dân cư. Trước mắt các hộ gia đình sẽ được chuyển đến các ngôi nhà tạm để ở. Sau khi chờ đợi chính quyền địa phương và cac sđơn vị liên quan hoàn thành khu tái định cư", "o": ["Chính quyền địa phương đã đảm bảo mục tiêu của chính sách an sinh xã hội.", "Người dân thôn làng X đã được tiếp cận các chính sách trợ giúp xã hội .", "Chính quyền địa phương đã hỗ trợ người dân bảo đảm thu nhập tối thiểu.", "Chính quyền địa phương X đã giúp đỡ người dân ổn định cuộc sống."], "a": [true, false, false, true], "e": "Đáp án: a) Đúng; b) Sai; c) Sai; d) Đúng.", "nguon": "Đề nguồn: Đề 4.docx · Phần II câu 2 · khoá: chữ Đúng/Sai trong ý"}, {"id": "L12-8T1-03-C27", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "dung_sai", "status": "cho_duyet", "q": "Tính đến cuối năm 2022, có hơn 600 000 người Việt Nam đi làm việc có thời hạn ở nước ngoài.Người lao động Việt Nam ở nước ngoài đang làm việc tại 40 quốc gia và vùng lãnh thổ với thu nhập ổn định, gửi về nước lượng kiều hối lớn, khoảng 3,5 tỉ Đô la Mỹ/ năm Theo báo cáo của Tổng cục thống kê, 11 tháng năm 2022, khách quốc tế đến Việt Nam đạt 2,95 triệu lượt người, gấp 21,1 lần so với cùng kì năm trước do Việt Nam đã mở cửa du lịch, các đường bay quốc tế được khôi phục trở lại. Doanh thu dịch vụ lưu trú, ăn uống 11 tháng của năm 2022 ước đạt 536 300 tỉ đồng, tăng 56,5% so với cùng kì năm trước.", "o": [".Một trong các hình thức hội nhập kinh tế quốc tế ở Việt Nam là dịch vụ thu ngoại tệ.", "Dịch vụ thu ngoại tệ ở Việt Nam bao gồm các dịch vụ quốc tế như du lịch, xuất, nhập khẩu lao động, dich vụ lưu trú.", "Hội nhập kinh tế quốc tế sẽ làm gia tăng sự lệ thuộc vào nước ngoài.", "Dịch vụ thu ngoại tệ góp phần thúc đẩy và tăng trưởng và phát triển kinh tế ở Việt Nam, tạo việc làm và nâng cao thu nhập cho các tầng lớp dân cư."], "a": [true, true, false, true], "e": "Đáp án: a) Đúng; b) Đúng; c) Sai; d) Đúng.", "nguon": "Đề nguồn: Đề 4.docx · Phần II câu 3 · khoá: chữ Đúng/Sai trong ý"}, {"id": "L12-8T1-03-C28", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "dung_sai", "status": "cho_duyet", "q": "Ngày 16/11/2013, Quốc hội ban hành Luật Việc làm, trong đó đã chuyển các quy định về chính sách bảo hiểm thất nghiệp từ Luật Bảo hiểm xã hội để sửa đổi, bổ sung và chính thức thực hiện theo quy định của Luật Việc làm từ ngày 1/1/2015. Chính sách bảo hiểm thất nghiệp được thực hiện để: chi trả trợ cấp thất nghiệp, đóng bảo hiểm y tế cho người hưởng trợ cấp thất nghiệp; hỗ trợ đào tạo, bồi dưỡng, nâng cao trình độ, kỹ năng nghề để duy trì việc làm cho người lao động; hỗ trợ tư vấn, giới thiệu việc làm; hỗ trợ học nghề... Tính tới hết năm 2023, số người tham gia bảo hiểm thất nghiệp tăng từ gần 6 triệu người năm 2009 lên hơn 14,6 triệu tăng hơn 2,4 lần. Chủ thể tham gia bảo hiểm thất nghiệp là người lao động và người sử dụng lao động", "o": ["Bảo hiểm thất nghiệp vừa mang tính tự nguyện vừa mang tính bắt buộc.", "Bảo hiểm thất nghiệp không chỉ quan trọng đối với người lao động và doanh nghiệp, mà còn góp phần ổn định kinh tế - xã hội.", "Người lao động sẽ không được hưởng chế độ hỗ trợ học nghề của chính sách bảo hiểm thất nghiệp khi bị mất việc.", "….Hết…."], "a": [true, true, true, false], "e": "Đáp án: a) Đúng; b) Đúng; c) Đúng; d) Sai.", "nguon": "Đề nguồn: Đề 4.docx · Phần II câu 4 · khoá: chữ Đúng/Sai trong ý"}]}, {"id": "L12-8T1-04", "loai": "khoi", "khoi": 12, "hoc_ki": 1, "bo": "8T1", "ten_bo": "8 tuần học kì I", "so_de": 4, "ten": "Lớp 12 · 8 tuần học kì I · Đề 4", "pham_vi": "Bài 1–4 (đề nguồn «8 TUẦN KÌ 1») · file nguồn: Đề 6.docx", "thoi_gian": 50, "cau_truc": "24 câu trắc nghiệm + 4 câu đúng/sai (mỗi câu 4 ý)", "status": "cho_duyet", "khoa": {"1 nguồn": 28}, "sua": "", "cau": [{"id": "L12-8T1-04-C01", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Sự tăng trưởng kinh tế gắn liền với sự chuyển dịch cơ cấu kinh tế hợp lí, đảm bảo tiến bộ xã hội là", "o": ["tổng sản phẩm quốc nội.", "phát triển kinh tế.", "hoạt động đối ngoại.", "thành phần kinh tế."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: Đề 6.docx · Phần I câu 1 · khoá: gạch chân"}, {"id": "L12-8T1-04-C02", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đọc thông tin và trả lời các câu 2-4\nGDP năm 2023 ước tính tăng 5,05% so với năm trước, chỉ cao hơn tốc  độ tăng 2,87% và 2,55% của các năm 2020 và  2021  trong  giai  đoạn  2011-2023.\nTrong mức tăng tổng giá trị tăng thêm toàn nền kinh tế, khu vực  nông,  lâm nghiệp và thủy sản tăng 3,83%, đóng góp 8,84%; khu vực công  nghiệp  và  xây dựng tăng 3,74%, đóng góp 28,87%; khu vực  dịch  vụ  tăng  6,82%,  đóng  góp\n62,29% (…). Quy mô GDP theo giá hiện hành năm 2023 ước đạt  10.221,8  nghìn tỷ đồng, tương đương 430 tỷ USD.\nGDP bình quân đầu người năm 2023 theo giá hiện hành  ước  đạt  101,9  triệu đồng/người, tương đương 4.284 USD, tăng 160 USD so với năm 2022.\n(Theo Báo cáo tình hình kinh tế xã hội quý IV năm 2023 – Tổng cục thống kê)\nTrong thông tin trên, con số nào dưới đây là chỉ tiêu tăng trưởng kinh?", "o": ["5,05%.", "2,87%.", "2,55%.", "62,29%."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: Đề 6.docx · Phần I câu 2 · khoá: gạch chân"}, {"id": "L12-8T1-04-C03", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đọc thông tin và trả lời các câu 2-4\nGDP năm 2023 ước tính tăng 5,05% so với năm trước, chỉ cao hơn tốc  độ tăng 2,87% và 2,55% của các năm 2020 và  2021  trong  giai  đoạn  2011-2023.\nTrong mức tăng tổng giá trị tăng thêm toàn nền kinh tế, khu vực  nông,  lâm nghiệp và thủy sản tăng 3,83%, đóng góp 8,84%; khu vực công  nghiệp  và  xây dựng tăng 3,74%, đóng góp 28,87%; khu vực  dịch  vụ  tăng  6,82%,  đóng  góp\n62,29% (…). Quy mô GDP theo giá hiện hành năm 2023 ước đạt  10.221,8  nghìn tỷ đồng, tương đương 430 tỷ USD.\nGDP bình quân đầu người năm 2023 theo giá hiện hành  ước  đạt  101,9  triệu đồng/người, tương đương 4.284 USD, tăng 160 USD so với năm 2022.\n(Theo Báo cáo tình hình kinh tế xã hội quý IV năm 2023 – Tổng cục thống kê)\nTheo thông tin trên, quy mô GDP theo giá hiện hành năm 2023 ước đạt 10.221,8 nghìn tỷ đồng là chỉ tiêu", "o": ["Tổng sản phẩm quốc nội.", "Tổng sản phẩm quốc dân.", "Chỉ số thu nhập.", "Chỉ số phát triển con người."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: Đề 6.docx · Phần I câu 3 · khoá: gạch chân"}, {"id": "L12-8T1-04-C04", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đọc thông tin và trả lời các câu 2-4\nGDP năm 2023 ước tính tăng 5,05% so với năm trước, chỉ cao hơn tốc  độ tăng 2,87% và 2,55% của các năm 2020 và  2021  trong  giai  đoạn  2011-2023.\nTrong mức tăng tổng giá trị tăng thêm toàn nền kinh tế, khu vực  nông,  lâm nghiệp và thủy sản tăng 3,83%, đóng góp 8,84%; khu vực công  nghiệp  và  xây dựng tăng 3,74%, đóng góp 28,87%; khu vực  dịch  vụ  tăng  6,82%,  đóng  góp\n62,29% (…). Quy mô GDP theo giá hiện hành năm 2023 ước đạt  10.221,8  nghìn tỷ đồng, tương đương 430 tỷ USD.\nGDP bình quân đầu người năm 2023 theo giá hiện hành  ước  đạt  101,9  triệu đồng/người, tương đương 4.284 USD, tăng 160 USD so với năm 2022.\n(Theo Báo cáo tình hình kinh tế xã hội quý IV năm 2023 – Tổng cục thống kê)\nDựa vào chỉ số GDP trong thông tin trên cho thấy: năm 2023 nền kinh tế Việt Nam", "o": ["có sự tăng trưởng kinh tế.", "rơi vào suy thoái.", "giảm về quy mô, sản lượng.", "rơi vào khủng hoảng."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: Đề 6.docx · Phần I câu 4 · khoá: gạch chân"}, {"id": "L12-8T1-04-C05", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Tốc độ tăng trưởng kinh tế phản ánh mức tăng", "o": ["chỉ số HDI của thời kì này so với thời kì trước.", "GNI bình quân đầu người của thời kì này so với thời kì trước.", "GDP bình quân đầu người của thời kì này so với thời kì trước.", "GDP hoặc GNI của thời kì này so với thời kì trước."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: Đề 6.docx · Phần I câu 5 · khoá: gạch chân"}, {"id": "L12-8T1-04-C06", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Việc làm nào dưới đây của công dân góp phần thúc đẩy sự tăng trưởng, phát triển kinh tế đất nước?", "o": ["Sản xuất hàng giả, hàng nhái.", "Ứng dụng công nghệ 4.0 vào sản xuất.", "Nợ lương của người lao động.", "Gian lận thuế, nợ thuế, trốn thuế."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: Đề 6.docx · Phần I câu 6 · khoá: gạch chân"}, {"id": "L12-8T1-04-C07", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "GNI là tiêu chí nào dưới đây đánh giá tăng trưởng kinh tế?", "o": ["Tổng thu nhập quốc nội bình quân đầu người.", "Tổng sản phẩm quốc nội.", "Tổng thu nhập quốc dân bình quân đầu người.", "Tổng thu nhập quốc dân."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: Đề 6.docx · Phần I câu 7 · khoá: gạch chân"}, {"id": "L12-8T1-04-C08", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Để nâng cao chỉ số phát triển con người, nước ta đẩy mạnh sự phát triển của con người thông qua các chỉ số", "o": ["sức khoẻ, thông minh và dân số.", "thông minh, dân số và giới tính.", "sức khoẻ, giáo dục và thu nhập.", "giới tính, thông minh và hạnh phúc."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: Đề 6.docx · Phần I câu 8 · khoá: gạch chân"}, {"id": "L12-8T1-04-C09", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Nội dung nào dưới đây không là vai trò của tăng trưởng kinh tế và phát triển kinh tế?", "o": ["Tạo điều kiện giải quyết công ăn việc làm.", "Làm cho mức thu nhập của dân cư tăng.", "Giảm bớt tình trạng đói nghèo.", "gia tăng khoảng cách giàu nghèo trong xã hội."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: Đề 6.docx · Phần I câu 9 · khoá: gạch chân"}, {"id": "L12-8T1-04-C10", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Quá trình một quốc gia thực hiện gắn kết nền kinh tế của mình với nền kinh tế các quốc gia khác trong khu vực và trên thế giới dựa trên cơ sở cùng có lợi và tuân thủ các quy định chung là nội dung của khái niệm nào sau đây?", "o": ["Hội nhập kinh tế quốc tế.", "Liên kết kinh tế quốc tế.", "Kết nối kinh tế quốc tế.", "Tích hợp kinh tế quốc tế."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: Đề 6.docx · Phần I câu 10 · khoá: gạch chân"}, {"id": "L12-8T1-04-C11", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Hội nhập kinh tế quốc tế được thực hiện theo các cấp độ nào dưới đây?", "o": ["Song phương, khu vực, toàn cầu.", "Song phương, đa phương, toàn diện.", "Thoả thuận, liên minh, hợp tác.", "Thoả thuận, liên kết, hoà nhập."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: Đề 6.docx · Phần I câu 11 · khoá: gạch chân"}, {"id": "L12-8T1-04-C12", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Trong thông tin trên, Việt Nam hội nhập kinh tế quốc tế ở cấ p độ", "o": ["song phương.", "khu vực.", "quốc tế.", "toàn cầu"], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: Đề 6.docx · Phần I câu 12 · khoá: gạch chân"}, {"id": "L12-8T1-04-C13", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Trong thông tin trên, Việt Nam hội nhập kinh tế quốc tế thông qua hình thức nào dưới đây của hoạt động kinh tế quốc tế?", "o": ["Thương mại quốc tế.", "Đầu tư quốc tế.", "Xuất khẩu hàng hóa.", "Chuyển giao công nghệ."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: Đề 6.docx · Phần I câu 13 · khoá: gạch chân"}, {"id": "L12-8T1-04-C14", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Việc trao đổi hàng hoá và dịch vụ giữa các quốc gia bao gồm hoạt động xuất khẩu và nhập khẩu hàng hoá, dịch vụ thể hiện hình thức hoạt động kinh tế quốc tế nào dưới đây?", "o": ["thương mại quốc tế.", "đầu tư quốc tế.", "dịch vụ thu ngoại tệ.", "thương mại nội địa."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: Đề 6.docx · Phần I câu 14 · khoá: gạch chân"}, {"id": "L12-8T1-04-C15", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Tham gia các diễn đàn hợp tác kinh tế châu Á – Thái Bình dương (APEC) sẽ đem lại lợi ích nào dưới đây cho Việt Nam?", "o": ["Thu hẹp thị trường xuất, nhập khẩu.", "Tách biệt mối quan hệ kinh tế.", "Giảm nguy cơ cạnh tranh.", "Mở rộng thị trường xuất khẩu."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: Đề 6.docx · Phần I câu 15 · khoá: gạch chân"}, {"id": "L12-8T1-04-C16", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Nội dung nào dưới đây là một trong những yêu cầu tất yếu của hội nhập kinh tế quốc tế đối với mọi quốc gia?", "o": ["Gia tăng khoảng cách giàu, nghèo.", "Gia tăng dân số tự nhiên.", "Đảm bảo tăng trưởng kinh tế ổn định.", "Thu hút vốn đầu tư nước ngoài."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: Đề 6.docx · Phần I câu 16 · khoá: gạch chân"}, {"id": "L12-8T1-04-C17", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Dịch vụ tài chính thông qua đó người tham gia bảo hiểm đóng một khoản phí cho tổ chức bảo hiểm để được hưởng bồi thường hoặc chi trả bảo hiểm khi xảy ra sự kiện bảo hiểm là nội dung của khái niệm nào sau đây?", "o": ["Bảo tức.", "Tín dụng.", "Bảo hiểm.", "Tài chính."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: Đề 6.docx · Phần I câu 17 · khoá: gạch chân"}, {"id": "L12-8T1-04-C18", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Theo thông tin Cục Quản lý giám sát bảo hiểm (Bộ Tài chính) công bố tính đến 17h ngày 12/9, sau bão Yagi, các doanh nghiệp bảo hiểm hiện đã tiếp nhận 9.000 vụ thiệt hại tài sản và xe cơ giới với tổng yêu cầu bồi thường 7.000 tỷ đồng. Con số sẽ còn tiếp tục tăng những ngày tới.Tổng số tiền yêu cầu bồi thường về người và tài sản ước tính khoảng 7.000 tỷ, trong đó chiếm phần lớn là bồi thường tài sản và xe cơ giới. Bên cạnh đó, các doanh nghiệp ghi nhận 14 khách hàng tử vong sau bão. (Theo báo VN Expresss, ngày 13-9-2024) Thông tin trên đề cập nội dung bảo hiểm nào dưới đây?", "o": ["Bảo hiểm xã hội.", "Bảo hiểm y tế.", "Bảo hiểm thất nghiệp.", "Bảo hiểm thương mại."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: Đề 6.docx · Phần I câu 18 · khoá: gạch chân"}, {"id": "L12-8T1-04-C19", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Nội dung nào sau đây không phải là vai trò của bảo hiểm đối với xã hội?", "o": ["Góp phần tạo công ăn việc làm, giảm thất nghiệp trong nền kinh tế.", "Đảm bảo an toàn cho cuộc sống con người.", "Góp phần hình thành lối sống tiết kiệm trên phạm vi toàn xã hội.", "Góp phần ổn định tài chính, đảm bảo an toàn cho các khoản đầu tư."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: Đề 6.docx · Phần I câu 19 · khoá: gạch chân"}, {"id": "L12-8T1-04-C20", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Hệ thống các chính sách do Nhà nước và các lực lượng xã hội thực hiện giải quyết các vấn đề xã hội nhằm nâng cao năng lực tự bảo vệ của người dân và xã hội trước những rủi ro hay nguy cơ giảm hoặc mất thu nhập góp phần cải thiện chất lượng cuộc sống, phát triển và công bằng xã hội là nội dung của khái niệm nào sau đây?", "o": ["Trợ giúp xã hội.", "Chính sách xã hội.", "An sinh xã hội.", "Bảo hiểm xã hội."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: Đề 6.docx · Phần I câu 20 · khoá: gạch chân"}, {"id": "L12-8T1-04-C21", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Hệ thống chính sách an sinh xã hội ở Việt Nam hiện nay không bao gồm chính sách nào sau đây?", "o": ["Chính sách về ngân sách nhà nước và thuế.", "Chính sách việc làm, thu nhập và giảm nghèo.", "Chính sách bảo hiểm xã hội.", "Chính sách trợ giúp xã hội."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: Đề 6.docx · Phần I câu 21 · khoá: gạch chân"}, {"id": "L12-8T1-04-C22", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Phí bảo hiểm là khoản tiền mà", "o": ["người được bảo hiểm phải đóng cho tổ chức bảo hiểm theo quy định của pháp luật hoặc do các bên thoả thuận trong hợp đồng bảo hiểm.", "người thứ ba (người thụ hưởng) phải đóng cho tổ chức bảo hiểm theo quy định của pháp luật hoặc do các bên thoả thuận trong hợp đồng bảo hiểm.", "bên mua bảo hiểm phải đóng cho tổ chức bảo hiểm theo quy định của pháp luật hoặc do các bên thoả thuận trong hợp đồng bảo hiểm.", "tổ chức bảo hiểm bồi thường cho người được bảo hiểm khi sự kiện bảo hiểm xảy ra."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: Đề 6.docx · Phần I câu 22 · khoá: gạch chân"}, {"id": "L12-8T1-04-C23", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đọc thông tin và trả lời các câu 23-24\nVề diện bao phủ BHYT: đã tăng nhanh và phát triển bền vững. Trước  khi\nBan Bí thư ban hành Chỉ thị số 38, năm 2008, toàn quốc chỉ có  39,7  triệu người tham gia BHYT, đạt tỷ lệ 46,1% dân số. Đến năm 2023,  cả  nước  đã  có hơn 93,3 triệu người tham gia BHYT, tăng gấp 2,3 lần so với  năm  2008,  đạt tỷ lệ 93,35% dân số, tiệm cận với mục tiêu BHYT toàn dân.\nVề công tác khám chữa bệnh (KCB) BHYT: Hằng năm, bình quân có trên 150 triệu lượt người KCB BHYT với số tiền quỹ BHYT chi trả  trên  100  nghìn  tỷ đồng. Hệ thống KCB BHYT được tổ chức tốt từ trung ương đến địa  phương,  bao gồm các cơ sở KCB công lập và tư nhân đã tạo thuận lợi giúp người  dân  tiếp cận và sử dụng các dịch vụ KCB BHYT.\n(Cổng thông tin Điện tử bộ Y tế)\nĐoạn thông tin trên đề cập đến quyền lợi nào dưới đây của người tham gia bảo hiểm y tế?", "o": ["Được nghỉ phép trong thời gian điều trị bệnh.", "Được trợ cấp trong thời gian điều trị bệnh.", "Được chi trả chi phí khám và điều trị bệnh.", "Được miễn đóng phí bảo hiểm y tế."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: Đề 6.docx · Phần I câu 23 · khoá: gạch chân"}, {"id": "L12-8T1-04-C24", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đọc thông tin và trả lời các câu 23-24\nVề diện bao phủ BHYT: đã tăng nhanh và phát triển bền vững. Trước  khi\nBan Bí thư ban hành Chỉ thị số 38, năm 2008, toàn quốc chỉ có  39,7  triệu người tham gia BHYT, đạt tỷ lệ 46,1% dân số. Đến năm 2023,  cả  nước  đã  có hơn 93,3 triệu người tham gia BHYT, tăng gấp 2,3 lần so với  năm  2008,  đạt tỷ lệ 93,35% dân số, tiệm cận với mục tiêu BHYT toàn dân.\nVề công tác khám chữa bệnh (KCB) BHYT: Hằng năm, bình quân có trên 150 triệu lượt người KCB BHYT với số tiền quỹ BHYT chi trả  trên  100  nghìn  tỷ đồng. Hệ thống KCB BHYT được tổ chức tốt từ trung ương đến địa  phương,  bao gồm các cơ sở KCB công lập và tư nhân đã tạo thuận lợi giúp người  dân  tiếp cận và sử dụng các dịch vụ KCB BHYT.\n(Cổng thông tin Điện tử bộ Y tế)\nĐoạn thông tin trên đề cập đến chính sách an sinh xã hội cơ bản nào dưới đây?", "o": ["Chính sách việc làm, thu nhập và giảm nghèo.", "Chính sách bảo hiểm xã hội.", "Chính sách trợ giúp xã hội.", "Chính sách về dịch vụ xã hội cơ bản."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: Đề 6.docx · Phần I câu 24 · khoá: gạch chân"}, {"id": "L12-8T1-04-C25", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "dung_sai", "status": "cho_duyet", "q": "Theo đánh giá chung của Chính Phủ, Quý III năm 2023, mức tăng trưởng kinh tế toàn cầu tăng nhẹ so với những dự báo đưa ra trước đó. Thị trường lao động trên phạm vi toàn thế giới, đặc biệt là tại các quốc gia phát triển có tỷ lệ thất nghiệp thấp và cơ hội việc làm cho người lao động đang gia tăng. Trong khi đó ở Việt Nam, tốc độ tăng trưởng kinh tế giữ ổn định, tỷ lệ thiếu việc làm và thất nghiệp trong độ tuổi lao động không thay đổi so với quý trước và tăng so với cùng kỳ năm trước. Tổng số đối tượng hưởng trợ cấp bảo hiểm thất nghiệp giảm. Thu nhập bình quân tháng của người lao động tăng so với quý trước và tăng so với cùng kỳ năm trước. Các dự án có vốn đầu tư nước ngoài vào Việt Nam đạt 12 tỉ USD. Về cán cân thương mại, Việt Nam vẫn là quốc gia nhập siêu. Trước tình hình trên Nhà nước ban hành chính sách giãn, giảm thuế và yêu cầu các ngân hàng có chính sách hỗ trợ về lãi xuất cho các doanh nghiệp sản xuất kinh doanh tạo ra lợi thế cạnh tranh trên thị trường thế giới.", "o": ["Thu nhập bình quân tháng của người lao động trong thông tin trên là tổng thu nhập quốc nội.", "Nền kinh tế của Việt Nam trong quý III năm 2023 không chịu sự tác động của tình hình kinh tế thế giới.", "Người lao động nên chủ động và yêu cầu doanh nghiệp tham gia đầy đủ các loại hình bảo hiểm bắt buộc cho mình.", "Số người lao động hưởng trợ cấp thất nghiệp tăng trong quý III/2023."], "a": [false, false, true, false], "e": "Đáp án: a) Sai; b) Sai; c) Đúng; d) Sai.", "nguon": "Đề nguồn: Đề 6.docx · Phần II câu 1 · khoá: chữ Đúng/Sai trong ý"}, {"id": "L12-8T1-04-C26", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "dung_sai", "status": "cho_duyet", "q": "Đọc thông tin và trả lời các câu 2-4\nGDP năm 2023 ước tính tăng 5,05% so với năm trước, chỉ cao hơn tốc  độ tăng 2,87% và 2,55% của các năm 2020 và  2021  trong  giai  đoạn  2011-2023.\nTrong mức tăng tổng giá trị tăng thêm toàn nền kinh tế, khu vực  nông,  lâm nghiệp và thủy sản tăng 3,83%, đóng góp 8,84%; khu vực công  nghiệp  và  xây dựng tăng 3,74%, đóng góp 28,87%; khu vực  dịch  vụ  tăng  6,82%,  đóng  góp\n62,29% (…). Quy mô GDP theo giá hiện hành năm 2023 ước đạt  10.221,8  nghìn tỷ đồng, tương đương 430 tỷ USD.\nGDP bình quân đầu người năm 2023 theo giá hiện hành  ước  đạt  101,9  triệu đồng/người, tương đương 4.284 USD, tăng 160 USD so với năm 2022.\n(Theo Báo cáo tình hình kinh tế xã hội quý IV năm 2023 – Tổng cục thống kê)\nKhép lại năm 2023,trong bối cảnh khó khăn, Việt Nam được nhiều tổ chức quốc tế ghi nhận tiếp tục là điểm sáng kinh tế toàn cầu; tổng kim ngạch xuất nhập khẩu vẫn ước đạt 683 tỷ USD, xuất siêu khoảng 26 tỷ USD, trong đó xuất khẩu nông sản, nhất là các mặt hàng rau quả và gạo lập đỉnh mới với nhiều con số kỷ lụcNhiều thành tựu đối ngoại quan trọng có tính lịch sử, tạo thời cơ, vận hội mới để phát triển đất nước, uy tín và vị thế Việt Nam được nâng lên tầm cao mới; Tính đến ngày 20/12/2023, tổng vốn đầu tư nước ngoài đăng ký vào Việt Nam (FDI) đạt gần 36,61 tỷ USD, tăng 32,1% so với cùng kỳ; Đột phá chiến lược về xây dựng hệ thống kết cấu hạ tầng, nhất là hạ tầng giao thông, có sự chuyển biến vượt bậc, đặc biệt là hệ thống đường bộ cao tốc; Năm 2023 ghi những dấu ấn mới trong cơ cấu lại nền kinh tế, phát triển những ngành, lĩnh vực mới nổi, thúc đẩy khoa học công nghệ, đổi mới sáng tạo, chuyển đổi số, chuyển đổi xanh, phát triển kinh tế số, kinh tế xanh, kinh tế tuần hoàn, kinh tế tri thức, kinh tế chia sẻ; Đời sống của nhân dân tiếp tục được cải thiện, thu nhập bình quân của người lao động tăng 6,8%; trên 94% số hộ gia đình đánh giá có thu nhập ổn định hoặc cao hơn cùng kỳ năm 2022. Theo Báo cáo Hạnh phúc thế giới vào tháng 3/2023 của Liên Hợp Quốc, Chỉ số hạnh phúc của Việt Nam tăng 12 bậc. (Theo chinhphu.vn)", "o": ["Đột phá về xây dựng kết cấu hạ tầng thể hiện vai trò của phát triển kinh tế của nước ta.", "Trong bối cảnh khó khăn, thị trường của Việt Nam đã bị thu hẹp.", "Chỉ số phát triển con người Việt Nam có chuyển biến tích cực.", "Việt Nam chưa có sự chuyển biến về cơ cấu kinh tế."], "a": [true, false, true, false], "e": "Đáp án: a) Đúng; b) Sai; c) Đúng; d) Sai.", "nguon": "Đề nguồn: Đề 6.docx · Phần II câu 2 · khoá: chữ Đúng/Sai trong ý"}, {"id": "L12-8T1-04-C27", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "dung_sai", "status": "cho_duyet", "q": "Đọc thông tin và trả lời các câu 2-4\nGDP năm 2023 ước tính tăng 5,05% so với năm trước, chỉ cao hơn tốc  độ tăng 2,87% và 2,55% của các năm 2020 và  2021  trong  giai  đoạn  2011-2023.\nTrong mức tăng tổng giá trị tăng thêm toàn nền kinh tế, khu vực  nông,  lâm nghiệp và thủy sản tăng 3,83%, đóng góp 8,84%; khu vực công  nghiệp  và  xây dựng tăng 3,74%, đóng góp 28,87%; khu vực  dịch  vụ  tăng  6,82%,  đóng  góp\n62,29% (…). Quy mô GDP theo giá hiện hành năm 2023 ước đạt  10.221,8  nghìn tỷ đồng, tương đương 430 tỷ USD.\nGDP bình quân đầu người năm 2023 theo giá hiện hành  ước  đạt  101,9  triệu đồng/người, tương đương 4.284 USD, tăng 160 USD so với năm 2022.\n(Theo Báo cáo tình hình kinh tế xã hội quý IV năm 2023 – Tổng cục thống kê)\nChính phủ ban hành chính sách tài khóa hỗ trợ phục hồi và tăng trưởng kinh tế trong đại dịch Covid-19, có các chính sách sau: Giảm 2% thuế suất thuế giá trị gia tăng (GTGT) trong năm 2022; Tăng chi đầu tư phát triển từ nguồn NSNN tối đa 176 nghìn tỷ đồng, tập trung trong 2 năm 2022 và 2023, bao gồm các lĩnh vực: Y tế; an sinh xã hội, lao động, việc làm; hỗ trợ doanh nghiệp, hợp tác xã, hộ kinh doanh; đầu tư phát triển kết cấu hạ tầng; và việc lựa chọn và phân bổ vốn cho các dự án thuộc Chương trình phải bảo đảm giải ngân vốn trong 2 năm 2022 và 2023; Hỗ trợ tiền thuê nhà cho người lao động có quan hệ lao động, đang ở thuê, ở trọ, làm việc trong các khu công nghiệp, khu chế xuất, khu vực kinh tế trọng điểm; Tăng hạn mức bảo lãnh Chính phủ đối với trái phiếu phát hành trong nước cho Ngân hàng Chính sách Xã hội tối đa 38,4 nghìn tỷ đồng… (Theo Cổng thông tin Điện tử Bộ tài chính)", "o": ["Chính sách tài khóa hỗ trợ chương trình phục hồi và tăng trưởng kinh tế bao gồm: Tăng trưởng kinh tế và an sinh xã hội. (Đ.", "Việc thực hiện đồng bộ các giải pháp phục hồi là cần thiết góp phần đảm bảo tiến bộ xã hội.", "Hỗ trợ tiền thuê nhà cho người lao động có quan hệ lao động, đang ở thuê, ở trọ, làm việc trong các khu công nghiệp, khu chế xuất, khu vực kinh tế trọng điểm… là chính sách về bảo hiểm của an sinh xã hội cơ bản.", "Tăng chi đầu tư phát triển từ nguồn NSNN, hạn mức bảo lãnh Chính phủ đối với trái phiếu phát hành trong nước, hỗ trợ doanh nghiệp, hợp tác xã kìm hãm tăng trưởng kinh tế."], "a": [true, true, false, false], "e": "Đáp án: a) Đúng; b) Đúng; c) Sai; d) Sai.", "nguon": "Đề nguồn: Đề 6.docx · Phần II câu 3 · khoá: chữ Đúng/Sai trong ý"}, {"id": "L12-8T1-04-C28", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "dung_sai", "status": "cho_duyet", "q": "Đọc thông tin và trả lời các câu 2-4\nGDP năm 2023 ước tính tăng 5,05% so với năm trước, chỉ cao hơn tốc  độ tăng 2,87% và 2,55% của các năm 2020 và  2021  trong  giai  đoạn  2011-2023.\nTrong mức tăng tổng giá trị tăng thêm toàn nền kinh tế, khu vực  nông,  lâm nghiệp và thủy sản tăng 3,83%, đóng góp 8,84%; khu vực công  nghiệp  và  xây dựng tăng 3,74%, đóng góp 28,87%; khu vực  dịch  vụ  tăng  6,82%,  đóng  góp\n62,29% (…). Quy mô GDP theo giá hiện hành năm 2023 ước đạt  10.221,8  nghìn tỷ đồng, tương đương 430 tỷ USD.\nGDP bình quân đầu người năm 2023 theo giá hiện hành  ước  đạt  101,9  triệu đồng/người, tương đương 4.284 USD, tăng 160 USD so với năm 2022.\n(Theo Báo cáo tình hình kinh tế xã hội quý IV năm 2023 – Tổng cục thống kê)\nTheo số liệu Cục Du lịch Quốc gia Việt Nam vừa công bố, tổng lượng khách quốc tế đến Việt Nam trong 7 tháng đầu năm 2024 đạt 9.983.703 lượt, tăng 51% so với cùng kỳ năm 2023. Lượng khách du lịch nội địa tháng 7/2024 ước khoảng 13,0 triệu lượt khách, trong đó có khoảng 8,7 triệu lượt khách có lưu trú. Lũy kế lượng khách du lịch nội địa 7 tháng đầu năm 2024 ước khoảng 79,5 triệu lượt. Cục Du lịch Quốc gia Việt Nam cho biết, tổng thu từ khách du lịch trong 7 tháng đầu năm 2024 ước khoảng hơn 513 nghìn tỷ đồng. Theo báo cáo của Cục Quản lý lao động ngoài nước (Bộ Lao động-Thương binh và Xã hội), trong 6 tháng đầu năm 2024, tổng số lao động Việt Nam đi làm việc ở nước ngoài là 78.640 lao động đạt 62,91 % kế hoạch năm 2024. Đến nay, cả nước có hơn 600.000 lao động đang làm việc tại 50 quốc gia và vùng lãnh thổ, mỗi năm chuyển về khoảng 4 tỷ USD ngoại tệ theo đường chính ngạch, chưa kể các kênh khác. (Theo chinhphu.vn)", "o": ["Một trong các hình thức của hội nhập kinh tế quốc tế ở Việt Nam là dịch vụ thu ngoại tệ.", "Dịch vụ thu ngoại tệ ở Việt Nam bao gồm các dịch vụ: như du lịch, xuất khẩu lao động.", "Tác động tích cực của dịch vụ thu ngoại tệ ở Việt Nam là góp phần tăng trưởng kinh tế và tăng thu nhập cho người lao động.", "Lượng khách du lịch nội địa làm gia tăng dịch vụ thu ngoại tệ của hội nhập kinh tế quốc tế."], "a": [true, false, true, true], "e": "Đáp án: a) Đúng; b) Sai; c) Đúng; d) Đúng.", "nguon": "Đề nguồn: Đề 6.docx · Phần II câu 4 · khoá: chữ Đúng/Sai trong ý"}]}, {"id": "L12-8T1-05", "loai": "khoi", "khoi": 12, "hoc_ki": 1, "bo": "8T1", "ten_bo": "8 tuần học kì I", "so_de": 5, "ten": "Lớp 12 · 8 tuần học kì I · Đề 5", "pham_vi": "Bài 1–4 (đề nguồn «HỌC KÌ 1 › bai_1_4») · file nguồn: Đề 1 đáp án.docx", "thoi_gian": 50, "cau_truc": "24 câu trắc nghiệm + 4 câu đúng/sai (mỗi câu 4 ý)", "status": "cho_duyet", "khoa": {"1 nguồn": 28}, "sua": "", "cau": [{"id": "L12-8T1-05-C01", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Dùng để biểu thị thu nhập của nền kinh tế trong một thời kỳ nhất định được tính bằng tổng thu nhập từ hàng hóa, dịch vụ cuối cùng do công dân của quốc gia đó tạo ra trong một năm là", "o": ["tổng thu nhập quốc nội (GDP).", "tổng thu nhập quốc dân trên đầu người.", "tổng thu nhập quốc nội trên đầu người.", "tổng thu nhập quốc dân (GNI)."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: Đề 1 đáp án.docx · Phần I câu 1 · khoá: gạch chân"}, {"id": "L12-8T1-05-C02", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Tăng trưởng kinh tế được biểu hiện ở nội dung nào dưới đây?", "o": ["Tập trung đến sự tiến bộ về phân phối thu nhập.", "Đảm bảo phát triển bền vững về môi trường.", "Sự gia tăng quy mô sản lượng của nền kinh tế.", "Chú trọng vào cải thiện chất lượng cuộc sống."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: Đề 1 đáp án.docx · Phần I câu 2 · khoá: gạch chân"}, {"id": "L12-8T1-05-C03", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đối với mỗi quốc gia, phát triển kinh tế thể hiện ở nội dung nào dưới đây?", "o": ["Chuyển dịch vùng sản xuất.", "Chuyển dịch cơ cấu ngành.", "Chuyển dịch việc phân phối.", "Chuyển đổi mô hình tiền tệ."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: Đề 1 đáp án.docx · Phần I câu 3 · khoá: gạch chân"}, {"id": "L12-8T1-05-C04", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Quá trình tăng trưởng kinh tế gắn liền với sự chuyển dịch cơ cấu kinh tế và đảm bảo tiến bộ xã hội là nội dung của khái niệm nào dưới đây?", "o": ["Phát triển kinh tế.", "Tăng trưởng kinh tế.", "Hội nhập kinh tế.", "Kinh tế đối ngoại."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: Đề 1 đáp án.docx · Phần I câu 4 · khoá: gạch chân"}, {"id": "L12-8T1-05-C05", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Giá trị bằng tiền của tất cả các hàng hóa và dịch vụ cuối cùng được sản xuất ra trên lãnh thổ một nước trong thời gian nhất định được gọi là", "o": ["tổng thu nhập quốc dân (GNI).", "tổng thu nhập quốc nội (GDP).", "tổng thu nhập quốc nội trên đầu người.", "tổng thu nhập quốc dân trên đầu người."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: Đề 1 đáp án.docx · Phần I câu 5 · khoá: gạch chân"}, {"id": "L12-8T1-05-C06", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đối với mỗi quốc gia, vai trò của tăng trưởng và phát triển kinh tế thể hiện ở việc, thông qua tăng trưởng và phát triển kinh tế sẽ góp phần", "o": ["tăng tỷ lệ đói nghèo đa chiều.", "gia tăng phân hóa giàu nghèo giữa các vùng và giữa các tầng lớp dân cư trong xã hội.", "giải quyết tốt vấn đề việc làm.", "gia tăng lệ thuộc vào thế giới."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: Đề 1 đáp án.docx · Phần I câu 6 · khoá: gạch chân"}, {"id": "L12-8T1-05-C07", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Tăng trưởng và phát triển kinh tế không có vai trò nào dưới đây?", "o": ["Thực hiện phân phối thu nhập công bằng giữa các tầng lớp dân cư trong xã hội.", "Nâng cao mức sống người dân.", "Gia tăng khoảng cách giàu nghèo.", "Thu hẹp khoảng cách các vùng."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: Đề 1 đáp án.docx · Phần I câu 7 · khoá: gạch chân"}, {"id": "L12-8T1-05-C08", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Trong mối quan hệ giữa tăng trưởng kinh tế với phát triển kinh tế thì tăng trưởng kinh tế không đóng vai trò nào dưới đây đối với phát triển kinh tế?", "o": ["Là nội dung của phát triển bền vững.", "Là động lực của phát triển xã hội.", "Là điều kiện cần thiết để phát triển bền vững.", "Là nhân tố bên ngoài của phát triển bền vững."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: Đề 1 đáp án.docx · Phần I câu 8 · khoá: gạch chân"}, {"id": "L12-8T1-05-C09", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đối với mỗi quốc gia, phát triển kinh tế không thể hiện ở chỉ tiêu nào dưới đây?", "o": ["Chỉ tiêu về thu nhập quốc dân.", "Chỉ tiêu về thu thuế toàn cầu.", "Chỉ tiêu về thu nhập quốc nội.", "Chỉ tiêu về tăng trưởng kinh tế."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: Đề 1 đáp án.docx · Phần I câu 9 · khoá: gạch chân"}, {"id": "L12-8T1-05-C10", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Từ ngày 11/1/2007, Việt Nam chính thức trở thành thành viên thứ 150 của Tổ chức Thương mại thế giới (WTO). Việc gia nhập WTO là biểu hiện của hình thức hội nhập kinh tế quốc tế nào dưới đây?", "o": ["Song phương.", "Khu vực.", "Toàn cầu.", "Toàn quốc."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: Đề 1 đáp án.docx · Phần I câu 10 · khoá: gạch chân"}, {"id": "L12-8T1-05-C11", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Ngày 28-7-1995, Việt Nam trở thành thành viên thứ bảy của ASEAN. Việc gia nhập ASEAN là biểu hiện của hình thức hội nhập kinh tế quốc tế nào dưới đây?", "o": ["Song phương.", "Toàn quốc.", "Khu vực.", "Toàn cầu."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: Đề 1 đáp án.docx · Phần I câu 11 · khoá: gạch chân"}, {"id": "L12-8T1-05-C12", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Là sự thoả thuận giữa các bên tham gia nhằm xoá bỏ hầu hết hàng rào thuế quan và phi thuế quan nhưng vẫn duy trì chính sách thuế quan riêng của mỗi bên đối với các nước ngoài hiệp định là thể hiện mức độ hội nhập kinh tế quốc tế ở mức độ", "o": ["thị trường chung.", "thoả thuận thương mại ưu đãi.", "hiệp định thương mại tự do.", "liên minh kinh tế."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: Đề 1 đáp án.docx · Phần I câu 12 · khoá: gạch chân"}, {"id": "L12-8T1-05-C13", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Hội nhập kinh tế quốc tế bao gồm các hình thức nào dưới đây?", "o": ["Hội nhập về kinh tế, hội nhập về văn hoá và hội nhập về xã hội của quốc gia.", "Hội nhập toàn cầu, hội nhập khu vực và hội nhập song phương.", "Toàn cầu hoá kinh tế và toàn cầu hoá chính trị.", "Hội nhập về kinh tế và hội nhập về xã hội."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: Đề 1 đáp án.docx · Phần I câu 13 · khoá: gạch chân"}, {"id": "L12-8T1-05-C14", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Được thành lập bởi các quốc gia trong cùng khu vực địa lí để thúc đẩy tự do thương mại, tự do di chuyển lao động và vốn giữa các thành viên là thể hiện mức độ hội nhập kinh tế quốc tế ở mức độ", "o": ["liên minh kinh tế.", "thị trường chung.", "hiệp định thương mại tự do.", "thoả thuận thương mại ưu đãi."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: Đề 1 đáp án.docx · Phần I câu 14 · khoá: gạch chân"}, {"id": "L12-8T1-05-C15", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Ngày 11/11/2011 Hiệp định Thương mại tự do Việt Nam – Chi Lê được ký kết và có hiệu lực từ ngày 1/1/2014, xét về cấp độ hợp tác đây là hình thức hợp tác", "o": ["khu vực.", "song phương.", "hợp tác theo châu lục giữa các quốc gia trong cùng một lục địa.", "toàn cầu."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: Đề 1 đáp án.docx · Phần I câu 15 · khoá: gạch chân"}, {"id": "L12-8T1-05-C16", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Khẳng định nào dưới đây là đúng khi nói về hội nhập khu vực?", "o": ["Là hợp tác kí kết giữa hai quốc gia trên nguyên tắc bình đẳng, cùng có lợi.", "Là quá trình liên kết hợp tác giữa các quốc gia trong một khu vực.", "Là quá trình liên kết giữa các quốc gia thông qua việc tham gia các tổ chức toàn cầu.", "Là quá trình liên kết giữa các quốc gia thông qua việc tham gia các tổ chức xã hội."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: Đề 1 đáp án.docx · Phần I câu 16 · khoá: gạch chân"}, {"id": "L12-8T1-05-C17", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Để thực hiện tốt chính sách an sinh xã hội về giải quyết việc làm, Nhà nước khuyến khích các doanh nghiệp", "o": ["tạo ra nhiều sản phẩm.", "tạo ra nhiều việc làm mới.", "bảo vệ người lao động.", "tăng thu nhập cho người lao động."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: Đề 1 đáp án.docx · Phần I câu 17 · khoá: gạch chân"}, {"id": "L12-8T1-05-C18", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Trong hệ thống chính sách an sinh xã hội ở nước ta hiện nay, một trong những chính sách dịch vụ xã hội cơ bản là dịch vụ", "o": ["việc làm tối thiểu.", "thu nhập tối đa.", "y tế tối thiểu.", "bảo hiểm tối thiểu."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: Đề 1 đáp án.docx · Phần I câu 18 · khoá: gạch chân"}, {"id": "L12-8T1-05-C19", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Bảo hiểm y tế là hình thức bảo hiểm thuộc lĩnh vực chăm sóc sức khỏe cộng đồng do", "o": ["đoàn thể thực hiện.", "Nhà nước thực hiện.", "Công đoàn thực hiện.", "người dân thực hiện."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: Đề 1 đáp án.docx · Phần I câu 19 · khoá: gạch chân"}, {"id": "L12-8T1-05-C20", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Loại hình bảo hiểm do Nhà nước tổ chức mà người lao động và người sử dụng lao động thuộc đối tượng theo quy định phải tham gia là", "o": ["bảo hiểm thân thể.", "bảo hiểm xã hội tự nguyện.", "bảo hiểm xã hội bắt buộc.", "bảo hiểm tài sản."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: Đề 1 đáp án.docx · Phần I câu 20 · khoá: gạch chân"}, {"id": "L12-8T1-05-C21", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đọc đoạn thông tin sau:\nTính chung thời kì thực hiện Chiến lược phát triển kinh tế xã hội 10 năm (2011 - 2020), tăng trưởng GDP của Việt Nam đạt khoảng 5,9%/năm, thuộc nhóm các nước tăng trưởng cao trong khu vực. Quy mô GDP tăng gấp 2,4 lần, từ 116 tỉ USD năm 2010 lên 268,4 tỉ USD vào năm 2020. GDP bình quân đầu người tăng từ 1.331 USD năm 2010 lên khoảng 2.750 USD năm 2020. Tỉ lệ hộ nghèo cả nước giảm nhanh, từ 14,2% năm 2010 xuống còn 7% năm 2015 (theo chuẩn nghèo giai đoạn 2011 - 2015) và giảm từ 9,2% năm 2016 xuống dưới 3% vào năm 2020 (theo chuẩn nghèo đa chiều). Cơ sở hạ tầng thiết yếu ở các huyện nghèo, xã nghèo, vùng đồng bào dân tộc thiểu số được tăng cường. Thực hiện nhiều giải pháp tạo việc làm, nâng cao thu nhập cho người lao động.\nNội dung nào dưới đây không phải là chỉ tiêu cơ bản để đánh giá sự tăng trưởng và phát triển kinh tế trong thông tin trên?", "o": ["Thu nhập bình quân theo GDP.", "Tốc độ tăng dân số.", "Tốc độ tăng GDP.", "Tỷ lệ hộ nghèo và thu nhập."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: Đề 1 đáp án.docx · Phần I câu 21 · khoá: gạch chân"}, {"id": "L12-8T1-05-C22", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đọc đoạn thông tin sau:\nTính chung thời kì thực hiện Chiến lược phát triển kinh tế xã hội 10 năm (2011 - 2020), tăng trưởng GDP của Việt Nam đạt khoảng 5,9%/năm, thuộc nhóm các nước tăng trưởng cao trong khu vực. Quy mô GDP tăng gấp 2,4 lần, từ 116 tỉ USD năm 2010 lên 268,4 tỉ USD vào năm 2020. GDP bình quân đầu người tăng từ 1.331 USD năm 2010 lên khoảng 2.750 USD năm 2020. Tỉ lệ hộ nghèo cả nước giảm nhanh, từ 14,2% năm 2010 xuống còn 7% năm 2015 (theo chuẩn nghèo giai đoạn 2011 - 2015) và giảm từ 9,2% năm 2016 xuống dưới 3% vào năm 2020 (theo chuẩn nghèo đa chiều). Cơ sở hạ tầng thiết yếu ở các huyện nghèo, xã nghèo, vùng đồng bào dân tộc thiểu số được tăng cường. Thực hiện nhiều giải pháp tạo việc làm, nâng cao thu nhập cho người lao động.\nYếu tố nào được đề cập trong thông tin trên là nhân tố quyết định việc thực hiện các chỉ tiêu phát triển kinh tế về mặt xã hội?", "o": ["Tăng trưởng dân số.", "Tốc độ tăng lạm phát.", "Tăng trưởng việc làm.", "Tăng trưởng kinh tế."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: Đề 1 đáp án.docx · Phần I câu 22 · khoá: gạch chân"}, {"id": "L12-8T1-05-C23", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đọc đoạn thông tin sau:\nDiễn đàn hợp tác kinh tế là hình thức hội nhập kinh tế quốc tế ra đời vào thập niên 80 thế kỷ XX, ví dụ: Diễn đàn hợp tác kinh tế châu Á - Thái Bình Dương (APEC) và Diễn đàn hợp tác Á - Âu (ASEM). Các quốc gia tham gia diễn đàn hợp tác kinh tế không có những cam kết mang tính ràng buộc thực hiện, mà chủ yếu mang tính định hướng, khuyến nghị hành động đối với các quốc gia thành viên. Những nguyên tắc được xây dựng giữa các quốc gia tham gia diễn đàn là linh hoạt và tự nguyện để thực hiện tự do hoá và thuận lợi hoá thương mại, đầu tư. Tuy vậy, ngày nay, diễn đàn hợp tác kinh tế cũng có vai trò khá quan trọng trong định hướng phát triển kinh tế, thương mại cũng như giải quyết các vấn đề kinh tế-xã hội cùng quan tâm của các quốc gia trong một khu vực, duy trì, thúc đẩy quá trình hội nhập quốc tế.\nCho biết nội dung nào dưới đây thể hiện mục đích của hội nhập kinh tế song phương và đa phương giữa các nước trên thế giới hiện nay, theo đoạn thông tin?", "o": ["Thúc đẩy chuyển giao vũ khí.", "Phân chia lợi nhuận bình quân.", "Phân chia lại phạm vi quyền lực.", "Thúc đẩy tự do hóa thương mại."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: Đề 1 đáp án.docx · Phần I câu 23 · khoá: gạch chân"}, {"id": "L12-8T1-05-C24", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đọc đoạn thông tin sau:\nDiễn đàn hợp tác kinh tế là hình thức hội nhập kinh tế quốc tế ra đời vào thập niên 80 thế kỷ XX, ví dụ: Diễn đàn hợp tác kinh tế châu Á - Thái Bình Dương (APEC) và Diễn đàn hợp tác Á - Âu (ASEM). Các quốc gia tham gia diễn đàn hợp tác kinh tế không có những cam kết mang tính ràng buộc thực hiện, mà chủ yếu mang tính định hướng, khuyến nghị hành động đối với các quốc gia thành viên. Những nguyên tắc được xây dựng giữa các quốc gia tham gia diễn đàn là linh hoạt và tự nguyện để thực hiện tự do hoá và thuận lợi hoá thương mại, đầu tư. Tuy vậy, ngày nay, diễn đàn hợp tác kinh tế cũng có vai trò khá quan trọng trong định hướng phát triển kinh tế, thương mại cũng như giải quyết các vấn đề kinh tế-xã hội cùng quan tâm của các quốc gia trong một khu vực, duy trì, thúc đẩy quá trình hội nhập quốc tế.\nCác diễn đàn hợp tác kinh tế như APEC và ASEM chủ yếu giải quyết các vấn đề nào dưới đây theo thông tin trên?", "o": ["Chính trị - quân sự.", "Kinh tế - quốc phòng.", "Kinh tế - thương mại.", "Ngoại giao – quốc phòng."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: Đề 1 đáp án.docx · Phần I câu 24 · khoá: gạch chân"}, {"id": "L12-8T1-05-C25", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "dung_sai", "status": "cho_duyet", "q": "Đọc đoạn thông tin sau và cho biết mỗi ý a, b, c, d là Đúng hay Sai. Theo Tổng cục Thống kê năm 2022, tổng tỷ lệ nghèo đa chiều cả nước là 9,35%, trong đó tỷ lệ hộ nghèo là 5,2% và tỷ lệ hộ cận nghèo là 4,15%. Theo báo cáo, Chỉ số phát triển con người (HDI) của Việt Nam là 0,703 vào năm 2021, tăng hai bậc, lên vị trí 115/191 quốc gia, thuộc nhóm trung bình cao của thế giới.", "o": ["Tổng tỷ lệ nghèo đa chiều bằng tổng tỷ lệ hộ nghèo và hộ cận nghèo.", "Việt Nam đứng thứ 115/191 về HDI, thuộc nhóm phát triển con người cao.", "Tăng trưởng kinh tế cao tạo tiền đề vật chất để thực hiện các mục tiêu về con người.", "Thực hiện nền kinh tế xanh, kinh tế tuần hoàn là mục tiêu của tăng trưởng kinh tế."], "a": [true, false, true, false], "e": "Đáp án: a) Đúng; b) Sai; c) Đúng; d) Sai.", "nguon": "Đề nguồn: Đề 1 đáp án.docx · Phần II câu 1 · khoá: chữ Đúng/Sai trong ý"}, {"id": "L12-8T1-05-C26", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "dung_sai", "status": "cho_duyet", "q": "Đọc đoạn thông tin sau và cho biết mỗi ý a, b, c, d là Đúng hay Sai. Vị thế của Việt Nam trên thế giới đã được củng cố toàn diện trong giai đoạn 2011 - 2022. Đến năm 2020, Việt Nam có 30 đối tác chiến lược và đối tác chiến lược toàn diện; có quan hệ ngoại giao với 189/193 nước, có quan hệ kinh tế với 160 nước và 70 vùng lãnh thổ. Đến năm 2022, tổng số quan hệ kinh tế - thương mại của Việt Nam đã nâng lên thành 230 nước và vùng lãnh thổ.", "o": ["Thiết lập quan hệ đối tác chiến lược là hội nhập kinh tế ở cấp độ khu vực.", "Hội nhập kinh tế góp phần thúc đẩy tăng trưởng GDP vì xuất khẩu hàng hóa được đẩy mạnh.", "Nước đang phát triển khi hội nhập phải chấp nhận từ bỏ lợi ích của mình.", "Hội nhập kinh tế quốc tế giúp hàng hóa Việt Nam dễ dàng thâm nhập thị trường thế giới."], "a": [false, true, false, true], "e": "Đáp án: a) Sai; b) Đúng; c) Sai; d) Đúng.", "nguon": "Đề nguồn: Đề 1 đáp án.docx · Phần II câu 2 · khoá: chữ Đúng/Sai trong ý"}, {"id": "L12-8T1-05-C27", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "dung_sai", "status": "cho_duyet", "q": "Đọc đoạn thông tin sau và cho biết mỗi ý a, b, c, d là Đúng hay Sai. Chị D cho biết, trước đây chị làm công nhân đã có 10 năm tham gia BHXH bắt buộc và sau khi nghỉ việc chị không còn được tham gia nữa. Chị chuyển sang bán hàng ăn để mưu sinh. Tính đến nay chị đã đóng BHXH tự nguyện được 5 năm, mỗi lần đều đóng theo quý, mỗi quý hơn 600 nghìn đồng. Không những tham gia BHXH tự nguyện, chị còn tham gia cả BHYT hộ gia đình.", "o": ["Lao động tự do có thể tham gia BHXH tự nguyện với mức đóng và phương thức đóng linh hoạt.", "Người tham gia BHXH tự nguyện được hưởng trợ cấp ốm đau như người tham gia BHXH bắt buộc.", "Bảo hiểm y tế do Nhà nước tổ chức, thuộc lĩnh vực chăm sóc sức khỏe cộng đồng.", "Mọi người có hợp đồng lao động đều được tham gia BHXH tự nguyện, không thuộc diện bắt buộc."], "a": [true, false, true, false], "e": "Đáp án: a) Đúng; b) Sai; c) Đúng; d) Sai.", "nguon": "Đề nguồn: Đề 1 đáp án.docx · Phần II câu 3 · khoá: chữ Đúng/Sai trong ý"}, {"id": "L12-8T1-05-C28", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "dung_sai", "status": "cho_duyet", "q": "Đọc đoạn thông tin sau và cho biết mỗi ý a, b, c, d là Đúng hay Sai. Bảo đảm nước sạch cho nhân dân là một nhiệm vụ và mục tiêu quan trọng mang tầm quốc gia. Chính phủ đã ban hành Chương trình mục tiêu Quốc gia nước sạch và vệ sinh môi trường nông thôn giai đoạn 2012-2015; Chiến lược quốc gia cấp nước sạch và vệ sinh nông thôn đến năm 2030. Phấn đấu đến năm 2030 có 65% dân số nông thôn được sử dụng nước sạch theo quy chuẩn với số lượng tối thiểu 60 lít/người/ngày.", "o": ["Chương trình nước sạch nông thôn thuộc chính sách việc làm, xóa đói giảm nghèo.", "Nước sạch là dịch vụ xã hội cơ bản, đồng thời gắn với chất lượng sống của người dân.", "Việc ban hành chương trình nước sạch là công cụ quản lí của Nhà nước nhằm bảo đảm công bằng xã hội.", "Ngân sách nhà nước là nguồn lực duy nhất để thực hiện chương trình nước sạch nông thôn."], "a": [false, true, true, false], "e": "Đáp án: a) Sai; b) Đúng; c) Đúng; d) Sai.", "nguon": "Đề nguồn: Đề 1 đáp án.docx · Phần II câu 4 · khoá: chữ Đúng/Sai trong ý"}]}, {"id": "L12-8T1-06", "loai": "khoi", "khoi": 12, "hoc_ki": 1, "bo": "8T1", "ten_bo": "8 tuần học kì I", "so_de": 6, "ten": "Lớp 12 · 8 tuần học kì I · Đề 6", "pham_vi": "Bài 1–4 (đề nguồn «HỌC KÌ 1 › bai_1_4») · file nguồn: Đề 2 đáp án.docx", "thoi_gian": 50, "cau_truc": "24 câu trắc nghiệm + 4 câu đúng/sai (mỗi câu 4 ý)", "status": "cho_duyet", "khoa": {"1 nguồn": 28}, "sua": "", "cau": [{"id": "L12-8T1-06-C01", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Mối quan hệ giữa tăng trưởng kinh tế và phát triển bền vững được thể hiện ở nội dung nào dưới đây?", "o": ["Tăng trưởng kinh tế và phát triển bền vững không liên quan đến nhau.", "Tăng trưởng kinh tế không gây ảnh hưởng đến phát triển bền vững.", "Tăng trưởng kinh tế và phát triển bền vững là hai nội dung đối lập, không thể thực hiện đồng thời.", "Tăng trưởng kinh tế là điều kiện tiên quyết để đạt được phát triển bền vững."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: Đề 2 đáp án.docx · Phần I câu 1 · khoá: gạch chân"}, {"id": "L12-8T1-06-C02", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Yếu tố nào dưới đây là chỉ tiêu của phát triển kinh tế?", "o": ["Mức sống bình dân.", "Tiến bộ xã hội.", "Cơ cấu dòng tiền.", "Tăng trưởng dân số."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: Đề 2 đáp án.docx · Phần I câu 2 · khoá: gạch chân"}, {"id": "L12-8T1-06-C03", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Phát biểu nào dưới đây là đúng về hội nhập kinh tế quốc tế?", "o": ["Hội nhập kinh tế quốc tế chỉ cần thiết đối với những quốc gia đang phát triển để thu hẹp khoảng cách tụt hậu.", "Trong hội nhập kinh tế quốc tế, một quốc gia được lợi thì sẽ có quốc gia khác chịu thiệt về kinh tế.", "Hội nhập kinh tế quốc tế tạo ra sự phụ thuộc và mất cân bằng về lợi ích giữa các quốc gia với nhau.", "Hội nhập kinh tế quốc tế có thể diễn ra giữa hai quốc gia với nhau trên cơ sở cùng có lợi về kinh tế."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: Đề 2 đáp án.docx · Phần I câu 3 · khoá: gạch chân"}, {"id": "L12-8T1-06-C04", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Sự phát triển nào dưới đây phản ánh sự chuyển biến tổng hợp của nền kinh tế cả về số lượng và chất lượng?", "o": ["Phát triển kinh tế.", "Tăng trưởng kinh tế.", "Tỷ lệ lạm phát.", "Tỷ lệ thất nghiệp."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: Đề 2 đáp án.docx · Phần I câu 4 · khoá: gạch chân"}, {"id": "L12-8T1-06-C05", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Sự gia tăng về quy mô sản lượng của một nền kinh tế trong một thời kỳ nhất định so với thời kỳ gốc là nội dung của khái niệm nào dưới đây?", "o": ["Tăng trưởng xã hội và tiến bộ, công bằng trong phân phối thu nhập.", "Tăng trưởng kinh tế.", "Phát triển kinh tế.", "Hội nhập kinh tế."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: Đề 2 đáp án.docx · Phần I câu 5 · khoá: gạch chân"}, {"id": "L12-8T1-06-C06", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Phát biểu nào dưới đây là đúng về chỉ tiêu tăng trưởng kinh tế?", "o": ["Mức tăng chỉ số bất bình đẳng trong phân phối thu nhập.", "Mức tăng tổng thu nhập quốc dân trong một thời kỳ nhất định.", "Mức tăng dân số của một quốc gia trong một thời kỳ nhất định.", "Mức tăng thu nhập của từng cá nhân trong một thời kỳ nhất định."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: Đề 2 đáp án.docx · Phần I câu 6 · khoá: gạch chân"}, {"id": "L12-8T1-06-C07", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đối với các nước đang phát triển, việc tham gia vào quá trình hội nhập kinh tế quốc tế sẽ mang lại lợi ích nào dưới đây?", "o": ["Lệ thuộc tài chính vào nước lớn.", "Tận dụng được nguồn tài chính.", "Mở mang thêm phạm vi lãnh thổ.", "Được chuyển lên thành nước lớn."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: Đề 2 đáp án.docx · Phần I câu 7 · khoá: gạch chân"}, {"id": "L12-8T1-06-C08", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đối với mỗi quốc gia, hình thức hội nhập sâu rộng nhất, gắn kết với nhiều quốc gia, tổ chức, khu vực trên thế giới là hình thức nào dưới đây?", "o": ["Hội nhập liên minh.", "Hội nhập song phương.", "Hội nhập khu vực.", "Hội nhập toàn cầu."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: Đề 2 đáp án.docx · Phần I câu 8 · khoá: gạch chân"}, {"id": "L12-8T1-06-C09", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Việc gia nhập Tổ chức Thương mại thế giới thể hiện Việt Nam tham gia cấp độ hội nhập nào dưới đây?", "o": ["Hội nhập song phương.", "Hội nhập khu vực.", "Hội nhập toàn cầu,", "Hội nhập đa phương."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: Đề 2 đáp án.docx · Phần I câu 9 · khoá: gạch chân"}, {"id": "L12-8T1-06-C10", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Là hình thức các bên tham gia hình thành thị trường chung đồng thời xây dựng chính sách kinh tế chung, thực hiện những mục tiêu chung cho toàn liên minh là thể hiện mức độ hội nhập kinh tế quốc tế ở mức độ", "o": ["thị trường chung.", "liên minh kinh tế.", "hiệp định thương mại tự do.", "thoả thuận thương mại ưu đãi."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: Đề 2 đáp án.docx · Phần I câu 10 · khoá: gạch chân"}, {"id": "L12-8T1-06-C11", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Các hoạt động kinh tế đối ngoại của quốc gia không gồm hoạt động nào?", "o": ["Thương mại nội địa.", "Thương mại quốc tế.", "Dịch vụ thu ngoại tệ.", "Đầu tư quốc tế."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: Đề 2 đáp án.docx · Phần I câu 11 · khoá: gạch chân"}, {"id": "L12-8T1-06-C12", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Thông qua việc gắn kết nền kinh tế của mình với các quốc gia khác trong khu vực và toàn thế giới, giúp các quốc gia có thể tận dụng được những", "o": ["ràng buộc về mặt lãnh thổ và chủ quyền quốc gia.", "hỗ trợ từ các tổ chức khủng bố.", "sai lầm của các quốc gia khác.", "thành tựu khoa học – công nghệ."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: Đề 2 đáp án.docx · Phần I câu 12 · khoá: gạch chân"}, {"id": "L12-8T1-06-C13", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Loại hình bảo hiểm do Nhà nước tổ chức nhằm bảo đảm thay thế hoặc bù đắp một phần thu nhập của người lao động khi họ bị giảm hoặc mất thu nhập do ốm, đau, thai sản, tai nạn lao động, bệnh nghề nghiệp, hết tuổi lao động dựa trên cơ sở mức đóng vào quỹ bảo hiểm xã hội của người lao động trước đó là loại hình bảo hiểm nào dưới đây?", "o": ["Bảo hiểm xã hội.", "Bảo hiểm dân sự.", "Bảo hiểm con người.", "Bảo hiểm thương mại."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: Đề 2 đáp án.docx · Phần I câu 13 · khoá: gạch chân"}, {"id": "L12-8T1-06-C14", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Chủ thể của loại hình bảo hiểm xã hội là do", "o": ["các doanh nghiệp tư nhân.", "tổ chức thương mại.", "nhà đầu tư nước ngoài.", "Nhà nước tổ chức."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: Đề 2 đáp án.docx · Phần I câu 14 · khoá: gạch chân"}, {"id": "L12-8T1-06-C15", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Về mặt kinh tế, một trong những vai trò của bảo hiểm góp phần giúp các cá nhân và tổ chức tham gia bảo hiểm", "o": ["ngày càng lệ thuộc vào nhau.", "ổn định được nguồn tài chính.", "thu được nhiều lợi nhuận từ việc khai thác tài sản của người khác.", "chiếm đoạt tài sản của nhau."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: Đề 2 đáp án.docx · Phần I câu 15 · khoá: gạch chân"}, {"id": "L12-8T1-06-C16", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Anh A đến đại lý bán bảo hiểm để mua bảo hiểm trách nhiệm dân sự xe cơ giới cho chiếc xe máy mà mình đang sử dụng. Bác A đã sử dụng loại hình bảo hiểm nào dưới đây?", "o": ["Bảo hiểm y tế.", "Bảo hiểm thương mại.", "Bảo hiểm xã hội.", "Bảo hiểm thất nghiệp."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: Đề 2 đáp án.docx · Phần I câu 16 · khoá: gạch chân"}, {"id": "L12-8T1-06-C17", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đối với đối tượng được hưởng chính sách an sinh xã hội, việc thực hiện tốt chính sách an sinh xã hội đem lại lợi ích nào dưới đây?", "o": ["Hưởng thu nhập vô điều kiện", "Được hoàn trả lại lợi ích đã mất.", "Khắc phục và giảm thiếu rủi ro.", "Được hỗ trợ miễn phí trọn đời."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: Đề 2 đáp án.docx · Phần I câu 17 · khoá: gạch chân"}, {"id": "L12-8T1-06-C18", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Hệ thống các chính sách can thiệp của Nhà nước và các lực lượng xã hội thực hiện nhằm giảm mức độ nghèo đói, nâng cao năng lực tự bảo vệ của người dân và xã hội trước những rủi ro hay nguy cơ giảm hoặc mất thu nhập, bảo đảm ổn định, phát triển và công bằng xã hội là nội dung của khái niệm nào dưới đây?", "o": ["An sinh xã hội.", "Bảo hiểm xã hội.", "Chất lượng cuộc sống.", "Thượng tầng xã hội."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: Đề 2 đáp án.docx · Phần I câu 18 · khoá: gạch chân"}, {"id": "L12-8T1-06-C19", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Việc nhà nước có chính sách hỗ trợ gạo từ nguồn ngân sách nhà nước cho nhân dân các vùng khó khăn dịp Tết nguyên đán là thực hiện chính sách an sinh xã hội nào dưới đây?", "o": ["Chính sách hỗ trợ bảo hiểm.", "Chính sách trợ giúp xã hội.", "Chính sách trợ giúp việc làm.", "Chính sách hỗ trợ thu nhập."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: Đề 2 đáp án.docx · Phần I câu 19 · khoá: gạch chân"}, {"id": "L12-8T1-06-C20", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đối với mỗi quốc gia, an sinh xã hội là một trong những tiêu chí đánh giá sự", "o": ["bất công xã hội.", "vi phạm dân quyền.", "phát triển kinh tế.", "tiến bộ xã hội."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: Đề 2 đáp án.docx · Phần I câu 20 · khoá: gạch chân"}, {"id": "L12-8T1-06-C21", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đọc đoạn thông tin sau:\nCơ cấu kinh tế ngành và nội ngành chuyển biến tích cực; tỉ trọng công nghiệp chế biến, chế tạo và ứng dụng công nghệ cao tăng lên. Tỉ trọng lao động nông, lâm nghiệp và thuỷ sản trong tổng số lao động cả nước giảm từ 48,6% năm 2010 xuống còn 34% năm 2020. Tỉ trọng lao động ngành công nghiệp và xây dựng tăng từ 21,7% lên 30,3%. Thu nhập bình quân đầu người tăng 3,1 lần, từ 16,6 triệu đồng năm 2010 lên 51,5 triệu đồng năm 2019.\nMột nền kinh tế được coi là phát triển khi cơ cấu lao động trong lĩnh vực công nghiệp và dịch vụ phải lớn hơn lao động tham gia vào khu vực", "o": ["công nghiệp chế biến và xây dựng.", "vận tải và kho bãi.", "dịch vụ và thương mại trong nền kinh tế.", "nông nghiệp."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: Đề 2 đáp án.docx · Phần I câu 21 · khoá: gạch chân"}, {"id": "L12-8T1-06-C22", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Giải quyết tốt vấn đề nào dưới đây sẽ góp phần nâng cao chỉ số phát triển con người (HDI) ở nước ta hiện nay?", "o": ["Chuyển dịch cơ cấu kinh tế.", "Gia tăng tỷ trọng ngành dịch vụ.", "Phát triển nông nghiệp hữu cơ và sản xuất thân thiện với môi trường trên diện rộng.", "Giải quyết việc làm và thu nhập."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: Đề 2 đáp án.docx · Phần I câu 22 · khoá: gạch chân"}, {"id": "L12-8T1-06-C23", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đọc đoạn thông tin sau:\nKể từ khi chính thức gia nhập WTO, Việt Nam đã ghi nhận những thành tựu về phát triển kinh tế. Việt Nam trở thành nền kinh tế có độ mở cao, tới 200% GDP và cải thiện cán cân thương mại hàng hóa, chuyển từ nhập siêu sang xuất siêu trong giai đoạn 2016 - 2020. Năm 2022, cán cân thương mại xuất siêu đạt 12,4 tỷ USD, là năm thứ 7 liên tiếp cán cân thương mại hàng hóa ở mức thặng dư.\nNội dung nào dưới đây thể hiện vai trò của hoạt động hội nhập kinh tế quốc tế của Việt Nam?", "o": ["Dịch chuyển dòng ngoại tệ.", "Gia tăng sự lệ thuộc về chính trị.", "Tăng cường quốc phòng.", "Đẩy mạnh xuất khẩu hàng hóa."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: Đề 2 đáp án.docx · Phần I câu 23 · khoá: gạch chân"}, {"id": "L12-8T1-06-C24", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Việc gia nhập WTO của Việt Nam là biểu hiện của hình thức hội nhập nào dưới đây?", "o": ["Hội nhập khu vực.", "Hội nhập toàn cầu.", "Hội nhập song phương.", "Hội nhập toàn diện."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: Đề 2 đáp án.docx · Phần I câu 24 · khoá: gạch chân"}, {"id": "L12-8T1-06-C25", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "dung_sai", "status": "cho_duyet", "q": "Đọc đoạn thông tin sau và cho biết mỗi ý a, b, c, d là Đúng hay Sai. Về cơ cấu nền kinh tế năm 2023, khu vực nông, lâm nghiệp và thủy sản chiếm tỷ trọng 11,96%; khu vực công nghiệp và xây dựng chiếm 37,12%; khu vực dịch vụ chiếm 42,54%. GDP bình quân đầu người năm 2023 ước đạt 101,9 triệu đồng/người, tương đương 4.284,5 USD, tăng 160 USD so với năm 2022. Năng suất lao động theo giá so sánh tăng 3,65% do trình độ của người lao động được cải thiện.", "o": ["Cơ cấu ngành kinh tế chuyển dịch chưa phù hợp với các chỉ tiêu phát triển kinh tế.", "Thu nhập 4.284,5 USD/người là thu nhập quốc dân bình quân theo đầu người.", "Năng suất lao động theo giá so sánh tăng 3,65% do trình độ người lao động được cải thiện.", "Trình độ người lao động là tiêu chí đánh giá sự phát triển kinh tế."], "a": [false, false, true, false], "e": "Đáp án: a) Sai; b) Sai; c) Đúng; d) Sai.", "nguon": "Đề nguồn: Đề 2 đáp án.docx · Phần II câu 1 · khoá: chữ Đúng/Sai trong ý"}, {"id": "L12-8T1-06-C26", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "dung_sai", "status": "cho_duyet", "q": "Đọc đoạn thông tin sau và cho biết mỗi ý a, b, c, d là Đúng hay Sai. Theo Tổng cục Thống kê công bố, tốc độ tăng trưởng GDP năm 2023 đạt 5,05% và có xu hướng tăng dần theo thời gian, quý IV đạt 6,72%, cao nhất so với quý III, II và quý I (tương ứng 5,47%, 4,25% và 3,41%).", "o": ["Quý IV năm 2023 có tốc độ tăng GDP cao nhất trong năm.", "Tốc độ tăng GDP năm 2023 cho thấy Việt Nam là quốc gia có mức sống cao.", "Tốc độ tăng GDP quý III năm 2023 (5,47%) cao hơn tốc độ tăng GDP cả năm 2023 (5,05%).", "Tốc độ tăng GDP năm 2023 là căn cứ để so sánh với tăng trưởng kinh tế năm 2024."], "a": [true, false, true, true], "e": "Đáp án: a) Đúng; b) Sai; c) Đúng; d) Đúng.", "nguon": "Đề nguồn: Đề 2 đáp án.docx · Phần II câu 2 · khoá: chữ Đúng/Sai trong ý"}, {"id": "L12-8T1-06-C27", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "dung_sai", "status": "cho_duyet", "q": "Đọc đoạn thông tin sau và cho biết mỗi ý a, b, c, d là Đúng hay Sai. Tăng trưởng kinh tế giai đoạn 2016 - 2020 đạt trung bình 7%/năm, nâng mức thu nhập bình quân đầu người hằng năm tính theo GDP tăng lên 3.200 - 3.500 USD (so với mức 2.100 USD năm 2015). Lạm phát giữ ở mức dưới 5%. Thu nhập bình quân đầu người đạt 2.052 USD/người (2014). Tuổi thọ trung bình đạt 73,5 tuổi (2015). Trên 72% dân số tham gia bảo hiểm y tế.", "o": ["Tăng trưởng 7%/năm giai đoạn 2016–2020 tạo tiền đề vật chất thúc đẩy các chỉ tiêu phát triển kinh tế.", "Thu nhập theo đầu người từ 3.500 USD giảm xuống còn 2.052 USD phản ánh phát triển kinh tế đi xuống.", "Tuổi thọ trung bình tăng là kết quả của việc thực hiện tăng trưởng kinh tế cao.", "72% dân số tham gia bảo hiểm y tế là chỉ tiêu về tiến bộ xã hội khi nước ta phát triển kinh tế."], "a": [true, false, true, true], "e": "Đáp án: a) Đúng; b) Sai; c) Đúng; d) Đúng.", "nguon": "Đề nguồn: Đề 2 đáp án.docx · Phần II câu 3 · khoá: chữ Đúng/Sai trong ý"}, {"id": "L12-8T1-06-C28", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "dung_sai", "status": "cho_duyet", "q": "Đọc đoạn thông tin sau và cho biết mỗi ý a, b, c, d là Đúng hay Sai. Tổ chức Thương mại thế giới được thành lập và hoạt động từ ngày 01/01/1995 với mục tiêu thiết lập và duy trì một nền thương mại toàn cầu tự do, thuận lợi và minh bạch. Tham gia WTO, các quốc gia được hưởng các quy định về tự do thương mại hàng hoá, dịch vụ, sở hữu trí tuệ và đầu tư. Từ ngày 11/01/2007, Việt Nam chính thức trở thành thành viên thứ 150 của WTO.", "o": ["WTO thuộc cấp độ hội nhập khu vực.", "Việt Nam là thành viên thứ 150 của WTO từ 11/1/2007 nên thuộc cấp độ hội nhập toàn cầu.", "Khi tham gia WTO, chỉ các nước phát triển được hưởng lợi ích.", "Các quốc gia thành viên không nhất thiết phải tuân thủ quy định chung của WTO."], "a": [false, true, false, false], "e": "Đáp án: a) Sai; b) Đúng; c) Sai; d) Sai.", "nguon": "Đề nguồn: Đề 2 đáp án.docx · Phần II câu 4 · khoá: chữ Đúng/Sai trong ý"}]}, {"id": "L12-8T1-07", "loai": "khoi", "khoi": 12, "hoc_ki": 1, "bo": "8T1", "ten_bo": "8 tuần học kì I", "so_de": 7, "ten": "Lớp 12 · 8 tuần học kì I · Đề 7", "pham_vi": "Bài 1–4 (đề nguồn «HỌC KÌ 1 › bai_1_4») · file nguồn: Đề 3 đáp án.docx", "thoi_gian": 50, "cau_truc": "24 câu trắc nghiệm + 4 câu đúng/sai (mỗi câu 4 ý)", "status": "cho_duyet", "khoa": {"1 nguồn": 28}, "sua": "", "cau": [{"id": "L12-8T1-07-C01", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đối với một quốc gia tăng trưởng và phát triển kinh tế có vai trò quan trọng, là điều kiện cần thiết để", "o": ["thúc đẩy tỷ lệ thất nghiệp.", "gia tăng tỷ lệ lạm phát và làm giảm sức mua của đồng tiền.", "thúc đẩy phân hóa giàu nghèo.", "khắc phục tình trạng đói nghèo."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: Đề 3 đáp án.docx · Phần I câu 1 · khoá: gạch chân"}, {"id": "L12-8T1-07-C02", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Trong quá trình hội nhập quốc tế, tăng trưởng kinh tế là điều kiện tiên quyết để nước ta không rơi vào tình trạng nào dưới đây?", "o": ["Thu hút nguồn vốn đầu tư trực tiếp.", "Có quan hệ song phương toàn diện.", "Hợp tác và cạnh tranh toàn diện.", "Ngày càng tụt hậu so với thế giới."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: Đề 3 đáp án.docx · Phần I câu 2 · khoá: gạch chân"}, {"id": "L12-8T1-07-C03", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đối với một quốc gia, tăng trưởng kinh tế được thể hiện ở sự gia tăng các", "o": ["tệ nạn xã hội.", "giá trị hàng hóa.", "quan hệ đối ngoại.", "tổ chức tội phạm."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: Đề 3 đáp án.docx · Phần I câu 3 · khoá: gạch chân"}, {"id": "L12-8T1-07-C04", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Ngoài việc căn cứ vào sự tăng lên về thu nhập hay tổng giá trị hàng hóa và dịch vụ mà nền kinh tế tạo ra trong một thời kỳ nhất định, người ta còn căn cứ vào sự tăng lên của yếu tố nào dưới đây?", "o": ["Thu nhập của đối tượng yếu thế.", "Thu nhập trung bình của các quốc gia.", "Thu nhập trung bình của người dân.", "Thu nhập của tầng lớp thượng lưu."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: Đề 3 đáp án.docx · Phần I câu 4 · khoá: gạch chân"}, {"id": "L12-8T1-07-C05", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Trong mối quan hệ giữa tăng trưởng kinh tế với phát triển kinh tế nếu tăng trưởng kinh tế không hợp lý sẽ tác động như thế nào tới việc phát triển kinh tế của mỗi quốc gia?", "o": ["Không tác động tới sự phát triển.", "Tạo điều kiện thuận lợi để phát triển", "Kìm hãm và tác động tiêu cực.", "Thúc đẩy và tạo động lực."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: Đề 3 đáp án.docx · Phần I câu 5 · khoá: gạch chân"}, {"id": "L12-8T1-07-C06", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Khi tham gia vào các quan hệ kinh tế quốc tế, các quốc gia thoả thuận, cam kết dành cho nhau các ưu đãi về thuế quan và phi thuế quan đối với hàng hoá của nhau là thể hiện mức độ hội nhập kinh tế quốc tế ở mức độ", "o": ["hiệp định thương mại tự do.", "thoả thuận thương mại ưu đãi.", "thị trường chung với việc di chuyển tự do lao động và vốn giữa các nước thành viên.", "liên minh kinh tế."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: Đề 3 đáp án.docx · Phần I câu 6 · khoá: gạch chân"}, {"id": "L12-8T1-07-C07", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Quá trình một quốc gia thực hiện việc gắn kết nền kinh tế của mình với nền kinh các quốc gia khác trong khu vực và trên thế giới dựa trên cơ sở cùng có lợi và tuân thủ quy định chung là nội dung của khái niệm nào dưới đây?", "o": ["Kinh tế đối ngoại.", "Hội nhập kinh tế.", "Phát triển kinh tế.", "Tăng trưởng kinh tế."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: Đề 3 đáp án.docx · Phần I câu 7 · khoá: gạch chân"}, {"id": "L12-8T1-07-C08", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Các hoạt động kinh tế đối ngoại của quốc gia không gồm hoạt động nào?", "o": ["Thương mại nội địa.", "Thương mại quốc tế.", "Dịch vụ thu ngoại tệ.", "Đầu tư quốc tế."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: Đề 3 đáp án.docx · Phần I câu 8 · khoá: gạch chân"}, {"id": "L12-8T1-07-C09", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Việc các quốc gia cùng nhau tham gia các liên minh thuế quan chung là biểu hiện của hình thức", "o": ["hợp tác lĩnh vực chính trị.", "hợp tác về biên giới lãnh thổ.", "hội nhập kinh tế quốc tế.", "hội nhập về văn hóa dân tộc."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: Đề 3 đáp án.docx · Phần I câu 9 · khoá: gạch chân"}, {"id": "L12-8T1-07-C10", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Quá trình liên kết, hợp tác giữa các quốc gia trong khu vực trên cơ sở tương đồng về địa lý, văn hóa, xã hội là một trong những hình thức hội nhập kinh tế quốc tế ở cấp độ", "o": ["hội nhập kinh tế toàn cầu.", "hội nhập kinh tế song phương.", "hội nhập kinh tế toàn diện.", "hội nhập kinh tế khu vực."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: Đề 3 đáp án.docx · Phần I câu 10 · khoá: gạch chân"}, {"id": "L12-8T1-07-C11", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Quá trình liên kết, hợp tác giữa hai quốc gia với nhau dựa trên nguyên tắc bình đẳng, cùng có lợi, tôn trọng độc lập chủ quyền của nhau l� biểu hiện của hình thức hợp tác quốc tế ở cấp độ", "o": ["hội nhập toàn cầu.", "hội nhập khu vực.", "hội nhập song phương.", "hội nhập toàn diện trên mọi lĩnh vực kinh tế, văn hóa, chính trị và xã hội."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: Đề 3 đáp án.docx · Phần I câu 11 · khoá: gạch chân"}, {"id": "L12-8T1-07-C12", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Một trong những quyền lợi của người tham gia bảo hiểm y tế là khi không may bị ốm đau, hay xảy ra tai nạn họ sẽ nhận được", "o": ["trợ cấp thai sản, ốm đau.", "tiền mặt để chi tiêu hàng ngày.", "thanh toán khám, chữa bệnh.", "lương hưu hành tháng."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: Đề 3 đáp án.docx · Phần I câu 12 · khoá: gạch chân"}, {"id": "L12-8T1-07-C13", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Một trong những mục đích của người tham gia bảo hiểm là nhằm", "o": ["phải nộp phí bảo hiểm.", "được đóng phí bảo hiểm.", "được từ chối trách nhiệm bồi thường khi rủi ro xảy ra theo hợp đồng.", "được bồi thường thiệt hại."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: Đề 3 đáp án.docx · Phần I câu 13 · khoá: gạch chân"}, {"id": "L12-8T1-07-C14", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Loại hình dịch vụ trong đó có sự cam kết bồi thường giữa bên cung cấp bảo hiểm với bên tham gia bảo hiểm về những rủi ro, thiệt hại khi xảy ra sự kiện bảo hiểm nhằm mục đích ổn định kinh tế cho người tham gia v� hướng tới đảm bảo an sinh xã hội là nội dung của khái niệm nào dưới đây?", "o": ["Thất nghiệp.", "Tăng trưởng kinh tế.", "Bảo hiểm.", "Phát triển kinh tế."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: Đề 3 đáp án.docx · Phần I câu 14 · khoá: gạch chân"}, {"id": "L12-8T1-07-C15", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Loại hình bảo hiểm nào dưới đây, trong đó hoạt động của tổ chức bảo hiểm chấp nhận rủi ro của người được bảo hiểm trên cơ sở bên mua bảo hiểm đóng phí bảo hiểm để tổ chức bảo hiểm bồi thường, trả tiền bảo hiểm khi xảy ra sự kiện bảo hiểm theo thoả thuận trong hợp đồng bảo hiểm đã được hai bên kí kết.", "o": ["Bảo hiểm ý tế.", "Bảo hiểm thất nghiệp.", "Bảo hiểm thương mại.", "Bảo hiểm xã hội."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: Đề 3 đáp án.docx · Phần I câu 15 · khoá: gạch chân"}, {"id": "L12-8T1-07-C16", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Một trong những quyền lợi của người tham gia bảo hiểm xã hội là bị ốm đau hoặc nghỉ thai sản, nếu đủ điều kiện họ sẽ được nhận", "o": ["tiền trợ cấp theo quy định.", "toàn bộ số tiền đã đóng bảo hiểm cộng với lãi suất ngân hàng.", "bảo hiểm thất nghiệp.", "chi phí khám chữa bệnh."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: Đề 3 đáp án.docx · Phần I câu 16 · khoá: gạch chân"}, {"id": "L12-8T1-07-C17", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Một trong những vai trò của an sinh xã hội là góp phần giúp các đối tượng được hưởng chính sách an sinh xã hội có thể chủ động, ngăn ngừa v� giảm bớt", "o": ["phạm tội.", "rủi ro.", "quyền lợi.", "lợi nhuận."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: Đề 3 đáp án.docx · Phần I câu 17 · khoá: gạch chân"}, {"id": "L12-8T1-07-C18", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Việc nhà nước có chính sách trợ cấp hàng tháng cho đối tượng người cao tuổi không thuộc diện được hưởng chế độ hưu trí là thực hiện chính sách an sinh xã hội nào dưới đây?", "o": ["Chính sách hỗ trợ y tế.", "Chính sách trợ giúp việc làm.", "Chính sách hỗ trợ nhà ở.", "Chính sách trợ giúp xã hội."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: Đề 3 đáp án.docx · Phần I câu 18 · khoá: gạch chân"}, {"id": "L12-8T1-07-C19", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đối với sự phát triển kinh tế xã hội, chính sách an sinh xã hội có vai trò nào dưới đây?", "o": ["Khắc phục rủi ro gặp phải.", "Giải quyết các vấn đề xã hội.", "Nâng cao chất lượng đời sống và giảm thiểu mọi loại tệ nạn xã hội.", "Nâng cao vị thế của cá nhân."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: Đề 3 đáp án.docx · Phần I câu 19 · khoá: gạch chân"}, {"id": "L12-8T1-07-C20", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Một trong những mục tiêu của chính sách an sinh xã hội về bảo hiểm nhằm giúp người dân", "o": ["xóa đói giảm nghèo.", "xóa bỏ nhà tạm.", "phòng ngừa rủi ro.", "phòng ngừa thất nghiệp."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: Đề 3 đáp án.docx · Phần I câu 20 · khoá: gạch chân"}, {"id": "L12-8T1-07-C21", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đọc đoạn thông tin sau:\nĐảng, Nhà nước đã bố trí nguồn lực từ ngân sách nhà nước và huy động nguồn lực toàn xã hội để thực hiện Chương trình mục tiêu quốc gia xóa đói giảm nghèo. Kết quả xóa đói giảm nghèo đã tạo thêm cơ sở vững chắc cho Việt Nam bảo đảm các quyền và lợi ích của người dân. Đến năm 2020, cả nước đã xây dựng, củng cố được hàng vạn ngôi nhà cho người nghèo; 99% địa bàn đồng bào dân tộc thiểu số có đường giao thông từ tỉnh đến huyện, xã.\nNội dung nào dưới đây thể hiện vai trò của tăng trưởng kinh tế đối với việc xóa đói giảm nghèo ở nước ta?", "o": ["Tăng trưởng kinh tế làm gia tăng tỷ lệ đói nghèo.", "Xóa đói giảm nghèo sẽ hạn chế sự tăng trưởng kinh tế.", "Xóa đói giảm nghèo sẽ thúc đẩy tăng trưởng kinh tế.", "Tăng trưởng kinh tế là cơ sở để xóa đói giảm nghèo."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: Đề 3 đáp án.docx · Phần I câu 21 · khoá: gạch chân"}, {"id": "L12-8T1-07-C22", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Việc thực hiện tốt công tác xóa đói giảm nghèo sẽ góp phần trực tiếp vào việc thực hiện mục tiêu nào dưới đây của phát triển kinh tế?", "o": ["Chỉ số thất nghiệp cơ cấu.", "Chỉ số lạm phát tự nhiên.", "Chỉ số lao động, việc làm và thu nhập bình quân của người lao động.", "Chỉ số phát triển con người."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: Đề 3 đáp án.docx · Phần I câu 22 · khoá: gạch chân"}, {"id": "L12-8T1-07-C23", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đọc đoạn thông tin sau:\nViệt Nam đã phát triển quan hệ kinh tế với các tổ chức quốc tế, các công ty đa quốc gia. Hiệp định thương mại tự do Việt Nam - Hàn Quốc (VKFTA, năm 2015), Hiệp định thương mại tự do Việt Nam - Liên minh Kinh tế Á - Âu (EAEU, năm 2016). Việc ký kết các FTA chứng tỏ vai trò của Việt Nam trong việc thúc đẩy thương mại tự do và hội nhập kinh tế, thương mại.\nViệc tham gia ký kết các hiệp định thương mại tự do song phương v� đa phương không mang lại ý nghĩa nào đươi đây?", "o": ["Thúc đẩy tăng trưởng kinh tế.", "Mở rộng thị trường việc làm.", "Mở rộng thị trường xuất khẩu.", "Thay đổi chế độ chính trị."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: Đề 3 đáp án.docx · Phần I câu 23 · khoá: gạch chân"}, {"id": "L12-8T1-07-C24", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Hiệp định thương mại tự do Việt Nam - Hàn Quốc là biểu hiện của hình thức hợp tác nào dưới đây?", "o": ["Hội nhập đa phương.", "Hội nhập khu vực.", "Hội nhập song phương.", "Hội nhập toàn cầu trong khuôn khổ tổ chức thương mại thế giới."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: Đề 3 đáp án.docx · Phần I câu 24 · khoá: gạch chân"}, {"id": "L12-8T1-07-C25", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "dung_sai", "status": "cho_duyet", "q": "Đọc đoạn thông tin sau và cho biết mỗi ý a, b, c, d là Đúng hay Sai. Việt Nam ngày càng thực sự phát huy vai trò của mình trong việc tham gia ngày càng sâu rộng vào quá trình liên kết khu vực và thế giới. Là thành viên của ASEAN từ năm 1995, nước ta tham gia tích cực và đóng góp vào quá trình xây dựng Cộng đồng ASEAN... Cộng đồng Pháp ngữ, Phong trào không liên kết... Nước ta đã tham gia nhiều Hiệp định thương mại tự do song phương và khu vực và đang đàm phán các Hiệp định thương mại tự do thế hệ mới.", "o": ["Cộng đồng Pháp ngữ, Phong trào không liên kết là biểu hiện của hội nhập kinh tế quốc tế.", "Việt Nam cần vừa hội nhập kinh tế song phương vừa hội nhập kinh tế đa phương.", "Kết hợp hội nhập kinh tế với hội nhập về chính trị, văn hóa để hợp tác toàn diện và sâu rộng.", "Khi hội nhập kinh tế quốc tế, Việt Nam phải tuân thủ các quy định do các nước phát triển đặt ra."], "a": [false, true, true, false], "e": "Đáp án: a) Sai; b) Đúng; c) Đúng; d) Sai.", "nguon": "Đề nguồn: Đề 3 đáp án.docx · Phần II câu 1 · khoá: chữ Đúng/Sai trong ý"}, {"id": "L12-8T1-07-C26", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "dung_sai", "status": "cho_duyet", "q": "Đọc đoạn thông tin sau và cho biết mỗi ý a, b, c, d là Đúng hay Sai. Đến nay, nước ta đã có quan hệ chính thức với 189/193 quốc gia và vùng lãnh thổ; có quan hệ thương mại với 224 đối tác và quan hệ hợp tác với hơn 300 tổ chức quốc tế; đã ký hơn 90 hiệp định thương mại song phương, gần 60 hiệp định khuyến khích và bảo hộ đầu tư; đàm phán, ký kết và thực thi 19 Hiệp định thương mại tự do (FTA).", "o": ["Việt Nam có quan hệ kinh tế với 189/193 quốc gia.", "Ký kết hiệp định thương mại song phương giúp Việt Nam mở rộng hoạt động kinh tế đối ngoại.", "Kinh tế đối ngoại góp phần thúc đẩy tăng trưởng và phát triển kinh tế.", "Hoạt động kinh tế đối ngoại là một bộ phận cấu thành chính sách đối ngoại của Việt Nam."], "a": [false, true, true, true], "e": "Đáp án: a) Sai; b) Đúng; c) Đúng; d) Đúng.", "nguon": "Đề nguồn: Đề 3 đáp án.docx · Phần II câu 2 · khoá: chữ Đúng/Sai trong ý"}, {"id": "L12-8T1-07-C27", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "dung_sai", "status": "cho_duyet", "q": "Đọc đoạn thông tin sau và cho biết mỗi ý a, b, c, d là Đúng hay Sai. Ông H, ở Thành phố K, sau khi dừng tham gia BHXH bắt buộc đã bỏ số tiền hơn 44 triệu đồng đóng BHXH tự nguyện những năm còn thiếu để được hưởng lương hưu. Quá trình tham gia BHXH của ông chỉ được 18 năm 02 tháng, chưa đủ điều kiện để hưởng chế độ hưu trí. Ông quyết định đóng BHXH tự nguyện số năm còn thiếu để hưởng lương hưu. Tiền lương hưu hàng tháng đủ trang trải cho cuộc sống hằng ngày và ông được cấp thẻ BHYT.", "o": ["Đóng một lần số năm còn thiếu để hưởng hưu trí là phù hợp vì đã có trên 18 năm tham gia.", "Rút bảo hiểm xã hội một lần là việc cần cân nhắc kỹ vì quyền lợi lâu dài.", "Ngoài chế độ hưu trí, ông H còn được hưởng trợ cấp ốm đau và chế độ bảo hiểm y tế.", "Việc linh hoạt đóng bảo hiểm xã hội tự nguyện thể hiện chính sách ưu việt của Nhà nước."], "a": [true, true, false, true], "e": "Đáp án: a) Đúng; b) Đúng; c) Sai; d) Đúng.", "nguon": "Đề nguồn: Đề 3 đáp án.docx · Phần II câu 3 · khoá: chữ Đúng/Sai trong ý"}, {"id": "L12-8T1-07-C28", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "dung_sai", "status": "cho_duyet", "q": "Đọc đoạn thông tin sau và cho biết mỗi ý a, b, c, d là Đúng hay Sai. Chị E giao kết hợp đồng lao động không xác định thời hạn với công ty A. Hàng tháng, chị E đóng đầy đủ các loại BHXH. Đến 01/6/2020, chị E nghỉ thai sản (nghỉ đến hết 31/12/2020). Vì lý do gia đình, 01/1/2021 chị E nộp đơn xin nghỉ việc. Trước khi chấm dứt HĐLĐ, tổng thời gian đóng bảo hiểm thất nghiệp là 15 tháng. Sau đó chị E tham gia gói bảo hiểm nhân thọ cho cả mẹ và con.", "o": ["Chị E tham gia bảo hiểm xã hội tự nguyện trước khi nghỉ việc.", "Chị E tham gia bảo hiểm thất nghiệp tự nguyện nên được hưởng trợ cấp thất nghiệp.", "Trước khi nghỉ việc, chị E không tham gia bảo hiểm y tế.", "Bảo hiểm nhân thọ chị E tham gia là loại hình bảo hiểm thương mại, mang tính tự nguyện."], "a": [false, false, false, true], "e": "Đáp án: a) Sai; b) Sai; c) Sai; d) Đúng.", "nguon": "Đề nguồn: Đề 3 đáp án.docx · Phần II câu 4 · khoá: chữ Đúng/Sai trong ý"}]}, {"id": "L12-8T1-08", "loai": "khoi", "khoi": 12, "hoc_ki": 1, "bo": "8T1", "ten_bo": "8 tuần học kì I", "so_de": 8, "ten": "Lớp 12 · 8 tuần học kì I · Đề 8", "pham_vi": "Bài 1–4 (đề nguồn «HỌC KÌ 1 › bai_1_4») · file nguồn: Đề 4 đáp án.docx", "thoi_gian": 50, "cau_truc": "24 câu trắc nghiệm + 4 câu đúng/sai (mỗi câu 4 ý)", "status": "cho_duyet", "khoa": {"1 nguồn": 28}, "sua": "", "cau": [{"id": "L12-8T1-08-C01", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Trong mối quan hệ giữa tăng trưởng kinh tế với phát triển kinh tế các quốc gia kiên trì mục tiêu phát triển bền vững sẽ tác động trở lại đối với tăng trưởng kinh tế theo chiều hướng nào dưới đây?", "o": ["Không thúc đẩy và bị động.", "Kìm hãm và hạn chế tác động.", "Thúc đẩy và tạo động lực.", "Cân bằng và không liên hệ."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: Đề 4 đáp án.docx · Phần I câu 1 · khoá: gạch chân"}, {"id": "L12-8T1-08-C02", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Phát biểu nào dưới đây là đúng về chỉ tiêu tăng trưởng kinh tế?", "o": ["Mức tăng chỉ số bất bình đẳng trong phân phối thu nhập.", "Mức tăng tổng thu nhập quốc dân trong một thời kỳ nhất định.", "Mức tăng dân số của một quốc gia trong một thời kỳ nhất định.", "Mức tăng thu nhập của từng cá nhân trong một thời kỳ nhất định."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: Đề 4 đáp án.docx · Phần I câu 2 · khoá: gạch chân"}, {"id": "L12-8T1-08-C03", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Một quốc gia được coi là có sự phát triển về kinh tế khi cơ cấu ngành nông nghiệp giảm đi, cơ cấu ngành công nghiệp, dịch vụ có xu hướng", "o": ["giảm theo.", "tăng lên.", "không đổi.", "cân bằng."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: Đề 4 đáp án.docx · Phần I câu 3 · khoá: gạch chân"}, {"id": "L12-8T1-08-C04", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Nội dung nào dưới đây không phản ánh bản chất của phát triển kinh tế?", "o": ["Tình trạng mất ổn định chính trị diễn ra thường xuyên trong khu vực.", "Mức sống trung bình của người dân tăng trong một thời kì nhất định.", "Cải thiện năng suất lao động thông qua áp dụng công nghệ tiên tiến.", "Tăng tỉ trọng ngành công nghiệp trong tổng sản phẩm quốc nội và giảm tỉ trọng nông nghiệp trong nền kinh tế."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: Đề 4 đáp án.docx · Phần I câu 4 · khoá: gạch chân"}, {"id": "L12-8T1-08-C05", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Trong điều kiện toàn cầu hóa, hội nhập kinh tế quốc tế giúp mỗi quốc gia có cơ hội", "o": ["mở rộng lãnh thổ và biên giới quốc gia với các nước láng giềng.", "mở rộng chủ quyền.", "mở rộng thị trường.", "mở mang trí tuệ."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: Đề 4 đáp án.docx · Phần I câu 5 · khoá: gạch chân"}, {"id": "L12-8T1-08-C06", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Xét về hình thức, hội nhập kinh tế quốc tế là toàn bộ các hoạt động kinh tế đối ngoại của một quốc gia, bao gồm các hoạt động nào dưới đây?", "o": ["Thương mại nội địa, đầu tư quốc tế, du lịch nội địa.", "Thương mại quốc tế, đầu tư trong nước, đầu tư nước ngoài và hoạt động vay vốn trong nước.", "Thương mại quốc tế, đầu tư quốc tế, dịch vụ thu ngoại tệ.", "Toàn cầu hoá kinh tế và toàn cầu hoá chính trị."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: Đề 4 đáp án.docx · Phần I câu 6 · khoá: gạch chân"}, {"id": "L12-8T1-08-C07", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Trong quá trình hội nhập kinh tế quốc tế, các bên tham gia không được sử dụng nguyên tắc nào dưới đây?", "o": ["Cùng có lợi.", "Cưỡng chế.", "Cùng thỏa thuận.", "Bình đẳng."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: Đề 4 đáp án.docx · Phần I câu 7 · khoá: gạch chân"}, {"id": "L12-8T1-08-C08", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Khi tham gia vào quá trình hội nhập kinh tế quốc tế, hình thức hội nhập song phương là quá trình liên kết và hợp tác giữa", "o": ["bốn quốc gia.", "nhiều quốc gia.", "ba quốc gia.", "hai quốc gia."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: Đề 4 đáp án.docx · Phần I câu 8 · khoá: gạch chân"}, {"id": "L12-8T1-08-C09", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Trong quá trình hội nhập kinh tế quốc tế, Việt Nam luôn kiên định quan điểm “ lợi ích hài hòa, rủi ro chia sẻ” điều này thể hiện nguyên tắc nào khi hội nhập kinh tế quốc tế?", "o": ["Bình đẳng giữa các quốc gia, không phân biệt quy mô hay trình độ phát triển.", "Thỏa thuận.", "Công bằng.", "Cùng có lợi."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: Đề 4 đáp án.docx · Phần I câu 9 · khoá: gạch chân"}, {"id": "L12-8T1-08-C10", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Quá trình liên kết, gắn kết giữa các quốc gia, vùng lãnh thổ với nhau thông qua việc tham gia vào các tổ chức kinh tế toàn cầu là một trong những hình thức hội nhập kinh tế quốc tế ở cấp độ", "o": ["khu vực.", "song phương.", "toàn cầu.", "toàn diện."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: Đề 4 đáp án.docx · Phần I câu 10 · khoá: gạch chân"}, {"id": "L12-8T1-08-C11", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Bảo hiểm y tế là hình thức bảo hiểm thuộc lĩnh vực chăm sóc sức khỏe cộng đồng gồm những loại hình nào dưới đây?", "o": ["Vận động và tự nguyện.", "Tự nguyện và cưỡng chế.", "Bắt buộc và vận động.", "Tự nguyện và bắt buộc."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: Đề 4 đáp án.docx · Phần I câu 11 · khoá: gạch chân"}, {"id": "L12-8T1-08-C12", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Một trong những quyền lợi của người tham gia bảo hiểm xã hội là khi hết tuổi lao động, nếu đủ điều kiện họ sẽ được nhận", "o": ["tiền trợ cấp thất nghiệp.", "số tiền đã đóng bảo hiểm.", "tiền lương hưu hàng tháng.", "tiền hỗ trợ khi về già từ quỹ tiết kiệm của gia đình."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: Đề 4 đáp án.docx · Phần I câu 12 · khoá: gạch chân"}, {"id": "L12-8T1-08-C13", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Theo quy định của pháp luật, đối tượng tham gia bảo hiểm thất nghiệp là người lao động v�", "o": ["cơ quan quản lý lao động.", "thân nhân người lao động.", "người sử dụng lao động.", "người đào tạo lao động."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: Đề 4 đáp án.docx · Phần I câu 13 · khoá: gạch chân"}, {"id": "L12-8T1-08-C14", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Trong vấn đề giải quyết việc làm, việc mở rộng và đa dạng hóa các loại hình bảo hiểm sẽ góp phần", "o": ["tăng tỉ lệ thất nghiệp thường xuyên.", "đưa thị trường việc làm bị thu hẹp.", "làm mất cân đối cung cầu lao động trên toàn thị trường việc làm.", "tạo ra ngày càng nhiều việc làm mới."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: Đề 4 đáp án.docx · Phần I câu 14 · khoá: gạch chân"}, {"id": "L12-8T1-08-C15", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Một trong những quyền lợi của người tham gia bảo hiểm thất nghiệp là khi họ bị mất việc nếu đủ điều kiện họ sẽ nhận được", "o": ["lương hưu hàng tháng.", "phí bảo hiểm đã đóng.", "tiền trợ cấp thất nghiệp.", "trợ cấp khám chữa bệnh và hỗ trợ tiền thuốc men hằng tháng."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: Đề 4 đáp án.docx · Phần I câu 15 · khoá: gạch chân"}, {"id": "L12-8T1-08-C16", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Chủ thể của loại hình bảo hiểm thất nghiệp là do", "o": ["Nhà nước thực hiện.", "người dân thực hiện.", "Công đoàn thực hiện", "đoàn thể thực hiện."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: Đề 4 đáp án.docx · Phần I câu 16 · khoá: gạch chân"}, {"id": "L12-8T1-08-C17", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Một trong những mục tiêu của việc thực hiện chính sách trợ giúp xã hội là nhằm giúp các đối tượng yếu thế trong xã hội có thể", "o": ["ổn định cuộc sống.", "mặc cảm và tự ti.", "từ bỏ cuộc sống.", "gia tăng giàu nghèo."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: Đề 4 đáp án.docx · Phần I câu 17 · khoá: gạch chân"}, {"id": "L12-8T1-08-C18", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Việc nhà nước có chính sách hỗ trợ gạo từ nguồn ngân sách nhà nước cho nhân dân các vùng khó khăn dịp Tết nguyên đán là thực hiện chính sách an sinh xã hội nào dưới đây?", "o": ["Chính sách hỗ trợ bảo hiểm.", "Chính sách trợ giúp xã hội.", "Chính sách trợ giúp việc làm.", "Chính sách hỗ trợ thu nhập."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: Đề 4 đáp án.docx · Phần I câu 18 · khoá: gạch chân"}, {"id": "L12-8T1-08-C19", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Nội dung nào dưới đây không phản ánh chính sách dịch vụ xã hội cơ bản trong hệ thống an sinh xã hội ở nước ta?", "o": ["Dịch vụ y tế tối thiếu.", "Công tác văn hóa, thông tin.", "Dịch vụ việc làm tối thiếu.", "Dịch vụ giáo dục tối thiếu."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: Đề 4 đáp án.docx · Phần I câu 19 · khoá: gạch chân"}, {"id": "L12-8T1-08-C20", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Nội dung nào dưới đây không thể hiện nội dung của chính sách an sinh xã hội về bảo hiểm ở nước ta?", "o": ["Trợ cấp tai nạn lao động.", "Trợ cấp xóa nhà tạm.", "Trợ cấp ốm đau.", "Trợ cấp thai sản."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: Đề 4 đáp án.docx · Phần I câu 20 · khoá: gạch chân"}, {"id": "L12-8T1-08-C21", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đọc đoạn thông tin sau:\nBà H là lao động tự do sống trên địa bàn tỉnh Y. Sau một thời gian khám bệnh và điều trị tại bệnh viện K, bà H cầm trên tay hóa đơn, chứng từ thanh toán bảo hiểm y tế với số tiền 80 triệu đồng. Bà đã được thanh toán gần một nửa chi phí điều trị, gần 50 triệu đồng, thuộc đối tượng đồng chi trả 20%. Bà nói: cách đây 5 tháng tôi có mua một tấm thẻ bảo hiểm y tế, nhờ có tấm thẻ này mà tôi không trở thành gánh nặng tài chính của các con khi ốm đau.\nLoại hình bảo hiểm mà bà H tham gia có đặc điểm là", "o": ["bắt buộc.", "được tài trợ.", "được vĩnh viễn.", "tự nguyện."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: Đề 4 đáp án.docx · Phần I câu 21 · khoá: gạch chân"}, {"id": "L12-8T1-08-C22", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Nhờ có tham gia loại hình bảo hiểm đã mang lại lợi ích gì dưới đây cho bà H khi gặp rủi ro về ốm đau?", "o": ["Khám chữa bệnh chất lượng cao tại các bệnh viện tuyến trung ương.", "Giảm gánh nặng tài chính gia đình.", "Được hỗ trợ tiền sau khi ra viện.", "Được khám miễn phí suốt đời."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: Đề 4 đáp án.docx · Phần I câu 22 · khoá: gạch chân"}, {"id": "L12-8T1-08-C23", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đọc đoạn thông tin sau:\nÔng N từng tham gia đóng BHXH bắt buộc, sau đó nghỉ khi mới đóng được 15 năm, chưa đủ điều kiện về số năm đóng BHXH để có chế độ hưu trí (tối thiểu 20 năm). Cuối năm 2022, ông quyết định tham gia BHXH tự nguyện và đóng một lần cho những năm còn thiếu. Ít ngày sau ông nhận tháng lương hưu đầu tiên hơn 1,8 triệu đồng và được cấp thẻ BHYT chăm sóc sức khỏe trọn đời.\nÔng N đã tham gia các loại hình bảo hiểm xã hội nào dưới đây?", "o": ["Tự nguyện và trọn đời.", "Tự nguyện và trả góp.", "Bắt buộc và tự nguyện.", "Bắt buộc và trả góp theo từng năm đóng bảo hiểm."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: Đề 4 đáp án.docx · Phần I câu 23 · khoá: gạch chân"}, {"id": "L12-8T1-08-C24", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đọc đoạn thông tin sau:\nÔng N từng tham gia đóng BHXH bắt buộc, sau đó nghỉ khi mới đóng được 15 năm, chưa đủ điều kiện về số năm đóng BHXH để có chế độ hưu trí (tối thiểu 20 năm). Cuối năm 2022, ông quyết định tham gia BHXH tự nguyện và đóng một lần cho những năm còn thiếu. Ít ngày sau ông nhận tháng lương hưu đầu tiên hơn 1,8 triệu đồng và được cấp thẻ BHYT chăm sóc sức khỏe trọn đời.\nÔng N không là đối tượng của loại hình bảo hiểm nào được đề cập trong thông tin trên.", "o": ["Bảo hiểm xã hội tự nguyện.", "Bảo hiểm y tế.", "Bảo hiểm xã hội bắt buộc.", "Bảo hiểm thất nghiệp."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: Đề 4 đáp án.docx · Phần I câu 24 · khoá: gạch chân"}, {"id": "L12-8T1-08-C25", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "dung_sai", "status": "cho_duyet", "q": "Đọc đoạn thông tin sau và cho biết mỗi ý a, b, c, d là Đúng hay Sai. Nhà nước đã dành 21% ngân sách cho phúc lợi xã hội, là mức cao nhất trong số các nước ASEAN, nhờ đó đã cơ bản thực hiện thành công các mục tiêu, nhiệm vụ đặt ra. Trong bối cảnh đại dịch COVID-19, thông qua chính sách hỗ trợ trực tiếp của Chính phủ và chính sách bảo hiểm xã hội, bảo hiểm thất nghiệp, đã hỗ trợ hơn 14,4 triệu người với tổng kinh phí hơn 33.000 tỷ đồng.", "o": ["Hỗ trợ kinh phí cho người có công là thực hiện chính sách trợ giúp xã hội.", "Tăng trưởng kinh tế đóng vai trò quan trọng trong việc thực hiện các chính sách an sinh xã hội.", "Việt Nam vừa phát triển kinh tế vừa quan tâm thực hiện chính sách an sinh xã hội.", "Ngân sách nhà nước là nguồn lực duy nhất để thực hiện các chính sách an sinh."], "a": [true, true, true, false], "e": "Đáp án: a) Đúng; b) Đúng; c) Đúng; d) Sai.", "nguon": "Đề nguồn: Đề 4 đáp án.docx · Phần II câu 1 · khoá: chữ Đúng/Sai trong ý"}, {"id": "L12-8T1-08-C26", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "dung_sai", "status": "cho_duyet", "q": "Đọc đoạn thông tin sau và cho biết mỗi ý a, b, c, d là Đúng hay Sai. Nhà nước đã ban hành các chính sách về phổ cập giáo dục; các chính sách hỗ trợ giáo dục cho học sinh thuộc hộ nghèo, thuộc diện đối tượng bảo trợ xã hội, dân tộc thiểu số. Đảng và Nhà nước tập trung hoàn thiện hệ thống khám chữa bệnh, hệ thống bảo hiểm y tế, hệ thống y tế dự phòng. Ưu tiên cho trẻ em dưới 6 tuổi, người cao tuổi từ 80 tuổi trở lên, người dân tộc thiểu số, người nghèo và các đối tượng yếu thế.", "o": ["Phát triển hệ thống y tế dự phòng là nội dung của chính sách bảo hiểm xã hội.", "Ưu tiên khám chữa bệnh cho trẻ em dưới 6 tuổi, người cao tuổi từ 80 tuổi thể hiện chính sách trợ giúp xã hội.", "Hoàn thiện khám chữa bệnh để bảo đảm dịch vụ y tế tối thiểu là phù hợp với chính sách an sinh xã hội.", "Phổ cập giáo dục và hỗ trợ giáo dục là một trong những dịch vụ xã hội tối thiểu của an sinh xã hội."], "a": [false, true, true, true], "e": "Đáp án: a) Sai; b) Đúng; c) Đúng; d) Đúng.", "nguon": "Đề nguồn: Đề 4 đáp án.docx · Phần II câu 2 · khoá: chữ Đúng/Sai trong ý"}, {"id": "L12-8T1-08-C27", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "dung_sai", "status": "cho_duyet", "q": "Đọc đoạn thông tin sau và cho biết mỗi ý a, b, c, d là Đúng hay Sai. Đảng và Nhà nước xác định vấn đề bảo đảm nhà ở ổn định cho người dân là một nhiệm vụ xã hội quan trọng. Luật Nhà ở năm 2014 quy định các chính sách hỗ trợ về nhà ở cho một số đối tượng: hộ gia đình nghèo và cận nghèo tại khu vực nông thôn; người thu nhập thấp, hộ nghèo, cận nghèo tại khu vực đô thị; người lao động đang làm việc tại các doanh nghiệp trong và ngoài khu công nghiệp. Nhà nước đã ban hành một số chính sách về đất đai, huy động vốn, vay vốn ưu đãi và loại hình phát triển nhà ở xã hội.", "o": ["Bảo đảm nhà ở ổn định cho người dân là nội dung cơ bản của chính sách trợ giúp xã hội.", "Chính sách bảo hiểm về nhà ở để hỗ trợ người thu nhập thấp vay vốn mua nhà.", "Thực hiện chính sách nhà ở cho người dân là thể hiện chỉ số tiến bộ xã hội.", "Giải quyết vấn đề nhà ở xã hội là trách nhiệm của toàn xã hội."], "a": [true, false, true, true], "e": "Đáp án: a) Đúng; b) Sai; c) Đúng; d) Đúng.", "nguon": "Đề nguồn: Đề 4 đáp án.docx · Phần II câu 3 · khoá: chữ Đúng/Sai trong ý"}, {"id": "L12-8T1-08-C28", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "dung_sai", "status": "cho_duyet", "q": "Đọc đoạn thông tin sau và cho biết mỗi ý a, b, c, d là Đúng hay Sai. Chị D cho biết, trước đây chị làm công nhân đã có 10 năm tham gia BHXH bắt buộc và sau khi nghỉ việc chị không còn được tham gia nữa. Chị chuyển sang bán hàng ăn để mưu sinh. Tính đến nay chị đã đóng BHXH tự nguyện được 5 năm, mỗi lần đều đóng theo quý, mỗi quý hơn 600 nghìn đồng. Không những tham gia BHXH tự nguyện, chị còn tham gia cả BHYT hộ gia đình.", "o": ["Chị D tham gia bảo hiểm bắt buộc 10 năm rồi bỏ không tham gia nữa là hợp lý.", "Lao động tự do nên tham gia BHXH tự nguyện vì hình thức này linh hoạt.", "Chị D được hưởng trợ cấp ốm đau khi mổ u vì đã tham gia BHXH.", "Loại hình bảo hiểm y tế của chị D là bắt buộc đối với mọi gia đình."], "a": [false, true, false, false], "e": "Đáp án: a) Sai; b) Đúng; c) Sai; d) Sai.", "nguon": "Đề nguồn: Đề 4 đáp án.docx · Phần II câu 4 · khoá: chữ Đúng/Sai trong ý"}]}, {"id": "L12-8T1-09", "loai": "khoi", "khoi": 12, "hoc_ki": 1, "bo": "8T1", "ten_bo": "8 tuần học kì I", "so_de": 9, "ten": "Lớp 12 · 8 tuần học kì I · Đề 9", "pham_vi": "Bài 1–4 (đề nguồn «HỌC KÌ 1 › bai_1_4») · file nguồn: Đề 5 đáp án.docx", "thoi_gian": 50, "cau_truc": "24 câu trắc nghiệm + 4 câu đúng/sai (mỗi câu 4 ý)", "status": "cho_duyet", "khoa": {"1 nguồn": 28}, "sua": "", "cau": [{"id": "L12-8T1-09-C01", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Phát biểu nào dưới đây là đúng về hội nhập kinh tế quốc tế?", "o": ["Hội nhập kinh tế quốc tế chỉ cần thiết đối với những quốc gia đang phát triển để thu hẹp khoảng cách tụt hậu.", "Trong hội nhập kinh tế quốc tế, một quốc gia được lợi thì sẽ có quốc gia khác chịu thiệt về kinh tế.", "Hội nhập kinh tế quốc tế tạo ra sự phụ thuộc và mất cân bằng về lợi ích giữa các quốc gia với nhau.", "Hội nhập kinh tế quốc tế có thể diễn ra giữa hai quốc gia với nhau trên cơ sở cùng có lợi về kinh tế."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: Đề 5 đáp án.docx · Phần I câu 1 · khoá: gạch chân"}, {"id": "L12-8T1-09-C02", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đối với hình thức hội nhập kinh tế song phương, việc thực hiện những thỏa thuận và nghĩa vụ đã ký kết được áp dụng cho", "o": ["hai quốc gia ký kết với nhau.", "các nước trong khu vực.", "mọi quốc gia trên thế giới, không phân biệt có ký kết hay không.", "nhiều quốc gia khác nhau."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: Đề 5 đáp án.docx · Phần I câu 2 · khoá: gạch chân"}, {"id": "L12-8T1-09-C03", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Ở cấp độ quốc gia, việc làm nào dưới đây thể hiện sự hội nhập quốc tế?", "o": ["Tài trợ hoạt động khủng bố và các tổ chức vũ trang trái phép.", "Tài trợ tổ chức phi nhân đạo.", "Tham gia sứ mệnh nhân đạo.", "Tham gia hiệp định thương mại."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: Đề 5 đáp án.docx · Phần I câu 3 · khoá: gạch chân"}, {"id": "L12-8T1-09-C04", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Hình thức hợp tác nào dưới đây không phải là biểu hiện của hình thức hội nhập kinh tế quốc tế?", "o": ["Hội nhập bảo tồn văn hóa.", "Hội nhập kinh tế song phương.", "Hội nhập kinh tế toàn cầu.", "Hội nhập kinh tế khu vực."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: Đề 5 đáp án.docx · Phần I câu 4 · khoá: gạch chân"}, {"id": "L12-8T1-09-C05", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Một trong những biểu hiện của hợp tác kinh tế quốc tế là các quốc gia có thể cùng quốc gia khác tham gia ký kết", "o": ["hiệp định chiến tranh và thỏa thuận hòa bình giữa các quốc gia.", "xác định mốc biên giới.", "hiệp định thương mại tự do.", "tuần tra chung trên biển."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: Đề 5 đáp án.docx · Phần I câu 5 · khoá: gạch chân"}, {"id": "L12-8T1-09-C06", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Trong quá trình hội nhập kinh tế quốc tế, các nước tham gia cần tuân thủ nguyên tắc nào dưới đây?", "o": ["Cá lớn nuốt cá bé.", "Nước nhỏ phụ thuộc nước lớn.", "Các bên cùng có lợi.", "Nước nhỏ không được tự quyết."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: Đề 5 đáp án.docx · Phần I câu 6 · khoá: gạch chân"}, {"id": "L12-8T1-09-C07", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Xét về mặt quan hệ dân sự, bảo hiểm là một", "o": ["dịch vụ ngân hàng và tín dụng thương mại cho doanh nghiệp.", "dịch vụ tín dụng.", "dịch vụ tài chính.", "dịch vụ tiền tệ."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: Đề 5 đáp án.docx · Phần I câu 7 · khoá: gạch chân"}, {"id": "L12-8T1-09-C08", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Một trong những đặc điểm của loại hình bảo hiểm thương mại là có", "o": ["tính không hoàn lại.", "tính bắt buộc.", "tính kinh doanh.", "tính rủi ro cao."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: Đề 5 đáp án.docx · Phần I câu 8 · khoá: gạch chân"}, {"id": "L12-8T1-09-C09", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Xét về bản chất thì bảo hiểm xã hội, bảo hiểm y tế, bảo hiểm thất nghiệp và bảo hiểm thương mại đều có điểm chung ở chỗ các loại hình bảo hiểm này đều", "o": ["là một loại hình của dịch vụ tài chính.", "có độ rủi ro cao và không nên tham gia.", "người tham gia bao giờ cũng thua thiệt do phải đóng phí quá cao.", "có tính bắt buộc mọi chủ thể tham gia."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: Đề 5 đáp án.docx · Phần I câu 9 · khoá: gạch chân"}, {"id": "L12-8T1-09-C10", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đối với mỗi cá nhân, khi không may gặp rủi ro, việc tham gia bảo hiểm sẽ giúp các cá nhân", "o": ["được hỗ trợ trọn đời.", "được hoàn trả đầy đủ.", "đổi vận may mắn.", "ổn định tài chính."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: Đề 5 đáp án.docx · Phần I câu 10 · khoá: gạch chân"}, {"id": "L12-8T1-09-C11", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Bạn A học sinh lớp 10 trường THPT X không may bị tai nạn giao thông phải nhập viện điều trị một tháng. Sau khi ra viện, bạn A được cơ quan bảo hiểm thanh toán toàn bộ chi phí điều trị và phẫu thuật theo quy định. Bạn A đã tham gia loại hình bảo hiểm nào dưới đây?", "o": ["Bảo hiểm thất nghiệp.", "Bảo hiểm xã hội.", "Bảo hiểm thương mại.", "Bảo hiểm y tế."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: Đề 5 đáp án.docx · Phần I câu 11 · khoá: gạch chân"}, {"id": "L12-8T1-09-C12", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Loại hình bảo hiểm nào dưới đây nhằm bù đắp một phần thu nhập, hỗ trợ học nghề, duy trì và tìm kiếm việc làm cho người lao động khi bị mất việc làm trên cơ sở đóng góp vào quỹ bảo hiểm theo quy định.", "o": ["Bảo hiểm y tế.", "Bảo hiểm con người.", "Bảo hiểm thất nghiệp.", "Bảo hiểm xã hội bắt buộc và tự nguyện do Nhà nước tổ chức."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: Đề 5 đáp án.docx · Phần I câu 12 · khoá: gạch chân"}, {"id": "L12-8T1-09-C13", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Chính sách trợ giúp xã hội không nhằm thực hiện mục tiêu nào dưới đây?", "o": ["Gia tăng sự phân hóa, bất bình đẳng.", "Giúp người yếu thế ổn định cuộc sống.", "Thực hiện bình đẳng trong xã hội.", "Hỗ trợ người có hoàn cảnh khó khăn."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: Đề 5 đáp án.docx · Phần I câu 13 · khoá: gạch chân"}, {"id": "L12-8T1-09-C14", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Nhà nước có chính sách để hỗ trợ việc đẩy mạnh xuất khẩu lao động là góp phần thực hiện chính sách an sinh xã hội nào dưới đây?", "o": ["Chính sách hỗ trợ thu nhập.", "Chính sách trợ giúp xã hội đối với người nghèo, người yếu thế.", "Chính sách bảo hiểm xã hội.", "Chính sách giải quyết việc làm."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: Đề 5 đáp án.docx · Phần I câu 14 · khoá: gạch chân"}, {"id": "L12-8T1-09-C15", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đối với mỗi quốc gia, chính sách an sinh xã hội có vai trò như thế nào đối với Nhà nước?", "o": ["Thủ đoạn chính trị", "Chính sách tiền tệ", "Phương tiện điều hành.", "Công cụ quản lý."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: Đề 5 đáp án.docx · Phần I câu 15 · khoá: gạch chân"}, {"id": "L12-8T1-09-C16", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Nội dung nào dưới đây không thể hiện chính sách trợ giúp xã hội trong hệ thống chính sách an sinh xã hội ở nước ta?", "o": ["Hỗ trợ về bảo hiểm y tế.", "Hỗ trợ hoạt động tư pháp.", "Hỗ trợ dạy nghề, học nghề.", "Hỗ trợ sinh hoạt hàng tháng."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: Đề 5 đáp án.docx · Phần I câu 16 · khoá: gạch chân"}, {"id": "L12-8T1-09-C17", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Việc nhà nước có chính sách hỗ trợ thường xuyên đối với các đối tượng như trẻ mồ côi, người khuyết tật để giúp họ ổn định cuộc sống thể hiện nội dung của chính sách an sinh xã hội nào dưới đây?", "o": ["Chính sách hỗ trợ giáo dục.", "Chính sách hỗ trợ xã hội.", "Chính sách việc làm, thu nhập.", "Chính sách giảm nghèo."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: Đề 5 đáp án.docx · Phần I câu 17 · khoá: gạch chân"}, {"id": "L12-8T1-09-C18", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Ở nước ta hiện nay, chính sách nào dưới đây là nội dung cơ bản của hệ thống an sinh xã hội?", "o": ["Chính sách gia tăng dân số.", "Chính sách hỗ trợ việc làm.", "Chính sách giáo dục và đào tạo.", "Chính sách khoa học và công nghệ."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: Đề 5 đáp án.docx · Phần I câu 18 · khoá: gạch chân"}, {"id": "L12-8T1-09-C19", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Yếu tố nào dưới đây là chỉ tiêu của phát triển kinh tế?", "o": ["Mức sống bình dân.", "Tiến bộ xã hội.", "Cơ cấu dòng tiền.", "Tăng trưởng dân số."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: Đề 5 đáp án.docx · Phần I câu 19 · khoá: gạch chân"}, {"id": "L12-8T1-09-C20", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Sự gia tăng về quy mô sản lượng của một nền kinh tế trong một thời kỳ nhất định so với thời kỳ gốc là nội dung của khái niệm nào dưới đây?", "o": ["Tăng trưởng xã hội trong nền kinh tế và tiến bộ xã hội.", "Tăng trưởng kinh tế.", "Phát triển kinh tế.", "Hội nhập kinh tế."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: Đề 5 đáp án.docx · Phần I câu 20 · khoá: gạch chân"}, {"id": "L12-8T1-09-C21", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đọc đoạn thông tin sau:\nNăm 2013 bà Nguyễn Thị A giao kết hợp đồng lao động có thời hạn 24 tháng với trường tiểu học E. Từ ngày 01/1/2015 đến ngày 30/6/2015, bà A nghỉ hưởng chế độ thai sản. Ngày 01/7/2015 trường tiểu học E ban hành quyết định nghỉ việc cho bà A, quyết định có hiệu lực kể từ ngày ký.\nTheo quy định của pháp luật, sau thời gian bà A được trường tiểu học E ban hành quyết định nghỉ việc, bà A có quyền được hưởng loại bảo hiểm nào dưới đây?", "o": ["Bảo hiểm thất nghiệp.", "Bảo hiểm dân sự đối với trách nhiệm bồi thường thiệt hại.", "Trợ cấp tai nạn.", "Trợ cấp thai sản."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: Đề 5 đáp án.docx · Phần I câu 21 · khoá: gạch chân"}, {"id": "L12-8T1-09-C22", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Theo quy định của pháp luật, trong thời gian nghỉ chế độ thai sản b� A được hưởng chế độ bảo hiểm nào dưới đây?", "o": ["Trợ cấp nghề nghiệp.", "Bảo hiểm thất nghiệp.", "Chế độ hưu trí.", "Chế độ thai sản."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: Đề 5 đáp án.docx · Phần I câu 22 · khoá: gạch chân"}, {"id": "L12-8T1-09-C23", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đọc đoạn thông tin sau:\nTrong năm 2023 toàn tỉnh M đã giải quyết việc làm mới cho hơn 8.000 lao động; trong 5 năm đã tạo việc làm cho 41.394 lao động, đạt 103% so với kế hoạch. Tỉ lệ thất nghiệp ở khu vực thành thị giảm từ 5,2% năm xuống còn 4,54%. Kết quả giảm nghèo của toàn tỉnh trong 5 năm đã vượt mục tiêu đề ra, giảm từ 38.085 hộ nghèo xuống còn 18.048 hộ nghèo.\nViệc giảm tỷ lệ thất nghiệp ở khu vực thành thị đã phản ánh hiệu quả của chính sách an sinh xã hội nào dưới đây mà tỉnh M đã thực hiện?", "o": ["Chính sách bảo hiểm.", "Chính sách giảm nghèo.", "Chính sách việc làm.", "Chính sách thu nhập."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: Đề 5 đáp án.docx · Phần I câu 23 · khoá: gạch chân"}, {"id": "L12-8T1-09-C24", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Chính sách an sinh xã hội nào dưới đây mà tỉnh M triển khai đã giúp các hộ nghèo từng bước ổn định cuộc sống?", "o": ["Chính sách dịch vụ xã hội.", "Chính sách xóa đói, giảm nghèo.", "Chính sách trợ giúp xã hội.", "Chính sách bảo hiểm xã hội bắt buộc đối với người lao động."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: Đề 5 đáp án.docx · Phần I câu 24 · khoá: gạch chân"}, {"id": "L12-8T1-09-C25", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "dung_sai", "status": "cho_duyet", "q": "Đọc đoạn thông tin sau và cho biết mỗi ý a, b, c, d là Đúng hay Sai. Bà H là lao động tự do sống trên địa bàn tỉnh Y. Sau một thời gian khám bệnh và điều trị tại bệnh viện K, bà H cầm trên tay hóa đơn, chứng từ thanh toán bảo hiểm y tế với số tiền 80 triệu đồng. Bà đã được thanh toán gần một nửa chi phí điều trị, gần 50 triệu đồng, thuộc đối tượng đồng chi trả 20%. Bà nói: cách đây 5 tháng tôi có mua một tấm thẻ bảo hiểm y tế, nhờ có tấm thẻ này mà tôi không trở thành gánh nặng tài chính của các con khi ốm đau.", "o": ["Loại hình bảo hiểm mà bà H mua thẻ thể hiện đặc điểm bảo hiểm tự nguyện.", "Nhờ có thẻ bảo hiểm y tế, bà H được giảm gánh nặng tài chính cho gia đình khi ốm đau.", "Bà H được thanh toán toàn bộ 80 triệu đồng chi phí điều trị.", "Bảo hiểm y tế là loại hình bắt buộc đối với mọi lao động tự do."], "a": [true, true, false, false], "e": "Đáp án: a) Đúng; b) Đúng; c) Sai; d) Sai.", "nguon": "Đề nguồn: Đề 5 đáp án.docx · Phần II câu 1 · khoá: chữ Đúng/Sai trong ý"}, {"id": "L12-8T1-09-C26", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "dung_sai", "status": "cho_duyet", "q": "Đọc đoạn thông tin sau và cho biết mỗi ý a, b, c, d là Đúng hay Sai. Ông N từng tham gia đóng BHXH bắt buộc, sau đó nghỉ khi mới đóng được 15 năm, chưa đủ điều kiện về số năm đóng BHXH để có chế độ hưu trí (tối thiểu 20 năm). Cuối năm 2022, ông quyết định tham gia BHXH tự nguyện và đóng một lần cho những năm còn thiếu. Ít ngày sau ông nhận tháng lương hưu đầu tiên hơn 1,8 triệu đồng và được cấp thẻ BHYT chăm sóc sức khỏe trọn đời.", "o": ["Công dân đóng đủ số năm tham gia bảo hiểm xã hội là sẽ được nhận chế độ hưu trí.", "Ông N cao tuổi nên rút bảo hiểm xã hội một lần sẽ lợi hơn khi đóng tiếp để hưởng hưu trí.", "Ông N chỉ được hưởng chế độ hưu trí và thẻ bảo hiểm y tế để khám bệnh.", "Tham gia bảo hiểm giúp ông N được bảo vệ sức khỏe và yên tâm tài chính khi về già."], "a": [false, false, false, true], "e": "Đáp án: a) Sai; b) Sai; c) Sai; d) Đúng.", "nguon": "Đề nguồn: Đề 5 đáp án.docx · Phần II câu 2 · khoá: chữ Đúng/Sai trong ý"}, {"id": "L12-8T1-09-C27", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "dung_sai", "status": "cho_duyet", "q": "Đọc đoạn thông tin sau và cho biết mỗi ý a, b, c, d là Đúng hay Sai. Bảo đảm nước sạch cho nhân dân là một nhiệm vụ và mục tiêu quan trọng mang tầm quốc gia. Chính phủ đã ban hành Chương trình mục tiêu Quốc gia nước sạch và vệ sinh môi trường nông thôn giai đoạn 2012-2015; Chiến lược quốc gia cấp nước sạch và vệ sinh nông thôn đến năm 2030. Phấn đấu đến năm 2030 có 65% dân số nông thôn được sử dụng nước sạch theo quy chuẩn với số lượng tối thiểu 60 lít/người/ngày.", "o": ["Chương trình nước sạch là nội dung của chính sách việc làm.", "Nước sạch vừa là vấn đề an sinh xã hội vừa là vấn đề chất lượng sống của người dân.", "Chỉ tiêu về nước sạch là chỉ tiêu quan trọng đánh giá tăng trưởng kinh tế.", "Giải quyết vấn đề nước sạch cũng chính là thực hiện tốt quyền con người."], "a": [false, true, false, true], "e": "Đáp án: a) Sai; b) Đúng; c) Sai; d) Đúng.", "nguon": "Đề nguồn: Đề 5 đáp án.docx · Phần II câu 3 · khoá: chữ Đúng/Sai trong ý"}, {"id": "L12-8T1-09-C28", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "dung_sai", "status": "cho_duyet", "q": "Đọc đoạn thông tin sau và cho biết mỗi ý a, b, c, d là Đúng hay Sai. Cơ cấu kinh tế ngành và nội ngành chuyển biến tích cực; tỉ trọng công nghiệp chế biến, chế tạo và ứng dụng công nghệ cao tăng lên. Tỉ trọng lao động nông, lâm nghiệp và thuỷ sản trong tổng số lao động cả nước giảm từ 48,6% năm 2010 xuống còn 34% năm 2020. Tỉ trọng lao động ngành công nghiệp và xây dựng tăng từ 21,7% lên 30,3%. Thu nhập bình quân đầu người tăng 3,1 lần, từ 16,6 triệu đồng năm 2010 lên 51,5 triệu đồng năm 2019.", "o": ["Tỉ trọng lao động nông, lâm nghiệp và thủy sản giảm từ 48,6% năm 2010 xuống 34% năm 2020.", "Thu nhập bình quân đầu người tăng 3,1 lần từ năm 2010 đến năm 2019.", "Tỉ trọng ngành dịch vụ tăng từ 29,7% lên khoảng 35,7% giai đoạn 2010–2020.", "Tỉ trọng lao động ngành công nghiệp và xây dựng giảm từ 21,7% lên 30,3%."], "a": [true, true, true, false], "e": "Đáp án: a) Đúng; b) Đúng; c) Đúng; d) Sai.", "nguon": "Đề nguồn: Đề 5 đáp án.docx · Phần II câu 4 · khoá: chữ Đúng/Sai trong ý"}]}, {"id": "L12-8T1-10", "loai": "khoi", "khoi": 12, "hoc_ki": 1, "bo": "8T1", "ten_bo": "8 tuần học kì I", "so_de": 10, "ten": "Lớp 12 · 8 tuần học kì I · Đề 10", "pham_vi": "Bài 1–4 (đề nguồn «HỌC KÌ 1 › bai_1_4») · file nguồn: Đề 6 đáp án.docx", "thoi_gian": 50, "cau_truc": "24 câu trắc nghiệm + 4 câu đúng/sai (mỗi câu 4 ý)", "status": "cho_duyet", "khoa": {"1 nguồn": 27, "đã tự giải lại": 1}, "sua": "Câu 23 (vai trò chính sách an sinh xã hội đối với người yếu thế): «tạo bình đẳng trong xã hội» (A). Đề 8T1-01 có cùng câu và khoá A; khoá B trong đề này lệch.", "cau": [{"id": "L12-8T1-10-C01", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Trong các quan hệ kinh tế quốc tế, việc tham gia của mỗi quốc gia không được thực hiện ở cấp độ nào dưới đây?", "o": ["Quy chế miễn thị thực.", "Liên minh kinh tế với chính sách thương mại và thuế quan chung.", "Thị trường chung.", "Liên minh thuế quan."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: Đề 6 đáp án.docx · Phần I câu 1 · khoá: gạch chân"}, {"id": "L12-8T1-10-C02", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Hội nhập kinh tế khu vực không được thực hiện giữa các quốc gia có đặc điểm nào dưới đây?", "o": ["Tương đồng về địa lý.", "Đang chiến tranh với nhau.", "Có sự phù hợp về văn hóa.", "Cùng chung mục tiêu phát triển và hợp tác kinh tế lâu dài."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: Đề 6 đáp án.docx · Phần I câu 2 · khoá: gạch chân"}, {"id": "L12-8T1-10-C03", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Khi tham gia vào quá trình hội nhập kinh tế quốc tế song phương, các quốc gia không bắt buộc phải thủ nguyên tắc nào dưới đây?", "o": ["Tôn trọng vị thế của nhau.", "Bình đẳng cùng có lợi.", "Phải sử dụng ngôn ngữ của nhau.", "Tôn trọng độc lập chủ quyền và toàn vẹn lãnh thổ của nhau."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: Đề 6 đáp án.docx · Phần I câu 3 · khoá: gạch chân"}, {"id": "L12-8T1-10-C04", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Về mặt tài chính, khi các doanh nghiệp tham gia các loại hình bảo hiểm sẽ giúp doanh nghiệp được", "o": ["thâu tóm thị trường.", "miễn các loại thuế.", "ổn định và an toàn.", "xuất khẩu ưu đãi."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: Đề 6 đáp án.docx · Phần I câu 4 · khoá: gạch chân"}, {"id": "L12-8T1-10-C05", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Ông M được cơ quan có thẩm quyền ra quyết định nghỉ hưu theo quy định, sau khi hoàn thiện các thủ tục, ông M được nhận chế độ hưu trí hàng tháng. Ông M đã tham gia loại hình bảo hiểm nào dưới đây?", "o": ["Bảo hiểm y tế.", "Bảo hiểm xã hội.", "Bảo hiểm thương mại.", "Bảo hiểm thất nghiệp."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: Đề 6 đáp án.docx · Phần I câu 5 · khoá: gạch chân"}, {"id": "L12-8T1-10-C06", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Loại hình bảo hiểm nào dưới đây thuộc lĩnh vực chăm sóc sức khoẻ cộng đồng do Nhà nước thực hiện; theo đó, người tham gia bảo hiểm sẽ được chi trả một phần hoặc toàn bộ chi phí thăm khám, điều trị, phục hồi sức khoẻ nếu không may xảy ra tai nạn hoặc bệnh tật?", "o": ["Bảo hiểm y tế.", "Bảo hiểm con người.", "Bảo hiểm xã hội", "Bảo hiểm thất nghiệp."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: Đề 6 đáp án.docx · Phần I câu 6 · khoá: gạch chân"}, {"id": "L12-8T1-10-C07", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Nội dung nào dưới đây không thể hiện vai trò của bảo hiểm đối với mỗi cá nhân và gia đình?", "o": ["Ổn định vật chất, tinh thần.", "Chia sẻ khi gặp rủi ro.", "Đảm bảo an toàn tài chính.", "Gia tăng bạo lực giới."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: Đề 6 đáp án.docx · Phần I câu 7 · khoá: gạch chân"}, {"id": "L12-8T1-10-C08", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đối với người tham gia bảo hiểm, một trong những vai trò của bảo hiểm đó là giúp mỗi cá nhân tham gia bảo hiểm nếu không may gặp rủi ro có thể", "o": ["chuyển giao rủi ro cho cơ quan bảo hiểm.", "được mọi người giúp đỡ, hỗ trợ thiệt hại.", "yêu cầu được bồi thường cho bản thân.", "xác định được phần thiệt hại của bản thân."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: Đề 6 đáp án.docx · Phần I câu 8 · khoá: gạch chân"}, {"id": "L12-8T1-10-C09", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Với loại hình bảo hiểm xã hội, người lao động sẽ nhận được quyền lợi bảo hiểm dựa trên cơ sở nào dưới đây?", "o": ["Mức đóng vào quỹ bảo hiểm xã hội.", "Vị thế xã hội và địa vị kinh tế của người lao động lúc tham gia.", "Địa vị xã hội khi tham gia.", "Nhu cầu hưởng bảo hiểm xã hội."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: Đề 6 đáp án.docx · Phần I câu 9 · khoá: gạch chân"}, {"id": "L12-8T1-10-C10", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Theo quy định của pháp luật, với người tham gia loại hình bảo hiểm xã hội trường hợp nào dưới đây người tham gia bảo hiểm không được nhận quyền lợi bảo hiểm?", "o": ["Do hết tuổi lao động theo quy định.", "Do bị sa thải vì vi phạm kỷ luật.", "Ốm đau hoặc tai nạn lao động.", "Thai sản hoặc bệnh nghề nghiệp."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: Đề 6 đáp án.docx · Phần I câu 10 · khoá: gạch chân"}, {"id": "L12-8T1-10-C11", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Cơ sở pháp lý để thực hiện quyền và nghĩa vụ của các bên khi tham gia bảo hiểm thương mại là dựa vào", "o": ["địa vị người tham gia bảo hiểm.", "hậu quả của người được bảo hiểm.", "hợp đồng bảo hiểm giữa hai bên.", "quy mô của công ty bảo hiểm."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: Đề 6 đáp án.docx · Phần I câu 11 · khoá: gạch chân"}, {"id": "L12-8T1-10-C12", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Việc hỗ trợ người dân tham gia bảo hiểm y tế là thể hiện chính sách an sinh xã hội nào dưới đây?", "o": ["Chính sách giảm nghèo.", "Chính sách hỗ trợ giáo dục.", "Chính sách bảo hiểm xã hội.", "Chính sách việc làm, thu nhập."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: Đề 6 đáp án.docx · Phần I câu 12 · khoá: gạch chân"}, {"id": "L12-8T1-10-C13", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đối với đối tượng được hưởng chính sách an sinh xã hội, việc thực hiện tốt chính sách an sinh xã hội đem lại lợi ích nào dưới đây?", "o": ["Hưởng thu nhập vô điều kiện", "Được hoàn trả lại lợi ích đã mất.", "Khắc phục và giảm thiếu rủi ro.", "Được hỗ trợ miễn phí trọn đời."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: Đề 6 đáp án.docx · Phần I câu 13 · khoá: gạch chân"}, {"id": "L12-8T1-10-C14", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Yếu tố nào dưới đây là chỉ tiêu của phát triển kinh tế?", "o": ["Mức sống bình dân.", "Tiến bộ xã hội.", "Cơ cấu dòng tiền.", "Tăng trưởng dân số."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: Đề 6 đáp án.docx · Phần I câu 14 · khoá: gạch chân"}, {"id": "L12-8T1-10-C15", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đối với một quốc gia tăng trưởng và phát triển kinh tế có vai trò quan trọng, là điều kiện cần thiết để", "o": ["thúc đẩy tỷ lệ thất nghiệp.", "gia tăng tỷ lệ lạm phát và làm giảm sức mua của đồng tiền.", "thúc đẩy phân hóa giàu nghèo.", "khắc phục tình trạng đói nghèo."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: Đề 6 đáp án.docx · Phần I câu 15 · khoá: gạch chân"}, {"id": "L12-8T1-10-C16", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Phát biểu nào dưới đây là đúng về chỉ tiêu tăng trưởng kinh tế?", "o": ["Mức tăng chỉ số bất bình đẳng trong phân phối thu nhập.", "Mức tăng tổng thu nhập quốc dân trong một thời kỳ nhất định.", "Mức tăng dân số của một quốc gia trong một thời kỳ nhất định.", "Mức tăng thu nhập của từng cá nhân trong một thời kỳ nhất định."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: Đề 6 đáp án.docx · Phần I câu 16 · khoá: gạch chân"}, {"id": "L12-8T1-10-C17", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Sự phát triển nào dưới đây phản ánh sự chuyển biến tổng hợp của nền kinh tế cả về số lượng và chất lượng?", "o": ["Phát triển kinh tế.", "Tăng trưởng kinh tế.", "Tỷ lệ lạm phát.", "Tỷ lệ thất nghiệp."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: Đề 6 đáp án.docx · Phần I câu 17 · khoá: gạch chân"}, {"id": "L12-8T1-10-C18", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đối với mỗi quốc gia, hình thức hội nhập sâu rộng nhất, gắn kết với nhiều quốc gia, tổ chức, khu vực trên thế giới là hình thức nào dưới đây?", "o": ["Hội nhập liên minh.", "Hội nhập song phương.", "Hội nhập khu vực.", "Hội nhập toàn cầu."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: Đề 6 đáp án.docx · Phần I câu 18 · khoá: gạch chân"}, {"id": "L12-8T1-10-C19", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Quá trình liên kết, hợp tác giữa các quốc gia trong khu vực trên cơ sở tương đồng về địa lý, văn hóa, xã hội là một trong những hình thức hội nhập kinh tế quốc tế ở cấp độ", "o": ["hội nhập kinh tế toàn cầu.", "hội nhập kinh tế song phương.", "hội nhập kinh tế toàn diện.", "hội nhập kinh tế khu vực."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: Đề 6 đáp án.docx · Phần I câu 19 · khoá: gạch chân"}, {"id": "L12-8T1-10-C20", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đối với mỗi quốc gia, an sinh xã hội là một trong những tiêu chí đánh giá sự", "o": ["bất công xã hội.", "vi phạm dân quyền.", "phát triển kinh tế.", "tiến bộ xã hội."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: Đề 6 đáp án.docx · Phần I câu 20 · khoá: gạch chân"}, {"id": "L12-8T1-10-C21", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đọc đoạn thông tin sau:\nHệ thống bảo hiểm xã hội được quan tâm phát triển, nhằm chia sẻ rủi ro và trợ giúp thiết thực cho những người tham gia. Số người tham gia bảo hiểm bắt buộc tăng nhanh, từ 4,8 triệu (năm 2001) lên 9,7 triệu (năm 2011). Kinh phí trợ giúp thường xuyên từ ngân sách nhà nước tăng từ 113 tỉ đồng cho hơn 180 nghìn người (năm 2001) lên 4.500 tỉ đồng cho hơn 1,6 triệu người (năm 2010).\nViệc nhà nước triển khai chính sách bảo hiểm xã hội và chương trình xóa đói giảm nghèo là thực hiện chỉ tiêu nào dưới đây của phát triển kinh tế?", "o": ["Chỉ số tiến bộ xã hội.", "Tổng thu nhập quốc dân.", "Tổng sản phẩm quốc dân.", "Thu nhập theo đầu người."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: Đề 6 đáp án.docx · Phần I câu 21 · khoá: gạch chân"}, {"id": "L12-8T1-10-C22", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Hệ thống bảo hiểm là một trong những trụ cột của chính sách an sinh xã hội nào dưới đây?", "o": ["Chính sách việc làm.", "Chính sách thu nhập.", "Chính sách giảm nghèo.", "Chính sách bảo hiểm."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: Đề 6 đáp án.docx · Phần I câu 22 · khoá: gạch chân"}, {"id": "L12-8T1-10-C23", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đọc đoạn thông tin sau:\nTheo thống kê, hiện nước ta có khoảng hơn 20% dân số là những đối tượng yếu thế trong xã hội, trong đó khoảng trên 12 triệu người cao tuổi, gần 7 triệu người khuyết tật, 2 triệu trẻ em có hoàn cảnh đặc biệt, khoảng 2 triệu lượt hộ gia đình cần được trợ giúp đột xuất hàng năm. Các đối tượng này cần được sự trợ giúp của Nhà nước và xã hội.\nViệc thực hiện tốt các chính sách an sinh xã hội đối với các đối tượng là người yếu thế trong xã hội có vai trò nào dưới đây?", "o": ["Tạo bình đẳng trong xã hội.", "Giúp họ bớt tự ti, mặc cảm.", "Tạo gánh nặng cho xã hội.", "Gia tăng khoảng cách giàu nghèo."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: Đề 6 đáp án.docx · Phần I câu 23 · khoá: ĐÃ TỰ GIẢI LẠI (đối chiếu SGK)"}, {"id": "L12-8T1-10-C24", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Nội dung nào dưới đây không góp phần vào việc hỗ trợ, trợ giúp các lực lượng yếu thế trong xã hội với hệ thống chính sách an sinh xã hội của nước ta?", "o": ["Hỗ trợ về y tế và bảo hiểm.", "Ngăn cản họ tiếp cận dịch vụ xã hội.", "Xây dựng trung tâm bảo trợ xã hội.", "Trợ cấp kinh phí hàng tháng và hỗ trợ dạy nghề cho đối tượng yếu thế."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: Đề 6 đáp án.docx · Phần I câu 24 · khoá: gạch chân"}, {"id": "L12-8T1-10-C25", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "dung_sai", "status": "cho_duyet", "q": "Đọc đoạn thông tin sau và cho biết mỗi ý a, b, c, d là Đúng hay Sai. Kể từ khi chính thức gia nhập WTO, Việt Nam đã ghi nhận những thành tựu về phát triển kinh tế. Việt Nam trở thành nền kinh tế có độ mở cao, tới 200% GDP và cải thiện cán cân thương mại hàng hóa, chuyển từ nhập siêu sang xuất siêu trong giai đoạn 2016 - 2020. Năm 2022, cán cân thương mại xuất siêu đạt 12,4 tỷ USD, là năm thứ 7 liên tiếp cán cân thương mại hàng hóa ở mức thặng dư.", "o": ["Việt Nam có độ mở cao tới 200% GDP nhờ gia nhập WTO.", "Hội nhập WTO khiến cán cân thương mại Việt Nam chuyển từ xuất siêu sang nhập siêu.", "Năm 2022 xuất siêu 12,4 tỷ USD, là năm thứ 7 liên tiếp cán cân thương mại thặng dư.", "Việt Nam là một trong 20 nền thương mại lớn nhất thế giới."], "a": [true, false, true, true], "e": "Đáp án: a) Đúng; b) Sai; c) Đúng; d) Đúng.", "nguon": "Đề nguồn: Đề 6 đáp án.docx · Phần II câu 1 · khoá: chữ Đúng/Sai trong ý"}, {"id": "L12-8T1-10-C26", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "dung_sai", "status": "cho_duyet", "q": "Đọc đoạn thông tin sau và cho biết mỗi ý a, b, c, d là Đúng hay Sai. Trong năm 2023 toàn tỉnh M đã giải quyết việc làm mới cho hơn 8.000 lao động; trong 5 năm đã tạo việc làm cho 41.394 lao động, đạt 103% so với kế hoạch. Tỉ lệ thất nghiệp ở khu vực thành thị giảm từ 5,2% năm xuống còn 4,54%. Kết quả giảm nghèo của toàn tỉnh trong 5 năm đã vượt mục tiêu đề ra, giảm từ 38.085 hộ nghèo xuống còn 18.048 hộ nghèo.", "o": ["Tỉ lệ thất nghiệp thành thị giảm từ 5,2% xuống 4,54% là hiệu quả của chính sách việc làm.", "Số hộ nghèo của tỉnh M giảm hơn 25.000 hộ trong 5 năm.", "Chính sách giảm nghèo của tỉnh M làm gia tăng phân hóa giàu nghèo.", "Tỉ lệ hộ nghèo trước khi thực hiện chương trình là 28,4% số hộ."], "a": [true, false, false, true], "e": "Đáp án: a) Đúng; b) Sai; c) Sai; d) Đúng.", "nguon": "Đề nguồn: Đề 6 đáp án.docx · Phần II câu 2 · khoá: chữ Đúng/Sai trong ý"}, {"id": "L12-8T1-10-C27", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "dung_sai", "status": "cho_duyet", "q": "Đọc đoạn thông tin sau và cho biết mỗi ý a, b, c, d là Đúng hay Sai. Về cơ cấu nền kinh tế năm 2023, khu vực nông, lâm nghiệp và thủy sản chiếm tỷ trọng 11,96%; khu vực công nghiệp và xây dựng chiếm 37,12%; khu vực dịch vụ chiếm 42,54%. GDP bình quân đầu người năm 2023 ước đạt 101,9 triệu đồng/người, tương đương 4.284,5 USD, tăng 160 USD so với năm 2022. Năng suất lao động theo giá so sánh tăng 3,65% do trình độ của người lao động được cải thiện.", "o": ["Khu vực dịch vụ chiếm 42,54%, lớn nhất trong ba khu vực kinh tế năm 2023.", "Khu vực nông, lâm nghiệp và thủy sản chiếm trên 20% GDP năm 2023.", "Năng suất lao động hiện hành năm 2023 tăng 274 USD so với năm 2022.", "GDP bình quân đầu người năm 2022 là 4.384,5 USD."], "a": [true, false, true, false], "e": "Đáp án: a) Đúng; b) Sai; c) Đúng; d) Sai.", "nguon": "Đề nguồn: Đề 6 đáp án.docx · Phần II câu 3 · khoá: chữ Đúng/Sai trong ý"}, {"id": "L12-8T1-10-C28", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "dung_sai", "status": "cho_duyet", "q": "Đọc đoạn thông tin sau và cho biết mỗi ý a, b, c, d là Đúng hay Sai. Năm 2013 bà Nguyễn Thị A giao kết hợp đồng lao động có thời hạn 24 tháng với trường tiểu học E. Từ ngày 01/1/2015 đến ngày 30/6/2015, bà A nghỉ hưởng chế độ thai sản. Ngày 01/7/2015 trường tiểu học E ban hành quyết định nghỉ việc cho bà A, quyết định có hiệu lực kể từ ngày ký.", "o": ["Bà A nhận trợ cấp thất nghiệp ngay sau khi nghỉ việc theo quyết định.", "Bà A được nghỉ thai sản từ ngày 01/01/2015 đến ngày 30/6/2015.", "Bà A được hưởng chế độ hưu trí ngay sau khi nghỉ việc.", "Quyết định nghỉ việc có hiệu lực từ ngày ký."], "a": [false, true, false, true], "e": "Đáp án: a) Sai; b) Đúng; c) Sai; d) Đúng.", "nguon": "Đề nguồn: Đề 6 đáp án.docx · Phần II câu 4 · khoá: chữ Đúng/Sai trong ý"}]}, {"id": "L12-HK1-01", "loai": "khoi", "khoi": 12, "hoc_ki": 1, "bo": "HK1", "ten_bo": "học kì I", "so_de": 1, "ten": "Lớp 12 · học kì I · Đề 1", "pham_vi": "Tổng hợp Bài 1–7 (đề nguồn «HỌC KÌ 1 › tong_hop_1_7») · file nguồn: Đề 1 đáp án.docx", "thoi_gian": 50, "cau_truc": "24 câu trắc nghiệm + 4 câu đúng/sai (mỗi câu 4 ý)", "status": "cho_duyet", "khoa": {"1 nguồn": 28}, "sua": "", "cau": [{"id": "L12-HK1-01-C01", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Dùng để biểu thị thu nhập của nền kinh tế trong một thời kỳ nhất định được tính bằng tổng thu nhập từ hàng hóa, dịch vụ cuối cùng do công dân của quốc gia đó tạo ra trong một năm là", "o": ["tổng thu nhập quốc nội (GDP).", "tổng thu nhập quốc dân trên đầu người.", "tổng thu nhập quốc nội trên đầu người.", "tổng thu nhập quốc dân (GNI)."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: Đề 1 đáp án.docx · Phần I câu 1 · khoá: gạch chân"}, {"id": "L12-HK1-01-C02", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Tăng trưởng kinh tế được biểu hiện ở nội dung nào dưới đây?", "o": ["Tập trung đến sự tiến bộ về phân phối thu nhập.", "Đảm bảo phát triển bền vững về môi trường.", "Sự gia tăng quy mô sản lượng của nền kinh tế.", "Chú trọng vào cải thiện chất lượng cuộc sống."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: Đề 1 đáp án.docx · Phần I câu 2 · khoá: gạch chân"}, {"id": "L12-HK1-01-C03", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đối với mỗi quốc gia, phát triển kinh tế thể hiện ở nội dung nào dưới đây?", "o": ["Chuyển dịch vùng sản xuất.", "Chuyển dịch cơ cấu ngành.", "Chuyển dịch việc phân phối.", "Chuyển đổi mô hình tiền tệ."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: Đề 1 đáp án.docx · Phần I câu 3 · khoá: gạch chân"}, {"id": "L12-HK1-01-C04", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Quá trình tăng trưởng kinh tế gắn liền với sự chuyển dịch cơ cấu kinh tế và đảm bảo tiến bộ xã hội là nội dung của khái niệm nào dưới đây?", "o": ["Phát triển kinh tế.", "Tăng trưởng kinh tế.", "Hội nhập kinh tế.", "Kinh tế đối ngoại."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: Đề 1 đáp án.docx · Phần I câu 4 · khoá: gạch chân"}, {"id": "L12-HK1-01-C05", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Giá trị bằng tiền của tất cả các hàng hóa và dịch vụ cuối cùng được sản xuất ra trên lãnh thổ một nước trong thời gian nhất định được gọi là", "o": ["tổng thu nhập quốc dân (GNI).", "tổng thu nhập quốc nội (GDP).", "tổng thu nhập quốc nội trên đầu người.", "tổng thu nhập quốc dân trên đầu người."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: Đề 1 đáp án.docx · Phần I câu 5 · khoá: gạch chân"}, {"id": "L12-HK1-01-C06", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đối với mỗi quốc gia, vai trò của tăng trưởng và phát triển kinh tế thể hiện ở việc, thông qua tăng trưởng và phát triển kinh tế sẽ góp phần", "o": ["tăng tỷ lệ đói nghèo đa chiều.", "gia tăng phân hóa giàu nghèo giữa các vùng và giữa các tầng lớp dân cư trong xã hội.", "giải quyết tốt vấn đề việc làm.", "gia tăng lệ thuộc vào thế giới."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: Đề 1 đáp án.docx · Phần I câu 6 · khoá: gạch chân"}, {"id": "L12-HK1-01-C07", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Tăng trưởng và phát triển kinh tế không có vai trò nào dưới đây?", "o": ["Thực hiện phân phối thu nhập công bằng giữa các tầng lớp dân cư trong xã hội.", "Nâng cao mức sống người dân.", "Gia tăng khoảng cách giàu nghèo.", "Thu hẹp khoảng cách các vùng."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: Đề 1 đáp án.docx · Phần I câu 7 · khoá: gạch chân"}, {"id": "L12-HK1-01-C08", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Trong mối quan hệ giữa tăng trưởng kinh tế với phát triển kinh tế thì tăng trưởng kinh tế không đóng vai trò nào dưới đây đối với phát triển kinh tế?", "o": ["Là nội dung của phát triển bền vững.", "Là động lực của phát triển xã hội.", "Là điều kiện cần thiết để phát triển bền vững.", "Là nhân tố bên ngoài của phát triển bền vững."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: Đề 1 đáp án.docx · Phần I câu 8 · khoá: gạch chân"}, {"id": "L12-HK1-01-C09", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đối với mỗi quốc gia, phát triển kinh tế không thể hiện ở chỉ tiêu nào dưới đây?", "o": ["Chỉ tiêu về thu nhập quốc dân.", "Chỉ tiêu về thu thuế toàn cầu.", "Chỉ tiêu về thu nhập quốc nội.", "Chỉ tiêu về tăng trưởng kinh tế."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: Đề 1 đáp án.docx · Phần I câu 9 · khoá: gạch chân"}, {"id": "L12-HK1-01-C10", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Từ ngày 11/1/2007, Việt Nam chính thức trở thành thành viên thứ 150 của Tổ chức Thương mại thế giới (WTO). Việc gia nhập WTO là biểu hiện của hình thức hội nhập kinh tế quốc tế nào dưới đây?", "o": ["Song phương.", "Khu vực.", "Toàn cầu.", "Toàn quốc."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: Đề 1 đáp án.docx · Phần I câu 10 · khoá: gạch chân"}, {"id": "L12-HK1-01-C11", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Việc các chủ thể kinh tế xác định các vấn đề như kinh doanh mặt hàng gì, đối tượng khách hàng là ai, họ có nhu cầu gì là thực hiện nội dung nào dưới đây của việc lập kế hoạch kinh doanh?", "o": ["Xác định mục tiêu kinh doanh.", "Xác định chiến lược kinh doanh.", "Xác định ý tưởng kinh doanh.", "Xác định điều kiện thực hiện."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: Đề 1 đáp án.docx · Phần I câu 11 · khoá: gạch chân"}, {"id": "L12-HK1-01-C12", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Để quá trình kinh doanh diễn ra hiệu quả, kế hoạch kinh doanh của các chủ thể cần xác định được", "o": ["số thuế phải đóng.", "ý tưởng kinh doanh.", "số tiền sẽ thu lợi.", "thời gian thành công."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: Đề 1 đáp án.docx · Phần I câu 12 · khoá: gạch chân"}, {"id": "L12-HK1-01-C13", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Khi các chủ thể đặt ra những kế hoạch và mục tiêu cụ thể sẽ đạt được khi tiến hành kinh doanh là đã thực hiện nội dung nào dưới đây của lập kế hoạch kinh doanh?", "o": ["Xác định điều kiện thực hiện.", "Xác định ý tưởng kinh doanh.", "Xác định chiến lược kinh doanh.", "Xác định mục tiêu kinh doanh."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: Đề 1 đáp án.docx · Phần I câu 13 · khoá: gạch chân"}, {"id": "L12-HK1-01-C14", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Bước khởi đầu trong việc lập kế hoạch kinh doanh là các chủ thể phải xác định được", "o": ["ý tưởng kinh doanh.", "chiến lược kinh doanh.", "các rủi ro gặp phải.", "mục tiêu kinh doanh."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: Đề 1 đáp án.docx · Phần I câu 14 · khoá: gạch chân"}, {"id": "L12-HK1-01-C15", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đối với doanh nghiệp, nội dung nào dưới đây thể hiện ý nghĩa của việc thực hiện trách nhiệm xã hội của doanh nghiệp?", "o": ["Tăng lợi thế và khả năng cạnh tranh.", "Góp phần bảo vệ môi trường sống và giảm thiểu ô nhiễm do hoạt động sản xuất gây ra.", "Giúp ổn định cuộc sống cộng đồng.", "Hỗ trợ cộng đồng vượt qua khó khăn"], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: Đề 1 đáp án.docx · Phần I câu 15 · khoá: gạch chân"}, {"id": "L12-HK1-01-C16", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Theo quy định của pháp luật, khi tiến hành kinh doanh, mọi doanh nghiệp đều phải thực hiện nghĩa vụ tuân thủ pháp luật về môi trường là đã thực hiện trách nhiệm xã hội của doanh nghiệp ở hình thức nào dưới đây?", "o": ["Trách nhiệm kinh tế.", "Trách nhiệm pháp lý.", "Trách nhiệm kinh doanh.", "Trách nhiệm từ thiện."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: Đề 1 đáp án.docx · Phần I câu 16 · khoá: gạch chân"}, {"id": "L12-HK1-01-C17", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Tạo việc làm, thu nhập và cơ hội phát triển cho người lao động, cung ứng nhiều sản phẩm có chất lượng cho người tiêu dùng là thể hiện hình thức trách nhiệm xã hội nào của doanh nghiệp?", "o": ["Đạo đức.", "Nhân văn.", "Kinh tế.", "Pháp lý."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: Đề 1 đáp án.docx · Phần I câu 17 · khoá: gạch chân"}, {"id": "L12-HK1-01-C18", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Việc doanh doanh thực hiện tốt những chính sách và việc làm cụ thể nhằm mang lại ảnh hưởng tích cực đến xã hội đóng góp cho các mục tiêu xã hội và sự phát triển bền vững của đất nước là thể hiện nội dung nào dưới đây của doanh nghiệp?", "o": ["Trách nhiệm tiêu dùng.", "Trách nhiệm sản xuất.", "Trách nhiệm xã hội.", "Trách nhiệm phân phối."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: Đề 1 đáp án.docx · Phần I câu 18 · khoá: gạch chân"}, {"id": "L12-HK1-01-C19", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Thực hiện tốt trách nhiệm xã hội sẽ đem lại lợi ích nào dưới đây đối với doanh nghiệp?", "o": ["Xây dựng thương hiệu tích cực.", "Giảm khả năng cạnh tranh và làm suy giảm uy tín trên thị trường.", "Được nhà nước hỗ trợ thuế.", "Thúc đẩy nguy cơ phá sản."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: Đề 1 đáp án.docx · Phần I câu 19 · khoá: gạch chân"}, {"id": "L12-HK1-01-C20", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Trong quá trình sản xuất kinh doanh, giám đốc công ty M luôn luôn chỉ đạo nhân viên phải không ngừng cải tiến kỹ thuật, hợp lý hóa sản xuất để tạo ra những sản phẩm chất lượng, an toàn là đã góp phần thực hiện trách nhiệm xã hội của doanh nghiệp ở hình thức nào dưới đây?", "o": ["Trách nhiệm pháp lý.", "Trách nhiệm đạo đức.", "Trách nhiệm kinh tế.", "Trách nhiệm nhân văn."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: Đề 1 đáp án.docx · Phần I câu 20 · khoá: gạch chân"}, {"id": "L12-HK1-01-C21", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đọc đoạn thông tin sau:\nTính chung thời kì thực hiện Chiến lược phát triển kinh tế xã hội 10 năm (2011 - 2020), tăng trưởng GDP của Việt Nam đạt khoảng 5,9%/năm, thuộc nhóm các nước tăng trưởng cao trong khu vực. Quy mô GDP tăng gấp 2,4 lần, từ 116 tỉ USD năm 2010 lên 268,4 tỉ USD vào năm 2020. GDP bình quân đầu người tăng từ 1.331 USD năm 2010 lên khoảng 2.750 USD năm 2020. Tỉ lệ hộ nghèo cả nước giảm nhanh, từ 14,2% năm 2010 xuống còn 7% năm 2015 (theo chuẩn nghèo giai đoạn 2011 - 2015) và giảm từ 9,2% năm 2016 xuống dưới 3% vào năm 2020 (theo chuẩn nghèo đa chiều). Cơ sở hạ tầng thiết yếu ở các huyện nghèo, xã nghèo, vùng đồng bào dân tộc thiểu số được tăng cường. Thực hiện nhiều giải pháp tạo việc làm, nâng cao thu nhập cho người lao động.\nNội dung nào dưới đây không phải là chỉ tiêu cơ bản để đánh giá sự tăng trưởng và phát triển kinh tế trong thông tin trên?", "o": ["Thu nhập bình quân theo GDP.", "Tốc độ tăng dân số.", "Tốc độ tăng GDP.", "Tỷ lệ hộ nghèo và thu nhập."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: Đề 1 đáp án.docx · Phần I câu 21 · khoá: gạch chân"}, {"id": "L12-HK1-01-C22", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đọc đoạn thông tin sau:\nTính chung thời kì thực hiện Chiến lược phát triển kinh tế xã hội 10 năm (2011 - 2020), tăng trưởng GDP của Việt Nam đạt khoảng 5,9%/năm, thuộc nhóm các nước tăng trưởng cao trong khu vực. Quy mô GDP tăng gấp 2,4 lần, từ 116 tỉ USD năm 2010 lên 268,4 tỉ USD vào năm 2020. GDP bình quân đầu người tăng từ 1.331 USD năm 2010 lên khoảng 2.750 USD năm 2020. Tỉ lệ hộ nghèo cả nước giảm nhanh, từ 14,2% năm 2010 xuống còn 7% năm 2015 (theo chuẩn nghèo giai đoạn 2011 - 2015) và giảm từ 9,2% năm 2016 xuống dưới 3% vào năm 2020 (theo chuẩn nghèo đa chiều). Cơ sở hạ tầng thiết yếu ở các huyện nghèo, xã nghèo, vùng đồng bào dân tộc thiểu số được tăng cường. Thực hiện nhiều giải pháp tạo việc làm, nâng cao thu nhập cho người lao động.\nYếu tố nào được đề cập trong thông tin trên là nhân tố quyết định việc thực hiện các chỉ tiêu phát triển kinh tế về mặt xã hội?", "o": ["Tăng trưởng dân số.", "Tốc độ tăng lạm phát.", "Tăng trưởng việc làm.", "Tăng trưởng kinh tế."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: Đề 1 đáp án.docx · Phần I câu 22 · khoá: gạch chân"}, {"id": "L12-HK1-01-C23", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đọc đoạn thông tin sau:\nĐể vận hành quán cà phê, anh H xác định ngoài chủ quán có 8 nhân viên; Chủ quán: người trực tiếp quản lí và điều hành 24/7; Tiếp tân: thu tiền và in hoá đơn; Đầu bếp: pha chế nước uống và chế biến món ăn. Quán hoạt động từ 6 giờ đến 23 giờ nên đội ngũ được chia thành hai ca, mỗi ca 4 người.\nThông tin trên đề cập đến yếu tố nào dưới đây khi tiến hành đánh giá các điều kiện thực hiện hoạt động kinh doanh?", "o": ["Thị trường.", "Khách hàng.", "Sản phẩm.", "Nhân sự."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: Đề 1 đáp án.docx · Phần I câu 23 · khoá: gạch chân"}, {"id": "L12-HK1-01-C24", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Anh H đã thực hiện nội dung nào dưới đây của lập kế hoạch kinh doanh?", "o": ["Xác định chiến lược kinh doanh.", "Phân tích các điều kiện kinh doanh.", "Xác định mục tiêu kinh doanh.", "Đánh giá các yếu tố rủi ro gặp phải."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: Đề 1 đáp án.docx · Phần I câu 24 · khoá: gạch chân"}, {"id": "L12-HK1-01-C25", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "dung_sai", "status": "cho_duyet", "q": "Đọc đoạn thông tin sau và cho biết mỗi ý a, b, c, d là Đúng hay Sai. Theo Tổng cục Thống kê năm 2022, tổng tỷ lệ nghèo đa chiều cả nước là 9,35%, trong đó tỷ lệ hộ nghèo là 5,2% và tỷ lệ hộ cận nghèo là 4,15%. Theo báo cáo, Chỉ số phát triển con người (HDI) của Việt Nam là 0,703 vào năm 2021, tăng hai bậc, lên vị trí 115/191 quốc gia, thuộc nhóm trung bình cao của thế giới.", "o": ["Tổng tỷ lệ nghèo đa chiều bằng tổng tỷ lệ hộ nghèo và hộ cận nghèo.", "Việt Nam đứng thứ 115/191 về HDI, thuộc nhóm phát triển con người cao.", "Tăng trưởng kinh tế cao tạo tiền đề vật chất để thực hiện các mục tiêu về con người.", "Thực hiện nền kinh tế xanh, kinh tế tuần hoàn là mục tiêu của tăng trưởng kinh tế."], "a": [true, false, true, false], "e": "Đáp án: a) Đúng; b) Sai; c) Đúng; d) Sai.", "nguon": "Đề nguồn: Đề 1 đáp án.docx · Phần II câu 1 · khoá: chữ Đúng/Sai trong ý"}, {"id": "L12-HK1-01-C26", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "dung_sai", "status": "cho_duyet", "q": "Đọc đoạn thông tin sau và cho biết mỗi ý a, b, c, d là Đúng hay Sai. Vị thế của Việt Nam trên thế giới đã được củng cố toàn diện trong giai đoạn 2011 - 2022. Đến năm 2020, Việt Nam có 30 đối tác chiến lược và đối tác chiến lược toàn diện; có quan hệ ngoại giao với 189/193 nước, có quan hệ kinh tế với 160 nước và 70 vùng lãnh thổ. Đến năm 2022, tổng số quan hệ kinh tế - thương mại của Việt Nam đã nâng lên thành 230 nước và vùng lãnh thổ.", "o": ["Thiết lập quan hệ đối tác chiến lược là hội nhập kinh tế ở cấp độ khu vực.", "Hội nhập kinh tế góp phần thúc đẩy tăng trưởng GDP vì xuất khẩu hàng hóa được đẩy mạnh.", "Nước đang phát triển khi hội nhập phải chấp nhận từ bỏ lợi ích của mình.", "Hội nhập kinh tế quốc tế giúp hàng hóa Việt Nam dễ dàng thâm nhập thị trường thế giới."], "a": [false, true, false, true], "e": "Đáp án: a) Sai; b) Đúng; c) Sai; d) Đúng.", "nguon": "Đề nguồn: Đề 1 đáp án.docx · Phần II câu 2 · khoá: chữ Đúng/Sai trong ý"}, {"id": "L12-HK1-01-C27", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "dung_sai", "status": "cho_duyet", "q": "Đọc đoạn thông tin sau và cho biết mỗi ý a, b, c, d là Đúng hay Sai. Sau khi tốt nghiệp đại học ngành công nghệ sinh học, với lợi thế là nhà gần các trường đại học, lại có diện tích đất lớn, chị D quyết định lập nghiệp bằng con đường kinh doanh sản phẩm cây cảnh mini với mong muốn sau hai năm sẽ thành lập một doanh nghiệp phân phối các sản phẩm này. Đây là lĩnh vực kinh doanh không đòi hỏi vốn lớn, trong khi thị trường là các bạn sinh viên có nhu cầu khá cao. Do thời gian đầu chưa có nhiều kinh nghiệm, sản phẩm nhiều cây gặp sâu bệnh chết. Từ thực tế kinh doanh, chị quyết định mở rộng sản xuất và đầu tư thêm nhiều cửa hàng mới.", "o": ["Chị D xác định ý tưởng kinh doanh dựa trên lợi thế nội tại như kiến thức công nghệ sinh học và mặt bằng gần trường.", "Mục tiêu sau hai năm thành lập doanh nghiệp là không hợp lý.", "Chị D không phân tích điều kiện thị trường và tài chính khi thực hiện ý tưởng kinh doanh.", "Lập kế hoạch kinh doanh giúp chị D phát huy tốt các lợi thế của mình."], "a": [true, false, false, true], "e": "Đáp án: a) Đúng; b) Sai; c) Sai; d) Đúng.", "nguon": "Đề nguồn: Đề 1 đáp án.docx · Phần II câu 3 · khoá: chữ Đúng/Sai trong ý"}, {"id": "L12-HK1-01-C28", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "dung_sai", "status": "cho_duyet", "q": "Đọc đoạn thông tin sau và cho biết mỗi ý a, b, c, d là Đúng hay Sai. Sau khi cưới nhau, anh D và chị H dự định sau 3 năm sẽ mua nhà và ra ở riêng. Vợ chồng anh chị đồng thuận thực hiện kế hoạch quản lí thu, chi bằng sổ theo dõi hằng tháng. Theo đó, vợ chồng chị sẽ dành 50% tổng thu nhập cho chi tiêu thiết yếu; 20% cho các khoản dự phòng, tiết kiệm, mua nhà; và 30% còn lại cho các hoạt động giải trí, giao tiếp xã hội. Sau năm đầu, do có con nhỏ, anh chị buộc phải giảm số tiền cho các hoạt động giải trí để tăng cho các sinh hoạt thiết yếu; chị đã tham gia một gói bảo hiểm an sinh cho con mình đề phòng lúc ốm đau.", "o": ["Thực hiện kế hoạch thu chi bằng sổ theo dõi hằng tháng là thể hiện việc xác định mục tiêu tài chính.", "Việc tham gia bảo hiểm an sinh cho con là biện pháp nhằm tăng nguồn thu nhập cho gia đình.", "Kể từ khi có con nhỏ, anh chị chủ động cắt giảm khoản chi không thiết yếu là phù hợp.", "Anh chị xác định mục tiêu mua nhà sau 3 năm là chưa phù hợp."], "a": [false, false, true, false], "e": "Đáp án: a) Sai; b) Sai; c) Đúng; d) Sai.", "nguon": "Đề nguồn: Đề 1 đáp án.docx · Phần II câu 4 · khoá: chữ Đúng/Sai trong ý"}]}, {"id": "L12-HK1-02", "loai": "khoi", "khoi": 12, "hoc_ki": 1, "bo": "HK1", "ten_bo": "học kì I", "so_de": 2, "ten": "Lớp 12 · học kì I · Đề 2", "pham_vi": "Tổng hợp Bài 1–7 (đề nguồn «HỌC KÌ 1 › tong_hop_1_7») · file nguồn: Đề 2 đáp án.docx", "thoi_gian": 50, "cau_truc": "24 câu trắc nghiệm + 4 câu đúng/sai (mỗi câu 4 ý)", "status": "cho_duyet", "khoa": {"1 nguồn": 28}, "sua": "", "cau": [{"id": "L12-HK1-02-C01", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Mối quan hệ giữa tăng trưởng kinh tế và phát triển bền vững được thể hiện ở nội dung nào dưới đây?", "o": ["Tăng trưởng kinh tế và phát triển bền vững không liên quan đến nhau.", "Tăng trưởng kinh tế không gây ảnh hưởng đến phát triển bền vững.", "Tăng trưởng kinh tế và phát triển bền vững là hai nội dung đối lập, không thể thực hiện đồng thời.", "Tăng trưởng kinh tế là điều kiện tiên quyết để đạt được phát triển bền vững."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: Đề 2 đáp án.docx · Phần I câu 1 · khoá: gạch chân"}, {"id": "L12-HK1-02-C02", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Yếu tố nào dưới đây là chỉ tiêu của phát triển kinh tế?", "o": ["Mức sống bình dân.", "Tiến bộ xã hội.", "Cơ cấu dòng tiền.", "Tăng trưởng dân số."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: Đề 2 đáp án.docx · Phần I câu 2 · khoá: gạch chân"}, {"id": "L12-HK1-02-C03", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Phát biểu nào dưới đây là đúng về hội nhập kinh tế quốc tế?", "o": ["Hội nhập kinh tế quốc tế chỉ cần thiết đối với những quốc gia đang phát triển để thu hẹp khoảng cách tụt hậu.", "Trong hội nhập kinh tế quốc tế, một quốc gia được lợi thì sẽ có quốc gia khác chịu thiệt về kinh tế.", "Hội nhập kinh tế quốc tế tạo ra sự phụ thuộc và mất cân bằng về lợi ích giữa các quốc gia với nhau.", "Hội nhập kinh tế quốc tế có thể diễn ra giữa hai quốc gia với nhau trên cơ sở cùng có lợi về kinh tế."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: Đề 2 đáp án.docx · Phần I câu 3 · khoá: gạch chân"}, {"id": "L12-HK1-02-C04", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Sự phát triển nào dưới đây phản ánh sự chuyển biến tổng hợp của nền kinh tế cả về số lượng và chất lượng?", "o": ["Phát triển kinh tế.", "Tăng trưởng kinh tế.", "Tỷ lệ lạm phát.", "Tỷ lệ thất nghiệp."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: Đề 2 đáp án.docx · Phần I câu 4 · khoá: gạch chân"}, {"id": "L12-HK1-02-C05", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Sự gia tăng về quy mô sản lượng của một nền kinh tế trong một thời kỳ nhất định so với thời kỳ gốc là nội dung của khái niệm nào dưới đây?", "o": ["Tăng trưởng xã hội và tiến bộ, công bằng trong phân phối thu nhập.", "Tăng trưởng kinh tế.", "Phát triển kinh tế.", "Hội nhập kinh tế."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: Đề 2 đáp án.docx · Phần I câu 5 · khoá: gạch chân"}, {"id": "L12-HK1-02-C06", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Phát biểu nào dưới đây là đúng về chỉ tiêu tăng trưởng kinh tế?", "o": ["Mức tăng chỉ số bất bình đẳng trong phân phối thu nhập.", "Mức tăng tổng thu nhập quốc dân trong một thời kỳ nhất định.", "Mức tăng dân số của một quốc gia trong một thời kỳ nhất định.", "Mức tăng thu nhập của từng cá nhân trong một thời kỳ nhất định."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: Đề 2 đáp án.docx · Phần I câu 6 · khoá: gạch chân"}, {"id": "L12-HK1-02-C07", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đối với các nước đang phát triển, việc tham gia vào quá trình hội nhập kinh tế quốc tế sẽ mang lại lợi ích nào dưới đây?", "o": ["Lệ thuộc tài chính vào nước lớn.", "Tận dụng được nguồn tài chính.", "Mở mang thêm phạm vi lãnh thổ.", "Được chuyển lên thành nước lớn."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: Đề 2 đáp án.docx · Phần I câu 7 · khoá: gạch chân"}, {"id": "L12-HK1-02-C08", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đối với mỗi quốc gia, hình thức hội nhập sâu rộng nhất, gắn kết với nhiều quốc gia, tổ chức, khu vực trên thế giới là hình thức nào dưới đây?", "o": ["Hội nhập liên minh.", "Hội nhập song phương.", "Hội nhập khu vực.", "Hội nhập toàn cầu."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: Đề 2 đáp án.docx · Phần I câu 8 · khoá: gạch chân"}, {"id": "L12-HK1-02-C09", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Việc gia nhập Tổ chức Thương mại thế giới thể hiện Việt Nam tham gia cấp độ hội nhập nào dưới đây?", "o": ["Hội nhập song phương.", "Hội nhập khu vực.", "Hội nhập toàn cầu,", "Hội nhập đa phương."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: Đề 2 đáp án.docx · Phần I câu 9 · khoá: gạch chân"}, {"id": "L12-HK1-02-C10", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Là hình thức các bên tham gia hình thành thị trường chung đồng thời xây dựng chính sách kinh tế chung, thực hiện những mục tiêu chung cho toàn liên minh là thể hiện mức độ hội nhập kinh tế quốc tế ở mức độ", "o": ["thị trường chung.", "liên minh kinh tế.", "hiệp định thương mại tự do.", "thoả thuận thương mại ưu đãi."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: Đề 2 đáp án.docx · Phần I câu 10 · khoá: gạch chân"}, {"id": "L12-HK1-02-C11", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Khi xác định mục tiêu kinh doanh, các chủ thể không cần chú ý tới tiêu chí nào dưới đây?", "o": ["Tính có thể đo lường.", "Tính khả thi.", "Tính vô thời hạn.", "Tính cụ thể."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: Đề 2 đáp án.docx · Phần I câu 11 · khoá: gạch chân"}, {"id": "L12-HK1-02-C12", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Một trong những điều kiện thực hiện ý tưởng kinh doanh mà các chủ thể sản xuất cần phân tích để lập kế hoạch kinh doanh phù hợp l�", "o": ["yếu tố hội nhập kinh tế quốc tế và các chính sách thương mại.", "yếu tố khách hàng.", "yếu tố xuất thân và nguồn gốc gia đình của người kinh doanh.", "yếu tố quốc tế."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: Đề 2 đáp án.docx · Phần I câu 12 · khoá: gạch chân"}, {"id": "L12-HK1-02-C13", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Một trong những đặc điểm của ý tưởng kinh doanh là ý tưởng đó phải có", "o": ["tính nhân đạo.", "tính sáng tạo.", "tính phi lợi nhuận.", "tính xã hội."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: Đề 2 đáp án.docx · Phần I câu 13 · khoá: gạch chân"}, {"id": "L12-HK1-02-C14", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Khi xây dựng bản kế hoạch kinh doanh, các chủ thể không cần đưa nội dung nào dưới đây vào kế hoạch của mình?", "o": ["Phương hướng kinh doanh.", "Cách thức thực hiện.", "Thời điểm hoàn thành.", "Điều kiện thực hiện."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: Đề 2 đáp án.docx · Phần I câu 14 · khoá: gạch chân"}, {"id": "L12-HK1-02-C15", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Công dân hoàn thiện đầy đủ điều kiện theo quy định của pháp luật trước khi tiến hành các hoạt động kinh doanh là đã thực hiện trách nhiệm xã hội của doanh nghiệp ở hình thức nào dưới đây?", "o": ["Trách nhiệm pháp lý.", "Trách nhiệm kinh doanh.", "Trách nhiệm nhân văn.", "Trách nhiệm từ thiện."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: Đề 2 đáp án.docx · Phần I câu 15 · khoá: gạch chân"}, {"id": "L12-HK1-02-C16", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Bên cạnh việc phát triển sản xuất, các doanh nghiệp tích cực tham gia các hoạt động nhân đạo là đã thể hiện trách nhiệm nào dưới đây của doanh nghiệp?", "o": ["Trách nhiệm sản xuất.", "Trách nhiệm tiêu dùng.", "Trách nhiệm nhân văn.", "Trách nhiệm pháp lý."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: Đề 2 đáp án.docx · Phần I câu 16 · khoá: gạch chân"}, {"id": "L12-HK1-02-C17", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Việc các chủ thể kinh tế thực hiện tốt trách nhiệm xã hội của mình khi kinh doanh sẽ đem lại lợi ích nào dưới đây đối với sự phát triển bền vững?", "o": ["Bảo vệ bất bình đẳng xã hội.", "Bảo vệ môi trường sống.", "Gây rối loạn thị trường.", "Cạnh tranh không lành mạnh."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: Đề 2 đáp án.docx · Phần I câu 17 · khoá: gạch chân"}, {"id": "L12-HK1-02-C18", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Doanh nghiệp sản xuất các sản phẩm, dịch vụ hữu ích; không gây hại cho xã hội và môi trường, thể hiện hình thức trách nhiệm xã hội nào của doanh nghiệp?", "o": ["Nhân văn.", "Đạo đức.", "Pháp lý.", "Kinh tế."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: Đề 2 đáp án.docx · Phần I câu 18 · khoá: gạch chân"}, {"id": "L12-HK1-02-C19", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Công dân thực hiện tốt các quy định của pháp luật về bảo vệ quyền lợi hợp pháp của người tiêu dùng khi tiến hành kinh doanh là đã thực hiện trách nhiệm xã hội của doanh nghiệp ở hình thức nào dưới đây?", "o": ["Trách nhiệm nhân văn.", "Trách nhiệm từ thiện.", "Trách nhiệm pháp lý.", "Trách nhiệm kinh doanh."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: Đề 2 đáp án.docx · Phần I câu 19 · khoá: gạch chân"}, {"id": "L12-HK1-02-C20", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Công dân kinh doanh đúng ngành, nghề ghi trong giấy chứng nhận đăng kí kinh doanh là thể hiện trách nhiệm xã hội của doanh nghiệp ở hình thức nào dưới đây?", "o": ["Trách nhiệm kinh doanh.", "Trách nhiệm pháp lý.", "Trách nhiệm từ thiện.", "Trách nhiệm kinh tế."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: Đề 2 đáp án.docx · Phần I câu 20 · khoá: gạch chân"}, {"id": "L12-HK1-02-C21", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đọc đoạn thông tin sau:\nCơ cấu kinh tế ngành và nội ngành chuyển biến tích cực; tỉ trọng công nghiệp chế biến, chế tạo và ứng dụng công nghệ cao tăng lên. Tỉ trọng lao động nông, lâm nghiệp và thuỷ sản trong tổng số lao động cả nước giảm từ 48,6% năm 2010 xuống còn 34% năm 2020. Tỉ trọng lao động ngành công nghiệp và xây dựng tăng từ 21,7% lên 30,3%. Thu nhập bình quân đầu người tăng 3,1 lần, từ 16,6 triệu đồng năm 2010 lên 51,5 triệu đồng năm 2019.\nMột nền kinh tế được coi là phát triển khi cơ cấu lao động trong lĩnh vực công nghiệp và dịch vụ phải lớn hơn lao động tham gia vào khu vực", "o": ["công nghiệp chế biến và xây dựng.", "vận tải và kho bãi.", "dịch vụ và thương mại trong nền kinh tế.", "nông nghiệp."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: Đề 2 đáp án.docx · Phần I câu 21 · khoá: gạch chân"}, {"id": "L12-HK1-02-C22", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Giải quyết tốt vấn đề nào dưới đây sẽ góp phần nâng cao chỉ số phát triển con người (HDI) ở nước ta hiện nay?", "o": ["Chuyển dịch cơ cấu kinh tế.", "Gia tăng tỷ trọng ngành dịch vụ.", "Phát triển nông nghiệp hữu cơ và sản xuất thân thiện với môi trường trên diện rộng.", "Giải quyết việc làm và thu nhập."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: Đề 2 đáp án.docx · Phần I câu 22 · khoá: gạch chân"}, {"id": "L12-HK1-02-C23", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đọc đoạn thông tin sau:\nNhận thấy quê hương mình rất phong phú về các loại thảo mộc và nhu cầu thị trường về dòng sản phẩm này ngày càng tăng lên, anh H đã xây dựng kế hoạch kinh doanh mĩ phẩm chiết xuất từ thiên nhiên. Sau khi đánh giá những thuận lợi và khó khăn, anh H nhận thấy kế hoạch kinh doanh của mình có khả thi. Nhờ xây dựng kế hoạch kinh doanh tốt, đánh giá đúng cơ hội, đối tượng khách hàng tiềm năng,… nên việc kinh doanh đã đạt được những thành công ban đầu.\nAnh H đã biết xác định ý tưởng kinh doanh thông qua việc làm nào dưới đây?", "o": ["Kinh doanh mĩ phẩm từ thiên nhiên.", "Nhận thấy nhu cầu cao về thảo mộc.", "Đạt hiệu quả cao trong kinh doanh và tăng doanh thu bán hàng.", "Đánh giá tiềm năng về khách hàng."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: Đề 2 đáp án.docx · Phần I câu 23 · khoá: gạch chân"}, {"id": "L12-HK1-02-C24", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Khi đánh giá những thuận lợi và khó khăn khi tiến hành kinh doanh, anh H đã thực hiện bước nào dưới đây của việc lập kế hoạch kinh doanh?", "o": ["Xác định ý tưởng kinh doanh.", "Xác định mục tiêu kinh doanh.", "Phân tích điều kiện thực hiện kinh doanh.", "Phân tích những rủi ro và biện pháp xử lý."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: Đề 2 đáp án.docx · Phần I câu 24 · khoá: gạch chân"}, {"id": "L12-HK1-02-C25", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "dung_sai", "status": "cho_duyet", "q": "Đọc đoạn thông tin sau và cho biết mỗi ý a, b, c, d là Đúng hay Sai. Về cơ cấu nền kinh tế năm 2023, khu vực nông, lâm nghiệp và thủy sản chiếm tỷ trọng 11,96%; khu vực công nghiệp và xây dựng chiếm 37,12%; khu vực dịch vụ chiếm 42,54%. GDP bình quân đầu người năm 2023 ước đạt 101,9 triệu đồng/người, tương đương 4.284,5 USD, tăng 160 USD so với năm 2022. Năng suất lao động theo giá so sánh tăng 3,65% do trình độ của người lao động được cải thiện.", "o": ["Cơ cấu ngành kinh tế chuyển dịch chưa phù hợp với các chỉ tiêu phát triển kinh tế.", "Thu nhập 4.284,5 USD/người là thu nhập quốc dân bình quân theo đầu người.", "Năng suất lao động theo giá so sánh tăng 3,65% do trình độ người lao động được cải thiện.", "Trình độ người lao động là tiêu chí đánh giá sự phát triển kinh tế."], "a": [false, false, true, false], "e": "Đáp án: a) Sai; b) Sai; c) Đúng; d) Sai.", "nguon": "Đề nguồn: Đề 2 đáp án.docx · Phần II câu 1 · khoá: chữ Đúng/Sai trong ý"}, {"id": "L12-HK1-02-C26", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "dung_sai", "status": "cho_duyet", "q": "Đọc đoạn thông tin sau và cho biết mỗi ý a, b, c, d là Đúng hay Sai. Theo Tổng cục Thống kê công bố, tốc độ tăng trưởng GDP năm 2023 đạt 5,05% và có xu hướng tăng dần theo thời gian, quý IV đạt 6,72%, cao nhất so với quý III, II và quý I (tương ứng 5,47%, 4,25% và 3,41%).", "o": ["Quý IV năm 2023 có tốc độ tăng GDP cao nhất trong năm.", "Tốc độ tăng GDP năm 2023 cho thấy Việt Nam là quốc gia có mức sống cao.", "Tốc độ tăng GDP quý III năm 2023 (5,47%) cao hơn tốc độ tăng GDP cả năm 2023 (5,05%).", "Tốc độ tăng GDP năm 2023 là căn cứ để so sánh với tăng trưởng kinh tế năm 2024."], "a": [true, false, true, true], "e": "Đáp án: a) Đúng; b) Sai; c) Đúng; d) Đúng.", "nguon": "Đề nguồn: Đề 2 đáp án.docx · Phần II câu 2 · khoá: chữ Đúng/Sai trong ý"}, {"id": "L12-HK1-02-C27", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "dung_sai", "status": "cho_duyet", "q": "Đọc đoạn thông tin sau và cho biết mỗi ý a, b, c, d là Đúng hay Sai. Công ty cổ phần B sản xuất hàng đồ chơi trẻ em. Từ nhiều năm nay, công ty đã thực hiện đầy đủ quy định pháp luật về bảo vệ môi trường trong sản xuất, hàng năm đầu tư hàng tỉ đồng để xây dựng hệ thống xử lí nước thải; sản xuất đồ chơi không ảnh hưởng đến sức khoẻ của trẻ em. Đồng thời, công ty còn thực hiện đúng nghĩa vụ kê khai và nộp thuế cho Nhà nước theo quy định.", "o": ["Thực hiện pháp luật về bảo vệ môi trường là đã thực hiện trách nhiệm xã hội ở hình thức pháp lý và kinh tế.", "Sản xuất đồ chơi không ảnh hưởng đến sức khỏe trẻ em là phù hợp với trách nhiệm đạo đức và kinh tế.", "Thực hiện tốt nghĩa vụ nộp thuế cho Nhà nước gắn liền với trách nhiệm nhân văn của doanh nghiệp.", "Tạo ra sản phẩm không ảnh hưởng đến sức khỏe trẻ em thể hiện trách nhiệm thúc đẩy phát triển bền vững."], "a": [false, true, false, true], "e": "Đáp án: a) Sai; b) Đúng; c) Sai; d) Đúng.", "nguon": "Đề nguồn: Đề 2 đáp án.docx · Phần II câu 3 · khoá: chữ Đúng/Sai trong ý"}, {"id": "L12-HK1-02-C28", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "dung_sai", "status": "cho_duyet", "q": "Đọc đoạn thông tin sau và cho biết mỗi ý a, b, c, d là Đúng hay Sai. Khi biết có một căn nhà cũ bán với giá rẻ, anh T liền lên kế hoạch dự trù tài chính, mua lại căn nhà đó để sửa chữa và cho thuê với giá hợp lí. Cách thức này vừa giúp gia đình anh có thêm nguồn thu nhập vừa giữ được tài sản hiện có. Bên cạnh đó, anh T dành một khoản lớn thu nhập cho mục tiêu tiết kiệm. Anh chi tiêu ở mức tối thiểu cho sinh hoạt hằng ngày với các nhu cầu thiết yếu.", "o": ["Việc phân chia chi tiêu thiết yếu và không thiết yếu của anh T là hoàn toàn phù hợp.", "Mua nhà rồi cho thuê lại là khoản thu nhập thụ động trong gia đình.", "Mua nhà và mua xe là các mục tiêu tài chính trong gia đình của anh T.", "Hạn chế giao tiếp để giảm chi tiêu thiết yếu của anh T là phù hợp."], "a": [false, true, true, false], "e": "Đáp án: a) Sai; b) Đúng; c) Đúng; d) Sai.", "nguon": "Đề nguồn: Đề 2 đáp án.docx · Phần II câu 4 · khoá: chữ Đúng/Sai trong ý"}]}, {"id": "L12-HK1-03", "loai": "khoi", "khoi": 12, "hoc_ki": 1, "bo": "HK1", "ten_bo": "học kì I", "so_de": 3, "ten": "Lớp 12 · học kì I · Đề 3", "pham_vi": "Tổng hợp Bài 1–7 (đề nguồn «HỌC KÌ 1 › tong_hop_1_7») · file nguồn: Đề 3 đáp án.docx", "thoi_gian": 50, "cau_truc": "24 câu trắc nghiệm + 4 câu đúng/sai (mỗi câu 4 ý)", "status": "cho_duyet", "khoa": {"1 nguồn": 28}, "sua": "", "cau": [{"id": "L12-HK1-03-C01", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đối với một quốc gia tăng trưởng và phát triển kinh tế có vai trò quan trọng, là điều kiện cần thiết để", "o": ["thúc đẩy tỷ lệ thất nghiệp.", "gia tăng tỷ lệ lạm phát và làm giảm sức mua của đồng tiền.", "thúc đẩy phân hóa giàu nghèo.", "khắc phục tình trạng đói nghèo."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: Đề 3 đáp án.docx · Phần I câu 1 · khoá: gạch chân"}, {"id": "L12-HK1-03-C02", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Trong quá trình hội nhập quốc tế, tăng trưởng kinh tế là điều kiện tiên quyết để nước ta không rơi vào tình trạng nào dưới đây?", "o": ["Thu hút nguồn vốn đầu tư trực tiếp.", "Có quan hệ song phương toàn diện.", "Hợp tác và cạnh tranh toàn diện.", "Ngày càng tụt hậu so với thế giới."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: Đề 3 đáp án.docx · Phần I câu 2 · khoá: gạch chân"}, {"id": "L12-HK1-03-C03", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đối với một quốc gia, tăng trưởng kinh tế được thể hiện ở sự gia tăng các", "o": ["tệ nạn xã hội.", "giá trị hàng hóa.", "quan hệ đối ngoại.", "tổ chức tội phạm."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: Đề 3 đáp án.docx · Phần I câu 3 · khoá: gạch chân"}, {"id": "L12-HK1-03-C04", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Ngoài việc căn cứ vào sự tăng lên về thu nhập hay tổng giá trị hàng hóa và dịch vụ mà nền kinh tế tạo ra trong một thời kỳ nhất định, người ta còn căn cứ vào sự tăng lên của yếu tố nào dưới đây?", "o": ["Thu nhập của đối tượng yếu thế.", "Thu nhập trung bình của các quốc gia.", "Thu nhập trung bình của người dân.", "Thu nhập của tầng lớp thượng lưu."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: Đề 3 đáp án.docx · Phần I câu 4 · khoá: gạch chân"}, {"id": "L12-HK1-03-C05", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Trong mối quan hệ giữa tăng trưởng kinh tế với phát triển kinh tế nếu tăng trưởng kinh tế không hợp lý sẽ tác động như thế nào tới việc phát triển kinh tế của mỗi quốc gia?", "o": ["Không tác động tới sự phát triển.", "Tạo điều kiện thuận lợi để phát triển", "Kìm hãm và tác động tiêu cực.", "Thúc đẩy và tạo động lực."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: Đề 3 đáp án.docx · Phần I câu 5 · khoá: gạch chân"}, {"id": "L12-HK1-03-C06", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Khi tham gia vào các quan hệ kinh tế quốc tế, các quốc gia thoả thuận, cam kết dành cho nhau các ưu đãi về thuế quan và phi thuế quan đối với hàng hoá của nhau là thể hiện mức độ hội nhập kinh tế quốc tế ở mức độ", "o": ["hiệp định thương mại tự do.", "thoả thuận thương mại ưu đãi.", "thị trường chung với việc di chuyển tự do lao động và vốn giữa các nước thành viên.", "liên minh kinh tế."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: Đề 3 đáp án.docx · Phần I câu 6 · khoá: gạch chân"}, {"id": "L12-HK1-03-C07", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Quá trình một quốc gia thực hiện việc gắn kết nền kinh tế của mình với nền kinh các quốc gia khác trong khu vực và trên thế giới dựa trên cơ sở cùng có lợi và tuân thủ quy định chung là nội dung của khái niệm nào dưới đây?", "o": ["Kinh tế đối ngoại.", "Hội nhập kinh tế.", "Phát triển kinh tế.", "Tăng trưởng kinh tế."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: Đề 3 đáp án.docx · Phần I câu 7 · khoá: gạch chân"}, {"id": "L12-HK1-03-C08", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Các hoạt động kinh tế đối ngoại của quốc gia không gồm hoạt động nào?", "o": ["Thương mại nội địa.", "Thương mại quốc tế.", "Dịch vụ thu ngoại tệ.", "Đầu tư quốc tế."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: Đề 3 đáp án.docx · Phần I câu 8 · khoá: gạch chân"}, {"id": "L12-HK1-03-C09", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Việc các quốc gia cùng nhau tham gia các liên minh thuế quan chung là biểu hiện của hình thức", "o": ["hợp tác lĩnh vực chính trị.", "hợp tác về biên giới lãnh thổ.", "hội nhập kinh tế quốc tế.", "hội nhập về văn hóa dân tộc."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: Đề 3 đáp án.docx · Phần I câu 9 · khoá: gạch chân"}, {"id": "L12-HK1-03-C10", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Quá trình liên kết, hợp tác giữa các quốc gia trong khu vực trên cơ sở tương đồng về địa lý, văn hóa, xã hội là một trong những hình thức hội nhập kinh tế quốc tế ở cấp độ", "o": ["hội nhập kinh tế toàn cầu.", "hội nhập kinh tế song phương.", "hội nhập kinh tế toàn diện.", "hội nhập kinh tế khu vực."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: Đề 3 đáp án.docx · Phần I câu 10 · khoá: gạch chân"}, {"id": "L12-HK1-03-C11", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Nội dung cơ bản của một bản kế hoạch kinh doanh gồm một chuỗi các biện pháp, cách thức của chủ thể kinh doanh nhằm đạt được hiệu quả tối ưu được gọi l�", "o": ["kế hoạch sản xuất và phân phối sản phẩm ra thị trường.", "kế hoạch tài chính và kế hoạch nhân sự của doanh nghiệp.", "chiến lược đàm phán và ký kết hợp đồng với đối tác.", "chiến lược kinh doanh."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: Đề 3 đáp án.docx · Phần I câu 11 · khoá: gạch chân"}, {"id": "L12-HK1-03-C12", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Nội dung nào dưới đây không thể hiện việc xác định ý tưởng kinh doanh khi lập kế hoạch kinh doanh?", "o": ["Kinh doanh mặt hàng gì và quy mô sản xuất dự kiến.", "Đối tượng khách hàng là ai.", "Tỷ suất lợi nhuận thu được.", "Kinh doanh bằng cách nào và với phương thức bán hàng ra sao."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: Đề 3 đáp án.docx · Phần I câu 12 · khoá: gạch chân"}, {"id": "L12-HK1-03-C13", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Ý tưởng kinh doanh là những suy nghĩ, hành động sáng tạo, có tính khả thi, có thể đem lại lợi nhuận trong", "o": ["nghệ thuật và văn hóa của cộng đồng dân cư địa phương.", "công tác hành chính của cơ quan nhà nước.", "học tập và nghiên cứu khoa học trong nhà trường.", "kinh doanh."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: Đề 3 đáp án.docx · Phần I câu 13 · khoá: gạch chân"}, {"id": "L12-HK1-03-C14", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Khi phân tích các điều kiện thực hiện hoạt động kinh doanh, các chủ thể cần chú ý phân tích điều kiện nào dưới đây?", "o": ["Phân tích chiến lược.", "Phân tích mục tiêu.", "Phân tích sản phẩm.", "Phân tích ý tưởng."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: Đề 3 đáp án.docx · Phần I câu 14 · khoá: gạch chân"}, {"id": "L12-HK1-03-C15", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Tuân thủ các quy định về quan hệ cạnh tranh lành mạnh, quan hệ lao động công bằng, bình đẳng là thể hiện hình thức trách nhiệm xã hội nào của doanh nghiệp?", "o": ["Đạo đức.", "Pháp lý.", "Kinh tế.", "Nhân văn."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: Đề 3 đáp án.docx · Phần I câu 15 · khoá: gạch chân"}, {"id": "L12-HK1-03-C16", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Tuân thủ các quy định về kinh doanh, thực hiện nghĩa vụ nộp thuế l� thể hiện hình thức trách nhiệm xã hội nào của doanh nghiệp?", "o": ["Nhân văn.", "Đạo đức.", "Pháp lý.", "Kinh tế."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: Đề 3 đáp án.docx · Phần I câu 16 · khoá: gạch chân"}, {"id": "L12-HK1-03-C17", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Việc các chủ thể kinh tế luôn giữ gìn sự trung thực về sản phẩm của mình đã cam kết là thể hiện trách nhiệm nào dưới đây của doanh nghiệp?", "o": ["Trách nhiệm phân phối.", "Trách nhiệm sản xuất.", "Trách nhiệm đạo đức.", "Trách nhiệm tiêu dùng."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: Đề 3 đáp án.docx · Phần I câu 17 · khoá: gạch chân"}, {"id": "L12-HK1-03-C18", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Việc doanh nghiệp H tìm các giải pháp để mở rộng sản xuất kinh doanh tạo nhiều việc làm cho người lao động và đem lại lợi nhuận cho doanh nghiệp là đã thực hiện trách nhiệm nào dưới đây?", "o": ["Trách nhiệm pháp lý.", "Trách nhiệm kinh tế.", "Trách nhiệm đạo đức.", "Trách nhiệm nhân văn."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: Đề 3 đáp án.docx · Phần I câu 18 · khoá: gạch chân"}, {"id": "L12-HK1-03-C19", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Trách nhiệm kinh tế của các doanh nghiệp không thể hiện ở việc mỗi chủ thể kinh tế vì mục tiêu lợi nhuận đã", "o": ["đảm bảo lợi ích người tiêu dùng.", "nâng cao năng xuất lao động.", "đầu cơ tích trữ nhiều hàng hóa.", "gia tăng phúc lợi cho công nhân."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: Đề 3 đáp án.docx · Phần I câu 19 · khoá: gạch chân"}, {"id": "L12-HK1-03-C20", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Nội dung nào dưới đây không thể hiện trách nhiệm kinh tế của doanh nghiệp?", "o": ["Sản xuất hàng giả thu lợi nhuận.", "Tạo nhiều việc làm mới cho xã hội.", "Chăm lo lợi ích người lao động.", "Sản xuất hàng hóa đạt tiêu chuẩn."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: Đề 3 đáp án.docx · Phần I câu 20 · khoá: gạch chân"}, {"id": "L12-HK1-03-C21", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đọc đoạn thông tin sau:\nĐảng, Nhà nước đã bố trí nguồn lực từ ngân sách nhà nước và huy động nguồn lực toàn xã hội để thực hiện Chương trình mục tiêu quốc gia xóa đói giảm nghèo. Kết quả xóa đói giảm nghèo đã tạo thêm cơ sở vững chắc cho Việt Nam bảo đảm các quyền và lợi ích của người dân. Đến năm 2020, cả nước đã xây dựng, củng cố được hàng vạn ngôi nhà cho người nghèo; 99% địa bàn đồng bào dân tộc thiểu số có đường giao thông từ tỉnh đến huyện, xã.\nNội dung nào dưới đây thể hiện vai trò của tăng trưởng kinh tế đối với việc xóa đói giảm nghèo ở nước ta?", "o": ["Tăng trưởng kinh tế làm gia tăng tỷ lệ đói nghèo.", "Xóa đói giảm nghèo sẽ hạn chế sự tăng trưởng kinh tế.", "Xóa đói giảm nghèo sẽ thúc đẩy tăng trưởng kinh tế.", "Tăng trưởng kinh tế là cơ sở để xóa đói giảm nghèo."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: Đề 3 đáp án.docx · Phần I câu 21 · khoá: gạch chân"}, {"id": "L12-HK1-03-C22", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Việc thực hiện tốt công tác xóa đói giảm nghèo sẽ góp phần trực tiếp vào việc thực hiện mục tiêu nào dưới đây của phát triển kinh tế?", "o": ["Chỉ số thất nghiệp cơ cấu.", "Chỉ số lạm phát tự nhiên.", "Chỉ số lao động, việc làm và thu nhập bình quân của người lao động.", "Chỉ số phát triển con người."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: Đề 3 đáp án.docx · Phần I câu 22 · khoá: gạch chân"}, {"id": "L12-HK1-03-C23", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đọc đoạn thông tin sau:\nSau khi tốt nghiệp đại học ngành công nghệ sinh học, chị D quyết định lập nghiệp bằng con đường kinh doanh sản phẩm cây cảnh mini với mong muốn sau hai năm sẽ thành lập một doanh nghiệp phân phối các sản phẩm này. Từ thực tế kinh doanh, chị quyết định mở rộng sản xuất và lên kế hoạch đầu tư thêm nhiều cửa hàng mới cũng như phát triển kênh truyền thông nhằm mở rộng thị trường.\nNội dung nào dưới đây thể hiện chị D đã biết xác định ý tưởng khi lập kế hoạch kinh doanh?", "o": ["Mở cửa hàng để bán.", "Thuê lao động bán hàng.", "Sử dụng mạng xã hội.", "Kinh doanh cây cảnh."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: Đề 3 đáp án.docx · Phần I câu 23 · khoá: gạch chân"}, {"id": "L12-HK1-03-C24", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Chị D đã xác định cho mình mục tiêu kinh doanh l�", "o": ["mở rộng sản xuất và phát triển kênh bán hàng trực tuyến.", "thành lập doanh nghiệp.", "lập thân, lập nghiệp và tạo việc làm cho người khác.", "đẩy mạnh truyền thông."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: Đề 3 đáp án.docx · Phần I câu 24 · khoá: gạch chân"}, {"id": "L12-HK1-03-C25", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "dung_sai", "status": "cho_duyet", "q": "Đọc đoạn thông tin sau và cho biết mỗi ý a, b, c, d là Đúng hay Sai. Việt Nam ngày càng thực sự phát huy vai trò của mình trong việc tham gia ngày càng sâu rộng vào quá trình liên kết khu vực và thế giới. Là thành viên của ASEAN từ năm 1995, nước ta tham gia tích cực và đóng góp vào quá trình xây dựng Cộng đồng ASEAN... Cộng đồng Pháp ngữ, Phong trào không liên kết... Nước ta đã tham gia nhiều Hiệp định thương mại tự do song phương và khu vực và đang đàm phán các Hiệp định thương mại tự do thế hệ mới.", "o": ["Cộng đồng Pháp ngữ, Phong trào không liên kết là biểu hiện của hội nhập kinh tế quốc tế.", "Việt Nam cần vừa hội nhập kinh tế song phương vừa hội nhập kinh tế đa phương.", "Kết hợp hội nhập kinh tế với hội nhập về chính trị, văn hóa để hợp tác toàn diện và sâu rộng.", "Khi hội nhập kinh tế quốc tế, Việt Nam phải tuân thủ các quy định do các nước phát triển đặt ra."], "a": [false, true, true, false], "e": "Đáp án: a) Sai; b) Đúng; c) Đúng; d) Sai.", "nguon": "Đề nguồn: Đề 3 đáp án.docx · Phần II câu 1 · khoá: chữ Đúng/Sai trong ý"}, {"id": "L12-HK1-03-C26", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "dung_sai", "status": "cho_duyet", "q": "Đọc đoạn thông tin sau và cho biết mỗi ý a, b, c, d là Đúng hay Sai. Đến nay, nước ta đã có quan hệ chính thức với 189/193 quốc gia và vùng lãnh thổ; có quan hệ thương mại với 224 đối tác và quan hệ hợp tác với hơn 300 tổ chức quốc tế; đã ký hơn 90 hiệp định thương mại song phương, gần 60 hiệp định khuyến khích và bảo hộ đầu tư; đàm phán, ký kết và thực thi 19 Hiệp định thương mại tự do (FTA).", "o": ["Việt Nam có quan hệ kinh tế với 189/193 quốc gia.", "Ký kết hiệp định thương mại song phương giúp Việt Nam mở rộng hoạt động kinh tế đối ngoại.", "Kinh tế đối ngoại góp phần thúc đẩy tăng trưởng và phát triển kinh tế.", "Hoạt động kinh tế đối ngoại là một bộ phận cấu thành chính sách đối ngoại của Việt Nam."], "a": [false, true, true, true], "e": "Đáp án: a) Sai; b) Đúng; c) Đúng; d) Đúng.", "nguon": "Đề nguồn: Đề 3 đáp án.docx · Phần II câu 2 · khoá: chữ Đúng/Sai trong ý"}, {"id": "L12-HK1-03-C27", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "dung_sai", "status": "cho_duyet", "q": "Đọc đoạn thông tin sau và cho biết mỗi ý a, b, c, d là Đúng hay Sai. Với mong muốn xây dựng thành công chuỗi cửa hàng phân phối thực phẩm sạch trên địa bàn huyện X, anh H đã lên kế hoạch chi tiết để thực hiện ý tưởng kinh doanh. Qua tìm hiểu thực tế anh nhận thấy đây là sản phẩm đang có nhu cầu lớn. Anh đã dự liệu được những rủi ro, khó khăn tiềm ẩn để có giải pháp khắc phục; đã lên kế hoạch chi tiết việc bán hàng, tiếp thị, quảng cáo.", "o": ["Anh H xác định ý tưởng kinh doanh khi thấy sản phẩm thực phẩm sạch có nhu cầu lớn.", "Anh H chưa phân tích các điều kiện thực hiện ý tưởng kinh doanh.", "Anh H đã dự liệu rủi ro, khó khăn tiềm ẩn và có giải pháp khắc phục.", "Anh H đã biết xác định chiến lược kinh doanh qua việc lên kế hoạch bán hàng, tiếp thị và quảng cáo."], "a": [true, false, true, true], "e": "Đáp án: a) Đúng; b) Sai; c) Đúng; d) Đúng.", "nguon": "Đề nguồn: Đề 3 đáp án.docx · Phần II câu 3 · khoá: chữ Đúng/Sai trong ý"}, {"id": "L12-HK1-03-C28", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "dung_sai", "status": "cho_duyet", "q": "Đọc đoạn thông tin sau và cho biết mỗi ý a, b, c, d là Đúng hay Sai. Đầu năm, vợ chồng anh A thống nhất đặt mục tiêu mỗi tháng sẽ dành 60% thu nhập cho các chi tiêu thiết yếu, tiết kiệm 20% thu nhập gia đình để có đủ tiền mua xe máy mới cho vợ. Hai tháng nay anh A bị mất việc, thu nhập giảm sút. Để phụ giúp gia đình, anh A đã tham gia chạy xe ôm và nhận giao hàng. Nhờ đó mà sau một năm vợ chồng anh A đã hoàn thành mục tiêu đặt ra. Hai vợ chồng quyết tâm năm năm tới sẽ mua được một mảnh đất để làm cửa hàng cho thuê.", "o": ["Kiểm soát các khoản chi tiêu là nhân tố giúp vợ chồng anh A đạt được mục tiêu tài chính.", "Vợ chồng anh A đã phân chia tỷ lệ các khoản chi tiêu trong gia đình.", "Vợ chồng anh A dành 60% thu nhập cho chi tiêu thiết yếu là chưa phù hợp.", "Đồng thời thực hiện hai mục tiêu tài chính của vợ chồng anh A là chưa hợp lý."], "a": [true, true, false, false], "e": "Đáp án: a) Đúng; b) Đúng; c) Sai; d) Sai.", "nguon": "Đề nguồn: Đề 3 đáp án.docx · Phần II câu 4 · khoá: chữ Đúng/Sai trong ý"}]}, {"id": "L12-HK1-04", "loai": "khoi", "khoi": 12, "hoc_ki": 1, "bo": "HK1", "ten_bo": "học kì I", "so_de": 4, "ten": "Lớp 12 · học kì I · Đề 4", "pham_vi": "Tổng hợp Bài 1–7 (đề nguồn «HỌC KÌ 1 › tong_hop_1_7») · file nguồn: Đề 4 đáp án.docx", "thoi_gian": 50, "cau_truc": "24 câu trắc nghiệm + 4 câu đúng/sai (mỗi câu 4 ý)", "status": "cho_duyet", "khoa": {"1 nguồn": 28}, "sua": "", "cau": [{"id": "L12-HK1-04-C01", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Trong mối quan hệ giữa tăng trưởng kinh tế với phát triển kinh tế các quốc gia kiên trì mục tiêu phát triển bền vững sẽ tác động trở lại đối với tăng trưởng kinh tế theo chiều hướng nào dưới đây?", "o": ["Không thúc đẩy và bị động.", "Kìm hãm và hạn chế tác động.", "Thúc đẩy và tạo động lực.", "Cân bằng và không liên hệ."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: Đề 4 đáp án.docx · Phần I câu 1 · khoá: gạch chân"}, {"id": "L12-HK1-04-C02", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Phát biểu nào dưới đây là đúng về chỉ tiêu tăng trưởng kinh tế?", "o": ["Mức tăng chỉ số bất bình đẳng trong phân phối thu nhập.", "Mức tăng tổng thu nhập quốc dân trong một thời kỳ nhất định.", "Mức tăng dân số của một quốc gia trong một thời kỳ nhất định.", "Mức tăng thu nhập của từng cá nhân trong một thời kỳ nhất định."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: Đề 4 đáp án.docx · Phần I câu 2 · khoá: gạch chân"}, {"id": "L12-HK1-04-C03", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Một quốc gia được coi là có sự phát triển về kinh tế khi cơ cấu ngành nông nghiệp giảm đi, cơ cấu ngành công nghiệp, dịch vụ có xu hướng", "o": ["giảm theo.", "tăng lên.", "không đổi.", "cân bằng."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: Đề 4 đáp án.docx · Phần I câu 3 · khoá: gạch chân"}, {"id": "L12-HK1-04-C04", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Nội dung nào dưới đây không phản ánh bản chất của phát triển kinh tế?", "o": ["Tình trạng mất ổn định chính trị diễn ra thường xuyên trong khu vực.", "Mức sống trung bình của người dân tăng trong một thời kì nhất định.", "Cải thiện năng suất lao động thông qua áp dụng công nghệ tiên tiến.", "Tăng tỉ trọng ngành công nghiệp trong tổng sản phẩm quốc nội và giảm tỉ trọng nông nghiệp trong nền kinh tế."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: Đề 4 đáp án.docx · Phần I câu 4 · khoá: gạch chân"}, {"id": "L12-HK1-04-C05", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Trong điều kiện toàn cầu hóa, hội nhập kinh tế quốc tế giúp mỗi quốc gia có cơ hội", "o": ["mở rộng lãnh thổ và biên giới quốc gia với các nước láng giềng.", "mở rộng chủ quyền.", "mở rộng thị trường.", "mở mang trí tuệ."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: Đề 4 đáp án.docx · Phần I câu 5 · khoá: gạch chân"}, {"id": "L12-HK1-04-C06", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Xét về hình thức, hội nhập kinh tế quốc tế là toàn bộ các hoạt động kinh tế đối ngoại của một quốc gia, bao gồm các hoạt động nào dưới đây?", "o": ["Thương mại nội địa, đầu tư quốc tế, du lịch nội địa.", "Thương mại quốc tế, đầu tư trong nước, đầu tư nước ngoài và hoạt động vay vốn trong nước.", "Thương mại quốc tế, đầu tư quốc tế, dịch vụ thu ngoại tệ.", "Toàn cầu hoá kinh tế và toàn cầu hoá chính trị."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: Đề 4 đáp án.docx · Phần I câu 6 · khoá: gạch chân"}, {"id": "L12-HK1-04-C07", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Trong quá trình hội nhập kinh tế quốc tế, các bên tham gia không được sử dụng nguyên tắc nào dưới đây?", "o": ["Cùng có lợi.", "Cưỡng chế.", "Cùng thỏa thuận.", "Bình đẳng."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: Đề 4 đáp án.docx · Phần I câu 7 · khoá: gạch chân"}, {"id": "L12-HK1-04-C08", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Khi tham gia vào quá trình hội nhập kinh tế quốc tế, hình thức hội nhập song phương là quá trình liên kết và hợp tác giữa", "o": ["bốn quốc gia.", "nhiều quốc gia.", "ba quốc gia.", "hai quốc gia."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: Đề 4 đáp án.docx · Phần I câu 8 · khoá: gạch chân"}, {"id": "L12-HK1-04-C09", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Trong quá trình hội nhập kinh tế quốc tế, Việt Nam luôn kiên định quan điểm “ lợi ích hài hòa, rủi ro chia sẻ” điều này thể hiện nguyên tắc nào khi hội nhập kinh tế quốc tế?", "o": ["Bình đẳng giữa các quốc gia, không phân biệt quy mô hay trình độ phát triển.", "Thỏa thuận.", "Công bằng.", "Cùng có lợi."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: Đề 4 đáp án.docx · Phần I câu 9 · khoá: gạch chân"}, {"id": "L12-HK1-04-C10", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Quá trình liên kết, gắn kết giữa các quốc gia, vùng lãnh thổ với nhau thông qua việc tham gia vào các tổ chức kinh tế toàn cầu là một trong những hình thức hội nhập kinh tế quốc tế ở cấp độ", "o": ["khu vực.", "song phương.", "toàn cầu.", "toàn diện."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: Đề 4 đáp án.docx · Phần I câu 10 · khoá: gạch chân"}, {"id": "L12-HK1-04-C11", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Bản tóm tắt kế hoạch kinh doanh không bao gồm nội dung nào dưới đây?", "o": ["Thuận lợi và khó khăn.", "Ý tưởng kinh doanh.", "Tên kế hoạch kinh doanh.", "Thời điểm thành công."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: Đề 4 đáp án.docx · Phần I câu 11 · khoá: gạch chân"}, {"id": "L12-HK1-04-C12", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Kế hoạch kinh doanh xác định rõ sứ mệnh, tầm nhìn, chiến lược, công việc dự định thực hiện và cách đạt được", "o": ["trách nhiệm xã hội của doanh nghiệp đối với cộng đồng.", "mục tiêu xã hội.", "mục tiêu kinh doanh.", "trách nhiệm kinh tế của doanh nghiệp trong thị trường."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: Đề 4 đáp án.docx · Phần I câu 12 · khoá: gạch chân"}, {"id": "L12-HK1-04-C13", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Yếu tố nào dưới đây không phải là tiêu chí để đánh giá một ý tưởng kinh doanh tốt?", "o": ["Không có tính khả thi.", "Có tính mới mẻ, độc đáo.", "Có ưu thế vượt trội.", "Có lợi thế cạnh tranh."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: Đề 4 đáp án.docx · Phần I câu 13 · khoá: gạch chân"}, {"id": "L12-HK1-04-C14", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Kế hoạch kinh doanh là bản phác thảo quá trình kinh doanh trong một khoảng thời gian", "o": ["không xác định.", "chưa xác định.", "mãi mãi.", "nhất định."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: Đề 4 đáp án.docx · Phần I câu 14 · khoá: gạch chân"}, {"id": "L12-HK1-04-C15", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Việc thực hiện trách nhiệm xã hội của doanh nghiệp góp phần mang lại ý nghĩa như thế nào đối với sự phát triển của mỗi quốc gia?", "o": ["Gia tăng khủng hoảng.", "Phát triển bền vững.", "Lạm phát bất ổn.", "Thất nghiệp gia tăng."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: Đề 4 đáp án.docx · Phần I câu 15 · khoá: gạch chân"}, {"id": "L12-HK1-04-C16", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Khi tiến hành hoạt động kinh doanh, các doanh nghiệp phải thực hiện tốt trách nhiệm xã hội thông qua việc làm nào dưới đây?", "o": ["Ứng dụng trí tuệ nhân tạo vào quản lí sản xuất kinh doanh.", "Tham gia bảo hiểm nhân thọ cho toàn bộ nhân viên trong công ty.", "Tổ chức hội nghị khách hàng.", "Bảo vệ quyền lợi người tiêu dùng."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: Đề 4 đáp án.docx · Phần I câu 16 · khoá: gạch chân"}, {"id": "L12-HK1-04-C17", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Anh T nộp hồ sơ đăng kí và được cấp giấy phép mở đại lí phân phối xe mô tô. Anh T đã thực hiện trách nhiệm xã hội ở hình thức nào dưới đây?", "o": ["Trách nhiệm nhân văn.", "Trách nhiệm kinh tế.", "Trách nhiệm pháp lý.", "Trách nhiệm đạo đức."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: Đề 4 đáp án.docx · Phần I câu 17 · khoá: gạch chân"}, {"id": "L12-HK1-04-C18", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Doanh nghiệp tham gia các hoạt động khám chữa bệnh miễn phí, xây dựng nhà tình nghĩa là thể hiện hình thức trách nhiệm xã hội nào của doanh nghiệp?", "o": ["Pháp lý và tuân thủ quy định về bảo hiểm y tế.", "Đạo đức kinh doanh và trung thực với khách hàng.", "Kinh tế và phát triển sản xuất bền vững.", "Nhân văn."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: Đề 4 đáp án.docx · Phần I câu 18 · khoá: gạch chân"}, {"id": "L12-HK1-04-C19", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Nội dung nào dưới đây thể hiện trách nhiệm pháp lý của doanh nghiệp?", "o": ["Gian lận hồ sơ kê khai thuế để giảm số thuế phải nộp.", "Thường xuyên nộp chậm thuế và không kê khai đầy đủ.", "Bị xử phạt hành chính vì chậm nộp thuế theo quy định.", "Chấp hành pháp luật về thuế."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: Đề 4 đáp án.docx · Phần I câu 19 · khoá: gạch chân"}, {"id": "L12-HK1-04-C20", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Trách nhiệm xã hội của doanh nghiệp là toàn bộ trách nhiệm mà doanh nghiệp thực hiện đối với xã hội bằng những chính sách và việc làm cụ thể mang tính", "o": ["tạm thời và không ổn định theo từng thời kì.", "tích cực.", "tiêu cực và gây ảnh hưởng xấu đến xã hội.", "thời vụ theo mùa vụ sản xuất trong năm."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: Đề 4 đáp án.docx · Phần I câu 20 · khoá: gạch chân"}, {"id": "L12-HK1-04-C21", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đọc đoạn thông tin sau:\nBà H là lao động tự do sống trên địa bàn tỉnh Y. Sau một thời gian khám bệnh và điều trị tại bệnh viện K, bà H cầm trên tay hóa đơn, chứng từ thanh toán bảo hiểm y tế với số tiền 80 triệu đồng. Bà đã được thanh toán gần một nửa chi phí điều trị, gần 50 triệu đồng, thuộc đối tượng đồng chi trả 20%. Bà nói: cách đây 5 tháng tôi có mua một tấm thẻ bảo hiểm y tế, nhờ có tấm thẻ này mà tôi không trở thành gánh nặng tài chính của các con khi ốm đau.\nLoại hình bảo hiểm mà bà H tham gia có đặc điểm là", "o": ["bắt buộc.", "được tài trợ.", "được vĩnh viễn.", "tự nguyện."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: Đề 4 đáp án.docx · Phần I câu 21 · khoá: gạch chân"}, {"id": "L12-HK1-04-C22", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Nhờ có tham gia loại hình bảo hiểm đã mang lại lợi ích gì dưới đây cho bà H khi gặp rủi ro về ốm đau?", "o": ["Khám chữa bệnh chất lượng cao tại các bệnh viện tuyến trung ương.", "Giảm gánh nặng tài chính gia đình.", "Được hỗ trợ tiền sau khi ra viện.", "Được khám miễn phí suốt đời."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: Đề 4 đáp án.docx · Phần I câu 22 · khoá: gạch chân"}, {"id": "L12-HK1-04-C23", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đọc đoạn thông tin sau:\nVới mong muốn xây dựng thành công chuỗi cửa hàng phân phối thực phẩm sạch trên địa bàn huyện X, anh H đã lên kế hoạch chi tiết để thực hiện ý tưởng kinh doanh. Qua tìm hiểu thực tế anh nhận thấy đây là sản phẩm đang có nhu cầu lớn. Anh đã dự liệu được những rủi ro, khó khăn tiềm ẩn để có giải pháp khắc phục; đã lên kế hoạch chi tiết việc bán hàng, tiếp thị, quảng cáo.\nNội dung nào dưới đây thể hiện việc xác định ý tưởng kinh doanh của anh H?", "o": ["Đẩy mạnh quảng cáo sản phẩm.", "Xây dựng chuỗi cửa hàng.", "Mở cửa hàng chất lượng cao.", "Kinh doanh thực phẩm sạch."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: Đề 4 đáp án.docx · Phần I câu 23 · khoá: gạch chân"}, {"id": "L12-HK1-04-C24", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Anh H đã xác định mục tiêu kinh doanh của mình đó l�", "o": ["sản phẩm đang có nhu cầu lớn.", "xây dựng chuỗi thực phẩm sạch.", "tiếp cận nhu cầu người tiêu dùng.", "quảng cáo giới thiệu sản phẩm."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: Đề 4 đáp án.docx · Phần I câu 24 · khoá: gạch chân"}, {"id": "L12-HK1-04-C25", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "dung_sai", "status": "cho_duyet", "q": "Đọc đoạn thông tin sau và cho biết mỗi ý a, b, c, d là Đúng hay Sai. Nhà nước đã dành 21% ngân sách cho phúc lợi xã hội, là mức cao nhất trong số các nước ASEAN, nhờ đó đã cơ bản thực hiện thành công các mục tiêu, nhiệm vụ đặt ra. Trong bối cảnh đại dịch COVID-19, thông qua chính sách hỗ trợ trực tiếp của Chính phủ và chính sách bảo hiểm xã hội, bảo hiểm thất nghiệp, đã hỗ trợ hơn 14,4 triệu người với tổng kinh phí hơn 33.000 tỷ đồng.", "o": ["Hỗ trợ kinh phí cho người có công là thực hiện chính sách trợ giúp xã hội.", "Tăng trưởng kinh tế đóng vai trò quan trọng trong việc thực hiện các chính sách an sinh xã hội.", "Việt Nam vừa phát triển kinh tế vừa quan tâm thực hiện chính sách an sinh xã hội.", "Ngân sách nhà nước là nguồn lực duy nhất để thực hiện các chính sách an sinh."], "a": [true, true, true, false], "e": "Đáp án: a) Đúng; b) Đúng; c) Đúng; d) Sai.", "nguon": "Đề nguồn: Đề 4 đáp án.docx · Phần II câu 1 · khoá: chữ Đúng/Sai trong ý"}, {"id": "L12-HK1-04-C26", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "dung_sai", "status": "cho_duyet", "q": "Đọc đoạn thông tin sau và cho biết mỗi ý a, b, c, d là Đúng hay Sai. Nhà nước đã ban hành các chính sách về phổ cập giáo dục; các chính sách hỗ trợ giáo dục cho học sinh thuộc hộ nghèo, thuộc diện đối tượng bảo trợ xã hội, dân tộc thiểu số. Đảng và Nhà nước tập trung hoàn thiện hệ thống khám chữa bệnh, hệ thống bảo hiểm y tế, hệ thống y tế dự phòng. Ưu tiên cho trẻ em dưới 6 tuổi, người cao tuổi từ 80 tuổi trở lên, người dân tộc thiểu số, người nghèo và các đối tượng yếu thế.", "o": ["Phát triển hệ thống y tế dự phòng là nội dung của chính sách bảo hiểm xã hội.", "Ưu tiên khám chữa bệnh cho trẻ em dưới 6 tuổi, người cao tuổi từ 80 tuổi thể hiện chính sách trợ giúp xã hội.", "Hoàn thiện khám chữa bệnh để bảo đảm dịch vụ y tế tối thiểu là phù hợp với chính sách an sinh xã hội.", "Phổ cập giáo dục và hỗ trợ giáo dục là một trong những dịch vụ xã hội tối thiểu của an sinh xã hội."], "a": [false, true, true, true], "e": "Đáp án: a) Sai; b) Đúng; c) Đúng; d) Đúng.", "nguon": "Đề nguồn: Đề 4 đáp án.docx · Phần II câu 2 · khoá: chữ Đúng/Sai trong ý"}, {"id": "L12-HK1-04-C27", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "dung_sai", "status": "cho_duyet", "q": "Đọc đoạn thông tin sau và cho biết mỗi ý a, b, c, d là Đúng hay Sai. Ông S là giám đốc công ty cổ phần sản xuất hàng công nghiệp. Trong quá trình sản xuất, ông đã chỉ đạo công ty làm mọi cách để giảm chi phí sản xuất nhằm tăng lợi nhuận, kể cả việc bỏ qua trách nhiệm của công ty về bảo vệ môi trường như thải khí thải vượt quá mức quy định. Ông chỉ đạo thay đổi một số linh kiện có giá rẻ hơn. Đối với người lao động, công ty đã ký hợp đồng thời vụ với một số lao động phổ thông để không phải đóng bảo hiểm xã hội cho họ.", "o": ["Giám đốc S chưa thực hiện tốt trách nhiệm pháp lý và trách nhiệm đạo đức trong sản xuất kinh doanh.", "Lắp ráp sản phẩm có giá rẻ hơn để tối ưu lợi nhuận là phù hợp với trách nhiệm kinh tế.", "Ký hợp đồng thời vụ để không đóng bảo hiểm xã hội là thể hiện trách nhiệm đạo đức của doanh nghiệp.", "Trích lợi nhuận để làm từ thiện là đủ để xây dựng uy tín, không cần thực hiện nghĩa vụ pháp lý."], "a": [true, false, false, false], "e": "Đáp án: a) Đúng; b) Sai; c) Sai; d) Sai.", "nguon": "Đề nguồn: Đề 4 đáp án.docx · Phần II câu 3 · khoá: chữ Đúng/Sai trong ý"}, {"id": "L12-HK1-04-C28", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "dung_sai", "status": "cho_duyet", "q": "Đọc đoạn thông tin sau và cho biết mỗi ý a, b, c, d là Đúng hay Sai. Vợ chồng chị H đều làm nhân viên cho công ty người ngoài, thu nhập của hai vợ chồng ở mức khá từ 40 – 60 triệu đồng/tháng. Hai vợ chồng chị xác định, ngoài việc nuôi hai con ăn học, cần phải tiết kiệm để sau 3 năm nữa sẽ đủ tiền mua được chung cư. Chị H thực hiện triệt để quy tắc 50/30/20: 50% dành cho chi tiêu thiết yếu, 30% dùng cho các mục tiêu tài chính như trả nợ, tiết kiệm, quỹ dự phòng, 20% dành cho chi tiêu cá nhân. Cuối mỗi tháng, chị tổng hợp chi tiêu và so sánh với kế hoạch.", "o": ["Số tiền 40–60 triệu đồng/tháng là nguồn thu nhập chính làm căn cứ xây dựng kế hoạch thu chi.", "Kế hoạch quản lý thu chi của gia đình chị H chỉ có một mục tiêu là mua chung cư sau ba năm.", "Quy tắc 50/30/20 hợp lí với mức thu nhập của hai vợ chồng chị H.", "Việc thường xuyên tổng hợp và so sánh chi tiêu thực tế với kế hoạch là phù hợp."], "a": [true, false, true, true], "e": "Đáp án: a) Đúng; b) Sai; c) Đúng; d) Đúng.", "nguon": "Đề nguồn: Đề 4 đáp án.docx · Phần II câu 4 · khoá: chữ Đúng/Sai trong ý"}]}, {"id": "L12-HK1-05", "loai": "khoi", "khoi": 12, "hoc_ki": 1, "bo": "HK1", "ten_bo": "học kì I", "so_de": 5, "ten": "Lớp 12 · học kì I · Đề 5", "pham_vi": "Tổng hợp Bài 1–7 (đề nguồn «HỌC KÌ 1 › tong_hop_1_7») · file nguồn: Đề 5 đáp án.docx", "thoi_gian": 50, "cau_truc": "24 câu trắc nghiệm + 4 câu đúng/sai (mỗi câu 4 ý)", "status": "cho_duyet", "khoa": {"1 nguồn": 28}, "sua": "", "cau": [{"id": "L12-HK1-05-C01", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Phát biểu nào dưới đây là đúng về hội nhập kinh tế quốc tế?", "o": ["Hội nhập kinh tế quốc tế chỉ cần thiết đối với những quốc gia đang phát triển để thu hẹp khoảng cách tụt hậu.", "Trong hội nhập kinh tế quốc tế, một quốc gia được lợi thì sẽ có quốc gia khác chịu thiệt về kinh tế.", "Hội nhập kinh tế quốc tế tạo ra sự phụ thuộc và mất cân bằng về lợi ích giữa các quốc gia với nhau.", "Hội nhập kinh tế quốc tế có thể diễn ra giữa hai quốc gia với nhau trên cơ sở cùng có lợi về kinh tế."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: Đề 5 đáp án.docx · Phần I câu 1 · khoá: gạch chân"}, {"id": "L12-HK1-05-C02", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đối với hình thức hội nhập kinh tế song phương, việc thực hiện những thỏa thuận và nghĩa vụ đã ký kết được áp dụng cho", "o": ["hai quốc gia ký kết với nhau.", "các nước trong khu vực.", "mọi quốc gia trên thế giới, không phân biệt có ký kết hay không.", "nhiều quốc gia khác nhau."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: Đề 5 đáp án.docx · Phần I câu 2 · khoá: gạch chân"}, {"id": "L12-HK1-05-C03", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Ở cấp độ quốc gia, việc làm nào dưới đây thể hiện sự hội nhập quốc tế?", "o": ["Tài trợ hoạt động khủng bố và các tổ chức vũ trang trái phép.", "Tài trợ tổ chức phi nhân đạo.", "Tham gia sứ mệnh nhân đạo.", "Tham gia hiệp định thương mại."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: Đề 5 đáp án.docx · Phần I câu 3 · khoá: gạch chân"}, {"id": "L12-HK1-05-C04", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Hình thức hợp tác nào dưới đây không phải là biểu hiện của hình thức hội nhập kinh tế quốc tế?", "o": ["Hội nhập bảo tồn văn hóa.", "Hội nhập kinh tế song phương.", "Hội nhập kinh tế toàn cầu.", "Hội nhập kinh tế khu vực."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: Đề 5 đáp án.docx · Phần I câu 4 · khoá: gạch chân"}, {"id": "L12-HK1-05-C05", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Một trong những biểu hiện của hợp tác kinh tế quốc tế là các quốc gia có thể cùng quốc gia khác tham gia ký kết", "o": ["hiệp định chiến tranh và thỏa thuận hòa bình giữa các quốc gia.", "xác định mốc biên giới.", "hiệp định thương mại tự do.", "tuần tra chung trên biển."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: Đề 5 đáp án.docx · Phần I câu 5 · khoá: gạch chân"}, {"id": "L12-HK1-05-C06", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Trong quá trình hội nhập kinh tế quốc tế, các nước tham gia cần tuân thủ nguyên tắc nào dưới đây?", "o": ["Cá lớn nuốt cá bé.", "Nước nhỏ phụ thuộc nước lớn.", "Các bên cùng có lợi.", "Nước nhỏ không được tự quyết."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: Đề 5 đáp án.docx · Phần I câu 6 · khoá: gạch chân"}, {"id": "L12-HK1-05-C07", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Xét về mặt quan hệ dân sự, bảo hiểm là một", "o": ["dịch vụ ngân hàng và tín dụng thương mại cho doanh nghiệp.", "dịch vụ tín dụng.", "dịch vụ tài chính.", "dịch vụ tiền tệ."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: Đề 5 đáp án.docx · Phần I câu 7 · khoá: gạch chân"}, {"id": "L12-HK1-05-C08", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Một trong những đặc điểm của loại hình bảo hiểm thương mại là có", "o": ["tính không hoàn lại.", "tính bắt buộc.", "tính kinh doanh.", "tính rủi ro cao."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: Đề 5 đáp án.docx · Phần I câu 8 · khoá: gạch chân"}, {"id": "L12-HK1-05-C09", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Xét về bản chất thì bảo hiểm xã hội, bảo hiểm y tế, bảo hiểm thất nghiệp và bảo hiểm thương mại đều có điểm chung ở chỗ các loại hình bảo hiểm này đều", "o": ["là một loại hình của dịch vụ tài chính.", "có độ rủi ro cao và không nên tham gia.", "người tham gia bao giờ cũng thua thiệt do phải đóng phí quá cao.", "có tính bắt buộc mọi chủ thể tham gia."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: Đề 5 đáp án.docx · Phần I câu 9 · khoá: gạch chân"}, {"id": "L12-HK1-05-C10", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đối với mỗi cá nhân, khi không may gặp rủi ro, việc tham gia bảo hiểm sẽ giúp các cá nhân", "o": ["được hỗ trợ trọn đời.", "được hoàn trả đầy đủ.", "đổi vận may mắn.", "ổn định tài chính."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: Đề 5 đáp án.docx · Phần I câu 10 · khoá: gạch chân"}, {"id": "L12-HK1-05-C11", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Nhận định nào dưới đây là không đúng khi nói về ý nghĩa của việc lập kế hoạch kinh doanh?", "o": ["Giúp doanh nghiệp đạt được mục tiêu kinh doanh.", "Tăng lợi nhuận kinh doanh ngay lập tức.", "Tăng khả năng huy động vốn cho doanh nghiệp.", "Duy trì thị trường và xây dựng quan hệ tốt với khách hàng."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: Đề 5 đáp án.docx · Phần I câu 11 · khoá: gạch chân"}, {"id": "L12-HK1-05-C12", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Khi phân tích yếu tố nhân sự để thực hiện ý tưởng kinh doanh, chủ thể không cần phải phân tích nội dung nào dưới đây?", "o": ["Số lượng nhân sự.", "Chất lượng nhân sự.", "Kỹ năng, chuyên môn.", "Quan hệ gia đình."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: Đề 5 đáp án.docx · Phần I câu 12 · khoá: gạch chân"}, {"id": "L12-HK1-05-C13", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Nhận thấy tỉnh B có nhu cầu lớn về các sản phẩm gỗ nhân tạo do có nhiều khu công nghiệp lớn chuẩn bị đi vào hoạt động. Công ty A đã quyết định lên kế hoạch mở rộng thị trường sang tỉnh B. Công ty A đã phân tích các điều kiện kinh doanh ở nội dung nào dưới đây?", "o": ["Sản phẩm và chất lượng của gỗ nhân tạo dự kiến.", "Thị trường.", "Tài chính và nguồn vốn đầu tư của công ty.", "Khách hàng và đối tác phân phối trong tỉnh."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: Đề 5 đáp án.docx · Phần I câu 13 · khoá: gạch chân"}, {"id": "L12-HK1-05-C14", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Nội dung nào dưới đây không thể hiện trong kế hoạch kinh doanh?", "o": ["Các điều kiện thực hiện hoạt động kinh doanh và rủi ro dự kiến.", "Mục tiêu và chiến lược kinh doanh dài hạn của doanh nghiệp.", "Kế hoạch hoạt động kinh doanh trong từng giai đoạn.", "Thông số kĩ thuật, công thức sản xuất sản phẩm."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: Đề 5 đáp án.docx · Phần I câu 14 · khoá: gạch chân"}, {"id": "L12-HK1-05-C15", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Doanh nghiệp đóng góp quỹ phòng chống thiên tai, quỹ vắc-xin phòng, chống Covid-19… thể hiện hình thức trách nhiệm xã hội nào của doanh nghiệp?", "o": ["Pháp lý và tuân thủ quy định về kê khai thuế.", "Đạo đức kinh doanh và trung thực với khách hàng.", "Kinh tế và phát triển sản xuất bền vững.", "Nhân văn."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: Đề 5 đáp án.docx · Phần I câu 15 · khoá: gạch chân"}, {"id": "L12-HK1-05-C16", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Doanh nghiệp sản xuất hàng giả, hàng kém chất lượng là đã không thực hiện trách nhiệm xã hội nào của doanh nghiệp?", "o": ["Pháp lý.", "Kinh tế.", "Đạo đức.", "Nhân văn."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: Đề 5 đáp án.docx · Phần I câu 16 · khoá: gạch chân"}, {"id": "L12-HK1-05-C17", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đối với mỗi doanh nghiệp, việc thực hiện tốt trách nhiệm xã hội sẽ góp phần giúp doanh nghiệp tạo dựng được", "o": ["quan hệ phi lợi nhuận trong dài hạn của doanh nghiệp.", "các quan hệ phi pháp với đối tác và khách hàng.", "mối quan hệ miễn thuế và ưu đãi tài chính lâu dài.", "thương hiệu và tên tuổi."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: Đề 5 đáp án.docx · Phần I câu 17 · khoá: gạch chân"}, {"id": "L12-HK1-05-C18", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Nội dung nào dưới đây không thể hiện trách nhiệm xã hội của doanh nghiệp?", "o": ["Cải tiến mẫu mã sản phẩm để tăng khả năng cạnh tranh.", "Duy trì chất lượng sản phẩm theo cam kết với khách hàng.", "Ủng hộ đồng bào bị lũ lụt và thiên tai khu vực miền Trung.", "Liên kết với các nhà phân phối."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: Đề 5 đáp án.docx · Phần I câu 18 · khoá: gạch chân"}, {"id": "L12-HK1-05-C19", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đối với doanh nghiệp, nội dung nào dưới đây thể hiện ý nghĩa của việc thực hiện trách nhiệm xã hội của doanh nghiệp?", "o": ["Tăng lợi thế và khả năng cạnh tranh.", "Góp phần bảo vệ môi trường sống và giảm thiểu ô nhiễm do hoạt động sản xuất gây ra.", "Giúp ổn định cuộc sống cộng đồng.", "Hỗ trợ cộng đồng vượt qua khó khăn"], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: Đề 5 đáp án.docx · Phần I câu 19 · khoá: gạch chân"}, {"id": "L12-HK1-05-C20", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Theo quy định của pháp luật, khi tiến hành kinh doanh, mọi doanh nghiệp đều phải thực hiện nghĩa vụ tuân thủ pháp luật về môi trường là đã thực hiện trách nhiệm xã hội của doanh nghiệp ở hình thức nào dưới đây?", "o": ["Trách nhiệm kinh tế.", "Trách nhiệm pháp lý.", "Trách nhiệm kinh doanh.", "Trách nhiệm từ thiện."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: Đề 5 đáp án.docx · Phần I câu 20 · khoá: gạch chân"}, {"id": "L12-HK1-05-C21", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đọc đoạn thông tin sau:\nNăm 2013 bà Nguyễn Thị A giao kết hợp đồng lao động có thời hạn 24 tháng với trường tiểu học E. Từ ngày 01/1/2015 đến ngày 30/6/2015, bà A nghỉ hưởng chế độ thai sản. Ngày 01/7/2015 trường tiểu học E ban hành quyết định nghỉ việc cho bà A, quyết định có hiệu lực kể từ ngày ký.\nTheo quy định của pháp luật, sau thời gian bà A được trường tiểu học E ban hành quyết định nghỉ việc, bà A có quyền được hưởng loại bảo hiểm nào dưới đây?", "o": ["Bảo hiểm thất nghiệp.", "Bảo hiểm dân sự đối với trách nhiệm bồi thường thiệt hại.", "Trợ cấp tai nạn.", "Trợ cấp thai sản."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: Đề 5 đáp án.docx · Phần I câu 21 · khoá: gạch chân"}, {"id": "L12-HK1-05-C22", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Theo quy định của pháp luật, trong thời gian nghỉ chế độ thai sản b� A được hưởng chế độ bảo hiểm nào dưới đây?", "o": ["Trợ cấp nghề nghiệp.", "Bảo hiểm thất nghiệp.", "Chế độ hưu trí.", "Chế độ thai sản."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: Đề 5 đáp án.docx · Phần I câu 22 · khoá: gạch chân"}, {"id": "L12-HK1-05-C23", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đọc đoạn thông tin sau:\nÔng M đã ấp ủ ý tưởng về việc lắp ráp và kinh doanh ô tô với mục tiêu sẽ đưa ra thị trường những chiếc ô tô mang thương hiệu Việt Nam. Ông nhận thấy thị trường ô tô ở Việt Nam chưa có thương hiệu trong nước trong khi nhu cầu của người dân rất cao, nhà nước có nhiều chính sách ưu đãi để phát triển. Ông luôn chủ động, sáng tạo, nắm bắt cơ hội, vạch ra chiến lược kinh doanh; xây dựng hệ thống quản lí nội bộ công ty chuyên nghiệp.\nNội dung nào dưới đây thể hiện việc ông M đã biết xác định mục tiêu kinh doanh của mình?", "o": ["Xây dựng thương hiệu ô tô Việt.", "Trang bị kiến thức cơ bản về quản trị doanh nghiệp.", "Vận dụng chính sách ưu đãi của nhà nước vào kinh doanh.", "Nắm bắt cơ hội để kinh doanh và mở rộng thị trường."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: Đề 5 đáp án.docx · Phần I câu 23 · khoá: gạch chân"}, {"id": "L12-HK1-05-C24", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Việc làm nào dưới đây thể hiện ông M đã biết phân tích các điều kiện thực hiện ý tưởng kinh doanh?", "o": ["Lắp ráp và kinh doanh ô tô Việt.", "Xây dựng thương hiệu ô tô Việt.", "Nhận thấy nhu cầu trong nước cao.", "Tạo dựng mối quan hệ rộng rãi."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: Đề 5 đáp án.docx · Phần I câu 24 · khoá: gạch chân"}, {"id": "L12-HK1-05-C25", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "dung_sai", "status": "cho_duyet", "q": "Đọc đoạn thông tin sau và cho biết mỗi ý a, b, c, d là Đúng hay Sai. Bà H là lao động tự do sống trên địa bàn tỉnh Y. Sau một thời gian khám bệnh và điều trị tại bệnh viện K, bà H cầm trên tay hóa đơn, chứng từ thanh toán bảo hiểm y tế với số tiền 80 triệu đồng. Bà đã được thanh toán gần một nửa chi phí điều trị, gần 50 triệu đồng, thuộc đối tượng đồng chi trả 20%. Bà nói: cách đây 5 tháng tôi có mua một tấm thẻ bảo hiểm y tế, nhờ có tấm thẻ này mà tôi không trở thành gánh nặng tài chính của các con khi ốm đau.", "o": ["Loại hình bảo hiểm mà bà H mua thẻ thể hiện đặc điểm bảo hiểm tự nguyện.", "Nhờ có thẻ bảo hiểm y tế, bà H được giảm gánh nặng tài chính cho gia đình khi ốm đau.", "Bà H được thanh toán toàn bộ 80 triệu đồng chi phí điều trị.", "Bảo hiểm y tế là loại hình bắt buộc đối với mọi lao động tự do."], "a": [true, true, false, false], "e": "Đáp án: a) Đúng; b) Đúng; c) Sai; d) Sai.", "nguon": "Đề nguồn: Đề 5 đáp án.docx · Phần II câu 1 · khoá: chữ Đúng/Sai trong ý"}, {"id": "L12-HK1-05-C26", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "dung_sai", "status": "cho_duyet", "q": "Đọc đoạn thông tin sau và cho biết mỗi ý a, b, c, d là Đúng hay Sai. Ông N từng tham gia đóng BHXH bắt buộc, sau đó nghỉ khi mới đóng được 15 năm, chưa đủ điều kiện về số năm đóng BHXH để có chế độ hưu trí (tối thiểu 20 năm). Cuối năm 2022, ông quyết định tham gia BHXH tự nguyện và đóng một lần cho những năm còn thiếu. Ít ngày sau ông nhận tháng lương hưu đầu tiên hơn 1,8 triệu đồng và được cấp thẻ BHYT chăm sóc sức khỏe trọn đời.", "o": ["Công dân đóng đủ số năm tham gia bảo hiểm xã hội là sẽ được nhận chế độ hưu trí.", "Ông N cao tuổi nên rút bảo hiểm xã hội một lần sẽ lợi hơn khi đóng tiếp để hưởng hưu trí.", "Ông N chỉ được hưởng chế độ hưu trí và thẻ bảo hiểm y tế để khám bệnh.", "Tham gia bảo hiểm giúp ông N được bảo vệ sức khỏe và yên tâm tài chính khi về già."], "a": [false, false, false, true], "e": "Đáp án: a) Sai; b) Sai; c) Sai; d) Đúng.", "nguon": "Đề nguồn: Đề 5 đáp án.docx · Phần II câu 2 · khoá: chữ Đúng/Sai trong ý"}, {"id": "L12-HK1-05-C27", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "dung_sai", "status": "cho_duyet", "q": "Đọc đoạn thông tin sau và cho biết mỗi ý a, b, c, d là Đúng hay Sai. Công ty D chuyên sản xuất máy móc phục vụ cho nông nghiệp. Từ khi sản xuất kinh doanh có hiệu quả, công ty luôn chú trọng bảo vệ môi trường, thực hiện các biện pháp giảm lượng chất thải như rác, khói bụi, nước xả thải. Công ty còn hợp tác với tổ chức bảo tồn thiên nhiên quốc tế và Uỷ ban nhân dân tỉnh K để bảo tồn các vùng đất ngập nước tự nhiên. Công ty đầu tư xây dựng ba công trình công cộng cho cộng đồng.", "o": ["Biện pháp giảm chất thải, xử lí rác và khói bụi là trách nhiệm pháp lí khi kinh doanh.", "Hợp tác với tổ chức bảo tồn thiên nhiên quốc tế là thể hiện hội nhập kinh tế quốc tế.", "Bảo tồn vùng đất ngập nước là thể hiện trách nhiệm kinh tế của doanh nghiệp.", "Đóng góp xây dựng các công trình công cộng cho cộng đồng phù hợp với trách nhiệm nhân văn."], "a": [true, false, false, true], "e": "Đáp án: a) Đúng; b) Sai; c) Sai; d) Đúng.", "nguon": "Đề nguồn: Đề 5 đáp án.docx · Phần II câu 3 · khoá: chữ Đúng/Sai trong ý"}, {"id": "L12-HK1-05-C28", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "dung_sai", "status": "cho_duyet", "q": "Đọc đoạn thông tin sau và cho biết mỗi ý a, b, c, d là Đúng hay Sai. Vợ chồng anh P và chị Q đang tìm mua căn nhà đầu tiên. Hai người đều có công việc tốt, có khả năng mua căn nhà như mong muốn nhưng vẫn muốn đảm bảo việc có thể duy trì các khoản thanh toán thế chấp trong tương lai và lối sống hiện tại.", "o": ["Xác định mục tiêu tài chính là mua căn nhà và duy trì khoản thanh toán thế chấp trong tương lai.", "Ưu tiên chi tiêu cho nhu cầu thiết yếu là việc cần làm khi quản lí thu chi.", "Chi tiêu dựa trên số tiền có sẵn là đúng nguyên tắc quản lí thu chi.", "Chi tiêu cho sở thích của hai vợ chồng là nên làm khi quản lí thu chi."], "a": [true, true, false, false], "e": "Đáp án: a) Đúng; b) Đúng; c) Sai; d) Sai.", "nguon": "Đề nguồn: Đề 5 đáp án.docx · Phần II câu 4 · khoá: chữ Đúng/Sai trong ý"}]}, {"id": "L12-HK1-06", "loai": "khoi", "khoi": 12, "hoc_ki": 1, "bo": "HK1", "ten_bo": "học kì I", "so_de": 6, "ten": "Lớp 12 · học kì I · Đề 6", "pham_vi": "Tổng hợp Bài 1–7 (đề nguồn «HỌC KÌ 1 › tong_hop_1_7») · file nguồn: Đề 6 đáp án.docx", "thoi_gian": 50, "cau_truc": "24 câu trắc nghiệm + 4 câu đúng/sai (mỗi câu 4 ý)", "status": "cho_duyet", "khoa": {"1 nguồn": 28}, "sua": "", "cau": [{"id": "L12-HK1-06-C01", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Trong các quan hệ kinh tế quốc tế, việc tham gia của mỗi quốc gia không được thực hiện ở cấp độ nào dưới đây?", "o": ["Quy chế miễn thị thực.", "Liên minh kinh tế với chính sách thương mại và thuế quan chung.", "Thị trường chung.", "Liên minh thuế quan."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: Đề 6 đáp án.docx · Phần I câu 1 · khoá: gạch chân"}, {"id": "L12-HK1-06-C02", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Hội nhập kinh tế khu vực không được thực hiện giữa các quốc gia có đặc điểm nào dưới đây?", "o": ["Tương đồng về địa lý.", "Đang chiến tranh với nhau.", "Có sự phù hợp về văn hóa.", "Cùng chung mục tiêu phát triển và hợp tác kinh tế lâu dài."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: Đề 6 đáp án.docx · Phần I câu 2 · khoá: gạch chân"}, {"id": "L12-HK1-06-C03", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Khi tham gia vào quá trình hội nhập kinh tế quốc tế song phương, các quốc gia không bắt buộc phải thủ nguyên tắc nào dưới đây?", "o": ["Tôn trọng vị thế của nhau.", "Bình đẳng cùng có lợi.", "Phải sử dụng ngôn ngữ của nhau.", "Tôn trọng độc lập chủ quyền và toàn vẹn lãnh thổ của nhau."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: Đề 6 đáp án.docx · Phần I câu 3 · khoá: gạch chân"}, {"id": "L12-HK1-06-C04", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Về mặt tài chính, khi các doanh nghiệp tham gia các loại hình bảo hiểm sẽ giúp doanh nghiệp được", "o": ["thâu tóm thị trường.", "miễn các loại thuế.", "ổn định và an toàn.", "xuất khẩu ưu đãi."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: Đề 6 đáp án.docx · Phần I câu 4 · khoá: gạch chân"}, {"id": "L12-HK1-06-C05", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Ông M được cơ quan có thẩm quyền ra quyết định nghỉ hưu theo quy định, sau khi hoàn thiện các thủ tục, ông M được nhận chế độ hưu trí hàng tháng. Ông M đã tham gia loại hình bảo hiểm nào dưới đây?", "o": ["Bảo hiểm y tế.", "Bảo hiểm xã hội.", "Bảo hiểm thương mại.", "Bảo hiểm thất nghiệp."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: Đề 6 đáp án.docx · Phần I câu 5 · khoá: gạch chân"}, {"id": "L12-HK1-06-C06", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Loại hình bảo hiểm nào dưới đây thuộc lĩnh vực chăm sóc sức khoẻ cộng đồng do Nhà nước thực hiện; theo đó, người tham gia bảo hiểm sẽ được chi trả một phần hoặc toàn bộ chi phí thăm khám, điều trị, phục hồi sức khoẻ nếu không may xảy ra tai nạn hoặc bệnh tật?", "o": ["Bảo hiểm y tế.", "Bảo hiểm con người.", "Bảo hiểm xã hội", "Bảo hiểm thất nghiệp."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: Đề 6 đáp án.docx · Phần I câu 6 · khoá: gạch chân"}, {"id": "L12-HK1-06-C07", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Nội dung nào dưới đây không thể hiện vai trò của bảo hiểm đối với mỗi cá nhân và gia đình?", "o": ["Ổn định vật chất, tinh thần.", "Chia sẻ khi gặp rủi ro.", "Đảm bảo an toàn tài chính.", "Gia tăng bạo lực giới."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: Đề 6 đáp án.docx · Phần I câu 7 · khoá: gạch chân"}, {"id": "L12-HK1-06-C08", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đối với người tham gia bảo hiểm, một trong những vai trò của bảo hiểm đó là giúp mỗi cá nhân tham gia bảo hiểm nếu không may gặp rủi ro có thể", "o": ["chuyển giao rủi ro cho cơ quan bảo hiểm.", "được mọi người giúp đỡ, hỗ trợ thiệt hại.", "yêu cầu được bồi thường cho bản thân.", "xác định được phần thiệt hại của bản thân."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: Đề 6 đáp án.docx · Phần I câu 8 · khoá: gạch chân"}, {"id": "L12-HK1-06-C09", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Với loại hình bảo hiểm xã hội, người lao động sẽ nhận được quyền lợi bảo hiểm dựa trên cơ sở nào dưới đây?", "o": ["Mức đóng vào quỹ bảo hiểm xã hội.", "Vị thế xã hội và địa vị kinh tế của người lao động lúc tham gia.", "Địa vị xã hội khi tham gia.", "Nhu cầu hưởng bảo hiểm xã hội."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: Đề 6 đáp án.docx · Phần I câu 9 · khoá: gạch chân"}, {"id": "L12-HK1-06-C10", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Theo quy định của pháp luật, với người tham gia loại hình bảo hiểm xã hội trường hợp nào dưới đây người tham gia bảo hiểm không được nhận quyền lợi bảo hiểm?", "o": ["Do hết tuổi lao động theo quy định.", "Do bị sa thải vì vi phạm kỷ luật.", "Ốm đau hoặc tai nạn lao động.", "Thai sản hoặc bệnh nghề nghiệp."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: Đề 6 đáp án.docx · Phần I câu 10 · khoá: gạch chân"}, {"id": "L12-HK1-06-C11", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Nội dung nào dưới đây thể hiện việc chủ thể đã biết phân tích các điều kiện thực hiện kế hoạch kinh doanh?", "o": ["Mở rộng hoạt động quảng cáo trực tuyến.", "Dự kiến kinh doanh thực phẩm sạch.", "Sản phẩm phù hợp với nhu cầu người tiêu dùng.", "Phấn đấu thu hồi vốn sau sáu tháng kinh doanh."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: Đề 6 đáp án.docx · Phần I câu 11 · khoá: gạch chân"}, {"id": "L12-HK1-06-C12", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Khi phân tích yếu tố về thị trường để lập kế hoạch kinh doanh, các chủ thể không phân tích yếu tố nào dưới đây?", "o": ["Xu hướng tiêu dùng của người dân trong khu vực.", "Tốc độ tăng trưởng của thị trường trong năm.", "Quy mô thị trường và nhu cầu khách hàng hiện tại.", "Xu hướng ảnh hưởng."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: Đề 6 đáp án.docx · Phần I câu 12 · khoá: gạch chân"}, {"id": "L12-HK1-06-C13", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Bản mô tả những nội dung cơ bản về định hướng, mục tiêu, nguồn lực, tài chính, kế hoạch bán hàng.... nhằm giúp chủ thể kinh doanh xác định được các nhiệm vụ để thực hiện mục tiêu đề ra được gọi l�", "o": ["quản lí kinh doanh và tổ chức nhân sự trong doanh nghiệp.", "quản lí tài chính và kiểm soát chi phí của doanh nghiệp.", "kế hoạch kinh doanh.", "kế hoạch tài chính và kế hoạch huy động vốn đầu tư."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: Đề 6 đáp án.docx · Phần I câu 13 · khoá: gạch chân"}, {"id": "L12-HK1-06-C14", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Kế hoạch kinh doanh của các chủ thể thể kinh doanh cần có nội dung nào dưới đây?", "o": ["Tóm tắt kế hoạch kinh doanh.", "Tóm tắt quá trình đã kinh doanh.", "Tóm tắt thành quả khi kinh doanh.", "Tóm tắt những thất bại khi kinh doanh."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: Đề 6 đáp án.docx · Phần I câu 14 · khoá: gạch chân"}, {"id": "L12-HK1-06-C15", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Tạo việc làm, thu nhập và cơ hội phát triển cho người lao động, cung ứng nhiều sản phẩm có chất lượng cho người tiêu dùng là thể hiện hình thức trách nhiệm xã hội nào của doanh nghiệp?", "o": ["Đạo đức.", "Nhân văn.", "Kinh tế.", "Pháp lý."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: Đề 6 đáp án.docx · Phần I câu 15 · khoá: gạch chân"}, {"id": "L12-HK1-06-C16", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Việc doanh doanh thực hiện tốt những chính sách và việc làm cụ thể nhằm mang lại ảnh hưởng tích cực đến xã hội đóng góp cho các mục tiêu xã hội và sự phát triển bền vững của đất nước là thể hiện nội dung nào dưới đây của doanh nghiệp?", "o": ["Trách nhiệm tiêu dùng.", "Trách nhiệm sản xuất.", "Trách nhiệm xã hội.", "Trách nhiệm phân phối."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: Đề 6 đáp án.docx · Phần I câu 16 · khoá: gạch chân"}, {"id": "L12-HK1-06-C17", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Thực hiện tốt trách nhiệm xã hội sẽ đem lại lợi ích nào dưới đây đối với doanh nghiệp?", "o": ["Xây dựng thương hiệu tích cực.", "Giảm khả năng cạnh tranh và làm suy giảm uy tín trên thị trường.", "Được nhà nước hỗ trợ thuế.", "Thúc đẩy nguy cơ phá sản."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: Đề 6 đáp án.docx · Phần I câu 17 · khoá: gạch chân"}, {"id": "L12-HK1-06-C18", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Trong quá trình sản xuất kinh doanh, giám đốc công ty M luôn luôn chỉ đạo nhân viên phải không ngừng cải tiến kỹ thuật, hợp lý hóa sản xuất để tạo ra những sản phẩm chất lượng, an toàn là đã góp phần thực hiện trách nhiệm xã hội của doanh nghiệp ở hình thức nào dưới đây?", "o": ["Trách nhiệm pháp lý.", "Trách nhiệm đạo đức.", "Trách nhiệm kinh tế.", "Trách nhiệm nhân văn."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: Đề 6 đáp án.docx · Phần I câu 18 · khoá: gạch chân"}, {"id": "L12-HK1-06-C19", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Công dân hoàn thiện đầy đủ điều kiện theo quy định của pháp luật trước khi tiến hành các hoạt động kinh doanh là đã thực hiện trách nhiệm xã hội của doanh nghiệp ở hình thức nào dưới đây?", "o": ["Trách nhiệm pháp lý.", "Trách nhiệm kinh doanh.", "Trách nhiệm nhân văn.", "Trách nhiệm từ thiện."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: Đề 6 đáp án.docx · Phần I câu 19 · khoá: gạch chân"}, {"id": "L12-HK1-06-C20", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Bên cạnh việc phát triển sản xuất, các doanh nghiệp tích cực tham gia các hoạt động nhân đạo là đã thể hiện trách nhiệm nào dưới đây của doanh nghiệp?", "o": ["Trách nhiệm sản xuất.", "Trách nhiệm tiêu dùng.", "Trách nhiệm nhân văn.", "Trách nhiệm pháp lý."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: Đề 6 đáp án.docx · Phần I câu 20 · khoá: gạch chân"}, {"id": "L12-HK1-06-C21", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đọc đoạn thông tin sau:\nHệ thống bảo hiểm xã hội được quan tâm phát triển, nhằm chia sẻ rủi ro và trợ giúp thiết thực cho những người tham gia. Số người tham gia bảo hiểm bắt buộc tăng nhanh, từ 4,8 triệu (năm 2001) lên 9,7 triệu (năm 2011). Kinh phí trợ giúp thường xuyên từ ngân sách nhà nước tăng từ 113 tỉ đồng cho hơn 180 nghìn người (năm 2001) lên 4.500 tỉ đồng cho hơn 1,6 triệu người (năm 2010).\nViệc nhà nước triển khai chính sách bảo hiểm xã hội và chương trình xóa đói giảm nghèo là thực hiện chỉ tiêu nào dưới đây của phát triển kinh tế?", "o": ["Chỉ số tiến bộ xã hội.", "Tổng thu nhập quốc dân.", "Tổng sản phẩm quốc dân.", "Thu nhập theo đầu người."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: Đề 6 đáp án.docx · Phần I câu 21 · khoá: gạch chân"}, {"id": "L12-HK1-06-C22", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Hệ thống bảo hiểm là một trong những trụ cột của chính sách an sinh xã hội nào dưới đây?", "o": ["Chính sách việc làm.", "Chính sách thu nhập.", "Chính sách giảm nghèo.", "Chính sách bảo hiểm."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: Đề 6 đáp án.docx · Phần I câu 22 · khoá: gạch chân"}, {"id": "L12-HK1-06-C23", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đọc đoạn thông tin sau:\nĐầu năm, vợ chồng anh A thống nhất đặt mục tiêu mỗi tháng sẽ dành 60% thu nhập cho các chi tiêu thiết yếu, tiết kiệm 20% thu nhập gia đình để có đủ tiền mua xe máy mới cho vợ. Hai tháng nay anh A bị mất việc, thu nhập giảm sút. Để phụ giúp gia đình, anh A đã tham gia chạy xe ôm và nhận giao hàng. Nhờ đó mà sau một năm vợ chồng anh A đã hoàn thành mục tiêu đặt ra. Hai vợ chồng quyết tâm năm năm tới sẽ mua được một mảnh đất để làm cửa hàng cho thuê.\nViệc tham gia chạy xe ôm và giao hàng cho các cửa hàng là hoạt động góp phần tạo ra thu nhập nào dưới đây?", "o": ["Thừa kế tài sản từ người thân trong gia đình.", "Bảo hiểm xã hội và bảo hiểm thất nghiệp.", "Thụ động từ lãi tiền gửi và cho thuê tài sản.", "Chủ động."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: Đề 6 đáp án.docx · Phần I câu 23 · khoá: gạch chân"}, {"id": "L12-HK1-06-C24", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Nội dung nào dưới đây thể hiện việc thực hiện kế hoạch quản lý thu, chi trong gia đình anh A?", "o": ["Điều chỉnh các khoản chi.", "Đặt mục tiêu mua xe.", "Bổ sung các khoản tiết kiệm.", "Tham gia tìm kiếm việc làm."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: Đề 6 đáp án.docx · Phần I câu 24 · khoá: gạch chân"}, {"id": "L12-HK1-06-C25", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "dung_sai", "status": "cho_duyet", "q": "Đọc đoạn thông tin sau và cho biết mỗi ý a, b, c, d là Đúng hay Sai. Kể từ khi chính thức gia nhập WTO, Việt Nam đã ghi nhận những thành tựu về phát triển kinh tế. Việt Nam trở thành nền kinh tế có độ mở cao, tới 200% GDP và cải thiện cán cân thương mại hàng hóa, chuyển từ nhập siêu sang xuất siêu trong giai đoạn 2016 - 2020. Năm 2022, cán cân thương mại xuất siêu đạt 12,4 tỷ USD, là năm thứ 7 liên tiếp cán cân thương mại hàng hóa ở mức thặng dư.", "o": ["Việt Nam có độ mở cao tới 200% GDP nhờ gia nhập WTO.", "Hội nhập WTO khiến cán cân thương mại Việt Nam chuyển từ xuất siêu sang nhập siêu.", "Năm 2022 xuất siêu 12,4 tỷ USD, là năm thứ 7 liên tiếp cán cân thương mại thặng dư.", "Việt Nam là một trong 20 nền thương mại lớn nhất thế giới."], "a": [true, false, true, true], "e": "Đáp án: a) Đúng; b) Sai; c) Đúng; d) Đúng.", "nguon": "Đề nguồn: Đề 6 đáp án.docx · Phần II câu 1 · khoá: chữ Đúng/Sai trong ý"}, {"id": "L12-HK1-06-C26", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "dung_sai", "status": "cho_duyet", "q": "Đọc đoạn thông tin sau và cho biết mỗi ý a, b, c, d là Đúng hay Sai. Trong năm 2023 toàn tỉnh M đã giải quyết việc làm mới cho hơn 8.000 lao động; trong 5 năm đã tạo việc làm cho 41.394 lao động, đạt 103% so với kế hoạch. Tỉ lệ thất nghiệp ở khu vực thành thị giảm từ 5,2% năm xuống còn 4,54%. Kết quả giảm nghèo của toàn tỉnh trong 5 năm đã vượt mục tiêu đề ra, giảm từ 38.085 hộ nghèo xuống còn 18.048 hộ nghèo.", "o": ["Tỉ lệ thất nghiệp thành thị giảm từ 5,2% xuống 4,54% là hiệu quả của chính sách việc làm.", "Số hộ nghèo của tỉnh M giảm hơn 25.000 hộ trong 5 năm.", "Chính sách giảm nghèo của tỉnh M làm gia tăng phân hóa giàu nghèo.", "Tỉ lệ hộ nghèo trước khi thực hiện chương trình là 28,4% số hộ."], "a": [true, false, false, true], "e": "Đáp án: a) Đúng; b) Sai; c) Sai; d) Đúng.", "nguon": "Đề nguồn: Đề 6 đáp án.docx · Phần II câu 2 · khoá: chữ Đúng/Sai trong ý"}, {"id": "L12-HK1-06-C27", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "dung_sai", "status": "cho_duyet", "q": "Đọc đoạn thông tin sau và cho biết mỗi ý a, b, c, d là Đúng hay Sai. Doanh nghiệp C kinh doanh trong ngành hàng xuất khẩu thuỷ hải sản. Doanh nghiệp quan tâm tạo việc làm thường xuyên cho người lao động với mức lương, thưởng xứng đáng và xây dựng một môi trường lao động an toàn. Trong nhiều năm qua, công ty thường xuyên thực hiện hoạt động quyên góp từ thiện giúp đỡ nhân dân các vùng gặp khó khăn, hoạn nạn. Công ty đã phát động phong trào “Vì miền Trung thân yêu”, nhằm chia sẻ khó khăn với đồng bào các tỉnh miền Trung vượt qua những cơn lũ lụt.", "o": ["Hoạt động quyên góp từ thiện góp phần thực hiện chính sách an sinh xã hội của doanh nghiệp.", "Công ty C đã thực hiện tốt trách nhiệm kinh tế khi kinh doanh qua hoạt động quyên góp này.", "Quan tâm tạo việc làm thường xuyên cho người lao động là phù hợp với trách nhiệm pháp lý của doanh nghiệp.", "Ủng hộ chương trình “Vì miền Trung thân yêu” là phù hợp với trách nhiệm nhân văn từ thiện của doanh nghiệp."], "a": [true, false, false, true], "e": "Đáp án: a) Đúng; b) Sai; c) Sai; d) Đúng.", "nguon": "Đề nguồn: Đề 6 đáp án.docx · Phần II câu 3 · khoá: chữ Đúng/Sai trong ý"}, {"id": "L12-HK1-06-C28", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "dung_sai", "status": "cho_duyet", "q": "Đọc đoạn thông tin sau và cho biết mỗi ý a, b, c, d là Đúng hay Sai. Vợ chồng anh N có tổng thu nhập từ 20 – 25 triệu đồng/tháng. Kể từ khi mới kết hôn, anh chị đã thống nhất cách thức kiểm soát thu, chi. Mọi nguồn thu của các thành viên trong gia đình đều được ghi chép lại và người vợ sẽ giữ tiền. Anh chị còn đưa ra 4 cách kiểm soát nguồn chi: chỉ mua sắm vào những ngày quy định, chi tiêu có mục đích, tạo danh sách mua sắm trước khi mua và tạo ra giới hạn chi tiêu.", "o": ["Vợ chồng anh N không xác định mục tiêu tài chính rõ ràng.", "Kiên trì thực hiện 4 cách kiểm soát nguồn chi làm chi tiêu trong gia đình bị hạn chế.", "Số tiền 20–25 triệu đồng/tháng là căn cứ để xây dựng kế hoạch quản lí thu chi.", "Vợ chồng anh N không cần điều chỉnh kế hoạch quản lí thu chi vì biện pháp đã phù hợp."], "a": [false, false, true, false], "e": "Đáp án: a) Sai; b) Sai; c) Đúng; d) Sai.", "nguon": "Đề nguồn: Đề 6 đáp án.docx · Phần II câu 4 · khoá: chữ Đúng/Sai trong ý"}]}, {"id": "L12-HK1-07", "loai": "khoi", "khoi": 12, "hoc_ki": 1, "bo": "HK1", "ten_bo": "học kì I", "so_de": 7, "ten": "Lớp 12 · học kì I · Đề 7", "pham_vi": "Bài 5–7 (đề nguồn «HỌC KÌ 1 › bai_5_7») · file nguồn: Đề 1 đáp án.docx", "thoi_gian": 50, "cau_truc": "24 câu trắc nghiệm + 4 câu đúng/sai (mỗi câu 4 ý)", "status": "cho_duyet", "khoa": {"1 nguồn": 28}, "sua": "", "cau": [{"id": "L12-HK1-07-C01", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Việc các chủ thể kinh tế xác định các vấn đề như kinh doanh mặt hàng gì, đối tượng khách hàng là ai, họ có nhu cầu gì là thực hiện nội dung nào dưới đây của việc lập kế hoạch kinh doanh?", "o": ["Xác định mục tiêu kinh doanh.", "Xác định chiến lược kinh doanh.", "Xác định ý tưởng kinh doanh.", "Xác định điều kiện thực hiện."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: Đề 1 đáp án.docx · Phần I câu 1 · khoá: gạch chân"}, {"id": "L12-HK1-07-C02", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Để quá trình kinh doanh diễn ra hiệu quả, kế hoạch kinh doanh của các chủ thể cần xác định được", "o": ["số thuế phải đóng.", "ý tưởng kinh doanh.", "số tiền sẽ thu lợi.", "thời gian thành công."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: Đề 1 đáp án.docx · Phần I câu 2 · khoá: gạch chân"}, {"id": "L12-HK1-07-C03", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Khi các chủ thể đặt ra những kế hoạch và mục tiêu cụ thể sẽ đạt được khi tiến hành kinh doanh là đã thực hiện nội dung nào dưới đây của lập kế hoạch kinh doanh?", "o": ["Xác định điều kiện thực hiện.", "Xác định ý tưởng kinh doanh.", "Xác định chiến lược kinh doanh.", "Xác định mục tiêu kinh doanh."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: Đề 1 đáp án.docx · Phần I câu 3 · khoá: gạch chân"}, {"id": "L12-HK1-07-C04", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Bước khởi đầu trong việc lập kế hoạch kinh doanh là các chủ thể phải xác định được", "o": ["ý tưởng kinh doanh.", "chiến lược kinh doanh.", "các rủi ro gặp phải.", "mục tiêu kinh doanh."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: Đề 1 đáp án.docx · Phần I câu 4 · khoá: gạch chân"}, {"id": "L12-HK1-07-C05", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đối với doanh nghiệp, nội dung nào dưới đây thể hiện ý nghĩa của việc thực hiện trách nhiệm xã hội của doanh nghiệp?", "o": ["Tăng lợi thế và khả năng cạnh tranh.", "Góp phần bảo vệ môi trường sống và giảm thiểu ô nhiễm do hoạt động sản xuất gây ra.", "Giúp ổn định cuộc sống cộng đồng.", "Hỗ trợ cộng đồng vượt qua khó khăn"], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: Đề 1 đáp án.docx · Phần I câu 5 · khoá: gạch chân"}, {"id": "L12-HK1-07-C06", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Theo quy định của pháp luật, khi tiến hành kinh doanh, mọi doanh nghiệp đều phải thực hiện nghĩa vụ tuân thủ pháp luật về môi trường là đã thực hiện trách nhiệm xã hội của doanh nghiệp ở hình thức nào dưới đây?", "o": ["Trách nhiệm kinh tế.", "Trách nhiệm pháp lý.", "Trách nhiệm kinh doanh.", "Trách nhiệm từ thiện."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: Đề 1 đáp án.docx · Phần I câu 6 · khoá: gạch chân"}, {"id": "L12-HK1-07-C07", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Tạo việc làm, thu nhập và cơ hội phát triển cho người lao động, cung ứng nhiều sản phẩm có chất lượng cho người tiêu dùng là thể hiện hình thức trách nhiệm xã hội nào của doanh nghiệp?", "o": ["Đạo đức.", "Nhân văn.", "Kinh tế.", "Pháp lý."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: Đề 1 đáp án.docx · Phần I câu 7 · khoá: gạch chân"}, {"id": "L12-HK1-07-C08", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Việc doanh doanh thực hiện tốt những chính sách và việc làm cụ thể nhằm mang lại ảnh hưởng tích cực đến xã hội đóng góp cho các mục tiêu xã hội và sự phát triển bền vững của đất nước là thể hiện nội dung nào dưới đây của doanh nghiệp?", "o": ["Trách nhiệm tiêu dùng.", "Trách nhiệm sản xuất.", "Trách nhiệm xã hội.", "Trách nhiệm phân phối."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: Đề 1 đáp án.docx · Phần I câu 8 · khoá: gạch chân"}, {"id": "L12-HK1-07-C09", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Thực hiện tốt trách nhiệm xã hội sẽ đem lại lợi ích nào dưới đây đối với doanh nghiệp?", "o": ["Xây dựng thương hiệu tích cực.", "Giảm khả năng cạnh tranh và làm suy giảm uy tín trên thị trường.", "Được nhà nước hỗ trợ thuế.", "Thúc đẩy nguy cơ phá sản."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: Đề 1 đáp án.docx · Phần I câu 9 · khoá: gạch chân"}, {"id": "L12-HK1-07-C10", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Trong quá trình sản xuất kinh doanh, giám đốc công ty M luôn luôn chỉ đạo nhân viên phải không ngừng cải tiến kỹ thuật, hợp lý hóa sản xuất để tạo ra những sản phẩm chất lượng, an toàn là đã góp phần thực hiện trách nhiệm xã hội của doanh nghiệp ở hình thức nào dưới đây?", "o": ["Trách nhiệm pháp lý.", "Trách nhiệm đạo đức.", "Trách nhiệm kinh tế.", "Trách nhiệm nhân văn."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: Đề 1 đáp án.docx · Phần I câu 10 · khoá: gạch chân"}, {"id": "L12-HK1-07-C11", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Phát biểu nào dưới đây là đúng về sự cần thiết phải quản lý thu chi trong gia đình.", "o": ["Lập kế hoạch thu chi trong gia đình giúp mỗi thành viên chi tiêu không giới hạn.", "Lập kế hoạch thu chi trong gia đình giúp hạn chế các thói quen chi tiêu tích cực.", "Lập kế hoạch thu chi trong gia đình là giải pháp để cân bằng tài chính gia đình.", "Lập kế hoạch thu chi trong gia đình nhằm kiểm soát nguồn chi tiêu của người vợ."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: Đề 1 đáp án.docx · Phần I câu 11 · khoá: gạch chân"}, {"id": "L12-HK1-07-C12", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Thực hiện việc quản lý thu chi trong gia đình giúp mỗi gia đình chủ động thực hiện được kế hoạch tài chính", "o": ["dòng họ và các thành viên trong đại gia đình.", "gia đình.", "cá nhân và các khoản tiền riêng của từng người.", "nhà nước và các cơ quan quản lí tài chính."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: Đề 1 đáp án.docx · Phần I câu 12 · khoá: gạch chân"}, {"id": "L12-HK1-07-C13", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Khi xác định mục tiêu tài chính trong gia đình, cần tránh xác định những mục tiêu tài chính có tính chất nào dưới đây?", "o": ["Trìu tượng.", "Có khả thi.", "Đo lường được.", "Cụ thể."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: Đề 1 đáp án.docx · Phần I câu 13 · khoá: gạch chân"}, {"id": "L12-HK1-07-C14", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Nội dung nào dưới đây không phản ánh sự cần thiết phải quản lí thu, chi trong gia đình?", "o": ["Tăng số tiền mặt cho hoạt động mua sắm hằng ngày.", "Tăng chất lượng cuộc sống của gia đình.", "Kiểm soát được nguồn thu, chi trong gia đình.", "Dự phòng cho các trường hợp khẩn cấp và tương lai."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: Đề 1 đáp án.docx · Phần I câu 14 · khoá: gạch chân"}, {"id": "L12-HK1-07-C15", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Nội dung nào dưới đây không thể hiện việc xác định mục tiêu tài chính trong gia đình?", "o": ["Mục tiêu tài chính ngắn hạn.", "Mục tiêu tài chính dài hạn.", "Mục tiêu tài chính trung hạn.", "Mục tiêu tài chính vô hạn."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: Đề 1 đáp án.docx · Phần I câu 15 · khoá: gạch chân"}, {"id": "L12-HK1-07-C16", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Việc xác định các nguồn thu nhập trong gia đình sẽ giúp mỗi gia đình biết được nội dung nào dưới đây?", "o": ["Mối quan hệ giữa các thành viên.", "Tình hình việc làm và thu nhập.", "Tình hình tài chính hiện tại.", "Tình trạng hôn nhân gia đình."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: Đề 1 đáp án.docx · Phần I câu 16 · khoá: gạch chân"}, {"id": "L12-HK1-07-C17", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Nội dung nào dưới đây được liệt kê vào nguồn thu nhập của gia đình khi xây dựng kế hoạch thu chi trong gia đình?", "o": ["Chi tiêu cho nhu cầu thiết yếu.", "Thu nhập từ hoạt động kinh doanh.", "Thu nhập từ lương của bố mẹ và các khoản thu nhập chi tiêu hằng ngày.", "Thu nhập tiền lãi gửi ngân hàng."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: Đề 1 đáp án.docx · Phần I câu 17 · khoá: gạch chân"}, {"id": "L12-HK1-07-C18", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Mục đích của quản lí thu, chi trong gia đình biểu hiện ở nội dung nào dưới đây?", "o": ["Chủ động kiểm soát chi tiêu của bản thân.", "Chủ động thực hiện kế hoạch tài chính của gia đình.", "Đảm bảo ổn định dòng tiền cho việc mua sắm của gia đình.", "Tối ưu hoá sử dụng khoản thu của bản thân."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: Đề 1 đáp án.docx · Phần I câu 18 · khoá: gạch chân"}, {"id": "L12-HK1-07-C19", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Thực hiện việc quản lý thu chi trong gia đình không mang lại lợi ích nào dưới đây?", "o": ["Kiểm soát thu chi hiệu quả.", "Giúp cân bằng tài chính.", "Hạn chế quan hệ gia đình.", "Vượt qua rủi ro tài chính."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: Đề 1 đáp án.docx · Phần I câu 19 · khoá: gạch chân"}, {"id": "L12-HK1-07-C20", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Nội dung nào dưới đây thể hiện việc xác định các nguồn thu nhập khi xây dựng kế hoạch chi tiêu trong gia đình?", "o": ["Ghi chép các khoản chi tiêu hàng ngày.", "Thống nhất tỷ lệ phân chia các khoản.", "Chủ động tiềm kiếm nguồn thu nhập.", "Xác định khoản chi tiêu thiết yếu."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: Đề 1 đáp án.docx · Phần I câu 20 · khoá: gạch chân"}, {"id": "L12-HK1-07-C21", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đọc đoạn thông tin sau:\nĐể vận hành quán cà phê, anh H xác định ngoài chủ quán có 8 nhân viên; Chủ quán: người trực tiếp quản lí và điều hành 24/7; Tiếp tân: thu tiền và in hoá đơn; Đầu bếp: pha chế nước uống và chế biến món ăn. Quán hoạt động từ 6 giờ đến 23 giờ nên đội ngũ được chia thành hai ca, mỗi ca 4 người.\nThông tin trên đề cập đến yếu tố nào dưới đây khi tiến hành đánh giá các điều kiện thực hiện hoạt động kinh doanh?", "o": ["Thị trường.", "Khách hàng.", "Sản phẩm.", "Nhân sự."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: Đề 1 đáp án.docx · Phần I câu 21 · khoá: gạch chân"}, {"id": "L12-HK1-07-C22", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Anh H đã thực hiện nội dung nào dưới đây của lập kế hoạch kinh doanh?", "o": ["Xác định chiến lược kinh doanh.", "Phân tích các điều kiện kinh doanh.", "Xác định mục tiêu kinh doanh.", "Đánh giá các yếu tố rủi ro gặp phải."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: Đề 1 đáp án.docx · Phần I câu 22 · khoá: gạch chân"}, {"id": "L12-HK1-07-C23", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đọc đoạn thông tin sau:\nCông ty V chuyên sản xuất kinh doanh các sản phẩm sữa, thường xuyên cải tiến mẫu mã, đảm bảo chất lượng sản phẩm cung cấp ra thị trường, kê khai và nộp thuế đầy đủ. Doanh nghiệp đã tham gia chương trình sữa học đường, mang sữa đến các trường mầm non, tiểu học tại nhiều địa phương, phát động cán bộ nhân viên quyên góp, giúp đỡ người dân vùng bị thiên tai vượt qua khó khăn.\nNội dung nào dưới đây phản ánh việc thực hiện trách nhiệm pháp lý của công ty V?", "o": ["Cải tiễn mẫu mã sản phẩm.", "Đảm bảo chất lượng sản phẩm.", "Kê khai và nộp thuế đầy đủ.", "Tham gia dự án sữa miễn phí."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: Đề 1 đáp án.docx · Phần I câu 23 · khoá: gạch chân"}, {"id": "L12-HK1-07-C24", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Hoạt động tham gia chương trình sữa học đường, mang sữa đến các trường mầm non, tiểu học tại nhiều địa phương là thể hiện trách nhiệm nào dưới đây của công ty?", "o": ["Trách nhiệm pháp lý khi tuân thủ các quy định về sữa học đường.", "Trách nhiệm nhân văn.", "Trách nhiệm đạo đức.", "Trách nhiệm kinh tế."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: Đề 1 đáp án.docx · Phần I câu 24 · khoá: gạch chân"}, {"id": "L12-HK1-07-C25", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "dung_sai", "status": "cho_duyet", "q": "Đọc đoạn thông tin sau và cho biết mỗi ý a, b, c, d là Đúng hay Sai. Sau khi tốt nghiệp đại học ngành công nghệ sinh học, với lợi thế là nhà gần các trường đại học, lại có diện tích đất lớn, chị D quyết định lập nghiệp bằng con đường kinh doanh sản phẩm cây cảnh mini với mong muốn sau hai năm sẽ thành lập một doanh nghiệp phân phối các sản phẩm này. Đây là lĩnh vực kinh doanh không đòi hỏi vốn lớn, trong khi thị trường là các bạn sinh viên có nhu cầu khá cao. Do thời gian đầu chưa có nhiều kinh nghiệm, sản phẩm nhiều cây gặp sâu bệnh chết. Từ thực tế kinh doanh, chị quyết định mở rộng sản xuất và đầu tư thêm nhiều cửa hàng mới.", "o": ["Chị D xác định ý tưởng kinh doanh dựa trên lợi thế nội tại như kiến thức công nghệ sinh học và mặt bằng gần trường.", "Mục tiêu sau hai năm thành lập doanh nghiệp là không hợp lý.", "Chị D không phân tích điều kiện thị trường và tài chính khi thực hiện ý tưởng kinh doanh.", "Lập kế hoạch kinh doanh giúp chị D phát huy tốt các lợi thế của mình."], "a": [true, false, false, true], "e": "Đáp án: a) Đúng; b) Sai; c) Sai; d) Đúng.", "nguon": "Đề nguồn: Đề 1 đáp án.docx · Phần II câu 1 · khoá: chữ Đúng/Sai trong ý"}, {"id": "L12-HK1-07-C26", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "dung_sai", "status": "cho_duyet", "q": "Đọc đoạn thông tin sau và cho biết mỗi ý a, b, c, d là Đúng hay Sai. Công ty cổ phần B sản xuất hàng đồ chơi trẻ em. Từ nhiều năm nay, công ty đã thực hiện đầy đủ quy định pháp luật về bảo vệ môi trường trong sản xuất, hàng năm đầu tư hàng tỉ đồng để xây dựng hệ thống xử lí nước thải; sản xuất đồ chơi không ảnh hưởng đến sức khoẻ của trẻ em. Đồng thời, công ty còn thực hiện đúng nghĩa vụ kê khai và nộp thuế cho Nhà nước theo quy định.", "o": ["Thực hiện pháp luật về bảo vệ môi trường là đã thực hiện trách nhiệm xã hội ở hình thức pháp lý và kinh tế.", "Sản xuất đồ chơi không ảnh hưởng đến sức khỏe trẻ em là phù hợp với trách nhiệm đạo đức và kinh tế.", "Thực hiện tốt nghĩa vụ nộp thuế cho Nhà nước gắn liền với trách nhiệm nhân văn của doanh nghiệp.", "Tạo ra sản phẩm không ảnh hưởng đến sức khỏe trẻ em thể hiện trách nhiệm thúc đẩy phát triển bền vững."], "a": [false, true, false, true], "e": "Đáp án: a) Sai; b) Đúng; c) Sai; d) Đúng.", "nguon": "Đề nguồn: Đề 1 đáp án.docx · Phần II câu 2 · khoá: chữ Đúng/Sai trong ý"}, {"id": "L12-HK1-07-C27", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "dung_sai", "status": "cho_duyet", "q": "Đọc đoạn thông tin sau và cho biết mỗi ý a, b, c, d là Đúng hay Sai. Sau khi cưới nhau, anh D và chị H dự định sau 3 năm sẽ mua nhà và ra ở riêng. Vợ chồng anh chị đồng thuận thực hiện kế hoạch quản lí thu, chi bằng sổ theo dõi hằng tháng. Theo đó, vợ chồng chị sẽ dành 50% tổng thu nhập cho chi tiêu thiết yếu; 20% cho các khoản dự phòng, tiết kiệm, mua nhà; và 30% còn lại cho các hoạt động giải trí, giao tiếp xã hội. Sau năm đầu, do có con nhỏ, anh chị buộc phải giảm số tiền cho các hoạt động giải trí để tăng cho các sinh hoạt thiết yếu; chị đã tham gia một gói bảo hiểm an sinh cho con mình đề phòng lúc ốm đau.", "o": ["Thực hiện kế hoạch thu chi bằng sổ theo dõi hằng tháng là thể hiện việc xác định mục tiêu tài chính.", "Việc tham gia bảo hiểm an sinh cho con là biện pháp nhằm tăng nguồn thu nhập cho gia đình.", "Kể từ khi có con nhỏ, anh chị chủ động cắt giảm khoản chi không thiết yếu là phù hợp.", "Anh chị xác định mục tiêu mua nhà sau 3 năm là chưa phù hợp."], "a": [false, false, true, false], "e": "Đáp án: a) Sai; b) Sai; c) Đúng; d) Sai.", "nguon": "Đề nguồn: Đề 1 đáp án.docx · Phần II câu 3 · khoá: chữ Đúng/Sai trong ý"}, {"id": "L12-HK1-07-C28", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "dung_sai", "status": "cho_duyet", "q": "Đọc đoạn thông tin sau và cho biết mỗi ý a, b, c, d là Đúng hay Sai. Vợ chồng chị H đều làm nhân viên cho công ty người ngoài, thu nhập của hai vợ chồng ở mức khá từ 40 – 60 triệu đồng/tháng. Hai vợ chồng chị xác định, ngoài việc nuôi hai con ăn học, cần phải tiết kiệm để sau 3 năm nữa sẽ đủ tiền mua được chung cư. Chị H thực hiện triệt để quy tắc 50/30/20: 50% dành cho chi tiêu thiết yếu, 30% dùng cho các mục tiêu tài chính như trả nợ, tiết kiệm, quỹ dự phòng, 20% dành cho chi tiêu cá nhân. Cuối mỗi tháng, chị tổng hợp chi tiêu và so sánh với kế hoạch.", "o": ["Số tiền 40–60 triệu đồng/tháng là nguồn thu nhập chính làm căn cứ xây dựng kế hoạch thu chi.", "Kế hoạch quản lý thu chi của gia đình chị H chỉ có một mục tiêu là mua chung cư sau ba năm.", "Quy tắc 50/30/20 hợp lí với mức thu nhập của hai vợ chồng chị H.", "Việc thường xuyên tổng hợp và so sánh chi tiêu thực tế với kế hoạch là phù hợp."], "a": [true, false, true, true], "e": "Đáp án: a) Đúng; b) Sai; c) Đúng; d) Đúng.", "nguon": "Đề nguồn: Đề 1 đáp án.docx · Phần II câu 4 · khoá: chữ Đúng/Sai trong ý"}]}, {"id": "L12-HK1-08", "loai": "khoi", "khoi": 12, "hoc_ki": 1, "bo": "HK1", "ten_bo": "học kì I", "so_de": 8, "ten": "Lớp 12 · học kì I · Đề 8", "pham_vi": "Bài 5–7 (đề nguồn «HỌC KÌ 1 › bai_5_7») · file nguồn: Đề 2 đáp án.docx", "thoi_gian": 50, "cau_truc": "24 câu trắc nghiệm + 4 câu đúng/sai (mỗi câu 4 ý)", "status": "cho_duyet", "khoa": {"1 nguồn": 28}, "sua": "", "cau": [{"id": "L12-HK1-08-C01", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Khi xác định mục tiêu kinh doanh, các chủ thể không cần chú ý tới tiêu chí nào dưới đây?", "o": ["Tính có thể đo lường.", "Tính khả thi.", "Tính vô thời hạn.", "Tính cụ thể."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: Đề 2 đáp án.docx · Phần I câu 1 · khoá: gạch chân"}, {"id": "L12-HK1-08-C02", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Một trong những điều kiện thực hiện ý tưởng kinh doanh mà các chủ thể sản xuất cần phân tích để lập kế hoạch kinh doanh phù hợp l�", "o": ["yếu tố hội nhập kinh tế quốc tế và các chính sách thương mại.", "yếu tố khách hàng.", "yếu tố xuất thân và nguồn gốc gia đình của người kinh doanh.", "yếu tố quốc tế."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: Đề 2 đáp án.docx · Phần I câu 2 · khoá: gạch chân"}, {"id": "L12-HK1-08-C03", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Một trong những đặc điểm của ý tưởng kinh doanh là ý tưởng đó phải có", "o": ["tính nhân đạo.", "tính sáng tạo.", "tính phi lợi nhuận.", "tính xã hội."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: Đề 2 đáp án.docx · Phần I câu 3 · khoá: gạch chân"}, {"id": "L12-HK1-08-C04", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Khi xây dựng bản kế hoạch kinh doanh, các chủ thể không cần đưa nội dung nào dưới đây vào kế hoạch của mình?", "o": ["Phương hướng kinh doanh.", "Cách thức thực hiện.", "Thời điểm hoàn thành.", "Điều kiện thực hiện."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: Đề 2 đáp án.docx · Phần I câu 4 · khoá: gạch chân"}, {"id": "L12-HK1-08-C05", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Công dân hoàn thiện đầy đủ điều kiện theo quy định của pháp luật trước khi tiến hành các hoạt động kinh doanh là đã thực hiện trách nhiệm xã hội của doanh nghiệp ở hình thức nào dưới đây?", "o": ["Trách nhiệm pháp lý.", "Trách nhiệm kinh doanh.", "Trách nhiệm nhân văn.", "Trách nhiệm từ thiện."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: Đề 2 đáp án.docx · Phần I câu 5 · khoá: gạch chân"}, {"id": "L12-HK1-08-C06", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Bên cạnh việc phát triển sản xuất, các doanh nghiệp tích cực tham gia các hoạt động nhân đạo là đã thể hiện trách nhiệm nào dưới đây của doanh nghiệp?", "o": ["Trách nhiệm sản xuất.", "Trách nhiệm tiêu dùng.", "Trách nhiệm nhân văn.", "Trách nhiệm pháp lý."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: Đề 2 đáp án.docx · Phần I câu 6 · khoá: gạch chân"}, {"id": "L12-HK1-08-C07", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Việc các chủ thể kinh tế thực hiện tốt trách nhiệm xã hội của mình khi kinh doanh sẽ đem lại lợi ích nào dưới đây đối với sự phát triển bền vững?", "o": ["Bảo vệ bất bình đẳng xã hội.", "Bảo vệ môi trường sống.", "Gây rối loạn thị trường.", "Cạnh tranh không lành mạnh."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: Đề 2 đáp án.docx · Phần I câu 7 · khoá: gạch chân"}, {"id": "L12-HK1-08-C08", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Doanh nghiệp sản xuất các sản phẩm, dịch vụ hữu ích; không gây hại cho xã hội và môi trường, thể hiện hình thức trách nhiệm xã hội nào của doanh nghiệp?", "o": ["Nhân văn.", "Đạo đức.", "Pháp lý.", "Kinh tế."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: Đề 2 đáp án.docx · Phần I câu 8 · khoá: gạch chân"}, {"id": "L12-HK1-08-C09", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Công dân thực hiện tốt các quy định của pháp luật về bảo vệ quyền lợi hợp pháp của người tiêu dùng khi tiến hành kinh doanh là đã thực hiện trách nhiệm xã hội của doanh nghiệp ở hình thức nào dưới đây?", "o": ["Trách nhiệm nhân văn.", "Trách nhiệm từ thiện.", "Trách nhiệm pháp lý.", "Trách nhiệm kinh doanh."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: Đề 2 đáp án.docx · Phần I câu 9 · khoá: gạch chân"}, {"id": "L12-HK1-08-C10", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Công dân kinh doanh đúng ngành, nghề ghi trong giấy chứng nhận đăng kí kinh doanh là thể hiện trách nhiệm xã hội của doanh nghiệp ở hình thức nào dưới đây?", "o": ["Trách nhiệm kinh doanh.", "Trách nhiệm pháp lý.", "Trách nhiệm từ thiện.", "Trách nhiệm kinh tế."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: Đề 2 đáp án.docx · Phần I câu 10 · khoá: gạch chân"}, {"id": "L12-HK1-08-C11", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Khi thống nhất tỷ lệ phân chia các khoản chi tiêu, các gia đình không cần phân chi tỷ lệ cho nội dung nào dưới đây?", "o": ["Chi thiết yếu cho sinh hoạt hằng ngày của các thành viên.", "Chi nộp thuế nhà đất.", "Chi không thiết yếu cho giải trí và giao tiếp xã hội.", "Chi tiết kiệm."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: Đề 2 đáp án.docx · Phần I câu 11 · khoá: gạch chân"}, {"id": "L12-HK1-08-C12", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Thông qua việc thực hiện quản lý thu, chi trong gia đình góp phần theo dõi và điều chỉnh những hành vi nào dưới đây để đạt được các mục tiêu tài chính trong gia đình?", "o": ["Thói quen chi tiêu hoang phí và không có kế hoạch rõ ràng.", "Thói quen chi tiêu tích cực đã được hình thành từ trước đó.", "Thói quen chi tiêu không tích cực.", "Thói quen chi tiêu tiết kiệm."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: Đề 2 đáp án.docx · Phần I câu 12 · khoá: gạch chân"}, {"id": "L12-HK1-08-C13", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Việc quản lý thi, chi trong gia đình sẽ giúp mỗi gia đình chủ động được", "o": ["các khoản rủi ro khi chi tiêu.", "các khoản nhà nước hỗ trợ.", "các khoản thu nhập ngoài.", "kế hoạch tài chính gia đình."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: Đề 2 đáp án.docx · Phần I câu 13 · khoá: gạch chân"}, {"id": "L12-HK1-08-C14", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Việc cân đối các khoản thu và chi nhằm đáp ứng nhu cầu vật chất, tinh thần của các thành viên sao cho phù hợp với các nguồn thu nhập của gia đình là nội dung của khái niệm nào dưới đây?", "o": ["Quản lí thu, chi nội bộ của doanh nghiệp trong nội bộ công ty.", "Quản lí thu, chi đối ngoại với các tổ chức tài chính bên ngoài.", "Quản lí thu, chi đối nội.", "Quản lí thu, chi trong gia đình."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: Đề 2 đáp án.docx · Phần I câu 14 · khoá: gạch chân"}, {"id": "L12-HK1-08-C15", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Nội dung nào dưới đây không thể hiện sự cần thiết phải quản lý thu, chi trong gia đình?", "o": ["Điều chỉnh hành vi tiêu dùng cho phù hợp với mục tiêu tài chính.", "Thiết lập mục tiêu tài chính.", "Chi tiêu tự do mất kiểm soát.", "Kiểm soát các nguồn thu nhập."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: Đề 2 đáp án.docx · Phần I câu 15 · khoá: gạch chân"}, {"id": "L12-HK1-08-C16", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Khi lập kế hoạch quản lý thu chi trong gia đình, việc thống nhất các khoản chi thiết yếu và không thiết yếu cần đảm bảo nguyên tắc nào dưới đây?", "o": ["Ưu tiên cho khoản không thiết yếu.", "Dành toàn bộ cho khoản không thiết yếu.", "Dành toàn bộ cho khoản thiết yếu", "Ưu tiên cho khoản chi tiêu thiết yếu."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: Đề 2 đáp án.docx · Phần I câu 16 · khoá: gạch chân"}, {"id": "L12-HK1-08-C17", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Nội dung nào dưới đây không phải là căn cứ để xây dựng kế hoạch quản lý thu, chi trong gia đình?", "o": ["Các khoản chi tiêu trong gia đình.", "Các mối quan hệ trong gia đình.", "Mục tiêu tài chính trong gia đình.", "Các nguồn thu nhập trong gia đình."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: Đề 2 đáp án.docx · Phần I câu 17 · khoá: gạch chân"}, {"id": "L12-HK1-08-C18", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Kế hoạch quản lý thu chi trong gia đình không bao gồm nội dung nào dưới đây?", "o": ["Xác định mục tiêu tài chính trong gia đình trong dài hạn và ngắn hạn.", "Xác định các nguồn thu nhập trong gia đình.", "Xác định các khoản chi tiêu thiết yếu.", "Xác định kế hoạch thu lợi nhuận kinh doanh."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: Đề 2 đáp án.docx · Phần I câu 18 · khoá: gạch chân"}, {"id": "L12-HK1-08-C19", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Để biết được tình hình tài chính hiện tại từ đó có cơ sở để xây dựng kế hoạch tài chính, mỗi gia đình cần xác định được", "o": ["các vấn đề sẽ phát sinh sau hôn nhân.", "các nguồn thu nhập trong gia đình.", "các biện pháp thúc đẩy bình đẳng giới.", "các mối quan hệ trong v� ngoài gia đình."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: Đề 2 đáp án.docx · Phần I câu 19 · khoá: gạch chân"}, {"id": "L12-HK1-08-C20", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Gia đình bạn B (có 4 thành viên) đặt ra mục tiêu sau 3 tháng mua một chiếc xe đạp điện chuẩn bị cho em gái vào học trung học phổ thông, sau 3 năm tích luỹ được một khoản tiền cho anh trai vào học đại học, sau 10 năm sẽ mua được một căn chung cư. Mục tiêu tài chính nào dưới đây không được gia đình bạn B xác định?", "o": ["Trung hạn, kéo dài từ một đến ba năm.", "Dài hạn, kéo dài trên ba năm.", "Không thời hạn", "Ngắn hạn, dưới một năm."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: Đề 2 đáp án.docx · Phần I câu 20 · khoá: gạch chân"}, {"id": "L12-HK1-08-C21", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đọc đoạn thông tin sau:\nNhận thấy quê hương mình rất phong phú về các loại thảo mộc và nhu cầu thị trường về dòng sản phẩm này ngày càng tăng lên, anh H đã xây dựng kế hoạch kinh doanh mĩ phẩm chiết xuất từ thiên nhiên. Sau khi đánh giá những thuận lợi và khó khăn, anh H nhận thấy kế hoạch kinh doanh của mình có khả thi. Nhờ xây dựng kế hoạch kinh doanh tốt, đánh giá đúng cơ hội, đối tượng khách hàng tiềm năng,… nên việc kinh doanh đã đạt được những thành công ban đầu.\nAnh H đã biết xác định ý tưởng kinh doanh thông qua việc làm nào dưới đây?", "o": ["Kinh doanh mĩ phẩm từ thiên nhiên.", "Nhận thấy nhu cầu cao về thảo mộc.", "Đạt hiệu quả cao trong kinh doanh và tăng doanh thu bán hàng.", "Đánh giá tiềm năng về khách hàng."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: Đề 2 đáp án.docx · Phần I câu 21 · khoá: gạch chân"}, {"id": "L12-HK1-08-C22", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Khi đánh giá những thuận lợi và khó khăn khi tiến hành kinh doanh, anh H đã thực hiện bước nào dưới đây của việc lập kế hoạch kinh doanh?", "o": ["Xác định ý tưởng kinh doanh.", "Xác định mục tiêu kinh doanh.", "Phân tích điều kiện thực hiện kinh doanh.", "Phân tích những rủi ro và biện pháp xử lý."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: Đề 2 đáp án.docx · Phần I câu 22 · khoá: gạch chân"}, {"id": "L12-HK1-08-C23", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đọc đoạn thông tin sau:\nLà một doanh nghiệp nhỏ ngành dệt may ở một xã thuần nông, doanh nghiệp V đã cung ứng cho thị trường nhiều sản phẩm có chất lượng cao, thân thiện với môi trường. Công ty đã thu hút những lao động là thanh niên trong xã, đào tạo họ trở thành những người thợ lành nghề. Hằng năm, doanh nghiệp còn hỗ trợ kinh phí cho học sinh có hoàn cảnh đặc biệt khó khăn trong xã được đi học đại học. Năm qua doanh nghiệp được cơ quan thuế tặng bằng khen vì thành tích thực hiện tốt nghĩa vụ nộp thuế.\nViệc hỗ trợ kinh phí cho học sinh có hoàn cảnh đặc biệt khó khăn trong xã được đi học đại học và tham gia các hoạt động cộng đồng trong xã là thể hiện trách nhiệm xã hội nào dưới đây của doanh nghiệp?", "o": ["Trách nhiệm kinh tế.", "Trách nhiệm nhân văn.", "Trách nhiệm pháp lý.", "Trách nhiệm địa phương."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: Đề 2 đáp án.docx · Phần I câu 23 · khoá: gạch chân"}, {"id": "L12-HK1-08-C24", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Việc làm nào dưới đây của doanh nghiệp V không thể hiện trách nhiệm kinh tế của doanh nghiệp khi tiến hành sản xuất, kinh doanh?", "o": ["Cung cấp các sản phẩm có chất lượng cao cho người tiêu dùng trong nước.", "Hỗ trợ kinh phí cho học sinh theo học đại học.", "Giải quyết việc làm cho lao động địa phương.", "Sản xuất sản phẩm thân thiện với môi trường."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: Đề 2 đáp án.docx · Phần I câu 24 · khoá: gạch chân"}, {"id": "L12-HK1-08-C25", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "dung_sai", "status": "cho_duyet", "q": "Đọc đoạn thông tin sau và cho biết mỗi ý a, b, c, d là Đúng hay Sai. Với mong muốn xây dựng thành công chuỗi cửa hàng phân phối thực phẩm sạch trên địa bàn huyện X, anh H đã lên kế hoạch chi tiết để thực hiện ý tưởng kinh doanh. Qua tìm hiểu thực tế anh nhận thấy đây là sản phẩm đang có nhu cầu lớn. Anh đã dự liệu được những rủi ro, khó khăn tiềm ẩn để có giải pháp khắc phục; đã lên kế hoạch chi tiết việc bán hàng, tiếp thị, quảng cáo.", "o": ["Anh H xác định ý tưởng kinh doanh khi thấy sản phẩm thực phẩm sạch có nhu cầu lớn.", "Anh H chưa phân tích các điều kiện thực hiện ý tưởng kinh doanh.", "Anh H đã dự liệu rủi ro, khó khăn tiềm ẩn và có giải pháp khắc phục.", "Anh H đã biết xác định chiến lược kinh doanh qua việc lên kế hoạch bán hàng, tiếp thị và quảng cáo."], "a": [true, false, true, true], "e": "Đáp án: a) Đúng; b) Sai; c) Đúng; d) Đúng.", "nguon": "Đề nguồn: Đề 2 đáp án.docx · Phần II câu 1 · khoá: chữ Đúng/Sai trong ý"}, {"id": "L12-HK1-08-C26", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "dung_sai", "status": "cho_duyet", "q": "Đọc đoạn thông tin sau và cho biết mỗi ý a, b, c, d là Đúng hay Sai. Ông S là giám đốc công ty cổ phần sản xuất hàng công nghiệp. Trong quá trình sản xuất, ông đã chỉ đạo công ty làm mọi cách để giảm chi phí sản xuất nhằm tăng lợi nhuận, kể cả việc bỏ qua trách nhiệm của công ty về bảo vệ môi trường như thải khí thải vượt quá mức quy định. Ông chỉ đạo thay đổi một số linh kiện có giá rẻ hơn. Đối với người lao động, công ty đã ký hợp đồng thời vụ với một số lao động phổ thông để không phải đóng bảo hiểm xã hội cho họ.", "o": ["Giám đốc S chưa thực hiện tốt trách nhiệm pháp lý và trách nhiệm đạo đức trong sản xuất kinh doanh.", "Lắp ráp sản phẩm có giá rẻ hơn để tối ưu lợi nhuận là phù hợp với trách nhiệm kinh tế.", "Ký hợp đồng thời vụ để không đóng bảo hiểm xã hội là thể hiện trách nhiệm đạo đức của doanh nghiệp.", "Trích lợi nhuận để làm từ thiện là đủ để xây dựng uy tín, không cần thực hiện nghĩa vụ pháp lý."], "a": [true, false, false, false], "e": "Đáp án: a) Đúng; b) Sai; c) Sai; d) Sai.", "nguon": "Đề nguồn: Đề 2 đáp án.docx · Phần II câu 2 · khoá: chữ Đúng/Sai trong ý"}, {"id": "L12-HK1-08-C27", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "dung_sai", "status": "cho_duyet", "q": "Đọc đoạn thông tin sau và cho biết mỗi ý a, b, c, d là Đúng hay Sai. Khi biết có một căn nhà cũ bán với giá rẻ, anh T liền lên kế hoạch dự trù tài chính, mua lại căn nhà đó để sửa chữa và cho thuê với giá hợp lí. Cách thức này vừa giúp gia đình anh có thêm nguồn thu nhập vừa giữ được tài sản hiện có. Bên cạnh đó, anh T dành một khoản lớn thu nhập cho mục tiêu tiết kiệm. Anh chi tiêu ở mức tối thiểu cho sinh hoạt hằng ngày với các nhu cầu thiết yếu.", "o": ["Việc phân chia chi tiêu thiết yếu và không thiết yếu của anh T là hoàn toàn phù hợp.", "Mua nhà rồi cho thuê lại là khoản thu nhập thụ động trong gia đình.", "Mua nhà và mua xe là các mục tiêu tài chính trong gia đình của anh T.", "Hạn chế giao tiếp để giảm chi tiêu thiết yếu của anh T là phù hợp."], "a": [false, true, true, false], "e": "Đáp án: a) Sai; b) Đúng; c) Đúng; d) Sai.", "nguon": "Đề nguồn: Đề 2 đáp án.docx · Phần II câu 3 · khoá: chữ Đúng/Sai trong ý"}, {"id": "L12-HK1-08-C28", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "dung_sai", "status": "cho_duyet", "q": "Đọc đoạn thông tin sau và cho biết mỗi ý a, b, c, d là Đúng hay Sai. Vợ chồng anh N có tổng thu nhập từ 20 – 25 triệu đồng/tháng. Kể từ khi mới kết hôn, anh chị đã thống nhất cách thức kiểm soát thu, chi. Mọi nguồn thu của các thành viên trong gia đình đều được ghi chép lại và người vợ sẽ giữ tiền. Anh chị còn đưa ra 4 cách kiểm soát nguồn chi: chỉ mua sắm vào những ngày quy định, chi tiêu có mục đích, tạo danh sách mua sắm trước khi mua và tạo ra giới hạn chi tiêu.", "o": ["Vợ chồng anh N không xác định mục tiêu tài chính rõ ràng.", "Kiên trì thực hiện 4 cách kiểm soát nguồn chi làm chi tiêu trong gia đình bị hạn chế.", "Số tiền 20–25 triệu đồng/tháng là căn cứ để xây dựng kế hoạch quản lí thu chi.", "Vợ chồng anh N không cần điều chỉnh kế hoạch quản lí thu chi vì biện pháp đã phù hợp."], "a": [false, false, true, false], "e": "Đáp án: a) Sai; b) Sai; c) Đúng; d) Sai.", "nguon": "Đề nguồn: Đề 2 đáp án.docx · Phần II câu 4 · khoá: chữ Đúng/Sai trong ý"}]}, {"id": "L12-HK1-09", "loai": "khoi", "khoi": 12, "hoc_ki": 1, "bo": "HK1", "ten_bo": "học kì I", "so_de": 9, "ten": "Lớp 12 · học kì I · Đề 9", "pham_vi": "Bài 5–7 (đề nguồn «HỌC KÌ 1 › bai_5_7») · file nguồn: Đề 3 đáp án.docx", "thoi_gian": 50, "cau_truc": "24 câu trắc nghiệm + 4 câu đúng/sai (mỗi câu 4 ý)", "status": "cho_duyet", "khoa": {"1 nguồn": 28}, "sua": "", "cau": [{"id": "L12-HK1-09-C01", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Nội dung cơ bản của một bản kế hoạch kinh doanh gồm một chuỗi các biện pháp, cách thức của chủ thể kinh doanh nhằm đạt được hiệu quả tối ưu được gọi l�", "o": ["kế hoạch sản xuất và phân phối sản phẩm ra thị trường.", "kế hoạch tài chính và kế hoạch nhân sự của doanh nghiệp.", "chiến lược đàm phán và ký kết hợp đồng với đối tác.", "chiến lược kinh doanh."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: Đề 3 đáp án.docx · Phần I câu 1 · khoá: gạch chân"}, {"id": "L12-HK1-09-C02", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Nội dung nào dưới đây không thể hiện việc xác định ý tưởng kinh doanh khi lập kế hoạch kinh doanh?", "o": ["Kinh doanh mặt hàng gì và quy mô sản xuất dự kiến.", "Đối tượng khách hàng là ai.", "Tỷ suất lợi nhuận thu được.", "Kinh doanh bằng cách nào và với phương thức bán hàng ra sao."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: Đề 3 đáp án.docx · Phần I câu 2 · khoá: gạch chân"}, {"id": "L12-HK1-09-C03", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Ý tưởng kinh doanh là những suy nghĩ, hành động sáng tạo, có tính khả thi, có thể đem lại lợi nhuận trong", "o": ["nghệ thuật và văn hóa của cộng đồng dân cư địa phương.", "công tác hành chính của cơ quan nhà nước.", "học tập và nghiên cứu khoa học trong nhà trường.", "kinh doanh."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: Đề 3 đáp án.docx · Phần I câu 3 · khoá: gạch chân"}, {"id": "L12-HK1-09-C04", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Khi phân tích các điều kiện thực hiện hoạt động kinh doanh, các chủ thể cần chú ý phân tích điều kiện nào dưới đây?", "o": ["Phân tích chiến lược.", "Phân tích mục tiêu.", "Phân tích sản phẩm.", "Phân tích ý tưởng."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: Đề 3 đáp án.docx · Phần I câu 4 · khoá: gạch chân"}, {"id": "L12-HK1-09-C05", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Tuân thủ các quy định về quan hệ cạnh tranh lành mạnh, quan hệ lao động công bằng, bình đẳng là thể hiện hình thức trách nhiệm xã hội nào của doanh nghiệp?", "o": ["Đạo đức.", "Pháp lý.", "Kinh tế.", "Nhân văn."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: Đề 3 đáp án.docx · Phần I câu 5 · khoá: gạch chân"}, {"id": "L12-HK1-09-C06", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Tuân thủ các quy định về kinh doanh, thực hiện nghĩa vụ nộp thuế l� thể hiện hình thức trách nhiệm xã hội nào của doanh nghiệp?", "o": ["Nhân văn.", "Đạo đức.", "Pháp lý.", "Kinh tế."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: Đề 3 đáp án.docx · Phần I câu 6 · khoá: gạch chân"}, {"id": "L12-HK1-09-C07", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Việc các chủ thể kinh tế luôn giữ gìn sự trung thực về sản phẩm của mình đã cam kết là thể hiện trách nhiệm nào dưới đây của doanh nghiệp?", "o": ["Trách nhiệm phân phối.", "Trách nhiệm sản xuất.", "Trách nhiệm đạo đức.", "Trách nhiệm tiêu dùng."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: Đề 3 đáp án.docx · Phần I câu 7 · khoá: gạch chân"}, {"id": "L12-HK1-09-C08", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Việc doanh nghiệp H tìm các giải pháp để mở rộng sản xuất kinh doanh tạo nhiều việc làm cho người lao động và đem lại lợi nhuận cho doanh nghiệp là đã thực hiện trách nhiệm nào dưới đây?", "o": ["Trách nhiệm pháp lý.", "Trách nhiệm kinh tế.", "Trách nhiệm đạo đức.", "Trách nhiệm nhân văn."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: Đề 3 đáp án.docx · Phần I câu 8 · khoá: gạch chân"}, {"id": "L12-HK1-09-C09", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Trách nhiệm kinh tế của các doanh nghiệp không thể hiện ở việc mỗi chủ thể kinh tế vì mục tiêu lợi nhuận đã", "o": ["đảm bảo lợi ích người tiêu dùng.", "nâng cao năng xuất lao động.", "đầu cơ tích trữ nhiều hàng hóa.", "gia tăng phúc lợi cho công nhân."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: Đề 3 đáp án.docx · Phần I câu 9 · khoá: gạch chân"}, {"id": "L12-HK1-09-C10", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Nội dung nào dưới đây không thể hiện trách nhiệm kinh tế của doanh nghiệp?", "o": ["Sản xuất hàng giả thu lợi nhuận.", "Tạo nhiều việc làm mới cho xã hội.", "Chăm lo lợi ích người lao động.", "Sản xuất hàng hóa đạt tiêu chuẩn."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: Đề 3 đáp án.docx · Phần I câu 10 · khoá: gạch chân"}, {"id": "L12-HK1-09-C11", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Khi xác định các nguồn thu nhập trong gia đình để xây dựng kế hoạch thu chi, các chủ thể không cần xác định nguồn thu nhập nào dưới đây?", "o": ["Tiền trúng thưởng xổ số trong một lần nhất định.", "Tiền nộp thuế kinh doanh.", "Thu nhập từ kinh doanh của các thành viên trong gia đình.", "Lợi tức từ kinh doanh và lãi tiền gửi tiết kiệm."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: Đề 3 đáp án.docx · Phần I câu 11 · khoá: gạch chân"}, {"id": "L12-HK1-09-C12", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Khi thực hiện việc quản lý thu chi trong gia đình sẽ giúp mỗi gia đình có thể chủ động", "o": ["tự do chi tiêu theo sở thích.", "ứng phó các tình huống rủi ro.", "chi tiêu ngoài kế hoạch đã định.", "tạo ra các quỹ ngoài kế hoạch."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: Đề 3 đáp án.docx · Phần I câu 12 · khoá: gạch chân"}, {"id": "L12-HK1-09-C13", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Sau khi kết hôn, vợ chồng anh D bàn bạc thống nhất mục tiêu sau 1 năm sẽ mua sắm được những đồ dùng thiết yếu trong gia đình và tiết kiệm được khoảng 100 triệu đồng. Vợ chồng anh D đã thực hiện bước nào dưới đây của quá trình lập kế hoạch thu chi trong gia đình?", "o": ["Xác định nguồn thu thiết yếu.", "Xác định khoản chi thiết yếu.", "Xác định các nguồn thu nhập.", "Xác định mục tiêu tài chính."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: Đề 3 đáp án.docx · Phần I câu 13 · khoá: gạch chân"}, {"id": "L12-HK1-09-C14", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Khi lập kế hoạch quản lý thu chi trong gia đình, các chủ thể chủ động xác định và thiết lập các mục tiêu tài chính cụ thể mà gia đình mong muốn đạt được trong tương lai là thực hiện bước nào dưới đây?", "o": ["Phân chi các khoản thu chi theo từng tháng và từng mục.", "Xác định các nguồn thu nhập.", "Xác định mục tiêu tài chính.", "Thống nhất tỷ lệ thu chi giữa các thành viên trong gia đình."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: Đề 3 đáp án.docx · Phần I câu 14 · khoá: gạch chân"}, {"id": "L12-HK1-09-C15", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Những khoản bắt buộc phải chi tiêu hàng tháng để phục vụ các thành viên trong gia đình được gọi là khoản chi tiêu", "o": ["không thiết yếu.", "đặc biệt.", "thiết yếu.", "quá xa xỉ."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: Đề 3 đáp án.docx · Phần I câu 15 · khoá: gạch chân"}, {"id": "L12-HK1-09-C16", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Nhận định nào dưới đây là đúng khi nói về quản lí thu, chi trong gia đình?", "o": ["Ghi chép đầy đủ khoản thu hằng tháng của mọi thành viên trong gia đình.", "Lập kế hoạch chi tiêu hằng tháng.", "Phân loại các khoản chi thiết yếu và không thiết yếu.", "Phân bổ các khoản thu và chi vào các mục đích cụ thể."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: Đề 3 đáp án.docx · Phần I câu 16 · khoá: gạch chân"}, {"id": "L12-HK1-09-C17", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Khoản chi nào dưới đây được gọi là khoản chi tiêu thiết yếu trong gia đình?", "o": ["Chi tiêu cho ăn, mặc.", "Chi tiêu mua hàng xa xỉ.", "Chi tiêu cho việc đi lại.", "Chi tiêu cho việc học tập."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: Đề 3 đáp án.docx · Phần I câu 17 · khoá: gạch chân"}, {"id": "L12-HK1-09-C18", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Phát biểu nào dưới đây là sai về các yêu cầu khi lập kế hoạch thu, chi trong gia đình?", "o": ["Luôn luôn ưu tiên cắt giảm các khoản chi tiêu thiết yếu.", "Xác định mục tiêu tài chính trong gia đình cần giới hạn thời gian hoàn thành.", "Thường xuyên kiểm tra ngân sách và nguồn thu nhập của gia đình.", "Chủ động loại bỏ các thói quen chi tiêu không hợp lý."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: Đề 3 đáp án.docx · Phần I câu 18 · khoá: gạch chân"}, {"id": "L12-HK1-09-C19", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Vợ chồng anh D và chị H dự định năm tới sẽ mua nhà trên thành phố phục vụ việc học tập của các con, anh chị yêu cầu các thành viên trong gia đình đều có trách nhiệm chi tiêu hợp lý để thực hiện ý định trên. Anh D v� chị H đã thực hiện nội dung nào dưới đây của lập kế hoạch quản lý thu chi trong gia đình?", "o": ["Thống nhất các khoản chi thiết yếu của gia đình trong năm tới.", "Thống nhất các nguồn thu nhập cơ bản và các khoản vay tín dụng.", "Xác định mục tiêu tài chính gia đình.", "Thực hiện các khoản thu, chi đã định."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: Đề 3 đáp án.docx · Phần I câu 19 · khoá: gạch chân"}, {"id": "L12-HK1-09-C20", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Khi xác định các mục tiêu tài chính trong gia đình, mỗi gia đình cần ưu tiên thực hiện các mục tiêu mang tính", "o": ["không xác định.", "cấp bách.", "dài hạn.", "không cần thiết."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: Đề 3 đáp án.docx · Phần I câu 20 · khoá: gạch chân"}, {"id": "L12-HK1-09-C21", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đọc đoạn thông tin sau:\nSau khi tốt nghiệp đại học ngành công nghệ sinh học, chị D quyết định lập nghiệp bằng con đường kinh doanh sản phẩm cây cảnh mini với mong muốn sau hai năm sẽ thành lập một doanh nghiệp phân phối các sản phẩm này. Từ thực tế kinh doanh, chị quyết định mở rộng sản xuất và lên kế hoạch đầu tư thêm nhiều cửa hàng mới cũng như phát triển kênh truyền thông nhằm mở rộng thị trường.\nNội dung nào dưới đây thể hiện chị D đã biết xác định ý tưởng khi lập kế hoạch kinh doanh?", "o": ["Mở cửa hàng để bán.", "Thuê lao động bán hàng.", "Sử dụng mạng xã hội.", "Kinh doanh cây cảnh."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: Đề 3 đáp án.docx · Phần I câu 21 · khoá: gạch chân"}, {"id": "L12-HK1-09-C22", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Chị D đã xác định cho mình mục tiêu kinh doanh l�", "o": ["mở rộng sản xuất và phát triển kênh bán hàng trực tuyến.", "thành lập doanh nghiệp.", "lập thân, lập nghiệp và tạo việc làm cho người khác.", "đẩy mạnh truyền thông."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: Đề 3 đáp án.docx · Phần I câu 22 · khoá: gạch chân"}, {"id": "L12-HK1-09-C23", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đọc đoạn thông tin sau:\nLà doanh nghiệp chuyên kinh doanh các mặt hàng thực phẩm, Công ty A đặc biệt lưu ý đến việc kiểm soát chất lượng đầu vào, luôn chọn những nhà cung cấp tuân thủ đúng các quy định của Nhà nước về hồ sơ pháp lí; ưu tiên chọn nhà cung cấp có chứng nhận VietGAP, chuỗi thực phẩm an toàn. Ngoài ra, công ty còn định kì khảo sát, đánh giá trực tiếp điều kiện cơ sở vật chất của nhà cung cấp. Vì vậy, sản phẩm của công ty ngày càng được nhiều khách hàng tin tưởng.\nViệc công ty A chú trọng lựa chọn những nhà cung cấp tuân thủ đúng các quy định của Nhà nước về hồ sơ pháp lí là thể hiện trách nhiệm xã hội nào dưới đây của doanh nghiệp?", "o": ["Trách nhiệm đạo đức trong kinh doanh với đối tác.", "Trách nhiệm công vụ.", "Trách nhiệm pháp lý.", "Trách nhiệm kinh tế trong sản xuất và tiêu thụ hàng hóa."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: Đề 3 đáp án.docx · Phần I câu 23 · khoá: gạch chân"}, {"id": "L12-HK1-09-C24", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Quá trình công ty A kiểm soát chặt chẽ chất lượng đầu vào để đảm bảo hành hóa bản cho người tieu dùng luôn có chất lượng tốt nhất như đã cam kết là đã thực hiện tốt trách nhiệm xã hội nào dưới đây của doanh nghiệp?", "o": ["Trách nhiệm kinh tế.", "Trách nhiệm pháp lý.", "Trách nhiệm nhân văn.", "Trách nhiệm đạo đức."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: Đề 3 đáp án.docx · Phần I câu 24 · khoá: gạch chân"}, {"id": "L12-HK1-09-C25", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "dung_sai", "status": "cho_duyet", "q": "Đọc đoạn thông tin sau và cho biết mỗi ý a, b, c, d là Đúng hay Sai. Ông M đã ấp ủ ý tưởng về việc lắp ráp và kinh doanh ô tô với mục tiêu sẽ đưa ra thị trường những chiếc ô tô mang thương hiệu Việt Nam. Ông nhận thấy thị trường ô tô ở Việt Nam chưa có thương hiệu trong nước trong khi nhu cầu của người dân rất cao, nhà nước có nhiều chính sách ưu đãi để phát triển. Ông luôn chủ động, sáng tạo, nắm bắt cơ hội, vạch ra chiến lược kinh doanh; xây dựng hệ thống quản lí nội bộ công ty chuyên nghiệp.", "o": ["Ông M đã xác định đúng mục tiêu và ý tưởng kinh doanh trên cơ sở đánh giá đúng các điều kiện.", "Việc ông M khởi nghiệp từ nghề sửa chữa ô tô là giai đoạn tích lũy kiến thức để thực hiện mục tiêu kinh doanh.", "Ông M phân tích sai yếu tố thị trường và yếu tố khách hàng khi thực hiện ý tưởng kinh doanh.", "Ông M chưa chú trọng hợp tác quốc tế về sản xuất ô tô nên không tiếp cận được công nghệ thế giới."], "a": [true, true, false, true], "e": "Đáp án: a) Đúng; b) Đúng; c) Sai; d) Đúng.", "nguon": "Đề nguồn: Đề 3 đáp án.docx · Phần II câu 1 · khoá: chữ Đúng/Sai trong ý"}, {"id": "L12-HK1-09-C26", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "dung_sai", "status": "cho_duyet", "q": "Đọc đoạn thông tin sau và cho biết mỗi ý a, b, c, d là Đúng hay Sai. Là doanh nghiệp hoạt động trong lĩnh vực sản xuất hàng tiêu dùng, công ty H luôn tạo mọi điều kiện để nhân viên được làm việc trong một môi trường an toàn, thân thiện. Công ty đã xây dựng các chính sách đãi ngộ hợp lí, thoả đáng cho đội ngũ nhân viên, như chế độ lương thưởng kịp thời, chế độ bảo hiểm xã hội, thăm hỏi nhân viên và thân nhân của họ.", "o": ["Xây dựng môi trường an toàn, thân thiện cho nhân viên là thực hiện tốt trách nhiệm kinh tế khi kinh doanh.", "Chính sách đãi ngộ hợp lí và thỏa đáng cho nhân viên vừa thể hiện an sinh xã hội vừa thể hiện trách nhiệm xã hội của doanh nghiệp.", "Thăm hỏi nhân viên và thân nhân là thể hiện trách nhiệm pháp lý của doanh nghiệp.", "Xây dựng chính sách đãi ngộ là thể hiện khả năng lập kế hoạch kinh doanh của công ty."], "a": [true, true, false, false], "e": "Đáp án: a) Đúng; b) Đúng; c) Sai; d) Sai.", "nguon": "Đề nguồn: Đề 3 đáp án.docx · Phần II câu 2 · khoá: chữ Đúng/Sai trong ý"}, {"id": "L12-HK1-09-C27", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "dung_sai", "status": "cho_duyet", "q": "Đọc đoạn thông tin sau và cho biết mỗi ý a, b, c, d là Đúng hay Sai. Đầu năm, vợ chồng anh A thống nhất đặt mục tiêu mỗi tháng sẽ dành 60% thu nhập cho các chi tiêu thiết yếu, tiết kiệm 20% thu nhập gia đình để có đủ tiền mua xe máy mới cho vợ. Hai tháng nay anh A bị mất việc, thu nhập giảm sút. Để phụ giúp gia đình, anh A đã tham gia chạy xe ôm và nhận giao hàng. Nhờ đó mà sau một năm vợ chồng anh A đã hoàn thành mục tiêu đặt ra. Hai vợ chồng quyết tâm năm năm tới sẽ mua được một mảnh đất để làm cửa hàng cho thuê.", "o": ["Kiểm soát các khoản chi tiêu là nhân tố giúp vợ chồng anh A đạt được mục tiêu tài chính.", "Vợ chồng anh A đã phân chia tỷ lệ các khoản chi tiêu trong gia đình.", "Vợ chồng anh A dành 60% thu nhập cho chi tiêu thiết yếu là chưa phù hợp.", "Đồng thời thực hiện hai mục tiêu tài chính của vợ chồng anh A là chưa hợp lý."], "a": [true, true, false, false], "e": "Đáp án: a) Đúng; b) Đúng; c) Sai; d) Sai.", "nguon": "Đề nguồn: Đề 3 đáp án.docx · Phần II câu 3 · khoá: chữ Đúng/Sai trong ý"}, {"id": "L12-HK1-09-C28", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "dung_sai", "status": "cho_duyet", "q": "Đọc đoạn thông tin sau và cho biết mỗi ý a, b, c, d là Đúng hay Sai. Vợ chồng anh P và chị Q đang tìm mua căn nhà đầu tiên. Hai người đều có công việc tốt, có khả năng mua căn nhà như mong muốn nhưng vẫn muốn đảm bảo việc có thể duy trì các khoản thanh toán thế chấp trong tương lai và lối sống hiện tại.", "o": ["Xác định mục tiêu tài chính là mua căn nhà và duy trì khoản thanh toán thế chấp trong tương lai.", "Ưu tiên chi tiêu cho nhu cầu thiết yếu là việc cần làm khi quản lí thu chi.", "Chi tiêu dựa trên số tiền có sẵn là đúng nguyên tắc quản lí thu chi.", "Chi tiêu cho sở thích của hai vợ chồng là nên làm khi quản lí thu chi."], "a": [true, true, false, false], "e": "Đáp án: a) Đúng; b) Đúng; c) Sai; d) Sai.", "nguon": "Đề nguồn: Đề 3 đáp án.docx · Phần II câu 4 · khoá: chữ Đúng/Sai trong ý"}]}, {"id": "L12-HK1-10", "loai": "khoi", "khoi": 12, "hoc_ki": 1, "bo": "HK1", "ten_bo": "học kì I", "so_de": 10, "ten": "Lớp 12 · học kì I · Đề 10", "pham_vi": "Bài 5–7 (đề nguồn «HỌC KÌ 1 › bai_5_7») · file nguồn: Đề 4 đáp án.docx", "thoi_gian": 50, "cau_truc": "24 câu trắc nghiệm + 4 câu đúng/sai (mỗi câu 4 ý)", "status": "cho_duyet", "khoa": {"1 nguồn": 28}, "sua": "", "cau": [{"id": "L12-HK1-10-C01", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Bản tóm tắt kế hoạch kinh doanh không bao gồm nội dung nào dưới đây?", "o": ["Thuận lợi và khó khăn.", "Ý tưởng kinh doanh.", "Tên kế hoạch kinh doanh.", "Thời điểm thành công."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: Đề 4 đáp án.docx · Phần I câu 1 · khoá: gạch chân"}, {"id": "L12-HK1-10-C02", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Kế hoạch kinh doanh xác định rõ sứ mệnh, tầm nhìn, chiến lược, công việc dự định thực hiện và cách đạt được", "o": ["trách nhiệm xã hội của doanh nghiệp đối với cộng đồng.", "mục tiêu xã hội.", "mục tiêu kinh doanh.", "trách nhiệm kinh tế của doanh nghiệp trong thị trường."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: Đề 4 đáp án.docx · Phần I câu 2 · khoá: gạch chân"}, {"id": "L12-HK1-10-C03", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Yếu tố nào dưới đây không phải là tiêu chí để đánh giá một ý tưởng kinh doanh tốt?", "o": ["Không có tính khả thi.", "Có tính mới mẻ, độc đáo.", "Có ưu thế vượt trội.", "Có lợi thế cạnh tranh."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: Đề 4 đáp án.docx · Phần I câu 3 · khoá: gạch chân"}, {"id": "L12-HK1-10-C04", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Kế hoạch kinh doanh là bản phác thảo quá trình kinh doanh trong một khoảng thời gian", "o": ["không xác định.", "chưa xác định.", "mãi mãi.", "nhất định."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: Đề 4 đáp án.docx · Phần I câu 4 · khoá: gạch chân"}, {"id": "L12-HK1-10-C05", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Việc thực hiện trách nhiệm xã hội của doanh nghiệp góp phần mang lại ý nghĩa như thế nào đối với sự phát triển của mỗi quốc gia?", "o": ["Gia tăng khủng hoảng.", "Phát triển bền vững.", "Lạm phát bất ổn.", "Thất nghiệp gia tăng."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: Đề 4 đáp án.docx · Phần I câu 5 · khoá: gạch chân"}, {"id": "L12-HK1-10-C06", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Khi tiến hành hoạt động kinh doanh, các doanh nghiệp phải thực hiện tốt trách nhiệm xã hội thông qua việc làm nào dưới đây?", "o": ["Ứng dụng trí tuệ nhân tạo vào quản lí sản xuất kinh doanh.", "Tham gia bảo hiểm nhân thọ cho toàn bộ nhân viên trong công ty.", "Tổ chức hội nghị khách hàng.", "Bảo vệ quyền lợi người tiêu dùng."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: Đề 4 đáp án.docx · Phần I câu 6 · khoá: gạch chân"}, {"id": "L12-HK1-10-C07", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Anh T nộp hồ sơ đăng kí và được cấp giấy phép mở đại lí phân phối xe mô tô. Anh T đã thực hiện trách nhiệm xã hội ở hình thức nào dưới đây?", "o": ["Trách nhiệm nhân văn.", "Trách nhiệm kinh tế.", "Trách nhiệm pháp lý.", "Trách nhiệm đạo đức."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: Đề 4 đáp án.docx · Phần I câu 7 · khoá: gạch chân"}, {"id": "L12-HK1-10-C08", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Doanh nghiệp tham gia các hoạt động khám chữa bệnh miễn phí, xây dựng nhà tình nghĩa là thể hiện hình thức trách nhiệm xã hội nào của doanh nghiệp?", "o": ["Pháp lý và tuân thủ quy định về bảo hiểm y tế.", "Đạo đức kinh doanh và trung thực với khách hàng.", "Kinh tế và phát triển sản xuất bền vững.", "Nhân văn."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: Đề 4 đáp án.docx · Phần I câu 8 · khoá: gạch chân"}, {"id": "L12-HK1-10-C09", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Nội dung nào dưới đây thể hiện trách nhiệm pháp lý của doanh nghiệp?", "o": ["Gian lận hồ sơ kê khai thuế để giảm số thuế phải nộp.", "Thường xuyên nộp chậm thuế và không kê khai đầy đủ.", "Bị xử phạt hành chính vì chậm nộp thuế theo quy định.", "Chấp hành pháp luật về thuế."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: Đề 4 đáp án.docx · Phần I câu 9 · khoá: gạch chân"}, {"id": "L12-HK1-10-C10", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Trách nhiệm xã hội của doanh nghiệp là toàn bộ trách nhiệm mà doanh nghiệp thực hiện đối với xã hội bằng những chính sách và việc làm cụ thể mang tính", "o": ["tạm thời và không ổn định theo từng thời kì.", "tích cực.", "tiêu cực và gây ảnh hưởng xấu đến xã hội.", "thời vụ theo mùa vụ sản xuất trong năm."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: Đề 4 đáp án.docx · Phần I câu 10 · khoá: gạch chân"}, {"id": "L12-HK1-10-C11", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Sự cần thiết phải tiết kiệm và đầu tư khi quản lí thu chi trong gia đình thể hiện ở việc", "o": ["quản lí và phân bố thu nhập gia đình.", "dự phòng cho tương lai.", "tăng quỹ tiền mặt cho hoạt động mua sắm.", "tối ưu hoá sử dụng thu nhập của gia đình."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: Đề 4 đáp án.docx · Phần I câu 11 · khoá: gạch chân"}, {"id": "L12-HK1-10-C12", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Khi xác đinh mục tiêu tài chính trong gia đình, cần đảm bảo nguyên tắc nào dưới đây?", "o": ["Vừa làm vừa thay đổi thời gian thực hiện theo ý muốn.", "Không xác định thời gian hoàn thành mục tiêu tài chính.", "Làm xong công việc rồi mới xác định mục tiêu tài chính.", "Dự kiến thời gian hoàn thành mục tiêu."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: Đề 4 đáp án.docx · Phần I câu 12 · khoá: gạch chân"}, {"id": "L12-HK1-10-C13", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Quá trình xác định, theo dõi và tối ưu hoá các nguồn thu nhập để đảm bảo tài chính gia đình được gọi l�", "o": ["quản lí hoạt động tiêu dùng của cá nhân và gia đình.", "quản lí thu nhập trong gia đình.", "quản lí hoạt động kinh tế của doanh nghiệp và hộ kinh doanh.", "quản lí chi tiêu trong gia đình và các khoản dự phòng."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: Đề 4 đáp án.docx · Phần I câu 13 · khoá: gạch chân"}, {"id": "L12-HK1-10-C14", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Nội dung nào dưới đây không phải là tiêu chí khi xác định mục tiêu tài chính của gia đình?", "o": ["Mục tiêu tài chính vô hạn.", "Mục tiêu tài chính ngắn hạn.", "Mục tiêu tài chính trung hạn.", "Mục tiêu tài chính dài hạn."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: Đề 4 đáp án.docx · Phần I câu 14 · khoá: gạch chân"}, {"id": "L12-HK1-10-C15", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Quản lý thu chi trong gia đình là việc sử dụng các nội dung nào dưới đây để đáp ứng nhu cầu vật chất và tinh thần của các thành viên trong gia đình?", "o": ["Các khoản chi tiêu thiết yếu và không thiết yếu.", "Các khoản tài trợ từ bên ngoài gia đình.", "Các khoản thu, chi.", "Các khoản thu nhập từ lương và kinh doanh."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: Đề 4 đáp án.docx · Phần I câu 15 · khoá: gạch chân"}, {"id": "L12-HK1-10-C16", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Nội dung nào dưới đây thể hiện việc xác định các khoản chi tiêu trong gia đình khi lập kế hoạch quản lý thu chi?", "o": ["Chủ động tiềm kiếm nguồn thu nhập.", "Xác định khoản chi tiêu thiết yếu.", "Ghi chép các khoản chi tiêu hàng ngày.", "Thống nhất tỷ lệ phân chia các khoản."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: Đề 4 đáp án.docx · Phần I câu 16 · khoá: gạch chân"}, {"id": "L12-HK1-10-C17", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Để xây dựng kế hoạch quản lý thu, chi hợp lý, mỗi gia đình cần thảo luận dân chủ để cùng nhau", "o": ["xác định vai trò của mỗi cá nhân.", "xác định dòng vốn cần đầu tư.", "xác định công việc của mỗi thành viên.", "xác định mục tiêu tài chính phù hợp."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: Đề 4 đáp án.docx · Phần I câu 17 · khoá: gạch chân"}, {"id": "L12-HK1-10-C18", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Việc làm nào dưới đây thể hiện thói quen chi tiêu hợp lý trong gia đình?", "o": ["Thiết lập mục tiêu tài chính.", "Chi tiêu quá mức thu nhập hằng tháng của gia đình.", "Không xây dựng quỹ dự phòng cho các khoản chi phát sinh.", "Chi tiêu không có kế hoạch và không theo dõi thu chi."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: Đề 4 đáp án.docx · Phần I câu 18 · khoá: gạch chân"}, {"id": "L12-HK1-10-C19", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Thói quen chi tiêu nào dưới đây là phù hợp với việc quản lý chi tiêu trong gia đình?", "o": ["Dành toàn bộ thu nhập cho tiêu dùng hằng tháng.", "Chi tiêu tự do theo sở thích cá nhân của từng người.", "Dành toàn bộ thu nhập cho tiết kiệm mà không chi tiêu.", "Chi tiêu theo kế hoạch đã lập."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: Đề 4 đáp án.docx · Phần I câu 19 · khoá: gạch chân"}, {"id": "L12-HK1-10-C20", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Để giúp gia đình kiểm soát được các khoản chi tiêu đồng thời đảm bảo được các mục tiêu tài chính đã xác định thì các thành viên trong gia đình cần có sự thống nhất về tỷ lệ", "o": ["phân chia các khoản chi tiêu.", "đóng góp vào mục tiêu chung.", "chi tiêu các khoản hàng tháng.", "số tiền sẽ phải tiết kiệm."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: Đề 4 đáp án.docx · Phần I câu 20 · khoá: gạch chân"}, {"id": "L12-HK1-10-C21", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đọc đoạn thông tin sau:\nVới mong muốn xây dựng thành công chuỗi cửa hàng phân phối thực phẩm sạch trên địa bàn huyện X, anh H đã lên kế hoạch chi tiết để thực hiện ý tưởng kinh doanh. Qua tìm hiểu thực tế anh nhận thấy đây là sản phẩm đang có nhu cầu lớn. Anh đã dự liệu được những rủi ro, khó khăn tiềm ẩn để có giải pháp khắc phục; đã lên kế hoạch chi tiết việc bán hàng, tiếp thị, quảng cáo.\nNội dung nào dưới đây thể hiện việc xác định ý tưởng kinh doanh của anh H?", "o": ["Đẩy mạnh quảng cáo sản phẩm.", "Xây dựng chuỗi cửa hàng.", "Mở cửa hàng chất lượng cao.", "Kinh doanh thực phẩm sạch."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: Đề 4 đáp án.docx · Phần I câu 21 · khoá: gạch chân"}, {"id": "L12-HK1-10-C22", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Anh H đã xác định mục tiêu kinh doanh của mình đó l�", "o": ["sản phẩm đang có nhu cầu lớn.", "xây dựng chuỗi thực phẩm sạch.", "tiếp cận nhu cầu người tiêu dùng.", "quảng cáo giới thiệu sản phẩm."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: Đề 4 đáp án.docx · Phần I câu 22 · khoá: gạch chân"}, {"id": "L12-HK1-10-C23", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đọc đoạn thông tin sau:\nSau khi cưới nhau, anh D và chị H dự định sau 3 năm sẽ mua nhà và ra ở riêng. Vợ chồng anh chị đồng thuận thực hiện kế hoạch quản lí thu, chi bằng sổ theo dõi hằng tháng. Theo đó, vợ chồng chị sẽ dành 50% tổng thu nhập cho chi tiêu thiết yếu; 20% cho các khoản dự phòng, tiết kiệm, mua nhà; và 30% còn lại cho các hoạt động giải trí, giao tiếp xã hội. Sau năm đầu, do có con nhỏ, anh chị buộc phải giảm số tiền cho các hoạt động giải trí để tăng cho các sinh hoạt thiết yếu; chị đã tham gia một gói bảo hiểm an sinh cho con mình đề phòng lúc ốm đau.\nGói bảo hiểm an sinh mà vợ chồng anh D và chị H tham gia cho con mình là loại hình bảo hiểm nào dưới đây?", "o": ["Bảo hiểm thất nghiệp.", "Bảo hiểm xã hội.", "Bảo hiểm thương mại.", "Bảo hiểm y tế."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: Đề 4 đáp án.docx · Phần I câu 23 · khoá: gạch chân"}, {"id": "L12-HK1-10-C24", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Nội dung nào dưới đây thể hiện việc xác định mục tiêu tài chính trong gia đình?", "o": ["Tham gia hoạt động giải trí và thể thao cuối tuần.", "Mua bảo hiểm an sinh cho con để phòng rủi ro ốm đau.", "Mua nhà và ra ở riêng sau 3 năm.", "Xây dựng sổ theo dõi thu chi hằng tháng của gia đình."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: Đề 4 đáp án.docx · Phần I câu 24 · khoá: gạch chân"}, {"id": "L12-HK1-10-C25", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "dung_sai", "status": "cho_duyet", "q": "Đọc đoạn thông tin sau và cho biết mỗi ý a, b, c, d là Đúng hay Sai. Một doanh nghiệp nhỏ phân tích điều kiện thực hiện ý tưởng kinh doanh thực phẩm hữu cơ. Qua khảo sát thị trường, sản phẩm, khách hàng và các đối thủ cạnh tranh cho thấy: xu hướng của người tiêu dùng ở khu vực này đang quan tâm đến việc ăn uống lành mạnh và thực phẩm hữu cơ. Thị trường ở đây đã có một vài cửa hàng thực phẩm, nhưng chưa có doanh nghiệp nào tập trung hoàn toàn vào thực phẩm hữu cơ.", "o": ["Thông tin nói về ý tưởng kinh doanh thực phẩm hữu cơ sau khi phân tích các điều kiện.", "Khi xác định ý tưởng kinh doanh chỉ cần lưu ý đến vấn đề tài chính.", "Chưa có doanh nghiệp tập trung vào thực phẩm hữu cơ trong khu vực là lợi thế cạnh tranh của sản phẩm.", "Nhu cầu sản phẩm trên thị trường là điều kiện để xác định ý tưởng kinh doanh."], "a": [true, false, true, true], "e": "Đáp án: a) Đúng; b) Sai; c) Đúng; d) Đúng.", "nguon": "Đề nguồn: Đề 4 đáp án.docx · Phần II câu 1 · khoá: chữ Đúng/Sai trong ý"}, {"id": "L12-HK1-10-C26", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "dung_sai", "status": "cho_duyet", "q": "Đọc đoạn thông tin sau và cho biết mỗi ý a, b, c, d là Đúng hay Sai. Công ty D chuyên sản xuất máy móc phục vụ cho nông nghiệp. Từ khi sản xuất kinh doanh có hiệu quả, công ty luôn chú trọng bảo vệ môi trường, thực hiện các biện pháp giảm lượng chất thải như rác, khói bụi, nước xả thải. Công ty còn hợp tác với tổ chức bảo tồn thiên nhiên quốc tế và Uỷ ban nhân dân tỉnh K để bảo tồn các vùng đất ngập nước tự nhiên. Công ty đầu tư xây dựng ba công trình công cộng cho cộng đồng.", "o": ["Biện pháp giảm chất thải, xử lí rác và khói bụi là trách nhiệm pháp lí khi kinh doanh.", "Hợp tác với tổ chức bảo tồn thiên nhiên quốc tế là thể hiện hội nhập kinh tế quốc tế.", "Bảo tồn vùng đất ngập nước là thể hiện trách nhiệm kinh tế của doanh nghiệp.", "Đóng góp xây dựng các công trình công cộng cho cộng đồng phù hợp với trách nhiệm nhân văn."], "a": [true, false, false, true], "e": "Đáp án: a) Đúng; b) Sai; c) Sai; d) Đúng.", "nguon": "Đề nguồn: Đề 4 đáp án.docx · Phần II câu 2 · khoá: chữ Đúng/Sai trong ý"}, {"id": "L12-HK1-10-C27", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "dung_sai", "status": "cho_duyet", "q": "Đọc đoạn thông tin sau và cho biết mỗi ý a, b, c, d là Đúng hay Sai. Sau khi tốt nghiệp đại học ngành công nghệ sinh học, với lợi thế là nhà gần các trường đại học, lại có diện tích đất lớn, chị D quyết định lập nghiệp bằng con đường kinh doanh sản phẩm cây cảnh mini với mong muốn sau hai năm sẽ thành lập một doanh nghiệp phân phối các sản phẩm này. Đây là lĩnh vực kinh doanh không đòi hỏi vốn lớn, trong khi thị trường là các bạn sinh viên có nhu cầu khá cao. Do thời gian đầu chưa có nhiều kinh nghiệm, sản phẩm nhiều cây gặp sâu bệnh chết. Từ thực tế kinh doanh, chị quyết định mở rộng sản xuất và đầu tư thêm nhiều cửa hàng mới.", "o": ["Việc chị D thành lập doanh nghiệp sau hai năm là bước đi thiếu cơ sở về thị trường.", "Mở rộng cửa hàng và phát triển kênh truyền thống nhằm mở rộng thị trường là phù hợp.", "Chị D không cần lập kế hoạch đầu tư vì doanh thu đã ổn định.", "Đối tượng khách hàng là sinh viên có nhu cầu cao là điều kiện thị trường chị D đã phân tích."], "a": [false, true, false, true], "e": "Đáp án: a) Sai; b) Đúng; c) Sai; d) Đúng.", "nguon": "Đề nguồn: Đề 4 đáp án.docx · Phần II câu 3 · khoá: chữ Đúng/Sai trong ý"}, {"id": "L12-HK1-10-C28", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "dung_sai", "status": "cho_duyet", "q": "Đọc đoạn thông tin sau và cho biết mỗi ý a, b, c, d là Đúng hay Sai. Nhận thấy quê hương mình rất phong phú về các loại thảo mộc và nhu cầu thị trường về dòng sản phẩm này ngày càng tăng lên, anh H đã xây dựng kế hoạch kinh doanh mĩ phẩm chiết xuất từ thiên nhiên. Sau khi đánh giá những thuận lợi và khó khăn, anh H nhận thấy kế hoạch kinh doanh của mình có khả thi. Nhờ xây dựng kế hoạch kinh doanh tốt, đánh giá đúng cơ hội, đối tượng khách hàng tiềm năng,… nên việc kinh doanh đã đạt được những thành công ban đầu.", "o": ["Anh H xác định ý tưởng kinh doanh khi nhận thấy quê hương có nhiều thảo mộc và nhu cầu thị trường tăng.", "Anh H đánh giá những thuận lợi và khó khăn là bước phân tích điều kiện thực hiện ý tưởng.", "Anh H xác định ý tưởng kinh doanh sau khi việc kinh doanh đã đạt thành công ban đầu.", "Đánh giá đúng cơ hội và khách hàng tiềm năng góp phần làm kế hoạch kinh doanh tốt."], "a": [true, true, false, true], "e": "Đáp án: a) Đúng; b) Đúng; c) Sai; d) Đúng.", "nguon": "Đề nguồn: Đề 4 đáp án.docx · Phần II câu 4 · khoá: chữ Đúng/Sai trong ý"}]}, {"id": "L12-8T2-01", "loai": "khoi", "khoi": 12, "hoc_ki": 2, "bo": "8T2", "ten_bo": "8 tuần học kì II", "so_de": 1, "ten": "Lớp 12 · 8 tuần học kì II · Đề 1", "pham_vi": "Đề nguồn «8 TUẦN KÌ 2 › BO_DE_MOI» · file nguồn: Đề 1 đáp án.docx", "thoi_gian": 50, "cau_truc": "24 câu trắc nghiệm + 4 câu đúng/sai (mỗi câu 4 ý)", "status": "cho_duyet", "khoa": {"1 nguồn": 28}, "sua": "", "cau": [{"id": "L12-8T2-01-C01", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Tăng trưởng kinh tế được hiểu là sự gia tăng", "o": ["tỉ lệ dân số sống ở khu vực thành thị của một quốc gia.", "phân phối lại thu nhập giữa các tầng lớp dân cư trong xã hội.", "quy mô sản lượng và thu nhập của nền kinh tế qua thời gian.", "số lượng văn bản pháp luật được ban hành hằng năm."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: Đề 1 đáp án.docx · Phần I câu 1 · khoá: gạch chân"}, {"id": "L12-8T2-01-C02", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Phát triển kinh tế khác tăng trưởng kinh tế ở điểm nào?", "o": ["Không cần có sự gia tăng sản lượng mà không cần xem xét đến hoàn cảnh cụ thể.", "Gắn với tiến bộ, công bằng xã hội và bảo vệ môi trường.", "Chỉ đo bằng GDP.", "Chỉ diễn ra ở các nước phát triển."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: Đề 1 đáp án.docx · Phần I câu 2 · khoá: gạch chân"}, {"id": "L12-8T2-01-C03", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Tiêu chí nào dưới đây thường được dùng để đánh giá mức độ phát triển kinh tế?", "o": ["Số giờ nắng trong năm.", "Số lượng xe máy lưu thông trên đường.", "GDP bình quân đầu người.", "Diện tích đất canh tác của một hộ."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: Đề 1 đáp án.docx · Phần I câu 3 · khoá: gạch chân"}, {"id": "L12-8T2-01-C04", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Phát triển bền vững bao gồm các trụ cột nào?", "o": ["Kinh tế, xã hội và môi trường.", "Thương mại, tài chính và thuế.", "Chính trị, quân sự và ngoại giao.", "Văn hóa, tôn giáo và du lịch."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: Đề 1 đáp án.docx · Phần I câu 4 · khoá: gạch chân"}, {"id": "L12-8T2-01-C05", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Mối quan hệ giữa tăng trưởng và phát triển kinh tế là", "o": ["tăng trưởng luôn làm giảm phát triển.", "tăng trưởng là điều kiện cần để đạt phát triển.", "phát triển không cần dựa vào tăng trưởng mà không cần xem xét đến hoàn cảnh cụ thể.", "hai khái niệm hoàn toàn đồng nhất."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: Đề 1 đáp án.docx · Phần I câu 5 · khoá: gạch chân"}, {"id": "L12-8T2-01-C06", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Chỉ số phát triển con người (HDI) dựa trên các nội dung nào?", "o": ["Diện tích, dân số và mật độ.", "Số lượng nhà máy và cảng biển trong mọi trường hợp, không cần căn cứ pháp luật.", "Thu nhập, giáo dục và tuổi thọ.", "Doanh thu xuất khẩu hằng năm."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: Đề 1 đáp án.docx · Phần I câu 6 · khoá: gạch chân"}, {"id": "L12-8T2-01-C07", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Cơ cấu kinh tế hợp lý là cơ cấu", "o": ["các ngành và thành phần kinh tế phát triển cân đối, phù hợp với điều kiện.", "chỉ có khu vực nông nghiệp.", "chỉ tập trung vào dịch vụ tài chính mà không cần xem xét đến hoàn cảnh cụ thể.", "không thay đổi qua thời gian."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: Đề 1 đáp án.docx · Phần I câu 7 · khoá: gạch chân"}, {"id": "L12-8T2-01-C08", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Vai trò của tăng trưởng kinh tế đối với đời sống xã hội là", "o": ["tạo việc làm và nâng cao mức sống của người dân.", "làm tăng thất nghiệp.", "làm giảm nguồn thu của Nhà nước.", "làm tăng bất bình đẳng về tài nguyên trong mọi trường hợp, không cần căn cứ pháp luật."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: Đề 1 đáp án.docx · Phần I câu 8 · khoá: gạch chân"}, {"id": "L12-8T2-01-C09", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Việc bảo vệ môi trường trong phát triển kinh tế có ý nghĩa", "o": ["hạn chế kinh tế phát triển.", "chỉ phục vụ mục đích du lịch.", "bảo đảm phát triển bền vững cho thế hệ hiện tại và tương lai.", "làm tăng chi phí sản xuất vô ích trong mọi trường hợp, không cần căn cứ pháp luật."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: Đề 1 đáp án.docx · Phần I câu 9 · khoá: gạch chân"}, {"id": "L12-8T2-01-C10", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Công dân có trách nhiệm gì trong phát triển kinh tế?", "o": ["Chỉ cần nhận lợi ích từ tăng trưởng.", "Tích cực học tập, lao động và bảo vệ môi trường.", "Đầu tư vào các ngành bị pháp luật cấm.", "Không tham gia các hoạt động cộng đồng mà không cần xem xét đến hoàn cảnh cụ thể."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: Đề 1 đáp án.docx · Phần I câu 10 · khoá: gạch chân"}, {"id": "L12-8T2-01-C11", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Hội nhập kinh tế quốc tế theo hình thức song phương là", "o": ["hợp tác toàn cầu trong WTO.", "hợp tác giữa hai quốc gia.", "hợp tác giữa các địa phương trong một nước.", "hợp tác giữa nhiều khu vực trên thế giới."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: Đề 1 đáp án.docx · Phần I câu 11 · khoá: gạch chân"}, {"id": "L12-8T2-01-C12", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Việt Nam gia nhập Tổ chức Thương mại thế giới (WTO) vào năm nào?", "o": ["1998.", "2016.", "1995 mà không cần xem xét đến hoàn cảnh cụ thể.", "2007."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: Đề 1 đáp án.docx · Phần I câu 12 · khoá: gạch chân"}, {"id": "L12-8T2-01-C13", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Việt Nam trở thành thành viên ASEAN vào năm 1995 là biểu hiện của hội nhập", "o": ["song phương.", "khu vực.", "toàn cầu.", "toàn quốc."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: Đề 1 đáp án.docx · Phần I câu 13 · khoá: gạch chân"}, {"id": "L12-8T2-01-C14", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Cấp độ hội nhập kinh tế quốc tế nào xóa bỏ hầu hết hàng rào thuế quan và phi thuế quan giữa các bên?", "o": ["Thương mại ưu đãi.", "Liên minh thuế quan mà không cần xem xét đến hoàn cảnh cụ thể.", "Thị trường chung.", "Khu vực mậu dịch tự do."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: Đề 1 đáp án.docx · Phần I câu 14 · khoá: gạch chân"}, {"id": "L12-8T2-01-C15", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Lợi ích của hội nhập kinh tế quốc tế đối với Việt Nam là", "o": ["giảm hoàn toàn vai trò của Nhà nước.", "mở rộng thị trường và thu hút đầu tư nước ngoài.", "đóng cửa thị trường trong nước.", "làm giảm sức cạnh tranh của doanh nghiệp mà không cần xem xét đến hoàn cảnh cụ thể."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: Đề 1 đáp án.docx · Phần I câu 15 · khoá: gạch chân"}, {"id": "L12-8T2-01-C16", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Công dân khi kinh doanh có quyền tự chủ đăng ký kinh doanh trong những ngành nghề nào?", "o": ["Những ngành nghề do chính quyền địa phương chỉ định.", "Những ngành nghề có lợi nhuận cao nhất.", "Những ngành nghề mà pháp luật không cấm.", "Những ngành nghề do người thân lựa chọn."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: Đề 1 đáp án.docx · Phần I câu 16 · khoá: gạch chân"}, {"id": "L12-8T2-01-C17", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Hành vi nào sau đây thể hiện nghĩa vụ kê khai thuế của người kinh doanh?", "o": ["Kê khai đầy đủ, đúng hạn các khoản thuế phát sinh.", "Kê khai thuế thay cho người khác.", "Không khai báo doanh thu để giảm thuế mà không cần xem xét đến hoàn cảnh cụ thể.", "Trì hoãn kê khai để chờ hoàn thuế."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: Đề 1 đáp án.docx · Phần I câu 17 · khoá: gạch chân"}, {"id": "L12-8T2-01-C18", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Theo quy định của pháp luật, doanh nghiệp có trách nhiệm bảo vệ quyền lợi nào sau đây?", "o": ["Quyền lợi của người tiêu dùng.", "Quyền quảng cáo không giới hạn.", "Quyền lợi của đối thủ cạnh tranh.", "Quyền sử dụng đất của hàng xóm."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: Đề 1 đáp án.docx · Phần I câu 18 · khoá: gạch chân"}, {"id": "L12-8T2-01-C19", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Công dân bị cơ quan thuế xử lý sai có quyền làm gì?", "o": ["Bỏ qua quyền lợi của mình.", "Tự ý không thực hiện quyết định.", "Đăng tải thông tin sai sự thật lên mạng.", "Khiếu nại theo quy định của pháp luật."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: Đề 1 đáp án.docx · Phần I câu 19 · khoá: gạch chân"}, {"id": "L12-8T2-01-C20", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đọc đoạn thông tin sau:\nHọc xong lớp 12, P tham dự kì thi tốt nghiệp trung học phổ thông và đạt số điểm rất cao khối A00, tuy nhiên, gia đình khó khăn không có điều kiện cho em thực hiện ước mơ học đại học. Khi biết tin, chính quyền địa phương cùng các cá nhân, cơ quan, tổ chức đã đến động viên, thăm hỏi, tặng quà và trao học bổng để giúp P tiếp tục đi học. Nhận được sự hỗ trợ kịp thời, P rất xúc động, em quyết định đăng kí học ngành công nghệ thông tin yêu thích ở trường đại học gần nhà để thực hiện ước mơ của mình\nNội dung nào dưới đây trong thông tin trên thể hiện quyền học không h ạ n c h ế c ủ a b ạ n P ?", "o": ["Chính quyền chung tay hỗ trợ mà không cần xem xét đến hoàn cảnh cụ thể.", "Có số điểm thi cao theo khối", "Được trao học bổng để theo học.", "Quyết tâm để học Đại học."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: Đề 1 đáp án.docx · Phần I câu 20 · khoá: gạch chân"}, {"id": "L12-8T2-01-C21", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đọc đoạn thông tin sau:\nHọc xong lớp 12, P tham dự kì thi tốt nghiệp trung học phổ thông và đạt số điểm rất cao khối A00, tuy nhiên, gia đình khó khăn không có điều kiện cho em thực hiện ước mơ học đại học. Khi biết tin, chính quyền địa phương cùng các cá nhân, cơ quan, tổ chức đã đến động viên, thăm hỏi, tặng quà và trao học bổng để giúp P tiếp tục đi học. Nhận được sự hỗ trợ kịp thời, P rất xúc động, em quyết định đăng kí học ngành công nghệ thông tin yêu thích ở trường đại học gần nhà để thực hiện ước mơ của mình\nNội dung nào dưới đây góp phần vào việc thực hiện quyền bình đẳng c ủ a c ô n g d â n t r o n g h ọ c t ậ p ?", "o": ["Trao học bổng để hỗ trợ khó khăn.", "Thăm hỏi động viên về tinh thần.", "Tham dự thi tốt nghiệp phổ thông.", "Mơ ước theo học bậc học Đại học."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: Đề 1 đáp án.docx · Phần I câu 21 · khoá: gạch chân"}, {"id": "L12-8T2-01-C22", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đọc đoạn thông tin sau:\nVì muốn con được vào lớp chất lượng cao trong trường chuyên của tỉnh, chị H nhờ ông B hiệu trưởng và được ông đồng ý với số tiền là 200 triệu đông. Sau khi nhận tiền, ông B đã cùng với bà P phó hiệu trưởng làm giả một số giấy tờ để cho con chị H đủ điều kiện. Do lớp chất lượng cao chỉ cho phép một số lượng học sinh cố định nên sau khi nhận con chị H vào ông B hiệu trưởng đã chuyển cháu S xuống lớp đại trà với lý do là kết quả học tập thấp nên bị bố cháu S là ông K làm đơn tố cáo tới cơ quan chức năng.\nChủ thể nào trong thông tin trên đã vi phạm quyền học tập của công d â n ?", "o": ["Chị H và ông", "Chị H, ông B và bà P.", "Ông B và bà P.", "Chị H, bà P và ông K trong mọi trường hợp, không cần căn cứ pháp luật."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: Đề 1 đáp án.docx · Phần I câu 22 · khoá: gạch chân"}, {"id": "L12-8T2-01-C23", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đọc đoạn thông tin sau:\nÔng H nhận bằng tốt nghiệp Trung học phổ thông ở tuổi 68 khiến bạn bè v� người thân không khỏi ngưỡng mộ. Ông chia sẻ rằng, lúc còn trẻ ông rất thích đi học, nhưng vì hoàn cảnh gia đình khó khăn nên ông chỉ được học đến hết lớp 11. Để có thể tốt nghiệp kì thi này, ông đã đăng ký tham gia học tập văn hóa lớp 12 tại Trung tâm Giáo dục thường xuyên của quận. Trong suốt quá trình học tập tại đây, ngoài việc nghiêm chỉnh chấp hành nội quy của Trung tâm, ông H còn không ngừng cố gắng tự học. Ông hi vọng rằng tinh thần hiếu học của bản thân sẽ lan toả được đến các con, cháu của mình.\nNội dung nào trong thông tin trên không thể hiện quyền của người h ọ c ?", "o": ["Thực hiện tốt nội quy đề ra.", "Đăng ký học lấy bằng THPT.", "Tự học tập, tự nghiên cứu.", "Lựa chọn hình thức học tập mà không cần xem xét đến hoàn cảnh cụ thể."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: Đề 1 đáp án.docx · Phần I câu 23 · khoá: gạch chân"}, {"id": "L12-8T2-01-C24", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đọc đoạn thông tin sau:\nÔng H nhận bằng tốt nghiệp Trung học phổ thông ở tuổi 68 khiến bạn bè v� người thân không khỏi ngưỡng mộ. Ông chia sẻ rằng, lúc còn trẻ ông rất thích đi học, nhưng vì hoàn cảnh gia đình khó khăn nên ông chỉ được học đến hết lớp 11. Để có thể tốt nghiệp kì thi này, ông đã đăng ký tham gia học tập văn hóa lớp 12 tại Trung tâm Giáo dục thường xuyên của quận. Trong suốt quá trình học tập tại đây, ngoài việc nghiêm chỉnh chấp hành nội quy của Trung tâm, ông H còn không ngừng cố gắng tự học. Ông hi vọng rằng tinh thần hiếu học của bản thân sẽ lan toả được đến các con, cháu của mình.\nThông tin trên thể hiện ông H đã lựa chọn hình thức học tập nào d ư ớ i đ â y ?", "o": ["Vừa học vừa làm.", "Học thông qua sự ủy quyền mà không cần xem xét đến hoàn cảnh cụ thể.", "Học không hạn chế.", "Học thường xuyên, suốt đời."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: Đề 1 đáp án.docx · Phần I câu 24 · khoá: gạch chân"}, {"id": "L12-8T2-01-C25", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "dung_sai", "status": "cho_duyet", "q": "Đọc đoạn thông tin sau và cho biết mỗi ý a, b, c, d là Đúng hay Sai. Gần đây, Trường Đại học C tổ chức kì thi kết thúc học phần nhưng do không nắm vững kiến thức các môn học nên M (sinh viên Trường Đại học C) quyết định tìm người thi hộ. Thông qua mạng xã hội, M thuê B (sinh viên một trường đại học khác trên địa bàn) thi hộ hai môn chuyên ngành với giá 600.000 đồng/môn. Tuy nhiên, khi B đang sử dụng giấy tờ giả để tham dự kì thi hộ M thì đã bị giám thị phát hiện. Sau đó các cơ quan chức năng đã tiến hành xử lý hành vi vi phạm của cả M và B bằng hình thức đuổi học.", "o": ["Sinh viên M đã vi phạm quyền học tập của sinh viên B.", "Bạn M và B đều được học tập tại các trường đại học là thực hiện quyền học tập của công dân.", "Việc cơ quan chức năng tiến hành đuổi học bạn M và bạn B là vi phạm quyền học tập của công dân.", "Việc bạn M và bạn B khiếu nại quyết định kỷ luật đối với mình là không phù hợp vì hành vi của 2 người là cụ thể."], "a": [false, true, false, false], "e": "Đáp án: a) Sai; b) Đúng; c) Sai; d) Sai.", "nguon": "Đề nguồn: Đề 1 đáp án.docx · Phần II câu 1 · khoá: chữ Đúng/Sai trong ý"}, {"id": "L12-8T2-01-C26", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "dung_sai", "status": "cho_duyet", "q": "Đọc đoạn thông tin sau và cho biết mỗi ý a, b, c, d là Đúng hay Sai. Trước đây, điều kiện gia đình khó khăn nên ông Đ phải nghỉ học giữa chừng để kiếm tiền phụ giúp bố mẹ. Mỗi khi nhìn bạn bè theo đuổi con đường học tập, ông luôn cảm thấy tiếc nuối. Khi lập gia đình và có con, ông Đ đặt hết mọi kì vọng của bản thân lên các con của mình. Vì vậy, ông luôn cố gắng tạo điều kiện về kinh tế để các con yên tâm học tập nhưng lại luôn so sánh, tạo sức ép, bắt các con phải tập trung học tập, ngăn cấm các con tham gia những hoạt động văn hoá, văn nghệ, thể dục thể thao và những hoạt động xã hội khác. Gần đây, khi nhận tin con trai cả không thi đỗ vào trường chuyên của tỉnh, ông Đ vô cùng tức giận. Ông dùng nhiều lời lẽ tiêu cực để so sánh con với các bạn học khác và tuyên bố không cho con đi học.", "o": ["Ông Đ bị xâm phạm đến quyền học tập của công dân.", "Các con của ông Đ đã được thực hiện tốt quyền học tập của mình.", "Việc cấm các con không được tham gia các hoạt động văn hóa, văn nghệ để học tập là phù hợp với quyền và nghĩa vụ giữa cha mẹ và con.", "Việc dùng lời lẽ tiêu cực và so sánh kết quả học tập của con mình với các bạn khác của ông Đ là hành vi xâm phạm đến quyền của công dân trong gia đình và trong học tập."], "a": [false, true, false, true], "e": "Đáp án: a) Sai; b) Đúng; c) Sai; d) Đúng.", "nguon": "Đề nguồn: Đề 1 đáp án.docx · Phần II câu 2 · khoá: chữ Đúng/Sai trong ý"}, {"id": "L12-8T2-01-C27", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "dung_sai", "status": "cho_duyet", "q": "Đọc đoạn thông tin sau và cho biết mỗi ý a, b, c, d là Đúng hay Sai. S là sinh viên năm thứ nhất của một trường đại học. Sau khi tìm hiểu các quy định của trường, S đã quyết định đăng kí thêm các môn học khác so với chương trình tiêu chuẩn mỗi học kì. S nhận thấy các môn có sự liên kết nhất định với nhau và nếu tích luỹ đủ các tín chỉ theo chương trình đào tạo có thể ra trường sớm hơn so với các bạn. Biết được ý định của con, bố mẹ đã ra sức phản đối không cho S đăng kí học vượt với lí do không phù hợp với trình độ nhận thức nhưng S vẫn làm hồ sơ đăng ký học thêm và được chấp nhận. Tuy nhiên do không sắp xếp được giữa việc học và đi làm thêm nên sau một năm đăng ký học thêm, S không đủ điều kiện được học tiếp.", "o": ["Sinh viên S đã được thực hiện quyền học tập của mình một cách phù hợp.", "Việc phản đối của bố mẹ S là vi phạm quyền học tập của công dân.", "Việc không đủ điều kiện được học tiếp các của sinh viên S không vi phạm nghĩa vụ học tập của công dân.", "Sinh viên S có quyền được khiếu nại để nhà trường xem xét lại quyết định không cho học tiếp đối với bản thân mình."], "a": [true, true, false, true], "e": "Đáp án: a) Đúng; b) Đúng; c) Sai; d) Đúng.", "nguon": "Đề nguồn: Đề 1 đáp án.docx · Phần II câu 3 · khoá: chữ Đúng/Sai trong ý"}, {"id": "L12-8T2-01-C28", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "dung_sai", "status": "cho_duyet", "q": "Đọc đoạn thông tin sau và cho biết mỗi ý a, b, c, d là Đúng hay Sai. Sau khi thi đỗ vào trường Đại học mơ ước, V quyết tâm học thật tốt với mong muốn có được việc làm phù hợp với chuyên ngành. Ngay từ năm thứ nhất, V đặt mục tiêu ra trường sớm để có thể giúp đỡ gia đình. Do đó, V đã lập kế hoạch học tập và đăng kí học vượt. Kết quả là V đã tốt nghiệp sớm hơn một năm v� có thể tự tin tìm việc với bằng tốt nghiệp loại Giỏi của mình và đủ điều kiện được học tiếp Thạc sỹ. Khi nộp hồ sơ ứng tuyển vào các công ty, hồ sơ của V đều bị loại với lý do V chưa có kinh nghiệm thực tế. Xuất phát từ thực tế đó, V quyết định vừa đăng ký học thạc sĩ vừa xin đi làm thêm cho một số công ty để tích lũy kinh nghiệm.", "o": ["Việc V đỗ vào trường Đại học mình mơ ước là phù hợp với quyền học tập không hạn chế của công dân.", "Sinh viên V vừa đi học Thạc sỹ vừa đi làm là chưa phù hợp với nghĩa vụ của công dân về học tập.", "Công dân có quyền đăng ký học trước tuổi, học vượt lớp nếu đủ điều kiện.", "Ngoài việc được thực hiện quyền học tập không hạn chế, sinh viên V đã lựa chọn hình thức học tập thường xuyên, học suốt đời để phù hợp với bản thân."], "a": [true, false, true, true], "e": "Đáp án: a) Đúng; b) Sai; c) Đúng; d) Đúng.", "nguon": "Đề nguồn: Đề 1 đáp án.docx · Phần II câu 4 · khoá: chữ Đúng/Sai trong ý"}]}, {"id": "L12-8T2-02", "loai": "khoi", "khoi": 12, "hoc_ki": 2, "bo": "8T2", "ten_bo": "8 tuần học kì II", "so_de": 2, "ten": "Lớp 12 · 8 tuần học kì II · Đề 2", "pham_vi": "Đề nguồn «8 TUẦN KÌ 2 › BO_DE_MOI» · file nguồn: Đề 2 đáp án.docx", "thoi_gian": 50, "cau_truc": "24 câu trắc nghiệm + 4 câu đúng/sai (mỗi câu 4 ý)", "status": "cho_duyet", "khoa": {"1 nguồn": 28}, "sua": "", "cau": [{"id": "L12-8T2-02-C01", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Tăng trưởng kinh tế thường được đo bằng chỉ tiêu nào?", "o": ["Tỷ lệ tăng dân số tự nhiên.", "Số lượng trường học mới.", "Tốc độ tăng của GDP.", "Số lượng thẻ ATM đang lưu hành."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: Đề 2 đáp án.docx · Phần I câu 1 · khoá: gạch chân"}, {"id": "L12-8T2-02-C02", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Điểm khác biệt cơ bản giữa tăng trưởng và phát triển kinh tế là", "o": ["không có điểm khác biệt nào.", "phát triển chỉ đo bằng sản lượng.", "phát triển bao hàm cả tiến bộ, công bằng xã hội và môi trường.", "tăng trưởng bao hàm cả giáo dục và y tế trong mọi trường hợp, không cần căn cứ pháp luật."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: Đề 2 đáp án.docx · Phần I câu 2 · khoá: gạch chân"}, {"id": "L12-8T2-02-C03", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Chuyển dịch cơ cấu kinh tế theo hướng công nghiệp hóa, hiện đại hóa là giảm tỉ trọng ngành nào?", "o": ["Công nghệ thông tin.", "Công nghiệp và dịch vụ.", "Nông nghiệp.", "Xuất nhập khẩu."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: Đề 2 đáp án.docx · Phần I câu 3 · khoá: gạch chân"}, {"id": "L12-8T2-02-C04", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Vai trò của tăng trưởng kinh tế đối với Nhà nước là", "o": ["tăng nguồn thu ngân sách để chi cho an sinh và phúc lợi.", "giảm nhu cầu chi tiêu công.", "làm suy giảm nguồn lực của quốc gia trong mọi trường hợp, không cần căn cứ pháp luật.", "xóa bỏ hoàn toàn vai trò quản lý."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: Đề 2 đáp án.docx · Phần I câu 4 · khoá: gạch chân"}, {"id": "L12-8T2-02-C05", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Việc Việt Nam gia nhập ASEAN vào năm 1995 đánh dấu bước đi trong hội nhập ở cấp độ nào?", "o": ["Song phương.", "Khu vực.", "Toàn cầu.", "Cấp địa phương."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: Đề 2 đáp án.docx · Phần I câu 5 · khoá: gạch chân"}, {"id": "L12-8T2-02-C06", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Hiệp định thương mại tự do khác với liên minh thuế quan ở điểm nào?", "o": ["Các bên không xóa bỏ bất kỳ thuế quan nào.", "Các bên chỉ hợp tác về văn hóa.", "Các bên áp dụng chung một biểu thuế đối với nước ngoài mà không cần xem xét đến hoàn cảnh cụ thể.", "Các bên xóa bỏ thuế và hàng rào phi thuế nhưng vẫn giữ thuế riêng đối với nước ngoài."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: Đề 2 đáp án.docx · Phần I câu 6 · khoá: gạch chân"}, {"id": "L12-8T2-02-C07", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Một thành viên APEC thường được hưởng lợi ích nào?", "o": ["Không phải tuân thủ bất kỳ quy định chung nào mà không cần xem xét đến hoàn cảnh cụ thể.", "Bị hạn chế tiếp cận thị trường các nước khác.", "Mở rộng cơ hội thương mại và đầu tư trong khu vực châu Á – Thái Bình Dương.", "Được miễn toàn bộ thuế nhập khẩu vĩnh viễn."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: Đề 2 đáp án.docx · Phần I câu 7 · khoá: gạch chân"}, {"id": "L12-8T2-02-C08", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Hội nhập kinh tế quốc tế đặt ra yêu cầu nào đối với doanh nghiệp Việt Nam?", "o": ["Từ bỏ việc xuất khẩu hàng hóa.", "Nâng cao năng lực cạnh tranh và tuân thủ luật chơi quốc tế.", "Không cần đổi mới công nghệ.", "Chỉ hoạt động trong thị trường nội địa mà không cần xem xét đến hoàn cảnh cụ thể."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: Đề 2 đáp án.docx · Phần I câu 8 · khoá: gạch chân"}, {"id": "L12-8T2-02-C09", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Công dân tham gia hội nhập cần có ý thức nào?", "o": ["Làm theo cảm tính và không cần hiểu luật mà không cần xem xét đến hoàn cảnh cụ thể.", "Chấp nhận mọi hàng hóa nhập lậu.", "Chỉ quan tâm đến lợi ích cá nhân.", "Bảo vệ lợi ích quốc gia và tôn trọng pháp luật."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: Đề 2 đáp án.docx · Phần I câu 9 · khoá: gạch chân"}, {"id": "L12-8T2-02-C10", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Nội dung nào dưới đây là thách thức của hội nhập đối với nền kinh tế?", "o": ["Mở rộng thị trường xuất khẩu.", "Tiếp thu kinh nghiệm quản lý tiên tiến trong mọi trường hợp, không cần căn cứ pháp luật.", "Nguy cơ phụ thuộc vào thị trường bên ngoài và cạnh tranh không lành mạnh.", "Thu hút vốn đầu tư nước ngoài."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: Đề 2 đáp án.docx · Phần I câu 10 · khoá: gạch chân"}, {"id": "L12-8T2-02-C11", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Bảo hiểm thương mại là loại hình", "o": ["chỉ dành cho người cao tuổi.", "người dân tự nguyện mua từ doanh nghiệp bảo hiểm.", "bắt buộc đối với mọi công dân mà không cần xem xét đến hoàn cảnh cụ thể.", "do Nhà nước cấp không thu phí."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: Đề 2 đáp án.docx · Phần I câu 11 · khoá: gạch chân"}, {"id": "L12-8T2-02-C12", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đối tượng tham gia bảo hiểm xã hội bắt buộc gồm", "o": ["người lao động làm việc theo hợp đồng lao động.", "học sinh phổ thông.", "người nước ngoài du lịch ngắn ngày mà không cần xem xét đến hoàn cảnh cụ thể.", "mọi người dân không có việc làm."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: Đề 2 đáp án.docx · Phần I câu 12 · khoá: gạch chân"}, {"id": "L12-8T2-02-C13", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Việc đóng bảo hiểm xã hội đúng hạn và đủ số tiền có ý nghĩa gì?", "o": ["Được miễn trách nhiệm pháp lý.", "Được quyền sử dụng tài sản của người khác trong mọi trường hợp, không cần căn cứ pháp luật.", "Bảo đảm quyền lợi khi ốm đau, thai sản, hưu trí, tử tuất.", "Được miễn toàn bộ thuế thu nhập."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: Đề 2 đáp án.docx · Phần I câu 13 · khoá: gạch chân"}, {"id": "L12-8T2-02-C14", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Trợ giúp xã hội thường xuất phát từ nguồn lực nào?", "o": ["Từ tiền cho vay nặng lãi.", "Từ ngân sách Nhà nước và sự đóng góp của cộng đồng.", "Chỉ từ ngân sách của doanh nghiệp tư nhân trong mọi trường hợp, không cần căn cứ pháp luật.", "Từ quỹ đầu tư nước ngoài."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: Đề 2 đáp án.docx · Phần I câu 14 · khoá: gạch chân"}, {"id": "L12-8T2-02-C15", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Chính sách bảo hiểm xã hội nhằm", "o": ["thay thế hoàn toàn trách nhiệm của gia đình mà không cần xem xét đến hoàn cảnh cụ thể.", "bảo đảm thu nhập khi người lao động bị giảm hoặc mất thu nhập.", "ngăn cản người lao động nghỉ hưu.", "tăng thuế cho người lao động."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: Đề 2 đáp án.docx · Phần I câu 15 · khoá: gạch chân"}, {"id": "L12-8T2-02-C16", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Doanh nghiệp mở rộng quy mô sản xuất khi đã đủ điều kiện là thể hiện quyền nào?", "o": ["Quyền miễn trừ nghĩa vụ thuế.", "Quyền sử dụng lao động không hợp đồng mà không cần xem xét đến hoàn cảnh cụ thể.", "Quyền chiếm đoạt tài nguyên.", "Quyền chủ động mở rộng quy mô kinh doanh."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: Đề 2 đáp án.docx · Phần I câu 16 · khoá: gạch chân"}, {"id": "L12-8T2-02-C17", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Việc doanh nghiệp tự do liên doanh, liên kết với đối tác thể hiện nội dung nào?", "o": ["Hành vi cạnh tranh không lành mạnh.", "Nghĩa vụ nộp thuế thay cho đối tác.", "Trách nhiệm hình sự.", "Quyền tự chủ kinh doanh."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: Đề 2 đáp án.docx · Phần I câu 17 · khoá: gạch chân"}, {"id": "L12-8T2-02-C18", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Người nộp thuế có quyền nào sau đây?", "o": ["Được cung cấp thông tin, tài liệu để thực hiện nghĩa vụ thuế.", "Được từ chối kê khai thuế.", "Được miễn mọi loại thuế.", "Được gian lận hồ sơ thuế để giảm chi phí mà không cần xem xét đến hoàn cảnh cụ thể."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: Đề 2 đáp án.docx · Phần I câu 18 · khoá: gạch chân"}, {"id": "L12-8T2-02-C19", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Hành vi nào sau đây vi phạm nghĩa vụ kinh doanh đúng ngành nghề?", "o": ["Nộp hồ sơ đăng ký đầy đủ.", "Đăng ký ngành nghề phù hợp với năng lực trong mọi trường hợp, không cần căn cứ pháp luật.", "Kinh doanh thêm mặt hàng không có trong giấy phép.", "Kinh doanh đúng mặt hàng đã đăng ký."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: Đề 2 đáp án.docx · Phần I câu 19 · khoá: gạch chân"}, {"id": "L12-8T2-02-C20", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đọc đoạn thông tin sau:\nÔng B có hai người con. Mặc dù điều kiện kinh tế của gia đình ông không khó khăn nhưng ông cho rằng con gái thì không cần học nhiều mà chỉ cần lấy chồng có điều kiện kinh tế là được. Vì vậy, khi con gái ông là chị T học hết lớp 9, ông không cho chị tiếp tục học THPT mà ở nhà phụ giúp công việc gia đình. Anh C là con trai của ông B sau khi học hết THPT thì rất muốn tiếp tục theo học ngành Mĩ thuật của một trường cao đẳng vì anh có năng khiếu và rất yêu thích công việc liên quan đến lĩnh vực này, thấy được nguyện vọng của anh C, ông B đã động viên và tạo điều kiện để anh C ôn luyện và tham gia thi tuyển. Kết quả anh C đã trúng tuyển vào trường Đại học phù hợp với nguyện vọng của mình.\nNội dung nào dưới đây thể hiện ông B đã vi phạm nghĩa vụ của công d â n t r o n g h ọ c t ậ p ?", "o": ["Quan tâm động viên con.", "Tạo điều kiện để con đi học.", "Không cho con đi học tiếp.", "Yêu cầu con phụ giúp bố mẹ."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: Đề 2 đáp án.docx · Phần I câu 20 · khoá: gạch chân"}, {"id": "L12-8T2-02-C21", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đọc đoạn thông tin sau:\nNgay sau khi hoàn thành nghĩa vụ quân sự và trở lại địa phương sinh sống anh S đã nộp hồ sơ xin trợ cấp học nghề gửi cơ quan nhà nước có thẩm quyền và được đồng ý. Khi hoàn thành quá trình học nghề với chuyên môn nhất định, anh S được Uỷ ban nhân dân xã A tạo điều kiện hỗ trợ để có thể mở xưởng sản xuất với quy mô nhỏ. Ngoài ra, anh còn được Ngân hàng chính sách xã hội tạo điều kiện cho vay vốn ưu đãi để xưởng sản xuất có thể đi vào hoạt động ổn định.\nViệc làm nào dưới đây của anh S thể hiện quyền của công dân trong đ ả m b ả o a n s i n h x ã h ộ i ?", "o": ["Tìm công việc để ổn định.", "Phục viên trở về địa phương mà không cần xem xét đến hoàn cảnh cụ thể.", "Nộp hồ sơ xin trợ cấp học nghề.", "Thực hiện nghĩa vụ quân sự."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: Đề 2 đáp án.docx · Phần I câu 21 · khoá: gạch chân"}, {"id": "L12-8T2-02-C22", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đọc đoạn thông tin sau:\nBạn G là một học sinh bị khuyết tật vận động từ khi còn nhỏ. Trong quá trình học tập, cùng với sự cố gắng nỗ lực của gia đình, G luôn nhận được sự quan tâm của nhà trường và chính quyền địa phương nhằm tạo điều kiện học tập tốt nhất. G cũng được thăm khám sức khoẻ thường xuyên và được cấp phát thuốc để đảm bảo sức khoẻ. Sau khi tốt nghiệp đại học G đi xin việc thì lại bị một số doanh nghiệp từ chối và kì thị với lí do bị khuyết không đáp ứng được yêu cầu của công việc.\nTrong thông tin trên, chủ thể nào dưới đây chưa thực hiện tốt nghĩa v ụ c ủ a c ô n g d â n t r o n g v i ệ c b ả o v ề c h ă m s ó c s ứ c k h ỏ e v à b ả o đ ả m a n s i n h x ã h ộ i c ủ a c ô n g d â n ?", "o": ["Doanh nghiệp", "Chính quyền", "Nhà trường.", "Gia đình G mà không cần xem xét đến hoàn cảnh cụ thể."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: Đề 2 đáp án.docx · Phần I câu 22 · khoá: gạch chân"}, {"id": "L12-8T2-02-C23", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đọc đoạn thông tin sau:\nBà C phát hiện cơ thể mình xuất hiện một số triệu chứng mắc bệnh bệnh truyền nhiễm nhưng không thông báo với cán bộ y tế ở địa phương mà tự mua thuốc về chữa trị. Đồng thời, bà vẫn xuất hiện ở những nơi đông người như trường học, khu công nghiệp, trung tâm thương mại mà không thực hiện bất kì phương pháp bảo hộ nào.\nBà C chưa thực hiện tốt nghĩa vụ của công dân trong việc bảo vệ v� c h ă m s ó c s ứ c k h ỏ e ở n ộ i d u n g n à o d ư ớ i đ â y ?", "o": ["Tích cực tham gia hoạt động cộng đồng.", "Chủ động chăm sóc sức khỏe bản thân.", "Chấp hành quy định phòng chống dịch.", "Giữ bí mật thông tin về tình trạng bệnh."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: Đề 2 đáp án.docx · Phần I câu 23 · khoá: gạch chân"}, {"id": "L12-8T2-02-C24", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đọc đoạn thông tin sau:\nNgười thân của bà M phát hiện bà đang nằm hôn mê, bất động trên trên nền nhà nên vội đưa bà tới Bệnh viện A ở gần nhà để cấp cứu. Khi tới bệnh viện, bà M được nhân viên bệnh viện đưa vào phòng bệnh. Tuy nhiên, sau khi thăm khám, nhân viên y tế lại đẩy băng ca đưa bà M ra ngoài, từ chối chữa trị vì tình trạng bệnh của bà quá nặng, bệnh viện thiếu bác sĩ, thiếu trang bị y tế. Không nhận được sự hỗ trợ từ Bệnh viện A, người thân của bà M buộc phải liên hệ, tìm kiếm phương tiện để đưa bà tới một cơ sở y tế khác cấp cứu khi bà đang ở trong tình trạng nguy kịch.\nTrong thông tin trên, nhân viên y tế không vi phạm nghĩa vụ nào d ư ớ i đ â y t r o n g b ả o v ệ v à c h ă m s ó c s ứ c k h ỏ e c ô n g d â n ?", "o": ["Thực hiện khám bệnh theo quy định.", "Thực hiện công tác phòng chống dịch.", "Tư vấn hỗ trợ bệnh nhân chữa bệnh.", "Tôn trọng người bệnh và người nhà."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: Đề 2 đáp án.docx · Phần I câu 24 · khoá: gạch chân"}, {"id": "L12-8T2-02-C25", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "dung_sai", "status": "cho_duyet", "q": "Đọc đoạn thông tin sau và cho biết mỗi ý a, b, c, d là Đúng hay Sai. Được nuông chiều từ bé nên B có tính tình kiêu căng. Khi bước vào bậc THPT, B hầu như không tương tác hoặc chơi cùng với các bạn. Nhiều lần B có thái độ không tôn trọng thầy cô giáo. Cho rằng gia đình mình có điều kiện nên khi sử dụng các trang thiết bị của lớp học, B thường không chú ý giữ gìn, bảo quản. Khi được giáo viên nhắc nhở, B thường tỏ ra không quan tâm v� tuyên bố rằng bố mẹ sẽ bồi thường cho bất kì tổn thất nào gây ra cho trường học. Cuối năm học, B không đủ điều kiện xếp loại lên lớp và bị lưu ban. Xét thấy gia đình đủ điều kiện để lo cho cuộc sống của B sau này, bố mẹ B đã làm đơn cho B thôi học.", "o": ["Bố mẹ B chưa thực hiện tốt trách nhiệm của cha mẹ đối với con trong hôn nhân và gia đình.", "Hành vi không tôn trọng thầy cô giáo là vi phạm nghĩa vụ của công dân trong học tập.", "Việc làm đơn cho B thôi học của bố mẹ bạn B là vi phạm nghĩa vụ của công dân trong học tập.", "Bạn B bị lưu ban lại lớp là hậu quả của hành vi vi phạm quyền và nghĩa vụ của công dân trong học tập của bố mẹ bạn B."], "a": [true, true, true, false], "e": "Đáp án: a) Đúng; b) Đúng; c) Đúng; d) Sai.", "nguon": "Đề nguồn: Đề 2 đáp án.docx · Phần II câu 1 · khoá: chữ Đúng/Sai trong ý"}, {"id": "L12-8T2-02-C26", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "dung_sai", "status": "cho_duyet", "q": "Đọc đoạn thông tin sau và cho biết mỗi ý a, b, c, d là Đúng hay Sai. Khi bị ngất xỉu, chị P đã được gia đình đưa vào bệnh viện để khám bệnh. Trong quá trình trao đổi với bác sĩ M, chị P đã không kể chi tiết về những biểu hiện của cơ thể để không phải nhập viện. Nhưng với kinh nghiệm chuyên môn và qua khám ban đầu, bác sĩ M đã yêu cầu chị P đi chụp chiếu và làm một số xét nghiệm để xác định rõ tình trạng bệnh tim. Nhưng chị P lại không đồng ý với lí do sức khoẻ của minh vẫn tốt và yêu cầu người nhà đưa chị về.", "o": ["Chị P che giấu tình trạng sức khỏe của bản thân là phù hợp với quyền của công dân trong khám chữa bệnh.", "Việc yêu cầu chị P đi chụp chiếu và làm xét nghiệm là không cần thiết.", "Chị P và bác sĩ M đều chưa thực hiện đúng nghĩa vụ của công dân trong bảo vệ và chăm sóc sức khỏe.", "Bác sĩ M thực hiện đúng các quy định của pháp luật về bảo vệ và chăm sóc sức khỏe công dân."], "a": [false, false, false, true], "e": "Đáp án: a) Sai; b) Sai; c) Sai; d) Đúng.", "nguon": "Đề nguồn: Đề 2 đáp án.docx · Phần II câu 2 · khoá: chữ Đúng/Sai trong ý"}, {"id": "L12-8T2-02-C27", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "dung_sai", "status": "cho_duyet", "q": "Đọc đoạn thông tin sau và cho biết mỗi ý a, b, c, d là Đúng hay Sai. Sau khi kết thúc 2 tháng thử việc, ông V liên tục đưa ra nhiều lí do khác nhau để trì hoãn việc kí hợp đồng và đóng bảo hiểm y tế, bảo hiểm xã hội cho người lao động theo quy định của pháp luật. Đồng thời, ông V cũng không đầu tư trang bị bảo hộ lao động cho các công nhân làm việc trong xưởng sản xuất để đảm bảo an toàn và sức khoẻ cho họ.", "o": ["Ông V vừa vi phạm quyền và nghĩa vụ của công dân trong bảo vệ, chăm sóc sức khỏe và đảm bảo an sinh xã hội.", "Người lao động trong công ty của ông V có quyền khiếu nại tới cơ quan chức năng để yêu cầu ông V bồi thường thiệt hại.", "Ông V chuyển trực tiếp số tiền phải đóng bảo hiểm xã hội cho người lao động cho người lao động tự đóng là phù hợp với quy định của pháp luật.", "Ông V chưa thực hiện đúng trách nhiệm pháp lý và trách nhiệm từ thiện của doanh nghiệp."], "a": [true, false, false, false], "e": "Đáp án: a) Đúng; b) Sai; c) Sai; d) Sai.", "nguon": "Đề nguồn: Đề 2 đáp án.docx · Phần II câu 3 · khoá: chữ Đúng/Sai trong ý"}, {"id": "L12-8T2-02-C28", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "dung_sai", "status": "cho_duyet", "q": "Đọc đoạn thông tin sau và cho biết mỗi ý a, b, c, d là Đúng hay Sai. Vừa qua, trên địa bàn xã A thuộc huyện K xảy ra lũ ống, lũ quét gây ảnh hưởng nghiêm trọng đến sức khoẻ và tài sản của người dân nên chính quyền huyện K đã quyết định trích một phần ngân sách để hỗ trợ cho người dân khắc phục khó khăn, ổn định lại cuộc sống, số tiền hỗ trợ sẽ được phân bổ theo mức độ thiệt hại của từng hộ gia đình. Khi kê khai thiệt hại về tài sản, gia đình bà M đã cố tình kê khai mức thiệt hại lớn hơn so với thực tế để trục lợi. Việc làm của gia đình bà M bị ông H (cán bộ xã A) phát hiện nhưng do có mối quan hệ họ hàng với bà M nên ông H im lặng bỏ qua.", "o": ["Quyết định trích ngân sách để hỗ trợ các gia đình bị thiệt hại của xã A là góp phần thực hiện quyền được đảm bảo an sinh xã hội của người dân.", "Bà M đã được thực hiện quyền của công dân trong việc đảm bảo an sinh xã hội.", "Ông H và bà M đều chưa thực hiện đúng nghĩa vụ của công dân trong việc đảm bảo an sinh xã hội.", "Việc làm của ông H và bà M gây ra hậu quả mất công bằng trong việc thực hiện chính sách an sinh xã hội của nhà nước."], "a": [true, true, true, true], "e": "Đáp án: a) Đúng; b) Đúng; c) Đúng; d) Đúng.", "nguon": "Đề nguồn: Đề 2 đáp án.docx · Phần II câu 4 · khoá: chữ Đúng/Sai trong ý"}]}, {"id": "L12-8T2-03", "loai": "khoi", "khoi": 12, "hoc_ki": 2, "bo": "8T2", "ten_bo": "8 tuần học kì II", "so_de": 3, "ten": "Lớp 12 · 8 tuần học kì II · Đề 3", "pham_vi": "Đề nguồn «8 TUẦN KÌ 2 › BO_DE_MOI» · file nguồn: Đề 3 đáp án.docx", "thoi_gian": 50, "cau_truc": "24 câu trắc nghiệm + 4 câu đúng/sai (mỗi câu 4 ý)", "status": "cho_duyet", "khoa": {"1 nguồn": 28}, "sua": "", "cau": [{"id": "L12-8T2-03-C01", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đại lượng nào thường được dùng để đo tăng trưởng kinh tế?", "o": ["diện tích đất nông nghiệp được khai hoang mà không cần xem xét đến hoàn cảnh cụ thể.", "số lượng công chức trong bộ máy Nhà nước.", "tổng sản phẩm quốc nội (GDP) tăng qua các năm.", "mức chi tiêu cá nhân của mỗi hộ gia đình."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: Đề 3 đáp án.docx · Phần I câu 1 · khoá: gạch chân"}, {"id": "L12-8T2-03-C02", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Nội dung nào dưới đây KHÔNG thuộc tiêu chí đánh giá phát triển kinh tế?", "o": ["Trình độ giáo dục và tuổi thọ bình quân.", "Mức sống và chất lượng cuộc sống của người dân.", "Cơ cấu ngành kinh tế và chuyển dịch cơ cấu.", "Số lượng cây xanh trong thành phố."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: Đề 3 đáp án.docx · Phần I câu 2 · khoá: gạch chân"}, {"id": "L12-8T2-03-C03", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Phát triển kinh tế đòi hỏi", "o": ["tập trung vào một ngành duy nhất.", "hạn chế hoàn toàn đầu tư nước ngoài.", "kết hợp tăng trưởng với tiến bộ, công bằng xã hội và bảo vệ môi trường.", "chỉ tăng quy mô sản xuất bằng mọi giá trong mọi trường hợp, không cần căn cứ pháp luật."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: Đề 3 đáp án.docx · Phần I câu 3 · khoá: gạch chân"}, {"id": "L12-8T2-03-C04", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Việc hình thành Cộng đồng ASEAN là biểu hiện của hội nhập kinh tế quốc tế ở cấp độ", "o": ["khu vực.", "địa phương.", "song phương.", "toàn quốc."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: Đề 3 đáp án.docx · Phần I câu 4 · khoá: gạch chân"}, {"id": "L12-8T2-03-C05", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Liên minh thuế quan khác với khu vực mậu dịch tự do ở điểm nào?", "o": ["Không có sự hợp tác về thương mại.", "Các thành viên áp dụng chung biểu thuế đối với nước ngoài.", "Các thành viên không xóa bỏ thuế nội khối mà không cần xem xét đến hoàn cảnh cụ thể.", "Chỉ hợp tác về văn hóa và giáo dục."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: Đề 3 đáp án.docx · Phần I câu 5 · khoá: gạch chân"}, {"id": "L12-8T2-03-C06", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Một trong những lợi ích của hội nhập kinh tế quốc tế đối với doanh nghiệp là", "o": ["không phải cạnh tranh với hàng hóa nước ngoài trong mọi trường hợp, không cần căn cứ pháp luật.", "được độc quyền toàn bộ thị trường.", "không phải tuân thủ các quy định pháp luật.", "tiếp cận công nghệ và kinh nghiệm quản lý tiên tiến."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: Đề 3 đáp án.docx · Phần I câu 6 · khoá: gạch chân"}, {"id": "L12-8T2-03-C07", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Bảo hiểm thất nghiệp do ai đóng?", "o": ["Không ai đóng, Nhà nước chi trả toàn bộ.", "Chỉ người nghỉ việc tự đóng.", "Người lao động, người sử dụng lao động và Nhà nước hỗ trợ theo quy định.", "Chỉ người sử dụng lao động đóng toàn bộ mà không cần xem xét đến hoàn cảnh cụ thể."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: Đề 3 đáp án.docx · Phần I câu 7 · khoá: gạch chân"}, {"id": "L12-8T2-03-C08", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Bảo hiểm thương mại khác bảo hiểm xã hội ở điểm nào?", "o": ["Bắt buộc đối với toàn bộ người lao động.", "Chỉ áp dụng cho người về hưu.", "Do Nhà nước đảm bảo hoàn toàn và không đóng phí mà không cần xem xét đến hoàn cảnh cụ thể.", "Do doanh nghiệp bảo hiểm cung cấp và người dân tự nguyện tham gia."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: Đề 3 đáp án.docx · Phần I câu 8 · khoá: gạch chân"}, {"id": "L12-8T2-03-C09", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Bảo hiểm y tế bắt buộc được áp dụng với", "o": ["chỉ học sinh phổ thông.", "người tham gia bảo hiểm xã hội và một số đối tượng do pháp luật quy định.", "người nước ngoài làm việc ngắn hạn trong mọi trường hợp, không cần căn cứ pháp luật.", "người đã nghỉ hưu hoàn toàn."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: Đề 3 đáp án.docx · Phần I câu 9 · khoá: gạch chân"}, {"id": "L12-8T2-03-C10", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Ưu đãi người có công với cách mạng là nội dung thuộc chính sách nào?", "o": ["Thuế xuất khẩu mà không cần xem xét đến hoàn cảnh cụ thể.", "Đối ngoại.", "An sinh xã hội.", "Tiền tệ."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: Đề 3 đáp án.docx · Phần I câu 10 · khoá: gạch chân"}, {"id": "L12-8T2-03-C11", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Mục đích cơ bản của trợ cấp xã hội là", "o": ["làm tăng thu nhập cho doanh nghiệp.", "hạn chế quyền tiếp cận dịch vụ công.", "thay thế hoàn toàn nghĩa vụ lao động mà không cần xem xét đến hoàn cảnh cụ thể.", "giúp đối tượng khó khăn vượt qua hoàn cảnh và ổn định cuộc sống."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: Đề 3 đáp án.docx · Phần I câu 11 · khoá: gạch chân"}, {"id": "L12-8T2-03-C12", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Trong kế hoạch kinh doanh, phần phân tích tài chính nhằm", "o": ["tuyển người làm bảo vệ.", "dự tính vốn, doanh thu, chi phí và khả năng sinh lời.", "soạn nội dung quảng cáo trên mạng xã hội trong mọi trường hợp, không cần căn cứ pháp luật.", "chọn màu sắc biển hiệu cửa hàng."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: Đề 3 đáp án.docx · Phần I câu 12 · khoá: gạch chân"}, {"id": "L12-8T2-03-C13", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Trước khi triển khai kế hoạch kinh doanh, người kinh doanh cần", "o": ["đánh giá rủi ro và điều chỉnh kế hoạch cho phù hợp.", "bỏ qua phân tích đối thủ.", "không cần xác định mục tiêu trong mọi trường hợp, không cần căn cứ pháp luật.", "vay vốn với mọi điều kiện."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: Đề 3 đáp án.docx · Phần I câu 13 · khoá: gạch chân"}, {"id": "L12-8T2-03-C14", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Doanh nghiệp thể hiện trách nhiệm đối với cộng đồng khi", "o": ["tham gia các hoạt động an sinh, hỗ trợ địa phương.", "gây ô nhiễm nguồn nước sinh hoạt mà không cần xem xét đến hoàn cảnh cụ thể.", "trốn tránh nghĩa vụ đóng thuế.", "thu hẹp quyền lợi của khách hàng."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: Đề 3 đáp án.docx · Phần I câu 14 · khoá: gạch chân"}, {"id": "L12-8T2-03-C15", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Việc doanh nghiệp công khai thông tin sản phẩm, bảo đảm chất lượng là thể hiện trách nhiệm với", "o": ["khách hàng.", "cơ quan quảng cáo.", "đối thủ cạnh tranh.", "các nhà đầu cơ."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: Đề 3 đáp án.docx · Phần I câu 15 · khoá: gạch chân"}, {"id": "L12-8T2-03-C16", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Khi đủ điều kiện, công dân được hưởng ưu đãi về thuế nào?", "o": ["Ưu đãi tùy theo sở thích cá nhân.", "Ưu đãi do người nộp thuế tự quyết định trong mọi trường hợp, không cần căn cứ pháp luật.", "Ưu đãi không cần căn cứ pháp luật.", "Ưu đãi thuế theo quy định của pháp luật."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: Đề 3 đáp án.docx · Phần I câu 16 · khoá: gạch chân"}, {"id": "L12-8T2-03-C17", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Hành vi nào sau đây là vi phạm nghĩa vụ của người nộp thuế?", "o": ["Kê khai thuế đúng hạn.", "Thực hiện đăng ký thuế.", "Trốn thuế, gian lận thuế.", "Cung cấp thông tin về thuế."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: Đề 3 đáp án.docx · Phần I câu 17 · khoá: gạch chân"}, {"id": "L12-8T2-03-C18", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Mọi doanh nghiệp bình đẳng về nghĩa vụ trước pháp luật khi nào?", "o": ["Khi được miễn toàn bộ thuế.", "Khi được tự định mức thuế.", "Khi cùng thực hiện nghĩa vụ đóng thuế theo quy định.", "Khi được ưu tiên cấp giấy phép mà không cần xem xét đến hoàn cảnh cụ thể."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: Đề 3 đáp án.docx · Phần I câu 18 · khoá: gạch chân"}, {"id": "L12-8T2-03-C19", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Công dân có quyền khiếu nại khi nào trong lĩnh vực thuế?", "o": ["Khi cơ quan thuế thông báo đúng thời hạn.", "Khi quyền lợi hợp pháp bị xâm phạm.", "Khi thấy thuế đánh vào mình quá ít.", "Khi không muốn nộp thuế."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: Đề 3 đáp án.docx · Phần I câu 19 · khoá: gạch chân"}, {"id": "L12-8T2-03-C20", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đọc đoạn thông tin sau:\nAnh H bị đau bụng nên tới Bệnh viện B khám. Sau khi thực hiện các thủ tục thăm khám ban đầu, các bác sĩ ở bệnh viện chỉ định anh H phải thực hiện một số xét nghiệm và siêu âm ổ bụng để xác định nguyên nhân dẫn đến các cơn đau. Trong lúc chờ đợi, anh H bị đau bụng nhiều nên rất nôn nóng, khó chịu. Sau nhiều lần thúc giục các y, bác sĩ nhanh chóng kê đơn chữa trị cho mình nhưng không được đáp ứng vì chưa có kết quả xét nghiệm, chưa xác định rõ tình trạng bệnh lí, anh H tức giận có những lời nói tiêu cực xúc phạm các nhân viên bệnh viện và yêu cầu xuất viện, không điều trị.\nAnh H không vi phạm nghĩa vụ nào dưới đây của công dân trong việc t h ự c h i ệ n q u y ề n b ả o v ệ v à c h ă m s ó c s ứ c k h ỏ e c ủ a c ô n g d â n ?", "o": ["Xúc phạm danh dự cán bộ y tế.", "Không chấp hành nội quy điều trị.", "Chậm thanh toán kinh phí điều trị", "Không chấp hành chỉ định điều trị mà không cần xem xét đến hoàn cảnh cụ thể."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: Đề 3 đáp án.docx · Phần I câu 20 · khoá: gạch chân"}, {"id": "L12-8T2-03-C21", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đọc đoạn thông tin sau:\nAnh H bị đau bụng nên tới Bệnh viện B khám. Sau khi thực hiện các thủ tục thăm khám ban đầu, các bác sĩ ở bệnh viện chỉ định anh H phải thực hiện một số xét nghiệm và siêu âm ổ bụng để xác định nguyên nhân dẫn đến các cơn đau. Trong lúc chờ đợi, anh H bị đau bụng nhiều nên rất nôn nóng, khó chịu. Sau nhiều lần thúc giục các y, bác sĩ nhanh chóng kê đơn chữa trị cho mình nhưng không được đáp ứng vì chưa có kết quả xét nghiệm, chưa xác định rõ tình trạng bệnh lí, anh H tức giận có những lời nói tiêu cực xúc phạm các nhân viên bệnh viện và yêu cầu xuất viện, không điều trị.\nNội dung nào dưới đây không phải là hậu quả do hành vi vi phạm q u y ề n v à n g h ĩ a v ụ c ủ a c ô n g d â n t r o n g b ả o v ệ , c h ă m s ó c s ứ c k h ỏ e d o a n h H g â y r a ?", "o": ["Cản trở hoạt động khám chữa bệnh.", "Ảnh hưởng sức khỏe người bệnh.", "Xâm phạm tính mạng người thân.", "Gây khó khăn cho công tác điều trị."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: Đề 3 đáp án.docx · Phần I câu 21 · khoá: gạch chân"}, {"id": "L12-8T2-03-C22", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đọc đoạn thông tin sau:\nTrong những năm qua, nhà sưu tầm cổ vật N đã sưu tầm được hàng ngàn cổ vật, trong đó có nhiều cổ vật quý hiếm, có giá trị lớn về văn hoá, lịch sử. Phần lớn các cổ vật này được ông lựa chọn để trao tặng cho các bảo tàng, trường đại học để phục vụ trưng bày và giảng dạy. Số còn lại được ông trưng bày tại nhà hàng của mình ở một địa điểm du lịch để phục vụ du khách tham quan miễn phí.\nÔng N đã thể hiện quyền của công dân trong bảo vệ di sản văn hóa ở n ộ i d u n g n à o d ư ớ i đ â y ?", "o": ["Thay đổi nội dung cổ vật.", "Thu phí tham quan cổ vật.", "Giữ gìn giá trị các cổ vật.", "Trao tặng cô vật có giá trị."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: Đề 3 đáp án.docx · Phần I câu 22 · khoá: gạch chân"}, {"id": "L12-8T2-03-C23", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đọc đoạn thông tin sau:\nHằng năm trường trung học phổ thông B thường tổ chức cho học sinh đi tham quan các di tích lịch sử - văn hoá ở tỉnh nhà. Qua hoạt động tham quan này, học sinh của trường được thực hiện quyền của công dân về bảo vệ di sản văn hoá, được giáo dục truyền thống văn hoá của dân tộc qua các thời kì lịch sử. Khi đi tham quan, học sinh tìm hiểu ý nghĩa, lịch sử của các di sản văn hoá. Một số bạn còn ghi chép lại các sự kiện, tìm hiểu thêm các tư liệu liên quan đến di tích\nHoạt động tổ chức cho học sinh tham quan các di tích lịch sử văn h ó a t ỉ n h c ủ a c ủ a t r ư ờ n g T H P T B l à g ó p p h ầ n t h ự c h i ệ n q u y ề n c ủ a c ô n g d â n t r o n g b ả o v ệ d i s ả n v ă n h ó a ở n ộ i d u n g n à o d ư ớ i đ â y ?", "o": ["Tham gia phục dựng giá trị di sản.", "Tiếp cận và hưởng thụ giá trị di sản.", "Khai thác nguồn lợi kinh tế của di sản.", "Tôn tạo và bổ sung các di sản mới."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: Đề 3 đáp án.docx · Phần I câu 23 · khoá: gạch chân"}, {"id": "L12-8T2-03-C24", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đọc đoạn thông tin sau:\nKể từ khi được UNESCO công nhận là Di sản văn hoá phi vật thể đại diện của nhân loại, dân ca Ví, Giặm Nghệ Tĩnh ngày càng được phát huy trong đời sống văn hoá của nhân dân xứ Nghệ. Ở Nghệ An, Hà Tĩnh, các câu lạc bộ Ví, Giặm được thành lập ở khắp nơi để duy trì và phát huy làn điệu dân ca xứ sở. Cộng đồng dân cư ở hai tỉnh Nghệ An, Hà Tĩnh tích cực tham gia giao lưu các hoạt động, hưởng thụ đời sống tinh thần hay quả đó góp phần để dân ca Ví, Giặm mãi được duy trì và phát huy trong nền văn hoá dân tộc.\nViệc làm nào dưới đây không thể hiện quyền của công dân trong việc t h a m g i a b ả o v ệ c á c g i á t r ị d i s ả n v ă n h ó a ?", "o": ["Thay đổi nội dung của hát Ví, Giặm.", "Phổ biến giá trị của hát Ví, Giặm trong mọi trường hợp, không cần căn cứ pháp luật.", "Tham gia tìm hiểu hát Ví Giặm.", "Thành lập câu lạc bộ Ví, Giặm."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: Đề 3 đáp án.docx · Phần I câu 24 · khoá: gạch chân"}, {"id": "L12-8T2-03-C25", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "dung_sai", "status": "cho_duyet", "q": "Đọc đoạn thông tin sau và cho biết mỗi ý a, b, c, d là Đúng hay Sai. Các di sản văn hoá đã được đặt dưới sự bảo hộ của Luật Di sản văn hoá v� các công ước của UNESCO mà Việt Nam đã tham gia. Trong số gần 4 triệu hiện vật đang lưu giữ trong các bảo tàng công lập, bảo tàng ngoài công lập v� các bộ , tập tư nhân có 238 hiện vật và nhóm hiện vật được Thủ tướng Chính phủ công nhận là bảo vật quốc gia. Từ năm 2015 – 2022, đã có 131 nghệ nhân được phong tặng danh hiệu Nghệ nhân nhân dân và 1 507 nghệ nhân được phong tặng danh hiệu Nghệ nhân ưu tú. Luật Di sản văn hoá cho phép tư nhân/chủ sở hữu sưu tập hiện vật xây dựng bảo tàng ngoài công lập, tư nhân hiến tặng cổ vật cho các bảo tàng công lập. Nhà nước đã đầu tư những khoản ngân sách khá lớn cho mục tiêu bảo tồn di sản văn hoá. Ngoài ra, phải kể tới hàng nghìn tỉ đồng được huy động từ sự tự nguyện đóng góp của cộng đồng cư dân các địa phương cũng như vốn hỗ trợ từ UNESCO.", "o": ["Quyền của công dân về bảo vệ di sản văn hoá thể hiện ở việc 238 hiện vật và nhóm hiện vật được Thủ tướng Chính phủ công nhận là bảo vật quốc gia.", "Việc phong tặng danh hiệu Nghệ nhân nhân dân và danh hiệu Nghệ nhân ưu tủ nằm ngoài lĩnh vực về bảo vệ di sản văn hoá.", "Pháp luật cho phép tư nhân sưu tập hiện vật xây dựng bảo tàng ngoài công lập là để tạo cơ hội cho người dân được tiếp cận và hưởng thụ các giá trị di sản văn hoá.", "Pháp luật quy định cộng đồng cư dân các địa phương có nghĩa vụ tự nguyện đóng góp hàng nghìn tỉ đồng cho mục tiêu bảo tồn di sản văn hoá."], "a": [false, false, true, false], "e": "Đáp án: a) Sai; b) Sai; c) Đúng; d) Sai.", "nguon": "Đề nguồn: Đề 3 đáp án.docx · Phần II câu 1 · khoá: chữ Đúng/Sai trong ý"}, {"id": "L12-8T2-03-C26", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "dung_sai", "status": "cho_duyet", "q": "Đọc đoạn thông tin sau và cho biết mỗi ý a, b, c, d là Đúng hay Sai. Năm 2021, Chùa Đậu – di tích lịch sử được mệnh danh là “Danh lam đệ nhất. trời Nam\" bỗng nhiên bị làm mới. Công trình hàng nghìn năm tuổi với nhiều hạng mục được xây thêm, làm mới khiến nhiều người chua xót: Chùa Đậu giờ chỉ còn 1 năm tuổi, nhưng có người lại cho rằng, chỉ vài năm nữa, rêu xanh sẽ mọc lên vì các hạng mục được xây mới, sửa chữa sẽ lại nhuốm màu cổ kính như xưa. Cả chuyện của Chùa Đậu được làm mới vốn không mới, nhưng lại xảy ra thưởng xuyên tại hầu hết các địa phương trong cả nước.", "o": ["Với việc làm mới, Chùa Đậu chỉ mất đi vẻ cổ kính, nhưng thực tế vẫn được lịch sử hàng nghìn năm.", "Công dân thực hiện quyền và nghĩa vụ bảo vệ di sản văn hoá bằng cách tranh cãi về việc nên/không nên làm mới các di tích lịch sử.", "Nhiều hạng mục được xây thêm và làm mới khiến Chùa Đậu mất đi vẻ cổ kinh là dấu hiệu công dân lạm dụng quyền về bảo vệ di sản văn hoá.", "Xử lí hành vi làm mới ở di tích lịch sử Chùa Đậu sẽ ngăn chặn được hiện tượng này ở hầu hết các địa phương khác."], "a": [false, false, true, true], "e": "Đáp án: a) Sai; b) Sai; c) Đúng; d) Đúng.", "nguon": "Đề nguồn: Đề 3 đáp án.docx · Phần II câu 2 · khoá: chữ Đúng/Sai trong ý"}, {"id": "L12-8T2-03-C27", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "dung_sai", "status": "cho_duyet", "q": "Đọc đoạn thông tin sau và cho biết mỗi ý a, b, c, d là Đúng hay Sai. Tổ liên ngành an ninh của Trung tâm Bảo tồn di tích Cố đô Huế trong quá trình tuần tra đã phát hiện một nhóm học sinh leo qua gác chắn đi vào khu vực kì đài nên đã đề nghị nhóm học sinh ra khỏi khu vực di tích. Sau đó, phát hiện một số bóng đèn LED chiếu sáng tại đây đã bị đập vỡ, mảnh kính từ bóng đèn nằm vương vãi trên mặt nền di tích. Thông qua hệ thống giám sát của trung tâm, lực lượng bảo vệ xác định đây là hành vi phá hoại tài sản của nhóm học sinh kể trên.", "o": ["Cố đô Huế là di sản văn hóa được nhà nước bảo vệ.", "Việc phá hoại các bóng đèn LED của khu di tích không nằm trong giá trị bảo tồn của di tích Cố đô Huế.", "Các thanh niên trong thông tin trên thực hiện chưa đúng trách nhiệm của công dân trong việc giữ gìn và bảo vệ di sản văn hóa.", "Các học sinh trong thông tin trên sẽ phải chịu trách nhiệm pháp lý về hành vi vi phạm của mình."], "a": [true, false, false, true], "e": "Đáp án: a) Đúng; b) Sai; c) Sai; d) Đúng.", "nguon": "Đề nguồn: Đề 3 đáp án.docx · Phần II câu 3 · khoá: chữ Đúng/Sai trong ý"}, {"id": "L12-8T2-03-C28", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "dung_sai", "status": "cho_duyet", "q": "Đọc đoạn thông tin sau và cho biết mỗi ý a, b, c, d là Đúng hay Sai. Ngôi đền cổ ở xã X của bạn H bị các đối tượng xấu đột nhập trộm một lượng lớn cổ vật có giá trị. Các lực lượng chức năng và người dân địa phương nhiều lần tìm kiếm nhưng chưa bắt được thủ phạm và chưa thu hồi được các cổ vật. Một lần sang nhà bạn thân chơi, H vô tình bắt gặp anh trai bạn thân đang ngồi đóng gói một số đồ vật có hình dạng giống các cổ vật đã bị đánh cắp ở ngôi đền nên nảy sinh nghi ngờ. Sau đó H viết thư tố cáo gửi tới cơ quan chức năng để xem xét. Tuy nhiên vì do sợ bị trả thù nên H đã không trình bày cụ thể tên tuổi và địa chỉ người tố cáo nên đơn tố cáo của H không được xem xét giải quyết.", "o": ["Bạn H vừa chưa thực hiện đúng quyền vừa chưa thực hiện đúng nghĩa vụ của công dân trong việc bảo vệ di sản văn hóa.", "Người dân và lực lượng chức năng chưa thực hiện tốt nghĩa vụ của công dân về bảo vệ di sản văn hóa theo quy định.", "Việc cơ quan chức năng không xem xét đơn của H là hành vi vi phạm quyền và nghĩa vụ của công dân trong bảo vệ di sản.", "Bạn H nên trực tiếp chia sẻ với người có thẩm quyền để có biện pháp xử lý phù hợp."], "a": [true, true, false, true], "e": "Đáp án: a) Đúng; b) Đúng; c) Sai; d) Đúng.", "nguon": "Đề nguồn: Đề 3 đáp án.docx · Phần II câu 4 · khoá: chữ Đúng/Sai trong ý"}]}, {"id": "L12-8T2-04", "loai": "khoi", "khoi": 12, "hoc_ki": 2, "bo": "8T2", "ten_bo": "8 tuần học kì II", "so_de": 4, "ten": "Lớp 12 · 8 tuần học kì II · Đề 4", "pham_vi": "Đề nguồn «8 TUẦN KÌ 2 › BO_DE_MOI» · file nguồn: Đề 4 đáp án.docx", "thoi_gian": 50, "cau_truc": "24 câu trắc nghiệm + 4 câu đúng/sai (mỗi câu 4 ý)", "status": "cho_duyet", "khoa": {"1 nguồn": 28}, "sua": "", "cau": [{"id": "L12-8T2-04-C01", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Chỉ số nào sau đây phản ánh thu nhập bình quân trên mỗi người dân?", "o": ["Số lượng ô tô đăng ký mà không cần xem xét đến hoàn cảnh cụ thể.", "Tổng số dân.", "GDP bình quân đầu người.", "Tỉ lệ biết chữ."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: Đề 4 đáp án.docx · Phần I câu 1 · khoá: gạch chân"}, {"id": "L12-8T2-04-C02", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Trong phát triển bền vững, việc khai thác tài nguyên cần", "o": ["không cần quy hoạch.", "khai thác tối đa trong thời gian ngắn trong mọi trường hợp, không cần căn cứ pháp luật.", "chỉ phục vụ xuất khẩu thô.", "bảo đảm tái tạo và không làm cạn kiệt cho thế hệ sau."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: Đề 4 đáp án.docx · Phần I câu 2 · khoá: gạch chân"}, {"id": "L12-8T2-04-C03", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Sự chuyển dịch cơ cấu kinh tế theo hướng tích cực thường làm", "o": ["làm mất cân đối giữa các vùng.", "tăng tỉ trọng nông nghiệp lên mức cao nhất mà không cần xem xét đến hoàn cảnh cụ thể.", "chỉ thay đổi về dân số.", "tăng tỉ trọng công nghiệp và dịch vụ, giảm tỉ trọng nông nghiệp."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: Đề 4 đáp án.docx · Phần I câu 3 · khoá: gạch chân"}, {"id": "L12-8T2-04-C04", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Hiệp định đối tác kinh tế song phương là ví dụ của hội nhập", "o": ["theo hình thức khu vực châu Mỹ.", "theo hình thức toàn cầu.", "theo hình thức đa phương rộng lớn.", "theo hình thức song phương."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: Đề 4 đáp án.docx · Phần I câu 4 · khoá: gạch chân"}, {"id": "L12-8T2-04-C05", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Việc tham gia APEC giúp Việt Nam", "o": ["tách biệt khỏi các nền kinh tế lớn.", "chỉ hợp tác về thể thao.", "bãi bỏ mọi quy định về xuất nhập khẩu mà không cần xem xét đến hoàn cảnh cụ thể.", "thúc đẩy thương mại và đầu tư trong khu vực châu Á – Thái Bình Dương."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: Đề 4 đáp án.docx · Phần I câu 5 · khoá: gạch chân"}, {"id": "L12-8T2-04-C06", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Khi hội nhập, doanh nghiệp cần đặc biệt chú ý đến", "o": ["quy tắc thương mại quốc tế và tiêu chuẩn chất lượng.", "tránh mọi hợp tác với đối tác nước ngoài mà không cần xem xét đến hoàn cảnh cụ thể.", "chỉ làm theo thói quen cũ.", "không cần đổi mới sản phẩm."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: Đề 4 đáp án.docx · Phần I câu 6 · khoá: gạch chân"}, {"id": "L12-8T2-04-C07", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Một rủi ro của hội nhập kinh tế là", "o": ["nền kinh tế dễ bị tác động bởi biến động của thị trường thế giới.", "mọi doanh nghiệp đều được hưởng lợi như nhau mà không cần xem xét đến hoàn cảnh cụ thể.", "không có tác động xấu nào.", "chỉ làm tăng thuế nội địa."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: Đề 4 đáp án.docx · Phần I câu 7 · khoá: gạch chân"}, {"id": "L12-8T2-04-C08", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Người lao động tham gia bảo hiểm xã hội bắt buộc được hưởng lương hưu khi", "o": ["chỉ cần đóng một lần duy nhất.", "đủ điều kiện về tuổi đời và thời gian đóng theo quy định.", "không cần đóng bảo hiểm trong suốt quá trình làm việc mà không cần xem xét đến hoàn cảnh cụ thể.", "bất kỳ lúc nào theo nguyện vọng cá nhân."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: Đề 4 đáp án.docx · Phần I câu 8 · khoá: gạch chân"}, {"id": "L12-8T2-04-C09", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Quỹ bảo hiểm xã hội được quản lý nhằm mục đích", "o": ["bảo đảm an toàn, chi trả đúng quyền lợi cho người tham gia.", "chia lợi nhuận cho doanh nghiệp.", "thanh toán chi phí quảng cáo sản phẩm.", "phục vụ đầu tư cá nhân của cán bộ quản lý mà không cần xem xét đến hoàn cảnh cụ thể."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: Đề 4 đáp án.docx · Phần I câu 9 · khoá: gạch chân"}, {"id": "L12-8T2-04-C10", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Chăm sóc người cao tuổi neo đơn, người khuyết tật là nội dung của", "o": ["chính sách giá đất.", "chính sách lao động nước ngoài.", "trợ giúp xã hội.", "chính sách thuế."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: Đề 4 đáp án.docx · Phần I câu 10 · khoá: gạch chân"}, {"id": "L12-8T2-04-C11", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Chính sách xóa đói, giảm nghèo của Nhà nước nhằm", "o": ["nâng cao thu nhập và điều kiện sống cho hộ nghèo.", "chuyển đổi hộ nghèo thành hộ không có đất trong mọi trường hợp, không cần căn cứ pháp luật.", "hạn chế quyền học tập của trẻ em.", "tăng chi phí sinh hoạt của hộ nghèo."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: Đề 4 đáp án.docx · Phần I câu 11 · khoá: gạch chân"}, {"id": "L12-8T2-04-C12", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Mô hình kinh doanh nên được xây dựng dựa trên", "o": ["các sản phẩm không có khách hàng.", "ý kiến của người không liên quan mà không cần xem xét đến hoàn cảnh cụ thể.", "cảm tính của người sáng lập.", "nhu cầu thị trường và nguồn lực thực tế của doanh nghiệp."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: Đề 4 đáp án.docx · Phần I câu 12 · khoá: gạch chân"}, {"id": "L12-8T2-04-C13", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Kế hoạch marketing trong kế hoạch kinh doanh giúp doanh nghiệp", "o": ["không cần đăng ký kinh doanh mà không cần xem xét đến hoàn cảnh cụ thể.", "giảm số lượng nhân viên.", "miễn trừ thuế thu nhập.", "tiếp cận và giữ chân khách hàng mục tiêu."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: Đề 4 đáp án.docx · Phần I câu 13 · khoá: gạch chân"}, {"id": "L12-8T2-04-C14", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Doanh nghiệp tôn trọng quyền lợi người lao động thể hiện qua việc", "o": ["không cung cấp điều kiện làm việc an toàn mà không cần xem xét đến hoàn cảnh cụ thể.", "trả lương dưới mức tối thiểu.", "ký hợp đồng lao động và đóng bảo hiểm đầy đủ.", "sa thải lao động tùy tiện."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: Đề 4 đáp án.docx · Phần I câu 14 · khoá: gạch chân"}, {"id": "L12-8T2-04-C15", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Trách nhiệm pháp lý của doanh nghiệp về an toàn sản phẩm là", "o": ["bảo đảm sản phẩm không gây hại cho người tiêu dùng.", "được miễn thuế khi sản phẩm bị lỗi.", "không phải chịu trách nhiệm khi có sự cố trong mọi trường hợp, không cần căn cứ pháp luật.", "chỉ cần quảng cáo sản phẩm tốt."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: Đề 4 đáp án.docx · Phần I câu 15 · khoá: gạch chân"}, {"id": "L12-8T2-04-C16", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Việc doanh nghiệp tuân thủ quy định bảo vệ môi trường là thực hiện nghĩa vụ nào?", "o": ["Nghĩa vụ đầu tư quảng cáo.", "Nghĩa vụ thay đổi loại hình doanh nghiệp mà không cần xem xét đến hoàn cảnh cụ thể.", "Nghĩa vụ tổ chức hội nghị.", "Nghĩa vụ tuân thủ pháp luật về môi trường."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: Đề 4 đáp án.docx · Phần I câu 16 · khoá: gạch chân"}, {"id": "L12-8T2-04-C17", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Công dân được tố cáo hành vi nào trong lĩnh vực kinh doanh?", "o": ["Hành vi tuân thủ quy định về hóa đơn.", "Hành vi kinh doanh đúng ngành nghề đăng ký.", "Hành vi nộp thuế đầy đủ.", "Hành vi vi phạm pháp luật về kinh doanh."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: Đề 4 đáp án.docx · Phần I câu 17 · khoá: gạch chân"}, {"id": "L12-8T2-04-C18", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Khi chấp hành đúng quy định về thuế, người nộp thuế thể hiện điều gì?", "o": ["Thực hiện quyền làm trái pháp luật.", "Thực hiện quyền gian lận thuế.", "Thực hiện đúng nghĩa vụ của công dân.", "Thực hiện quyền trốn tránh trách nhiệm."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: Đề 4 đáp án.docx · Phần I câu 18 · khoá: gạch chân"}, {"id": "L12-8T2-04-C19", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Quyền tự do kinh doanh của công dân được hiểu là", "o": ["quyền kinh doanh mọi lĩnh vực không cần giấy phép mà không cần xem xét đến hoàn cảnh cụ thể.", "quyền không phải tuân thủ quy định nào.", "quyền kinh doanh trong khuôn khổ pháp luật cho phép.", "quyền sử dụng tài sản công cho mục đích riêng."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: Đề 4 đáp án.docx · Phần I câu 19 · khoá: gạch chân"}, {"id": "L12-8T2-04-C20", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đọc đoạn thông tin sau:\nTừ năm 2018, ông M thành lập Công ty Trách nhiệm hữu hạn Thương mại và Sản xuất G với ngành nghề kinh doanh dầu nhớt, phụ tùng xe gắn máy. Trong thời gian kinh doanh, ông M nhận thấy khách hàng ưa chuộng các phụ tùng xe gắn máy hiệu H và dầu nhớt hiệu K nên nảy sinh ý định làm giả sản phẩm của các thương hiệu này bán cho khách hàng để thu lợi. Ông M chỉ đạo nhân viên thiết kế các mẫu tem xác nhận hàng chính hãng và thuê người in nhiều mẫu tem để sử dụng, sau đó ông cùng vợ đến một số chợ trong khu vực tìm mua các phụ tùng xe gắn máy, dầu nhớt chất lượng kém đem về đóng gói, dán tem làm giả sản phẩm của các thương hiệu nổi tiếng, bán ra thị trường cho khách với giá thấp hơn hàng chính hãng từ 10% – 15%. Bằng thủ đoạn đó, trong thời gian gần 2 năm, vợ chồng ông M đã sản xuất số lượng hàng giả có giá trị tương đương hàng thật hơn 750 triệu đồng, thu lợi khoảng 300 triệu đồng.\nViệc thành lập Công ty Trách nhiệm hữu hạn Thương mại và Sản xuất G c ủ a ô n g M l à v ậ n d ụ n g q u y ề n c ủ a c ô n g d â n v ề k i n h ở n ộ i d u n g n à o d ư ớ i đ â y ?", "o": ["Tự chủ đăng ký kinh doanh.", "Lựa chọn loại hình kinh doanh.", "Tích cực mở rộng thị trường trong mọi trường hợp, không cần căn cứ pháp luật.", "Mở rộng quy mô sản xuất."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: Đề 4 đáp án.docx · Phần I câu 20 · khoá: gạch chân"}, {"id": "L12-8T2-04-C21", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đọc đoạn thông tin sau:\nAnh H đăng kí thành lập công ty tư nhân HD, chuyên sản xuất hàng may mặc. Khi đăng kí thành lập công ty, anh kê khai đầy đủ nội dung hồ sơ đăng kí doanh nghiệp. Sau 5 năm hoạt động, công ty sản xuất, kinh doanh hiệu quả, mang lại lợi nhuận, nộp thuế, đóng góp vào ngân sách nhà nước, giải quyết việc làm, tăng thu nhập và thực hiện tốt chế độ cho người lao động ở địa phương. Trong suốt 5 năm qua, vốn và tài sản của công ty được sử dụng vào hoạt động kinh doanh luôn được ghi chép đầy đủ vào số kế toán và báo cáo tài chính của công ty. Sau khi cân nhắc, anh quyết định mở rộng kinh doanh thông qua việc tăng vốn và điều lệ và xem xét chuyển sang mô hình công ty cổ phần.\nHoạt động ghi chép đầy đủ vào sổ kế toán và báo cáo tài chính của c ô n g t y l à t h ể h i ệ n n ộ i d u n g n à o d ư ớ i đ â y c ủ a v i ệ c t h ự c h i ệ n q u y ề n v à n g h ĩ a v ụ c ủ a c ô n g d â n v ề k i n h d o a n h ?", "o": ["Nghĩa vụ kinh doanh.", "Trách nhiệm từ thiện.", "Quyền kinh doanh.", "Trách nhiệm pháp lý."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: Đề 4 đáp án.docx · Phần I câu 21 · khoá: gạch chân"}, {"id": "L12-8T2-04-C22", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đọc đoạn thông tin sau:\nAnh H đăng kí thành lập công ty tư nhân HD, chuyên sản xuất hàng may mặc. Khi đăng kí thành lập công ty, anh kê khai đầy đủ nội dung hồ sơ đăng kí doanh nghiệp. Sau 5 năm hoạt động, công ty sản xuất, kinh doanh hiệu quả, mang lại lợi nhuận, nộp thuế, đóng góp vào ngân sách nhà nước, giải quyết việc làm, tăng thu nhập và thực hiện tốt chế độ cho người lao động ở địa phương. Trong suốt 5 năm qua, vốn và tài sản của công ty được sử dụng vào hoạt động kinh doanh luôn được ghi chép đầy đủ vào số kế toán và báo cáo tài chính của công ty. Sau khi cân nhắc, anh quyết định mở rộng kinh doanh thông qua việc tăng vốn và điều lệ và xem xét chuyển sang mô hình công ty cổ phần.\nViệc nộp thuế và đóng góp đầy đủ vào ngân sách nhà nước là thể hiện t r á c h n h i ệ m x ã h ộ i n à o d ư ớ i đ â y c ủ a c ô n g t y H D ?", "o": ["Trách nhiệm đạo đức.", "Trách nhiệm kinh tế.", "Trách nhiệm từ thiện.", "Trách nhiệm pháp lý."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: Đề 4 đáp án.docx · Phần I câu 22 · khoá: gạch chân"}, {"id": "L12-8T2-04-C23", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đọc đoạn thông tin sau:\nDoanh nghiệp tư nhân của ông C mở cửa hàng kinh doanh đồ dùng gia đình sau khi được cơ quan đăng kí kinh doanh của tỉnh cấp giấy chứng nhận đăng kí doanh nghiệp. Khi nộp hồ sơ đăng kí doanh nghiệp, ông C không kê khai một số mặt hàng trong đồ dùng gia đình, nhưng cửa hàng của ông vẫn bán những mặt hàng này. Khi kê khai nộp thuế, ông đã không kê khai những mặt hàng mới này. Ông C cho rằng, mình không kê khai tính thuế như vậy là đúng, vì những mặt hàng này không nằm trong hồ sơ đăng kí doanh nghiệp.\nÔng C đã thực hiện chưa đúng nghĩa vụ về nộp thuế của công dân ở n ộ i d u n g n à o d ư ớ i đ â y ?", "o": ["Sử dụng không đúng mã số thuế.", "Nộp thuế không đúng thời hạn.", "Chiếm đoạt tiền hoàn thuế.", "Kê khai không trung thực."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: Đề 4 đáp án.docx · Phần I câu 23 · khoá: gạch chân"}, {"id": "L12-8T2-04-C24", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đọc đoạn thông tin sau:\nDoanh nghiệp tư nhân của ông C mở cửa hàng kinh doanh đồ dùng gia đình sau khi được cơ quan đăng kí kinh doanh của tỉnh cấp giấy chứng nhận đăng kí doanh nghiệp. Khi nộp hồ sơ đăng kí doanh nghiệp, ông C không kê khai một số mặt hàng trong đồ dùng gia đình, nhưng cửa hàng của ông vẫn bán những mặt hàng này. Khi kê khai nộp thuế, ông đã không kê khai những mặt hàng mới này. Ông C cho rằng, mình không kê khai tính thuế như vậy là đúng, vì những mặt hàng này không nằm trong hồ sơ đăng kí doanh nghiệp.\nBiện pháp nào dưới đây không được áp dụng đối với hành vi vi phạm n g h ĩ a v ụ n ộ p t h u ế m à ô n g C p h ả i g á n h c h ị u t r o n g t h ô n g t i n t r ê n ?", "o": ["Xử phạt vi phạm hành chính trong mọi trường hợp, không cần căn cứ pháp luật.", "Bổ sung tờ khai nộp thuế.", "Miễn thuế và rút kinh nghiệm.", "Truy thu số thuế còn thiếu."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: Đề 4 đáp án.docx · Phần I câu 24 · khoá: gạch chân"}, {"id": "L12-8T2-04-C25", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "dung_sai", "status": "cho_duyet", "q": "Đọc đoạn thông tin sau và cho biết mỗi ý a, b, c, d là Đúng hay Sai. Ngôi đền ở xã X từ lâu đã tồn tại các lễ hội, phong tục tốt đẹp được pháp luật bảo vệ. Ông P, chủ tịch Uỷ ban nhân dân xã đã đề xuất trùng tu lại ngôi đền để đảm bảo an toàn về mặt kiến trúc và bảo vệ các giá trị văn hoá. Biết được thông tin này, anh Y đã giả danh là một công ty xây dựng để nhận thầu thi công. Phát hiện thấy trong đền có nhiều cổ vật nên anh Y có ý định lấy trộm. Anh Y dùng tiền, quà tặng để hối lộ ông P và đã thành công lấy được một số cổ vật. Người dân xã X phát hiện sự việc nên đã ngay lập tức trình báo vụ việc cho cơ quan chức năng.", "o": ["Ông P đề xuất trùng tu lại ngôi đền thể hiện ông là người hiểu rõ quyền và nghĩa vụ về bảo tồn di sản văn hoá.", "Hành vì nhận hối lộ của ông P và dung túng cho anh Y phạm tội là không vi phạm quy định của pháp luật về bảo tồn di sản văn hoá.", "Người dân xã X đã sử dụng quyền và nghĩa vụ công dân về bảo vệ di sản văn hoá để tố cáo vụ việc của anh Y cho cơ quan có thẩm quyền.", "Anh Y đã vi phạm quyền và nghĩa vụ của công dân về hưởng thụ các di sản văn hoá vật chất và tinh thần của dân tộc."], "a": [true, false, true, false], "e": "Đáp án: a) Đúng; b) Sai; c) Đúng; d) Sai.", "nguon": "Đề nguồn: Đề 4 đáp án.docx · Phần II câu 1 · khoá: chữ Đúng/Sai trong ý"}, {"id": "L12-8T2-04-C26", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "dung_sai", "status": "cho_duyet", "q": "Đọc đoạn thông tin sau và cho biết mỗi ý a, b, c, d là Đúng hay Sai. Hầu hết các làng nghề đang hoạt động hiện nay đều có những ảnh hưởng trực tiếp hoặc giản tiếp tới môi trường không khí. Trong số đó, ba nhóm làng nghề: tái chế (kim loại, giấy, nhựa,...), vật liệu xây dựng dựng và chế biến nông sản, thực phẩm là những nhóm làng nghề có nguy cơ gây ô nhiễm môi trường không khí cao. Nguồn thải gây ô nhiễm môi trường không khí tại các làng nghề chủ yếu từ việc sử dụng than làm nhiên liệu, sử dụng hóa chất, phụ gia trong quá trình sản xuất. Trong đó, nhóm làng nghề có thải lượng ô nhiễm lớn nhất là tái chế (kim loại, giấy, nhựa quá trình tái chế và gia công, xử lí bề mặt, phun sơn, đánh bông bề mặt sản phẩm, nung, sấy, tẩy trắng, khi thải lò rèn.... làm phát sinh bụi và các khí thải như SO NO₂, hơi axit và kiềm.", "o": ["Làng nghề hiện nay là nguyên nhân chính gây ô nhiễm môi trường cho cộng đồng dân cư.", "Theo quy định của pháp luật hiện hành, một số hộ gia đình đã làm nghề truyền thống thì không cần phải có giấy chứng nhận đủ điều kiện sản xuất, kinh doanh.", "Việc quản lý hoạt động của các làng nghề này là trách nhiệm của chính quyền địa phương.", "Học sinh sống trong khu vực làng nghề này có quyền thực hiện quyền tố cáo tới cơ quan chức năng nếu phát hiện hành vi vi phạm về bảo vệ môi trường."], "a": [false, false, false, true], "e": "Đáp án: a) Sai; b) Sai; c) Sai; d) Đúng.", "nguon": "Đề nguồn: Đề 4 đáp án.docx · Phần II câu 2 · khoá: chữ Đúng/Sai trong ý"}, {"id": "L12-8T2-04-C27", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "dung_sai", "status": "cho_duyet", "q": "Đọc đoạn thông tin sau và cho biết mỗi ý a, b, c, d là Đúng hay Sai. Gần nhà bà H có một nhà máy xử lí rác thải X đang hoạt động. Hằng ngày, xe chuyển rác thải về nhà máy X rất nhiều, nhưng thưởng không có bạt che chắn, dẫn với tình trạng rác thải rơi trên đường. Bên cạnh đó, do rác thải ở nh� máy X không được xử lí kịp thời nên có mùi hội thối bốc lên ảnh hưởng đến chất lượng cuộc sống của người dân địa phương. Nhiều trẻ em trong khu vực dân cư bị các bệnh về đường hô hấp, xuất hiện dịch sốt xuất huyết gây nguy hiểm đến sức khoẻ, tính mạng của người dân.", "o": ["Nhà máy X đã vừa vi phạm quyền được bảo vệ sức khỏe và chăm sóc sức khỏe vừa vi phạm quyền được sống trong môi trường trong lành của công dân.", "Nhà máy X đã vi phạm nghĩa vụ của công dân trong bảo vệ môi trường.", "Vì là nhà máy xử lý rác thải nên nhà máy X không phải chịu trách nhiệm dân sự đối với những vấn đề liên quan đến sức khỏe của người dân.", "Việc xử lý vi phạm của nhà máy X chỉ được các cơ quan tiến hành nếu có đơn tố cáo vi phạm của nhân dân bị ảnh hưởng trong khu vực nhà máy."], "a": [true, true, false, false], "e": "Đáp án: a) Đúng; b) Đúng; c) Sai; d) Sai.", "nguon": "Đề nguồn: Đề 4 đáp án.docx · Phần II câu 3 · khoá: chữ Đúng/Sai trong ý"}, {"id": "L12-8T2-04-C28", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "dung_sai", "status": "cho_duyet", "q": "Đọc đoạn thông tin sau và cho biết mỗi ý a, b, c, d là Đúng hay Sai. Vào ngày 20/4/2022, lực lượng Phòng Cảnh sát môi trường, Công an tỉnh ĐN bắt quả tang công nhân xí nghiệp X đang thực hiện xay nghiền tiêu huỷ các vỏ bóng đèn thải không đúng quy định. Tại hiện trường, khoảng gần 5 tấn thuỷ tinh có hoá chất chứa trong 195 bao và gần 370 nghìn bóng đèn thải chưa kịp xay nghiền đựng trong các sọt nhựa. Nước thải trong quá trình xay nghiền bóng đèn được thoát trực tiếp ra hệ thống mương nước mưa.Tiếp tục kiểm tra, lực lượng công an phát hiện 2 hầm bê tông được xây dựng âm dưới đất bên trong xí nghiệp có chứa hơn 89 tấn bóng đèn hỏng, thuỷ tinh đã nghiền, gần 1 tấn thuỷ tinh lẫn bùn thải và hơn 32 tấn nước phát sinh từ hoạt động tiêu huỷ. Mở rộng điều tra, cơ quan chức năng phát hiện xí nghiệp X cũng không đóng bảo hiểm xã hội, không tổ chức khám sức khoẻ định kì cho các công nhân đang làm việc tại đó.", "o": ["Xí nghiệp X đã vi phạm nghĩa vụ của các chủ thể kinh tế trong việc bảo vệ môi trường.", "Theo quy định của Luật bảo vệ môi trường, hành vi của xí nghiệp X chỉ bị nhắc nhở và rút kinh nghiệm.", "Ngoài lãnh đạo xí nghiệp thì các công nhân trong công ty cũng phải chịu trách nhiệm pháp lý về hành vi vi phạm trong lĩnh vực bảo vệ môi trường.", "Học sinh khi phát hiện các vụ việc xả thải trái phép của các doanh nghiệp có quyền cùng với người thân trong gia đình kiểm tra giấy phép kinh doanh và xử phạt các doanh nghiệp đó."], "a": [true, false, false, false], "e": "Đáp án: a) Đúng; b) Sai; c) Sai; d) Sai.", "nguon": "Đề nguồn: Đề 4 đáp án.docx · Phần II câu 4 · khoá: chữ Đúng/Sai trong ý"}]}, {"id": "L12-8T2-05", "loai": "khoi", "khoi": 12, "hoc_ki": 2, "bo": "8T2", "ten_bo": "8 tuần học kì II", "so_de": 5, "ten": "Lớp 12 · 8 tuần học kì II · Đề 5", "pham_vi": "Đề nguồn «8 TUẦN KÌ 2 › BO_DE_MOI» · file nguồn: Đề 5 đáp án.docx", "thoi_gian": 50, "cau_truc": "24 câu trắc nghiệm + 4 câu đúng/sai (mỗi câu 4 ý)", "status": "cho_duyet", "khoa": {"1 nguồn": 28}, "sua": "", "cau": [{"id": "L12-8T2-05-C01", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Chỉ số nào dưới đây đánh giá chất lượng cuộc sống qua giáo dục, y tế và thu nhập?", "o": ["Chỉ số chứng khoán.", "Chỉ số phát triển con người (HDI).", "Tỉ lệ thất nghiệp.", "Chỉ số giá tiêu dùng (CPI) mà không cần xem xét đến hoàn cảnh cụ thể."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: Đề 5 đáp án.docx · Phần I câu 1 · khoá: gạch chân"}, {"id": "L12-8T2-05-C02", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Tăng trưởng kinh tế nhanh nhưng làm cạn kiệt tài nguyên và ô nhiễm môi trường cho thấy", "o": ["không có mối liên hệ với môi trường.", "tăng trưởng chưa gắn với phát triển bền vững.", "phát triển bền vững đã được bảo đảm mà không cần xem xét đến hoàn cảnh cụ thể.", "cần ngừng mọi hoạt động sản xuất."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: Đề 5 đáp án.docx · Phần I câu 2 · khoá: gạch chân"}, {"id": "L12-8T2-05-C03", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Khi kinh tế phát triển bền vững, người dân thường được hưởng lợi ích gì?", "o": ["Phúc lợi xã hội được cải thiện và bất bình đẳng được thu hẹp.", "Vai trò của gia đình bị suy yếu.", "Cơ hội học tập bị thu hẹp.", "Số người nghèo tăng lên nhanh chóng trong mọi trường hợp, không cần căn cứ pháp luật."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: Đề 5 đáp án.docx · Phần I câu 3 · khoá: gạch chân"}, {"id": "L12-8T2-05-C04", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Khi Việt Nam gia nhập WTO, hàng hóa Việt Nam được hưởng lợi nào?", "o": ["Không phải tuân thủ luật thương mại mà không cần xem xét đến hoàn cảnh cụ thể.", "Được độc quyền xuất khẩu.", "Đối xử bình đẳng, ưu đãi thương mại theo cam kết.", "Được miễn toàn bộ mọi loại thuế."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: Đề 5 đáp án.docx · Phần I câu 4 · khoá: gạch chân"}, {"id": "L12-8T2-05-C05", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Hội nhập kinh tế quốc tế góp phần thúc đẩy", "o": ["chuyển giao công nghệ và nâng cao năng suất.", "giảm hoạt động đầu tư.", "sự cô lập của nền kinh tế.", "đóng cửa thị trường trong nước mà không cần xem xét đến hoàn cảnh cụ thể."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: Đề 5 đáp án.docx · Phần I câu 5 · khoá: gạch chân"}, {"id": "L12-8T2-05-C06", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Bảo hiểm xã hội tự nguyện áp dụng cho", "o": ["người lao động không thuộc đối tượng bắt buộc, có nguyện vọng tham gia.", "chỉ những người có hợp đồng lao động dài hạn mà không cần xem xét đến hoàn cảnh cụ thể.", "người đang đi học phổ thông.", "chỉ người nước ngoài."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: Đề 5 đáp án.docx · Phần I câu 6 · khoá: gạch chân"}, {"id": "L12-8T2-05-C07", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Khi người lao động không đóng bảo hiểm đúng quy định, họ có thể", "o": ["được hưởng đầy đủ quyền lợi như người đã đóng mà không cần xem xét đến hoàn cảnh cụ thể.", "bị ảnh hưởng quyền lợi và bị xử lý theo quy định của pháp luật.", "tự quyết định mức hưởng.", "được miễn mọi nghĩa vụ đóng góp."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: Đề 5 đáp án.docx · Phần I câu 7 · khoá: gạch chân"}, {"id": "L12-8T2-05-C08", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Trợ giúp đột xuất cho người dân khi gặp thiên tai là một nội dung của", "o": ["chính sách đối ngoại.", "chính sách tiền tệ.", "chính sách đầu tư công nghiệp.", "an sinh xã hội."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: Đề 5 đáp án.docx · Phần I câu 8 · khoá: gạch chân"}, {"id": "L12-8T2-05-C09", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Hệ thống an sinh xã hội có vai trò", "o": ["hạn chế sự tham gia của cộng đồng.", "tăng gánh nặng cho người có thu nhập thấp trong mọi trường hợp, không cần căn cứ pháp luật.", "thay thế hoàn toàn thị trường lao động.", "giúp người dân vượt qua rủi ro và ổn định cuộc sống."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: Đề 5 đáp án.docx · Phần I câu 9 · khoá: gạch chân"}, {"id": "L12-8T2-05-C10", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Mục tiêu của kế hoạch kinh doanh cần được xác định", "o": ["chung chung theo cảm tính.", "càng mơ hồ càng tốt để linh hoạt trong mọi trường hợp, không cần căn cứ pháp luật.", "chỉ dựa vào đối thủ cạnh tranh.", "cụ thể, đo lường được theo từng giai đoạn."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: Đề 5 đáp án.docx · Phần I câu 10 · khoá: gạch chân"}, {"id": "L12-8T2-05-C11", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Nội dung cốt lõi của kế hoạch kinh doanh gồm", "o": ["chỉ có nội dung quảng cáo.", "chỉ có phần trang trí bìa.", "chỉ liệt kê danh sách bạn bè thân thiết mà không cần xem xét đến hoàn cảnh cụ thể.", "tóm tắt, mô tả sản phẩm, thị trường, nhân sự và tài chính."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: Đề 5 đáp án.docx · Phần I câu 11 · khoá: gạch chân"}, {"id": "L12-8T2-05-C12", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Việc doanh nghiệp đầu tư vào đào tạo người lao động thể hiện trách nhiệm", "o": ["chỉ với cơ quan thuế.", "chỉ với đối thủ cạnh tranh trong mọi trường hợp, không cần căn cứ pháp luật.", "chỉ với cổ đông lớn.", "với người lao động và sự phát triển bền vững."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: Đề 5 đáp án.docx · Phần I câu 12 · khoá: gạch chân"}, {"id": "L12-8T2-05-C13", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Doanh nghiệp không tuân thủ quy định về xả thải thì", "o": ["có thể bị xử phạt và gây hậu quả cho cộng đồng.", "không chịu trách nhiệm pháp lý trong mọi trường hợp, không cần căn cứ pháp luật.", "được ưu tiên trong đấu thầu.", "được miễn nộp thuế môi trường."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: Đề 5 đáp án.docx · Phần I câu 13 · khoá: gạch chân"}, {"id": "L12-8T2-05-C14", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Trách nhiệm xã hội của doanh nghiệp có ý nghĩa đối với Nhà nước là", "o": ["nộp thuế đầy đủ và tuân thủ pháp luật.", "yêu cầu Nhà nước giảm mọi nghĩa vụ đóng góp.", "không cần liên hệ với cơ quan quản lý.", "trốn thuế để tăng lợi nhuận."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: Đề 5 đáp án.docx · Phần I câu 14 · khoá: gạch chân"}, {"id": "L12-8T2-05-C15", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Trong gia đình, người quản lý chi tiêu cần", "o": ["giữ kín mọi khoản chi tiêu với người thân.", "chi tiêu theo thói quen mà không cần kiểm tra mà không cần xem xét đến hoàn cảnh cụ thể.", "thống nhất kế hoạch chi tiêu với các thành viên.", "bỏ qua khoản dự phòng cho khẩn cấp."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: Đề 5 đáp án.docx · Phần I câu 15 · khoá: gạch chân"}, {"id": "L12-8T2-05-C16", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Doanh nghiệp được tuyển dụng lao động phù hợp theo quy định là thể hiện quyền nào?", "o": ["Quyền chiếm đoạt sức lao động.", "Quyền miễn thuế thu nhập.", "Quyền tự chủ trong sử dụng lao động.", "Quyền không phải đóng bảo hiểm trong mọi trường hợp, không cần căn cứ pháp luật."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: Đề 5 đáp án.docx · Phần I câu 16 · khoá: gạch chân"}, {"id": "L12-8T2-05-C17", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Người nộp thuế có quyền giữ bí mật thông tin nào?", "o": ["Thông tin về hóa đơn đã làm giả.", "Thông tin về các khoản thuế đã trốn.", "Mọi thông tin kinh doanh, kể cả thông tin cơ quan thuế yêu cầu trong mọi trường hợp, không cần căn cứ pháp luật.", "Thông tin cá nhân không thuộc diện phải cung cấp cho cơ quan thuế."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: Đề 5 đáp án.docx · Phần I câu 17 · khoá: gạch chân"}, {"id": "L12-8T2-05-C18", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Nghĩa vụ cạnh tranh lành mạnh của doanh nghiệp là gì?", "o": ["Dùng mọi cách để loại bỏ đối thủ mà không cần xem xét đến hoàn cảnh cụ thể.", "Bán phá giá để chiếm thị phần.", "Không dùng thủ đoạn gian lận để giành khách hàng.", "Sao chép thương hiệu của đối thủ."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: Đề 5 đáp án.docx · Phần I câu 18 · khoá: gạch chân"}, {"id": "L12-8T2-05-C19", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Hành vi nào sau đây không vi phạm quyền và nghĩa vụ về thuế?", "o": ["Chiếm đoạt tiền thuế đã thu.", "Trốn thuế bằng cách khai thiếu doanh thu.", "Làm giả hóa đơn để khấu trừ thuế.", "Kê khai đúng và nộp thuế đúng thời hạn."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: Đề 5 đáp án.docx · Phần I câu 19 · khoá: gạch chân"}, {"id": "L12-8T2-05-C20", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đọc đoạn thông tin sau:\nAnh K đã mua một số thực phẩm không rõ nguồn gốc của chị H để chế biến đồ ăn bán cho khách hàng. Hàng xóm của anh K là chị M phát hiện ra sự việc đã báo cho cán bộ cơ quan chức năng là ông N. Do có nhận của anh K một số tiền, nên ông N đã chỉ đạo cho nhân viên dưới quyền là anh G lập biên bản xử phạt chị H, còn anh K không bị xử phạt. Biết chuyện, chị H đã tố cáo hành vi của ông N với cơ quan có thẩm quyền khiến ông N bị tạm đình chỉ công tác để điều tra.\nChủ thể nào dưới đây đã vi phạm nghĩa vụ của công dân khi kinh d o a n h ?", "o": ["Anh G và ông N.", "Anh K và ông N.", "Chị H và ông N.", "Anh K và chị H."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: Đề 5 đáp án.docx · Phần I câu 20 · khoá: gạch chân"}, {"id": "L12-8T2-05-C21", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đọc đoạn thông tin sau:\nAnh K đã mua một số thực phẩm không rõ nguồn gốc của chị H để chế biến đồ ăn bán cho khách hàng. Hàng xóm của anh K là chị M phát hiện ra sự việc đã báo cho cán bộ cơ quan chức năng là ông N. Do có nhận của anh K một số tiền, nên ông N đã chỉ đạo cho nhân viên dưới quyền là anh G lập biên bản xử phạt chị H, còn anh K không bị xử phạt. Biết chuyện, chị H đã tố cáo hành vi của ông N với cơ quan có thẩm quyền khiến ông N bị tạm đình chỉ công tác để điều tra.\nChị H đã được thực hiện quyền của công dân về kinh doanh ở nội dung n à o d ư ớ i đ â y ?", "o": ["Tố cáo hành vi vi phạm kinh doanh.", "Khiếu nại để bảo vệ quyền lợi mà không cần xem xét đến hoàn cảnh cụ thể.", "Mở rộng quy mô sản xuất.", "Tự chủ đăng ký kinh doanh."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: Đề 5 đáp án.docx · Phần I câu 21 · khoá: gạch chân"}, {"id": "L12-8T2-05-C22", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đọc đoạn thông tin sau:\nAnh A và chị B cùng đến UBND huyện C đăng kí kinh doanh. Hồ sơ của hai người đầy đủ theo luật định. Anh A đăng kí kinh doanh đồ điện tử, chị B đăng kí kinh doanh hàng mỹ phẩm. Do có mâu thuân với chị B, anh X cán bộ phòng kinh doanh chỉ chấp nhận lĩnh vực đăng kí kinh doanh của anh A và đề nghị chị B đổi lĩnh vực kinh doanh khác thì mới chấp nhận với lí do khu vực này có nhiều cửa hàng mỹ phẩm. Thấy anh A được cấp phép kinh doanh trong khi hồ sơ của mình đủ điều kiện nhưng không được cấp phép, chị B đã viết bài đăng lên mạng xã hội vu khống chuyện đời tư của anh X.\nĐể bảo vệ quyền kinh doanh của mình, chị B có thể sử dụng quyền nào d ư ớ i đ â y ?", "o": ["Quyền trưng dụng.", "Quyền tố cáo.", "Quyền khiếu nại.", "Quyền đóng thuế."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: Đề 5 đáp án.docx · Phần I câu 22 · khoá: gạch chân"}, {"id": "L12-8T2-05-C23", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đọc đoạn thông tin sau:\nBà Đ nộp hồ sơ đăng kí thành lập doanh nghiệp và được cấp Giấy chứng nhận đăng kí doanh nghiệp. Sau khi được cấp phép kinh doanh, bà Đ đã chủ động tuyến dụng lao động, tìm đối tác kinh doanh, quảng cáo nhằm thu hút khách hàng. Thời gian đầu, doanh nghiệp của bà Đ còn bỡ ngỡ trong hồ sơ khai thuế thu nhập doanh nghiệp dẫn đến thiếu số tiền thuế phải nộp vào ngân sách nh� nước. Tuy nhiên, sau đó nhờ tìm hiểu kĩ hơn các quy định của pháp luật, b� Đ đã bổ sung đầy đủ số tiền thuế còn thiếu đúng thời hạn.\nBà Đ chưa thực hiện đúng nội dung nào dưới đây về quyền và nghĩa vụ c ủ a c ô n g d â n t r o n g n ộ p t h u ế ?", "o": ["Kê khai chưa đúng hồ sơ thuế.", "Chiếm đoạt tiền hoàn thuế.", "Khiếu nại quyền lợi về nộp thuế.", "Tố cáo hành vi vi phạm về thuế."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: Đề 5 đáp án.docx · Phần I câu 23 · khoá: gạch chân"}, {"id": "L12-8T2-05-C24", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đọc đoạn thông tin sau:\nBà Đ nộp hồ sơ đăng kí thành lập doanh nghiệp và được cấp Giấy chứng nhận đăng kí doanh nghiệp. Sau khi được cấp phép kinh doanh, bà Đ đã chủ động tuyến dụng lao động, tìm đối tác kinh doanh, quảng cáo nhằm thu hút khách hàng. Thời gian đầu, doanh nghiệp của bà Đ còn bỡ ngỡ trong hồ sơ khai thuế thu nhập doanh nghiệp dẫn đến thiếu số tiền thuế phải nộp vào ngân sách nh� nước. Tuy nhiên, sau đó nhờ tìm hiểu kĩ hơn các quy định của pháp luật, b� Đ đã bổ sung đầy đủ số tiền thuế còn thiếu đúng thời hạn.\nNội dung nào dưới đây không thể hiện quyền của công dân về kinh d o a n h t r o n g t h ô n g t i n t r ê n ?", "o": ["Quảng cáo để thu hút khách hàng mà không cần xem xét đến hoàn cảnh cụ thể.", "Nộp hồ sơ đăng ký kinh doanh.", "Nộp thuế cho cơ quan thẩm quyền.", "Chủ động tuyển dụng lao động."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: Đề 5 đáp án.docx · Phần I câu 24 · khoá: gạch chân"}, {"id": "L12-8T2-05-C25", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "dung_sai", "status": "cho_duyet", "q": "Đọc đoạn thông tin sau và cho biết mỗi ý a, b, c, d là Đúng hay Sai. Sau nhiều biện pháp tuyên truyền, giáo dục tuy nhiên hiện tượng đổ rác thải không đúng quy định vẫn diễn ra. Chị H hội trưởng hội phụ nữ xã X đề xuất sáng kiến lắp camera theo dõi khi thấy người vi phạm sẽ in và dán công khai hình ảnh các cá nhân đổ rác không đúng quy định tại nơi đổ rác. Thấy hình ảnh của mình bị dán tại khu vực đó, anh D vô cùng ấm ức cho rằng chị H đã xúc phạm tới danh dự và nhân phẩm của mình, sau khi có được những bằng chứng về việc cơ sở chế biến hải sản do anh M chồng chị H làm chủ có hành vi xả chất thải chưa qua xử lý ra môi trường và sử dụng các sản phẩm không có nguồn gốc xuất xứ bán cho khác hàng, anh D đã làm đơn tố cáo tới cơ quan chức năng khiến cơ sở của anh M bị đình chỉ hoạt động.", "o": ["Anh D vi phạm nghĩa vụ của công dân trong bảo vệ môi trường.", "Chị H vi phạm quyền của công dân được sống trong môi trường trong lành.", "Việc làm của anh M là chưa phù hợp với nghĩa vụ của công dân trong bảo vệ môi trường và chăm sóc sức khỏe công dân.", "Anh D tố cáo hành vi vi phạm của anh M với cơ quan chức năng là phù hợp với quyền của công dân trong bảo vệ môi trường."], "a": [true, false, true, true], "e": "Đáp án: a) Đúng; b) Sai; c) Đúng; d) Đúng.", "nguon": "Đề nguồn: Đề 5 đáp án.docx · Phần II câu 1 · khoá: chữ Đúng/Sai trong ý"}, {"id": "L12-8T2-05-C26", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "dung_sai", "status": "cho_duyet", "q": "Đọc đoạn thông tin sau và cho biết mỗi ý a, b, c, d là Đúng hay Sai. Theo Tổng cục Thống kê năm 2022, tổng tỷ lệ nghèo đa chiều cả nước l� 9,35%, trong đó, tỷ lệ hộ nghèo là 5,2% và tỷ lệ hộ cận nghèo là 4,15%. Theo báo cáo, Chỉ số phát triển con người (HDI) của Việt Nam là 0,703 vào năm 2021, tăng hai bậc trên bảng xếp hạng toàn cầu, lên vị trí 115/191 quốc gia, thuộc nhóm trung bình cao của thế giới. Điều này cho thấy, kinh tế, xã hội của nước ta đang tiếp tục phát triển và là điểm sáng thứ hai châu Á về tốc độ tăng GDP, cải thiện về thu hút FDI, vốn gián tiếp, kiều hối và phát triển du lịch, nông nghiệp và một số ngành công nghiệp phụ trợ gắn với xuất khẩu. Để thực hiện và giải quyết hài hòa mối quan hệ giữa tăng trưởng kinh tế, phát triển văn hóa, tiến bộ và công bằng xã hội, nhất định chúng ta phải xây dựng môi trường xã hội chủ nghĩa trong cơ chế thị trường định hướng xã hội chủ nghĩa, với một hệ giá trị thật sự tiến bộ.", "o": ["Chỉ số phát triển con người (HDI) tỷ lệ thuận với tốc độ tăng trưởng kinh tế trong nước.", "Tỷ lệ hộ nghèo, cận nghèo là chỉ tiêu quan trọng để đánh giá tốc độc tăng trưởng kinh tế của một quốc gia.", "Việt Nam đã giải quyết hài hòa mối quan hệ giữa tăng trưởng và phát triển kinh tế.", "Thực hiện nền kinh tế xanh, nền kinh tế tuần hoàn, nền kinh tế hướng tới con người là mục tiêu của tăng trưởng kinh tế."], "a": [true, false, true, false], "e": "Đáp án: a) Đúng; b) Sai; c) Đúng; d) Sai.", "nguon": "Đề nguồn: Đề 5 đáp án.docx · Phần II câu 2 · khoá: chữ Đúng/Sai trong ý"}, {"id": "L12-8T2-05-C27", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "dung_sai", "status": "cho_duyet", "q": "Đọc đoạn thông tin sau và cho biết mỗi ý a, b, c, d là Đúng hay Sai. Về cơ cấu nền kinh tế năm 2023, khu vực nông, lâm nghiệp và thủy sản chiếm tỷ trọng 11,96%; khu vực công nghiệp và xây dựng chiếm 37,12%; khu vực dịch vụ chiếm 42,54%; thuế sản phẩm trừ trợ cấp sản phẩm chiếm 8,38%. Quy mô GDP theo giá hiện hành năm 2023 ước đạt 10.221,8 nghìn tỷ đồng, tương đương 430 tỷ USD. GDP bình quân đầu người năm 2023 theo giá hiện hành ước đạt 101,9 triệu đồng/người, tương đương 4.284,5 USD, tăng 160 USD so với năm 2022. Năng suất lao động của toàn nền kinh tế năm 2023 theo giá hiện hành ước đạt 199,3 triệu đồng/lao động (tương đương 8.380 USD/lao động, tăng 274 USD so với năm 2022); theo giá so sánh, năng suất lao động tăng 3,65% do trình độ của người lao động được cải thiện (tỷ lệ lao động qua đào tạo có bằng, chứng chỉ năm 2023 ước đạt 27%, cao hơn 0,6 điểm phần trăm so với năm 2022).", "o": ["Cơ cấu ngành kinh tế chuyển dịch chưa phù hợp với các chỉ tiêu về phát triển kinh tế.", "Thu nhập 4284,5USD/1 (GDP/người) người năm 2023 thể hiện thu nhập quốc dân bình quân theo đầu người (GNI/người) của nước ta.", "Năng suất lao động là một chỉ tiêu cơ bản phản ánh sự tăng trưởng v� phát triển kinh tế của một quốc gia.", "Trình độ của người lao động là tiêu chí để đánh giá sự phát triển kinh tế."], "a": [false, false, false, false], "e": "Đáp án: a) Sai; b) Sai; c) Sai; d) Sai.", "nguon": "Đề nguồn: Đề 5 đáp án.docx · Phần II câu 3 · khoá: chữ Đúng/Sai trong ý"}, {"id": "L12-8T2-05-C28", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "dung_sai", "status": "cho_duyet", "q": "Đọc đoạn thông tin sau và cho biết mỗi ý a, b, c, d là Đúng hay Sai. Theo Tổng cục Thống kê công bố, tốc độ tăng trưởng GDP năm 2023 đạt 5,05% và có xu hướng tăng dần theo thời gian, quý IV đạt 6,72%, cao nhất so với quý III, II và quý 1 (tương ứng đạt 5,47, 4,25% và 3,41%), cao hơn mức trung bình của thế giới và khu vực cũng như nhiều nước trong giai đoạn tăng trưởng nhanh.", "o": ["Tốc độ tăng trưởng GDP của Việt Nam năm 2023 đạt mức cao nhất so với các năm trước đó.", "Tốc độ tăng trưởng GDP của Việt Nam năm 2023 sẽ tỉ lệ thuận với mức thu nhập và đời sống của người dân.", "Tốc độ tăng trưởng GDP của Việt Nam năm 2023 cho thấy Việt Nam là quốc gia có mức sống cao.", "Tốc độ tăng trưởng GDP của Việt Nam năm 2023 là căn cứ để so sánh với sự tăng trưởng kinh tế của năm 2024."], "a": [true, true, false, true], "e": "Đáp án: a) Đúng; b) Đúng; c) Sai; d) Đúng.", "nguon": "Đề nguồn: Đề 5 đáp án.docx · Phần II câu 4 · khoá: chữ Đúng/Sai trong ý"}]}, {"id": "L12-8T2-06", "loai": "khoi", "khoi": 12, "hoc_ki": 2, "bo": "8T2", "ten_bo": "8 tuần học kì II", "so_de": 6, "ten": "Lớp 12 · 8 tuần học kì II · Đề 6", "pham_vi": "Đề nguồn «8 TUẦN KÌ 2 › BO_DE_MOI» · file nguồn: Đề 6 đáp án.docx", "thoi_gian": 50, "cau_truc": "24 câu trắc nghiệm + 4 câu đúng/sai (mỗi câu 4 ý)", "status": "cho_duyet", "khoa": {"1 nguồn": 28}, "sua": "", "cau": [{"id": "L12-8T2-06-C01", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đặc điểm nổi bật của phát triển kinh tế so với tăng trưởng kinh tế là", "o": ["không cần thay đổi cơ cấu kinh tế.", "chỉ dựa vào thương mại quốc tế.", "chỉ phản ánh con số tổng sản phẩm mà không cần xem xét đến hoàn cảnh cụ thể.", "gắn với sự tiến bộ về cơ cấu, đời sống và môi trường."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: Đề 6 đáp án.docx · Phần I câu 1 · khoá: gạch chân"}, {"id": "L12-8T2-06-C02", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Vì sao cần chú trọng phát triển bền vững?", "o": ["Để bảo đảm hài hòa giữa kinh tế, xã hội và môi trường.", "Để chỉ tập trung vào lợi nhuận ngắn hạn mà không cần xem xét đến hoàn cảnh cụ thể.", "Để giảm vai trò của người dân.", "Để tăng nhanh sản lượng bằng mọi giá."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: Đề 6 đáp án.docx · Phần I câu 2 · khoá: gạch chân"}, {"id": "L12-8T2-06-C03", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Ví dụ nào thể hiện hội nhập kinh tế quốc tế ở cấp độ toàn cầu?", "o": ["Hai nước ký hiệp định thương mại song phương.", "Một doanh nghiệp mở chi nhánh nội địa.", "Các tỉnh trong nước liên kết du lịch.", "Việt Nam là thành viên của WTO."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: Đề 6 đáp án.docx · Phần I câu 3 · khoá: gạch chân"}, {"id": "L12-8T2-06-C04", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Nội dung nào sau đây là thách thức của hội nhập đối với doanh nghiệp nhỏ và vừa?", "o": ["Khó cạnh tranh với doanh nghiệp nước ngoài có tiềm lực lớn.", "Được hưởng mọi ưu đãi mà không cần chuẩn bị trong mọi trường hợp, không cần căn cứ pháp luật.", "Không phải thay đổi công nghệ sản xuất.", "Không cần đào tạo nhân lực."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: Đề 6 đáp án.docx · Phần I câu 4 · khoá: gạch chân"}, {"id": "L12-8T2-06-C05", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Việt Nam mở rộng quan hệ kinh tế với nhiều đối tác nhằm", "o": ["đóng cửa thị trường với bên ngoài mà không cần xem xét đến hoàn cảnh cụ thể.", "đa dạng hóa thị trường và giảm phụ thuộc vào một thị trường.", "hạn chế xuất khẩu hàng hóa.", "không cần thu hút vốn đầu tư."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: Đề 6 đáp án.docx · Phần I câu 5 · khoá: gạch chân"}, {"id": "L12-8T2-06-C06", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Bảo hiểm xã hội một lần được áp dụng khi", "o": ["người lao động đang làm việc bình thường.", "người lao động tự ý ngừng đóng và yêu cầu hưởng mà không cần xem xét đến hoàn cảnh cụ thể.", "người lao động chưa đóng bảo hiểm lần nào.", "người lao động không đủ điều kiện hưởng lương hưu theo quy định."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: Đề 6 đáp án.docx · Phần I câu 6 · khoá: gạch chân"}, {"id": "L12-8T2-06-C07", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Quyền lợi bảo hiểm y tế của người tham gia là", "o": ["được hỗ trợ chi phí khám bệnh, chữa bệnh theo quy định.", "được quyền kê đơn thuốc cho người khác.", "được hưởng lương hằng tháng từ bảo hiểm.", "được miễn mọi chi phí y tế trong mọi trường hợp trong mọi trường hợp, không cần căn cứ pháp luật."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: Đề 6 đáp án.docx · Phần I câu 7 · khoá: gạch chân"}, {"id": "L12-8T2-06-C08", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Chính sách bảo hiểm thất nghiệp và hỗ trợ việc làm nhằm", "o": ["làm tăng số người không có việc làm.", "khuyến khích người lao động nghỉ việc lâu dài trong mọi trường hợp, không cần căn cứ pháp luật.", "giảm tổng số lao động có trình độ.", "giúp người lao động ổn định đời sống và sớm tìm được việc mới."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: Đề 6 đáp án.docx · Phần I câu 8 · khoá: gạch chân"}, {"id": "L12-8T2-06-C09", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Người có công với cách mạng được hưởng chính sách nào?", "o": ["Miễn toàn bộ trách nhiệm đóng thuế thu nhập mà không cần xem xét đến hoàn cảnh cụ thể.", "Ưu đãi về đời sống, y tế, nhà ở theo quy định.", "Được trao quyền sở hữu mọi tài sản công.", "Được miễn mọi nghĩa vụ công dân."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: Đề 6 đáp án.docx · Phần I câu 9 · khoá: gạch chân"}, {"id": "L12-8T2-06-C10", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Trong kế hoạch kinh doanh, phân tích đối thủ cạnh tranh nhằm", "o": ["tránh mọi sự cạnh tranh trên thị trường trong mọi trường hợp, không cần căn cứ pháp luật.", "sao chép toàn bộ sản phẩm của đối thủ.", "chỉ tính lương cho nhân viên.", "nhận diện điểm mạnh, yếu để xác định lợi thế riêng."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: Đề 6 đáp án.docx · Phần I câu 10 · khoá: gạch chân"}, {"id": "L12-8T2-06-C11", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Trước khi đầu tư, doanh nghiệp cần dự tính rõ điều gì?", "o": ["Số lượng thành viên trong câu lạc bộ trong mọi trường hợp, không cần căn cứ pháp luật.", "Địa điểm tổ chức sự kiện khai trương.", "Mẫu logo và màu sắc của bảng hiệu.", "Nguồn vốn, chi phí ban đầu và thời gian thu hồi vốn."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: Đề 6 đáp án.docx · Phần I câu 11 · khoá: gạch chân"}, {"id": "L12-8T2-06-C12", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Hoạt động tài trợ học bổng của doanh nghiệp thể hiện trách nhiệm xã hội đối với", "o": ["cộng đồng và giáo dục.", "chính quyền địa phương để được ưu đãi.", "các nhà đầu tư ngắn hạn.", "đối thủ cạnh tranh."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: Đề 6 đáp án.docx · Phần I câu 12 · khoá: gạch chân"}, {"id": "L12-8T2-06-C13", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Doanh nghiệp cam kết không sử dụng lao động trẻ em là thể hiện trách nhiệm", "o": ["chỉ với cổ đông.", "với đối thủ trong ngành trong mọi trường hợp, không cần căn cứ pháp luật.", "với người lao động và quyền con người.", "chỉ với cơ quan thuế."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: Đề 6 đáp án.docx · Phần I câu 13 · khoá: gạch chân"}, {"id": "L12-8T2-06-C14", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Tuân thủ quy định về an toàn thực phẩm của doanh nghiệp đồ ăn là trách nhiệm đối với", "o": ["ngân hàng cho vay.", "đối thủ cạnh tranh.", "nhà đầu tư nước ngoài.", "người tiêu dùng."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: Đề 6 đáp án.docx · Phần I câu 14 · khoá: gạch chân"}, {"id": "L12-8T2-06-C15", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Để giảm nợ, gia đình nên", "o": ["không cần thanh toán đúng hạn.", "giấu kín các khoản nợ.", "lập kế hoạch trả nợ và ưu tiên khoản vay lãi suất cao.", "vay thêm để trả nợ cũ liên tục mà không cần xem xét đến hoàn cảnh cụ thể."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: Đề 6 đáp án.docx · Phần I câu 15 · khoá: gạch chân"}, {"id": "L12-8T2-06-C16", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Nghĩa vụ của công dân về kinh doanh không thể hiện ở việc doanh nghiệp phải", "o": ["bảo vệ quyền lợi người tiêu dùng.", "kinh doanh đúng ngành nghề đã đăng ký.", "gian lận doanh thu để giảm thuế.", "nộp thuế theo quy định."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: Đề 6 đáp án.docx · Phần I câu 16 · khoá: gạch chân"}, {"id": "L12-8T2-06-C17", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Doanh nghiệp đăng ký kinh doanh thêm ngành nghề mới khi đủ điều kiện, điều này thể hiện quyền nào?", "o": ["Quyền chiếm hữu tài sản công.", "Quyền bỏ qua thủ tục hành chính mà không cần xem xét đến hoàn cảnh cụ thể.", "Quyền tự chủ đăng ký kinh doanh.", "Quyền miễn nghĩa vụ thuế."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: Đề 6 đáp án.docx · Phần I câu 17 · khoá: gạch chân"}, {"id": "L12-8T2-06-C18", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Người nộp thuế được khiếu nại khi nào?", "o": ["Khi muốn được trốn thuế.", "Khi có căn cứ cho rằng quyết định về thuế làm ảnh hưởng quyền lợi hợp pháp.", "Khi muốn được hưởng thuế suất 0 mà không đủ điều kiện trong mọi trường hợp, không cần căn cứ pháp luật.", "Khi không muốn kê khai thuế."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: Đề 6 đáp án.docx · Phần I câu 18 · khoá: gạch chân"}, {"id": "L12-8T2-06-C19", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Công dân khi kinh doanh có trách nhiệm gì đối với môi trường?", "o": ["Khai thác tối đa tài nguyên không tái tạo.", "Bỏ qua quy định về môi trường.", "Bảo vệ tài nguyên và môi trường.", "Xả thải không xử lý để giảm chi phí."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: Đề 6 đáp án.docx · Phần I câu 19 · khoá: gạch chân"}, {"id": "L12-8T2-06-C20", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đọc đoạn thông tin sau:\nTrong năm 2023 toàn tỉnh M đã giải quyết việc làm mới cho hơn 8.000 lao động, trong 5 năm đã tạo việc làm cho 41.394 lao động, đạt 103% so với kế hoạch. Tỉ lệ thất nghiệp ở khu vực thành thị giảm từ 5,2% năm xuống còn 4,54%. Tỉ lệ sử dụng thời gian lao động ở khu vực nông thôn tăng dần, đạt 75% tăng lên 85%. Chương trình mục tiêu giảm nghèo của tỉnh triển khai có hiệu quả các chính sách, chương trình hỗ trợ người nghèo, hộ nghèo, vùng nghèo. Đa số hộ nghèo được nâng cao nhận thức, cố gắng tìm tòi học tập kinh nghiệm trong sản xuất, tự tạo việc làm để vươn lên thoát nghèo, cải thiện điều kiện sống và sinh hoạt. Kết quả giảm nghèo của toàn tỉnh trong 5 năm đã vượt mục tiêu đề ra, giảm từ 38.085 hộ nghèo, chiếm tỉ lệ 28,4% xuống còn 18.048 hộ nghèo.\nViệc giảm tỷ lệ thất nghiệp ở khu vực thành thị đã phản ánh hiệu q u ả c ủ a c h í n h s á c h a n s i n h x ã h ộ i n à o d ư ớ i đ â y m à t ỉ n h M đ ã t h ự c h i ệ n ?", "o": ["Chính sách bảo hiểm.", "Chính sách giảm nghèo.", "Chính sách thu nhập.", "Chính sách việc làm."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: Đề 6 đáp án.docx · Phần I câu 20 · khoá: gạch chân"}, {"id": "L12-8T2-06-C21", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đọc đoạn thông tin sau:\nTrong năm 2023 toàn tỉnh M đã giải quyết việc làm mới cho hơn 8.000 lao động, trong 5 năm đã tạo việc làm cho 41.394 lao động, đạt 103% so với kế hoạch. Tỉ lệ thất nghiệp ở khu vực thành thị giảm từ 5,2% năm xuống còn 4,54%. Tỉ lệ sử dụng thời gian lao động ở khu vực nông thôn tăng dần, đạt 75% tăng lên 85%. Chương trình mục tiêu giảm nghèo của tỉnh triển khai có hiệu quả các chính sách, chương trình hỗ trợ người nghèo, hộ nghèo, vùng nghèo. Đa số hộ nghèo được nâng cao nhận thức, cố gắng tìm tòi học tập kinh nghiệm trong sản xuất, tự tạo việc làm để vươn lên thoát nghèo, cải thiện điều kiện sống và sinh hoạt. Kết quả giảm nghèo của toàn tỉnh trong 5 năm đã vượt mục tiêu đề ra, giảm từ 38.085 hộ nghèo, chiếm tỉ lệ 28,4% xuống còn 18.048 hộ nghèo.\nChính sách an sinh xã hội nào dưới đây mà tỉnh M triển khai đã giúp c á c h ộ n g h è o t ừ n g b ư ớ c ổ n đ ị n h c u ộ c s ố n g ?", "o": ["Chính sách trợ giúp xã hội mà không cần xem xét đến hoàn cảnh cụ thể.", "Chính sách xóa đói, giảm nghèo.", "Chính sách bảo hiểm xã hội.", "Chính sách dịch vụ xã hội."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: Đề 6 đáp án.docx · Phần I câu 21 · khoá: gạch chân"}, {"id": "L12-8T2-06-C22", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đọc đoạn thông tin sau:\nTrong năm 2023 toàn tỉnh M đã giải quyết việc làm mới cho hơn 8.000 lao động, trong 5 năm đã tạo việc làm cho 41.394 lao động, đạt 103% so với kế hoạch. Tỉ lệ thất nghiệp ở khu vực thành thị giảm từ 5,2% năm xuống còn 4,54%. Tỉ lệ sử dụng thời gian lao động ở khu vực nông thôn tăng dần, đạt 75% tăng lên 85%. Chương trình mục tiêu giảm nghèo của tỉnh triển khai có hiệu quả các chính sách, chương trình hỗ trợ người nghèo, hộ nghèo, vùng nghèo. Đa số hộ nghèo được nâng cao nhận thức, cố gắng tìm tòi học tập kinh nghiệm trong sản xuất, tự tạo việc làm để vươn lên thoát nghèo, cải thiện điều kiện sống và sinh hoạt. Kết quả giảm nghèo của toàn tỉnh trong 5 năm đã vượt mục tiêu đề ra, giảm từ 38.085 hộ nghèo, chiếm tỉ lệ 28,4% xuống còn 18.048 hộ nghèo.\nNội dung nào dưới đây không thể hiện vai trò của việc thực hiện c h í n h s á c h a n s i n h x ã h ộ i m à t ỉ n h M đ ã t r i ể n k h a i ?", "o": ["Giải quyết vấn đề việc làm.", "Tăng thu nhập cho người dân.", "Thúc đẩy sự phân hóa giàu nghèo.", "Giúp người nghèo ổn định cuộc sống."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: Đề 6 đáp án.docx · Phần I câu 22 · khoá: gạch chân"}, {"id": "L12-8T2-06-C23", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đọc đoạn thông tin sau:\nHệ thống bảo hiểm xã hội được quan tâm phát triển với nội dung và hình thức ngày càng phong phú, nhằm chia sẻ rủi ro và trợ giúp thiết thực cho những người tham gia. Số người tham gia bảo hiểm bắt buộc tăng nhanh, từ 4,8 triệu (năm 2001) lên 9,7 triệu (năm 2011). Sau gần 3 năm triển khai bảo hiểm xã hội tự nguyện, đến năm 2010 có khoảng 96,6 nghìn người tham gia. Năm 2011 có khoảng 7,6 triệu người tham gia bảo hiểm thất nghiệp. Bảo hiểm y tế tăng nhanh từ 13,4% dân số (năm 2000) lên khoảng 62% (năm 2010). Đặc biệt, đã thực hiện chính sách bảo hiểm y tế miễn phí cho trẻ em dưới 6 tuổi, một số đối tượng chính sách, người nghèo và hỗ trợ bảo hiểm y tế cho các hộ cận nghèo, v.v..Bên cạnh đó việc hỗ trợ các đối tượng yếu thế được thực hiện rộng hơn cả về quy mô và đối tượng thụ hưởng với mức trợ giúp ngày càng tăng. Kinh phí trợ giúp thường xuyên từ ngân sách nhà nước và số người được thụ hưởng tăng nhanh, từ 113 tỉ đồng cho hơn 180 nghìn người (năm 2001) tăng lên 4.500 tỉ đồng cho hơn 1,6 triệu người (năm 2010). Hằng năm Nhà nước còn trợ cấp đột xuất hàng nghìn tỉ đồng và hàng chục nghìn tấn lương thực, thuốc men, chủ yếu để trợ giúp khắc phục thiên tai.\nHệ thống bảo hiểm là một trong những trụ cột của chính sách an sinh x ã h ộ i n à o d ư ớ i đ â y ?", "o": ["Chính sách thu nhập.", "Chính sách việc làm.", "Chính sách bảo hiểm.", "Chính sách giảm nghèo."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: Đề 6 đáp án.docx · Phần I câu 23 · khoá: gạch chân"}, {"id": "L12-8T2-06-C24", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đọc đoạn thông tin sau:\nHệ thống bảo hiểm xã hội được quan tâm phát triển với nội dung và hình thức ngày càng phong phú, nhằm chia sẻ rủi ro và trợ giúp thiết thực cho những người tham gia. Số người tham gia bảo hiểm bắt buộc tăng nhanh, từ 4,8 triệu (năm 2001) lên 9,7 triệu (năm 2011). Sau gần 3 năm triển khai bảo hiểm xã hội tự nguyện, đến năm 2010 có khoảng 96,6 nghìn người tham gia. Năm 2011 có khoảng 7,6 triệu người tham gia bảo hiểm thất nghiệp. Bảo hiểm y tế tăng nhanh từ 13,4% dân số (năm 2000) lên khoảng 62% (năm 2010). Đặc biệt, đã thực hiện chính sách bảo hiểm y tế miễn phí cho trẻ em dưới 6 tuổi, một số đối tượng chính sách, người nghèo và hỗ trợ bảo hiểm y tế cho các hộ cận nghèo, v.v..Bên cạnh đó việc hỗ trợ các đối tượng yếu thế được thực hiện rộng hơn cả về quy mô và đối tượng thụ hưởng với mức trợ giúp ngày càng tăng. Kinh phí trợ giúp thường xuyên từ ngân sách nhà nước và số người được thụ hưởng tăng nhanh, từ 113 tỉ đồng cho hơn 180 nghìn người (năm 2001) tăng lên 4.500 tỉ đồng cho hơn 1,6 triệu người (năm 2010). Hằng năm Nhà nước còn trợ cấp đột xuất hàng nghìn tỉ đồng và hàng chục nghìn tấn lương thực, thuốc men, chủ yếu để trợ giúp khắc phục thiên tai.\nViệc các đối tượng yếu thế được nhận sự hỗ trợ từ nguồn ngân sách n h à n ư ớ c l à t h ể h i ệ n c h í n h s á c h a n s i n h x ã h ộ i n à o d ư ớ i đ â y c ủ a n h à n ư ớ c ?", "o": ["Chính sách bảo hiểm xã hội.", "Chính sách trợ giúp xã hội.", "Chính sách giảm nghèo, thu nhập.", "Chính sách dịch vụ xã hội cơ bản."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: Đề 6 đáp án.docx · Phần I câu 24 · khoá: gạch chân"}, {"id": "L12-8T2-06-C25", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "dung_sai", "status": "cho_duyet", "q": "Đọc đoạn thông tin sau và cho biết mỗi ý a, b, c, d là Đúng hay Sai. Tính chung thời kì thực hiện Chiến lược phát triển kinh tế xã hội 10 năm (2011 - 2020), tăng trưởng GDP của Việt Nam đạt khoảng 5,9%/năm, thuộc nhóm các nước tăng trưởng cao trong khu vực. Quy mô GDP tăng gấp 2,4 lần, từ 116 tỉ USD năm 2010 lên 268,4 tỉ USD vào năm 2020. GDP bình quân đầu người tăng từ 1.331 USD năm 2010 lên khoảng 2.750 USD năm 2020. Tỉ lệ hộ nghèo cả nước giảm nhanh, từ 14,2% năm 2010 xuống còn 7% năm 2015 (theo chuẩn nghèo giai đoạn 2011 - 2015) và giảm từ 9,2% năm 2016 xuống dưới 3% vào năm 2020 (theo chuẩn nghèo đa chiều). Cơ sở hạ tầng thiết yếu ở các huyện nghèo, xã nghèo, vùng đồng bào dân tộc thiểu số được tăng cường. Thực hiện nhiều giải pháp tạo việc làm, nâng cao thu nhập cho người lao động", "o": ["Trong giai đoạn 2011 – 2020 Việt Nam luôn duy trì được tốc độ tăng trưởng kinh tế cao.", "Phát triển kinh tế góp phần giúp nước ta thực hiện tốt các vấn đề xã hội.", "Việc chúng ta đầu tư nhiều cho phát triển xã hội sẽ kéo giảm tốc độ tăng trưởng kinh tế.", "Trong quá trình phát triển, Việt Nam luôn đặt con người vào vị trí trung tâm của sự phát triển."], "a": [true, true, false, true], "e": "Đáp án: a) Đúng; b) Đúng; c) Sai; d) Đúng.", "nguon": "Đề nguồn: Đề 6 đáp án.docx · Phần II câu 1 · khoá: chữ Đúng/Sai trong ý"}, {"id": "L12-8T2-06-C26", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "dung_sai", "status": "cho_duyet", "q": "Đọc đoạn thông tin sau và cho biết mỗi ý a, b, c, d là Đúng hay Sai. Về kinh tế, từng bước thực hiện tăng trưởng xanh, phát triển năng lượng sạch; thực hiện sản xuất và tiêu dùng bền vững. Tăng trưởng kinh tế giai đoạn 2016 - 2020 đạt trung bình 7%/năm, nâng mức thu nhập bình quân đầu người hằng năm tính theo GDP tăng lên 3.200 - 3.500 USD (so với mức 2.100 USD năm 2015). Lạm phát giữ ở mức dưới 5%. Thực hiện tiến bộ và công bằng xã hội; thực hiện tốt các chính sách an sinh xã hội; năm 2014 đã có 1,4 triệu người tham gia bảo hiểm xã hội, trên 8,5 triệu người tham gia bảo hiểm thất nghiệp, trên 72% dân số tham gia bảo hiểm y tế. Đời sống nhân dân được cải thiện. Thu nhập bình quân đầu người đạt 2.052 USD/người (2014). Tuổi thọ trung bình đạt 73,5 tuổi (2015). Hoàn thành nhiều mục tiêu Thiên niên kỷ.", "o": ["Kết quả tăng trưởng kinh tế giai đoạn 2016 - 2020 đạt trung bình 7%/năm tạo tiền đề vật chất thúc đẩy các chỉ tiêu về phát triển kinh tế.", "Thu nhập theo đầu người từ 3.500 USD (GDP) giảm xuống còn 2052 USD (GNI) phản ánh sự phát triển kinh tế theo chiều hướng đi xuống.", "Tuổi thọ trung bình của người dân Việt Nam không ngừng tăng là kết quả của việc thực hiện tăng trưởng kinh tế cao.", "Với 72% dân số tham gia bảo hiểm y tế là thể hiện các chỉ tiêu về tiến bộ xã hội khi nước ta phát triển kinh tế."], "a": [true, false, true, true], "e": "Đáp án: a) Đúng; b) Sai; c) Đúng; d) Đúng.", "nguon": "Đề nguồn: Đề 6 đáp án.docx · Phần II câu 2 · khoá: chữ Đúng/Sai trong ý"}, {"id": "L12-8T2-06-C27", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "dung_sai", "status": "cho_duyet", "q": "Đọc đoạn thông tin sau và cho biết mỗi ý a, b, c, d là Đúng hay Sai. Vị thế của Việt Nam trên thế giới đã được củng cố toàn diện trong giai đoạn 2011 - 2022. Cùng với quá trình hội nhập kinh tế quốc tế mạnh mẽ, đến năm 2020, Việt Nam có 30 đối tác chiến lược và đối tác chiến lược toàn diện; có quan hệ ngoại giao với 189/193 nước, có quan hệ kinh tế với 160 nước và 70 vùng lãnh thổ. Đến năm 2022, tổng số quan hệ kinh tế - thương mại của Việt Nam đã nâng lên thành 230 nước và vùng lãnh thổ. Với việc thực hiện chủ trương hội nhập quốc tế toàn diện với trọng tâm là hội nhập kinh tế quốc tế, vị thế của đất nước tiếp tục được cải thiện đáng kể. Có thể khẳng định, hội nhập kinh tế quốc tế đóng góp quan trọng vào việc mở rộng và đưa quan hệ của nước ta với các đối tác đi vào chiều sâu, tạo thế đan xen lợi ích, góp phần gìn giữ môi trường hòa bình, ổn định để phát triển đất nước; nâng cao uy tín và vị thế của Việt Nam trên trường quốc tế.", "o": ["Việc thiết lập quan hệ đối tác chiến lược và chiến lược toàn diện l� thể hiện hình thức hội nhập kinh tế quốc tế ở cấp độ khu vực.", "Hội nhập kinh tế quốc tế không góp phần thúc đẩy sự tăng trưởng GDP hàng năm ở Việt Nam.", "Nước ta đang phát triển vì vậy khi hội nhập kinh tế quốc tế Việt Nam phải chấp nhận từ bỏ lợi ích của mình để hội nhập.", "Hội nhập kinh tế quốc tế góp phần đưa hàng hóa của Việt Nam đến với các thị trường trên thế giới."], "a": [false, false, false, true], "e": "Đáp án: a) Sai; b) Sai; c) Sai; d) Đúng.", "nguon": "Đề nguồn: Đề 6 đáp án.docx · Phần II câu 3 · khoá: chữ Đúng/Sai trong ý"}, {"id": "L12-8T2-06-C28", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "dung_sai", "status": "cho_duyet", "q": "Đọc đoạn thông tin sau và cho biết mỗi ý a, b, c, d là Đúng hay Sai. Đến nay, nước ta đã có quan hệ chính thức với 189/193 quốc gia và vùng lãnh thổ (trong đó có 4 đối tác chiến lược toàn diện, 17 đối tác chiến lược, 13 đối tác toàn diện); có quan hệ thương mại với 224 đối tác và quan hệ hợp tác với hơn 300 tổ chức quốc tế; đã ký hơn 90 hiệp định thương mại song phương, gần 60 hiệp định khuyến khích và bảo hộ đầu tư; đàm phán, ký kết và thực thi 19 Hiệp định thương mại tự do (FTA) song phương và đa phương với hầu hết các nền kinh tế lớn trên thế giới; trong đó 16 FTA đã có hiệu lực với hơn 60 đối tác, phủ rộng khắp các châu lục với tổng GDP chiếm gần 90% GDP toàn cầu, đưa Việt Nam trở thành một trong những nước dẫn đầu khu vực về tham gia các khuôn khổ hợp tác kinh tế song phương và đa phương. �", "o": ["Nước ta có quan hệ hợp tác kinh tế với 189/193 quốc gia và vùng lãnh thổ.", "Việc ký kết các hiệp định thương mại song phương và đa phương giúp Việt Nam mở rộng hoạt động kinh tế đối ngoại.", "Kinh tế đối ngoại là yếu tố giữ vai trò quan trọng góp phần thúc đẩy tăng trưởng và phát triển kinh tế.", "Hoạt động kinh tế đối ngoại là một bộ phận cấu thành chính sách đối ngoại của Việt Nam."], "a": [false, true, true, true], "e": "Đáp án: a) Sai; b) Đúng; c) Đúng; d) Đúng.", "nguon": "Đề nguồn: Đề 6 đáp án.docx · Phần II câu 4 · khoá: chữ Đúng/Sai trong ý"}]}, {"id": "L12-8T2-07", "loai": "khoi", "khoi": 12, "hoc_ki": 2, "bo": "8T2", "ten_bo": "8 tuần học kì II", "so_de": 7, "ten": "Lớp 12 · 8 tuần học kì II · Đề 7", "pham_vi": "Đề nguồn «8 TUẦN KÌ 2 › BO_DE_MOI» · file nguồn: Đề 7 đáp án.docx", "thoi_gian": 50, "cau_truc": "24 câu trắc nghiệm + 4 câu đúng/sai (mỗi câu 4 ý)", "status": "cho_duyet", "khoa": {"1 nguồn": 28}, "sua": "", "cau": [{"id": "L12-8T2-07-C01", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Chế độ hôn nhân và gia đình ở Việt Nam dựa trên nguyên tắc nào?", "o": ["Gia trưởng, do bố mẹ quyết định.", "Một vợ, một chồng; tự nguyện, tiến bộ.", "Đa thê, đa phu theo truyền thống mà không cần xem xét đến hoàn cảnh cụ thể.", "Ràng buộc bằng tài sản."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: Đề 7 đáp án.docx · Phần I câu 1 · khoá: gạch chân"}, {"id": "L12-8T2-07-C02", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Độ tuổi kết hôn tối thiểu theo luật hiện hành là", "o": ["nam đủ 22 tuổi, nữ đủ 20 tuổi.", "nam đủ 18 tuổi, nữ đủ 16 tuổi trong mọi trường hợp, không cần căn cứ pháp luật.", "nam và nữ đều đủ 16 tuổi.", "nam đủ 20 tuổi, nữ đủ 18 tuổi."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: Đề 7 đáp án.docx · Phần I câu 2 · khoá: gạch chân"}, {"id": "L12-8T2-07-C03", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Hành vi nào sau đây bị pháp luật nghiêm cấm trong kết hôn?", "o": ["Tổ chức lễ cưới theo phong tục.", "Đăng ký kết hôn tại Ủy ban nhân dân.", "Tảo hôn.", "Chung sống sau khi đã kết hôn hợp pháp."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: Đề 7 đáp án.docx · Phần I câu 3 · khoá: gạch chân"}, {"id": "L12-8T2-07-C04", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Tài sản chung của vợ chồng bao gồm", "o": ["tài sản được thừa kế riêng.", "tài sản có trước khi kết hôn trong mọi trường hợp, không cần căn cứ pháp luật.", "quà tặng riêng cho một bên.", "thu nhập do lao động, sản xuất kinh doanh trong thời kỳ hôn nhân."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: Đề 7 đáp án.docx · Phần I câu 4 · khoá: gạch chân"}, {"id": "L12-8T2-07-C05", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Tài sản riêng của vợ hoặc chồng là tài sản", "o": ["có trước khi kết hôn hoặc được thừa kế riêng.", "tạo lập từ tiền lương của hai người.", "do cả hai người cùng tạo ra.", "mua trong thời kỳ hôn nhân bằng thu nhập chung."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: Đề 7 đáp án.docx · Phần I câu 5 · khoá: gạch chân"}, {"id": "L12-8T2-07-C06", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Vợ hoặc chồng có quyền yêu cầu ly hôn đơn phương khi", "o": ["bên kia bị Tòa án tuyên mất năng lực hành vi dân sự hoặc có bạo lực gia đình.", "hai người có bất đồng về ý kiến nhỏ trong sinh hoạt mà không cần xem xét đến hoàn cảnh cụ thể.", "bên kia không thích món ăn của mình.", "bên kia đi làm xa nhà vài tháng."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: Đề 7 đáp án.docx · Phần I câu 6 · khoá: gạch chân"}, {"id": "L12-8T2-07-C07", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Bạo lực gia đình là hành vi", "o": ["bàn bạc chi tiêu chung.", "cố ý gây tổn hại về thể chất, tinh thần, kinh tế giữa các thành viên gia đình.", "nhắc nhở con cái học tập.", "phân công việc nhà hợp lý mà không cần xem xét đến hoàn cảnh cụ thể mà không cần xem xét đến hoàn cảnh cụ thể."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: Đề 7 đáp án.docx · Phần I câu 7 · khoá: gạch chân"}, {"id": "L12-8T2-07-C08", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Vợ chồng có quyền lựa chọn nơi cư trú như thế nào?", "o": ["Do vợ quyết định toàn bộ.", "Do người lớn tuổi nhất trong nhà quyết định.", "Bình đẳng, bàn bạc và thống nhất với nhau.", "Do chồng quyết định toàn bộ."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: Đề 7 đáp án.docx · Phần I câu 8 · khoá: gạch chân"}, {"id": "L12-8T2-07-C09", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Khi ly hôn, việc giao con cho ai nuôi được quyết định dựa trên", "o": ["sự thuận tiện cho bên nội hoặc bên ngoại.", "quyền lợi mọi mặt của con.", "lỗi của bên không đòi được con.", "ý muốn của bên có thu nhập cao hơn."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: Đề 7 đáp án.docx · Phần I câu 9 · khoá: gạch chân"}, {"id": "L12-8T2-07-C10", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Mọi công dân có quyền học tập theo quy định, không phân biệt", "o": ["nơi cư trú đăng ký thường trú mà không cần xem xét đến hoàn cảnh cụ thể.", "dân tộc, giới tính, tôn giáo, hoàn cảnh kinh tế.", "trình độ học vấn trước đó.", "thời gian đã làm việc."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: Đề 7 đáp án.docx · Phần I câu 10 · khoá: gạch chân"}, {"id": "L12-8T2-07-C11", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Việc hoàn thành phổ cập giáo dục trung học cơ sở là", "o": ["quyền lợi chỉ dành cho học sinh giỏi.", "trách nhiệm chỉ của gia đình.", "điều kiện không bắt buộc với mọi người mà không cần xem xét đến hoàn cảnh cụ thể.", "nghĩa vụ của mỗi công dân trong độ tuổi quy định."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: Đề 7 đáp án.docx · Phần I câu 11 · khoá: gạch chân"}, {"id": "L12-8T2-07-C12", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Hành vi nào sau đây vi phạm nghĩa vụ học tập và quy định thi cử?", "o": ["Chấp hành nội quy nhà trường.", "Tôn trọng nhà giáo.", "Gian lận trong kiểm tra và thi cử.", "Nộp bài kiểm tra đúng thời gian quy định."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: Đề 7 đáp án.docx · Phần I câu 12 · khoá: gạch chân"}, {"id": "L12-8T2-07-C13", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Học sinh khuyết tật hoặc thuộc hộ nghèo được", "o": ["miễn toàn bộ mọi nghĩa vụ học tập mà không cần xem xét đến hoàn cảnh cụ thể.", "hỗ trợ học tập theo chính sách của Nhà nước.", "được chuyển trường tùy ý.", "được cấp bằng mà không cần học."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: Đề 7 đáp án.docx · Phần I câu 13 · khoá: gạch chân"}, {"id": "L12-8T2-07-C14", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Công dân có nghĩa vụ đối với nhà giáo, cán bộ, nhân viên trong nhà trường là", "o": ["bình luận xúc phạm trên mạng xã hội.", "không cần tham gia các hoạt động của trường.", "tôn trọng, lễ phép và chấp hành nội quy.", "yêu cầu nhân viên phục vụ riêng."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: Đề 7 đáp án.docx · Phần I câu 14 · khoá: gạch chân"}, {"id": "L12-8T2-07-C15", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Quyền được học tập suốt đời thể hiện ở việc", "o": ["học một lần rồi không học thêm.", "không được học lại khi đã có bằng.", "công dân được học thường xuyên, học liên tục để nâng cao trình độ.", "chỉ học đến khi có việc làm đầu tiên mà không cần xem xét đến hoàn cảnh cụ thể."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: Đề 7 đáp án.docx · Phần I câu 15 · khoá: gạch chân"}, {"id": "L12-8T2-07-C16", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Khi quyền học tập bị xâm phạm, người học có thể", "o": ["tự ý bỏ học và không báo cáo.", "khiếu nại, tố cáo theo quy định của pháp luật.", "tự xử lý bằng vũ lực với nhà trường trong mọi trường hợp, không cần căn cứ pháp luật.", "bỏ qua vì không quan trọng."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: Đề 7 đáp án.docx · Phần I câu 16 · khoá: gạch chân"}, {"id": "L12-8T2-07-C17", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Công dân có quyền được bảo vệ và chăm sóc sức khỏe, trong đó bao gồm quyền", "o": ["từ chối mọi dịch vụ y tế của Nhà nước trong mọi trường hợp, không cần căn cứ pháp luật.", "tự kê đơn thuốc cho người khác.", "không tiêm chủng theo ý muốn.", "được khám bệnh, chữa bệnh và tham gia bảo hiểm y tế."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: Đề 7 đáp án.docx · Phần I câu 17 · khoá: gạch chân"}, {"id": "L12-8T2-07-C18", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Nghĩa vụ của công dân trong phòng, chống dịch bệnh là", "o": ["tham gia tiêm chủng và thực hiện các biện pháp phòng bệnh.", "phát tán thông tin sai lệch về dịch bệnh trong mọi trường hợp, không cần căn cứ pháp luật.", "trốn tránh cách ly khi có chỉ định.", "tự ý tiêm thuốc không rõ nguồn gốc."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: Đề 7 đáp án.docx · Phần I câu 18 · khoá: gạch chân"}, {"id": "L12-8T2-07-C19", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Hành vi nào sau đây bị nghiêm cấm trong bảo vệ sức khỏe?", "o": ["Đảm bảo vệ sinh an toàn thực phẩm.", "Tham gia bảo hiểm y tế.", "Sử dụng, mua bán ma túy.", "Thăm khám sức khỏe định kỳ."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: Đề 7 đáp án.docx · Phần I câu 19 · khoá: gạch chân"}, {"id": "L12-8T2-07-C20", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đọc đoạn thông tin sau:\nTheo thống kê, hiện nước ta có khoảng hơn 20% dân số là những đối tượng yếu thế trong xã hội, trong đó khoảng trên 12 triệu người cao tuổi, gần 7 triệu người khuyết tật, người có vấn đề sức khỏe tâm thần, 2 triệu trẻ em có hoàn cảnh đặc biệt, khoảng 2 triệu lượt hộ gia đình cần được trợ giúp đột xuất hàng năm, 234.000 người nhiễm HIV được phát hiện, khoảng 30.000 nạn nhân bị bạo lực, bạo hành trong gia đình. Ngoài ra, còn các đối tượng là phụ nữ, trẻ em bị ngược đãi, bị mua bán, bị xâm hại, hoặc lang thang kiếm sống trên đường phố cần được sự trợ giúp của Nhà nước và xã hội.\nNội dung nào dưới đây không góp phần vào việc hỗ trợ, trợ giúp các l ự c l ư ợ n g y ế u t h ế t r o n g x ã h ộ i v ớ i h ệ t h ố n g c h í n h s á c h a n s i n h x ã h ộ i c ủ a n ư ớ c t a ?", "o": ["Hỗ trợ về y tế và bảo hiểm.", "Xây dựng trung tâm bảo trợ xã hội trong mọi trường hợp, không cần căn cứ pháp luật.", "Trợ cấp kinh phí hàng tháng.", "Ngăn cản họ tiếp cận dịch vụ xã hội."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: Đề 7 đáp án.docx · Phần I câu 20 · khoá: gạch chân"}, {"id": "L12-8T2-07-C21", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đọc đoạn thông tin sau:\nTheo thống kê, hiện nước ta có khoảng hơn 20% dân số là những đối tượng yếu thế trong xã hội, trong đó khoảng trên 12 triệu người cao tuổi, gần 7 triệu người khuyết tật, người có vấn đề sức khỏe tâm thần, 2 triệu trẻ em có hoàn cảnh đặc biệt, khoảng 2 triệu lượt hộ gia đình cần được trợ giúp đột xuất hàng năm, 234.000 người nhiễm HIV được phát hiện, khoảng 30.000 nạn nhân bị bạo lực, bạo hành trong gia đình. Ngoài ra, còn các đối tượng là phụ nữ, trẻ em bị ngược đãi, bị mua bán, bị xâm hại, hoặc lang thang kiếm sống trên đường phố cần được sự trợ giúp của Nhà nước và xã hội.\nĐể giúp các đối tượng yếu thế trong xã hội, nhà nước cần đẩy mạnh t h ự c h i ệ n c h í n h s á c h a n s i n h x ã h ộ i n à o d ư ớ i đ â y ?", "o": ["Chính sách việc làm.", "Chính sách giáo dục.", "Chính sách trợ giúp xã hội.", "Chính sách xóa đói giảm nghèo."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: Đề 7 đáp án.docx · Phần I câu 21 · khoá: gạch chân"}, {"id": "L12-8T2-07-C22", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đọc đoạn thông tin sau:\nĐể vận hành quán cà phê, anh H xác định ngoài chủ quán có 8 nhân viên; Chủ quán: người trực tiếp quản lí và điều hành quản lí 24/7; Tiếp tân: thu tiền và in hoá đơn; Đầu bếp: pha chế nước uống và chế biến món ăn. Quán hoạt động từ 6 giờ đến 23 giờ nên đội ngũ được chia thành hai ca, mỗi ca 4 người. Khi quán đông khách có thể huy động thời gian rảnh của các thành viên trong gia đình để phục vụ.\nThông tin trên đề cập đến yếu tố nào dưới đây khi tiến hành đánh g i á c á c đ i ề u k i ệ n t h ự c h i ệ n h o ạ t đ ộ n g k i n h d o a n h ?", "o": ["Thị trường.", "Sản phẩm.", "Nhân sự.", "Khách hàng."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: Đề 7 đáp án.docx · Phần I câu 22 · khoá: gạch chân"}, {"id": "L12-8T2-07-C23", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đọc đoạn thông tin sau:\nĐể vận hành quán cà phê, anh H xác định ngoài chủ quán có 8 nhân viên; Chủ quán: người trực tiếp quản lí và điều hành quản lí 24/7; Tiếp tân: thu tiền và in hoá đơn; Đầu bếp: pha chế nước uống và chế biến món ăn. Quán hoạt động từ 6 giờ đến 23 giờ nên đội ngũ được chia thành hai ca, mỗi ca 4 người. Khi quán đông khách có thể huy động thời gian rảnh của các thành viên trong gia đình để phục vụ.\nAnh H đã thực hiện nội dung nào dưới đây của lập kế hoạch kinh d o a n h ?", "o": ["Phân tích các điều kiện kinh doanh.", "Xác định mục tiêu kinh doanh.", "Đánh giá các yếu tố rủi ro gặp phải.", "Xác định chiến lược kinh doanh."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: Đề 7 đáp án.docx · Phần I câu 23 · khoá: gạch chân"}, {"id": "L12-8T2-07-C24", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đọc đoạn thông tin sau:\nNhận thấy quê hương mình rất phong phú về các loại thảo mộc và nhu cầu thị trường về dòng sản phẩm này thiên nhiên ngày càng tăng lên, anh H đã xây dựng kế hoạch kinh doanh mĩ phẩm chiết xuất từ thiên nhiên. Sau khi đánh giá những thuận lợi và khó khăn, anh H nhận thấy kế hoạch kinh doanh của mình có khả thi. Nhờ xây dựng kế hoạch kinh doanh tốt, đánh giá đúng cơ hội, đối tượng khách hàng tiềm năng,… nên việc kinh doanh của anh H đã đạt được những thành công ban đầu.\nAnh H đã biết xác định ý tưởng kinh doanh thông qua việc làm nào d ư ớ i đ â y ?", "o": ["Kinh doanh mĩ phẩm từ thiên nhiên trong mọi trường hợp, không cần căn cứ pháp luật.", "Đánh giá tiềm năng về khách hàng.", "Đạt hiệu quả cao trong kinh doanh.", "Nhận thấy nhu cầu cao về thảo mộc."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: Đề 7 đáp án.docx · Phần I câu 24 · khoá: gạch chân"}, {"id": "L12-8T2-07-C25", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "dung_sai", "status": "cho_duyet", "q": "Đọc đoạn thông tin sau và cho biết mỗi ý a, b, c, d là Đúng hay Sai. Chia sẻ về việc quyết định tham gia BHXH tự nguyện, chị D cho biết, trước đây chị làm công nhân đã có 10 năm tham gia BHXH bắt buộc và sau khi nghỉ việc chị không còn được tham gia nữa. Nghỉ việc ở nhà, chị chuyển sang bán hàng ăn để mưu sinh hàng ngày. Công việc vất vả, thức khuya dậy sớm khiến sức khỏe chị ngày một yếu đi. Lúc này chị bắt đầu nghĩ tới và tham gia BHXH tự nguyện. Tính đến nay chị đã đóng được 5 năm, mỗi lần đều đóng theo quý, mỗi quý hơn 600 ngàn đồng. Không những tham gia BHXH tự nguyện, chị còn tham gia cả BHYT hộ gia đình. Nói về lợi ích của việc tham gia những loại hình bảo hiểm trên, chị D xúc động cho hay: Tôi cũng vừa mới mổ u được vài tháng. Đến khi bị bệnh tôi mới thấy sự hữu ích của những loại hình bảo hiểm này. Cứ hoàn cảnh như hiện nay, khi hết tuổi lao động mà không tham gia các loại hình bảo hiểm của nhà nước sẽ không biết lấy gì nuôi thân nếu như không có nguồn thu ổn định.", "o": ["Chị D tham gia bảo hiểm bắt buộc 10 năm sau đó bỏ không tham gia vì đã nghỉ việc là hợp lý.", "Người lao động tự do nên tham gia bảo hiểm xã hội tự nguyện.", "Vì đã tham gia bảo hiểm xã hội nên khi nhập viện mổ khối u chị sẽ được hưởng trợ cấp ốm đau.", "Loại hình bảo hiểm y tế mà chị D tham gia là loại hình bảo hiểm y tế bắt buộc đối với mọi gia đình."], "a": [false, true, false, false], "e": "Đáp án: a) Sai; b) Đúng; c) Sai; d) Sai.", "nguon": "Đề nguồn: Đề 7 đáp án.docx · Phần II câu 1 · khoá: chữ Đúng/Sai trong ý"}, {"id": "L12-8T2-07-C26", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "dung_sai", "status": "cho_duyet", "q": "Đọc đoạn thông tin sau và cho biết mỗi ý a, b, c, d là Đúng hay Sai. Ông H, ở Thành phố K, sau khi dừng tham gia BHXH bắt buộc đã bỏ số tiền hơn 44 triệu đồng đóng BHXH tự nguyện những năm còn thiếu để được hưởng lương hưu tâm sự, chia sẻ: “Lúc trước làm việc, tôi cũng có tham gia BHXH, do điều kiện tôi xin nghỉ và đã hưởng một lần. Số tiền nhận khi đó cũng giúp tôi làm được một số việc nhưng cũng chẳng được bao lâu. Đến khi sau này đi làm lại và tham gia BHXH, lúc gần nghỉ việc do hết tuổi lao động, quá trình tham gia BHXH của mình chỉ được 18 năm 02 tháng chưa đủ điều kiện để hưởng chế độ hưu trí. Tôi đã suy nghĩ, rút kinh nghiệm lần trước nên đã quyết định đóng BHXH tự nguyện số năm còn thiếu để hưởng lương hưu”. Tiền lương hưu hàng tháng cũng đủ trang trải cho cuộc sống hàng ngày, mình còn được cấp thẻ BHYT quyền lợi cao hơn so với lúc đi làm để đi khám bệnh, m� lớn tuổi rồi sức khỏe xuống có khi ở bệnh viện nhiều hơn ở nhà. Nên tính ra việc nhận lương hưu nó bảo đảm hơn cho bản thân mình khi về già”.", "o": ["Ông H quyết định đóng một lần số năm còn thiếu để hưởng chế độ hưu trí là phù hợp.", "Việc rút bảo hiểm xã hội một lần là việc cần cân nhắc kỹ lưỡng với mọi công dân vì quyền lợi lâu dài.", "Ngoài chế độ hưu trí, ông H còn được hưởng trợ cấp ốm đau và chế độ bảo hiểm y tế.", "Việc linh hoạt đóng chế độ bảo hiểm xã hội tự nguyện thể hiện chính sách ưu việt của nhà nước."], "a": [true, true, false, true], "e": "Đáp án: a) Đúng; b) Đúng; c) Sai; d) Đúng.", "nguon": "Đề nguồn: Đề 7 đáp án.docx · Phần II câu 2 · khoá: chữ Đúng/Sai trong ý"}, {"id": "L12-8T2-07-C27", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "dung_sai", "status": "cho_duyet", "q": "Đọc đoạn thông tin sau và cho biết mỗi ý a, b, c, d là Đúng hay Sai. Chị E giao kết hợp đồng lao động không xác định thời hạn với công ty A. Hàng tháng, chị E đóng đầy đủ các loại BHXH. Đến 01/6/2020, chị E nghỉ thai sản (nghỉ đến hết 31/12/2020). Vì lý do gia đình, 01/1/2021 chị E nộp đơn xin nghỉ việc. Trước khi chấm dứt HĐLĐ, tổng thời gian đóng bảo hiểm thất nghiệp là 15 tháng. Căn cứ vào quy định của pháp luật lao động chị đã làm hồ sơ gửi cơ quan chức năng để nhận hỗ trợ theo quy định. Sau đó được sự tư vấn của bạn bè, chị E tham gia gói bảo hiểm nhân thọ cho cả mẹ và con chị.", "o": ["Loại hình bảo hiểm xã hội mà chị E tham gia trước khi nghỉ việc là bảo hiểm xã hội tự nguyện.", "Chị E đã tham gia loại hình bảo hiểm thất nghiệp tự nguyện nên chị được hưởng trợ cấp thất nghiệp.", "Trước khi nghỉ việc chị E không tham gia bảo hiểm y tế.", "Bảo hiểm nhân thọ mà chị E tham gia là loại hình bảo hiểm thương mại."], "a": [false, false, false, true], "e": "Đáp án: a) Sai; b) Sai; c) Sai; d) Đúng.", "nguon": "Đề nguồn: Đề 7 đáp án.docx · Phần II câu 3 · khoá: chữ Đúng/Sai trong ý"}, {"id": "L12-8T2-07-C28", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "dung_sai", "status": "cho_duyet", "q": "Đọc đoạn thông tin sau và cho biết mỗi ý a, b, c, d là Đúng hay Sai. Ông N từng tham gia đóng BHXH bắt buộc, sau đó ông nghỉ tham gia Hội Nông dân thị trấn khi mới đóng được 15 năm, chưa đủ điều kiện về số năm đóng BHXH để có chế độ hưu trí (tối thiểu 20 năm). Cuối năm 2022, ông quyết định tham gia BHXH tự nguyện, nhờ sự kiên trì theo đuổi đóng đủ số năm quy định, giờ đây ông N chính thức được nhận lương hưu. Ông chia sẻ: “ Sau khi được tư vấn cán bộ BHXH huyện, trường hợp của tôi có 2 phương án lựa chọn, 1 l� hưởng BHXH 01 lần , hai là đóng 1 lần BHXH tự nguyện những năm còn thiếu. Sau khi nghe cán bộ BHXH phân tích, tôi suy nghĩ và bàn bạc với gia đình, ông quyết định đóng BHXH tự nguyện một lần cho những năm còn thiếu. Sau khi hoàn thành thủ tục đóng tiền, ít ngày sau tôi nhận tháng lương hưu đầu tiên với số tiền hơn 1,8 triệu đồng. Với khoản lương hưu này giúp tôi có thêm khoản thu nhập để lo cuộc sống hàng ngày. Ngoài ra, tôi còn được cấp thẻ BHYT chăm sóc sức khỏe trọn đời.", "o": ["Công dân cứ đóng đủ số năm tham gia bảo hiểm xã hội là sẽ được nhận chế độ hưu trí.", "Ông N đã cao tuổi nên nếu rút bảo hiểm xã hội một lần sẽ lợi hơn khi đóng tiếp để hưởng hưu trí.", "Ông N chỉ được hưởng chế độ hưu trí và thẻ bảo hiểm y tế để khám bệnh.", "Tham gia bảo hiểm đã giúp ông N được bảo vệ sức khỏe và yên tâm về tài chính khi về già."], "a": [false, false, false, true], "e": "Đáp án: a) Sai; b) Sai; c) Sai; d) Đúng.", "nguon": "Đề nguồn: Đề 7 đáp án.docx · Phần II câu 4 · khoá: chữ Đúng/Sai trong ý"}]}, {"id": "L12-8T2-08", "loai": "khoi", "khoi": 12, "hoc_ki": 2, "bo": "8T2", "ten_bo": "8 tuần học kì II", "so_de": 8, "ten": "Lớp 12 · 8 tuần học kì II · Đề 8", "pham_vi": "Đề nguồn «8 TUẦN KÌ 2 › BO_DE_MOI» · file nguồn: Đề 8 đáp án.docx", "thoi_gian": 50, "cau_truc": "24 câu trắc nghiệm + 4 câu đúng/sai (mỗi câu 4 ý)", "status": "cho_duyet", "khoa": {"1 nguồn": 28}, "sua": "", "cau": [{"id": "L12-8T2-08-C01", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Mọi công dân có quyền kết hôn, ly hôn tự nguyện, dựa trên", "o": ["sự sắp đặt của người làm mai.", "sự tự nguyện của hai bên nam, nữ.", "quyết định của cha mẹ hai bên mà không cần xem xét đến hoàn cảnh cụ thể.", "thỏa thuận về lợi ích kinh tế."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: Đề 8 đáp án.docx · Phần I câu 1 · khoá: gạch chân"}, {"id": "L12-8T2-08-C02", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Cấm kết hôn giữa những người nào sau đây?", "o": ["Người có cùng dòng máu trực hệ.", "Người khác quê quán.", "Người có chênh lệch về học vấn mà không cần xem xét đến hoàn cảnh cụ thể.", "Người có sở thích khác nhau."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: Đề 8 đáp án.docx · Phần I câu 2 · khoá: gạch chân"}, {"id": "L12-8T2-08-C03", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Khi vợ chồng có tài sản chung, việc định đoạt tài sản đó được thực hiện theo nguyên tắc nào?", "o": ["Chỉ người lớn tuổi hơn có quyền quyết định trong mọi trường hợp, không cần căn cứ pháp luật.", "Người đứng tên giấy tờ tự quyết định.", "Bàn bạc, thỏa thuận bình đẳng giữa vợ và chồng.", "Người có thu nhập cao hơn quyết định."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: Đề 8 đáp án.docx · Phần I câu 3 · khoá: gạch chân"}, {"id": "L12-8T2-08-C04", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Nghĩa vụ cấp dưỡng giữa cha mẹ và con thể hiện ở việc", "o": ["con phải nuôi cha mẹ khi còn đang đi học.", "con không có quyền được cấp dưỡng.", "cha mẹ có trách nhiệm nuôi dưỡng, chăm sóc con chưa thành niên.", "cha mẹ chỉ cấp dưỡng khi con đã có việc làm trong mọi trường hợp, không cần căn cứ pháp luật."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: Đề 8 đáp án.docx · Phần I câu 4 · khoá: gạch chân"}, {"id": "L12-8T2-08-C05", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Quan hệ giữa ông bà và cháu được pháp luật bảo vệ bằng nghĩa vụ nào?", "o": ["Ông bà, cha mẹ, con cháu có quyền và nghĩa vụ tôn trọng, chăm sóc lẫn nhau.", "Ông bà không được nuôi dưỡng cháu.", "Ông bà tự do không liên hệ với cháu.", "Cháu không có trách nhiệm với ông bà trong mọi trường hợp, không cần căn cứ pháp luật."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: Đề 8 đáp án.docx · Phần I câu 5 · khoá: gạch chân"}, {"id": "L12-8T2-08-C06", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Vợ chồng có quyền và nghĩa vụ nào sau đây với nhau?", "o": ["Không cần chia sẻ trách nhiệm gia đình.", "Chung thủy, tôn trọng, giúp đỡ nhau.", "Được phép sống ly thân không cần lý do.", "Được tự ý sử dụng tài sản của nhau."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: Đề 8 đáp án.docx · Phần I câu 6 · khoá: gạch chân"}, {"id": "L12-8T2-08-C07", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Hôn nhân được thừa nhận theo pháp luật khi", "o": ["tổ chức lễ cưới tại gia đình.", "hai người sống chung nhà mà không đăng ký mà không cần xem xét đến hoàn cảnh cụ thể.", "có giấy hẹn của bên thứ ba.", "đăng ký kết hôn tại cơ quan có thẩm quyền."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: Đề 8 đáp án.docx · Phần I câu 7 · khoá: gạch chân"}, {"id": "L12-8T2-08-C08", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Bên bị bạo lực gia đình có quyền", "o": ["im lặng chịu đựng để giữ gìn gia đình trong mọi trường hợp, không cần căn cứ pháp luật.", "tự trả thù người gây bạo lực.", "yêu cầu cơ quan chức năng bảo vệ và xử lý người vi phạm.", "bỏ đi và không báo cho ai."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: Đề 8 đáp án.docx · Phần I câu 8 · khoá: gạch chân"}, {"id": "L12-8T2-08-C09", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Quyền học tập của công dân được pháp luật bảo đảm thông qua", "o": ["việc chỉ học các môn tự chọn.", "việc gia đình tự quyết định mọi thứ trong mọi trường hợp, không cần căn cứ pháp luật.", "hệ thống giáo dục quốc dân và chính sách hỗ trợ.", "học phí bắt buộc không có miễn giảm."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: Đề 8 đáp án.docx · Phần I câu 9 · khoá: gạch chân"}, {"id": "L12-8T2-08-C10", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Học sinh có nghĩa vụ giữ gìn tài sản của nhà trường, điều này thể hiện là", "o": ["quyền sử dụng tài sản trường cho mục đích riêng trong mọi trường hợp, không cần căn cứ pháp luật.", "quyền bán thiết bị học tập cũ.", "quyền mang tài sản trường về nhà.", "trách nhiệm chấp hành quy định về cơ sở vật chất."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: Đề 8 đáp án.docx · Phần I câu 10 · khoá: gạch chân"}, {"id": "L12-8T2-08-C11", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Khi hoàn thành chương trình giáo dục theo quy định, người học được", "o": ["hoàn lại toàn bộ tiền học phí đã nộp.", "miễn làm bài thi cuối kỳ của lớp học khác.", "bổ nhiệm vào cơ quan Nhà nước.", "cấp văn bằng, chứng chỉ tương ứng."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: Đề 8 đáp án.docx · Phần I câu 11 · khoá: gạch chân"}, {"id": "L12-8T2-08-C12", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Nội dung nào sau đây là nghĩa vụ của học sinh trong học tập?", "o": ["Học tập chăm chỉ và hoàn thành chương trình.", "Không cần đóng góp bất kỳ hoạt động nào mà không cần xem xét đến hoàn cảnh cụ thể.", "Chỉ học các môn mình thích.", "Nghỉ học tùy ý khi không có hứng thú."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: Đề 8 đáp án.docx · Phần I câu 12 · khoá: gạch chân"}, {"id": "L12-8T2-08-C13", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Người học được quyền tham gia các hoạt động giáo dục nào?", "o": ["Các hoạt động ngoại khóa, văn hóa, thể thao phù hợp.", "Các hoạt động trái pháp luật về giáo dục.", "Các hoạt động vi phạm nội quy trường học trong mọi trường hợp, không cần căn cứ pháp luật.", "Các hoạt động gây mất trật tự cộng đồng."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: Đề 8 đáp án.docx · Phần I câu 13 · khoá: gạch chân"}, {"id": "L12-8T2-08-C14", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Công dân có quyền được hưởng chính sách an sinh xã hội khi", "o": ["không có nhu cầu gì về sức khỏe.", "chưa từng đóng góp và không thuộc đối tượng nào mà không cần xem xét đến hoàn cảnh cụ thể.", "tự nguyện từ bỏ mọi chế độ.", "gặp rủi ro như ốm đau, tai nạn, già yếu theo quy định."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: Đề 8 đáp án.docx · Phần I câu 14 · khoá: gạch chân"}, {"id": "L12-8T2-08-C15", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Việc tham gia bảo hiểm y tế của người dân thể hiện nghĩa vụ nào?", "o": ["Đòi hoàn tiền đã đóng khi chưa ốm đau.", "Góp phần bảo đảm an sinh và sức khỏe cộng đồng.", "Tự khám chữa bệnh không cần cơ sở y tế.", "Trốn tránh trách nhiệm chi phí khám chữa bệnh trong mọi trường hợp, không cần căn cứ pháp luật."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: Đề 8 đáp án.docx · Phần I câu 15 · khoá: gạch chân"}, {"id": "L12-8T2-08-C16", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Người khuyết tật được pháp luật bảo đảm quyền nào sau đây?", "o": ["Được hỗ trợ, tạo điều kiện hòa nhập cộng đồng.", "Bị loại khỏi chế độ trợ cấp.", "Bị hạn chế tiếp cận giáo dục.", "Bị cấm tham gia hoạt động xã hội trong mọi trường hợp, không cần căn cứ pháp luật."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: Đề 8 đáp án.docx · Phần I câu 16 · khoá: gạch chân"}, {"id": "L12-8T2-08-C17", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Hành vi nào sau đây thể hiện trách nhiệm bảo vệ sức khỏe bản thân?", "o": ["Không hút thuốc lá, không uống rượu bia quá mức.", "Thường xuyên thức khuya và bỏ bữa.", "Tự ý sử dụng chất kích thích để giảm căng thẳng trong mọi trường hợp, không cần căn cứ pháp luật.", "Không đi khám khi có triệu chứng bất thường."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: Đề 8 đáp án.docx · Phần I câu 17 · khoá: gạch chân"}, {"id": "L12-8T2-08-C18", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Chính sách bảo vệ môi trường của Nhà nước nhằm mục tiêu", "o": ["tăng nhanh sản lượng bằng mọi giá.", "chỉ bảo vệ môi trường đô thị.", "phát triển bền vững, bảo vệ sức khỏe con người và thiên nhiên.", "giảm việc làm trong các ngành khai thác trong mọi trường hợp, không cần căn cứ pháp luật."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: Đề 8 đáp án.docx · Phần I câu 18 · khoá: gạch chân"}, {"id": "L12-8T2-08-C19", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Công dân có nghĩa vụ phân loại rác thải sinh hoạt nhằm mục đích", "o": ["chỉ để tiện cho người thu gom tự thu nhập mà không cần xem xét đến hoàn cảnh cụ thể.", "tăng khối lượng rác để dễ thu gom.", "để dễ dàng vứt bỏ ra ngoài đường.", "giảm ô nhiễm và tạo điều kiện tái chế, xử lý đúng quy định."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: Đề 8 đáp án.docx · Phần I câu 19 · khoá: gạch chân"}, {"id": "L12-8T2-08-C20", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đọc đoạn thông tin sau:\nNhận thấy quê hương mình rất phong phú về các loại thảo mộc và nhu cầu thị trường về dòng sản phẩm này thiên nhiên ngày càng tăng lên, anh H đã xây dựng kế hoạch kinh doanh mĩ phẩm chiết xuất từ thiên nhiên. Sau khi đánh giá những thuận lợi và khó khăn, anh H nhận thấy kế hoạch kinh doanh của mình có khả thi. Nhờ xây dựng kế hoạch kinh doanh tốt, đánh giá đúng cơ hội, đối tượng khách hàng tiềm năng,… nên việc kinh doanh của anh H đã đạt được những thành công ban đầu.\nKhi đánh giá những thuận lợi và khó khăn khi tiến hành kinh doanh, a n h H đ ã t h ự c h i ệ n b ư ớ c n à o d ư ớ i đ â y c ủ a v i ệ c l ậ p k ế h o ạ c h k i n h d o a n h ?", "o": ["Xác định mục tiêu kinh doanh.", "Phân tích những rủi ro và biện pháp xử lý.", "Phân tích điều kiện thực hiện kinh doanh.", "Xác định ý tưởng kinh doanh."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: Đề 8 đáp án.docx · Phần I câu 20 · khoá: gạch chân"}, {"id": "L12-8T2-08-C21", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đọc đoạn thông tin sau:\nSau khi tốt nghiệp đại học ngành công nghệ sinh học, với lợi thế l� nhà gần các trường đại học, lại có diện tích đất lớn, chị D quyết định lập nghiệp bằng con đường kinh doanh sản phẩm cây cảnh mi ni với mong muốn sau hai năm sẽ thành lập một doanh nghiệp phân phối các sản phẩm này. Xác định, đây là lĩnh vực kinh doanh không đòi hỏi vốn lớn, trong khi thị trường l� các bạn sinh viên có nhu cầu khá cao về loại sản phẩm này, lại không đòi hỏi phải thuê nhiều lao động. Khi bắt tay vào thực hiện công việc kinh doanh, chị đã tìm các nguồn hàng ở nhiều nơi có truyền thống kinh doanh cây cảnh để nhập về khá, ngoài việc thuê một cửa hàng gần trường đại học để bán và giới thiệu sản phẩm, chị D còn ứng dụng các nền tảng mạng xã hội để đăng và quảng bá sản phẩm. Do thời gian đầu chưa có nhiều kinh nghiệm, nên sản phẩm chị cung cấp nhiều cây gặp sâu bệnh chết, đối tượng khách hàng chưa thực sự nhiều, vốn bỏ ra tuy được bảo toàn nhưng lợi nhuận không cao. Từ thực tế kinh doanh, chị quyết định mở rộng sản xuất và lên kế hoạch đầu tư thêm nhiều cửa hàng mới cũng như phát triển kênh truyền thống nhằm mở rộng thị trường.\nNội dung nào dưới đây thể hiện chị D đã biết xác định ý tưởng khi l ậ p k ế h o ạ c h k i n h d o a n h ?", "o": ["Sử dụng mạng xã hội.", "Thuê lao động bán hàng.", "Mở cửa hàng để bán.", "Kinh doanh cây cảnh."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: Đề 8 đáp án.docx · Phần I câu 21 · khoá: gạch chân"}, {"id": "L12-8T2-08-C22", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đọc đoạn thông tin sau:\nSau khi tốt nghiệp đại học ngành công nghệ sinh học, với lợi thế l� nhà gần các trường đại học, lại có diện tích đất lớn, chị D quyết định lập nghiệp bằng con đường kinh doanh sản phẩm cây cảnh mi ni với mong muốn sau hai năm sẽ thành lập một doanh nghiệp phân phối các sản phẩm này. Xác định, đây là lĩnh vực kinh doanh không đòi hỏi vốn lớn, trong khi thị trường l� các bạn sinh viên có nhu cầu khá cao về loại sản phẩm này, lại không đòi hỏi phải thuê nhiều lao động. Khi bắt tay vào thực hiện công việc kinh doanh, chị đã tìm các nguồn hàng ở nhiều nơi có truyền thống kinh doanh cây cảnh để nhập về khá, ngoài việc thuê một cửa hàng gần trường đại học để bán và giới thiệu sản phẩm, chị D còn ứng dụng các nền tảng mạng xã hội để đăng và quảng bá sản phẩm. Do thời gian đầu chưa có nhiều kinh nghiệm, nên sản phẩm chị cung cấp nhiều cây gặp sâu bệnh chết, đối tượng khách hàng chưa thực sự nhiều, vốn bỏ ra tuy được bảo toàn nhưng lợi nhuận không cao. Từ thực tế kinh doanh, chị quyết định mở rộng sản xuất và lên kế hoạch đầu tư thêm nhiều cửa hàng mới cũng như phát triển kênh truyền thống nhằm mở rộng thị trường.\nViệc làm nào dưới đây thể hiện khả năng phân tích các điều kiện t h ự c h i ệ n ý t ư ở n g k i n h d o a n h c ủ a c h ị D ?", "o": ["Thiếu kinh nghiệm nên chưa thành công.", "Nhu cầu về mặt hàng cây cảnh lớn.", "Lựa chọn kinh doanh cây cảnh.", "Thành lập doanh nghiệp sau hai năm."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: Đề 8 đáp án.docx · Phần I câu 22 · khoá: gạch chân"}, {"id": "L12-8T2-08-C23", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đọc đoạn thông tin sau:\nSau khi tốt nghiệp đại học ngành công nghệ sinh học, với lợi thế l� nhà gần các trường đại học, lại có diện tích đất lớn, chị D quyết định lập nghiệp bằng con đường kinh doanh sản phẩm cây cảnh mi ni với mong muốn sau hai năm sẽ thành lập một doanh nghiệp phân phối các sản phẩm này. Xác định, đây là lĩnh vực kinh doanh không đòi hỏi vốn lớn, trong khi thị trường l� các bạn sinh viên có nhu cầu khá cao về loại sản phẩm này, lại không đòi hỏi phải thuê nhiều lao động. Khi bắt tay vào thực hiện công việc kinh doanh, chị đã tìm các nguồn hàng ở nhiều nơi có truyền thống kinh doanh cây cảnh để nhập về khá, ngoài việc thuê một cửa hàng gần trường đại học để bán và giới thiệu sản phẩm, chị D còn ứng dụng các nền tảng mạng xã hội để đăng và quảng bá sản phẩm. Do thời gian đầu chưa có nhiều kinh nghiệm, nên sản phẩm chị cung cấp nhiều cây gặp sâu bệnh chết, đối tượng khách hàng chưa thực sự nhiều, vốn bỏ ra tuy được bảo toàn nhưng lợi nhuận không cao. Từ thực tế kinh doanh, chị quyết định mở rộng sản xuất và lên kế hoạch đầu tư thêm nhiều cửa hàng mới cũng như phát triển kênh truyền thống nhằm mở rộng thị trường.\nChị D đã xác định cho mình mục tiêu kinh doanh l�", "o": ["đẩy mạnh truyền thông.", "lập thân, lập nghiệp.", "thành lập doanh nghiệp.", "mở rộng sản xuất."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: Đề 8 đáp án.docx · Phần I câu 23 · khoá: gạch chân"}, {"id": "L12-8T2-08-C24", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đọc đoạn thông tin sau:\nVới mong muốn xây dựng thành công chuỗi cửa hành phân phối thực phẩm sạch trên địa bàn huyện X. Sau khi tham khảo một số mô hình cũng như kiến thức cơ bản về lĩnh vực kinh doanh này. Anh H đã lên kế hoạch chi tiết để thực hiện ý tưởng kinh doanh của mình. Qua tìm hiểu thực tế anh nhận thấy, đây là sản phẩm đang có nhu cầu lớn, nếu chất lượng đảm bảo thì hoàn toàn có thể chiếm lĩnh được lòng tin của người tiêu dùng. Đặc biệt, qua tư vấn của bạn bè, anh H đã dự liệu được những rủi ro, khó khăn tiềm ẩn để có giải pháp khắc phục. Trên cơ sở tìm hiểu và đánh giá này, anh H đã lên kế hoạch chi tiết việc bán hàng, tiếp thị, quảng cáo để quảng bá giới thiệu sản phẩn đến khách hàng. Sự cam kết của anh đối với việc cung cấp sản phẩm chất lượng cao và an toàn đã thu hút được người tiêu dùng. Chính các yếu tố này đã giúp anh H xây dựng thành công thương hiệu của mình trên địa bàn huyện X, anh dự định sẽ tiếp tục mở rộng các cửa hàng để hình thành chuỗi cửa hàng chất lượng cao.\nNội dung nào dưới đây thể hiện việc xác định ý tưởng kinh doanh của a n h H ?", "o": ["Mở cửa hàng chất lượng cao.", "Đẩy mạnh quảng cáo sản phẩm.", "Kinh doanh thực phẩm sạch.", "Xây dựng chuỗi cửa hàng."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: Đề 8 đáp án.docx · Phần I câu 24 · khoá: gạch chân"}, {"id": "L12-8T2-08-C25", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "dung_sai", "status": "cho_duyet", "q": "Đọc đoạn thông tin sau và cho biết mỗi ý a, b, c, d là Đúng hay Sai. Gần đây, Trường Đại học C tổ chức kì thi kết thúc học phần nhưng do không nắm vững kiến thức các môn học nên M (sinh viên Trường Đại học C) quyết định tìm người thi hộ. Thông qua mạng xã hội, M thuê B (sinh viên một trường đại học khác trên địa bàn) thi hộ hai môn chuyên ngành với giá 600.000 đồng/môn. Tuy nhiên, khi B đang sử dụng giấy tờ giả để tham dự kì thi hộ M thì đã bị giám thị phát hiện. Sau đó các cơ quan chức năng đã tiến hành xử lý hành vi vi phạm của cả M và B bằng hình thức đuổi học.", "o": ["Sinh viên M đã vi phạm quyền học tập của sinh viên B.", "Bạn M và B đều được học tập tại các trường đại học là thực hiện quyền học tập của công dân.", "Việc cơ quan chức năng tiến hành đuổi học bạn M và bạn B là vi phạm quyền học tập của công dân.", "Việc bạn M và bạn B khiếu nại quyết định kỷ luật đối với mình là không phù hợp vì hành vi của 2 người là cụ thể."], "a": [false, true, false, false], "e": "Đáp án: a) Sai; b) Đúng; c) Sai; d) Sai.", "nguon": "Đề nguồn: Đề 8 đáp án.docx · Phần II câu 1 · khoá: chữ Đúng/Sai trong ý"}, {"id": "L12-8T2-08-C26", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "dung_sai", "status": "cho_duyet", "q": "Đọc đoạn thông tin sau và cho biết mỗi ý a, b, c, d là Đúng hay Sai. Trước đây, điều kiện gia đình khó khăn nên ông Đ phải nghỉ học giữa chừng để kiếm tiền phụ giúp bố mẹ. Mỗi khi nhìn bạn bè theo đuổi con đường học tập, ông luôn cảm thấy tiếc nuối. Khi lập gia đình và có con, ông Đ đặt hết mọi kì vọng của bản thân lên các con của mình. Vì vậy, ông luôn cố gắng tạo điều kiện về kinh tế để các con yên tâm học tập nhưng lại luôn so sánh, tạo sức ép, bắt các con phải tập trung học tập, ngăn cấm các con tham gia những hoạt động văn hoá, văn nghệ, thể dục thể thao và những hoạt động xã hội khác. Gần đây, khi nhận tin con trai cả không thi đỗ vào trường chuyên của tỉnh, ông Đ vô cùng tức giận. Ông dùng nhiều lời lẽ tiêu cực để so sánh con với các bạn học khác và tuyên bố không cho con đi học.", "o": ["Ông Đ bị xâm phạm đến quyền học tập của công dân.", "Các con của ông Đ đã được thực hiện tốt quyền học tập của mình.", "Việc cấm các con không được tham gia các hoạt động văn hóa, văn nghệ để học tập là phù hợp với quyền và nghĩa vụ giữa cha mẹ và con.", "Việc dùng lời lẽ tiêu cực và so sánh kết quả học tập của con mình với các bạn khác của ông Đ là hành vi xâm phạm đến quyền của công dân trong gia đình và trong học tập."], "a": [false, true, false, true], "e": "Đáp án: a) Sai; b) Đúng; c) Sai; d) Đúng.", "nguon": "Đề nguồn: Đề 8 đáp án.docx · Phần II câu 2 · khoá: chữ Đúng/Sai trong ý"}, {"id": "L12-8T2-08-C27", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "dung_sai", "status": "cho_duyet", "q": "Đọc đoạn thông tin sau và cho biết mỗi ý a, b, c, d là Đúng hay Sai. S là sinh viên năm thứ nhất của một trường đại học. Sau khi tìm hiểu các quy định của trường, S đã quyết định đăng kí thêm các môn học khác so với chương trình tiêu chuẩn mỗi học kì. S nhận thấy các môn có sự liên kết nhất định với nhau và nếu tích luỹ đủ các tín chỉ theo chương trình đào tạo có thể ra trường sớm hơn so với các bạn. Biết được ý định của con, bố mẹ đã ra sức phản đối không cho S đăng kí học vượt với lí do không phù hợp với trình độ nhận thức nhưng S vẫn làm hồ sơ đăng ký học thêm và được chấp nhận. Tuy nhiên do không sắp xếp được giữa việc học và đi làm thêm nên sau một năm đăng ký học thêm, S không đủ điều kiện được học tiếp.", "o": ["Sinh viên S đã được thực hiện quyền học tập của mình một cách phù hợp.", "Việc phản đối của bố mẹ S là vi phạm quyền học tập của công dân.", "Việc không đủ điều kiện được học tiếp các của sinh viên S không vi phạm nghĩa vụ học tập của công dân.", "Sinh viên S có quyền được khiếu nại để nhà trường xem xét lại quyết định không cho học tiếp đối với bản thân mình."], "a": [true, true, false, true], "e": "Đáp án: a) Đúng; b) Đúng; c) Sai; d) Đúng.", "nguon": "Đề nguồn: Đề 8 đáp án.docx · Phần II câu 3 · khoá: chữ Đúng/Sai trong ý"}, {"id": "L12-8T2-08-C28", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "dung_sai", "status": "cho_duyet", "q": "Đọc đoạn thông tin sau và cho biết mỗi ý a, b, c, d là Đúng hay Sai. Sau khi thi đỗ vào trường Đại học mơ ước, V quyết tâm học thật tốt với mong muốn có được việc làm phù hợp với chuyên ngành. Ngay từ năm thứ nhất, V đặt mục tiêu ra trường sớm để có thể giúp đỡ gia đình. Do đó, V đã lập kế hoạch học tập và đăng kí học vượt. Kết quả là V đã tốt nghiệp sớm hơn một năm v� có thể tự tin tìm việc với bằng tốt nghiệp loại Giỏi của mình và đủ điều kiện được học tiếp Thạc sỹ. Khi nộp hồ sơ ứng tuyển vào các công ty, hồ sơ của V đều bị loại với lý do V chưa có kinh nghiệm thực tế. Xuất phát từ thực tế đó, V quyết định vừa đăng ký học thạc sĩ vừa xin đi làm thêm cho một số công ty để tích lũy kinh nghiệm.", "o": ["Việc V đỗ vào trường Đại học mình mơ ước là phù hợp với quyền học tập không hạn chế của công dân.", "Sinh viên V vừa đi học Thạc sỹ vừa đi làm là chưa phù hợp với nghĩa vụ của công dân về học tập.", "Công dân có quyền đăng ký học trước tuổi, học vượt lớp nếu đủ điều kiện.", "Ngoài việc được thực hiện quyền học tập không hạn chế, sinh viên V đã lựa chọn hình thức học tập thường xuyên, học suốt đời để phù hợp với bản thân."], "a": [true, false, true, true], "e": "Đáp án: a) Đúng; b) Sai; c) Đúng; d) Đúng.", "nguon": "Đề nguồn: Đề 8 đáp án.docx · Phần II câu 4 · khoá: chữ Đúng/Sai trong ý"}]}, {"id": "L12-8T2-09", "loai": "khoi", "khoi": 12, "hoc_ki": 2, "bo": "8T2", "ten_bo": "8 tuần học kì II", "so_de": 9, "ten": "Lớp 12 · 8 tuần học kì II · Đề 9", "pham_vi": "Đề nguồn «8 TUẦN KÌ 2 › BO_DE_MOI» · file nguồn: Đề 9 đáp án.docx", "thoi_gian": 50, "cau_truc": "24 câu trắc nghiệm + 4 câu đúng/sai (mỗi câu 4 ý)", "status": "cho_duyet", "khoa": {"1 nguồn": 28}, "sua": "", "cau": [{"id": "L12-8T2-09-C01", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Chế độ tài sản của vợ chồng do ai thỏa thuận?", "o": ["Cha mẹ hai bên quyết định.", "Ủy ban nhân dân địa phương quyết định mà không cần xem xét đến hoàn cảnh cụ thể.", "Vợ và chồng, theo nguyên tắc tự nguyện, bình đẳng.", "Ngân hàng nơi vay vốn quyết định."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: Đề 9 đáp án.docx · Phần I câu 1 · khoá: gạch chân"}, {"id": "L12-8T2-09-C02", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Khi ly hôn, tài sản chung được chia theo nguyên tắc nào?", "o": ["Thuộc về người có thu nhập cao nhất.", "Bảo đảm quyền lợi hợp pháp của vợ, chồng và con.", "Chia đều tuyệt đối trong mọi trường hợp trong mọi trường hợp, không cần căn cứ pháp luật.", "Thuộc về người đứng tên trên giấy tờ."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: Đề 9 đáp án.docx · Phần I câu 2 · khoá: gạch chân"}, {"id": "L12-8T2-09-C03", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Hành vi nào sau đây vi phạm quyền bình đẳng trong hôn nhân và gia đình?", "o": ["Vợ chồng cùng chăm sóc con cái.", "Vợ chồng cùng bàn bạc việc chi tiêu.", "Vợ hoặc chồng ép buộc người kia phải từ bỏ việc học.", "Vợ chồng cùng thực hiện kế hoạch hóa gia đình mà không cần xem xét đến hoàn cảnh cụ thể."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: Đề 9 đáp án.docx · Phần I câu 3 · khoá: gạch chân"}, {"id": "L12-8T2-09-C04", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Trong quan hệ hôn nhân, tự do lựa chọn bạn đời là", "o": ["quyền chỉ thực hiện khi đã đủ 30 tuổi.", "quyền của mỗi người, không ai được cưỡng ép.", "quyền phải có sự đồng ý của tất cả họ hàng mà không cần xem xét đến hoàn cảnh cụ thể.", "quyền chỉ dành cho nam giới."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: Đề 9 đáp án.docx · Phần I câu 4 · khoá: gạch chân"}, {"id": "L12-8T2-09-C05", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Vợ chồng có nghĩa vụ đối với con cái trong việc nào?", "o": ["Chỉ cung cấp tiền mà không quan tâm tinh thần mà không cần xem xét đến hoàn cảnh cụ thể.", "Phó mặc con cho người khác chăm sóc.", "Nuôi dưỡng, giáo dục và tạo điều kiện phát triển con.", "Không cần quan tâm đến học tập của con."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: Đề 9 đáp án.docx · Phần I câu 5 · khoá: gạch chân"}, {"id": "L12-8T2-09-C06", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Tình trạng hôn nhân được xác định từ thời điểm nào?", "o": ["Ngày gặp gỡ lần đầu.", "Ngày sinh con đầu lòng.", "Ngày đăng ký kết hôn.", "Ngày tổ chức lễ cưới."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: Đề 9 đáp án.docx · Phần I câu 6 · khoá: gạch chân"}, {"id": "L12-8T2-09-C07", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Bên được cấp dưỡng sau ly hôn có thể là", "o": ["người có thu nhập cao hơn bên kia trong mọi trường hợp, không cần căn cứ pháp luật.", "bất kỳ người nào đề nghị.", "bên đã gây lỗi trong hôn nhân.", "con chưa thành niên hoặc người không có khả năng lao động."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: Đề 9 đáp án.docx · Phần I câu 7 · khoá: gạch chân"}, {"id": "L12-8T2-09-C08", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Hôn nhân tiến bộ được xây dựng trên cơ sở nào?", "o": ["Tình yêu, sự tôn trọng và bình đẳng.", "Lợi ích kinh tế của hai gia đình mà không cần xem xét đến hoàn cảnh cụ thể.", "Sự sắp xếp của người lớn tuổi.", "Mong muốn có danh phận."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: Đề 9 đáp án.docx · Phần I câu 8 · khoá: gạch chân"}, {"id": "L12-8T2-09-C09", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Quyền học tập được pháp luật ghi nhận cho những đối tượng nào?", "o": ["Chỉ học sinh có thành tích xuất sắc mà không cần xem xét đến hoàn cảnh cụ thể.", "Mọi công dân, không phân biệt điều kiện.", "Chỉ học sinh trong thành phố.", "Chỉ người có hộ khẩu tại trường học."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: Đề 9 đáp án.docx · Phần I câu 9 · khoá: gạch chân"}, {"id": "L12-8T2-09-C10", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Nghĩa vụ đóng góp học phí của người học ở trường công lập được thực hiện theo", "o": ["mức do học sinh tự đặt.", "mức thu của trường tư thục.", "ý muốn của phụ huynh từng năm mà không cần xem xét đến hoàn cảnh cụ thể.", "quy định của pháp luật về miễn, giảm học phí."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: Đề 9 đáp án.docx · Phần I câu 10 · khoá: gạch chân"}, {"id": "L12-8T2-09-C11", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Hành vi nào sau đây thể hiện quyền học tập được bảo đảm?", "o": ["Học sinh bị từ chối tiếp nhận vì khác dân tộc.", "Học sinh bị đuổi học khi có hoàn cảnh khó khăn mà không cần xem xét đến hoàn cảnh cụ thể.", "Học sinh được học bổng và hỗ trợ học tập theo chính sách.", "Học sinh không được tham gia thi cử."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: Đề 9 đáp án.docx · Phần I câu 11 · khoá: gạch chân"}, {"id": "L12-8T2-09-C12", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Nhà trường có trách nhiệm gì đối với học sinh?", "o": ["Thu học phí vượt quy định.", "Bỏ qua các trường hợp học sinh gặp khó khăn trong mọi trường hợp, không cần căn cứ pháp luật.", "Không cần thông báo cho phụ huynh.", "Bảo đảm môi trường học tập an toàn, lành mạnh."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: Đề 9 đáp án.docx · Phần I câu 12 · khoá: gạch chân"}, {"id": "L12-8T2-09-C13", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Vệ sinh an toàn thực phẩm là trách nhiệm của", "o": ["chỉ người bán lẻ ở chợ.", "chỉ người nấu ăn tại gia đình trong mọi trường hợp, không cần căn cứ pháp luật.", "cơ sở sản xuất, kinh doanh và cả người tiêu dùng.", "chỉ cơ quan y tế."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: Đề 9 đáp án.docx · Phần I câu 13 · khoá: gạch chân"}, {"id": "L12-8T2-09-C14", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Công dân có nghĩa vụ gì khi mắc bệnh truyền nhiễm?", "o": ["Che giấu để không ảnh hưởng đến công việc trong mọi trường hợp, không cần căn cứ pháp luật.", "Khai báo, điều trị và thực hiện biện pháp phòng lây nhiễm.", "Không cần điều trị vì sẽ tự khỏi.", "Tự ý đi lại đông người."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: Đề 9 đáp án.docx · Phần I câu 14 · khoá: gạch chân"}, {"id": "L12-8T2-09-C15", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Nhà nước bảo đảm quyền chăm sóc sức khỏe cho trẻ em thông qua việc", "o": ["tạo điều kiện tiêm chủng và khám sức khỏe định kỳ.", "thu phí tiêm chủng cao nhất có thể.", "bắt trẻ tự đi làm để tự lo sức khỏe.", "không cần chăm sóc trẻ em khuyết tật mà không cần xem xét đến hoàn cảnh cụ thể."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: Đề 9 đáp án.docx · Phần I câu 15 · khoá: gạch chân"}, {"id": "L12-8T2-09-C16", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Mọi người có nghĩa vụ bảo vệ rừng và tài nguyên rừng, cụ thể là", "o": ["khai thác gỗ quý để buôn bán.", "săn bắt động vật rừng hiếm.", "không chặt phá rừng trái phép, tham gia trồng rừng.", "đốt rừng để làm nương rẫy tùy ý mà không cần xem xét đến hoàn cảnh cụ thể."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: Đề 9 đáp án.docx · Phần I câu 16 · khoá: gạch chân"}, {"id": "L12-8T2-09-C17", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Việc sử dụng túi nilon khó phân hủy gây ô nhiễm, để hạn chế công dân nên", "o": ["đốt trực tiếp ngoài môi trường trong mọi trường hợp, không cần căn cứ pháp luật.", "hạn chế sử dụng và mang túi tái sử dụng.", "vứt bừa bãi xuống sông hồ.", "tăng sử dụng để thuận tiện."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: Đề 9 đáp án.docx · Phần I câu 17 · khoá: gạch chân"}, {"id": "L12-8T2-09-C18", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Hoạt động bảo tồn đa dạng sinh học nhằm mục đích gì?", "o": ["Phá vỡ hệ sinh thái tự nhiên.", "Khai thác mọi loài sinh vật để kinh doanh trong mọi trường hợp, không cần căn cứ pháp luật.", "Duy trì sự đa dạng của sinh vật phục vụ phát triển bền vững.", "Tăng số lượng loài ngoại lai."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: Đề 9 đáp án.docx · Phần I câu 18 · khoá: gạch chân"}, {"id": "L12-8T2-09-C19", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Hội nhập kinh tế quốc tế đòi hỏi doanh nghiệp điều gì?", "o": ["Tránh cạnh tranh với đối tác nước ngoài trong mọi trường hợp, không cần căn cứ pháp luật.", "Không cần đổi mới công nghệ.", "Nâng cao chất lượng sản phẩm và tuân thủ tiêu chuẩn quốc tế.", "Chỉ bán hàng trong nước."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: Đề 9 đáp án.docx · Phần I câu 19 · khoá: gạch chân"}, {"id": "L12-8T2-09-C20", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đọc đoạn thông tin sau:\nVới mong muốn xây dựng thành công chuỗi cửa hành phân phối thực phẩm sạch trên địa bàn huyện X. Sau khi tham khảo một số mô hình cũng như kiến thức cơ bản về lĩnh vực kinh doanh này. Anh H đã lên kế hoạch chi tiết để thực hiện ý tưởng kinh doanh của mình. Qua tìm hiểu thực tế anh nhận thấy, đây là sản phẩm đang có nhu cầu lớn, nếu chất lượng đảm bảo thì hoàn toàn có thể chiếm lĩnh được lòng tin của người tiêu dùng. Đặc biệt, qua tư vấn của bạn bè, anh H đã dự liệu được những rủi ro, khó khăn tiềm ẩn để có giải pháp khắc phục. Trên cơ sở tìm hiểu và đánh giá này, anh H đã lên kế hoạch chi tiết việc bán hàng, tiếp thị, quảng cáo để quảng bá giới thiệu sản phẩn đến khách hàng. Sự cam kết của anh đối với việc cung cấp sản phẩm chất lượng cao và an toàn đã thu hút được người tiêu dùng. Chính các yếu tố này đã giúp anh H xây dựng thành công thương hiệu của mình trên địa bàn huyện X, anh dự định sẽ tiếp tục mở rộng các cửa hàng để hình thành chuỗi cửa hàng chất lượng cao.\nNội dung nào dưới không thể hiện việc phân tích các điều kiện thực h i ệ n ý t ư ở n g k i n h d o a n h ?", "o": ["Sản phẩm có nhu cầu lớn.", "Quảng cáo giới thiệu sản phẩm.", "Cam kết với người tiêu dùng.", "Mở rộng quy mô cửa hàng."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: Đề 9 đáp án.docx · Phần I câu 20 · khoá: gạch chân"}, {"id": "L12-8T2-09-C21", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đọc đoạn thông tin sau:\nVới mong muốn xây dựng thành công chuỗi cửa hành phân phối thực phẩm sạch trên địa bàn huyện X. Sau khi tham khảo một số mô hình cũng như kiến thức cơ bản về lĩnh vực kinh doanh này. Anh H đã lên kế hoạch chi tiết để thực hiện ý tưởng kinh doanh của mình. Qua tìm hiểu thực tế anh nhận thấy, đây là sản phẩm đang có nhu cầu lớn, nếu chất lượng đảm bảo thì hoàn toàn có thể chiếm lĩnh được lòng tin của người tiêu dùng. Đặc biệt, qua tư vấn của bạn bè, anh H đã dự liệu được những rủi ro, khó khăn tiềm ẩn để có giải pháp khắc phục. Trên cơ sở tìm hiểu và đánh giá này, anh H đã lên kế hoạch chi tiết việc bán hàng, tiếp thị, quảng cáo để quảng bá giới thiệu sản phẩn đến khách hàng. Sự cam kết của anh đối với việc cung cấp sản phẩm chất lượng cao và an toàn đã thu hút được người tiêu dùng. Chính các yếu tố này đã giúp anh H xây dựng thành công thương hiệu của mình trên địa bàn huyện X, anh dự định sẽ tiếp tục mở rộng các cửa hàng để hình thành chuỗi cửa hàng chất lượng cao.\nAnh H đã xác định mục tiêu kinh doanh của mình đó l�", "o": ["xây dựng chuỗi thực phẩm sạch.", "sản phẩm đang có nhu cầu lớn.", "quảng cáo giới thiệu sản phẩm.", "tiếp cận nhu cầu người tiêu dùng."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: Đề 9 đáp án.docx · Phần I câu 21 · khoá: gạch chân"}, {"id": "L12-8T2-09-C22", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đọc đoạn thông tin sau:\nVới niềm yêu thích tìm hiểu và khám phá ngành công nghiệp ô tô, ngay từ khi còn là sinh viên, ông M đã ấp ủ ý tưởng về việc lắp ráp và kinh doanh ôtô với mục tiêu sẽ đưa ra thị trường những chiếc ô tô mang thương hiệu Việt Nam. Khởi nghiệp từ một sinh viên tốt nghiệp đại học ngành chế tạo ô tô, ban đầu ông M làm việc cho một nhà máy sửa chữa ô tô. Sau 5 năm làm quen với công việc, chịu khó học hỏi, ông quyết định thành lập cơ sở sửa chữa ô tô, xe máy, sau này phát triển thành công ty chuyên lắp ráp v� kinh doanh ô tô bởi ông nhận thấy thị trường ô tô ở Việt Nam chưa có thương hiệu trong nước trong khi nhu cầu của người dân rất cao, nhà nước có nhiều chính sách ưu đãi để phát triển. Để công ty hoạt động có hiệu quả, ông luôn chủ động, sáng tạo, nắm bắt cơ hội, vạch ra chiến lược kinh doanh; tự trang bị cho mình những kiến thức, kĩ năng quản trị doanh nghiệp, xây dựng hệ thống quản lí nội bộ công ty chuyên nghiệp, tạo dựng được mối quan hệ rộng rãi với các đối tác, khách hàng và xây dựng được văn hoá công ty. Nhờ kiến thức và niềm đam mê chỉ sau 10 năm thương hiệu tô tô do ông M xây dựng đã dần hình thành và từng bước có chỗ đứng trên thị trường Việt Nam\nNội dung nào dưới đây thể hiện việc ông M đã biết xác định mục tiêu k i n h d o a n h c ủ a m ì n h ?", "o": ["Xây dựng thương hiệu ô tô Việt.", "Nắm bắt cơ hội để kinh doanh.", "Trang bị kiến thức cơ bản.", "Vận dụng chính sách nhà nước trong mọi trường hợp, không cần căn cứ pháp luật."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: Đề 9 đáp án.docx · Phần I câu 22 · khoá: gạch chân"}, {"id": "L12-8T2-09-C23", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đọc đoạn thông tin sau:\nVới niềm yêu thích tìm hiểu và khám phá ngành công nghiệp ô tô, ngay từ khi còn là sinh viên, ông M đã ấp ủ ý tưởng về việc lắp ráp và kinh doanh ôtô với mục tiêu sẽ đưa ra thị trường những chiếc ô tô mang thương hiệu Việt Nam. Khởi nghiệp từ một sinh viên tốt nghiệp đại học ngành chế tạo ô tô, ban đầu ông M làm việc cho một nhà máy sửa chữa ô tô. Sau 5 năm làm quen với công việc, chịu khó học hỏi, ông quyết định thành lập cơ sở sửa chữa ô tô, xe máy, sau này phát triển thành công ty chuyên lắp ráp v� kinh doanh ô tô bởi ông nhận thấy thị trường ô tô ở Việt Nam chưa có thương hiệu trong nước trong khi nhu cầu của người dân rất cao, nhà nước có nhiều chính sách ưu đãi để phát triển. Để công ty hoạt động có hiệu quả, ông luôn chủ động, sáng tạo, nắm bắt cơ hội, vạch ra chiến lược kinh doanh; tự trang bị cho mình những kiến thức, kĩ năng quản trị doanh nghiệp, xây dựng hệ thống quản lí nội bộ công ty chuyên nghiệp, tạo dựng được mối quan hệ rộng rãi với các đối tác, khách hàng và xây dựng được văn hoá công ty. Nhờ kiến thức và niềm đam mê chỉ sau 10 năm thương hiệu tô tô do ông M xây dựng đã dần hình thành và từng bước có chỗ đứng trên thị trường Việt Nam\nNội dung nào dưới đây thể hiện việc ông M đã biết xác định ý tưởng k i n h d o a n h ?", "o": ["Khám phá ngành công nghiệp ô tô mà không cần xem xét đến hoàn cảnh cụ thể.", "Lắp ráp và kinh doanh ô tô Việt.", "Tạo dựng hiệu hiệu ô tô Việt.", "Tham gia sửa chữa ô tô, xe máy."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: Đề 9 đáp án.docx · Phần I câu 23 · khoá: gạch chân"}, {"id": "L12-8T2-09-C24", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đọc đoạn thông tin sau:\nVới niềm yêu thích tìm hiểu và khám phá ngành công nghiệp ô tô, ngay từ khi còn là sinh viên, ông M đã ấp ủ ý tưởng về việc lắp ráp và kinh doanh ôtô với mục tiêu sẽ đưa ra thị trường những chiếc ô tô mang thương hiệu Việt Nam. Khởi nghiệp từ một sinh viên tốt nghiệp đại học ngành chế tạo ô tô, ban đầu ông M làm việc cho một nhà máy sửa chữa ô tô. Sau 5 năm làm quen với công việc, chịu khó học hỏi, ông quyết định thành lập cơ sở sửa chữa ô tô, xe máy, sau này phát triển thành công ty chuyên lắp ráp v� kinh doanh ô tô bởi ông nhận thấy thị trường ô tô ở Việt Nam chưa có thương hiệu trong nước trong khi nhu cầu của người dân rất cao, nhà nước có nhiều chính sách ưu đãi để phát triển. Để công ty hoạt động có hiệu quả, ông luôn chủ động, sáng tạo, nắm bắt cơ hội, vạch ra chiến lược kinh doanh; tự trang bị cho mình những kiến thức, kĩ năng quản trị doanh nghiệp, xây dựng hệ thống quản lí nội bộ công ty chuyên nghiệp, tạo dựng được mối quan hệ rộng rãi với các đối tác, khách hàng và xây dựng được văn hoá công ty. Nhờ kiến thức và niềm đam mê chỉ sau 10 năm thương hiệu tô tô do ông M xây dựng đã dần hình thành và từng bước có chỗ đứng trên thị trường Việt Nam\nViệc làm nào dưới đây thể hiện ông M đã biết phân tích các điều k i ệ n t h ự c h i ệ n ý t ư ở n g k i n h d o a n h ?", "o": ["Lắp ráp và kinh doanh ô tô Việt.", "Nhận thấy nhu cầu trong nước cao.", "Xây dựng thương hiệu ô tô Việt.", "Tạo dựng mối quan hệ rộng rãi."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: Đề 9 đáp án.docx · Phần I câu 24 · khoá: gạch chân"}, {"id": "L12-8T2-09-C25", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "dung_sai", "status": "cho_duyet", "q": "Đọc đoạn thông tin sau và cho biết mỗi ý a, b, c, d là Đúng hay Sai. Được nuông chiều từ bé nên B có tính tình kiêu căng. Khi bước vào bậc THPT, B hầu như không tương tác hoặc chơi cùng với các bạn. Nhiều lần B có thái độ không tôn trọng thầy cô giáo. Cho rằng gia đình mình có điều kiện nên khi sử dụng các trang thiết bị của lớp học, B thường không chú ý giữ gìn, bảo quản. Khi được giáo viên nhắc nhở, B thường tỏ ra không quan tâm v� tuyên bố rằng bố mẹ sẽ bồi thường cho bất kì tổn thất nào gây ra cho trường học. Cuối năm học, B không đủ điều kiện xếp loại lên lớp và bị lưu ban. Xét thấy gia đình đủ điều kiện để lo cho cuộc sống của B sau này, bố mẹ B đã làm đơn cho B thôi học.", "o": ["Bố mẹ B chưa thực hiện tốt trách nhiệm của cha mẹ đối với con trong hôn nhân và gia đình.", "Hành vi không tôn trọng thầy cô giáo là vi phạm nghĩa vụ của công dân trong học tập.", "Việc làm đơn cho B thôi học của bố mẹ bạn B là vi phạm nghĩa vụ của công dân trong học tập.", "Bạn B bị lưu ban lại lớp là hậu quả của hành vi vi phạm quyền và nghĩa vụ của công dân trong học tập của bố mẹ bạn B."], "a": [true, true, true, false], "e": "Đáp án: a) Đúng; b) Đúng; c) Đúng; d) Sai.", "nguon": "Đề nguồn: Đề 9 đáp án.docx · Phần II câu 1 · khoá: chữ Đúng/Sai trong ý"}, {"id": "L12-8T2-09-C26", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "dung_sai", "status": "cho_duyet", "q": "Đọc đoạn thông tin sau và cho biết mỗi ý a, b, c, d là Đúng hay Sai. Khi bị ngất xỉu, chị P đã được gia đình đưa vào bệnh viện để khám bệnh. Trong quá trình trao đổi với bác sĩ M, chị P đã không kể chi tiết về những biểu hiện của cơ thể để không phải nhập viện. Nhưng với kinh nghiệm chuyên môn và qua khám ban đầu, bác sĩ M đã yêu cầu chị P đi chụp chiếu và làm một số xét nghiệm để xác định rõ tình trạng bệnh tim. Nhưng chị P lại không đồng ý với lí do sức khoẻ của minh vẫn tốt và yêu cầu người nhà đưa chị về.", "o": ["Chị P che giấu tình trạng sức khỏe của bản thân là phù hợp với quyền của công dân trong khám chữa bệnh.", "Việc yêu cầu chị P đi chụp chiếu và làm xét nghiệm là không cần thiết.", "Chị P và bác sĩ M đều chưa thực hiện đúng nghĩa vụ của công dân trong bảo vệ và chăm sóc sức khỏe.", "Bác sĩ M thực hiện đúng các quy định của pháp luật về bảo vệ và chăm sóc sức khỏe công dân."], "a": [false, false, false, true], "e": "Đáp án: a) Sai; b) Sai; c) Sai; d) Đúng.", "nguon": "Đề nguồn: Đề 9 đáp án.docx · Phần II câu 2 · khoá: chữ Đúng/Sai trong ý"}, {"id": "L12-8T2-09-C27", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "dung_sai", "status": "cho_duyet", "q": "Đọc đoạn thông tin sau và cho biết mỗi ý a, b, c, d là Đúng hay Sai. Sau khi kết thúc 2 tháng thử việc, ông V liên tục đưa ra nhiều lí do khác nhau để trì hoãn việc kí hợp đồng và đóng bảo hiểm y tế, bảo hiểm xã hội cho người lao động theo quy định của pháp luật. Đồng thời, ông V cũng không đầu tư trang bị bảo hộ lao động cho các công nhân làm việc trong xưởng sản xuất để đảm bảo an toàn và sức khoẻ cho họ.", "o": ["Ông V vừa vi phạm quyền và nghĩa vụ của công dân trong bảo vệ, chăm sóc sức khỏe và đảm bảo an sinh xã hội.", "Người lao động trong công ty của ông V có quyền khiếu nại tới cơ quan chức năng để yêu cầu ông V bồi thường thiệt hại.", "Ông V chuyển trực tiếp số tiền phải đóng bảo hiểm xã hội cho người lao động cho người lao động tự đóng là phù hợp với quy định của pháp luật.", "Ông V chưa thực hiện đúng trách nhiệm pháp lý và trách nhiệm từ thiện của doanh nghiệp."], "a": [true, false, false, false], "e": "Đáp án: a) Đúng; b) Sai; c) Sai; d) Sai.", "nguon": "Đề nguồn: Đề 9 đáp án.docx · Phần II câu 3 · khoá: chữ Đúng/Sai trong ý"}, {"id": "L12-8T2-09-C28", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "dung_sai", "status": "cho_duyet", "q": "Đọc đoạn thông tin sau và cho biết mỗi ý a, b, c, d là Đúng hay Sai. Vừa qua, trên địa bàn xã A thuộc huyện K xảy ra lũ ống, lũ quét gây ảnh hưởng nghiêm trọng đến sức khoẻ và tài sản của người dân nên chính quyền huyện K đã quyết định trích một phần ngân sách để hỗ trợ cho người dân khắc phục khó khăn, ổn định lại cuộc sống, số tiền hỗ trợ sẽ được phân bổ theo mức độ thiệt hại của từng hộ gia đình. Khi kê khai thiệt hại về tài sản, gia đình bà M đã cố tình kê khai mức thiệt hại lớn hơn so với thực tế để trục lợi. Việc làm của gia đình bà M bị ông H (cán bộ xã A) phát hiện nhưng do có mối quan hệ họ hàng với bà M nên ông H im lặng bỏ qua.", "o": ["Quyết định trích ngân sách để hỗ trợ các gia đình bị thiệt hại của xã A là góp phần thực hiện quyền được đảm bảo an sinh xã hội của người dân.", "Bà M đã được thực hiện quyền của công dân trong việc đảm bảo an sinh xã hội.", "Ông H và bà M đều chưa thực hiện đúng nghĩa vụ của công dân trong việc đảm bảo an sinh xã hội.", "Việc làm của ông H và bà M gây ra hậu quả mất công bằng trong việc thực hiện chính sách an sinh xã hội của nhà nước."], "a": [true, true, true, true], "e": "Đáp án: a) Đúng; b) Đúng; c) Đúng; d) Đúng.", "nguon": "Đề nguồn: Đề 9 đáp án.docx · Phần II câu 4 · khoá: chữ Đúng/Sai trong ý"}]}, {"id": "L12-8T2-10", "loai": "khoi", "khoi": 12, "hoc_ki": 2, "bo": "8T2", "ten_bo": "8 tuần học kì II", "so_de": 10, "ten": "Lớp 12 · 8 tuần học kì II · Đề 10", "pham_vi": "Đề nguồn «8 TUẦN KÌ 2 › BO_DE_MOI» · file nguồn: Đề 10 đáp án.docx", "thoi_gian": 50, "cau_truc": "24 câu trắc nghiệm + 4 câu đúng/sai (mỗi câu 4 ý)", "status": "cho_duyet", "khoa": {"1 nguồn": 28}, "sua": "", "cau": [{"id": "L12-8T2-10-C01", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Tự do kết hôn, ly hôn và quyền lựa chọn bạn đời là", "o": ["biểu hiện của tư tưởng gia trưởng.", "biểu hiện của sự ràng buộc kinh tế.", "biểu hiện của hôn nhân tiến bộ.", "biểu hiện của phong tục lạc hậu."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: Đề 10 đáp án.docx · Phần I câu 1 · khoá: gạch chân"}, {"id": "L12-8T2-10-C02", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Pháp luật cấm hành vi nào sau đây đối với vợ, chồng?", "o": ["Ngược đãi, hành hạ, xúc phạm danh dự nhau.", "Bàn bạc quyết định chung về gia đình trong mọi trường hợp, không cần căn cứ pháp luật.", "Chia sẻ việc nhà với nhau.", "Hỗ trợ nhau trong công việc."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: Đề 10 đáp án.docx · Phần I câu 2 · khoá: gạch chân"}, {"id": "L12-8T2-10-C03", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Quyền sở hữu tài sản riêng của vợ, chồng được pháp luật bảo vệ, nghĩa là", "o": ["người có tài sản riêng có quyền định đoạt theo quy định.", "tài sản riêng bị chia đều khi kết hôn mà không cần xem xét đến hoàn cảnh cụ thể.", "không ai được biết về tài sản riêng.", "tài sản riêng phải được đem chung."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: Đề 10 đáp án.docx · Phần I câu 3 · khoá: gạch chân"}, {"id": "L12-8T2-10-C04", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Khi vợ chồng sống ly thân, việc nuôi con được giải quyết theo", "o": ["thỏa thuận hoặc quyết định của Tòa án bảo đảm quyền lợi của con.", "quy định của người tổ chức lễ cưới.", "quyết định đơn phương của người có thu nhập cao mà không cần xem xét đến hoàn cảnh cụ thể.", "ý kiến của người lớn tuổi trong họ."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: Đề 10 đáp án.docx · Phần I câu 4 · khoá: gạch chân"}, {"id": "L12-8T2-10-C05", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Trong gia đình, mỗi thành viên có nghĩa vụ gì đối với nhau?", "o": ["Tôn trọng, yêu thương, giúp đỡ lẫn nhau.", "Sống độc lập, không liên hệ với nhau.", "Quản lý tài sản của người khác khi không được phép.", "Không cần chia sẻ trách nhiệm chăm sóc."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: Đề 10 đáp án.docx · Phần I câu 5 · khoá: gạch chân"}, {"id": "L12-8T2-10-C06", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Cha mẹ không được có hành vi nào đối với con?", "o": ["Lạm dụng sức lao động của con chưa thành niên.", "Giáo dục con về đạo đức và pháp luật trong mọi trường hợp, không cần căn cứ pháp luật.", "Tạo điều kiện cho con học tập.", "Lắng nghe ý kiến của con."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: Đề 10 đáp án.docx · Phần I câu 6 · khoá: gạch chân"}, {"id": "L12-8T2-10-C07", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Thủ tục ly hôn thuận tình được thực hiện khi", "o": ["không có sự đồng ý của một trong hai bên.", "chưa đăng ký kết hôn.", "một bên không đồng ý và đòi bồi thường lớn trong mọi trường hợp, không cần căn cứ pháp luật.", "hai bên tự nguyện, thỏa thuận được về con và tài sản."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: Đề 10 đáp án.docx · Phần I câu 7 · khoá: gạch chân"}, {"id": "L12-8T2-10-C08", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Vợ chồng có nghĩa vụ gì trong việc sinh con và kế hoạch hóa gia đình?", "o": ["Bắt buộc phải có con trai để nối dõi.", "Sinh con không giới hạn và không cần chuẩn bị trong mọi trường hợp, không cần căn cứ pháp luật.", "Không cần quan tâm đến sức khỏe sinh sản.", "Thực hiện kế hoạch hóa gia đình theo quy định của pháp luật."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: Đề 10 đáp án.docx · Phần I câu 8 · khoá: gạch chân"}, {"id": "L12-8T2-10-C09", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Mục tiêu của chính sách phổ cập giáo dục là", "o": ["chỉ đào tạo người giỏi nhất cho xã hội.", "giảm chi phí giáo dục của Nhà nước.", "phân loại học sinh theo khả năng tài chính mà không cần xem xét đến hoàn cảnh cụ thể.", "bảo đảm mọi người dân có cơ hội học tập nền tảng."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: Đề 10 đáp án.docx · Phần I câu 9 · khoá: gạch chân"}, {"id": "L12-8T2-10-C10", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Học sinh vi phạm nội quy nhà trường có thể bị", "o": ["không bị ghi nhận gì trong hồ sơ.", "đuổi học ngay lập tức không cần lý do mà không cần xem xét đến hoàn cảnh cụ thể.", "nhắc nhở, kỷ luật theo quy định của nhà trường.", "miễn mọi trách nhiệm học tập."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: Đề 10 đáp án.docx · Phần I câu 10 · khoá: gạch chân"}, {"id": "L12-8T2-10-C11", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Học sinh có quyền được tôn trọng nhân phẩm và được đối xử công bằng, điều này thể hiện là", "o": ["quyền cơ bản của người học.", "trách nhiệm của phụ huynh.", "đặc quyền chỉ dành cho học sinh giỏi.", "nghĩa vụ đối với giáo viên."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: Đề 10 đáp án.docx · Phần I câu 11 · khoá: gạch chân"}, {"id": "L12-8T2-10-C12", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Hành vi nào sau đây thể hiện nghĩa vụ học tập của công dân?", "o": ["Đi học đúng độ tuổi và tham gia học tập đầy đủ.", "Không tham gia kiểm tra theo quy định.", "Chỉ học khi có điểm thưởng.", "Bỏ học để đi làm kiếm tiền khi có cơ hội trong mọi trường hợp, không cần căn cứ pháp luật."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: Đề 10 đáp án.docx · Phần I câu 12 · khoá: gạch chân"}, {"id": "L12-8T2-10-C13", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Pháp luật về an sinh xã hội nhằm", "o": ["tạo gánh nặng cho người có thu nhập thấp.", "bảo đảm thu nhập và đời sống cho người dân khi gặp rủi ro.", "phân biệt đối xử giữa các nhóm người.", "thay thế hoàn toàn trách nhiệm của cá nhân mà không cần xem xét đến hoàn cảnh cụ thể."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: Đề 10 đáp án.docx · Phần I câu 13 · khoá: gạch chân"}, {"id": "L12-8T2-10-C14", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Công dân có quyền được hỗ trợ khám chữa bệnh khi thuộc đối tượng", "o": ["đã có bảo hiểm thương mại cao cấp.", "có thu nhập cao nhất trong vùng.", "không thuộc đối tượng nào trong chính sách trong mọi trường hợp, không cần căn cứ pháp luật.", "hộ nghèo, người có công và trẻ em dưới 6 tuổi theo quy định."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: Đề 10 đáp án.docx · Phần I câu 14 · khoá: gạch chân"}, {"id": "L12-8T2-10-C15", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Hành vi nào sau đây thể hiện trách nhiệm đảm bảo an toàn giao thông, bảo vệ sức khỏe?", "o": ["Uống rượu bia rồi điều khiển phương tiện.", "Chạy xe vượt đèn đỏ để tiết kiệm thời gian mà không cần xem xét đến hoàn cảnh cụ thể.", "Đi xe không có giấy tờ hợp lệ.", "Đội mũ bảo hiểm và chấp hành luật giao thông."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: Đề 10 đáp án.docx · Phần I câu 15 · khoá: gạch chân"}, {"id": "L12-8T2-10-C16", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Người lao động có quyền gì về an toàn lao động?", "o": ["Được làm việc không cần trang bị bảo hộ.", "Được bỏ qua quy trình an toàn để tăng năng suất trong mọi trường hợp, không cần căn cứ pháp luật.", "Được làm việc trong điều kiện bảo đảm an toàn, vệ sinh lao động.", "Được làm thêm giờ vô hạn độ."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: Đề 10 đáp án.docx · Phần I câu 16 · khoá: gạch chân"}, {"id": "L12-8T2-10-C17", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Bảo vệ di tích lịch sử – văn hóa thể hiện trách nhiệm của công dân trong việc", "o": ["xây dựng công trình che khuất di tích trong mọi trường hợp, không cần căn cứ pháp luật.", "bán các hiện vật để lấy tiền.", "dời đổi vị trí di tích theo ý thích.", "giữ gìn, không xâm hại và tham gia phát huy giá trị."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: Đề 10 đáp án.docx · Phần I câu 17 · khoá: gạch chân"}, {"id": "L12-8T2-10-C18", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Việc khai thác khoáng sản phải thực hiện theo", "o": ["ý thích của người khai thác.", "thỏa thuận riêng với người dân địa phương trong mọi trường hợp, không cần căn cứ pháp luật.", "giấy phép và quy định về bảo vệ môi trường.", "không cần thông báo cho cơ quan quản lý."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: Đề 10 đáp án.docx · Phần I câu 18 · khoá: gạch chân"}, {"id": "L12-8T2-10-C19", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Công dân có quyền làm gì khi phát hiện hành vi gây ô nhiễm môi trường?", "o": ["Đăng thông tin sai sự thật lên mạng trong mọi trường hợp, không cần căn cứ pháp luật.", "Tự ý dùng vũ lực với người vi phạm.", "Im lặng để tránh rắc rối.", "Phản ánh, tố cáo đến cơ quan có thẩm quyền."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: Đề 10 đáp án.docx · Phần I câu 19 · khoá: gạch chân"}, {"id": "L12-8T2-10-C20", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đọc đoạn thông tin sau:\nCông ty V chuyên sản xuất kinh doanh các sản phẩm sữa, thường xuyên cải tiến mẫu mã, đảm bảo chất lượng sản phẩm cung cấp ra thị trường, kê khai v� nộp thuế đầy đủ. Doanh nghiệp đã tham gia chương trình sữa học đường, mang sữa đến các trường mầm non, tiểu học tại nhiều địa phương, phát động cán bộ nhân viên quyên góp, giúp đỡ người dân vùng bị thiên tai vượt qua khó khăn và khắc phục hậu quả sau bão lũ,...\nNội dung nào dưới đây phản ánh việc thực hiện trách nhiệm pháp lý c ủ a c ô n g t y V ?", "o": ["Kê khai và nộp thuế đầy đủ.", "Tham gia dự án sữa miễn phí.", "Đảm bảo chất lượng sản phẩm.", "Cải tiễn mẫu mã sản phẩm."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: Đề 10 đáp án.docx · Phần I câu 20 · khoá: gạch chân"}, {"id": "L12-8T2-10-C21", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đọc đoạn thông tin sau:\nCông ty V chuyên sản xuất kinh doanh các sản phẩm sữa, thường xuyên cải tiến mẫu mã, đảm bảo chất lượng sản phẩm cung cấp ra thị trường, kê khai v� nộp thuế đầy đủ. Doanh nghiệp đã tham gia chương trình sữa học đường, mang sữa đến các trường mầm non, tiểu học tại nhiều địa phương, phát động cán bộ nhân viên quyên góp, giúp đỡ người dân vùng bị thiên tai vượt qua khó khăn và khắc phục hậu quả sau bão lũ,...\nHoạt động tham gia chương trình sữa học đường, mang sữa đến các t r ư ờ n g m ầ m n o n , t i ể u h ọ c t ạ i n h i ề u đ ị a p h ư ơ n g l à t h ể h i ệ n t r á c h n h i ệ m n à o d ư ớ i đ â y c ủ a c ô n g t y ?", "o": ["Trách nhiệm kinh tế.", "Trách nhiệm pháp lý trong mọi trường hợp, không cần căn cứ pháp luật.", "Trách nhiệm nhân văn.", "Trách nhiệm đạo đức."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: Đề 10 đáp án.docx · Phần I câu 21 · khoá: gạch chân"}, {"id": "L12-8T2-10-C22", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đọc đoạn thông tin sau:\nLà một doanh nghiệp nhỏ ngành dệt may ở một xã thuần nông, doanh nghiệp V đã cung ứng cho thị trường nhiều sản phẩm có chất lượng cao, thân thiện với môi trường. Công ty đã thu hút được những lao động là thanh niên trong xã, đào tạo họ trở thành những người thợ lành nghề, có việc làm và thu nhập ổn định. Hằng năm, doanh nghiệp còn hỗ trợ kinh phí cho học sinh có hoàn cảnh đặc biệt khó khăn trong xã được đi học đại học, tham gia nhiều hoạt động cộng đồng trong xã. Bên cạnh đó công ty rất quan tâm đến đời sống người lao động, ngoài việc thực hiện tốt các chế độ theo quy định, công ty còn chủ động tìm các nguồn kinh phí hợp pháp để hỗ trợ người lao động gặp khó khăn ổn định cuộc sống. Nhờ vậy, uy tín của doanh nghiệp đối với khách hàng, người lao động và xã hội ngày càng tăng, công việc kinh doanh ngày càng phát triển. Năm qua doanh nghiệp được cơ quan thuế tặng bằng khen vì thành tích thực hiện tốt nghĩa vụ nộp thuế trên địa bàn.\nViệc hỗ trợ kinh phí cho học sinh có hoàn cảnh đặc biệt khó khăn t r o n g x ã đ ư ợ c đ i h ọ c đ ạ i h ọ c v à t h a m g i a c á c h o ạ t đ ộ n g c ộ n g đ ồ n g t r o n g x ã l à t h ể h i ệ n t r á c h n h i ệ m x ã h ộ i n à o d ư ớ i đ â y c ủ a d o a n h n g h i ệ p ?", "o": ["Trách nhiệm nhân văn.", "Trách nhiệm pháp lý.", "Trách nhiệm kinh tế.", "Trách nhiệm địa phương."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: Đề 10 đáp án.docx · Phần I câu 22 · khoá: gạch chân"}, {"id": "L12-8T2-10-C23", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đọc đoạn thông tin sau:\nLà doanh nghiệp chuyên kinh doanh các mặt hàng thực phẩm, Công ty A đặc biệt lưu ý đến việc kiểm soát chất lượng đầu vào, luôn chọn những nh� cung cấp tuân thủ đúng các quy định của Nhà nước về hồ sơ pháp lí; ưu tiên chọn nhà cung cấp có chứng nhận VietGAP, chuỗi thực phẩm an toàn, chứng nhận hữu cơ, hàng Việt Nam chất lượng cao,... Ngoài ra, công ty còn định kì khảo sát, đánh giá trực tiếp điều kiện cơ sở vật chất, trang thiết bị nh� xưởng cũng như rà soát quá trình tiếp nhận, phân loại, sơ chế, sản xuất, đóng gói của nhà cung cấp. Vì vậy, sản phẩm của công ty ngày càng được nhiều khách hàng tin tưởng, ưa chuộng, doanh thu ngày càng tăng.\nViệc công ty A chú trọng lựa chọn những nhà cung cấp tuân thủ đ ú n g c á c q u y đ ị n h c ủ a N h à n ư ớ c v ề h ồ s ơ p h á p l í l à t h ể h i ệ n t r á c h n h i ệ m x ã h ộ i n à o d ư ớ i đ â y c ủ a d o a n h n g h i ệ p ?", "o": ["Trách nhiệm pháp lý.", "Trách nhiệm kinh tế.", "Trách nhiệm đạo đức trong mọi trường hợp, không cần căn cứ pháp luật.", "Trách nhiệm công vụ."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: Đề 10 đáp án.docx · Phần I câu 23 · khoá: gạch chân"}, {"id": "L12-8T2-10-C24", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đọc đoạn thông tin sau:\nSau khi cưới nhau, anh D và chị H dự định sau 3 năm sẽ mua nhà và ra ở riêng. Vợ chồng anh chị đồng thuận thực hiện kế hoạch quản lí thu, chi bằng số theo dõi hằng tháng sau khi bàn bạc thống nhất. Theo đó, vợ chồng chị sẽ dành 50% tổng thu nhập cho chi tiêu thiết yếu, sinh hoạt hằng ngày; 20% dành cho các khoản dự phòng, tiết kiệm, mua nhà,... và 30% còn lại dành cho các hoạt động giải trí, giao tiếp xã hội,...Sau năm đầu thực hiện, do có tố phát sinh đó là có con nhỏ nên anh chị buộc phải giảm số tiền cho các hoạt động giải trí để tăng cho các sinh hoạt thiết yếu, đặc biệt số tiền giảm này chị đã tham gia một gói bảo hiểm an sinh cho con mình đề phòng lúc ốm đau, mặc dù biết là nhiều mối quan hệ xã hội bị cắt giảm nhưng anh chị vẫn cảm thấy vui và tự tin về mục tiêu tài chính của mình sẽ đạt được/\nNội dung nào dưới đây thể hiện việc xác định mục tiêu tài chính t r o n g g i a đ ì n h ?", "o": ["Mua nhà và ra ở riêng sau 3 năm.", "Mua bảo hiểm an sinh cho con mà không cần xem xét đến hoàn cảnh cụ thể.", "Xây dựng sổ theo dõi thu chi.", "Tham gia hoạt động giải trí."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: Đề 10 đáp án.docx · Phần I câu 24 · khoá: gạch chân"}, {"id": "L12-8T2-10-C25", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "dung_sai", "status": "cho_duyet", "q": "Đọc đoạn thông tin sau và cho biết mỗi ý a, b, c, d là Đúng hay Sai. Các di sản văn hoá đã được đặt dưới sự bảo hộ của Luật Di sản văn hoá v� các công ước của UNESCO mà Việt Nam đã tham gia. Trong số gần 4 triệu hiện vật đang lưu giữ trong các bảo tàng công lập, bảo tàng ngoài công lập v� các bộ , tập tư nhân có 238 hiện vật và nhóm hiện vật được Thủ tướng Chính phủ công nhận là bảo vật quốc gia. Từ năm 2015 – 2022, đã có 131 nghệ nhân được phong tặng danh hiệu Nghệ nhân nhân dân và 1 507 nghệ nhân được phong tặng danh hiệu Nghệ nhân ưu tú. Luật Di sản văn hoá cho phép tư nhân/chủ sở hữu sưu tập hiện vật xây dựng bảo tàng ngoài công lập, tư nhân hiến tặng cổ vật cho các bảo tàng công lập. Nhà nước đã đầu tư những khoản ngân sách khá lớn cho mục tiêu bảo tồn di sản văn hoá. Ngoài ra, phải kể tới hàng nghìn tỉ đồng được huy động từ sự tự nguyện đóng góp của cộng đồng cư dân các địa phương cũng như vốn hỗ trợ từ UNESCO.", "o": ["Quyền của công dân về bảo vệ di sản văn hoá thể hiện ở việc 238 hiện vật và nhóm hiện vật được Thủ tướng Chính phủ công nhận là bảo vật quốc gia.", "Việc phong tặng danh hiệu Nghệ nhân nhân dân và danh hiệu Nghệ nhân ưu tủ nằm ngoài lĩnh vực về bảo vệ di sản văn hoá.", "Pháp luật cho phép tư nhân sưu tập hiện vật xây dựng bảo tàng ngoài công lập là để tạo cơ hội cho người dân được tiếp cận và hưởng thụ các giá trị di sản văn hoá.", "Pháp luật quy định cộng đồng cư dân các địa phương có nghĩa vụ tự nguyện đóng góp hàng nghìn tỉ đồng cho mục tiêu bảo tồn di sản văn hoá."], "a": [false, false, true, false], "e": "Đáp án: a) Sai; b) Sai; c) Đúng; d) Sai.", "nguon": "Đề nguồn: Đề 10 đáp án.docx · Phần II câu 1 · khoá: chữ Đúng/Sai trong ý"}, {"id": "L12-8T2-10-C26", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "dung_sai", "status": "cho_duyet", "q": "Đọc đoạn thông tin sau và cho biết mỗi ý a, b, c, d là Đúng hay Sai. Năm 2021, Chùa Đậu – di tích lịch sử được mệnh danh là “Danh lam đệ nhất. trời Nam\" bỗng nhiên bị làm mới. Công trình hàng nghìn năm tuổi với nhiều hạng mục được xây thêm, làm mới khiến nhiều người chua xót: Chùa Đậu giờ chỉ còn 1 năm tuổi, nhưng có người lại cho rằng, chỉ vài năm nữa, rêu xanh sẽ mọc lên vì các hạng mục được xây mới, sửa chữa sẽ lại nhuốm màu cổ kính như xưa. Cả chuyện của Chùa Đậu được làm mới vốn không mới, nhưng lại xảy ra thưởng xuyên tại hầu hết các địa phương trong cả nước.", "o": ["Với việc làm mới, Chùa Đậu chỉ mất đi vẻ cổ kính, nhưng thực tế vẫn được lịch sử hàng nghìn năm.", "Công dân thực hiện quyền và nghĩa vụ bảo vệ di sản văn hoá bằng cách tranh cãi về việc nên/không nên làm mới các di tích lịch sử.", "Nhiều hạng mục được xây thêm và làm mới khiến Chùa Đậu mất đi vẻ cổ kinh là dấu hiệu công dân lạm dụng quyền về bảo vệ di sản văn hoá.", "Xử lí hành vi làm mới ở di tích lịch sử Chùa Đậu sẽ ngăn chặn được hiện tượng này ở hầu hết các địa phương khác."], "a": [false, false, true, true], "e": "Đáp án: a) Sai; b) Sai; c) Đúng; d) Đúng.", "nguon": "Đề nguồn: Đề 10 đáp án.docx · Phần II câu 2 · khoá: chữ Đúng/Sai trong ý"}, {"id": "L12-8T2-10-C27", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "dung_sai", "status": "cho_duyet", "q": "Đọc đoạn thông tin sau và cho biết mỗi ý a, b, c, d là Đúng hay Sai. Tổ liên ngành an ninh của Trung tâm Bảo tồn di tích Cố đô Huế trong quá trình tuần tra đã phát hiện một nhóm học sinh leo qua gác chắn đi vào khu vực kì đài nên đã đề nghị nhóm học sinh ra khỏi khu vực di tích. Sau đó, phát hiện một số bóng đèn LED chiếu sáng tại đây đã bị đập vỡ, mảnh kính từ bóng đèn nằm vương vãi trên mặt nền di tích. Thông qua hệ thống giám sát của trung tâm, lực lượng bảo vệ xác định đây là hành vi phá hoại tài sản của nhóm học sinh kể trên.", "o": ["Cố đô Huế là di sản văn hóa được nhà nước bảo vệ.", "Việc phá hoại các bóng đèn LED của khu di tích không nằm trong giá trị bảo tồn của di tích Cố đô Huế.", "Các thanh niên trong thông tin trên thực hiện chưa đúng trách nhiệm của công dân trong việc giữ gìn và bảo vệ di sản văn hóa.", "Các học sinh trong thông tin trên sẽ phải chịu trách nhiệm pháp lý về hành vi vi phạm của mình."], "a": [true, false, false, true], "e": "Đáp án: a) Đúng; b) Sai; c) Sai; d) Đúng.", "nguon": "Đề nguồn: Đề 10 đáp án.docx · Phần II câu 3 · khoá: chữ Đúng/Sai trong ý"}, {"id": "L12-8T2-10-C28", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "dung_sai", "status": "cho_duyet", "q": "Đọc đoạn thông tin sau và cho biết mỗi ý a, b, c, d là Đúng hay Sai. Ngôi đền cổ ở xã X của bạn H bị các đối tượng xấu đột nhập trộm một lượng lớn cổ vật có giá trị. Các lực lượng chức năng và người dân địa phương nhiều lần tìm kiếm nhưng chưa bắt được thủ phạm và chưa thu hồi được các cổ vật. Một lần sang nhà bạn thân chơi, H vô tình bắt gặp anh trai bạn thân đang ngồi đóng gói một số đồ vật có hình dạng giống các cổ vật đã bị đánh cắp ở ngôi đền nên nảy sinh nghi ngờ. Sau đó H viết thư tố cáo gửi tới cơ quan chức năng để xem xét. Tuy nhiên vì do sợ bị trả thù nên H đã không trình bày cụ thể tên tuổi và địa chỉ người tố cáo nên đơn tố cáo của H không được xem xét giải quyết.", "o": ["Bạn H vừa chưa thực hiện đúng quyền vừa chưa thực hiện đúng nghĩa vụ của công dân trong việc bảo vệ di sản văn hóa.", "Người dân và lực lượng chức năng chưa thực hiện tốt nghĩa vụ của công dân về bảo vệ di sản văn hóa theo quy định.", "Việc cơ quan chức năng không xem xét đơn của H là hành vi vi phạm quyền và nghĩa vụ của công dân trong bảo vệ di sản.", "Bạn H nên trực tiếp chia sẻ với người có thẩm quyền để có biện pháp xử lý phù hợp."], "a": [true, true, false, true], "e": "Đáp án: a) Đúng; b) Đúng; c) Sai; d) Đúng.", "nguon": "Đề nguồn: Đề 10 đáp án.docx · Phần II câu 4 · khoá: chữ Đúng/Sai trong ý"}]}, {"id": "L12-HK2-01", "loai": "khoi", "khoi": 12, "hoc_ki": 2, "bo": "HK2", "ten_bo": "học kì II", "so_de": 1, "ten": "Lớp 12 · học kì II · Đề 1", "pham_vi": "Đề nguồn «CUỐI NĂM › 10 ĐỀ» · file nguồn: 01_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 1.docx", "thoi_gian": 50, "cau_truc": "24 câu trắc nghiệm + 4 câu đúng/sai (mỗi câu 4 ý)", "status": "cho_duyet", "khoa": {"khớp 2 nguồn": 24, "đã tự giải lại": 4}, "sua": "Rà đáp án (đề nguồn ghi khác): câu 4 — tạo sản phẩm mới, tối ưu sản xuất, cải tiến quản lý → năng lực tổ chức, lãnh đạo (A); câu 6 — «quyết định hình thức quản lý nhà nước ở cơ sở» không thuộc quyền đóng góp ý kiến (C); câu 20 — bệnh nhân được biết thông tin về phương pháp điều trị, giá dịch vụ → quyền được thông tin và giải thích (A); câu đúng/sai 4 ý b — không có «Tòa án kinh tế quốc tế» để nước B khởi kiện, tranh chấp thương mại giải quyết qua cơ chế của WTO → Sai.", "cau": [{"id": "L12-HK2-01-C01", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Những người sản xuất, cung cấp hàng hóa, dịch vụ ra thị trường, đáp ứng nhu cầu tiêu dùng của xã hội là", "o": ["Chủ thể nhà nước.", "Chủ thể tiêu dùng.", "Chủ thể sản xuất.", "Chủ thể trung gian."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: 01_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 1.docx · Phần I câu 1 · khoá: gạch chân, khớp file ĐÁP ÁN"}, {"id": "L12-HK2-01-C02", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Việc tổ chức, cá nhân vận dụng pháp luật, tiến hành những hoạt động mà pháp luật cho phép được gọi là hình thức thực hiện pháp luật nào?", "o": ["Tuân thủ pháp luật.", "Thi hành pháp luật.", "Sử dụng pháp luật.", "Áp dụng pháp luật."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: 01_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 1.docx · Phần I câu 2 · khoá: gạch chân, khớp file ĐÁP ÁN"}, {"id": "L12-HK2-01-C03", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Loại hình thất nghiệp nào dưới đây xảy ra do sự thay đổi trong cơ cấu ngành nghề của nền kinh tế?", "o": ["Thất nghiệp cơ cấu.", "Thất nghiệp tạm thời.", "Thất nghiệp chu kỳ.", "Thất nghiệp thời vụ."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: 01_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 1.docx · Phần I câu 3 · khoá: gạch chân, khớp file ĐÁP ÁN"}, {"id": "L12-HK2-01-C04", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Việc tạo ra sản phẩm mới, tối ưu hóa quá trình sản xuất và không ngừng cải tiến trong quản lý là biểu hiện của năng lực nào sau đây của người kinh doanh?", "o": ["Năng lực tổ chức, lãnh đạo.", "Năng lực giải quyết mối quan hệ.", "Năng lực tìm kiếm thị trường.", "Năng lực phân phối sản phẩm."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: 01_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 1.docx · Phần I câu 4 · khoá: ĐÃ TỰ GIẢI LẠI (đối chiếu SGK)"}, {"id": "L12-HK2-01-C05", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Theo Luật Bình đẳng giới năm 2006, nam và nữ được đối xử bình đẳng về quyền gì trong lĩnh vực lao động?", "o": ["Chính trị.", "Kinh tế.", "Lao động.", "Y tế."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: 01_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 1.docx · Phần I câu 5 · khoá: gạch chân, khớp file ĐÁP ÁN"}, {"id": "L12-HK2-01-C06", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Quyền tham gia đóng góp ý kiến vào các quyết định của nhà nước và xã hội không bao gồm việc nào dưới đây?", "o": ["Góp ý xây dựng các văn bản quy phạm pháp luật.", "Tham gia thảo luận về các vấn đề quan trọng của đất nước.", "Quyết định hình thức quản lý nhà nước ở cơ sở.", "Vận động mọi người góp ý kiến về các vấn đề của địa phương."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: 01_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 1.docx · Phần I câu 6 · khoá: ĐÃ TỰ GIẢI LẠI (đối chiếu SGK)"}, {"id": "L12-HK2-01-C07", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Một trong những yếu tố quan trọng nhất trong sự phát triển kinh tế là", "o": ["Tổng sản phẩm quốc nội bình quân đầu người.", "Chỉ số phát triển con người.", "Thu nhập quốc dân bình quân đầu người.", "Tổng sản phẩm quốc nội."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: 01_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 1.docx · Phần I câu 7 · khoá: gạch chân, khớp file ĐÁP ÁN"}, {"id": "L12-HK2-01-C08", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Người lao động bị mất việc làm có thể tham gia bảo hiểm nào dưới đây để nhận hỗ trợ về thu nhập và tìm kiếm công việc mới?", "o": ["Bảo hiểm thất nghiệp.", "Bảo hiểm y tế.", "Bảo hiểm xã hội.", "Bảo hiểm thân thể."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: 01_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 1.docx · Phần I câu 8 · khoá: gạch chân, khớp file ĐÁP ÁN"}, {"id": "L12-HK2-01-C09", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Chủ sở hữu có quyền sử dụng tài sản theo các hình thức hợp pháp, bao gồm cho vay, bán, hoặc cho mượn tài sản. Đây là quyền gì của chủ sở hữu?", "o": ["Chiếm hữu tài sản.", "Định đoạt tài sản.", "Sử dụng tài sản.", "Ủy quyền tài sản."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: 01_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 1.docx · Phần I câu 9 · khoá: gạch chân, khớp file ĐÁP ÁN"}, {"id": "L12-HK2-01-C10", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Mô hình kinh tế nào sau đây có đặc điểm là các thành viên hợp tác trong sản xuất, kinh doanh nhằm mục đích chung và cùng nhau chia sẻ lợi ích?", "o": ["Mô hình kinh tế hợp tác xã.", "Mô hình kinh tế hộ gia đình.", "Mô hình công ty cổ phần.", "Mô hình doanh nghiệp tư nhân."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: 01_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 1.docx · Phần I câu 10 · khoá: gạch chân, khớp file ĐÁP ÁN"}, {"id": "L12-HK2-01-C11", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Hiến pháp năm 2013 quy định về quyền và nghĩa vụ cơ bản của công dân là", "o": ["Quyền tự do cá nhân và nghĩa vụ bảo vệ tổ quốc.", "Quyền và nghĩa vụ bình đẳng trước pháp luật.", "Quyền tự do ngôn luận và nghĩa vụ tham gia lao động.", "Quyền và nghĩa vụ cơ bản của công dân được ghi nhận trong các điều kiện sống."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: 01_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 1.docx · Phần I câu 11 · khoá: gạch chân, khớp file ĐÁP ÁN"}, {"id": "L12-HK2-01-C12", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Theo quy định của pháp luật hiện hành, người có hành vi xâm phạm tài sản của người khác sẽ chịu trách nhiệm pháp lý nào?", "o": ["Phạt tiền từ 1.000.000₫ đến 3.000.000₫.", "Phạt tù từ 06 tháng đến 03 năm.", "Cải tạo không giam giữ từ 12 tháng đến 18 tháng.", "Phạt tù từ 03 năm đến 07 năm."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: 01_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 1.docx · Phần I câu 12 · khoá: gạch chân, khớp file ĐÁP ÁN"}, {"id": "L12-HK2-01-C13", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Theo quy định của pháp luật hiện hành, hành vi đưa thông tin sai sự thật ảnh hưởng đến danh dự, uy tín của người khác là vi phạm quyền nào?", "o": ["Quyền được bảo vệ sức khỏe.", "Quyền được bảo vệ danh dự, nhân phẩm.", "Quyền sở hữu tài sản.", "Quyền tự do ngôn luận."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: 01_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 1.docx · Phần I câu 13 · khoá: gạch chân, khớp file ĐÁP ÁN"}, {"id": "L12-HK2-01-C14", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Các quan hệ thỏa thuận về tiền lương và điều kiện làm việc của người lao động thuộc loại quan hệ nào?", "o": ["Thị trường lao động.", "Thị trường hàng hóa.", "Quan hệ lao động.", "Thị trường tiêu dùng."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: 01_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 1.docx · Phần I câu 14 · khoá: gạch chân, khớp file ĐÁP ÁN"}, {"id": "L12-HK2-01-C15", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Trong bối cảnh nhiều công ty cùng sản xuất một loại sản phẩm, công ty Y đã áp dụng chiến lược tặng quà kèm theo sản phẩm để thu hút khách hàng, trong khi không điều chỉnh giá bán. Việc làm của công ty Y thể hiện hành vi", "o": ["phù hợp với tập quán thương mại.", "cạnh tranh không lành mạnh.", "vì lợi ích của người tiêu dùng.", "vì lợi ích lâu dài của xã hội."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: 01_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 1.docx · Phần I câu 15 · khoá: gạch chân, khớp file ĐÁP ÁN"}, {"id": "L12-HK2-01-C16", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đọc thông tin và trả lời các câu hỏi 16, 17\nTheo báo cáo của ngành Giáo dục, tính đến hết năm 2023, cả nước có hơn 22 triệu học sinh, sinh viên tham gia học tập tại các cơ sở giáo dục phổ thông và đại học, trong đó gần 95% học sinh cấp tiểu học và trung học cơ sở đạt chuẩn phổ cập giáo dục. Ngoài ra, đã có hơn 3 triệu học sinh, sinh viên nhận được học bổng hoặc các hỗ trợ tài chính khác để đảm bảo điều kiện học tập. Ngành Giáo dục cũng đã tổ chức các chương trình ngoại khóa, phát triển kỹ năng sống cho trên 15 triệu lượt học sinh trong năm qua.\nTừ những số liệu trong thông tin trên, nhận định nào sau đây phù hợp với vai trò của giáo dục?", "o": ["Gần 95% học sinh cấp tiểu học và trung học cơ sở đạt chuẩn phổ cập giáo dục, cho thấy vẫn còn một số ít học sinh chưa được tiếp cận giáo dục.", "Hơn 3 triệu học sinh, sinh viên được nhận học bổng hoặc hỗ trợ tài chính đã tạo điều kiện tốt hơn để tiếp cận giáo dục.", "Hơn 15 triệu lượt học sinh tham gia chương trình ngoại khóa tạo áp lực cho ngân sách nhà nước.", "Chỉ có 95% học sinh tiểu học và trung học cơ sở đạt chuẩn phổ cập, cho thấy hệ thống giáo dục chưa đạt được hiệu quả như mong muốn."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: 01_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 1.docx · Phần I câu 16 · khoá: gạch chân, khớp file ĐÁP ÁN"}, {"id": "L12-HK2-01-C17", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đọc thông tin và trả lời các câu hỏi 16, 17\nTheo báo cáo của ngành Giáo dục, tính đến hết năm 2023, cả nước có hơn 22 triệu học sinh, sinh viên tham gia học tập tại các cơ sở giáo dục phổ thông và đại học, trong đó gần 95% học sinh cấp tiểu học và trung học cơ sở đạt chuẩn phổ cập giáo dục. Ngoài ra, đã có hơn 3 triệu học sinh, sinh viên nhận được học bổng hoặc các hỗ trợ tài chính khác để đảm bảo điều kiện học tập. Ngành Giáo dục cũng đã tổ chức các chương trình ngoại khóa, phát triển kỹ năng sống cho trên 15 triệu lượt học sinh trong năm qua.\nTrong thông tin trên, nội dung nào sau đây thể hiện trách nhiệm công dân về giáo dục?", "o": ["Gần 95% học sinh cấp tiểu học và trung học cơ sở đạt chuẩn phổ cập giáo dục.", "Hơn 22 triệu học sinh, sinh viên tham gia học tập.", "Hơn 3 triệu học sinh, sinh viên nhận được hỗ trợ tài chính.", "Trên 15 triệu lượt học sinh tham gia chương trình ngoại khóa."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: 01_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 1.docx · Phần I câu 17 · khoá: gạch chân, khớp file ĐÁP ÁN"}, {"id": "L12-HK2-01-C18", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Quản lý chi tiêu trong gia đình là việc sử dụng các khoản thu và chi để đảm bảo nhu cầu của các thành viên sao cho phù hợp với", "o": ["Kế hoạch chi tiêu.", "Nguồn thu nhập.", "Phong cách sống của gia đình.", "Mức sống của xã hội."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: 01_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 1.docx · Phần I câu 18 · khoá: gạch chân, khớp file ĐÁP ÁN"}, {"id": "L12-HK2-01-C19", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Phát biểu nào sau đây không đúng khi nói về tầm quan trọng của quản lý chi tiêu gia đình?", "o": ["Kiểm soát được việc tiêu dùng không hợp lý trong gia đình.", "Nâng cao đời sống tinh thần và vật chất của gia đình.", "Đảm bảo mọi thành viên chỉ chi tiêu theo ý kiến của người đứng đầu gia đình.", "Giúp phân bổ ngân sách hợp lý giữa các nhu cầu."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: 01_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 1.docx · Phần I câu 19 · khoá: gạch chân, khớp file ĐÁP ÁN"}, {"id": "L12-HK2-01-C20", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Theo Luật Khám bệnh, chữa bệnh năm 2023, bệnh nhân được biết các thông tin về phương pháp điều trị, giá dịch vụ và được hướng dẫn tự chăm sóc sức khỏe là nội dung thuộc quyền nào?", "o": ["Quyền được thông tin và giải thích về tình trạng sức khỏe.", "Quyền được khám bệnh, chữa bệnh.", "Quyền được lựa chọn bác sĩ điều trị.", "Quyền được bảo vệ thông tin cá nhân."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: 01_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 1.docx · Phần I câu 20 · khoá: ĐÃ TỰ GIẢI LẠI (đối chiếu SGK)"}, {"id": "L12-HK2-01-C21", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Cơ quan chức năng phát hiện nhà thuốc M kinh doanh thuốc giả với tổng giá trị 50 triệu đồng. Theo quy định pháp luật, hành vi này phải chịu trách nhiệm pháp lý nào sau đây?", "o": ["Phạt tiền, buộc tiêu hủy toàn bộ số thuốc giả.", "Phạt tiền, thu hồi giấy phép kinh doanh của nhà thuốc M.", "Thu hồi chứng chỉ hành nghề của chủ nhà thuốc M vĩnh viễn.", "Cảnh cáo và yêu cầu đình chỉ hoạt động trong 6 tháng."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: 01_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 1.docx · Phần I câu 21 · khoá: gạch chân, khớp file ĐÁP ÁN"}, {"id": "L12-HK2-01-C22", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đọc thông tin và trả lời các câu hỏi 22, 23, 24\nHội nhập kinh tế quốc tế đã tạo điều kiện cho Việt Nam đa dạng hóa các mặt hàng xuất khẩu. Trong đó, cà phê là một trong những sản phẩm thế mạnh của Việt Nam. Chỉ tính riêng trong nửa đầu năm 2024, Việt Nam đã xuất khẩu ước tính 1,1 triệu tấn cà phê với giá trị đạt 2,5 tỷ đô la Mỹ, tăng 35% về lượng và 45% về giá trị so với cùng kỳ năm trước. Tuy nhiên, một lô hàng của công ty cổ phần X bị phát hiện chứa chất bảo quản vượt mức cho phép. Phía đối tác yêu cầu công ty X bồi thường toàn bộ giá trị lô hàng nhưng công ty này không chấp nhận vì trong hợp đồng không quy định điều khoản này.\nTrong thông tin trên, hội nhập kinh tế quốc tế đem lại lợi ích nào sau đây cho các doanh nghiệp trong hoạt động xuất khẩu cà phê tại Việt Nam?", "o": ["Tăng giá trị xuất khẩu và nâng cao thương hiệu quốc gia.", "Đạt giá trị xuất khẩu 2,5 tỷ đô la Mỹ trong năm 2024.", "Tiếp cận thị trường và tăng giá trị xuất khẩu là 35%.", "Tạo cơ hội để các doanh nghiệp Việt Nam tham gia vào chuỗi cung ứng toàn cầu."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: 01_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 1.docx · Phần I câu 22 · khoá: gạch chân, khớp file ĐÁP ÁN"}, {"id": "L12-HK2-01-C23", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đọc thông tin và trả lời các câu hỏi 22, 23, 24\nHội nhập kinh tế quốc tế đã tạo điều kiện cho Việt Nam đa dạng hóa các mặt hàng xuất khẩu. Trong đó, cà phê là một trong những sản phẩm thế mạnh của Việt Nam. Chỉ tính riêng trong nửa đầu năm 2024, Việt Nam đã xuất khẩu ước tính 1,1 triệu tấn cà phê với giá trị đạt 2,5 tỷ đô la Mỹ, tăng 35% về lượng và 45% về giá trị so với cùng kỳ năm trước. Tuy nhiên, một lô hàng của công ty cổ phần X bị phát hiện chứa chất bảo quản vượt mức cho phép. Phía đối tác yêu cầu công ty X bồi thường toàn bộ giá trị lô hàng nhưng công ty này không chấp nhận vì trong hợp đồng không quy định điều khoản này.\nTheo quy định của pháp luật Việt Nam, hành vi vi phạm của công ty cổ phần X phải chịu trách nhiệm pháp lý nào sau đây?", "o": ["Buộc thu hồi sản phẩm và thay đổi quy trình sản xuất.", "Đền bù cho đối tác toàn bộ giá trị của lô hàng bị trả lại.", "Xử phạt hành chính và áp dụng hình phạt bổ sung theo quy định.", "Tước quyền xuất khẩu mặt hàng cà phê trong thời gian quy định."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: 01_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 1.docx · Phần I câu 23 · khoá: gạch chân, khớp file ĐÁP ÁN"}, {"id": "L12-HK2-01-C24", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đọc thông tin và trả lời các câu hỏi 22, 23, 24\nHội nhập kinh tế quốc tế đã tạo điều kiện cho Việt Nam đa dạng hóa các mặt hàng xuất khẩu. Trong đó, cà phê là một trong những sản phẩm thế mạnh của Việt Nam. Chỉ tính riêng trong nửa đầu năm 2024, Việt Nam đã xuất khẩu ước tính 1,1 triệu tấn cà phê với giá trị đạt 2,5 tỷ đô la Mỹ, tăng 35% về lượng và 45% về giá trị so với cùng kỳ năm trước. Tuy nhiên, một lô hàng của công ty cổ phần X bị phát hiện chứa chất bảo quản vượt mức cho phép. Phía đối tác yêu cầu công ty X bồi thường toàn bộ giá trị lô hàng nhưng công ty này không chấp nhận vì trong hợp đồng không quy định điều khoản này.\nTrong trường hợp trên, công ty cổ phần X nên lựa chọn phương thức giải quyết đầu tiên nào sau đây phù hợp với nguyên tắc hợp tác quốc tế với phía đối tác?", "o": ["Thương lượng với các bên liên quan để đạt thỏa thuận.", "Đàm phán trực tiếp với đại diện của tổ chức quốc tế.", "Đưa tranh chấp ra Tòa án quốc tế để giải quyết.", "Đơn phương đình chỉ hợp đồng thương mại để giảm thiệt hại."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: 01_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 1.docx · Phần I câu 24 · khoá: gạch chân, khớp file ĐÁP ÁN"}, {"id": "L12-HK2-01-C25", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "dung_sai", "status": "cho_duyet", "q": "Vị thế của Việt Nam trên thế giới đã được củng cố toàn diện trong giai đoạn 2011 - 2022. Cùng với quá trình hội nhập kinh tế quốc tế mạnh mẽ, đến năm 2020, Việt Nam có 30 đối tác chiến lược và đối tác chiến lược toàn diện; có quan hệ ngoại giao với 189/193 nước, có quan hệ kinh tế với 160 nước và 70 vùng lãnh thổ. Đến năm 2022, tổng số quan hệ kinh tế - thương mại của Việt Nam đã nâng lên thành 230 nước và vùng lãnh thổ. Với việc thực hiện chủ trương hội nhập quốc tế toàn diện với trọng tâm là hội nhập kinh tế quốc tế, vị thế của đất nước tiếp tục được cải thiện đáng kể. Có thể khẳng định, hội nhập kinh tế quốc tế đóng góp quan trọng vào việc mở rộng và đưa quan hệ của nước ta với các đối tác đi vào chiều sâu, tạo thế đan xen lợi ích, góp phần gìn giữ môi trường hòa bình, ổn định để phát triển đất nước; nâng cao uy tín và vị thế của Việt Nam trên trường quốc tế.", "o": ["Việc thiết lập quan hệ đối tác chiến lược và chiến lực toàn diện là thể hiện hình thức hội nhập kinh tế quốc tế ở cấp độ khu vực.", "Hội nhập kinh tế quốc tế không góp phần thúc đẩy sự tăng trưởng GDP hàng năm ở Việt Nam.", "Nước ta đang phát triển vì vậy khi hội nhập kinh tế quốc tế, Việt Nam phải chấp nhận từ bỏ lợi ích của mình để hội nhập.", "Hội nhập kinh tế quốc tế góp phần đưa hàng hóa của Việt Nam đến với các thị trường trên thế giới."], "a": [false, false, false, true], "e": "Đáp án: a) Sai; b) Sai; c) Sai; d) Đúng.", "nguon": "Đề nguồn: 01_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 1.docx · Phần II câu 1 · khoá: gạch chân, khớp file ĐÁP ÁN"}, {"id": "L12-HK2-01-C26", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "dung_sai", "status": "cho_duyet", "q": "Từ năm 2018, ông M thành lập Công ty Trách nhiệm hữu hạn Thương mại và Sản xuất G với ngành nghề kinh doanh dầu nhớt, phụ tùng xe gắn máy. Trong thời gian kinh doanh, ông M nhận thấy khách hàng ưa chuộng các phụ tùng xe gắn máy hiệu H và dầu nhớt hiệu K nên nảy sinh ý định làm giả sản phẩm của các thương hiệu này bán cho khách hàng để thu lợi. Ông M chỉ đạo nhân viên thiết kế các mẫu tem xác nhận hàng chính hãng và thuê người in nhiều mẫu tem để sử dụng, sau đó ông cùng vợ đến một số chợ trong khu vực tìm mua các phụ tùng xe gắn máy, dầu nhớt chất lượng kém đem về đóng gói, dán tem làm giả sản phẩm của các thương hiệu nổi tiếng, bán ra thị trường cho khách với giá thấp hơn hàng chính hãng từ 10% – 15%. Bằng thủ đoạn đó, trong thời gian gần 2 năm, vợ chồng ông M đã sản xuất số lượng hàng giả có giá trị tương đương hàng thật hơn 750 triệu đồng, thu lợi khoảng 300 triệu đồng.", "o": ["Hành vi làm giả hàng hóa các thương hiệu nổi tiếng để thu lợi nhuận là vi phạm quyền mở rộng kinh doanh của công dân.", "Ông M cùng vợ phải chịu trách nhiệm hình sự về hành vi vi phạm pháp luật của mình.", "Ông M vừa vi phạm nghĩa vụ kinh doanh vừa vi phạm nghĩa vụ nộp thuế cho nhà nước.", "Việc thành lập doanh nghiệp của ông M thể hiện quyền của công dân về kinh doanh."], "a": [false, true, true, true], "e": "Đáp án: a) Sai; b) Đúng; c) Đúng; d) Đúng.", "nguon": "Đề nguồn: 01_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 1.docx · Phần II câu 2 · khoá: gạch chân, khớp file ĐÁP ÁN"}, {"id": "L12-HK2-01-C27", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "dung_sai", "status": "cho_duyet", "q": "Công ty cổ phần B chuyên sản xuất mặt hàng đồ chơi trẻ em. Từ nhiều năm nay, công ty đã thực hiện đầy đủ quy định pháp luật về bảo vệ môi trường trong sản xuất, kinh doanh, hàng năm công ty đầu tư hàng tỉ đồng để xây dựng hệ thống xử lí nước thải bảo vệ môi trường, sản xuất đồ chơi không ảnh hưởng đến sức khoẻ của trẻ em. Đồng thời, công ty còn thực hiện đúng nghĩa vụ kê khai và nộp thuế cho Nhà nước theo quy định.", "o": ["Thực hiện quy định của pháp luật về bảo vệ môi trường là công ty đã thực hiện tốt trách nhiệm xã hội ở hình thức pháp lý và kinh tế.", "Việc sản xuất các đồ chơi không ảnh hưởng đến sức khỏe của trẻ em là phù hợp với trách nhiệm xã hội của doanh nghiệp ở hình thức đạo đức và kinh tế.", "Thực hiện tốt nghĩa vụ nộp thuế cho nhà nước gắn liền với trách nhiệm nhân văn của doanh nghiệp.", "Thông qua việc tạo ra những sản phẩm không ảnh hưởng đến sức khỏe của trẻ em, công ty B đã thể hiện trách nhiệm của mình trong việc thúc đẩy phát triển bền vững."], "a": [false, true, false, true], "e": "Đáp án: a) Sai; b) Đúng; c) Sai; d) Đúng.", "nguon": "Đề nguồn: 01_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 1.docx · Phần II câu 3 · khoá: gạch chân, khớp file ĐÁP ÁN"}, {"id": "L12-HK2-01-C28", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "dung_sai", "status": "cho_duyet", "q": "Sau khi phát hiện mặt hàng thép nhập khẩu từ nước B có dấu hiệu phá giá, ngành thép nước C đã yêu cầu Bộ Thương mại nước C mở cuộc điều tra. Kết quả cho thấy mặt hàng này được trợ giá bởi chính phủ nước B, gây ảnh hưởng lớn đến ngành thép nội địa nước C. Bộ Thương mại nước C quyết định áp thuế chống bán phá giá đối với mặt hàng thép nhập khẩu từ nước B với mức thuế 15%.", "o": ["Việc áp thuế chống bán phá giá đối với mặt hàng thép nhập khẩu từ nước B là biện pháp nhằm bảo vệ ngành sản xuất nội địa.", "Nước B có thể khởi kiện việc áp thuế chống bán phá giá lên Tòa án kinh tế quốc tế.", "Trong trường hợp nước C muốn điều chỉnh mức thuế áp dụng, nước C cần thông báo trước cho nước B.", "Việc áp thuế chống bán phá giá sẽ do Bộ Công thương nước C trực tiếp thực hiện mà không cần thông qua kết luận điều tra."], "a": [true, false, true, false], "e": "Đáp án: a) Đúng; b) Sai; c) Đúng; d) Sai.", "nguon": "Đề nguồn: 01_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 1.docx · Phần II câu 4 · khoá: ĐÃ TỰ GIẢI LẠI (đối chiếu SGK)"}]}, {"id": "L12-HK2-02", "loai": "khoi", "khoi": 12, "hoc_ki": 2, "bo": "HK2", "ten_bo": "học kì II", "so_de": 2, "ten": "Lớp 12 · học kì II · Đề 2", "pham_vi": "Đề nguồn «CUỐI NĂM › 10 ĐỀ» · file nguồn: 02_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 2.docx", "thoi_gian": 50, "cau_truc": "24 câu trắc nghiệm + 4 câu đúng/sai (mỗi câu 4 ý)", "status": "cho_duyet", "khoa": {"khớp 2 nguồn": 27, "đã tự giải lại": 1}, "sua": "Rà đáp án (đề nguồn ghi khác): câu đúng/sai 4 — Công ước Luật Biển 1982 là cơ sở pháp lí quan trọng bảo vệ quyền và lợi ích của Việt Nam trên biển (ý c Đúng); các hiệp định phân định biển nhằm xác định ranh giới, không phải «chia đều lợi ích» (ý d Sai).", "cau": [{"id": "L12-HK2-02-C01", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Trong nền kinh tế xã hội, hoạt động đóng vai trò cơ bản nhất, quyết định các hoạt động khác của đời sống xã hội là hoạt động", "o": ["sản xuất", "phân phối.", "tiêu dùng", "trao đổi."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: 02_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 2.docx · Phần I câu 1 · khoá: gạch chân, khớp file ĐÁP ÁN"}, {"id": "L12-HK2-02-C02", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Khởi tố bị can là hoạt động tư pháp của cơ quan nào dưới đây?", "o": ["Viện kiểm sát nhân dân.", "Tòa án nhân dân.", "Ủy ban nhân dân.", "Hội đồng nhân dân."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: 02_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 2.docx · Phần I câu 2 · khoá: gạch chân, khớp file ĐÁP ÁN"}, {"id": "L12-HK2-02-C03", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Số lượng hàng hóa, dịch vụ mà nhà cung cấp sẵn sàng đáp ứng cho nhu cầu của thị trường tương ứng với mức giá cả được xác định trong một khoảng thời gian nhất định được gọi là", "o": ["cung.", "cầu.", "lạm phát.", "thất nghiệp."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: 02_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 2.docx · Phần I câu 3 · khoá: gạch chân, khớp file ĐÁP ÁN"}, {"id": "L12-HK2-02-C04", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Trong mối quan hệ giữa thị trường việc làm và thị trường lao động, khi khả năng cung ứng lao động lớn hơn khả năng tạo việc làm sẽ dẫn đến hiện tượng nào trong xã hội gia tăng?", "o": ["Lạm phát.", "Thất nghiệp.", "Cạnh tranh.", "Khủng hoảng."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: 02_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 2.docx · Phần I câu 4 · khoá: gạch chân, khớp file ĐÁP ÁN"}, {"id": "L12-HK2-02-C05", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Công dân dù ở cương vị nào, khi vi phạm pháp luật đều bị xử lí theo quy định là", "o": ["công dân bình đẳng về kinh tế.", "công dân bình đẳng về quyền và nghĩa vụ.", "công dân bình đẳng về trách nhiệm pháp lí.", "công dân bình đẳng về chính trị."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: 02_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 2.docx · Phần I câu 5 · khoá: gạch chân, khớp file ĐÁP ÁN"}, {"id": "L12-HK2-02-C06", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Việc làm nào dưới đây thể hiện quyền bình đẳng giới trên lĩnh vực chính trị?", "o": ["Đăng ký học nâng cao trình độ.", "Góp ý dự thảo Luật đất đai sửa đổi.", "Hưởng trợ cấp tai nạn lao động.", "Đăng ký thành lập doanh nghiệp."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: 02_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 2.docx · Phần I câu 6 · khoá: gạch chân, khớp file ĐÁP ÁN"}, {"id": "L12-HK2-02-C07", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Giá trị bằng tiền của tất cả các hàng hóa và dịch vụ cuối cùng được sản xuất ra trên lãnh thổ một nước trong thời gian nhất định được gọi là", "o": ["tổng thu nhập quốc dân ( GNI).", "tổng thu nhập quốc nội (GDP).", "tổng thu nhập quốc nội trên đầu người.", "tổng thu nhập quốc dân trên đầu người."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: 02_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 2.docx · Phần I câu 7 · khoá: gạch chân, khớp file ĐÁP ÁN"}, {"id": "L12-HK2-02-C08", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Chủ thể của loại hình bảo hiểm xã hội là do", "o": ["các doanh nghiệp tư nhân.", "tổ chức thương mại.", "nhà đầu tư nước ngoài.", "Nhà nước tổ chức."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: 02_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 2.docx · Phần I câu 8 · khoá: gạch chân, khớp file ĐÁP ÁN"}, {"id": "L12-HK2-02-C09", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Việc chủ thể nắm giữ, chi phối tài sản một cách trực tiếp hoặc gián tiếp như chủ thể có quyền đối với tài sản được gọi là quyền", "o": ["chiếm hữu.", "sở hữu.", "sử dụng.", "định đoạt."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: 02_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 2.docx · Phần I câu 9 · khoá: gạch chân, khớp file ĐÁP ÁN"}, {"id": "L12-HK2-02-C10", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Theo quy định của pháp luật, khi thực hiện quyền của mình về bảo vệ Tổ quốc, mọi công dân nếu đủ điều kiện đều được", "o": ["kinh doanh mặt hàng quân sự.", "hợp lý hóa mô hình kinh doanh.", "mở rộng quy mô sản xuất.", "phục vụ trong quân đội."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: 02_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 2.docx · Phần I câu 10 · khoá: gạch chân, khớp file ĐÁP ÁN"}, {"id": "L12-HK2-02-C11", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Một trong những cơ chế kinh tế được các quốc gia vận dụng để điều hành nền kinh tế đó là", "o": ["cơ chế tự cung tự cấp.", "cơ chế kế hoạch hoá tập trung.", "Cơ chế chỉ huy của Chính phủ.", "Cơ chế thị trường."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: 02_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 2.docx · Phần I câu 11 · khoá: gạch chân, khớp file ĐÁP ÁN"}, {"id": "L12-HK2-02-C12", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Phát biểu nào sau đây thể hiện thói quen chi tiêu không hợp lí?", "o": ["Chi tiêu theo cảm xúc cá nhân.", "Không bỏ qua chi phí phát sinh.", "Sử dụng công cụ hỗ trợ quản lí tài chính.", "Điều chỉnh hoạt động chi tiêu"], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: 02_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 2.docx · Phần I câu 12 · khoá: gạch chân, khớp file ĐÁP ÁN"}, {"id": "L12-HK2-02-C13", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Ở nước ta hiện nay, nam nữ bình đẳng trong về tiêu chuẩn, độ tuổi khi được đề bạt, bổ nhiệm vào cùng vị trí quản lý, lãnh đạo của cơ quan tổ chức là thể hiện bình đẳng giới trong lĩnh vực", "o": ["chính trị.", "văn hóa.", "kinh tế.", "gia đình."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: 02_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 2.docx · Phần I câu 13 · khoá: gạch chân, khớp file ĐÁP ÁN"}, {"id": "L12-HK2-02-C14", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Căn cứ vào tiêu chí/ đặc điểm nào để phân chia các loại thị trường như thị trường vàng, thị trường bảo hiểm, thị trường bất động sản?", "o": ["Phạm vi hoạt động", "Đối tượng hàng hoá", "Tính chất và cơ chế vận hành", "Vai trò của các đối tượng mua bán"], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: 02_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 2.docx · Phần I câu 14 · khoá: gạch chân, khớp file ĐÁP ÁN"}, {"id": "L12-HK2-02-C15", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Hành vi nào sau đây thể hiện việc không tôn trọng quyền sở hữu tài sản của công dân?", "o": ["Trao đổi tài sản với bạn bè.", "Thừa kế tài sản của người thân.", "Kí kết hợp đồng mua bán tài sản.", "Làm hỏng tài sản của đồng nghiệp."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: 02_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 2.docx · Phần I câu 15 · khoá: gạch chân, khớp file ĐÁP ÁN"}, {"id": "L12-HK2-02-C16", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Theo Luật Di sản văn hoá năm 2013, tổ chức, cá nhân có nghĩa vụ giao nộp di vật, cổ vật, bảo vật quốc gia do mình tìm được cho ai?", "o": ["Bất kì ai mà tổ chức, cá nhân tin tưởng.", "Đại diện tổ chức xã hội nơi cư trú.", "Cơ quan nhà nước có thẩm quyền nơi gần nhất.", "Bất kì cơ quan nhà nước nào."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: 02_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 2.docx · Phần I câu 16 · khoá: gạch chân, khớp file ĐÁP ÁN"}, {"id": "L12-HK2-02-C17", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Trường hợp nào sau đây vi phạm pháp luật về quyền, nghĩa vụ của công dân trong học tập?", "o": ["Học sinh K tự ý tắt điện phòng học bên cạnh khi thấy các bạn lớp đó quên tắt.", "Ông B yêu cầu hội đồng tuyển sinh đại học Trường Đại học X phải cộng điểm ưu tiên cho con mình vì gia đình ông thuộc đồng bào dân tộc thiểu số.", "Với lí do để nâng cao kết quả học tập của học sinh, cô giáo S đã yêu cầu học sinh lớp mình chủ nhiệm học thêm lớp học miễn phí do cô dạy.", "Cho rằng con gái thì không cần học cao nên sau khi T học hết trung học cơ sở, gia đình bà M đã không cho T tiếp tục học lên cấp THPT."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: 02_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 2.docx · Phần I câu 17 · khoá: gạch chân, khớp file ĐÁP ÁN"}, {"id": "L12-HK2-02-C18", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đọc thông tin và trả lời câu hỏi 18, 19, 20\nGia đình anh T có thu nhập trung bình và đang có kế hoạch sau 8 năm nữa sẽ mua một căn hộ trên phố. Để thực hiện được kế hoạch này, vợ anh là chị H thường xuyên theo dõi, lập kế hoạch thu, chi trong gia đình và điều chỉnh việc sử dụng tài chính để đảm bảo các nhu cầu cơ bản được đáp ứng, tài chính gia đình được duy trì ổn định. Chị cũng thường xuyên theo dõi chi tiêu, ghi chép đánh giá để điều chỉnh kế hoạch khi cần.\nViệc chi tiêu có kế hoạch sẽ giúp gia đình anh T chủ động thực hiện", "o": ["tiêu dùng không giới hạn.", "chi tiêu không tiết kiệm.", "kế hoạch tài chính gia đình.", "cắt bỏ chi tiêu thiết yếu."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: 02_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 2.docx · Phần I câu 18 · khoá: gạch chân, khớp file ĐÁP ÁN"}, {"id": "L12-HK2-02-C19", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đọc thông tin và trả lời câu hỏi 18, 19, 20\nGia đình anh T có thu nhập trung bình và đang có kế hoạch sau 8 năm nữa sẽ mua một căn hộ trên phố. Để thực hiện được kế hoạch này, vợ anh là chị H thường xuyên theo dõi, lập kế hoạch thu, chi trong gia đình và điều chỉnh việc sử dụng tài chính để đảm bảo các nhu cầu cơ bản được đáp ứng, tài chính gia đình được duy trì ổn định. Chị cũng thường xuyên theo dõi chi tiêu, ghi chép đánh giá để điều chỉnh kế hoạch khi cần.\nThói quen chi tiêu của gia đình anh T là", "o": ["Chi tiêu cảm hứng, không có kế hoạch.", "Lãng phí tiền bạc cho những khoản chi không cần thiết.", "Chi tiêu quá mức so với khả năng tài chính.", "Thường xuyên theo dõi, điều chỉnh cách chi tiêu."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: 02_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 2.docx · Phần I câu 19 · khoá: gạch chân, khớp file ĐÁP ÁN"}, {"id": "L12-HK2-02-C20", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đọc thông tin và trả lời câu hỏi 18, 19, 20\nGia đình anh T có thu nhập trung bình và đang có kế hoạch sau 8 năm nữa sẽ mua một căn hộ trên phố. Để thực hiện được kế hoạch này, vợ anh là chị H thường xuyên theo dõi, lập kế hoạch thu, chi trong gia đình và điều chỉnh việc sử dụng tài chính để đảm bảo các nhu cầu cơ bản được đáp ứng, tài chính gia đình được duy trì ổn định. Chị cũng thường xuyên theo dõi chi tiêu, ghi chép đánh giá để điều chỉnh kế hoạch khi cần.\nĐể thực hiện tốt kế hoạch thu, chi trong gia đình, trong thời gian tới chị H không nên", "o": ["điều chỉnh tỉ lệ phân chia các khoản chi.", "thực hiện các khoản chi theo kế hoạch.", "cắt giảm các khoản chi thiết yếu.", "kiểm soát các nguồn thu trong gia đình."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: 02_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 2.docx · Phần I câu 20 · khoá: gạch chân, khớp file ĐÁP ÁN"}, {"id": "L12-HK2-02-C21", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đọc thông tin và trả lời câu hỏi 21, 22, 23, 24\nSau khi học hết lớp 9, T muốn tiếp tục đi học tiếp nhưng bố mẹ T không đồng ý vì cho rằng là con gái thì không cần học nhiều và yêu cầu T vào làm ở nhà máy X gần nhà dù gia đình vẫn có đủ điều kiện cho T theo học. Trong quá trình làm việc ở nhà máy X, T làm ở bộ phận thường xuyên tiếp xúc với các chất độc hại thông qua công việc hằng ngày là xả nước thải ra môi trường.\nTheo Luật Hôn nhân và gia đình hiện hành, bố mẹ của T đã phân biệt đối xử với các con trên cơ sở nào?", "o": ["Điều kiện kinh tế gia đình.", "Giới tính.", "Lực học của các con.", "Điều kiện việc làm ở địa phương."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: 02_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 2.docx · Phần I câu 21 · khoá: gạch chân, khớp file ĐÁP ÁN"}, {"id": "L12-HK2-02-C22", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đọc thông tin và trả lời câu hỏi 21, 22, 23, 24\nSau khi học hết lớp 9, T muốn tiếp tục đi học tiếp nhưng bố mẹ T không đồng ý vì cho rằng là con gái thì không cần học nhiều và yêu cầu T vào làm ở nhà máy X gần nhà dù gia đình vẫn có đủ điều kiện cho T theo học. Trong quá trình làm việc ở nhà máy X, T làm ở bộ phận thường xuyên tiếp xúc với các chất độc hại thông qua công việc hằng ngày là xả nước thải ra môi trường.\nTheo Luật Giáo dục hiện hành, việc T học hết lớp 9 thể hiện T đã hoàn thành", "o": ["giáo dục phổ thông.", "giáo dục nghề nghiệp.", "bồi dưỡng giáo dục.", "phổ cập giáo dục."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: 02_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 2.docx · Phần I câu 22 · khoá: gạch chân, khớp file ĐÁP ÁN"}, {"id": "L12-HK2-02-C23", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đọc thông tin và trả lời câu hỏi 21, 22, 23, 24\nSau khi học hết lớp 9, T muốn tiếp tục đi học tiếp nhưng bố mẹ T không đồng ý vì cho rằng là con gái thì không cần học nhiều và yêu cầu T vào làm ở nhà máy X gần nhà dù gia đình vẫn có đủ điều kiện cho T theo học. Trong quá trình làm việc ở nhà máy X, T làm ở bộ phận thường xuyên tiếp xúc với các chất độc hại thông qua công việc hằng ngày là xả nước thải ra môi trường.\nVới tính chất công việc của mình, T có quyền yêu cầu Công ty X tổ chức cho mình khám sức khoẻ định kì theo quy định hiện hành của pháp luật là", "o": ["ít nhất 01 tháng một lần.", "ít nhất 03 tháng một lần.", "ít nhất 06 tháng một lần.", "ít nhất 09 tháng một lần."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: 02_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 2.docx · Phần I câu 23 · khoá: gạch chân, khớp file ĐÁP ÁN"}, {"id": "L12-HK2-02-C24", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đọc thông tin và trả lời câu hỏi 21, 22, 23, 24\nSau khi học hết lớp 9, T muốn tiếp tục đi học tiếp nhưng bố mẹ T không đồng ý vì cho rằng là con gái thì không cần học nhiều và yêu cầu T vào làm ở nhà máy X gần nhà dù gia đình vẫn có đủ điều kiện cho T theo học. Trong quá trình làm việc ở nhà máy X, T làm ở bộ phận thường xuyên tiếp xúc với các chất độc hại thông qua công việc hằng ngày là xả nước thải ra môi trường.\nViệc nhà máy X xả thải ra môi trường là vi phạm", "o": ["nghĩa vụ trong bảo vệ môi trường,", "quyền về bảo vệ môi trường.", "nghĩa vụ trong nộp thuế.", "quyền tuyển dụng lao động."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: 02_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 2.docx · Phần I câu 24 · khoá: gạch chân, khớp file ĐÁP ÁN"}, {"id": "L12-HK2-02-C25", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "dung_sai", "status": "cho_duyet", "q": "Đọc đoạn thông tin sau: Theo số liệu từ Cục Đầu tư nước ngoài, Bộ Kế hoạch và Đầu tư, tính đến ngày 20/12/2023, tổng vốn đầu tư nước ngoài đăng kí vào Việt Nam (FDI) đạt gần 36,61 tỉ USD, tăng 32,1 % so với cùng kì; vốn thực hiện của dự án đầu tư nước ngoài ước đạt khoảng 23,18 tỉ USD, tăng 3,5 % so với năm 2022. Trong những năm qua, vốn vay ưu đãi và vốn viện trợ không hoàn lại (ODA) có tác động trực tiếp và gián tiếp đến tăng trưởng kinh tế ở Việt Nam. Vốn ODA góp phần gia tăng tổng đầu tư xã hội, tạo động lực thu hút đầu tư tư nhân và vốn FDI, từ đó thúc đẩy tăng trưởng kinh tế, hỗ trợ Việt Nam đạt được nhiều kết quả trong công cuộc xoá đói giảm nghèo. (Theo: Trang thông tin điện tử Đầu tư nước ngoài – Bộ Kế hoạch và Đầu tư, “Tình hình thu hút đầu tư nước ngoài tại Việt Nam năm 2023”, ngày 16/01/2024)", "o": ["Vốn đầu tư trực tiếp nước ngoài (FDI) còn có tên gọi khác là vốn ODA.", "Mặc dù vốn đầu tư nước ngoài đăng kí vào Việt Nam tăng nhưng tác động của nó đến tăng trưởng kinh tế vẫn còn nhiều tranh cãi.", "Cùng với hoạt động thương mại quốc tế và các dịch vụ thu ngoại tệ, đầu tư quốc tế là một trong các hoạt động kinh tế đối ngoại cơ bản, có ý nghĩa to lớn đối với sự tăng trưởng kinh tế của Việt Nam.", "Việt Nam tiếp nhận vốn vay ưu đãi và vốn viện trợ không hoàn lại góp phần xoá đói giảm nghèo, nâng cao đời sống của các tầng lớp dân cư, thúc đẩy phát triển kinh tế – xã hội."], "a": [false, false, true, true], "e": "Đáp án: a) Sai; b) Sai; c) Đúng; d) Đúng.", "nguon": "Đề nguồn: 02_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 2.docx · Phần II câu 1 · khoá: gạch chân, khớp file ĐÁP ÁN"}, {"id": "L12-HK2-02-C26", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "dung_sai", "status": "cho_duyet", "q": "Đọc đoạn thông tin sau: Vốn được đào tạo bài bản về công nghệ thông tin và có niềm đam mê đặc biệt với lĩnh vực giáo dục, anh S – Giám đốc điều hành của Công ty Cổ phần phát triển công nghệ giáo dục ABC bắt đầu khởi nghiệp từ năm 2019 (khi còn là sinh viên). Anh cho biết, bản thân nhận thức được rất rõ những giá trị mà khởi nghiệp sớm mang lại, cũng như những khó khăn, thách thức đi kèm. Anh cho rằng để tránh thất bại, các bạn trẻ cần hiểu bản chất của kinh doanh, phân tích thật kĩ về lợi thế cạnh tranh, sự khác biệt, tìm hiểu thị trường và lập kế hoạch kinh doanh thật chi tiết. Tiếp theo là khâu tìm kiếm đội ngũ nhân sự chất lượng để thực hiện dự án. Yếu tố cuối cùng không thể thiếu được đó là dự phòng rủi ro.", "o": ["Ý tưởng kinh doanh của anh S được xác định dựa trên lợi thế nội tại về sự đam mê và hiểu biết.", "Lập kế hoạch kinh doanh một cách chi tiết là việc cần làm đối với người khởi sự kinh doanh.", "Khi đưa ra lời khuyên về khởi nghiệp, anh S nhấn mạnh bước xác định mục tiêu trong quy trình lập kế hoạch kinh doanh.", "Chỉ nên phân tích rủi ro và biện pháp xử lí khi kế hoạch kinh doanh được triển khai trong thực tiễn."], "a": [true, true, false, false], "e": "Đáp án: a) Đúng; b) Đúng; c) Sai; d) Sai.", "nguon": "Đề nguồn: 02_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 2.docx · Phần II câu 2 · khoá: gạch chân, khớp file ĐÁP ÁN"}, {"id": "L12-HK2-02-C27", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "dung_sai", "status": "cho_duyet", "q": "Đọc đoạn thông tin sau: Vợ chồng ông K cùng con là anh T đang sinh sống trên mảnh đất được cấp quyền sử dụng đất mang tên ông K. Năm 2006, vì làm ăn không thuận lợi, ông K có thương lượng và nhượng lại mảnh đất gia đình đang ở cho em gái ruột của ông là cô P với giá 50 triệu đồng. Vì là anh em ruột, ông K và cô P chỉ làm giấy tờ kí tay về thoả thuận trên và ông K giao giấy chứng nhận quyền sử dụng đất cho cô P giữ. Cô P có hứa với gia đình ông K sau này nếu làm ăn được muốn lấy lại đất thì cô sẽ bán lại mảnh đất trên để sinh sống. Năm 2011, con ông K là anh T có đến xin chuộc lại mảnh đất trên thì được cô P đồng ý với giá 130 triệu đồng. Hai tháng sau, tình hình bất động sản nơi này giao dịch trở nên “sôi động”, anh T mang tiền đến mua lại đất thì được biết cô P đã nhượng lại cho cô Ch với giá 500 triệu đồng.", "o": ["Mảnh đất của gia đình ông K trước khi giao cho cô P thuộc sở hữu toàn dân mà Nhà nước là đại diện chủ sở hữu.", "Sau khi nhận giấy chứng nhận quyền sử dụng đất từ ông K và kí giấy thoả thuận tay với ông, quyền sử dụng đất đã được xác lập cho cô P.", "Thoả thuận nhượng đất giữa cô P và cô Ch là phù hợp với quy định của pháp luật.", "Gia đình anh T có quyền yêu cầu cô P huỷ bỏ thoả thuận nhượng đất với cô Ch."], "a": [true, false, false, true], "e": "Đáp án: a) Đúng; b) Sai; c) Sai; d) Đúng.", "nguon": "Đề nguồn: 02_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 2.docx · Phần II câu 3 · khoá: gạch chân, khớp file ĐÁP ÁN"}, {"id": "L12-HK2-02-C28", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "dung_sai", "status": "cho_duyet", "q": "Đọc đoạn thông tin sau: Với chủ trương nhất quán thông qua các biện pháp hoà bình giải quyết tranh chấp, bất đồng trên biển, Việt Nam đã có nhiều nỗ lực trong việc áp dụng có hiệu quả Công ước Liên hợp quốc về Luật Biển 1982 để phân định biển với các nước láng giềng, trong đó luôn đề cao nguyên tắc công bằng để tìm ra giải pháp hợp lí, cụ thể là: Việt Nam đã kí với Thái Lan Hiệp định về phân định biển ngày 09/8/1997; kí với Trung Quốc Hiệp định về phân định vịnh Bắc Bộ và Hiệp định hợp tác nghề cá trong vịnh Bắc Bộ ngày 25/12/2000; kí với Indonesia Hiệp định về phân định thềm lục địa ngày 26/6/2003.", "o": ["Các quốc gia cần đàm phán với nhau để giải quyết những tranh chấp, bất đồng trên biển.", "Trong bất kì trường hợp nào, các quốc gia cũng không được giải quyết tranh chấp, bất đồng trên biển bằng vũ lực.", "Công ước Liên hợp quốc về Luật Biển năm 1982 là cơ sở pháp lí quan trọng để bảo vệ quyền và lợi ích của Việt Nam trên biển.", "Việt Nam kí các Hiệp định với Thái Lan, Trung Quốc, Indonesia nhằm chia đều lợi ích giữa các quốc gia."], "a": [true, true, true, false], "e": "Đáp án: a) Đúng; b) Đúng; c) Đúng; d) Sai.", "nguon": "Đề nguồn: 02_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 2.docx · Phần II câu 4 · khoá: ĐÃ TỰ GIẢI LẠI (đối chiếu SGK)"}]}, {"id": "L12-HK2-03", "loai": "khoi", "khoi": 12, "hoc_ki": 2, "bo": "HK2", "ten_bo": "học kì II", "so_de": 3, "ten": "Lớp 12 · học kì II · Đề 3", "pham_vi": "Đề nguồn «CUỐI NĂM › 10 ĐỀ» · file nguồn: 03_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 3.docx", "thoi_gian": 50, "cau_truc": "24 câu trắc nghiệm + 4 câu đúng/sai (mỗi câu 4 ý)", "status": "cho_duyet", "khoa": {"khớp 2 nguồn": 26, "đã tự giải lại": 2}, "sua": "Câu đúng/sai 3 (anh Tuấn thành lập công ty): đề ghi Đ/S ngay trong từng ý (Đ, S, S, Đ); ý c «không có báo cáo tài chính» sai vì đoạn thông tin nói báo cáo tài chính được ghi chép đầy đủ. Gạch chân và file ĐÁP ÁN ghi nhầm ý c là Đúng. Câu đúng/sai 2 (chị T du học cho con): chữ Đúng/Sai đề viết cuối từng ý là S, Đ, S, Đ — gạch chân và file ĐÁP ÁN ghi ngược (Đ, S, Đ, S); ý c «chỉ khi chi tiêu theo sở thích… mới đạt tự do tài chính» rõ ràng sai.", "cau": [{"id": "L12-HK2-03-C01", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Trong nền kinh tế, chủ thể nào đóng vai trò quan trọng trong việc tạo ra hàng hoá cho xã hội, phục vụ nhu cầu tiêu dùng?", "o": ["Chủ thể trung gian", "Doanh nghiệp Nhà nước", "Các điểm bán hàng", "Chủ thể sản xuất"], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: 03_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 3.docx · Phần I câu 1 · khoá: gạch chân, khớp file ĐÁP ÁN"}, {"id": "L12-HK2-03-C02", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Trong nền kinh tế, chủ thể nào đóng vai trò là cầu nối giữa chủ thể sản xuất và chủ thể tiêu dùng?", "o": ["Chủ thể trung gian.", "Nhà đầu tư chứng khoán.", "Chủ thể doang nghiệp.", "Chủ thể nhà nước."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: 03_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 3.docx · Phần I câu 2 · khoá: gạch chân, khớp file ĐÁP ÁN"}, {"id": "L12-HK2-03-C03", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Loại thuế được cộng vào giá bán hàng hóa, dịch vụ và do người tiêu dùng trả khi sử dụng sản phẩm đó được gọi là gì?", "o": ["Thuế giá trị gia tăng.", "Thuế thu nhập doanh nghiệp.", "Thuế thu nhập cá nhân .", "Thuế bảo vệ môi trường."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: 03_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 3.docx · Phần I câu 3 · khoá: gạch chân, khớp file ĐÁP ÁN"}, {"id": "L12-HK2-03-C04", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Vai trò nào sau đây không phải của thuế?", "o": ["Thuế là nguồn thu quan trọng nhất cho ngân sách nhà nước.", "Thuế là công cụ kích thích đầu tư nhằm thúc đẩy tăng trưởng kinh tế.", "Thuế thực hiện công bằng an sinh xã hội.", "Thuế là công cụ hiệu quả nhất để điều tiết thu nhập"], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: 03_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 3.docx · Phần I câu 4 · khoá: gạch chân, khớp file ĐÁP ÁN"}, {"id": "L12-HK2-03-C05", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Lượng hàng hóa, dịch vụ mà người tiêu dùng sẵn sàng mua với một mức giá nhất định trong khoảng thời gian xác định được gọi là", "o": ["cung.", "cầu.", "giá trị.", "giá cả."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: 03_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 3.docx · Phần I câu 5 · khoá: gạch chân, khớp file ĐÁP ÁN"}, {"id": "L12-HK2-03-C06", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Trong sản xuất và lưu thông hàng hóa, khi giá cả thị trường giảm xuống thì các doanh nghiệp thường có xu hướng", "o": ["tăng giá trị cá biệt của hàng hóa", "mở rộng quy mô sản xuất.", "tăng khối lượng cung hàng hóa.", "thu hẹp quy mô sản xuất."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: 03_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 3.docx · Phần I câu 6 · khoá: gạch chân, khớp file ĐÁP ÁN"}, {"id": "L12-HK2-03-C07", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Tình trạng mức giá chung của nền kinh tế tăng lên trong một khoảng thời gian nhất định được gọi là", "o": ["Tăng trưởng.", "Lạm phát.", "Khủng hoảng.", "Suy thoái."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: 03_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 3.docx · Phần I câu 7 · khoá: gạch chân, khớp file ĐÁP ÁN"}, {"id": "L12-HK2-03-C08", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Xác định nguyên nhân dẫn đến lạm phát trong thông tin sau: Thông tin.Khi mất cân đối giữa tốc độ tăng cung tiền và tốc độ tăng trưởng GDP lớn thì sức ép lạm phát bắt đầu xuất hiện. Ví dụ, trong hai năm 2005 và 2006, GDP của Việt Nam tăng trưởng 17%, trong khi đó, tiền mặt trong lưu thông và tiền gửi trong ngân hàng tăng tới 73%.", "o": ["Chi phí sản xuất tăng cao.", "Tổng cầu của nền kinh tế tăng.", "Giá cả nguyên liệu, nhân công, thuế,… giảm.", "Lượng tiền trong lưu thông vượt quá mức cần thiết."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: 03_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 3.docx · Phần I câu 8 · khoá: gạch chân, khớp file ĐÁP ÁN"}, {"id": "L12-HK2-03-C09", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Để khắc phục tình trạng lạm phát do lượng tiền mặt trong lưu thông vượt quá mức cần thiết, nhà nước cần", "o": ["giảm thuế.", "giảm mức cung tiền.", "giảm lãi suất tiền gửi.", "tăng chi tiêu ngân sách."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: 03_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 3.docx · Phần I câu 9 · khoá: gạch chân, khớp file ĐÁP ÁN"}, {"id": "L12-HK2-03-C10", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Tình trạng thất nghiệp để lại hậu quả như thế nào đối với xã hội?", "o": ["Thu nhập giảm hoặc không có, đời sống gặp nhiều khó khăn.", "Lợi nhuận giảm hoặc thua lỗ, buộc phải thu hẹp quy mô sản xuất.", "Lãng phí nguồn lực, làm cho nền kinh tế rơi vào tình trạng suy thoái.", "Phát sinh nhiều tệ nạn xã hội; trật tự, an ninh xã hội không ổn định."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: 03_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 3.docx · Phần I câu 10 · khoá: gạch chân, khớp file ĐÁP ÁN"}, {"id": "L12-HK2-03-C11", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Nơi diễn ra các quan hệ thoả thuận giữa người sử dụng lao động và người lao động về tiền lương, điều kiện làm việc trên cơ sở hợp đồng lao động được gọi là", "o": ["thị trường việc làm.", "thị trường lao động.", "trung tâm giới thiệu việc làm.", "trung tâm môi giới việc làm."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: 03_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 3.docx · Phần I câu 11 · khoá: gạch chân, khớp file ĐÁP ÁN"}, {"id": "L12-HK2-03-C12", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Phiên giao dịch việc làm đã giúp cho các cơ sở sản xuất, kinh doanh tuyển dụng được lao động và những người lao động đã tìm được việc làm phù hợp là biểu hiện nội dung nào sau đây?", "o": ["Mối quan hệ giữa thị trường lao động và thị trường việc làm.", "Mối quan hệ giữa những người sử dụng lao động với nhau.", "Mối quan hệ giữa lao động và thị trường lao động.", "Mối quan hệ giữa việc làm và thị trường việc làm."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: 03_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 3.docx · Phần I câu 12 · khoá: gạch chân, khớp file ĐÁP ÁN"}, {"id": "L12-HK2-03-C13", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Phát biểu nào sau đây là sai về sự cần thiết của hội nhập kinh tế quốc tế?", "o": ["Tạo cơ hội tiếp cận và sử dụng nguồn lực tài chính bên ngoài.", "Tạo cơ hội tiếp cận và sử dụng kinh nghiệm quản lí bên ngoài.", "Giúp mỗi quốc gia mở rộng thị trường, thu hút nguồn vốn đầu tư.", "Giúp nước này có thể chi phối nước khác về lĩnh vực kinh tế."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: 03_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 3.docx · Phần I câu 13 · khoá: gạch chân, khớp file ĐÁP ÁN"}, {"id": "L12-HK2-03-C14", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Tổ chức lương thực và Nông nghiệp Liên Hợp Quốc là tổ chức quốc tế thuộc cấp độ hội nhập nào dưới đây ?", "o": ["Hội nhập toàn cầu", "Hội nhập khu vực", "Hội nhập song phương", "Hội nhập đa phương"], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: 03_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 3.docx · Phần I câu 14 · khoá: gạch chân, khớp file ĐÁP ÁN"}, {"id": "L12-HK2-03-C15", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Hệ thống các chính sách do Nhà nước và các lực lượng xã hội thực hiện giải quyết các vấn đề xã hội nhằm nâng cao năng lực tự bảo vệ của người dân và xã hội trước những rủi ro hay nguy cơ giảm hoặc mất thu nhập góp phần cải thiện chất lượng cuộc sống, phát triển và công bằng xã hội là nội dung của khái niệm nào sau đây?", "o": ["Trợ giúp xã hội.", "Chính sách xã hội.", "An sinh xã hội.", "Bảo hiểm xã hội."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: 03_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 3.docx · Phần I câu 15 · khoá: gạch chân, khớp file ĐÁP ÁN"}, {"id": "L12-HK2-03-C16", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đối với một doanh nghiệp bước khởi đầu trong quá trình lập kế hoạch kinh doanh là", "o": ["xác định mục tiêu và chiến lược kinh doanh.", "xác định định hướng, ý tưởng kinh doanh.", "xây dựng kế hoạch hoạt động kinh doanh.", "phân tích các điều kiện thực hiện ý tưởng kinh doanh"], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: 03_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 3.docx · Phần I câu 16 · khoá: gạch chân, khớp file ĐÁP ÁN"}, {"id": "L12-HK2-03-C17", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đọc trường hợp sau và trả lời các câu hỏi 17, 18\nAnh B thành lập doanh nghiệp tư nhân chuyên bán hàng và cung cấp dịch vụ công nghệ thông tin, được cơ quan nhà nước có thẩm quyền cấp Giấy chứng nhận đăng kí doanh nghiệp. Trước kì nộp thuế, anh B đến cơ quan thuế và được cung cấp đầy đủ thông tin tài liệu liên quan đến quyền và nghĩa vụ nộp thuế. Hiểu được quyền và nghĩa vụ của mình, anh B nghiêm chỉnh chấp hành chế độ kế toán thống kê, ghi chép đầy đủ doanh số bán hàng, kê khai đầy đủ, kịp thời, chính xác số tiền thuế phải nộp, đóng thuế đầy đủ và đúng hạn.\nDoanh nghiệp anh B thực hiện hình thức tổ chức kinh doanh nào?", "o": ["Công ty cổ phần.", "Doanh nghiệp tư nhân.", "Kinh tế tập thể.", "Doanh nghiệp tư bản tư nhân."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: 03_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 3.docx · Phần I câu 17 · khoá: gạch chân, khớp file ĐÁP ÁN"}, {"id": "L12-HK2-03-C18", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đọc trường hợp sau và trả lời các câu hỏi 17, 18\nAnh B thành lập doanh nghiệp tư nhân chuyên bán hàng và cung cấp dịch vụ công nghệ thông tin, được cơ quan nhà nước có thẩm quyền cấp Giấy chứng nhận đăng kí doanh nghiệp. Trước kì nộp thuế, anh B đến cơ quan thuế và được cung cấp đầy đủ thông tin tài liệu liên quan đến quyền và nghĩa vụ nộp thuế. Hiểu được quyền và nghĩa vụ của mình, anh B nghiêm chỉnh chấp hành chế độ kế toán thống kê, ghi chép đầy đủ doanh số bán hàng, kê khai đầy đủ, kịp thời, chính xác số tiền thuế phải nộp, đóng thuế đầy đủ và đúng hạn.\nAnh B đã thực hiện nghĩa vụ của một doanh nghiệp như thế nào khi thực hiện hoạt động kinh doanh của mình?", "o": ["Đóng thuế đầy đủ và đúng hạn.", "Kê khai sai lệch về doanh thu của doanh nghiệp.", "Tự do lựa chọn hình thức tổ chức kinh doanh.", "Được cơ quan thuế hướng dẫn đầy đủ thủ tục."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: 03_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 3.docx · Phần I câu 18 · khoá: gạch chân, khớp file ĐÁP ÁN"}, {"id": "L12-HK2-03-C19", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đọc thông tin và trả lời các câu hỏi 19,20\nHằng năm, trường trung học phổ thông Y thường tổ chức cho học sinh đi tham quan các di tích lịch sử - văn hoá của tỉnh. Qua hoạt động tham quan này, học sinh của trường THPT Y được thực hiện quyền của công dân về bảo vệ di sản văn hoá, được giáo dục truyền thống văn hoá của tỉnh qua các thời kì lịch sử. Khi đi tham quan, học sinh tìm hiểu ý nghĩa, lịch sử của các di sản văn hoá của tỉnh. Một số bạn còn ghi chép lại các sự kiện, tìm hiểu thêm các tư liệu liên quan đến di tích.\nHoạt động tổ chức cho học sinh tham quan các di tích lịch sử văn hóa tỉnh của của trường THPT Y là góp phần thực hiện quyền của công dân trong bảo vệ di sản văn hóa ở nội dung nào dưới đây?", "o": ["Tiếp cận và hưởng thụ giá trị di sản.", "Khai thác nguồn lợi kinh tế của di sản.", "Tôn tạo và bổ sung các di sản mới.", "Tham gia phục dựng giá trị di sản."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: 03_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 3.docx · Phần I câu 19 · khoá: gạch chân, khớp file ĐÁP ÁN"}, {"id": "L12-HK2-03-C20", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đọc thông tin và trả lời các câu hỏi 19,20\nHằng năm, trường trung học phổ thông Y thường tổ chức cho học sinh đi tham quan các di tích lịch sử - văn hoá của tỉnh. Qua hoạt động tham quan này, học sinh của trường THPT Y được thực hiện quyền của công dân về bảo vệ di sản văn hoá, được giáo dục truyền thống văn hoá của tỉnh qua các thời kì lịch sử. Khi đi tham quan, học sinh tìm hiểu ý nghĩa, lịch sử của các di sản văn hoá của tỉnh. Một số bạn còn ghi chép lại các sự kiện, tìm hiểu thêm các tư liệu liên quan đến di tích.\nViệc làm nào sau đây của các bạn học sinh trường THPT Y thể hiện nghĩa vụ của công dân trong bảo vệ di sản văn hóa?", "o": ["Tìm hiểu giá trị các di tích.", "Tôn trọng giá trị vốn có của di sản.", "Ghi chép lại đặc điểm di sản.", "Thay đổi giá trị vốn có của di sản."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: 03_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 3.docx · Phần I câu 20 · khoá: gạch chân, khớp file ĐÁP ÁN"}, {"id": "L12-HK2-03-C21", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đọc thông tin và trả lời các câu hỏi 21,22\nPhát hiện chồng mình là anh D thường qua lại với chị H là người yêu cũ dù chị đã có chồng con, chị M bế con bỏ nhà đi biệt tích. Nắm được sự việc, bà V mẹ chị M, tới nhà bà K nói chuyện, do thiếu kiềm chế, bà V đã có lời lẽ xúc phạm bà K và anh D nên bị con gái bà K mời ra khỏi nhà. Trong thời gian đó, do thường xuyên không được trang bị bảo hộ đạt chuẩn, anh D bị tai nạn phải nằm viện điều trị một tháng. Vì ông T giám đốc công ty nơi anh D làm việc không đồng ý bồi thường số tiền mà anh D yêu cầu nên bà K đã thuê phóng viên viết bài công khai việc ông T có con ngoài ra thú rồi chia sẻ lên mạng khiến uy tín của ông bị ảnh hưởng nghiêm trọng và vợ ông đòi ly hôn.\nTrong thông tin trên những ai dưới đây đã vi phạm quyền và nghĩa vụ giữa vợ và chồng trong quan hệ hôn nhân và gia đình?", "o": ["Chị H, ông T và bà K.", "Ông T, anh D và bà V.", "Anh D, chị H và ông T.", "Anh D, chị H và chị M."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: 03_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 3.docx · Phần I câu 21 · khoá: gạch chân, khớp file ĐÁP ÁN"}, {"id": "L12-HK2-03-C22", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đọc thông tin và trả lời các câu hỏi 21,22\nPhát hiện chồng mình là anh D thường qua lại với chị H là người yêu cũ dù chị đã có chồng con, chị M bế con bỏ nhà đi biệt tích. Nắm được sự việc, bà V mẹ chị M, tới nhà bà K nói chuyện, do thiếu kiềm chế, bà V đã có lời lẽ xúc phạm bà K và anh D nên bị con gái bà K mời ra khỏi nhà. Trong thời gian đó, do thường xuyên không được trang bị bảo hộ đạt chuẩn, anh D bị tai nạn phải nằm viện điều trị một tháng. Vì ông T giám đốc công ty nơi anh D làm việc không đồng ý bồi thường số tiền mà anh D yêu cầu nên bà K đã thuê phóng viên viết bài công khai việc ông T có con ngoài ra thú rồi chia sẻ lên mạng khiến uy tín của ông bị ảnh hưởng nghiêm trọng và vợ ông đòi ly hôn.\nAnh D và chị H đã vi phạm nội dung nào dưới đây của quyền và nghĩa vụ giữa vợ và chồng trong gia đình?", "o": ["Quyền kết hôn.", "Quyền ly hôn.", "Quyền tài sản.", "Quyền nhân thân."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: 03_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 3.docx · Phần I câu 22 · khoá: gạch chân, khớp file ĐÁP ÁN"}, {"id": "L12-HK2-03-C23", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đọc thông tin và trả lời câu hỏi 23,24\nHundu và Renda đều là hai quốc gia thành viên của Công ước về chống khủng bố quốc tế. Tháng 4/ 2011, Chính phủ Hundu nhận được báo cáo của Cục tình báo quốc gia về việc phát hiện ra nơi ẩn náu trên lãnh thổ Renda của tên trùm khủng bố ( bị truy nã toàn cầu) mà quốc gia này đang tìm kiếm. Chính phủ Hundu ngay lập tức bí mật điều động máy bay quân sự với tần số siêu âm, thoát khỏi sự kiểm soát của rada trinh thám Renda, vượt biên giới, tiến vào lãnh thổ nước này và tấn công nơi ở của tên trùm khủng bố, đồng thời tiêu diệt tên này.\nPhát hiện ra hành vi của Hundu, Renda đã lên tiếng phản đối mạnh mẽ. phía Renda cho rằng hành vi này đã vi phạm nghiêm trọng chủ quyền quốc gia. Tuy nhiên, Hundu cho rằng hành vi của quốc gia này là nhằm thưc hiện nghĩa vụ thành viên của Công ước về chống khủng bố. Hơn nữa, Tổng thống Hundu đã thực hiện cuộc điện đàm chính thức với Tổng thống Renda và ông này hứa sẽ tạo mọi điều kiện thuận lợi cho hoạt động chống khủng bố được thực hiện bởi Hundu.\nHành vi Hundu bí mật điều động máy bay quân sự với tần số siêu âm, thoát khỏi sự kiểm soát của rada trinh thám Renda, vượt biên giới, tiến vào lãnh thổ Renda là", "o": ["vi phạm pháp luật của Randa.", "vi phạm nguyên tắc bình đẳng về chủ quyền giữa các quốc gia của pháp luật quốc tế.", "hành động cần thiết khi bắt khủng bố.", "vi phạm pháp luật quốc tế."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: 03_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 3.docx · Phần I câu 23 · khoá: gạch chân, khớp file ĐÁP ÁN"}, {"id": "L12-HK2-03-C24", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đọc thông tin và trả lời câu hỏi 23,24\nHundu và Renda đều là hai quốc gia thành viên của Công ước về chống khủng bố quốc tế. Tháng 4/ 2011, Chính phủ Hundu nhận được báo cáo của Cục tình báo quốc gia về việc phát hiện ra nơi ẩn náu trên lãnh thổ Renda của tên trùm khủng bố ( bị truy nã toàn cầu) mà quốc gia này đang tìm kiếm. Chính phủ Hundu ngay lập tức bí mật điều động máy bay quân sự với tần số siêu âm, thoát khỏi sự kiểm soát của rada trinh thám Renda, vượt biên giới, tiến vào lãnh thổ nước này và tấn công nơi ở của tên trùm khủng bố, đồng thời tiêu diệt tên này.\nPhát hiện ra hành vi của Hundu, Renda đã lên tiếng phản đối mạnh mẽ. phía Renda cho rằng hành vi này đã vi phạm nghiêm trọng chủ quyền quốc gia. Tuy nhiên, Hundu cho rằng hành vi của quốc gia này là nhằm thưc hiện nghĩa vụ thành viên của Công ước về chống khủng bố. Hơn nữa, Tổng thống Hundu đã thực hiện cuộc điện đàm chính thức với Tổng thống Renda và ông này hứa sẽ tạo mọi điều kiện thuận lợi cho hoạt động chống khủng bố được thực hiện bởi Hundu.\nHành vi của Hundu có hợp pháp không? Vì sao?", "o": ["Có, vì Hundu thực hiện nghĩa vụ thành viên của Công ước về chống khủng bố.", "Không, vì Hundu bí mật điều động máy bay quân sự tiến vào lãnh thổ Renda.", "Không, vì Hundu vi phạm các nguyên tắc cơ bản của pháp luật quốc tế.", "Có, vì tiêu diệt khủng bố là nghĩa vụ của tất cả các nước trên thế giới. II/ CÂU HỎI TRẮC NGHIỆM ĐÚNG/SAI"], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: 03_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 3.docx · Phần I câu 24 · khoá: gạch chân, khớp file ĐÁP ÁN"}, {"id": "L12-HK2-03-C25", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "dung_sai", "status": "cho_duyet", "q": "Đọc thông tin sau Chị E giao kết hợp đồng lao động không xác định thời hạn với công ty A. Hàng tháng, chị E đóng đầy đủ các loại BHXH. Đến 01/6/2020, chị E nghỉ thai sản (nghỉ đến hết 31/12/2020). Vì lý do gia đình, 01/1/2021 chị E nộp đơn xin nghỉ việc. Trước khi chấm dứt HĐLĐ, tổng thời gian đóng bảo hiểm thất nghiệp là 15 tháng. Căn cứ vào quy định của pháp luật lao động chị đã làm hồ sơ gửi cơ quan chức năng để nhận hỗ trợ theo quy định. Sau đó được sự tư vấn của bạn bè, chị E tham gia gói bảo hiểm nhân thọ cho cả mẹ và con chị.", "o": ["Loại hình bảo hiểm xã hội mà chị E tham gia trước khi nghỉ việc là bảo hiểm xã hội tự nguyện.", "Chị E đã tham gia loại hình bảo hiểm thất nghiệp tự nguyện nên chị được hưởng trợ cấp thất nghiệp.", "Trước khi nghỉ việc chị E không tham gia bảo hiểm y tế.", "Bảo hiểm nhân thọ mà chị E tham gia là loại hình bảo hiểm thương mai."], "a": [false, false, false, true], "e": "Đáp án: a) Sai; b) Sai; c) Sai; d) Đúng.", "nguon": "Đề nguồn: 03_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 3.docx · Phần II câu 1 · khoá: chữ Đúng/Sai trong ý, khớp file ĐÁP ÁN"}, {"id": "L12-HK2-03-C26", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "dung_sai", "status": "cho_duyet", "q": "Đọc đoạn thông tin sau: Chị T ấp ủ dự định cho con trai (hiện đang học lớp 10) đi du học. Chị ước tính số tiền cần để trả tiền chi phí cho con 4 năm đại học là 300 triệu đồng. Với số tiền lớn này, Chị T xác định mốc thời gian tiết kiệm tiền phải trên 2 năm, mục tiêu trước mắt là khoản chi phí cho con học trung tâm để lấy chứng chỉ ngoại ngữ trong năm học lớp 10 này. Chị T lập một kế hoạch tài chính để đạt được mục tiêu tài chính trên. Theo dự kiến, mỗi tháng nhà chị T sẽ phải tiết kiệm tối thiểu 8 triệu đồng và duy trì mức tiết kiệm này là 3 năm. Để dự phòng chi phí phát sinh và đáp ứng các nhu cầu cấp thiết khác như: quỹ học tập, quỹ dự phòng, quỹ mừng sinh nhật bạn bè, người thân, ... mỗi tháng chị T tiết kiệm thêm 1 triệu đồng bỏ ở một ống tiết kiệm riêng dùng trong trường hợp khẩn cấp. Ngoài ra, chị T dự tính, sẽ làm thêm công việc báo cáo thuế tháng cho 2 công ty và chị T dùng số tiền này bổ sung vào quỹ tiết kiệm của mình. Trong 20 tháng đầu tiên, gia đình chị T cố gắng đạt được mục tiêu tiết kiệm 200 triệu đồng. Từ số tiền này, T sẽ mở tài khoản tiết kiệm ở ngân hàng để đầu tư sinh lời mỗi năm. Số tiền sinh lời này, T dùng bổ sung vào quỹ tiết kiệm của mình để sớm đạt được mục tiêu tài chính đã đặt.", "o": ["Quản lí thu, chi là việc quản lí các nguồn thu nhập và các khoản chi tiêu của tất cả các thành viên trong gia đình.", "Mục tiêu tài chính của gia đình chị T là mục tiêu tài chính trung hạn.", "Chỉ khi nào được chi tiêu theo sở thích, thỏa mãn mọi nhu cầu của các thành viên trong gia đình thì mới đạt được mục tiêu tự do tài chính.", "Mục tiêu tài chính cho con trai học lấy chứng chỉ ngoại ngữ là mục tiêu tài chính ngắn hạn."], "a": [false, true, false, true], "e": "Đáp án: a) Sai; b) Đúng; c) Sai; d) Đúng.", "nguon": "Đề nguồn: 03_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 3.docx · Phần II câu 2 · khoá: ĐÃ TỰ GIẢI LẠI (đối chiếu SGK)"}, {"id": "L12-HK2-03-C27", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "dung_sai", "status": "cho_duyet", "q": "Đọc đoạn thông tin sau: Anh Tuấn đăng ký thành lập công ty tư nhân chuyên sản xuất hàng may mặc. Khi đăng ký thành lập công ty, anh kê khai đầy đủ nội dung hồ sơ đăng ký doanh nghiệp. Sau 5 năm hoạt động, công ty sản xuất kinh doanh hiệu quả, mang lại lợi nhuận, nộp thuế đóng góp vào ngân sách nhà nước, giải quyết việc làm cho người lao động ở địa phương. Trong suốt 5 năm qua, vốn và tài sản của công ty được sử dụng vào hoạt động kinh doanh luôn được ghi chép đầy đủ vào sổ kế toán và báo cáo tài chính của công ty.", "o": ["Công ty anh Tuấn thành lập thực hiện quyền tuyển dụng, thuê và sử dụng lao động khi tiến hành kinh doanh.", "Anh Tuấn đã thực hiện nghĩa vụ bảo vệ môi trường và tài nguyên thiên nhiên.", "Doanh nghiệp của anh Tuấn không có báo cáo tài chính, vi phạm pháp luật về kinh doanh.", "Khi tiến hành hoạt động kinh doanh, anh Tuấn đã đóng góp vào ngân sách nhà nước."], "a": [true, false, false, true], "e": "Đáp án: a) Đúng; b) Sai; c) Sai; d) Đúng.", "nguon": "Đề nguồn: 03_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 3.docx · Phần II câu 3 · khoá: ĐÃ TỰ GIẢI LẠI (đối chiếu SGK)"}, {"id": "L12-HK2-03-C28", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "dung_sai", "status": "cho_duyet", "q": "Đọc đoạn thông tin sau: Anh D hoạt động trong lĩnh vực xuất bản phần mềm cho máy tính. Ngay khi nhận được khoản thu nhập đầu tiên từ công việc, anh D đã chủ động tìm hiểu thông tin về việc nộp thuế để thực hiện nghĩa vụ của mình. Anh D trực tiếp đến cơ quan thuế đề nghị hỗ trợ và được cán bộ cơ quan thuế cung cấp đầy đủ các thông tin liên quan đến quyền và nghĩa vụ nộp thuế. Sau khi nắm được thông tin, anh D đăng kí mã số thuế cá nhân, kê khai đầy đủ thông tin về thu nhập của bản thân và nộp đủ số tiền thuế theo quy định của pháp luật. Thời gian sau đó, mỗi khi đến kì nộp thuế, anh D luôn chủ động khai thuế và nộp thuế đầy đủ, đúng hạn.", "o": ["Anh D vừa thực hiện tốt nghĩa vụ kinh doanh vừa thực hiện tốt nghĩa vụ nộp thuế.", "Việc anh D được cung cấp đầy đủ các thông tin liên quan đến việc nộp thuế của bản thân thể hiện cơ quan thuế đã thực hiện tốt nghĩa vụ của mình.", "Anh D đã thực hiện tốt trách nhiệm kinh tế của doanh nghiệp khi tiến hành kinh doanh.", "Việc đăng ký mã số thuế cá nhân của anh D là thực hiện quyền của công dân về nộp thuế."], "a": [true, true, false, false], "e": "Đáp án: a) Đúng; b) Đúng; c) Sai; d) Sai.", "nguon": "Đề nguồn: 03_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 3.docx · Phần II câu 4 · khoá: chữ Đúng/Sai trong ý, khớp file ĐÁP ÁN"}]}, {"id": "L12-HK2-04", "loai": "khoi", "khoi": 12, "hoc_ki": 2, "bo": "HK2", "ten_bo": "học kì II", "so_de": 4, "ten": "Lớp 12 · học kì II · Đề 4", "pham_vi": "Đề nguồn «CUỐI NĂM › 10 ĐỀ» · file nguồn: 04_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 4.docx", "thoi_gian": 50, "cau_truc": "24 câu trắc nghiệm + 4 câu đúng/sai (mỗi câu 4 ý)", "status": "cho_duyet", "khoa": {"khớp 2 nguồn": 23, "đã tự giải lại": 2, "1 nguồn": 3}, "sua": "Câu 13 (chủ doanh nghiệp luôn suy nghĩ để vạch ra chiến lược kinh doanh): năng lực lãnh đạo (C). Ngân hàng bài lớp 11 (Bài 6, đề nguồn) cùng khoá «năng lực lãnh đạo»; khoá A («năng lực quốc tế») trong đề này lệch. Câu đúng/sai 2 (Nicaragua) ý c: «vi phạm nghĩa vụ hợp tác» — hành vi tài trợ, huấn luyện lật đổ chính phủ vi phạm nguyên tắc không can thiệp/không dùng vũ lực, không phải nghĩa vụ hợp tác → Sai (đề HK2-05 có cùng câu và khoá Sai).", "cau": [{"id": "L12-HK2-04-C01", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Hành vi nào dưới đây kìm hãm sự tăng trưởng, phát triển kinh tế đất nước?", "o": ["Sản xuất hàng giả, hàng nhái.", "Tạo việc làm cho người lao động.", "Tìm kiếm thị trường tiêu thụ.", "Đóng thuế theo quy định."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: 04_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 4.docx · Phần I câu 1 · khoá: gạch chân, khớp file ĐÁP ÁN"}, {"id": "L12-HK2-04-C02", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Theo quy định của pháp luật, khi thực hiện quyền tự do ngôn luận công dân có nghĩa vụ", "o": ["trình bày mọi quan điểm.", "xuyên tạc về mặt nội dung.", "tuân thủ quy định pháp luật.", "ủng hộ mọi quan điểm đưa ra."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: 04_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 4.docx · Phần I câu 2 · khoá: gạch chân, khớp file ĐÁP ÁN"}, {"id": "L12-HK2-04-C03", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Chính sách hỗ trợ người dân phòng ngừa, giảm thiểu rủi ro khi bị giảm hoặc mất thu nhập là nội dung của chính sách an sinh xã hội nào sau đây?", "o": ["Chính sách dịch vụ xã hội cơ bản.", "Chính sách việc làm, thu nhập và giảm nghèo.", "Chính sách bảo hiểm xã hội.", "Chính sách trợ giúp xã hội."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: 04_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 4.docx · Phần I câu 3 · khoá: gạch chân, khớp file ĐÁP ÁN"}, {"id": "L12-HK2-04-C04", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Tổ chức kinh tế có tên riêng, có tài sản, trụ sở giao dịch ổn định, được đăng kí kinh doanh theo quy định của pháp luật nhằm mục đích thực hiện các hoạt động kinh doanh được gọi là", "o": ["doanh nghiệp.", "xưởng sản xuất.", "khu công nghiệp.", "đại lí phân phối."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: 04_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 4.docx · Phần I câu 4 · khoá: gạch chân, khớp file ĐÁP ÁN"}, {"id": "L12-HK2-04-C05", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Mọi công dân đều bình đẳng về nghĩa vụ trước pháp luật khi thực hiện hành vi nào sau đây?", "o": ["Đăng kí hồ sơ đấu thầu.", "Xây dựng nguồn quỹ xã hội.", "Bảo vệ an ninh quốc gia.", "Thay đổi địa bàn cư trú."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: 04_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 4.docx · Phần I câu 5 · khoá: gạch chân, khớp file ĐÁP ÁN"}, {"id": "L12-HK2-04-C06", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Tự tiện bóc mở, thu giữ, tiêu hủy thư tín của người khác là xâm phạm quyền nào dưới đây của công dân?", "o": ["Quyền bất khả xâm phạm về chỗ ở.", "Quyền được đảm bảo an toàn nơi cư trú.", "Đảm bảo an toàn thư tín, điện thoại, điện tín.", "Quyền bất khả xâm phạm về thân thể."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: 04_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 4.docx · Phần I câu 6 · khoá: gạch chân, khớp file ĐÁP ÁN"}, {"id": "L12-HK2-04-C07", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Trong nền kinh tế thị trường người mua hàng hóa, dịch vụ để thỏa mãn nhu cầu tiêu dùng cho sinh hoạt, sản xuất là", "o": ["chủ thể sản xuất.", "chủ thể tiêu dùng.", "chủ thể trung gian.", "chủ thể nhà nước.."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: 04_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 4.docx · Phần I câu 7 · khoá: gạch chân, khớp file ĐÁP ÁN"}, {"id": "L12-HK2-04-C08", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Sự tranh đua giữa các chủ thể kinh tế nhằm có được những ưu thế trong sản xuất, tiêu thụ hàng hóa, qua đó thu được lợi ích tối đa là nội dung của khái niệm nào dưới đây?", "o": ["Lợi tức.", "Tranh giành.", "Cạnh tranh.", "Đấu tranh."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: 04_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 4.docx · Phần I câu 8 · khoá: gạch chân, khớp file ĐÁP ÁN"}, {"id": "L12-HK2-04-C09", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Theo quy định của pháp luật, nếu lần đầu tiến hành khiếu nại, người khiếu nại nếu không đồng ý với quyết định giải quyết khiếu nại của cơ quan có thẩm quyền thì có quyền", "o": ["tố cáo cơ quan chức năng.", "sử dụng các biện pháp bạo lực.", "khiếu nại tiếp lần thứ hai.", "từ chối không thực hiện."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: 04_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 4.docx · Phần I câu 9 · khoá: gạch chân, khớp file ĐÁP ÁN"}, {"id": "L12-HK2-04-C10", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Việc Việt Nam gia nhập Tổ chức Thương mại Thế giới thể hiện tham gia cấp độ hội nhập nào dưới đây?", "o": ["Hội nhập toàn cầu.", "Hội nhập khu vực.", "Hội nhập song phương.", "Hội nhập đa phương."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: 04_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 4.docx · Phần I câu 10 · khoá: gạch chân, khớp file ĐÁP ÁN"}, {"id": "L12-HK2-04-C11", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Trong quá trình lập kế hoạch kinh doanh, việc nào sau đây là quan trọng để đảm bảo tính khả thi của kế hoạch?", "o": ["Phân tích điểm mạnh, điểm yếu, cơ hội, rủi ro.", "Chuẩn bị một kế hoạch marketing chi tiết.", "Xác định mục tiêu và chiến lược kinh doanh phù hợp.", "Quyết định mức giá bán sản phẩm, dịch vụ."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: 04_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 4.docx · Phần I câu 11 · khoá: gạch chân, khớp file ĐÁP ÁN"}, {"id": "L12-HK2-04-C12", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Nội dung nào dưới đây thể hiện ý nghĩa của việc thực hiện trách nhiệm xã hội của doanh nghiệp đối với doanh nghiệp?", "o": ["Giúp ổn định cuộc sống cộng đồng.", "Góp phần bảo vệ môi trường sống.", "Nâng cao thương hiệu và uy tín doanh nghiệp.", "Hỗ trợ giải quyết những khó khăn của cộng đồng."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: 04_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 4.docx · Phần I câu 12 · khoá: gạch chân, khớp file ĐÁP ÁN"}, {"id": "L12-HK2-04-C13", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Khi tiến hành hoạt động kinh doanh, chủ doanh nghiệp luôn suy nghĩ để vạch ra chiến lược kinh doanh cho công ty của mình, điều này phản ánh năng lực nào dưới đây của chủ thể kinh doanh?", "o": ["Năng lực quốc tế.", "Năng lực giao tiếp.", "Năng lực lãnh đạo.", "Năng lực làm việc nhóm."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: 04_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 4.docx · Phần I câu 13 · khoá: ĐÃ TỰ GIẢI LẠI (đối chiếu SGK)"}, {"id": "L12-HK2-04-C14", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Căn cứ vào mức độ lạm phát, có những loại lạm phát nào?", "o": ["Có 2 loại lạm phát: lạm phát vừa phải, siêu lạm phát.", "Có 3 loại lạm phát: lạm phát vừa phải, lạm phát phi mã, siêu lạm phát.", "Có 3 loại lạm phát: lạm phát nhẹ, lạm phát vừa, siêu lạm phát.", "Có 2 loại lạm phát: lạm phát nhẹ và siêu lạm phát."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: 04_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 4.docx · Phần I câu 14 · khoá: gạch chân, khớp file ĐÁP ÁN"}, {"id": "L12-HK2-04-C15", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Nguyên nhân nào dưới đây là nguyên nhân chủ quan dẫn đến người lao động có nguy cơ lâm vào tình trạng thất nghiệp?", "o": ["Do cơ sở kinh doanh đóng cửa.", "Mất cân đối cung cầu lao động.", "Bị kỷ luật do vi phạm hợp đồng.", "Nền kinh tế rơi vào khủng hoảng."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: 04_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 4.docx · Phần I câu 15 · khoá: gạch chân, khớp file ĐÁP ÁN"}, {"id": "L12-HK2-04-C16", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Tổng thể các quy phạm pháp luật, các nguyên tắc, định hướng pháp luật có mối liên hệ mật thiết và thống nhất với nhau, được sắp xếp thành các ngành luật, các chế định pháp luật và được thể hiện trong các văn bản do cơ quan nhà nước có thẩm quyền ban hành theo những hình thức, thủ tục nhất định để điều chỉnh các quan hệ xã hội phát sinh trên lãnh thổ Việt Nam là đề cập đến khái niệm nào sau đây?", "o": ["Quy phạm pháp luật Việt Nam.", "Hệ thống pháp luật Việt Nam.", "Hệ thống chính trị Việt Nam.", "Thực hiện pháp luật Việt Nam."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: 04_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 4.docx · Phần I câu 16 · khoá: gạch chân, khớp file ĐÁP ÁN"}, {"id": "L12-HK2-04-C17", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Một trong những căn cứ quan trọng để thực hiện hình thức tín dụng cho vay thế chấp được thực hiện là người vay phải có", "o": ["đầy đủ quan hệ nhân thân.", "tài sản đảm bảo.", "địa vị chính trị.", "tư cách pháp nhân."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: 04_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 4.docx · Phần I câu 17 · khoá: gạch chân, khớp file ĐÁP ÁN"}, {"id": "L12-HK2-04-C18", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đọc đoạn thông tin sau và trả lời câu hỏi 18,19\nCông ty V chuyên sản xuất kinh doanh các sản phẩm sữa, thường xuyên cải tiến mẫu mã, đảm bảo chất lượng sản phẩm cung cấp ra thị trường, kê khai và nộp thuế đầy đủ. Doanh nghiệp đã tham gia chương trình sữa học đường, mang sữa đến các trường mầm non, tiểu học tại nhiều địa phương, phát động cán bộ nhân viên quyên góp, giúp đỡ người dân vùng bị thiên tai vượt qua khó khăn và khắc phục hậu quả sau bão lũ,...\nNội dung nào dưới đây phản ánh việc thực hiện trách nhiệm pháp lý của công ty V?", "o": ["Đảm bảo chất lượng sản phẩm.", "Kê khai và nộp thuế đầy đủ.", "Cải tiễn mẫu mã sản phẩm.", "Tham gia dự án sữa miễn phí."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: 04_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 4.docx · Phần I câu 18 · khoá: gạch chân, khớp file ĐÁP ÁN"}, {"id": "L12-HK2-04-C19", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đọc đoạn thông tin sau và trả lời câu hỏi 18,19\nCông ty V chuyên sản xuất kinh doanh các sản phẩm sữa, thường xuyên cải tiến mẫu mã, đảm bảo chất lượng sản phẩm cung cấp ra thị trường, kê khai và nộp thuế đầy đủ. Doanh nghiệp đã tham gia chương trình sữa học đường, mang sữa đến các trường mầm non, tiểu học tại nhiều địa phương, phát động cán bộ nhân viên quyên góp, giúp đỡ người dân vùng bị thiên tai vượt qua khó khăn và khắc phục hậu quả sau bão lũ,...\nHoạt động tham gia chương trình sữa học đường, mang sữa đến các trường mầm non, tiểu học tại nhiều địa phương là thể hiện trách nhiệm nào dưới đây của công ty?", "o": ["Trách nhiệm kinh tế.", "Trách nhiệm đạo đức.", "Trách nhiệm pháp lý.", "Trách nhiệm nhân văn."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: 04_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 4.docx · Phần I câu 19 · khoá: gạch chân, khớp file ĐÁP ÁN"}, {"id": "L12-HK2-04-C20", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đọc thông tin và trả lời các câu hỏi 20,21,22\nSau khi tốt nghiệp đại học ngành công nghệ sinh học, với lợi thế là nhà gần các trường đại học, lại có diện tích đất lớn, chị D quyết định lập nghiệp bằng con đường kinh doanh sản phẩm cây cảnh mi ni với mong muốn sau hai năm sẽ thành lập một doanh nghiệp phân phối các sản phẩm này. Xác định, đây là lĩnh vực kinh doanh không đòi hỏi vốn lớn, trong khi thị trường là các bạn sinh viên có nhu cầu khá cao về loại sản phẩm này, lại không đòi hỏi phải thuê nhiều lao động. Khi bắt tay vào thực hiện công việc kinh doanh, chị đã tìm các nguồn hàng ở nhiều nơi có truyền thống kinh doanh cây cảnh để nhập về khá, ngoài việc thuê một cửa hàng gần trường đại học để bán và giới thiệu sản phẩm, chị D còn ứng dụng các nền tảng mạng xã hội để đăng và quảng bá sản phẩm. Do thời gian đầu chưa có nhiều kinh nghiệm, nên sản phẩm chị cung cấp nhiều cây gặp sâu bệnh chết, đối tượng khách hàng chưa thực sự nhiều, vốn bỏ ra tuy được bảo toàn nhưng lợi nhuận không cao.  Từ thực tế kinh doanh, chị quyết định mở rộng sản xuất và lên kế hoạch đầu tư thêm nhiều cửa hàng mới cũng như phát triển kênh truyền thống nhằm mở rộng thị trường.\nNội dung nào dưới đây thể hiện chị D đã biết xác định ý tưởng khi lập kế hoạch kinh doanh?", "o": ["Mở cửa hàng để bán.", "Thuê lao động bán hàng.", "Sử dụng mạng xã hội.", "Kinh doanh cây cảnh."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: 04_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 4.docx · Phần I câu 20 · khoá: gạch chân, khớp file ĐÁP ÁN"}, {"id": "L12-HK2-04-C21", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đọc thông tin và trả lời các câu hỏi 20,21,22\nSau khi tốt nghiệp đại học ngành công nghệ sinh học, với lợi thế là nhà gần các trường đại học, lại có diện tích đất lớn, chị D quyết định lập nghiệp bằng con đường kinh doanh sản phẩm cây cảnh mi ni với mong muốn sau hai năm sẽ thành lập một doanh nghiệp phân phối các sản phẩm này. Xác định, đây là lĩnh vực kinh doanh không đòi hỏi vốn lớn, trong khi thị trường là các bạn sinh viên có nhu cầu khá cao về loại sản phẩm này, lại không đòi hỏi phải thuê nhiều lao động. Khi bắt tay vào thực hiện công việc kinh doanh, chị đã tìm các nguồn hàng ở nhiều nơi có truyền thống kinh doanh cây cảnh để nhập về khá, ngoài việc thuê một cửa hàng gần trường đại học để bán và giới thiệu sản phẩm, chị D còn ứng dụng các nền tảng mạng xã hội để đăng và quảng bá sản phẩm. Do thời gian đầu chưa có nhiều kinh nghiệm, nên sản phẩm chị cung cấp nhiều cây gặp sâu bệnh chết, đối tượng khách hàng chưa thực sự nhiều, vốn bỏ ra tuy được bảo toàn nhưng lợi nhuận không cao.  Từ thực tế kinh doanh, chị quyết định mở rộng sản xuất và lên kế hoạch đầu tư thêm nhiều cửa hàng mới cũng như phát triển kênh truyền thống nhằm mở rộng thị trường.\nViệc làm nào dưới đây thể hiện khả năng phân tích các điều kiện thực hiện ý tưởng kinh doanh của chị D?", "o": ["Thành lập doanh nghiệp sau hai năm.", "Thiếu kinh nghiệm nên chưa thành công.", "Lựa chọn kinh doanh cây cảnh.", "Nhu cầu về mặt hàng cây cảnh lớn."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: 04_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 4.docx · Phần I câu 21 · khoá: gạch chân, khớp file ĐÁP ÁN"}, {"id": "L12-HK2-04-C22", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đọc thông tin và trả lời các câu hỏi 20,21,22\nSau khi tốt nghiệp đại học ngành công nghệ sinh học, với lợi thế là nhà gần các trường đại học, lại có diện tích đất lớn, chị D quyết định lập nghiệp bằng con đường kinh doanh sản phẩm cây cảnh mi ni với mong muốn sau hai năm sẽ thành lập một doanh nghiệp phân phối các sản phẩm này. Xác định, đây là lĩnh vực kinh doanh không đòi hỏi vốn lớn, trong khi thị trường là các bạn sinh viên có nhu cầu khá cao về loại sản phẩm này, lại không đòi hỏi phải thuê nhiều lao động. Khi bắt tay vào thực hiện công việc kinh doanh, chị đã tìm các nguồn hàng ở nhiều nơi có truyền thống kinh doanh cây cảnh để nhập về khá, ngoài việc thuê một cửa hàng gần trường đại học để bán và giới thiệu sản phẩm, chị D còn ứng dụng các nền tảng mạng xã hội để đăng và quảng bá sản phẩm. Do thời gian đầu chưa có nhiều kinh nghiệm, nên sản phẩm chị cung cấp nhiều cây gặp sâu bệnh chết, đối tượng khách hàng chưa thực sự nhiều, vốn bỏ ra tuy được bảo toàn nhưng lợi nhuận không cao.  Từ thực tế kinh doanh, chị quyết định mở rộng sản xuất và lên kế hoạch đầu tư thêm nhiều cửa hàng mới cũng như phát triển kênh truyền thống nhằm mở rộng thị trường.\nChị D đã xác định cho mình mục tiêu kinh doanh là", "o": ["mở rộng sản xuất.", "thành lập doanh nghiệp.", "lập thân, lập nghiệp.", "đẩy mạnh truyền thông."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: 04_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 4.docx · Phần I câu 22 · khoá: gạch chân, khớp file ĐÁP ÁN"}, {"id": "L12-HK2-04-C23", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đọc đoạn thông tin sau và trả lời câu hỏi 23,24\nKhi biết có một căn nhà cũ bán với giá rẻ, anh T liền lên kế hoạch dự trù tài chính, mua lại căn nhà đó để sửa chữa và cho thuê với giá hợp lí. Cách thức này vừa giúp gia đình anh có thêm nguồn thu nhập vừa giữ được tài sản hiện có của anh. Bên cạnh đó, anh T dành một khoản lớn thu nhập cho mục tiêu tiết kiệm. Anh chi tiêu ở mức tối thiểu cho sinh hoạt hằng ngày với các nhu cầu thiết yếu. Anh quan niệm rằng chỉ có tiết kiệm mới có thể thực hiện được mục tiêu mua nhà, mua xe,... Vì vậy, anh hạn chế giao tiếp, không mở rộng quan hệ xã hội để tránh các khoản chi không cần thiết, không mang lại cho anh lợi ích gì.\nNội dung nào dưới đây thể hiện anh T chưa biết phân chia một cách phù hợp giữa các khoản chi tiêu thiết yếu và không thiết yếu?", "o": ["Mua nhà và sửa lại cho thuê.", "Tiết kiệm dùng để mua nhà.", "Bảo toàn tài sản hiện có.", "Dành khoản lớn để tiết kiệm."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: 04_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 4.docx · Phần I câu 23 · khoá: gạch chân, khớp file ĐÁP ÁN"}, {"id": "L12-HK2-04-C24", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đọc đoạn thông tin sau và trả lời câu hỏi 23,24\nKhi biết có một căn nhà cũ bán với giá rẻ, anh T liền lên kế hoạch dự trù tài chính, mua lại căn nhà đó để sửa chữa và cho thuê với giá hợp lí. Cách thức này vừa giúp gia đình anh có thêm nguồn thu nhập vừa giữ được tài sản hiện có của anh. Bên cạnh đó, anh T dành một khoản lớn thu nhập cho mục tiêu tiết kiệm. Anh chi tiêu ở mức tối thiểu cho sinh hoạt hằng ngày với các nhu cầu thiết yếu. Anh quan niệm rằng chỉ có tiết kiệm mới có thể thực hiện được mục tiêu mua nhà, mua xe,... Vì vậy, anh hạn chế giao tiếp, không mở rộng quan hệ xã hội để tránh các khoản chi không cần thiết, không mang lại cho anh lợi ích gì.\nViệc làm nào dưới đây thể hiện anh T đã biết bổ thu nguồn thu nhập cho gia đình?", "o": ["Tập trung vào tiền tiết kiệm.", "Giảm chi tiêu thiết yếu.", "Hạn chế giao tiếp bạn bè.", "Mua nhà rồi cho thuê lại."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: 04_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 4.docx · Phần I câu 24 · khoá: gạch chân, khớp file ĐÁP ÁN"}, {"id": "L12-HK2-04-C25", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "dung_sai", "status": "cho_duyet", "q": "Từ ngày 13 - 17/6/2022, tại Thủ đô Phnom Penh, Campuchia đã diễn ra Cuộc họp hai Chủ tịch Ủy ban liên hợp biên giới Việt Nam - Campuchia, Campuchia - Việt Nam. Tại Cuộc họp, hai bên đã trao đổi một số nội dung liên quan đến việc bảo đảm sự ổn định của đường biên, mốc giới nhằm góp phần củng cố và xây dựng đường biên giới hòa bình, ổn định, hữu nghị và hợp tác cùng phát triển giữa hai nước như: kế hoạch xử lý các cột mốc cũ còn tồn tại trên thực địa tại các khu vực đã hoàn thành phân giới cắm mốc (bao gồm việc dỡ bỏ và giữ lại một số cột mốc để làm chứng tích lịch sử và tạo thuận lợi cho công tác quản lý biên giới); xử lý, khắc phục một số mốc biên giới bị hư hỏng, sạt lở hoặc có nguy cơ sạt lở; khảo sát thực địa, cắm thêm một số cọc đánh dấu điểm đặc trưng làm rõ hướng đi của đường biên giới trên thực địa tại một số khu vực đã hoàn thành phân giới cắm mốc nhưng vẫn có khó khăn trong việc nhận biết. Hai bên khẳng định quyết tâm và nỗ lực tìm giải pháp công bằng, hợp lý mà hai bên cùng chấp nhận được để phân giới cắm mốc đối với 16% đường biên giới còn lại; đồng thời, nhất trí về sự cần thiết xây dựng Hiệp định về quy chế biên giới mới để thay thế cho Hiệp định về quy chế biên giới ký năm 1983 nhằm tạo thuận lợi cho công tác phối hợp quản lý biên giới chung.", "o": ["Xây dựng đường biên giới hòa bình, ổn định, hữu nghị và hợp tác cùng phát triển giữa hai nước Việt Nam – Campuchia là trách nhiệm của Nhà nước và nhân dân cả hai nước.", "Hai nước Việt Nam – Campuchia phối hợp với nhau trong công tác quản lý biên giới chung là thực hiện đúng quy định của pháp luật quốc tế.", "Khảo sát thực địa, cắm thêm một số cọc đánh dấu điểm đặc trưng làm rõ hướng đi của đường biên giới trên thực địa là việc làm cần thiết.", "Đường biên giới trên đất liền giữa hai nước không cần thể hiện trên bản đồ."], "a": [true, true, true, false], "e": "Đáp án: a) Đúng; b) Đúng; c) Đúng; d) Sai.", "nguon": "Đề nguồn: 04_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 4.docx · Phần II câu 1 · khoá: file ĐÁP ÁN"}, {"id": "L12-HK2-04-C26", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "dung_sai", "status": "cho_duyet", "q": "Năm 1979, một cuộc cách mạng nổi dậy ở Nicaragua thành công đưa Phong trào Sadino lên nắm quyền. Hoa Kỳ từ lâu đã chống đối Sadino, nên sau khi lực lượng Sadino lên nắm quyền, chính quyền Tổng thống Carter nhanh chóng hành động, ủng hộ tài chính cho phe đối lập để chống đối chính phủ của Phong trào Sadino ở Nicaragua. Khi ông Ronald Reagan làm Tổng thống, ông gia tăng hỗ trợ cho các nhóm Contras chống Sandino, thông qua ủng hộ tài chính, huấn luyện quân sự với âm mưu bạo động lật đổ chính phủ Sandino ở Nicaragua. Nicagua kiện Hoa Kỳ lên Toà án Công lí quốc tế. Năm 1986, Toà án Công lí quốc tế ra phán quyết, rằng Hoa Kỳ đã không tuân thủ trách nhiệm đối với pháp luật quốc tế.", "o": ["Tòa án công lý quốc tế là cơ quan tư pháp trong hệ thống pháp luật quốc tế.", "Việc Hoa Kỳ can thiệp ủng hộ tài chính cho phe đối lập để chống đối chính phủ của Phong trào Sadino ở Nicaragua la vi phạm nguyên tắc sử dụng vũ lực trong quan hệ quốc tế.", "Hoạt động ủnh hộ tài chính, huấn luyện quan sự với âm mưu bạo động lật đổ chính phủ Sandino ở Nicaragua của Hoa Kỳ là vi phạm nghĩa vụ hợp tác với các quốc gia khác.", "Việc Toà án Công lí quốc tế ra phán quyết khẳng định Hoa Kỳ đã vi phạm luật pháp quốc tế là thể hiện vai trò của pháp luật quốc tế đối với các quốc gia."], "a": [true, false, false, true], "e": "Đáp án: a) Đúng; b) Sai; c) Sai; d) Đúng.", "nguon": "Đề nguồn: 04_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 4.docx · Phần II câu 2 · khoá: ĐÃ TỰ GIẢI LẠI (đối chiếu SGK)"}, {"id": "L12-HK2-04-C27", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "dung_sai", "status": "cho_duyet", "q": "Ông S là giám đốc công ty cổ phần sản xuất hàng công nghiệp. Trong quá trình sản xuất, ông đã chỉ đạo công ty làm mọi cách để giảm chi phí sản xuất nhằm tăng lợi nhuận cho công ty, kể cả việc bỏ qua trách nhiệm của công ty về bảo vệ môi trường như thải khí thải vượt quá mức quy định và xả nước thải chưa qua xử lí vào nguồn nước, gây ảnh hưởng nghiêm trọng đến sức khoẻ và đời sống của người dân khu vực xung quanh. Đối với sản phẩm của công ty, khi sản phẩm có chỗ đứng trong thị trường, ông S chỉ đạo công ty thay đổi một số lính kiện có giá rẻ hơn để lấp ráp vào sản phẩm, làm giảm chi phí sản xuất, tăng lợi nhuận cho công ty. Đối với người lao động, công ty đã ký hợp đồng thời vụ với một số lao động phổ thông để không phải đóng bảo hiểm xã hội cho họ đồng thời tạo điều kiện để họ được tự do di chuyển sang công ty khác nếu cần.", "o": ["Giám đốc S chưa thực hiện tốt trách nhiệm pháp lý và trách nhiệm đạo đức trong quá trình hoạt động sản xuất kinh doanh.", "Việc bỏ qua yếu tố về môi trường cũng như lắp ráp sản phẩm có giá rẻ hơn để tối ưu hóa lợi nhuận là phù hợp với trách nhiệm kinh tế của doanh nghiệp.", "Việc tạo điều để người lao động ký hợp đồng thời vụ và không phải đóng bảo hiểm xã hội là thể hiện trách nhiệm đạo đức của doanh nghiệp.", "Để xây dựng uy tín và thương hiệu cho công ty, ông S nên trích lợi nhuận để tham gia các hoạt động từ thiện nhân đạo."], "a": [true, false, false, false], "e": "Đáp án: a) Đúng; b) Sai; c) Sai; d) Sai.", "nguon": "Đề nguồn: 04_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 4.docx · Phần II câu 3 · khoá: file ĐÁP ÁN"}, {"id": "L12-HK2-04-C28", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "dung_sai", "status": "cho_duyet", "q": "Trên cùng địa bàn một huyện có anh D là chủ hai doanh nghiệp kinh doanh thức ăn chăn nuôi; anh K là giám đốc một công ty tư nhân có chị P là kế toán, còn anh V là nhân viên của anh K. Để tăng vốn kinh doanh, anh K chỉ đạo chị P là kế toán kê khai không đầy đủ số tiền thuế phải nộp của công ty nên anh K đã bị cơ quan chức năng xử phạt. Nghi ngờ anh V là tố cáo hành vi của mình, anh K cố tình trì hoãn đóng bảo hiểm xã hội cho anh V như đã cam kết. Bức xúc, anh V tự ý nghỉ việc ở công ty của anh K và sang làm việc cho anh D. Một lần chứng kiến anh D bị cơ quan chức năng xử phạt về hành vi cung cấp sản phẩm không đảm bảo đúng tiêu chuẩn đã công bố, anh V đã kể lại sự việc cho vợ mình là chị T. Vô tình phát hiện việc anh D bị xử phạt, chị P đã viết và đăng bài xuyên tạc về doanh nghiệp của anh D lên mạng xã hội khiến lượng khách hàng của anh D giảm sút", "o": ["Anh D và anh K đều được thực hiện quyền của công dân về kinh doanh.", "Anh K thực hiện tốt nghĩa vụ kinh doanh nhưng vi phạm nghĩa vụ nộp thuế đối.", "Anh K vừa vi phạm trách nhiệm kinh tế vừa vi phạm trách nhiệm pháp lý của doanh nghiệp khi tiến hành kinh doanh.", "Anh K và anh D đều chưa thực hiện tốt nghĩa vụ kinh doanh."], "a": [true, false, false, true], "e": "Đáp án: a) Đúng; b) Sai; c) Sai; d) Đúng.", "nguon": "Đề nguồn: 04_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 4.docx · Phần II câu 4 · khoá: file ĐÁP ÁN"}]}, {"id": "L12-HK2-05", "loai": "khoi", "khoi": 12, "hoc_ki": 2, "bo": "HK2", "ten_bo": "học kì II", "so_de": 5, "ten": "Lớp 12 · học kì II · Đề 5", "pham_vi": "Đề nguồn «CUỐI NĂM › 10 ĐỀ» · file nguồn: 05_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 5.docx", "thoi_gian": 50, "cau_truc": "24 câu trắc nghiệm + 4 câu đúng/sai (mỗi câu 4 ý)", "status": "cho_duyet", "khoa": {"khớp 2 nguồn": 24, "1 nguồn": 4}, "sua": "", "cau": [{"id": "L12-HK2-05-C01", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Yếu tố nào sau đây là chỉ tiêu của tăng trưởng kinh tế?", "o": ["Số lao động tham gia sản xuất.", "Sự gia tăng dân số của một quốc gia.", "Mức tăng tổng sản phẩm quốc nội.", "Tổng diện tích đất được sử dụng."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: 05_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 5.docx · Phần I câu 1 · khoá: gạch chân, khớp file ĐÁP ÁN"}, {"id": "L12-HK2-05-C02", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Theo quy định của pháp luật, khi thực hiện quyền tự do ngôn luận công dân có nghĩa vụ", "o": ["trình bày mọi quan điểm.", "xuyên tạc về mặt nội dung.", "tuân thủ quy định pháp luật.", "ủng hộ mọi quan điểm đưa ra."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: 05_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 5.docx · Phần I câu 2 · khoá: gạch chân, khớp file ĐÁP ÁN"}, {"id": "L12-HK2-05-C03", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Sự bảo đảm thay thế hoặc bù đắp một phần thu nhập của người lao động khi họ bị giảm hoặc mất thu nhập do ốm đau, tai nạn lao động, hết tuổi lao động,... trên cơ sở đóng vào quỹ bảo hiểm xã hội được gọi là", "o": ["bảo hiểm nhân thọ.", "bảo hiểm thất nghiệp.", "bảo hiểm xã hội.", "bảo hiểm y tế."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: 05_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 5.docx · Phần I câu 3 · khoá: gạch chân, khớp file ĐÁP ÁN"}, {"id": "L12-HK2-05-C04", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Mô hình sản xuất kinh doanh do cá nhân hoặc một nhóm người là công dân Việt Nam đủ 18 tuổi, có năng lực hành vi dân sự đầy đủ, hoặc một hộ gia đình làm chủ, tự tổ chức sản xuất kinh doanh theo định hướng phát triển kinh tế của nhà nước, địa phương và quy định của pháp luật, tự chủ trong quản lí và tiêu thụ sản phẩm được gọi là", "o": ["công ty hợp danh.", "liên hiệp hợp tác xã.", "hộ sản xuất kinh doanh.", "doanh nghiệp tư nhân."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: 05_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 5.docx · Phần I câu 4 · khoá: gạch chân, khớp file ĐÁP ÁN"}, {"id": "L12-HK2-05-C05", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Mọi công dân đều bình đẳng về nghĩa vụ trước pháp luật khi thực hiện hành vi nào sau đây?", "o": ["Đăng kí hồ sơ đấu thầu.", "Xây dựng nguồn quỹ xã hội.", "Bảo vệ an ninh quốc gia.", "Thay đổi địa bàn cư trú."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: 05_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 5.docx · Phần I câu 5 · khoá: gạch chân, khớp file ĐÁP ÁN"}, {"id": "L12-HK2-05-C06", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Tự tiện bóc mở, thu giữ, tiêu hủy thư tín của người khác là xâm phạm quyền nào dưới đây của công dân?", "o": ["Quyền bất khả xâm phạm về chỗ ở.", "Quyền được đảm bảo an toàn nơi cư trú.", "Đảm bảo an toàn thư tín, điện thoại, điện tín.", "Quyền bất khả xâm phạm về thân thể."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: 05_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 5.docx · Phần I câu 6 · khoá: gạch chân, khớp file ĐÁP ÁN"}, {"id": "L12-HK2-05-C07", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Trong các hoạt động dưới đây, hoạt động nào mà con người sử dụng các yếu tố sản xuất để tạo ra các sản phẩm đáp ứng nhu cầu của đời sống xã hội?", "o": ["Hoạt động sản xuất.", "Hoạt động trao đổi.", "Hoạt động tiêu dùng.", "Hoạt động phân phối."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: 05_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 5.docx · Phần I câu 7 · khoá: gạch chân, khớp file ĐÁP ÁN"}, {"id": "L12-HK2-05-C08", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Các hãng xe đua nhau tung ra các mẫu xe máy điện mới, với thiết kế đa dạng và tính năng hiện đại để thu được nhiều lợi nhuận là thể hiện sự", "o": ["tranh giành.", "phát triển.", "đấu tranh.", "cạnh tranh."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: 05_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 5.docx · Phần I câu 8 · khoá: gạch chân, khớp file ĐÁP ÁN"}, {"id": "L12-HK2-05-C09", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Theo quy định của pháp luật, nếu lần đầu tiến hành khiếu nại, người khiếu nại nếu không đồng ý với quyết định giải quyết khiếu nại của cơ quan có thẩm quyền thì có quyền", "o": ["tố cáo cơ quan chức năng.", "sử dụng các biện pháp bạo lực.", "khiếu nại tiếp lần thứ hai.", "từ chối không thực hiện."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: 05_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 5.docx · Phần I câu 9 · khoá: gạch chân, khớp file ĐÁP ÁN"}, {"id": "L12-HK2-05-C10", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Việc Việt Nam gia nhập Tổ chức Thương mại Thế giới thể hiện tham gia cấp độ hội nhập nào dưới đây?", "o": ["Hội nhập toàn cầu.", "Hội nhập khu vực.", "Hội nhập song phương.", "Hội nhập đa phương."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: 05_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 5.docx · Phần I câu 10 · khoá: gạch chân, khớp file ĐÁP ÁN"}, {"id": "L12-HK2-05-C11", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Kế hoạch kinh doanh xác định rõ sứ mệnh, tầm nhìn, chiến lược, công việc dự định thực hiện và cách đạt được", "o": ["mục tiêu kinh doanh.", "trách nhiệm kinh tế.", "trách nhiệm xã hội.", "mục tiêu xã hội."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: 05_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 5.docx · Phần I câu 11 · khoá: gạch chân, khớp file ĐÁP ÁN"}, {"id": "L12-HK2-05-C12", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Cam kết của doanh nghiệp đóng góp cho việc phát triển kinh tế bền vững thông qua những việc làm nâng cao chất lượng đời sống của người lao động, thân nhân người lao động, cộng đông, cho toàn xã hội theo cách có lợi cho cả doanh nghiệp cũng như phát triển chung cho cả xã hội được gọi là", "o": ["trách nhiệm xã hội của doanh nghiệp", "trách nhiệm kinh doanh của doanh nghiệp.", "nghĩa vụ xã hội của doanh nghiệp.", "nghĩa vụ kinh doanh của doanh nghiệp."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: 05_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 5.docx · Phần I câu 12 · khoá: gạch chân, khớp file ĐÁP ÁN"}, {"id": "L12-HK2-05-C13", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Các nguồn giúp tạo ý tưởng kinh doanh của chủ thể sản xuất kinh doanh xuất phát từ yếu tố nào dưới đây?", "o": ["Lợi thế nội tại và cơ hội bên ngoài.", "Điểm yếu nội tại và khó khăn bên ngoài.", "Mâu thuẫn của chủ thể sản xuất.", "Khó khăn của chủ thể sản xuất."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: 05_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 5.docx · Phần I câu 13 · khoá: gạch chân, khớp file ĐÁP ÁN"}, {"id": "L12-HK2-05-C14", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Trong nền kinh tế thị trường khi xuất hiện tình trạng lạm phát phi mã sẽ gây ra hiện tượng như thế nào đối với nền kinh tế đó?", "o": ["bất ổn nghiêm trọng.", "hiệu ứng tích cực.", "sụp đổ hoàn toàn.", "cung tăng liên tục."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: 05_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 5.docx · Phần I câu 14 · khoá: gạch chân, khớp file ĐÁP ÁN"}, {"id": "L12-HK2-05-C15", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Khi tham gia vào thị trường lao động, việc ký kết hợp đồng mua bán sức lao động giữa người bán sức lao động và người mua sức lao động được thực hiện theo nguyên tắc nào dưới đây?", "o": ["Tự nguyện.", "Cưỡng chế.", "Cưỡng bức.", "Tự giác."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: 05_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 5.docx · Phần I câu 15 · khoá: gạch chân, khớp file ĐÁP ÁN"}, {"id": "L12-HK2-05-C16", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Tổng thể các quy phạm pháp luật, các nguyên tắc, định hướng pháp luật có mối liên hệ mật thiết và thống nhất với nhau, được sắp xếp thành các ngành luật, các chế định pháp luật và được thể hiện trong các văn bản do cơ quan nhà nước có thẩm quyền ban hành theo những hình thức, thủ tục nhất định để điều chỉnh các quan hệ xã hội phát sinh trên lãnh thổ Việt Nam là đề cập đến khái niệm nào sau đây?", "o": ["Quy phạm pháp luật Việt Nam.", "Hệ thống pháp luật Việt Nam.", "Hệ thống chính trị Việt Nam.", "Thực hiện pháp luật Việt Nam."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: 05_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 5.docx · Phần I câu 16 · khoá: gạch chân, khớp file ĐÁP ÁN"}, {"id": "L12-HK2-05-C17", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Hình thức vay tín dụng ngân hàng nào sau đây người vay phải trả lãi hàng tháng và một phần nợ gốc?", "o": ["Vay trả góp.", "Vay tín chấp.", "Vay thấu chi.", "Vay thế chấp."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: 05_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 5.docx · Phần I câu 17 · khoá: gạch chân, khớp file ĐÁP ÁN"}, {"id": "L12-HK2-05-C18", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đọc đoạn thông tin sau và trả lời câu hỏi 18,19\nTính chung thời kì thực hiện Chiến lược phát triển kinh tế xã hội 10 năm (2011 - 2020), tăng trưởng GDP của Việt Nam đạt khoảng 5,9%/năm, thuộc nhóm các nước tăng trưởng cao trong khu vực. Quy mô GDP tăng gấp 2,4 lần, từ 116 tỉ USD năm 2010 lên 268,4 tỉ USD vào năm 2020. GDP bình quân đầu người tăng từ 1.331 USD năm 2010 lên khoảng 2.750 USD năm 2020. Tỉ lệ hộ nghèo cả nước giảm nhanh, từ 14,2% năm 2010 xuống còn 7% năm 2015 (theo chuẩn nghèo giai đoạn 2011 - 2015) và giảm từ 9,2% năm 2016 xuống dưới 3% vào năm 2020 (theo chuẩn nghèo đa chiều). Cơ sở hạ tầng thiết yếu ở các huyện nghèo, xã nghèo, vùng đồng bào dân tộc thiểu số được tăng cường. Thực hiện nhiều giải pháp tạo việc làm, nâng cao thu nhập cho người lao động\nNội dung nào dưới đây thể hiện tăng trưởng kinh tế là điều kiện vật chất để thực hiện phát triển bền vững được đề cập trong thông tin trên?", "o": ["Thuộc nhóm các nước tăng trưởng cao.", "Tốc độ tăng dân số phù hợp với.", "Tạo việc làm và nâng cao thu nhập.", "Giảm tỷ lệ lạm phát, giá cả được kiểm soát."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: 05_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 5.docx · Phần I câu 18 · khoá: gạch chân, khớp file ĐÁP ÁN"}, {"id": "L12-HK2-05-C19", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đọc đoạn thông tin sau và trả lời câu hỏi 18,19\nTính chung thời kì thực hiện Chiến lược phát triển kinh tế xã hội 10 năm (2011 - 2020), tăng trưởng GDP của Việt Nam đạt khoảng 5,9%/năm, thuộc nhóm các nước tăng trưởng cao trong khu vực. Quy mô GDP tăng gấp 2,4 lần, từ 116 tỉ USD năm 2010 lên 268,4 tỉ USD vào năm 2020. GDP bình quân đầu người tăng từ 1.331 USD năm 2010 lên khoảng 2.750 USD năm 2020. Tỉ lệ hộ nghèo cả nước giảm nhanh, từ 14,2% năm 2010 xuống còn 7% năm 2015 (theo chuẩn nghèo giai đoạn 2011 - 2015) và giảm từ 9,2% năm 2016 xuống dưới 3% vào năm 2020 (theo chuẩn nghèo đa chiều). Cơ sở hạ tầng thiết yếu ở các huyện nghèo, xã nghèo, vùng đồng bào dân tộc thiểu số được tăng cường. Thực hiện nhiều giải pháp tạo việc làm, nâng cao thu nhập cho người lao động\nYếu tố nào được đề cập trong thông tin trên là nhân tố quyết định việc thực hiện các chỉ tiêu phát triển kinh tế về mặt xã hội?", "o": ["Tăng trưởng dân số.", "Tốc độ tăng lạm phát.", "Tăng trưởng việc làm.", "Tăng trưởng kinh tế."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: 05_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 5.docx · Phần I câu 19 · khoá: gạch chân, khớp file ĐÁP ÁN"}, {"id": "L12-HK2-05-C20", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đọc thông tin và trả lời các câu hỏi 20,21,22\nSau khi tốt nghiệp đại học ngành công nghệ sinh học, với lợi thế là nhà gần các trường đại học, lại có diện tích đất lớn, chị D quyết định lập nghiệp bằng con đường kinh doanh sản phẩm cây cảnh mi ni với mong muốn sau hai năm sẽ thành lập một doanh nghiệp phân phối các sản phẩm này. Xác định, đây là lĩnh vực kinh doanh không đòi hỏi vốn lớn, trong khi thị trường là các bạn sinh viên có nhu cầu khá cao về loại sản phẩm này, lại không đòi hỏi phải thuê nhiều lao động. Khi bắt tay vào thực hiện công việc kinh doanh, chị đã tìm các nguồn hàng ở nhiều nơi có truyền thống kinh doanh cây cảnh để nhập về khá, ngoài việc thuê một cửa hàng gần trường đại học để bán và giới thiệu sản phẩm, chị D còn ứng dụng các nền tảng mạng xã hội để đăng và quảng bá sản phẩm. Do thời gian đầu chưa có nhiều kinh nghiệm, nên sản phẩm chị cung cấp nhiều cây gặp sâu bệnh chết, đối tượng khách hàng chưa thực sự nhiều, vốn bỏ ra tuy được bảo toàn nhưng lợi nhuận không cao.  Từ thực tế kinh doanh, chị quyết định mở rộng sản xuất và lên kế hoạch đầu tư thêm nhiều cửa hàng mới cũng như phát triển kênh truyền thống nhằm mở rộng thị trường.\nNội dung nào dưới đây thể hiện chị D đã biết xác định ý tưởng khi lập kế hoạch kinh doanh?", "o": ["Mở cửa hàng để bán.", "Thuê lao động bán hàng.", "Sử dụng mạng xã hội.", "Kinh doanh cây cảnh."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: 05_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 5.docx · Phần I câu 20 · khoá: gạch chân, khớp file ĐÁP ÁN"}, {"id": "L12-HK2-05-C21", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đọc thông tin và trả lời các câu hỏi 20,21,22\nSau khi tốt nghiệp đại học ngành công nghệ sinh học, với lợi thế là nhà gần các trường đại học, lại có diện tích đất lớn, chị D quyết định lập nghiệp bằng con đường kinh doanh sản phẩm cây cảnh mi ni với mong muốn sau hai năm sẽ thành lập một doanh nghiệp phân phối các sản phẩm này. Xác định, đây là lĩnh vực kinh doanh không đòi hỏi vốn lớn, trong khi thị trường là các bạn sinh viên có nhu cầu khá cao về loại sản phẩm này, lại không đòi hỏi phải thuê nhiều lao động. Khi bắt tay vào thực hiện công việc kinh doanh, chị đã tìm các nguồn hàng ở nhiều nơi có truyền thống kinh doanh cây cảnh để nhập về khá, ngoài việc thuê một cửa hàng gần trường đại học để bán và giới thiệu sản phẩm, chị D còn ứng dụng các nền tảng mạng xã hội để đăng và quảng bá sản phẩm. Do thời gian đầu chưa có nhiều kinh nghiệm, nên sản phẩm chị cung cấp nhiều cây gặp sâu bệnh chết, đối tượng khách hàng chưa thực sự nhiều, vốn bỏ ra tuy được bảo toàn nhưng lợi nhuận không cao.  Từ thực tế kinh doanh, chị quyết định mở rộng sản xuất và lên kế hoạch đầu tư thêm nhiều cửa hàng mới cũng như phát triển kênh truyền thống nhằm mở rộng thị trường.\nViệc làm nào dưới đây thể hiện khả năng phân tích các điều kiện thực hiện ý tưởng kinh doanh của chị D?", "o": ["Thành lập doanh nghiệp sau hai năm.", "Thiếu kinh nghiệm nên chưa thành công.", "Lựa chọn kinh doanh cây cảnh.", "Nhu cầu về mặt hàng cây cảnh lớn."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: 05_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 5.docx · Phần I câu 21 · khoá: gạch chân, khớp file ĐÁP ÁN"}, {"id": "L12-HK2-05-C22", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đọc thông tin và trả lời các câu hỏi 20,21,22\nSau khi tốt nghiệp đại học ngành công nghệ sinh học, với lợi thế là nhà gần các trường đại học, lại có diện tích đất lớn, chị D quyết định lập nghiệp bằng con đường kinh doanh sản phẩm cây cảnh mi ni với mong muốn sau hai năm sẽ thành lập một doanh nghiệp phân phối các sản phẩm này. Xác định, đây là lĩnh vực kinh doanh không đòi hỏi vốn lớn, trong khi thị trường là các bạn sinh viên có nhu cầu khá cao về loại sản phẩm này, lại không đòi hỏi phải thuê nhiều lao động. Khi bắt tay vào thực hiện công việc kinh doanh, chị đã tìm các nguồn hàng ở nhiều nơi có truyền thống kinh doanh cây cảnh để nhập về khá, ngoài việc thuê một cửa hàng gần trường đại học để bán và giới thiệu sản phẩm, chị D còn ứng dụng các nền tảng mạng xã hội để đăng và quảng bá sản phẩm. Do thời gian đầu chưa có nhiều kinh nghiệm, nên sản phẩm chị cung cấp nhiều cây gặp sâu bệnh chết, đối tượng khách hàng chưa thực sự nhiều, vốn bỏ ra tuy được bảo toàn nhưng lợi nhuận không cao.  Từ thực tế kinh doanh, chị quyết định mở rộng sản xuất và lên kế hoạch đầu tư thêm nhiều cửa hàng mới cũng như phát triển kênh truyền thống nhằm mở rộng thị trường.\nChị D đã xác định cho mình mục tiêu kinh doanh là", "o": ["mở rộng sản xuất.", "thành lập doanh nghiệp.", "lập thân, lập nghiệp.", "đẩy mạnh truyền thông."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: 05_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 5.docx · Phần I câu 22 · khoá: gạch chân, khớp file ĐÁP ÁN"}, {"id": "L12-HK2-05-C23", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đọc đoạn thông tin sau và trả lời câu hỏi 23,24\nKhi biết có một căn nhà cũ bán với giá rẻ, anh T liền lên kế hoạch dự trù tài chính, mua lại căn nhà đó để sửa chữa và cho thuê với giá hợp lí. Cách thức này vừa giúp gia đình anh có thêm nguồn thu nhập vừa giữ được tài sản hiện có của anh. Bên cạnh đó, anh T dành một khoản lớn thu nhập cho mục tiêu tiết kiệm. Anh chi tiêu ở mức tối thiểu cho sinh hoạt hằng ngày với các nhu cầu thiết yếu. Anh quan niệm rằng chỉ có tiết kiệm mới có thể thực hiện được mục tiêu mua nhà, mua xe,... Vì vậy, anh hạn chế giao tiếp, không mở rộng quan hệ xã hội để tránh các khoản chi không cần thiết, không mang lại cho anh lợi ích gì.\nNội dung nào dưới đây thể hiện anh T chưa biết phân chia một cách phù hợp giữa các khoản chi tiêu thiết yếu và không thiết yếu?", "o": ["Mua nhà và sửa lại cho thuê.", "Tiết kiệm dùng để mua nhà.", "Bảo toàn tài sản hiện có.", "Dành khoản lớn để tiết kiệm."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: 05_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 5.docx · Phần I câu 23 · khoá: gạch chân, khớp file ĐÁP ÁN"}, {"id": "L12-HK2-05-C24", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đọc đoạn thông tin sau và trả lời câu hỏi 23,24\nKhi biết có một căn nhà cũ bán với giá rẻ, anh T liền lên kế hoạch dự trù tài chính, mua lại căn nhà đó để sửa chữa và cho thuê với giá hợp lí. Cách thức này vừa giúp gia đình anh có thêm nguồn thu nhập vừa giữ được tài sản hiện có của anh. Bên cạnh đó, anh T dành một khoản lớn thu nhập cho mục tiêu tiết kiệm. Anh chi tiêu ở mức tối thiểu cho sinh hoạt hằng ngày với các nhu cầu thiết yếu. Anh quan niệm rằng chỉ có tiết kiệm mới có thể thực hiện được mục tiêu mua nhà, mua xe,... Vì vậy, anh hạn chế giao tiếp, không mở rộng quan hệ xã hội để tránh các khoản chi không cần thiết, không mang lại cho anh lợi ích gì.\nViệc làm nào dưới đây thể hiện anh T đã biết bổ thu nguồn thu nhập cho gia đình?", "o": ["Tập trung vào tiền tiết kiệm.", "Giảm chi tiêu thiết yếu.", "Hạn chế giao tiếp bạn bè.", "Mua nhà rồi cho thuê lại."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: 05_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 5.docx · Phần I câu 24 · khoá: gạch chân, khớp file ĐÁP ÁN"}, {"id": "L12-HK2-05-C25", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "dung_sai", "status": "cho_duyet", "q": "Vị thế của Việt Nam trên thế giới đã được củng cố toàn diện trong giai đoạn 2011 - 2022. Cùng với quá trình hội nhập kinh tế quốc tế mạnh mẽ, đến năm 2020, Việt Nam có 30 đối tác chiến lược và đối tác chiến lược toàn diện; có quan hệ ngoại giao với 189/193 nước, có quan hệ kinh tế với 160 nước và 70 vùng lãnh thổ. Đến năm 2022, tổng số quan hệ kinh tế - thương mại của Việt Nam đã nâng lên thành 230 nước và vùng lãnh thổ. Với việc thực hiện chủ trương hội nhập quốc tế toàn diện với trọng tâm là hội nhập kinh tế quốc tế, vị thế của đất nước tiếp tục được cải thiện đáng kể. Có thể khẳng định, hội nhập kinh tế quốc tế đóng góp quan trọng vào việc mở rộng và đưa quan hệ của nước ta với các đối tác đi vào chiều sâu, tạo thế đan xen lợi ích, góp phần gìn giữ môi trường hòa bình, ổn định để phát triển đất nước; nâng cao uy tín và vị thế của Việt Nam trên trường quốc tế.", "o": ["Việc thiết lập quan hệ đối tác chiến lược và chiến lực toàn diện là thể hiện hình thức hội nhập kinh tế quốc tế ở cấp độ khu vực.", "Hội nhập kinh tế quốc tế không góp phần thúc đẩy sự tăng trưởng GDP hàng năm ở Việt Nam.", "Nước ta đang phát triển vì vậy khi hội nhập kinh tế quốc tế Việt Nam phải chấp nhận từ bỏ lợi ích của mình để hội nhập.", "Hội nhập kinh tế quốc tế góp phần đưa hàng hóa của Việt Nam đến với các thị trường trên thế giới."], "a": [false, false, false, true], "e": "Đáp án: a) Sai; b) Sai; c) Sai; d) Đúng.", "nguon": "Đề nguồn: 05_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 5.docx · Phần II câu 1 · khoá: file ĐÁP ÁN"}, {"id": "L12-HK2-05-C26", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "dung_sai", "status": "cho_duyet", "q": "Năm 1979, một cuộc cách mạng nổi dậy ở Nicaragua thành công đưa Phong trào Sadino lên nắm quyền. Hoa Kỳ từ lâu đã chống đối Sadino, nên sau khi lực lượng Sadino lên nắm quyền, chính quyền Tổng thống Carter nhanh chóng hành động, ủng hộ tài chính cho phe đối lập để chống đối chính phủ của Phong trào Sadino ở Nicaragua. Khi ông Ronald Reagan làm Tổng thống, ông gia tăng hỗ trợ cho các nhóm Contras chống Sandino, thông qua ủng hộ tài chính, huấn luyện quân sự với âm mưu bạo động lật đổ chính phủ Sandino ở Nicaragua. Nicagua kiện Hoa Kỳ lên Toà án Công lí quốc tế. Năm 1986, Toà án Công lí quốc tế ra phán quyết, rằng Hoa Kỳ đã không tuân thủ trách nhiệm đối với pháp luật quốc tế.", "o": ["Tòa án công lý quốc tế là cơ quan tư pháp trong hệ thống pháp luật quốc tế.", "Việc Hoa Kỳ can thiệp ủng hộ tài chính cho phe đối lập để chống đối chính phủ của Phong trào Sadino ở Nicaragua la vi phạm nguyên tắc sử dụng vũ lực trong quan hệ quốc tế.", "Hoạt động ủng hộ tài chính, huấn luyện quan sự với âm mưu bạo động lật đổ chính phủ Sandino ở Nicaragua của Hoa Kỳ là vi phạm nghĩa vụ hợp tác với các quốc gia khác.", "Việc Toà án Công lí quốc tế ra phán quyết khẳng định Hoa Kỳ đã vi phạm luật pháp quốc tế là thể hiện vai trò của pháp luật quốc tế đối với các quốc gia."], "a": [true, false, false, true], "e": "Đáp án: a) Đúng; b) Sai; c) Sai; d) Đúng.", "nguon": "Đề nguồn: 05_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 5.docx · Phần II câu 2 · khoá: file ĐÁP ÁN"}, {"id": "L12-HK2-05-C27", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "dung_sai", "status": "cho_duyet", "q": "Ông S là giám đốc công ty cổ phần sản xuất hàng công nghiệp. Trong quá trình sản xuất, ông đã chỉ đạo công ty làm mọi cách để giảm chi phí sản xuất nhằm tăng lợi nhuận cho công ty, kể cả việc bỏ qua trách nhiệm của công ty về bảo vệ môi trường như thải khí thải vượt quá mức quy định và xả nước thải chưa qua xử lí vào nguồn nước, gây ảnh hưởng nghiêm trọng đến sức khoẻ và đời sống của người dân khu vực xung quanh. Đối với sản phẩm của công ty, khi sản phẩm có chỗ đứng trong thị trường, ông S chỉ đạo công ty thay đổi một số lính kiện có giá rẻ hơn để lấp ráp vào sản phẩm, làm giảm chi phí sản xuất, tăng lợi nhuận cho công ty. Đối với người lao động, công ty đã ký hợp đồng thời vụ với một số lao động phổ thông để không phải đóng bảo hiểm xã hội cho họ đồng thời tạo điều kiện để họ được tự do di chuyển sang công ty khác nếu cần.", "o": ["Giám đốc S chưa thực hiện tốt trách nhiệm pháp lý và trách nhiệm đạo đức trong quá trình hoạt động sản xuất kinh doanh.", "Việc bỏ qua yếu tố về môi trường cũng như lắp ráp sản phẩm có giá rẻ hơn để tối ưu hóa lợi nhuận là phù hợp với trách nhiệm kinh tế của doanh nghiệp.", "Việc tạo điều để người lao động ký hợp đồng thời vụ và không phải đóng bảo hiểm xã hội là thể hiện trách nhiệm đạo đức của doanh nghiệp.", "Để xây dựng uy tín và thương hiệu cho công ty, ông S nên trích lợi nhuận để tham gia các hoạt động từ thiện nhân đạo."], "a": [true, false, false, false], "e": "Đáp án: a) Đúng; b) Sai; c) Sai; d) Sai.", "nguon": "Đề nguồn: 05_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 5.docx · Phần II câu 3 · khoá: file ĐÁP ÁN"}, {"id": "L12-HK2-05-C28", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "dung_sai", "status": "cho_duyet", "q": "Trên cùng địa bàn một huyện có anh D là chủ hai doanh nghiệp kinh doanh thức ăn chăn nuôi; anh K là giám đốc một công ty tư nhân có chị P là kế toán, còn anh V là nhân viên của anh K. Để tăng vốn kinh doanh, anh K chỉ đạo chị P là kế toán kê khai không đầy đủ số tiền thuế phải nộp của công ty nên anh K đã bị cơ quan chức năng xử phạt. Nghi ngờ anh V là tố cáo hành vi của mình, anh K cố tình trì hoãn đóng bảo hiểm xã hội cho anh V như đã cam kết. Bức xúc, anh V tự ý nghỉ việc ở công ty của anh K và sang làm việc cho anh D. Một lần chứng kiến anh D bị cơ quan chức năng xử phạt về hành vi cung cấp sản phẩm không đảm bảo đúng tiêu chuẩn đã công bố, anh V đã kể lại sự việc cho vợ mình là chị T. Vô tình phát hiện việc anh D bị xử phạt, chị P đã viết và đăng bài xuyên tạc về doanh nghiệp của anh D lên mạng xã hội khiến lượng khách hàng của anh D giảm sút", "o": ["Anh D và anh K đều được thực hiện quyền của công dân về kinh doanh.", "Anh K thực hiện tốt nghĩa vụ kinh doanh nhưng vi phạm nghĩa vụ nộp thuế đối.", "Anh K vừa vi phạm trách nhiệm kinh tế vừa vi phạm trách nhiệm pháp lý của doanh nghiệp khi tiến hành kinh doanh.", "Anh K và anh D đều chưa thực hiện tốt nghĩa vụ kinh doanh."], "a": [true, false, false, true], "e": "Đáp án: a) Đúng; b) Sai; c) Sai; d) Đúng.", "nguon": "Đề nguồn: 05_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 5.docx · Phần II câu 4 · khoá: file ĐÁP ÁN"}]}, {"id": "L12-HK2-06", "loai": "khoi", "khoi": 12, "hoc_ki": 2, "bo": "HK2", "ten_bo": "học kì II", "so_de": 6, "ten": "Lớp 12 · học kì II · Đề 6", "pham_vi": "Đề nguồn «CUỐI NĂM › 10 ĐỀ» · file nguồn: 06_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 6.docx", "thoi_gian": 50, "cau_truc": "24 câu trắc nghiệm + 4 câu đúng/sai (mỗi câu 4 ý)", "status": "cho_duyet", "khoa": {"khớp 2 nguồn": 28}, "sua": "", "cau": [{"id": "L12-HK2-06-C01", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Chủ thể nào sau đây có vai trò điều tiết và tạo điều kiện thuận lợi cho các ngành kinh tế hoạt động sản xuất kinh doanh?", "o": ["Chủ thể nhà nước.", "Chủ thể tiêu dùng.", "Chủ thể sản xuất.", "Chủ thể trung gian."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: 06_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 6.docx · Phần I câu 1 · khoá: gạch chân, khớp file ĐÁP ÁN"}, {"id": "L12-HK2-06-C02", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Sử dụng pháp luật là việc các cá nhân, tổ chức sử dụng đúng các quyền của mình, làm những gì mà pháp luật", "o": ["đã bãi bỏ.", "chưa cho phép.", "cho phép làm.", "tuyệt đối cấm."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: 06_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 6.docx · Phần I câu 2 · khoá: gạch chân, khớp file ĐÁP ÁN"}, {"id": "L12-HK2-06-C03", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Việc một số lao động mất việc khi nền kinh tế rơi vào thời kì khủng hoảng, trì trệ được gọi là", "o": ["thất nghiệp tạm thời", "thất nghiệp chu kì", "thất nghiệp cơ cấu.", "thất nghiệp tự nguyện."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: 06_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 6.docx · Phần I câu 3 · khoá: gạch chân, khớp file ĐÁP ÁN"}, {"id": "L12-HK2-06-C04", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Biết đánh giá cơ hội kinh doanh, lựa chọn và chớp cơ hội kinh doanh là biểu hiện cho năng lực nào của người kinh doanh?", "o": ["Năng lực thực hiện trách nhiệm với xã hội.", "Năng lực chuyên môn.", "Năng lực định hướng chiến lược.", "Năng lực nắm bắt cơ hội."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: 06_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 6.docx · Phần I câu 4 · khoá: gạch chân, khớp file ĐÁP ÁN"}, {"id": "L12-HK2-06-C05", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Bất kỳ công dân nào nếu có đủ các điều kiện theo quy định của pháp luật đều bình đẳng về cơ hội học tập là thể hiện công dân bình đẳng về", "o": ["tập tục.", "quyền.", "trách nhiệm.", "nghĩa vụ."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: 06_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 6.docx · Phần I câu 5 · khoá: gạch chân, khớp file ĐÁP ÁN"}, {"id": "L12-HK2-06-C06", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Trong hội nghị tổng kết cuối năm, một số người dân xã S đã yêu cầu kế toán xã giải trình về khoản thu, chi quỹ \"Đền ơn đáp nghĩa\". Người dân xã S đã thực hiện đúng quyền dân chủ nào dưới đây?", "o": ["Tham gia quản lí nhà nước và xã hội.", "Tự do ngôn luận.", "Chủ động kiểm toán ngân sách quốc gia.", "Độc lập phán quyết."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: 06_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 6.docx · Phần I câu 6 · khoá: gạch chân, khớp file ĐÁP ÁN"}, {"id": "L12-HK2-06-C07", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Cụm từ GNI là một trong những chỉ tiêu thể hiện tốc độ tăng trưởng kinh tế, điều này thể hiện nội dung nào dưới đây?", "o": ["Tổng thu nhập quốc dân.", "Tổng thu nhập quốc dân theo đầu người.", "Tổng sản phẩm quốc nội theo đầu người.", "Tổng sản phẩm quốc nội."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: 06_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 6.docx · Phần I câu 7 · khoá: gạch chân, khớp file ĐÁP ÁN"}, {"id": "L12-HK2-06-C08", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Loại hình bảo hiểm do Nhà nước tổ chức nhằm bảo đảm thay thế hoặc bù đắp một phần thu nhập của người lao động khi họ bị giảm hoặc mất thu nhập do ốm, đau, thai sản, tai nạn lao động, bệnh nghề nghiệp, hết tuổi lao động dựa trên cơ sở mức đóng vào quỹ bảo hiểm xã hội của người lao động trước đó là loại hình bảo hiểm nào dưới đây?", "o": ["Bảo hiểm xã hội.", "Bảo hiểm dân sự.", "Bảo hiểm con người.", "Bảo hiểm thương mại."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: 06_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 6.docx · Phần I câu 8 · khoá: gạch chân, khớp file ĐÁP ÁN"}, {"id": "L12-HK2-06-C09", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Quyền sở hữu tài sản không bao gồm quyền nào sau đây", "o": ["Quyền tước đoạt.", "Quyền sử dụng.", "Quyền chiếm hữu.", "Quyền định đoạt."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: 06_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 6.docx · Phần I câu 9 · khoá: gạch chân, khớp file ĐÁP ÁN"}, {"id": "L12-HK2-06-C10", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Loại hình doanh nghiệp có từ 2 đến 50 thành viên là loại hình doanh nghiệp nào dưới đây?", "o": ["Công ty cổ phần.", "Doanh nghiệp tư nhân.", "Công ty trách nhiệm hữu hạn một thành viên.", "Công ty trách nhiệm hữu hạn hai thành viên trở lên"], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: 06_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 6.docx · Phần I câu 10 · khoá: gạch chân, khớp file ĐÁP ÁN"}, {"id": "L12-HK2-06-C11", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Trong hệ thống pháp luật của nước Việt Nam hiện nay, Hiến pháp năm 2013 giữ vị trí, vai trò như thế nào?", "o": ["Luật cơ bản của Nhà nước.", "Pháp luật cơ bản của Nhà nước.", "Luật thiết yếu của Nhà nước.", "Luật thứ cấp của Nhà nước."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: 06_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 6.docx · Phần I câu 11 · khoá: gạch chân, khớp file ĐÁP ÁN"}, {"id": "L12-HK2-06-C12", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Theo quy định của pháp luật hiện hành, người có hành vi xâm phạm tài sản của người khác sẽ chịu trách nhiệm pháp lý nào?", "o": ["Phạt tiền từ 1.000.000₫ đến 3.000.000₫.", "Phạt tù từ 06 tháng đến 03 năm.", "Cải tạo không giam giữ từ 12 tháng đến 18 tháng.", "Phạt tù từ 03 năm đến 07 năm."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: 06_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 6.docx · Phần I câu 12 · khoá: gạch chân, khớp file ĐÁP ÁN"}, {"id": "L12-HK2-06-C13", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Pháp luật quy định không ai bị bắt, nếu không có quyết định của Toà án, quyết định phê chuẩn của Viện kiểm sát, trừ trường hợp", "o": ["đã có chứng cứ rõ ràng, đầy đủ.", "gây khó khăn cho việc điều tra.", "phạm tội quả tang hoặc đang bị truy nã.", "cần ngăn chặn ngay người phạm tội bỏ trốn."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: 06_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 6.docx · Phần I câu 13 · khoá: gạch chân, khớp file ĐÁP ÁN"}, {"id": "L12-HK2-06-C14", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Khi tham gia vào thị trường lao động, người bán sức lao động và người mua sức lao động thỏa thuận nội dung nào dưới đây?", "o": ["Tiền công, tiền lương.", "Điều kiện đi nước ngoài.", "Điều kiện xuất khẩu lao động.", "Tiền môi giới lao động."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: 06_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 6.docx · Phần I câu 14 · khoá: gạch chân, khớp file ĐÁP ÁN"}, {"id": "L12-HK2-06-C15", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Sự khác nhau giữa việc cạnh tranh lành mạnh và cạnh tranh không lành mạnh là gì?", "o": ["Chúng đều là cạnh tranh không có sự khác nhau nào hết.", "Cạnh tranh lành mạnh tạo được ra giá trị tích cực thúc đẩy nhu cầu của xã hội, cạnh tranh không lành mạnh có thể có các ảnh hưởng tiêu cực đến đời sống xã hội.", "Việc cạnh tranh lành mạnh được khuyến khích để tạo ra môi trường cạnh tranh trong nền kinh tế thị trường.", "Cạnh tranh không lành mạnh nên bị lên án, phê phán."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: 06_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 6.docx · Phần I câu 15 · khoá: gạch chân, khớp file ĐÁP ÁN"}, {"id": "L12-HK2-06-C16", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đọc thông tin\nvà trả lời các câu hỏi bên dưới 16, 17\nBà H là lao động tự do sống trên địa bàn tỉnh Y. Sau một thời gian khám bệnh và điều trị tại bệnh viện K, bà H cầm trên tay hóa đơn, chứng từ thanh toán bảo hiểm y tế với số tiền 80 triệu đồng. Kết quả sau khi điều trị, bà đã được thanh toán gần một nửa chi phí điều trị gần 50 triệu đồng, thuộc đối tượng đồng chi trả 20%. Bà xúc động nói thêm: “Nhờ có sự tư vấn của cán bộ bảo hiểm xã hội, cách đây 5 tháng tôi có mua một tấm thẻ bảo hiểm y tế nay nhờ có tấm thẻ BHYT này mà tôi không trở thành gánh nặng tài chính của các con khi ốm đau, đến bây giờ bản thân tôi mới thấm thía cái câu khẩu hiệu: “BHYT đóng góp khi lành để dành khi ốm. Có thẻ BHYT, mình được lợi rất nhiều về viện phí, chất lượng khám chữa bệnh cũng tương đương với dịch vụ, tôi mong rằng mọi người nên tham gia BHYT để được bảo vệ và chăm sóc sức khỏe, bản thân, gia đình một cách tốt nhất”.\nLoại hình bảo hiểm mà bà H tham gia có đặc điểm là", "o": ["bắt buộc.", "được tài trợ.", "được vĩnh viễn.", "tự nguyện."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: 06_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 6.docx · Phần I câu 16 · khoá: gạch chân, khớp file ĐÁP ÁN"}, {"id": "L12-HK2-06-C17", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Nhờ có tham gia loại hình bảo hiểm đã mang lại lợi ích gì dưới đây cho bà H khi gặp rủi ro về ốm đau?", "o": ["Khám chữa bệnh chất lượng cao.", "Giảm gánh nặng tài chính gia đình.", "Được hỗ trợ tiền sau khi ra viện.", "Được khám miễn phí suốt đời."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: 06_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 6.docx · Phần I câu 17 · khoá: gạch chân, khớp file ĐÁP ÁN"}, {"id": "L12-HK2-06-C18", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Khi thực hiện việc quản lý thu chi trong gia đình sẽ giúp mỗi gia đình có thể chủ động", "o": ["tự do chi tiêu theo sở thích.", "ứng phó các tình huống rủi ro.", "chi tiêu ngoài kế hoạch đã định.", "tạo ra các quỹ ngoài kế hoạch."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: 06_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 6.docx · Phần I câu 18 · khoá: gạch chân, khớp file ĐÁP ÁN"}, {"id": "L12-HK2-06-C19", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Khi thống nhất tỷ lệ phân chia các khoản chi tiêu, các gia đình không cần phân chi tỷ lệ cho nội dung nào dưới đây?", "o": ["Chi thiết yếu.", "Chi nộp thuế nhà đất.", "Chi không thiết yếu.", "Chi tiết kiệm."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: 06_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 6.docx · Phần I câu 19 · khoá: gạch chân, khớp file ĐÁP ÁN"}, {"id": "L12-HK2-06-C20", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Hành vi nào dưới đây thực hiện đúng quy định của pháp luật về bảo vệ tài nguyên thiên nhiên?", "o": ["Sử dụng tiết kiệm điện, nước, khoáng sản,…", "Săn bắn, buôn bán động vật quý hiếm.", "Dùng mìn, kích điện để đánh bắt cá.", "Phá rừng nguyên sinh để trồng cà phê."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: 06_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 6.docx · Phần I câu 20 · khoá: gạch chân, khớp file ĐÁP ÁN"}, {"id": "L12-HK2-06-C21", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Hành vi vi phạm quy định của pháp luật về quyền và nghĩa vụ của công dân trong bảo vệ di sản văn hóa, môi trường và tài nguyên thiên nhiên phải chịu", "o": ["trách nhiệm dân sự, trách nhiệm hành chính, trách nhiệm kỉ luật", "trách nhiệm hành chính, trách nhiệm kỉ luật", "trách nhiệm dân sự, trách nhiệm hành chính.", "trách nhiệm dân sự, trách nhiệm hành chính, trách nhiệm kỉ luật, trách nhiệm hình sự."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: 06_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 6.docx · Phần I câu 21 · khoá: gạch chân, khớp file ĐÁP ÁN"}, {"id": "L12-HK2-06-C22", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đọc thông tin và trả lời các câu hỏi 22, 23, 24\nHội nhập kinh tế quốc tế đã tạo điều kiện cho Việt Nam đa dạng hóa các mặt hàng xuất khẩu. Trong đó, cà phê là một trong những sản phẩm thế mạnh của Việt Nam. Chỉ tính riêng trong nửa đầu năm 2024, Việt Nam đã xuất khẩu ước tính 1,1 triệu tấn cà phê với giá trị đạt 2,5 tỷ đô la Mỹ, tăng 35% về lượng và 45% về giá trị so với cùng kỳ năm trước. Tuy nhiên, một lô hàng của công ty cổ phần X bị phát hiện chứa chất bảo quản vượt mức cho phép. Phía đối tác yêu cầu công ty X bồi thường toàn bộ giá trị lô hàng nhưng công ty này không chấp nhận vì trong hợp đồng không quy định điều khoản này.\nTrong thông tin trên, hội nhập kinh tế quốc tế đem lại lợi ích nào sau đây cho các doanh nghiệp trong hoạt động xuất khẩu cà phê tại Việt Nam?", "o": ["Tăng giá trị xuất khẩu và nâng cao thương hiệu quốc gia.", "Đạt giá trị xuất khẩu 2,5 tỷ đô la Mỹ trong năm 2024.", "Tiếp cận thị trường và tăng giá trị xuất khẩu là 35%.", "Tạo cơ hội để các doanh nghiệp Việt Nam tham gia vào chuỗi cung ứng toàn cầu."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: 06_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 6.docx · Phần I câu 22 · khoá: gạch chân, khớp file ĐÁP ÁN"}, {"id": "L12-HK2-06-C23", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đọc thông tin và trả lời các câu hỏi 22, 23, 24\nHội nhập kinh tế quốc tế đã tạo điều kiện cho Việt Nam đa dạng hóa các mặt hàng xuất khẩu. Trong đó, cà phê là một trong những sản phẩm thế mạnh của Việt Nam. Chỉ tính riêng trong nửa đầu năm 2024, Việt Nam đã xuất khẩu ước tính 1,1 triệu tấn cà phê với giá trị đạt 2,5 tỷ đô la Mỹ, tăng 35% về lượng và 45% về giá trị so với cùng kỳ năm trước. Tuy nhiên, một lô hàng của công ty cổ phần X bị phát hiện chứa chất bảo quản vượt mức cho phép. Phía đối tác yêu cầu công ty X bồi thường toàn bộ giá trị lô hàng nhưng công ty này không chấp nhận vì trong hợp đồng không quy định điều khoản này.\nTheo quy định của pháp luật Việt Nam, hành vi vi phạm của công ty cổ phần X phải chịu trách nhiệm pháp lý nào sau đây?", "o": ["Buộc thu hồi sản phẩm và thay đổi quy trình sản xuất.", "Đền bù cho đối tác toàn bộ giá trị của lô hàng bị trả lại.", "Xử phạt hành chính và áp dụng hình phạt bổ sung theo quy định.", "Tước quyền xuất khẩu mặt hàng cà phê trong thời gian quy định."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: 06_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 6.docx · Phần I câu 23 · khoá: gạch chân, khớp file ĐÁP ÁN"}, {"id": "L12-HK2-06-C24", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đọc thông tin và trả lời các câu hỏi 22, 23, 24\nHội nhập kinh tế quốc tế đã tạo điều kiện cho Việt Nam đa dạng hóa các mặt hàng xuất khẩu. Trong đó, cà phê là một trong những sản phẩm thế mạnh của Việt Nam. Chỉ tính riêng trong nửa đầu năm 2024, Việt Nam đã xuất khẩu ước tính 1,1 triệu tấn cà phê với giá trị đạt 2,5 tỷ đô la Mỹ, tăng 35% về lượng và 45% về giá trị so với cùng kỳ năm trước. Tuy nhiên, một lô hàng của công ty cổ phần X bị phát hiện chứa chất bảo quản vượt mức cho phép. Phía đối tác yêu cầu công ty X bồi thường toàn bộ giá trị lô hàng nhưng công ty này không chấp nhận vì trong hợp đồng không quy định điều khoản này.\nTrong trường hợp trên, công ty cổ phần X nên lựa chọn phương thức giải quyết đầu tiên nào sau đây phù hợp với nguyên tắc hợp tác quốc tế với phía đối tác?", "o": ["Thương lượng với các bên liên quan để đạt thỏa thuận.", "Đàm phán trực tiếp với đại diện của tổ chức quốc tế.", "Đưa tranh chấp ra Tòa án quốc tế để giải quyết.", "Đơn phương đình chỉ hợp đồng thương mại để giảm thiệt hại."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: 06_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 6.docx · Phần I câu 24 · khoá: gạch chân, khớp file ĐÁP ÁN"}, {"id": "L12-HK2-06-C25", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "dung_sai", "status": "cho_duyet", "q": "Vào tháng 11/2023, Việt Nam công bố kế hoạch tham gia Tổ chức Hợp tác và Phát triển Kinh tế (OECD). Mục tiêu là cải thiện chính sách kinh tế, thương mại, và phát triển bền vững nhằm đáp ứng các tiêu chuẩn quốc tế. Kế hoạch bao gồm tăng cường phát triển năng lượng tái tạo và giảm phụ thuộc vào nhiên liệu hóa thạch. Một doanh nghiệp tại Việt Nam đã nhanh chóng đầu tư vào lĩnh vực năng lượng mặt trời và gió để đáp ứng các tiêu chí môi trường của OECD.", "o": ["Kế hoạch tham gia OECD của Việt Nam là biểu hiện của hội nhập đa phương.", "Việc đầu tư vào năng lượng tái tạo giúp doanh nghiệp đáp ứng các tiêu chuẩn phát triển bền vững mà OECD đề ra.", "Đầu tư vào năng lượng tái tạo là một trong những cách thực hiện chiến lược phát triển doanh nghiệp trong dài hạn.", "Kể từ năm 2025, mọi doanh nghiệp tại Việt Nam phải tuân thủ toàn bộ tiêu chí của OECD về phát triển bền vững."], "a": [true, true, true, false], "e": "Đáp án: a) Đúng; b) Đúng; c) Đúng; d) Sai.", "nguon": "Đề nguồn: 06_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 6.docx · Phần II câu 1 · khoá: gạch chân, khớp file ĐÁP ÁN"}, {"id": "L12-HK2-06-C26", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "dung_sai", "status": "cho_duyet", "q": "Chị H mở một cửa hàng kinh doanh nhỏ tại địa phương, chủ yếu bán sản phẩm thủ công từ nguyên liệu tái chế. Hằng tháng, chị nộp thuế thu nhập cá nhân và thuế giá trị gia tăng đúng hạn. Doanh thu bình quân của cửa hàng là 150 triệu đồng/tháng. Trong khi đó, anh K, một người bạn của chị, chủ yếu bán sản phẩm qua mạng xã hội và không kê khai thuế vì cho rằng kinh doanh trực tuyến nhỏ lẻ không cần đóng thuế.", "o": ["Chị H thực hiện đầy đủ nghĩa vụ thuế, thể hiện trách nhiệm công dân.", "Với doanh thu 150 triệu đồng/tháng, chị H chỉ cần nộp thuế giá trị gia tăng mà không cần nộp thuế thu nhập cá nhân.", "Anh K không kê khai thuế là vi phạm quy định pháp luật về thuế đối với kinh doanh trực tuyến.", "Kinh doanh trực tuyến nhỏ lẻ dưới 100 triệu đồng/năm được miễn thuế, theo quy định pháp luật hiện hành."], "a": [true, false, true, true], "e": "Đáp án: a) Đúng; b) Sai; c) Đúng; d) Đúng.", "nguon": "Đề nguồn: 06_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 6.docx · Phần II câu 2 · khoá: gạch chân, khớp file ĐÁP ÁN"}, {"id": "L12-HK2-06-C27", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "dung_sai", "status": "cho_duyet", "q": "Công ty Y do bà A làm giám đốc chuyên sản xuất đồ nội thất từ gỗ tái chế. Năm 2023, công ty áp dụng mô hình kinh tế tuần hoàn, sử dụng chất thải từ sản xuất để tái chế thành nguyên liệu đầu vào, góp phần giảm lượng rác thải ra môi trường. Đồng thời, công ty xây dựng hệ thống xử lý nước thải đạt tiêu chuẩn quốc gia và hỗ trợ đào tạo nghề cho lao động địa phương. Nhờ các biện pháp này, công ty Y đã mở rộng thị trường ra nước ngoài, nâng cao lợi nhuận và tạo nhiều việc làm cho người lao động.", "o": ["Việc công ty Y áp dụng mô hình kinh tế tuần hoàn là thực hiện trách nhiệm xã hội về môi trường.", "Hỗ trợ đào tạo nghề cho lao động địa phương là trách nhiệm pháp lý của công ty Y.", "Thực hiện tốt nghĩa vụ bảo vệ môi trường gắn liền với trách nhiệm nhân văn của doanh nghiệp Y.", "Công ty Y mở rộng thị trường ra nước ngoài để tăng lợi nhuận là không liên quan đến trách nhiệm xã hội."], "a": [true, false, false, false], "e": "Đáp án: a) Đúng; b) Sai; c) Sai; d) Sai.", "nguon": "Đề nguồn: 06_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 6.docx · Phần II câu 3 · khoá: gạch chân, khớp file ĐÁP ÁN"}, {"id": "L12-HK2-06-C28", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "dung_sai", "status": "cho_duyet", "q": "Đọc đoạn thông tin sau Năm 2001, Việt Nam gia nhập Công ước Viên năm 1969 về Luật điều ước. Điều 26 Công ước Viên về Luật điều ước quốc tế năm 1969 quy định nguyên tắc Pacta sunt servanda quy định “mọi điều ước đã có hiệu lực đều ràng buộc các bên tham gia điều ước và phải được các bên thi hành với thiện ý”. Nguyên tắc này đã được chuyển hóa vào quy định của luật kí kết, gia nhập và thực hiện điều ước quốc tế năm 2025: “Nhà nước Cộng hòa xã hội chủ nghĩa Việt Nam tuân thủ điều ước quốc tế mà Cộng hòa xã hội chủ nghĩa Việt Nam là thành viên”. (khoản 6 Điều 3)", "o": ["Việt Nam gia nhập Công ước viên năm 1969 về Luật điều ước là một trong những minh chứng thể hiện lập trường của Việt Nam đối với việc nghiêm chỉnh tuân thủ điều ước quốc tế.", "Việt Nam gia nhập Công ước viên năm 1969 về Luật điều ước sẽ tạo ra mối quan hệ biện chứng giữa pháp luật Việt Nam với pháp luật quốc tế.", "Luật này áp dụng đối với tổ chức, cá nhân Việt Nam, cá nhân, tổ chức nước ngoài và người Việt Nam định cư ở nước ngoài đang hoạt động tại Việt Nam.", "Điều ước quốc tế mà Việt Nam đã kí kết hoặc gia nhập có giá trị pháp lí ưu tiên hơn so với pháp luật trong nước."], "a": [true, true, true, true], "e": "Đáp án: a) Đúng; b) Đúng; c) Đúng; d) Đúng.", "nguon": "Đề nguồn: 06_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 6.docx · Phần II câu 4 · khoá: gạch chân, khớp file ĐÁP ÁN"}]}, {"id": "L12-HK2-07", "loai": "khoi", "khoi": 12, "hoc_ki": 2, "bo": "HK2", "ten_bo": "học kì II", "so_de": 7, "ten": "Lớp 12 · học kì II · Đề 7", "pham_vi": "Đề nguồn «CUỐI NĂM › 10 ĐỀ» · file nguồn: 07_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 7.docx", "thoi_gian": 50, "cau_truc": "24 câu trắc nghiệm + 4 câu đúng/sai (mỗi câu 4 ý)", "status": "cho_duyet", "khoa": {"khớp 2 nguồn": 28}, "sua": "", "cau": [{"id": "L12-HK2-07-C01", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Chủ thể nào dưới đây đóng vai trò quản lý toàn bộ nền kinh tế quốc dân?", "o": ["Chủ thể trung gian.", "Chủ thể nhà nước.", "Chủ thể tiêu dùng.", "Chủ thể sản xuất."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: 07_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 7.docx · Phần I câu 1 · khoá: gạch chân, khớp file ĐÁP ÁN"}, {"id": "L12-HK2-07-C02", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Theo quy định của pháp luật, công dân thực hiện hành vi nào dưới đây là sử dụng pháp luật?", "o": ["Đăng ký nghĩa vụ quân sự khi đến tuổi.", "Không sử dụng điện thoại khi điều khiển xe máy.", "Lựa chọn nghề nghiệp, công việc và nơi làm việc.", "Thực hiện thủ tục cấp căn cước công dân."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: 07_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 7.docx · Phần I câu 2 · khoá: gạch chân, khớp file ĐÁP ÁN"}, {"id": "L12-HK2-07-C03", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Nội dung nào dưới đây thể hiện vai trò của sản xuất kinh doanh?", "o": ["Giải quyết việc làm.", "Giải quyết thủ tục đăng kí kinh doanh.", "Tạo ra lực lượng lao động.", "Thúc đẩy giá cả thị trường."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: 07_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 7.docx · Phần I câu 3 · khoá: gạch chân, khớp file ĐÁP ÁN"}, {"id": "L12-HK2-07-C04", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Phát biểu nào dưới đây nói về đặc điểm và vị trí của Hiến pháp nước Cộng hoà xã hội chủ nghĩa Việt Nam?", "o": ["Hiến pháp là luật cơ bản của Nhà nước.", "Hiến pháp là văn bản pháp luật mang tính biểu tượng.", "Hiến pháp là công cụ duy nhất để thực hiện pháp luật.", "Hiến pháp là văn bản quy định chi tiết, cụ thể về quyền học tập."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: 07_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 7.docx · Phần I câu 4 · khoá: gạch chân, khớp file ĐÁP ÁN"}, {"id": "L12-HK2-07-C05", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Cạnh tranh lành mạnh thúc đẩy những người sản xuất", "o": ["đưa ra các biện pháp hợp lý hóa sản xuất, nâng cao hiệu quả.", "sử dụng thủ đoạn phi pháp, triệt tiêu đối thủ.", "tung tin bịa đặt giảm uy tín, chất lượng hàng hóa đối thủ.", "không ngừng hủy hoại tài nguyên môi trường."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: 07_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 7.docx · Phần I câu 5 · khoá: gạch chân, khớp file ĐÁP ÁN"}, {"id": "L12-HK2-07-C06", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Mức độ tăng của giá cả ở một con số hằng năm dưới 10% thuộc loại hình lạm phát nào dưới đây?", "o": ["Lạm phát vừa phải.", "Lạm phát phi mã.", "Siêu lạm phát.", "Lạm phát tượng trưng."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: 07_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 7.docx · Phần I câu 6 · khoá: gạch chân, khớp file ĐÁP ÁN"}, {"id": "L12-HK2-07-C07", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Khi cung lao động cao hơn số lượng việc làm thì sẽ dẫn đến tình trạng nào dưới đây?", "o": ["Thiếu việc làm cho người cần tìm việc.", "Thiếu sản phẩm vật chất cho xã hội.", "Thiếu nguồn lực lao động.", "Không mất cân đối trong sản xuất."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: 07_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 7.docx · Phần I câu 7 · khoá: gạch chân, khớp file ĐÁP ÁN"}, {"id": "L12-HK2-07-C08", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Nội dung nào dưới đây phản ánh tầm quan trọng của việc xây dựng ý tưởng kinh doanh?", "o": ["Nâng tầm thương hiệu quốc gia.", "Lành mạnh hóa và thúc đẩy thị trường.", "Giảm thiểu nguy cơ lạm phát.", "Đem lại lợi nhuận cho chủ thể kinh doanh."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: 07_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 7.docx · Phần I câu 8 · khoá: gạch chân, khớp file ĐÁP ÁN"}, {"id": "L12-HK2-07-C09", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Thành phố A tiến hành cải tạo, sửa chữa vỉa hè cho người đi bộ, nhưng thiết kế lại không chú ý xây dựng thêm đường trượt dành cho người khuyết tật đi xe lăn. Việc làm của thành phố A chưa", "o": ["thực hiện quyền bình đẳng của công dân về hưởng quyền.", "thể hiện sự bình đẳng của công dân về nghĩa vụ.", "thể hiện hoạt động từ thiện dành cho người khuyết tật, khiếm thị.", "thể hiện sự ưu tiên về hưởng quyền của công dân."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: 07_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 7.docx · Phần I câu 9 · khoá: gạch chân, khớp file ĐÁP ÁN"}, {"id": "L12-HK2-07-C10", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Theo quy định của pháp luật, Uỷ ban nhân dân cấp xã phải công khai báo cáo tình hình thực hiện ngân sách một cách minh bạch, rõ ràng cho nhân dân được biết, theo dõi và giám sát. Tuy nhiên, ông T là Chủ tịch Uỷ ban nhân dân xã X lại không thực hiện việc công khai báo cáo tình hình thực hiện ngân sách xã. Hành vi của ông T đã vi phạm quyền và nghĩa vụ của công dân trong tham gia quản lý nhà nước và xã hội dẫn đến nhiều hậu quả tiêu cực như", "o": ["làm giảm lòng tin của công dân vào sự quản lý của Nhà nước.", "gây tổn thất về tinh thần, danh dự, uy tín của công dân.", "vi phạm quyền tự do của công dân.", "ông T sẽ bị xử lý hành chính và truy cứu trách nhiệm hình sự."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: 07_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 7.docx · Phần I câu 10 · khoá: gạch chân, khớp file ĐÁP ÁN"}, {"id": "L12-HK2-07-C11", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Nội dung nào dưới đây thể hiện quyền tham gia quản lý nhà nước và xã hội của công dân ở phạm vi cả nước?", "o": ["Công dân tham gia ý kiến trước khi cơ quan có thẩm quyền quyết định.", "Công dân tham gia đóng góp ý kiến, xây dựng các văn bản quy phạm pháp luật.", "Công dân bàn bạc và quyết định mức đóng góp xây dựng đường của thôn.", "Công dân tham gia giám sát hoạt động của chính quyền theo quy định của pháp luật."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: 07_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 7.docx · Phần I câu 11 · khoá: gạch chân, khớp file ĐÁP ÁN"}, {"id": "L12-HK2-07-C12", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Tổ bầu cử số 4 (xã Y) mở hòm phiếu để kiểm tra phiếu bầu. Kết quả kiểm phiếu cho thấy số phiếu bầu đại biểu Hội đồng nhân dân xã thu về nhiều hơn số phiếu phát ra. Qua xác minh, Ủy ban bầu cử xã phát hiện ông G (ứng cử viên đại biểu Hội đồng nhân dân) đã đề nghị ông T (Tổ trưởng Tổ bầu cử số 4) lấy một số phiếu bầu mang về nhà rồi gạch tên những ứng cử viên khác, để lại tên mình và bỏ vào thùng phiếu. Trong trường hợp này hành vi của của ông G và ông T đã gây ra hậu quả như thế nào?", "o": ["Làm sai lệch kết quả bầu cử và lãng phí ngân sách nhà nước.", "Là nhân tố duy nhất gây nên tình trạng bất ổn trong xã hội.", "Ảnh hưởng đến sức khỏe, tính mạng, danh dự của người dân.", "Cản trở công dân thực hiện bầu cử, làm giảm tỷ lệ tham gia bầu cử."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: 07_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 7.docx · Phần I câu 12 · khoá: gạch chân, khớp file ĐÁP ÁN"}, {"id": "L12-HK2-07-C13", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Nhận định nào dưới đây đúng về tăng trưởng kinh tế?", "o": ["Phát triển kinh tế là một chỉ tiêu của tăng trưởng kinh tế.", "Tăng trưởng kinh tế có phạm vi toàn diện hơn phát triển kinh tế.", "Tăng trưởng kinh tế bao hàm phát triển kinh tế.", "Tăng trưởng kinh tế phản ánh sự thay đổi về mặt lượng của nền kinh tế."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: 07_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 7.docx · Phần I câu 13 · khoá: gạch chân, khớp file ĐÁP ÁN"}, {"id": "L12-HK2-07-C14", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Khi nộp thuế, công dân cần thực hiện việc nào sau đây?", "o": ["Kê khai thuế chính xác.", "Được cung cấp thông tin để nộp thuế.", "Trì hoãn nộp hồ sơ khai thuế.", "Trì hoãn việc nộp thuế."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: 07_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 7.docx · Phần I câu 14 · khoá: gạch chân, khớp file ĐÁP ÁN"}, {"id": "L12-HK2-07-C15", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Thềm lục địa của một quốc gia ven biển bao gồm đáy biển và lòng đất dưới đáy biển bên ngoài lãnh hải của quốc gia đó đến một giới hạn theo quy định. Nội dung này được quy định tại văn bản quốc tế nào dưới đây?", "o": ["Công ước về đa dạng sinh học biển (CBD).", "Hiệp ước Nam Cực (Antarctic Treaty).", "Hiến pháp hòa bình về biển (UN Charter).", "Công ước của Liên hợp quốc về Luật biển năm 1982 (UNCLOS)."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: 07_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 7.docx · Phần I câu 15 · khoá: gạch chân, khớp file ĐÁP ÁN"}, {"id": "L12-HK2-07-C16", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Phát biểu nào dưới đây không đúng về vai trò của bảo hiểm?", "o": ["Bảo hiểm giúp người tham gia được nhận bồi thường, trợ cấp góp phần ổn định đời sống.", "Bảo hiểm thất nghiệp chỉ có ý nghĩa đối với người bị mất việc làm thời kì dịch bệnh.", "Bảo hiểm thương mại góp phần ổn định tài chính, giảm bớt nỗi lo cho người tham gia.", "Bảo hiểm đóng góp vào ngân sách giúp Nhà nước ổn định xã hội, thúc đẩy kinh tế phát triển."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: 07_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 7.docx · Phần I câu 16 · khoá: gạch chân, khớp file ĐÁP ÁN"}, {"id": "L12-HK2-07-C17", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Nội dung nào dưới đây không phải chính sách an sinh xã hội?", "o": ["Chính sách xuất nhập khẩu.", "Chính sách bảo hiểm xã hội.", "Chính sách trợ giúp xã hội.", "Chính sách giải quyết việc làm."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: 07_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 7.docx · Phần I câu 17 · khoá: gạch chân, khớp file ĐÁP ÁN"}, {"id": "L12-HK2-07-C18", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Hành vi nào đưới đây thể hiện việc không tôn trọng tài sản của người khác?", "o": ["Trả lại của rơi cho người đánh mất.", "Sử dụng tài sản mượn mà không trả.", "Bảo vệ tài sản của người khác khỏi bị huỷ hoại.", "Thông báo cho cơ quan có trách nhiệm khi nhặt được của rơi."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: 07_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 7.docx · Phần I câu 18 · khoá: gạch chân, khớp file ĐÁP ÁN"}, {"id": "L12-HK2-07-C19", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Trong hơn 1 tháng giá xăng dầu tăng 2 lần mỗi lần tăng trên 10%. Các hãng taxi vẫn chưa quyết định tăng giá chủ yếu vì đang “nhìn nhau”, cắn răng chịu lỗ để giữ thị phần, giá cước tăng quá cao so với hãng khác thì sợ mất khách. Ông T, Phó giám đốc Sở Công thương cho biết: \"Trong đợt tăng giá xăng dầu trước, giá cả trên địa bàn A tăng bình quân 10% - 15%. Dự báo đợt này cũng tăng bình quân ở mức đó, thậm chí có những mặt hàng tăng 20% - 25%, nhưng chủ yếu là những mặt hàng có giá trị thấp”. Chị L đi chợ cho biết, khi hay tin giá xăng tăng chị đã điều chỉnh thực đơn bữa ăn, tính toán lại cho kỹ từng bó rau, miếng thịt để không bị hụt tiền ăn trong ngày vì khi đó giá các mặt hàng thiết yếu cũng sẽ tăng. Nội dung nào dưới đây là biểu hiện của việc thực hiện quản lý thu, chi trong gia đình?", "o": ["Chị L điều chỉnh thực đơn bữa ăn.", "Điều chỉnh giá cả các mặt hàng thiết yếu.", "Giá xăng dầu tăng trên 10%.", "Hãng taxi vẫn chưa quyết định tăng giá."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: 07_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 7.docx · Phần I câu 19 · khoá: gạch chân, khớp file ĐÁP ÁN"}, {"id": "L12-HK2-07-C20", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Hành vi nào sau đây phù hợp với quy định pháp luật về quyền và nghĩa vụ của công dân trong bảo vệ môi trường và tài nguyên thiên nhiên?", "o": ["Anh A không dùng thiết bị che chắn khi xây dựng công trình nhà ở.", "Bạn M tìm hiểu thông tin về các hiện vật trong bảo tàng.", "Ông T tập kết rác thải sinh hoạt đến nơi quy định.", "Anh P có hành vi phá hoại hiện vật khi tham quan khu di tích."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: 07_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 7.docx · Phần I câu 20 · khoá: gạch chân, khớp file ĐÁP ÁN"}, {"id": "L12-HK2-07-C21", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đọc thông tin và trả lời câu hỏi 21, 22\nTrải qua hơn 35 năm đổi mới, Việt Nam đã có quá trình hội nhập kinh tế quốc tế mạnh mẽ và có tác động sâu sắc đến quá trình xây dựng nền kinh tế độc lập tự chủ của đất nước. Quá trình hội nhập quốc tế ấn tượng thông qua việc ký kết các hiệp định thương mại tự do (FTA). Trong số đó, có một số FTA đáng chú ý như:\n-\tHiệp định Đối tác Toàn diện và Tiến bộ xuyên Thái Bình Dương (CPTPP. CPTPP tạo điều kiện cho Việt Nam tiếp cận các thị trường mới và nâng cao tiêu chuẩn và quy tắc thương mại.\n-\tKhu vực Mậu dịch Tự do ASEAN (AFTA. AFTA thúc đẩy cải thiện tiêu chuẩn và quy tắc thương mại trong khu vực và tạo điều kiện thuận lợi cho thương mại và đầu tư.\n-\tFTA Việt Nam - Hàn Quốc (VKFTA nhằm thúc đẩy quan hệ thương mại và đã tạo điều kiện thuận lợi cho việc tiếp cận thị trường, mở ra cơ hội kinh doanh giữa 2 nước.\nTrích Tạp chí tài chính online “Ảnh hưởng của hội nhập kinh tế quốc tế đối với xây dựng nền kinh tế độc lập, tự chủ ở Việt Nam” ngày 17/03/2024\nViệt Nam hội nhập kinh tế quốc tế dựa trên cơ sở cùng có lợi và tuân thủ", "o": ["việc ký kết các hiệp định.", "việc tiếp cận các thị trường mới.", "chuẩn mực quốc tế chung.", "chuẩn mực quốc gia riêng."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: 07_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 7.docx · Phần I câu 21 · khoá: gạch chân, khớp file ĐÁP ÁN"}, {"id": "L12-HK2-07-C22", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đọc thông tin và trả lời câu hỏi 21, 22\nTrải qua hơn 35 năm đổi mới, Việt Nam đã có quá trình hội nhập kinh tế quốc tế mạnh mẽ và có tác động sâu sắc đến quá trình xây dựng nền kinh tế độc lập tự chủ của đất nước. Quá trình hội nhập quốc tế ấn tượng thông qua việc ký kết các hiệp định thương mại tự do (FTA). Trong số đó, có một số FTA đáng chú ý như:\n-\tHiệp định Đối tác Toàn diện và Tiến bộ xuyên Thái Bình Dương (CPTPP. CPTPP tạo điều kiện cho Việt Nam tiếp cận các thị trường mới và nâng cao tiêu chuẩn và quy tắc thương mại.\n-\tKhu vực Mậu dịch Tự do ASEAN (AFTA. AFTA thúc đẩy cải thiện tiêu chuẩn và quy tắc thương mại trong khu vực và tạo điều kiện thuận lợi cho thương mại và đầu tư.\n-\tFTA Việt Nam - Hàn Quốc (VKFTA nhằm thúc đẩy quan hệ thương mại và đã tạo điều kiện thuận lợi cho việc tiếp cận thị trường, mở ra cơ hội kinh doanh giữa 2 nước.\nTrích Tạp chí tài chính online “Ảnh hưởng của hội nhập kinh tế quốc tế đối với xây dựng nền kinh tế độc lập, tự chủ ở Việt Nam” ngày 17/03/2024\nTrong các hiệp định thương mại tự do (FTA) được nhắc đến trong thông tin trên, đâu là hình thức hội nhập kinh tế song phương của Việt Nam?", "o": ["FTA giữa các quốc gia thành viên của ASEAN.", "Hiệp định Đối tác Toàn diện và Tiến bộ xuyên Thái Bình Dương.", "FTA Việt Nam – WTO.", "FTA Việt Nam - Hàn Quốc (VKFTA)."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: 07_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 7.docx · Phần I câu 22 · khoá: gạch chân, khớp file ĐÁP ÁN"}, {"id": "L12-HK2-07-C23", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đọc thông tin và trả lời các câu hỏi 23, 24\nVới ước mơ xây dựng thành công chuỗi cửa hàng phân phối thực phẩm sạch trên địa bàn huyện X, sau khi tham khảo một số mô hình cũng như kiến thức cơ bản về lĩnh vực kinh doanh này, anh H đã lên kế hoạch chi tiết để thực hiện ý tưởng kinh doanh của mình. Qua tư vấn của bạn bè, anh H đã dự liệu được những rủi ro, khó khăn tiềm ẩn để có giải pháp khắc phục. Anh cũng đã lên kế hoạch chi tiết việc bán hàng, tiếp thị, quảng cáo để quảng bá giới thiệu sản phẩm đến khách hàng. Nhờ có kế hoạch kinh doanh tốt anh H xây dựng thành công thương hiệu của mình trên địa bàn huyện X, anh cũng mở rộng các cửa hàng để hình thành\nchuỗi cửa hàng chất lượng cao.\nAnh H đã xác định ý tưởng kinh doanh của mình dựa vào yếu tố nào dưới đây?", "o": ["Ước mơ xây dựng thành công chuỗi cửa hàng phân phối thực phẩm sạch.", "Dự liệu được những rủi ro tiềm ẩn để có giải pháp khắc phục.", "Xây dựng thành công thương hiệu trên địa bàn huyện X.", "Lên kế hoạch chi tiết việc bán hàng, tiếp thị, quảng cáo giới thiệu sản phẩm."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: 07_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 7.docx · Phần I câu 23 · khoá: gạch chân, khớp file ĐÁP ÁN"}, {"id": "L12-HK2-07-C24", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đọc thông tin và trả lời các câu hỏi 23, 24\nVới ước mơ xây dựng thành công chuỗi cửa hàng phân phối thực phẩm sạch trên địa bàn huyện X, sau khi tham khảo một số mô hình cũng như kiến thức cơ bản về lĩnh vực kinh doanh này, anh H đã lên kế hoạch chi tiết để thực hiện ý tưởng kinh doanh của mình. Qua tư vấn của bạn bè, anh H đã dự liệu được những rủi ro, khó khăn tiềm ẩn để có giải pháp khắc phục. Anh cũng đã lên kế hoạch chi tiết việc bán hàng, tiếp thị, quảng cáo để quảng bá giới thiệu sản phẩm đến khách hàng. Nhờ có kế hoạch kinh doanh tốt anh H xây dựng thành công thương hiệu của mình trên địa bàn huyện X, anh cũng mở rộng các cửa hàng để hình thành\nchuỗi cửa hàng chất lượng cao.\nNội dung nào cho thấy anh H lập kế hoạch kinh doanh là điều cần thiết?", "o": ["Anh H nhận được nhiều sự quan tâm, tư vấn của bạn bè trong ngành.", "Anh H tham khảo một số mô hình cũng như kiến thức cơ bản về lĩnh vực kinh doanh.", "Anh H xây dựng thành công thương hiệu của mình, mở rộng quy mô sản xuất kinh doanh.", "Anh H đăng kí kinh doanh với cơ quan nhà nước có thẩm quyền."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: 07_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 7.docx · Phần I câu 24 · khoá: gạch chân, khớp file ĐÁP ÁN"}, {"id": "L12-HK2-07-C25", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "dung_sai", "status": "cho_duyet", "q": "Đọc đoạn thông tin sau: Sau khi tốt nghiệp đại học ngành công nghệ sinh học, với lợi thế là nhà gần các trường đại học, lại có diện tích đất lớn, chị D quyết định lập nghiệp bằng con đường kinh doanh sản phẩm cây cảnh mi ni với mong muốn sau hai năm sẽ thành lập một doanh nghiệp phân phối các sản phẩm này. Đây là lĩnh vực kinh doanh không đòi hỏi vốn lớn, không cần nhiều lao động trong khi thị trường là các bạn sinh viên có nhu cầu khá cao về loại sản phẩm này. Sau khi nghiên cứu thị trường, phân tích nhu cầu khách hàng, chị lên ý tưởng kinh doanh và tiến hành các bước lập kế hoạch kinh doanh của mình. Nhận thấy ý tưởng kinh doanh khả thi chị quyết định thực hiện việc kinh doanh. Do chưa xây dựng phương án phòng ngừa, ứng phó với các rủi ro tiềm ẩn, thời gian đầu chưa có nhiều kinh nghiệm, nên sản phẩm chị cung cấp nhiều cây gặp sâu bệnh chết, vốn bỏ ra tuy được bảo toàn nhưng lợi nhuận không cao.", "o": ["Chị D nghiên cứu thị trường, phân tích nhu cầu khách hàng là thực hiện bước “Lập mục tiêu và chiến lược kinh doanh” trong việc lập kế hoạch kinh doanh.", "Chị D không cần xây dựng phương án phòng ngừa, ứng phó với các rủi ro tiềm ẩn khi lập kế hoạch kinh doanh vì thiệt hại là điều không thể tránh trong kinh doanh.", "Chị D xác định ý tưởng kinh doanh cây cảnh mi ni của mình dựa vào lợi thế nội tại của bản thân.", "Chị D nên tuân thủ các bước lập kế hoạch kinh doanh để đảm bảo việc kinh doanh của mình hiệu quả."], "a": [false, false, true, true], "e": "Đáp án: a) Sai; b) Sai; c) Đúng; d) Đúng.", "nguon": "Đề nguồn: 07_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 7.docx · Phần II câu 1 · khoá: gạch chân, khớp file ĐÁP ÁN"}, {"id": "L12-HK2-07-C26", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "dung_sai", "status": "cho_duyet", "q": "Đọc đoạn thông tin sau: Doanh nghiệp V kinh doanh trong ngành xuất khẩu thuỷ hải sản do ông K làm giám đốc. Doanh nghiệp quan tâm tạo việc làm thường xuyên cho người lao động với mức lương, thưởng tương xứng và xây dựng một môi trường lao động an toàn, thông thoáng bảo đảm sức khoẻ. Vì vậy năng suất lao động của doanh nghiệp khá cao, sản phẩm bảo đảm chất lượng theo cam kết, được khách hàng rất tin tưởng. Trong nhiều năm qua, doanh nghiệp thường xuyên thực hiện hoạt động quyên góp từ thiện giúp đỡ nhân dân các vùng gặp khó khăn, hoạn nạn. Doanh nghiệp đã phát động phong trào “Vì miền Trung thân yêu” và nhận được sự ủng hộ nhiệt tình của đông đảo cán bộ nhân viên đóng góp công sức để chia sẻ phần nào khó khăn với bà con miền Trung vượt qua những cơn lũ lụt. Vì không cạnh tranh được về chất lượng sản phẩm cũng như uy tín của doanh nghiệp V nên ông T giám đốc doanh nghiệp B đã chỉ đạo nhân viên của mình tung tin đồn sai sự thật về đời tư của ông K để hạ uy tín của doanh nghiệp V.", "o": ["Ông T chỉ đạo nhân viên của mình tung tin đồn sai sự thật về đời tư của ông K để hạ uy tín của doanh nghiệp V là hành vi cạnh tranh không lành mạnh, vi phạm trách nhiệm kinh tế của doanh nghiệp.", "Em đồng tình với việc doanh nghiệp V đã phát động phong trào ủng hộ miền Trung thân yêu vì đây là việc làm phù hợp với trách nhiệm pháp lí của doanh nghiệp.", "Ông K thực hiện tốt trách nhiệm công dân khi tham gia điều hành doanh nghiệp.", "Doanh nghiệp V quan tâm đảm bảo cho người lao động việc làm với mức lương, thưởng tương xứng là phù hợp với trách nhiệm kinh tế của doanh nghiệp."], "a": [false, false, true, true], "e": "Đáp án: a) Sai; b) Sai; c) Đúng; d) Đúng.", "nguon": "Đề nguồn: 07_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 7.docx · Phần II câu 2 · khoá: gạch chân, khớp file ĐÁP ÁN"}, {"id": "L12-HK2-07-C27", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "dung_sai", "status": "cho_duyet", "q": "Đọc đoạn thông tin sau: Điều 69, Luật Hôn nhân và gia đình năm 2014 quy định: \"Không được phân biệt đối xử với con trên cơ sở giới hoặc theo tình trạng hôn nhân của cha mẹ; không được lạm dụng sức lao động của con chưa thành niên, con đã thành niên mất năng lực hành vi dân sự hoặc không có khả năng lao động; không được xúi giục, ép buộc con làm việc trái pháp luật, trái đạo đức xã hội\"", "o": ["Em sẽ tố cáo nếu chứng kiến hành vi lạm dụng sức lao động của con chưa thành niên.", "Cha mẹ lạm dụng sức lao động của con chưa thành niên là không vi phạm pháp luật.", "Cha mẹ của em có quyền yêu cầu con tham gia mọi hoạt động lao động để rèn luyện sức khoẻ và tăng cường tính tự lập.", "Hành vi vi phạm quyền, nghĩa vụ giữa cha mẹ và con có thể khiến con không được chăm sóc, nuôi dưỡng đúng cách, ảnh hưởng đến thể chất, sức khoẻ, tinh thần và sức khoẻ của con."], "a": [true, false, false, true], "e": "Đáp án: a) Đúng; b) Sai; c) Sai; d) Đúng.", "nguon": "Đề nguồn: 07_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 7.docx · Phần II câu 3 · khoá: gạch chân, khớp file ĐÁP ÁN"}, {"id": "L12-HK2-07-C28", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "dung_sai", "status": "cho_duyet", "q": "Đọc đoạn thông tin sau: Năm 2018, Maysa (người Lào) đến Việt Nam sinh sống và học tập tại Đại học Khoa học xã hội nhân văn thành phố Hồ Chí Minh. Ngày 25/ 8/2023 Maysa lập gia đình và đã nhập quốc tịch Việt Nam.", "o": ["Từ 25/ 8/2023 Maysa là công dân Việt Nam.", "Maysa có quyền tham gia vào các hoạt động sản xuất kinh doanh theo quy định pháp luật Việt Nam.", "Maysa có thể tham gia các hoạt động như viết bài đăng báo, nghiên cứu khoa học tại Việt Nam.", "Sau thời điểm 25/8/2023 Maysa bị hạn chế về các quyền chính trị ở Việt Nam."], "a": [true, true, true, false], "e": "Đáp án: a) Đúng; b) Đúng; c) Đúng; d) Sai.", "nguon": "Đề nguồn: 07_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 7.docx · Phần II câu 4 · khoá: gạch chân, khớp file ĐÁP ÁN"}]}, {"id": "L12-HK2-08", "loai": "khoi", "khoi": 12, "hoc_ki": 2, "bo": "HK2", "ten_bo": "học kì II", "so_de": 8, "ten": "Lớp 12 · học kì II · Đề 8", "pham_vi": "Đề nguồn «CUỐI NĂM › 10 ĐỀ» · file nguồn: 08_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 8.docx", "thoi_gian": 50, "cau_truc": "24 câu trắc nghiệm + 4 câu đúng/sai (mỗi câu 4 ý)", "status": "cho_duyet", "khoa": {"khớp 2 nguồn": 28}, "sua": "", "cau": [{"id": "L12-HK2-08-C01", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Chủ thể kinh tế nào dưới đây thực hiện kết nối các quan hệ mua và bán, sản xuất và tiêu dùng?", "o": ["Chủ thể nhà nước.", "Chủ thể tiêu dùng.", "Chủ thể sản xuất.", "Chủ thể trung gian."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: 08_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 8.docx · Phần I câu 1 · khoá: gạch chân, khớp file ĐÁP ÁN"}, {"id": "L12-HK2-08-C02", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Hành vi nào dưới đây của công dân thể hiện hình thức tuân thủ pháp luật?", "o": ["Xét xử các hành vi vi phạm pháp luật hình sự.", "Không nộp thuế đầy đủ theo quy định.", "Hỗ trợ việc cấp đổi căn cước công dân.", "Không tàng trữ trái phép chất ma túy."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: 08_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 8.docx · Phần I câu 2 · khoá: gạch chân, khớp file ĐÁP ÁN"}, {"id": "L12-HK2-08-C03", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Sản xuất kinh doanh không có vai trò nào dưới đây?", "o": ["Cung cấp hàng hóa cho người tiêu dùng.", "Cung cấp sản phẩm đầu vào cho sản xuất.", "Điều tiết các hoạt động xã hội.", "Thúc đẩy phát triển kinh tế."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: 08_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 8.docx · Phần I câu 3 · khoá: gạch chân, khớp file ĐÁP ÁN"}, {"id": "L12-HK2-08-C04", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Trong hệ thống pháp luật nước Cộng hòa xã hội chủ nghĩa Việt Nam, văn bản pháp luật nào có giá trị pháp lý cao nhất?", "o": ["Hiến pháp.", "Luật hành chính.", "Luật tổ chức Quốc hội.", "Luật tổ chức Hội đồng nhân dân."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: 08_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 8.docx · Phần I câu 4 · khoá: gạch chân, khớp file ĐÁP ÁN"}, {"id": "L12-HK2-08-C05", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Cạnh tranh lành mạnh thúc đẩy những người sản xuất", "o": ["đưa ra các biện pháp hợp lý hóa sản xuất, nâng cao hiệu quả.", "sử dụng thủ đoạn phi pháp, triệt tiêu đối thủ.", "tung tin bịa đặt giảm uy tín, chất lượng hàng hóa đối thủ.", "không ngừng hủy hoại tài nguyên môi trường."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: 08_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 8.docx · Phần I câu 5 · khoá: gạch chân, khớp file ĐÁP ÁN"}, {"id": "L12-HK2-08-C06", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Khi mức độ tăng giá của hàng hóa và dịch vụ ở hai con số phản ánh lạm phát của nền kinh tế đó ở mức độ", "o": ["lạm phát vừa phải.", "lạm phát phi mã.", "siêu lạm phát.", "không đáng kể."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: 08_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 8.docx · Phần I câu 6 · khoá: gạch chân, khớp file ĐÁP ÁN"}, {"id": "L12-HK2-08-C07", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Khi cung lao động thấp hơn số lượng việc làm thì sẽ dẫn đến tình trạng nào dưới đây?", "o": ["Thừa lao động phục vụ cho sản xuất kinh doanh.", "Thiếu sản phẩm vật chất cho xã hội.", "Thiếu nguồn lực lao động.", "Không mất cân đối trong sản xuất."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: 08_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 8.docx · Phần I câu 7 · khoá: gạch chân, khớp file ĐÁP ÁN"}, {"id": "L12-HK2-08-C08", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Nội dung nào sau đây nói về tầm quan trọng của việc xây dựng ý tưởng kinh doanh?", "o": ["Những suy nghĩ, hành động sáng tạo, có tính khả thi.", "Tăng lợi thế cạnh tranh trong kinh doanh.", "Tạo ra tính chủ động và hiệu quả trong hoạt động kinh doanh.", "Đáp ứng sự biến động của thị trường."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: 08_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 8.docx · Phần I câu 8 · khoá: gạch chân, khớp file ĐÁP ÁN"}, {"id": "L12-HK2-08-C09", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Chị X làm đơn khiếu nại về quyết định xử phạt hành chính của tổ công tác cảnh sát giao thông khi nhận thấy quyết định này đã phạt mức tiền cao hơn so với quy định của luật giao thông đường bộ. Việc làm của chị X thể hiện ý nghĩa nào của quyền bình đẳng công dân trước pháp luật?", "o": ["Bảo vệ quyền và lợi ích tối thiểu của con người.", "Bảo vệ nghĩa vụ chính đáng của công dân.", "Bảo hiểm được lợi ích chính đáng của công dân.", "Bảo kê được quyền và lợi ích tối thiểu của con người."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: 08_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 8.docx · Phần I câu 9 · khoá: gạch chân, khớp file ĐÁP ÁN"}, {"id": "L12-HK2-08-C10", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Thôn của anh H tổ chức họp lấy ý kiến nhân dân về nội dung xây dựng nhà văn hoá mới. Anh H đã rủ anh M là hàng xóm cùng đi tham gia cuộc họp. Nhưng anh M lại từ chối với lí do bận việc gia đình và cũng không có đóng góp ý kiến gì. Trong trường hợp này hành vi của anh M không gây ra hậu quả nào sau đây?", "o": ["Anh M làm ảnh hưởng trật tự quản lý hành chính.", "Anh M không phát huy được vai trò, tính tích cực trong tham gia quản lý nhà nước và xã hội.", "Anh M làm ảnh hưởng đến hiệu quả của việc họp bàn xây dựng nhà văn hoá mới.", "Anh M không biết, không hiểu thông tin về dự án xây dựng nhà văn hoá mới."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: 08_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 8.docx · Phần I câu 10 · khoá: gạch chân, khớp file ĐÁP ÁN"}, {"id": "L12-HK2-08-C11", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Nội dung nào dưới đây thể hiện quyền tham gia quản lý nhà nước và xã hội của công dân ở phạm vi cả nước?", "o": ["Công dân tham gia ý kiến trước khi cơ quan có thẩm quyền quyết định.", "Công dân tham gia biểu quyết, quyết định vấn đề quan trọng khi nhà nước trưng cầu ý dân.", "Công dân bàn bạc và quyết định mức đóng góp xây dựng đường của thôn.", "Công dân tham gia giám sát họat động của chính quyền theo quy định của pháp luật."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: 08_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 8.docx · Phần I câu 11 · khoá: gạch chân, khớp file ĐÁP ÁN"}, {"id": "L12-HK2-08-C12", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Hành vi nào sau đây vi phạm quyền bất khả xâm phạm về thân thể của công dân?", "o": ["Đánh người gây thương tích.", "Đặt điều nói xấu, vu khống người khác.", "Giam giữ người trái phép.", "Đi xe máy gây tai nạn cho người khác."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: 08_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 8.docx · Phần I câu 12 · khoá: gạch chân, khớp file ĐÁP ÁN"}, {"id": "L12-HK2-08-C13", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Một trong những chỉ tiêu của tăng trưởng kinh tế là", "o": ["sự gia tăng GDP/người.", "tăng tỉ trọng công nghiệp, giảm tỉ trọng nông nghiệp.", "chỉ số phát triển con người HDI tăng.", "chỉ số đói nghèo giảm."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: 08_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 8.docx · Phần I câu 13 · khoá: gạch chân, khớp file ĐÁP ÁN"}, {"id": "L12-HK2-08-C14", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Theo quy định của pháp luật, trường hợp nào sau đây thể hiện quyền về nộp thuế của công dân?", "o": ["Kê khai nhằm tăng số tiền được hoàn thuế.", "Sử dụng không hợp pháp hóa đơn chứng từ.", "Khởi kiện quyết định xử lí về thuế.", "Cưỡng chế thi hành quyết định hành chính thuế."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: 08_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 8.docx · Phần I câu 14 · khoá: gạch chân, khớp file ĐÁP ÁN"}, {"id": "L12-HK2-08-C15", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Nhận định nào dưới đây đúng khi nói về bảo hiểm?", "o": ["Bảo hiểm là một trong những trụ cột đảm bảo an sinh xã hội cho người dân.", "Bảo hiểm y tế do nhà nước thực hiện mang tính lợi nhuận.", "Bảo hiểm hoạt động theo nguyên tắc “số ít bù số đông”", "Bảo hiểm không góp phần làm tăng thu ngân sách nhà nước."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: 08_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 8.docx · Phần I câu 15 · khoá: gạch chân, khớp file ĐÁP ÁN"}, {"id": "L12-HK2-08-C16", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Nội dung nào dưới đây không phải là cơ sở hình thành biên giới quốc gia?", "o": ["Điều ước quốc tế mà Việt Nam kí kết hoặc gia nhập.", "Sự thỏa thuận giữa Việt Nam và quốc gia khác.", "Nguyện vọng của một bộ phận người dân.", "Quy định của pháp luật Việt Nam."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: 08_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 8.docx · Phần I câu 16 · khoá: gạch chân, khớp file ĐÁP ÁN"}, {"id": "L12-HK2-08-C17", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Ở nước ta hiện nay, chính sách nào dưới đây không phải chính sách cơ bản của hệ thống an sinh xã hội?", "o": ["Chính sách giải quyết việc làm.", "Chính sách giáo dục và đào tạo.", "Chính sách trợ giúp xã hội.", "Chính sách bảo hiểm xã hội."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: 08_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 8.docx · Phần I câu 17 · khoá: gạch chân, khớp file ĐÁP ÁN"}, {"id": "L12-HK2-08-C18", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Theo quy định của pháp luật, khi mượn tài sản của người khác, công dân phải có nghĩa vụ", "o": ["giữ gìn, bảo quản tài sản mượn.", "khai thác công dụng, hưởng lợi tức từ tài sản.", "chuyển giao tài sản mượn cho người khác.", "thông báo cho cơ quan chức năng về tài sản mượn."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: 08_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 8.docx · Phần I câu 18 · khoá: gạch chân, khớp file ĐÁP ÁN"}, {"id": "L12-HK2-08-C19", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Nội dung nào sau đây không phản ánh đúng sự cần thiết của việc lập kế hoạch kinh doanh?", "o": ["Giúp chủ thể kinh doanh xác định được mục tiêu, chiến lược, thị trường.", "Tăng khả năng huy động vốn cho chủ thể kinh doanh.", "Là yếu tố đảm bảo chắc chắn cho sự thành công của hoạt động kinh doanh.", "Giúp chủ thể kinh doanh chủ động thực hiện và điều chỉnh kế hoạch."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: 08_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 8.docx · Phần I câu 19 · khoá: gạch chân, khớp file ĐÁP ÁN"}, {"id": "L12-HK2-08-C20", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Việc làm nào sau đây phù hợp khi học sinh đến tham quan di tích danh lam thắng cảnh?", "o": ["Khắc tên mình lên các bức tường di tích để lưu dấu ấn cá nhân.", "Ghi chép cẩn thận các thông tin để hiểu rõ hơn về lịch sử của di tích.", "Tụ tập ồn ào, không quan tâm đến các hướng dẫn và quy định tham quan.", "Mang thức ăn, nước uống vào khuôn viên di tích và để lại rác bừa bãi."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: 08_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 8.docx · Phần I câu 20 · khoá: gạch chân, khớp file ĐÁP ÁN"}, {"id": "L12-HK2-08-C21", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đọc thông tin và trả lời các câu hỏi 21, 22\nTrong những năm qua, hội nhập kinh tế quốc tế của Việt Nam đã đạt được một số thành tựu nhất định, đóng góp chung vào sự phát triển kinh tế - xã hội của đất nước. Tổng kim ngạch xuất, nhập khẩu năm 2018 ước đạt 475 tỷ USD, trong đó xuất khẩu đạt 239 tỷ USD, tăng 11,2% so với năm 2017. Hàng hóa Việt Nam đã tiếp tục khai thác các thị trường truyền thống\nvà mở rộng tìm kiếm, phát triển thêm nhiều thị trường mới. Vốn đầu tư trực tiếp nước ngoài (FDI), hiện cả nước có khoảng 334 tỷ USD vốn đăng ký với hơn 26.600 dự án còn hiệu lực. FDI đã đóng góp lớn trong việc gia tăng năng lực sản xuất và xuất khẩu của Việt Nam. Đến nay, khu vực FDI chiếm khoảng 25% tổng vốn đầu tư toàn xã hội, trên 70% tổng kim ngạch xuất khẩu của cả nước.\n(Theo tạp chí Viện Khoa Học Xã Hội Việt Nam số 7 năm 2019)\nThông tin trên thể hiện nội dung nào dưới đây của hội nhập kinh tế quốc tế?", "o": ["Khái niệm hội nhập kinh tế quốc tế .", "Sự cần thiết của hội nhập kinh tế quốc tế.", "Các hình thức hội nhập kinh tế quốc tế.", "Trách nhiệm của công dân đối với hội nhập kinh tế quốc tế."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: 08_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 8.docx · Phần I câu 21 · khoá: gạch chân, khớp file ĐÁP ÁN"}, {"id": "L12-HK2-08-C22", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đọc thông tin và trả lời các câu hỏi 21, 22\nTrong những năm qua, hội nhập kinh tế quốc tế của Việt Nam đã đạt được một số thành tựu nhất định, đóng góp chung vào sự phát triển kinh tế - xã hội của đất nước. Tổng kim ngạch xuất, nhập khẩu năm 2018 ước đạt 475 tỷ USD, trong đó xuất khẩu đạt 239 tỷ USD, tăng 11,2% so với năm 2017. Hàng hóa Việt Nam đã tiếp tục khai thác các thị trường truyền thống\nvà mở rộng tìm kiếm, phát triển thêm nhiều thị trường mới. Vốn đầu tư trực tiếp nước ngoài (FDI), hiện cả nước có khoảng 334 tỷ USD vốn đăng ký với hơn 26.600 dự án còn hiệu lực. FDI đã đóng góp lớn trong việc gia tăng năng lực sản xuất và xuất khẩu của Việt Nam. Đến nay, khu vực FDI chiếm khoảng 25% tổng vốn đầu tư toàn xã hội, trên 70% tổng kim ngạch xuất khẩu của cả nước.\n(Theo tạp chí Viện Khoa Học Xã Hội Việt Nam số 7 năm 2019)\nLợi ích nào của hội nhập kinh tế quốc tế đối với Việt Nam chưa được đề cập trong thông tin trên?", "o": ["gia tăng năng lực sản xuất và xuất khẩu của Việt Nam.", "mở rộng thị trường cho hàng hóa Việt Nam.", "thu hút vốn đầu tư nước ngoài.", "tận dụng tiến bộ khoa học công nghệ."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: 08_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 8.docx · Phần I câu 22 · khoá: gạch chân, khớp file ĐÁP ÁN"}, {"id": "L12-HK2-08-C23", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đọc thông tin và trả lời các câu hỏi 23, 24\nNhận thấy quê hương mình rất phong phú về các loại thảo mộc và nhu cầu thị trường về dòng sản phẩm thiên nhiên ngày càng tăng lên, ông T đã xây dựng kế hoạch kinh doanh mĩ\nphẩm chiết xuất từ thiên nhiên. Sau khi đánh giá những thuận lợi và khó khăn, ông T nhận thấy kế hoạch kinh doanh của mình rất khả thi. Nhờ xây dựng kế hoạch kinh doanh tốt, đánh giá đúng cơ hội, đối tượng khách hàng tiềm năng,… nên việc kinh doanh của ông T đã đạt được những thành công, tăng khả năng huy động vốn, mở rộng quy mô sản xuất kinh doanh.\nÔng T xác định định hướng kinh doanh của mình dựa vào yếu tố nào dưới đây?", "o": ["Nhu cầu thị trường về dòng sản phẩm thiên nhiên ngày càng tăng lên.", "Việc kinh doanh của ông T đã đạt được những thành công ban đầu.", "Nhiều người có nhu cầu kinh doanh mĩ phẩm chiết xuất từ thiên nhiên.", "Ông T là người kinh doanh mĩ phẩm chiết xuất từ thiên nhiên đầu tiên."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: 08_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 8.docx · Phần I câu 23 · khoá: gạch chân, khớp file ĐÁP ÁN"}, {"id": "L12-HK2-08-C24", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đọc thông tin và trả lời các câu hỏi 23, 24\nNhận thấy quê hương mình rất phong phú về các loại thảo mộc và nhu cầu thị trường về dòng sản phẩm thiên nhiên ngày càng tăng lên, ông T đã xây dựng kế hoạch kinh doanh mĩ\nphẩm chiết xuất từ thiên nhiên. Sau khi đánh giá những thuận lợi và khó khăn, ông T nhận thấy kế hoạch kinh doanh của mình rất khả thi. Nhờ xây dựng kế hoạch kinh doanh tốt, đánh giá đúng cơ hội, đối tượng khách hàng tiềm năng,… nên việc kinh doanh của ông T đã đạt được những thành công, tăng khả năng huy động vốn, mở rộng quy mô sản xuất kinh doanh.\nNội dung nào cho thấy ông T lập kế hoạch kinh doanh là điều cần thiết?", "o": ["Nhận thấy quê hương mình rất phong phú về các loại thảo mộc.", "Thấy kế hoạch kinh doanh của mình rất khả thi.", "Khả năng huy động vốn tăng lên, mở rộng quy mô sản xuất kinh doanh.", "Đăng kí kinh doanh với cơ quan nhà nước có thẩm quyền."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: 08_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 8.docx · Phần I câu 24 · khoá: gạch chân, khớp file ĐÁP ÁN"}, {"id": "L12-HK2-08-C25", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "dung_sai", "status": "cho_duyet", "q": "Đọc đoạn thông tin sau: Anh Q đã làm việc được 12 tháng theo hợp đồng lao động có thời hạn 24 tháng cho một công ty. Anh Q và công ty nơi anh Q làm việc đã tham gia và đóng đầy đủ bảo hiểm xã hội và bảo hiểm thất nghiệp nhưng không đóng bảo hiểm y tế. Do bị bệnh, anh Q phải nhập viện điều trị dài ngày nên anh đã làm đơn xin nghỉ việc chấm dứt hợp đồng lao động ở công ty. Vừa mất nguồn thu nhập vừa phải điều trị bệnh dài ngày nên cuộc sống của anh và gia đình vô cùng khó khăn.", "o": ["Anh Q và công ty nơi anh Q làm việc đã vi phạm quy định của Luật Bảo hiểm y tế.", "Anh Q cho rằng anh không tham gia BHYT nhưng có tham gia BHXH nên anh vẫn được quỹ BHYT chi trả một phần chi phí điều trị.", "Anh Q cần làm hồ sơ gửi đến Trung tâm Dịch vụ việc làm thuộc Sở Lao Động – Thương binh và Xã hội mới được nhận khoản trợ cấp thất nghiệp.", "Anh Q cần nhanh chóng tham gia bảo hiểm y tế bắt buộc vì anh còn phải điều trị bệnh dài ngày."], "a": [true, false, true, false], "e": "Đáp án: a) Đúng; b) Sai; c) Đúng; d) Sai.", "nguon": "Đề nguồn: 08_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 8.docx · Phần II câu 1 · khoá: gạch chân, khớp file ĐÁP ÁN"}, {"id": "L12-HK2-08-C26", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "dung_sai", "status": "cho_duyet", "q": "Đọc đoạn thông tin sau: Anh N thành lập doanh nghiệp tư nhân chuyên bán hàng và cung cấp dịch vụ công nghệ thông tin được cơ quan nhà nước có thẩm quyền cấp giấy chứng nhận đăng kí doanh nghiệp. Trước kì nộp thuế, anh luôn chủ động đến cơ quan thuế để được cung cấp đầy đủ thông tin tài liệu liên quan đến quyền và nghĩa vụ nộp thuế. Anh N nghiêm chỉnh chấp hành chế độ kế toán thống kê, ghi chép đầy đủ doanh số bán hàng, kê khai đầy đủ, kịp thời, chính xác số tiền thuế phải nộp, đóng thuế đầy đủ và đúng hạn.", "o": ["Doanh nghiệp tư nhân của anh N vi phạm quyền về kinh doanh.", "Nghĩa vụ mà doanh nghiệp tư nhân của anh N đã thực hiện là nghĩa vụ nộp thuế.", "Một trong các quyền mà doanh nghiệp của anh N được hưởng là tự chủ đăng kí kinh doanh.", "Doanh nghiệp của anh N đã thực hiện nghĩa vụ bảo đảm quyền và lợi ích hợp pháp của người lao động."], "a": [false, true, true, false], "e": "Đáp án: a) Sai; b) Đúng; c) Đúng; d) Sai.", "nguon": "Đề nguồn: 08_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 8.docx · Phần II câu 2 · khoá: gạch chân, khớp file ĐÁP ÁN"}, {"id": "L12-HK2-08-C27", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "dung_sai", "status": "cho_duyet", "q": "Đọc đoạn thông tin sau: Bà M có con gái là chị H, con trai là anh A và con dâu là chị B. Nghi ngờ anh A tham gia đánh bạc trực tuyến, chị B bí mật rút tiền tiết kiệm của hai vợ chồng rồi nhờ mẹ đẻ chị là bà Q giữ hộ. Vốn coi thường anh A không có thu nhập ổn định nên bà Q đã khuyên con gái góp vốn cùng bà kinh doanh nhu yếu phẩm và được chị B đồng ý. Biết chuyện, chị H bịa đặt và đưa thông tin sai lệch về chị B lên mạng xã hội đồng thời cùng bà M đến nhà bà Q vu khống bà Q lừa đảo chiếm đoạt tài sản của vợ chồng anh A nên giữa hai bên xảy ra xô xát.", "o": ["Em sẽ tố cáo hành vi chị B rút tiền tiết kiệm của hai vợ chồng rồi nhờ mẹ đẻ là bà Q giữ hộ vì vi phạm quyền và nghĩa vụ giữa vợ và chồng trong quan hệ nhân thân.", "Anh A không vi phạm quyền và nghĩa vụ giữa vợ và chồng.", "Em và cộng đồng mạng ủng hộ bà M và chị B vì bà Q lừa đảo chiếm đoạt tài sản của vợ chồng anh A là vi phạm quyền, nghĩa vụ công dân trong gia đình về quan hệ nhân thân.", "Hành vi của chị B, chị H và bà Q cùng vi phạm quyền và nghĩa vụ của công dân trong gia đình."], "a": [false, true, false, true], "e": "Đáp án: a) Sai; b) Đúng; c) Sai; d) Đúng.", "nguon": "Đề nguồn: 08_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 8.docx · Phần II câu 3 · khoá: gạch chân, khớp file ĐÁP ÁN"}, {"id": "L12-HK2-08-C28", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "dung_sai", "status": "cho_duyet", "q": "Đọc đoạn thông tin sau: Tại TP. Hồ Chí Minh, một sự kiện \"Ngày hội môi trường\" được tổ chức nhằm nâng cao nhận thức cộng đồng về bảo vệ môi trường. Sự kiện thu hút sự tham gia của học sinh, sinh viên, các tổ chức xã hội và các công ty trong khu vực. Các hoạt động như dọn dẹp công viên, trồng cây xanh và thu gom rác thải được thực hiện, nhưng cũng có những ý kiến trái chiều cho rằng các hoạt động này chỉ mang tính hình thức và không tạo ra sự thay đổi lâu dài. Tuy nhiên, sự kiện đã góp phần nâng cao ý thức cộng đồng về bảo vệ môi trường, đặc biệt là sự tham gia của các bạn trẻ trong việc thực hiện các hành động cụ thể.", "o": ["Công dân có thể tham gia vào các hoạt động bảo vệ môi trường nếu họ thấy cần thiết, nhưng không bắt buộc.", "Các hoạt động bảo vệ môi trường chỉ có ý nghĩa nếu chúng được thực hiện theo kế hoạch dài hạn và có sự tham gia của chính quyền địa phương.", "Em sẽ tham gia vào các sự kiện bảo vệ môi trường như \"Ngày hội môi trường\" vì đó là trách nhiệm của công dân, không chỉ của các tổ chức và doanh nghiệp.", "Các sự kiện bảo vệ môi trường không thực sự có hiệu quả nếu không có sự can thiệp từ các cơ quan chính phủ."], "a": [false, false, true, false], "e": "Đáp án: a) Sai; b) Sai; c) Đúng; d) Sai.", "nguon": "Đề nguồn: 08_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 8.docx · Phần II câu 4 · khoá: gạch chân, khớp file ĐÁP ÁN"}]}, {"id": "L12-HK2-09", "loai": "khoi", "khoi": 12, "hoc_ki": 2, "bo": "HK2", "ten_bo": "học kì II", "so_de": 9, "ten": "Lớp 12 · học kì II · Đề 9", "pham_vi": "Đề nguồn «CUỐI NĂM › 10 ĐỀ» · file nguồn: 09_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 9.docx", "thoi_gian": 50, "cau_truc": "24 câu trắc nghiệm + 4 câu đúng/sai (mỗi câu 4 ý)", "status": "cho_duyet", "khoa": {"khớp 2 nguồn": 27, "đã tự giải lại": 1}, "sua": "Câu đúng/sai 2 (dây cáp ngầm, khoan thềm lục địa): vị trí cách đường cơ sở 150 hải lý còn nằm trong thềm lục địa (tối thiểu 200 hải lý) nên ý a Đúng — khớp với các ý b, c, d đều nói «vùng thềm lục địa của TA» (đề nguồn ghi a Sai).", "cau": [{"id": "L12-HK2-09-C01", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Trong các hoạt động kinh tế, hoạt động nào đóng vai trò trung gian, kết nối người sản xuất với người tiêu dùng?", "o": ["Hoạt động tiêu dùng", "Hoạt động phân phối - trao đổi", "Hoạt động sản xuất - vận chuyển", "Hoạt động sản xuất - tiêu thụ"], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: 09_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 9.docx · Phần I câu 1 · khoá: gạch chân, khớp file ĐÁP ÁN"}, {"id": "L12-HK2-09-C02", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Trong quá trình cho vay có sự chênh lệch giữa chi phí sử dụng tiền mặt và chi phí sử dụng dịch vụ tín dụng được gọi là gì ?", "o": ["Tiền dịch vụ.", "Tiền lãi.", "Tiền gốc.", "Tiền phát sinh."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: 09_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 9.docx · Phần I câu 2 · khoá: gạch chân, khớp file ĐÁP ÁN"}, {"id": "L12-HK2-09-C03", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Người đứng đầu nhà nước, thay mặt nước Cộng hoà xã hội chủ nghĩa Việt Nam về đối nội và đối ngoại, thống lĩnh lực lượng vũ trang nhân dân là", "o": ["Chủ tịch nước.", "Chủ tịch Quốc hội.", "Thủ tướng chính phủ.", "Tổng bí thư"], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: 09_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 9.docx · Phần I câu 3 · khoá: gạch chân, khớp file ĐÁP ÁN"}, {"id": "L12-HK2-09-C04", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Những quy tắc xử sự chung được áp dụng nhiều lần, ở nhiều nơi đối với tất cả mọi người là thể hiện đặc điểm nào dưới đây của pháp luật?", "o": ["Tính chặt chẽ về hình thức.", "Tính kỉ luật nghiêm minh.", "Tính quy phạm phổ biến.", "Tính quyền lực, bắt buộc chung."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: 09_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 9.docx · Phần I câu 4 · khoá: gạch chân, khớp file ĐÁP ÁN"}, {"id": "L12-HK2-09-C05", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Trong nền kinh tế thị trường, nếu công nghệ và kĩ thuật chưa được ứng dụng phổ biến thì năng suất lao động giảm và chi phí lao động sản xuất ra hàng hoá tăng từ đó sẽ ảnh hưởng như thế nào đối với cung hàng hóa?", "o": ["Cung giảm xuống.", "Cung tăng lên.", "Cung không đổi.", "Cung bằng cầu."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: 09_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 9.docx · Phần I câu 5 · khoá: gạch chân, khớp file ĐÁP ÁN"}, {"id": "L12-HK2-09-C06", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Là sự thỏa thuận giữa người bán sức lao động và người mua sức lao động về tiền công, tiền lương và các điều kiện làm việc khác là nội dung của khái niệm", "o": ["thị trường lao động.", "thị trường tài chính.", "thị trường tiền tệ.", "thị trường công nghệ"], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: 09_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 9.docx · Phần I câu 6 · khoá: gạch chân, khớp file ĐÁP ÁN"}, {"id": "L12-HK2-09-C07", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Tình trạng người lao động mong muốn có việc làm nhưng chưa tìm được việc làm là nội dung của khái niệm", "o": ["thất nghiệp.", "lạm phát.", "thu nhập.", "khủng hoảng."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: 09_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 9.docx · Phần I câu 7 · khoá: gạch chân, khớp file ĐÁP ÁN"}, {"id": "L12-HK2-09-C08", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Các nguồn giúp tạo ý tưởng kinh doanh của chủ thể sản xuất kinh doanh xuất phát từ yếu tố nào dưới đây?", "o": ["Lợi thế nội tại và cơ hội bên ngoài.", "Điểm yếu nội tại và khó khăn bên ngoài.", "Mâu thuẫn của chủ thể sản xuất.", "Khó khăn của chủ thể sản xuất."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: 09_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 9.docx · Phần I câu 8 · khoá: gạch chân, khớp file ĐÁP ÁN"}, {"id": "L12-HK2-09-C09", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Theo quy định của pháp luật, quyền bình đẳng giữa các dân tộc trong lĩnh vực chính trị thể hiện ở việc các dân tộc trong cộng đồng dân tộc Việt Nam đều có quyền", "o": ["tham gia phát triển du lịch cộng đồng.", "hỗ trợ chi phí học tập đại học.", "khám chữa bệnh theo quy định .", "tham gia quản lý nhà nước và xã hội."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: 09_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 9.docx · Phần I câu 9 · khoá: gạch chân, khớp file ĐÁP ÁN"}, {"id": "L12-HK2-09-C10", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Hành vi nào dưới đây của công dân không thể hiện quyền bình đẳng của công dân trong hoạt động tín ngưỡng tôn giáo?", "o": ["Đạo pháp dân tộc.", "Tốt đời đẹp đạo.", "Buôn thần bán thánh.", "Kính chúa yêu nước."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: 09_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 9.docx · Phần I câu 10 · khoá: gạch chân, khớp file ĐÁP ÁN"}, {"id": "L12-HK2-09-C11", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Theo quy định của pháp luật, tại thời điểm tổ chức bầu cử, cử tri không vi phạm quyền và nghĩa vụ của công dân về bầu cử khi", "o": ["độc lập lựa chọn ứng cử viên.", "công khai nội dung đã viết vào phiếu bầu.", "tự ý bỏ phiếu thay người khác.", "ủy quyền thực hiện nghĩa vụ bầu cử."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: 09_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 9.docx · Phần I câu 11 · khoá: gạch chân, khớp file ĐÁP ÁN"}, {"id": "L12-HK2-09-C12", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Theo quy định của pháp luật, trong những trường hợp cần thiết, việc kiểm soát điện thoại, điện tín của công dân chỉ được tiến hành bởi", "o": ["người có thẩm quyền.", "lực lượng bưu chính.", "cơ quan ngôn luận.", "phóng viên báo chí."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: 09_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 9.docx · Phần I câu 12 · khoá: gạch chân, khớp file ĐÁP ÁN"}, {"id": "L12-HK2-09-C13", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Mối quan hệ giữa tăng trưởng kinh tế và phát triển bền vững được thể hiện ở nội dung nào dưới đây?", "o": ["Tăng trưởng kinh tế và phát triển bền vững không liên quan đến nhau.", "Tăng trưởng kinh tế không gây ảnh hưởng đến phát triển bền vững.", "Tăng trưởng kinh tế quan trọng nhưng không đảm bảo phát triển bền vững.", "Tăng trưởng kinh tế là điều kiện tiên quyết để đạt được phát triển bền vững."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: 09_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 9.docx · Phần I câu 13 · khoá: gạch chân, khớp file ĐÁP ÁN"}, {"id": "L12-HK2-09-C14", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Trong trường hợp sau, người dân trên địa bàn xã B đã được hưởng chính sách an sinh xã hội nào? Trường hợp. Năm 2022, do hậu quả của thiên tai, gây thiệt hại nghiêm trọng về người và tài sản, chính quyền xã B đã kịp thời trợ cấp cho các hộ gia đình và cá nhân bị ảnh hưởng, nhờ đó, người dân đã sớm ổn định lại cuộc sống.", "o": ["Chính sách việc làm, thu nhập và giảm nghèo.", "Chính sách dịch vụ xã hội cơ bản.", "Chính sách bảo hiểm xã hội.", "Chính sách trợ giúp xã hội."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: 09_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 9.docx · Phần I câu 14 · khoá: gạch chân, khớp file ĐÁP ÁN"}, {"id": "L12-HK2-09-C15", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Công dân phải kinh doanh đúng ngành, nghề ghi trong giấy chứng nhận đăng kí kinh doanh là nội dung quy định về nghĩa vụ nào dưới đây?", "o": ["Nghĩa vụ của công dân về sản xuất, kinh doanh.", "Nghĩa vụ của công dân về kinh doanh.", "Bảo vệ lợi ích hợp pháp của người tiêu dùng.", "Tuân thủ quy định của pháp luật về bảo vệ môi trường."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: 09_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 9.docx · Phần I câu 15 · khoá: gạch chân, khớp file ĐÁP ÁN"}, {"id": "L12-HK2-09-C16", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đọc thông tin và trả lời các câu hỏi 16, 17, 18\nVề kinh tế, từng bước thực hiện tăng trưởng xanh, phát triển năng lượng sạch; thực hiện sản xuất và tiêu dùng bền vững. Tăng trưởng kinh tế giai đoạn 2016 - 2020 đạt trung bình 7%/năm, nâng mức thu nhập bình quân đầu người hằng năm tính theo GDP tăng lên 3.200 - 3.500 USD (so với mức 2.100 USD năm 2015). Lạm phát giữ ở mức dưới 5%. Thực hiện tiến bộ và công bằng xã hội; thực hiện tốt các chính sách an sinh xã hội; năm 2014 đã có 1,4 triệu người tham gia bảo hiểm xã hội, trên 8,5 triệu người tham gia bảo hiểm thất nghiệp, trên 72% dân số tham gia bảo hiểm y tế. Đời sống nhân dân được cải thiện. Thu nhập bình quân đầu người đạt 2.052 USD/người (2014). Tuổi thọ trung bình đạt 73,5 tuổi (2015). Hoàn thành nhiều mục tiêu Thiên niên kỷ.\nCụm từ GDP/người là một trong những chỉ tiêu thể hiện tốc độ tăng trưởng kinh tế nó thể hiện nội dung nào dưới đây?", "o": ["Tổng sản phẩm quốc nội.", "Tổng sản phẩm quốc dân theo đầu người.", "Tổng sản phẩm quốc dân.", "Tổng sản phẩm quốc nội theo đầu người."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: 09_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 9.docx · Phần I câu 16 · khoá: gạch chân, khớp file ĐÁP ÁN"}, {"id": "L12-HK2-09-C17", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đọc thông tin và trả lời các câu hỏi 16, 17, 18\nVề kinh tế, từng bước thực hiện tăng trưởng xanh, phát triển năng lượng sạch; thực hiện sản xuất và tiêu dùng bền vững. Tăng trưởng kinh tế giai đoạn 2016 - 2020 đạt trung bình 7%/năm, nâng mức thu nhập bình quân đầu người hằng năm tính theo GDP tăng lên 3.200 - 3.500 USD (so với mức 2.100 USD năm 2015). Lạm phát giữ ở mức dưới 5%. Thực hiện tiến bộ và công bằng xã hội; thực hiện tốt các chính sách an sinh xã hội; năm 2014 đã có 1,4 triệu người tham gia bảo hiểm xã hội, trên 8,5 triệu người tham gia bảo hiểm thất nghiệp, trên 72% dân số tham gia bảo hiểm y tế. Đời sống nhân dân được cải thiện. Thu nhập bình quân đầu người đạt 2.052 USD/người (2014). Tuổi thọ trung bình đạt 73,5 tuổi (2015). Hoàn thành nhiều mục tiêu Thiên niên kỷ.\nNội dung nào dưới đây không phải là chỉ tiêu để đánh giá sự phát triển kinh tế của Việt Nam trong thông tin trên?", "o": ["Thực hiện chính sách an sinh xã hội.", "Công tác giải quyết việc làm, bảo hiểm.", "Thu nhập bình quân đầu người (GDP/người)", "Tỷ lệ lạm phát và tăng giá hàng tiêu dùng."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: 09_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 9.docx · Phần I câu 17 · khoá: gạch chân, khớp file ĐÁP ÁN"}, {"id": "L12-HK2-09-C18", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đọc thông tin và trả lời các câu hỏi 16, 17, 18\nVề kinh tế, từng bước thực hiện tăng trưởng xanh, phát triển năng lượng sạch; thực hiện sản xuất và tiêu dùng bền vững. Tăng trưởng kinh tế giai đoạn 2016 - 2020 đạt trung bình 7%/năm, nâng mức thu nhập bình quân đầu người hằng năm tính theo GDP tăng lên 3.200 - 3.500 USD (so với mức 2.100 USD năm 2015). Lạm phát giữ ở mức dưới 5%. Thực hiện tiến bộ và công bằng xã hội; thực hiện tốt các chính sách an sinh xã hội; năm 2014 đã có 1,4 triệu người tham gia bảo hiểm xã hội, trên 8,5 triệu người tham gia bảo hiểm thất nghiệp, trên 72% dân số tham gia bảo hiểm y tế. Đời sống nhân dân được cải thiện. Thu nhập bình quân đầu người đạt 2.052 USD/người (2014). Tuổi thọ trung bình đạt 73,5 tuổi (2015). Hoàn thành nhiều mục tiêu Thiên niên kỷ.\nTốc độ tăng trưởng kinh tế giai 2016 - 2020 đạt trung bình 7%/năm có vai trò như thế nào đối với sự phát triển kinh tế của nước ta trong giai đoạn này?", "o": ["Quyết định nhất.", "Không đáng kể.", "Kìm hãm.", "Động lực."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: 09_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 9.docx · Phần I câu 18 · khoá: gạch chân, khớp file ĐÁP ÁN"}, {"id": "L12-HK2-09-C19", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đọc thông tin và trả lời các câu hỏi 19, 20\nĐầu năm, vợ chồng anh A thống nhất đặt mục tiêu mỗi tháng sẽ dành 60% thu nhập cho các chi tiêu thiết yếu, tiết kiệm 20% thu nhập gia đình để có đủ tiền mua xe máy mới cho vợ nhưng hai tháng nay, anh A bị mất việc, thu nhập gia đình bị giảm sút, kinh tế gia đình eo hẹp mà vợ anh vẫn quyết tâm thực hiện mục tiêu tiết kiệm đã đặt ra bằng cách cắt giảm một số chi tiêu thiết yếu trong gia đình. Để phụ giúp gia đình trong thời gian chưa đi làm trở lại, anh A đã tham gia chạy xe ôm tại bến xe đồng thời nhận giao hàng cho một số cửa hàng trên địa bàn sinh sống. Nhờ đó mà sau một năm vợ chồng anh A đã hoàn thành mục tiêu đặt ra. Khi anh A đã ổn đinh với công việc mới, hai vợ chồng quyết tâm năm năm tới sẽ mua được một mảnh đất để làm cửa hàng cho thuê.\nViệc tham gia chạy xe ôm và giao hàng cho các cửa hàng là hoạt động góp phần tạo ra thu nhập nào dưới đây?", "o": ["Thừa kế.", "Bảo hiểm.", "Thụ động.", "Chủ động."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: 09_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 9.docx · Phần I câu 19 · khoá: gạch chân, khớp file ĐÁP ÁN"}, {"id": "L12-HK2-09-C20", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đọc thông tin và trả lời các câu hỏi 19, 20\nĐầu năm, vợ chồng anh A thống nhất đặt mục tiêu mỗi tháng sẽ dành 60% thu nhập cho các chi tiêu thiết yếu, tiết kiệm 20% thu nhập gia đình để có đủ tiền mua xe máy mới cho vợ nhưng hai tháng nay, anh A bị mất việc, thu nhập gia đình bị giảm sút, kinh tế gia đình eo hẹp mà vợ anh vẫn quyết tâm thực hiện mục tiêu tiết kiệm đã đặt ra bằng cách cắt giảm một số chi tiêu thiết yếu trong gia đình. Để phụ giúp gia đình trong thời gian chưa đi làm trở lại, anh A đã tham gia chạy xe ôm tại bến xe đồng thời nhận giao hàng cho một số cửa hàng trên địa bàn sinh sống. Nhờ đó mà sau một năm vợ chồng anh A đã hoàn thành mục tiêu đặt ra. Khi anh A đã ổn đinh với công việc mới, hai vợ chồng quyết tâm năm năm tới sẽ mua được một mảnh đất để làm cửa hàng cho thuê.\nNội dung nào dưới đây thể hiện việc thực hiện kế hoạch quản lý thu, chi trong gia đình anh A?", "o": ["Điều chỉnh các khoản chi.", "Đặt mục tiêu mua xe.", "Bổ sung các khoản tiết kiệm.", "Tham gia tìm kiếm việc làm."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: 09_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 9.docx · Phần I câu 20 · khoá: gạch chân, khớp file ĐÁP ÁN"}, {"id": "L12-HK2-09-C21", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Nội dung nào dưới đây thể hiện nghĩa vụ của công dân trong việc tham gia bảo vệ di sản văn hóa?", "o": ["Tố cáo hành vi phá hoại di tích.", "Tuyên truyền bảo vệ di tích.", "Phục chế trò chơi dân gian.", "Nghiên cứu loại hình nghệ thuật."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: 09_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 9.docx · Phần I câu 21 · khoá: gạch chân, khớp file ĐÁP ÁN"}, {"id": "L12-HK2-09-C22", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Việc người lao động tham gia và được hưởng chế độ bảo hiểm thất nghiệp theo quy định là đã thực hiện quyền của công dân ở nội dung nào dưới đây?", "o": ["Kinh doanh và đóng thuế.", "Chăm sóc bảo vệ sức khỏe.", "Học tập thường xuyên", "Bảo đảm an sinh xã hội."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: 09_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 9.docx · Phần I câu 22 · khoá: gạch chân, khớp file ĐÁP ÁN"}, {"id": "L12-HK2-09-C23", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đọc thông tin và trả lời các câu hỏi 23, 24\nPhát hiện chồng mình là anh D thường qua lại với chị H là người yêu cũ dù chị đã có chồng con, chị M bế con bỏ nhà đi biệt tích. Nắm được sự việc, bà V mẹ chị M, tới nhà bà K nói chuyện, do thiếu kiềm chế, bà V đã có lời lẽ xúc phạm bà K và anh D nên bị con gái bà K mời ra khỏi nhà. Trong thời gian đó, do thường xuyên không được trang bị bảo hộ đạt chuẩn, anh D bị tai nạn phải nằm viện điều trị một tháng. Vì ông T giám đốc công ty nơi anh D làm việc không đồng ý bồi thường số tiền mà anh D yêu cầu nên bà K đã thuê phóng viên viết bài công khai việc ông T có con ngoài giá thú rồi chia sẻ lên mạng khiến uy tín của ông bị ảnh hưởng nghiêm trọng và vợ ông đòi ly hôn.\nTrong thông tin trên những ai dưới đây đã vi phạm quyền và nghĩa vụ giữa vợ và chồng trong quan hệ hôn nhân và gia đình?", "o": ["Chị H, ông T và bà K.", "Ông T, anh D và bà V.", "Anh D, chị H và ông T.", "Anh D, chị H và chị M."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: 09_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 9.docx · Phần I câu 23 · khoá: gạch chân, khớp file ĐÁP ÁN"}, {"id": "L12-HK2-09-C24", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đọc thông tin và trả lời các câu hỏi 23, 24\nPhát hiện chồng mình là anh D thường qua lại với chị H là người yêu cũ dù chị đã có chồng con, chị M bế con bỏ nhà đi biệt tích. Nắm được sự việc, bà V mẹ chị M, tới nhà bà K nói chuyện, do thiếu kiềm chế, bà V đã có lời lẽ xúc phạm bà K và anh D nên bị con gái bà K mời ra khỏi nhà. Trong thời gian đó, do thường xuyên không được trang bị bảo hộ đạt chuẩn, anh D bị tai nạn phải nằm viện điều trị một tháng. Vì ông T giám đốc công ty nơi anh D làm việc không đồng ý bồi thường số tiền mà anh D yêu cầu nên bà K đã thuê phóng viên viết bài công khai việc ông T có con ngoài giá thú rồi chia sẻ lên mạng khiến uy tín của ông bị ảnh hưởng nghiêm trọng và vợ ông đòi ly hôn.\nAnh D và chị H đã vi phạm nội dung nào dưới đây của quyền và nghĩa vụ giữa vợ và chồng trong gia đình?", "o": ["Quyền kết hôn.", "Quyền ly hôn.", "Quyền tài sản.", "Quyền nhân thân."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: 09_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 9.docx · Phần I câu 24 · khoá: gạch chân, khớp file ĐÁP ÁN"}, {"id": "L12-HK2-09-C25", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "dung_sai", "status": "cho_duyet", "q": "Sau khi kết hôn, vợ chồng chị H được bố mẹ chị H tặng cho 2 vợ chồng một ngôi nhà, ngôi nhà đã được cấp giấy chứng nhận quyền sử dụng đất đứng tên 2 vợ chồng. Khi biết điều này, vợ chồng anh trai của chị H đã bày tỏ thái độ bất mãn, phản đối việc làm của bố mẹ vì cho rằng chị H là con gái nên không có quyền hưởng hết và đòi vợ chồng chị H phải đưa cho mình số tiền giá trị bằng nửa ngôi nhà đó. Chị H không đồng ý nên mỗi ngày vợ chồng người anh trai luôn tìm mọi cách để quấy phá làm ảnh hưởng đến cuộc sống riêng tư của gia đình chị H.", "o": ["Vợ chồng anh trai chị H đã được cơ quan có thẩm quyền cấp giấy chứng nhận quyền sử dụng đất.", "Vợ chồng chị H đã thực hiện quyền sử dụng tài sản theo đúng quy định pháp luật.", "Vợ chồng anh trai đến nhà quấy phá cuộc sống riêng tư của gia đình chị H là hành vi sai trái.", "Vợ chồng anh trai được quyền đòi một nửa số tiền tổng trị giá ngôi nhà của vợ chồng chị H."], "a": [false, true, true, false], "e": "Đáp án: a) Sai; b) Đúng; c) Đúng; d) Sai.", "nguon": "Đề nguồn: 09_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 9.docx · Phần II câu 1 · khoá: gạch chân, khớp file ĐÁP ÁN"}, {"id": "L12-HK2-09-C26", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "dung_sai", "status": "cho_duyet", "q": "Quốc gia HU xúc tiến việc lắp đặt các dây cáp ngầm dưới đáy biển ở vị trí cách đường cơ sở của quốc gia TA 150 hải lý.Trong quá trình lắp đặt, các kỹ sư thi công của HU nhận thấy rằng cần phải cố định các đường dây cáp bằng cách khoan 10 mũi vào đáy biển và họ gửi đề xuất này tới Chính phủ HU. Chính phủ HU đồng ý với đề xuất trên, đồng thời cho phép các kỹ sư thi công thăm dó và thực hiện việc khoan cố định 10 mũi vào lòng đất dưới đáy biển nơi đặt dây cáp ngầm. Khi phát hiện ra hành vi nói trên, TA đã yêu cầu HU dừng ngay hành vi lắp đặt dây cáp cũng như việc khoan vào lòng đất dưới đáy biển trong vùng biển của TA.", "o": ["Vị trí mà HU thực hiện các hành vi nêu trên thuộc vùng thềm lục địa của TA.", "TA yêu cầu HU dừng ngay hành vi lắp đặt dây cáp ngầm cũng như khoan vào lòng đất dưới đáy biển không phù hợp với quy định của luật quốc tế.", "HU tiến hành việc khoan 10 mũi khoan lên vùng thềm lục địa của TA khi không có sự đồng ý của TA là hành vi trái với quy định của pháp luật quốc tế, đồng thời vi phạm đến đặc quyền của TA.", "Quyền của HU lắp đặt dây cáp và ống dẫn ở thềm lục địa của quốc gia ven biển không phải là quyền tự do vô điều kiện mà phải có sự thỏa thuận của TA."], "a": [true, true, true, true], "e": "Đáp án: a) Đúng; b) Đúng; c) Đúng; d) Đúng.", "nguon": "Đề nguồn: 09_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 9.docx · Phần II câu 2 · khoá: ĐÃ TỰ GIẢI LẠI (đối chiếu SGK)"}, {"id": "L12-HK2-09-C27", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "dung_sai", "status": "cho_duyet", "q": "Công ty B (trụ sở thương mại tại Pháp) liên hệ với chi nhánh Công ty C (trụ sở thương mại Việt Nam) tại Pháp, yêu cầu mua 100 tấn gạo chất lượng cao, giá X xuất xứ Việt Nam. Ngày 14 tháng 2 năm 2019, Công ty C liên hệ trực tiếp với Công ty B để xác nhận lại đơn hàng với các điều khoản mà chi nhánh công ty này ở Pháp đã truyền đạt, thời hạn trả lời vào ngày 20 tháng 02 năm 2019. Ngày 18 tháng 02 năm 2019, Công ty C bị cháy kho hàng nên hàng hóa không còn đủ để thực hiện các hợp đồng mua bán nên Công ty C đã gửi fax đề cập đến tình hình của công ty và tuyên bố không thể giao hàng. Ngày 23 tháng 02 năm 2019, Công ty B hồi đáp yêu cầu công ty C giao hàng vào ngày 30 tháng 2, thanh toán tiền hàng thành 3 đợt. Bên Công ty C không thể giao hàng. Do đó, Công ty B kiện Công ty C ra Tòa án Việt Nam để giải quyết.", "o": ["Chủ thể của hợp đồng thương mại này là Pháp và Việt Nam.", "Hết thời hạn trả lời theo yêu cầu mà công ty C không trả lời thì xem như hợp đồng đã được giao kết.", "Công ty C không giao hàng bởi sự kiện bất khả kháng và đã thông báo cho công ty B nên không phải chịu trách nhiệm bồi thường.", "Công ty B không có cơ sở để kiện công ty C vì những điều khoản của hợp đồng này chưa đầy đủ."], "a": [true, false, true, false], "e": "Đáp án: a) Đúng; b) Sai; c) Đúng; d) Sai.", "nguon": "Đề nguồn: 09_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 9.docx · Phần II câu 3 · khoá: gạch chân, khớp file ĐÁP ÁN"}, {"id": "L12-HK2-09-C28", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "dung_sai", "status": "cho_duyet", "q": "Đến nay, nước ta đã có quan hệ chính thức với 189/193 quốc gia và vùng lãnh thổ (trong đó có 4 đối tác chiến lược toàn diện, 17 đối tác chiến lược, 13 đối tác toàn diện); có quan hệ thương mại với 224 đối tác và quan hệ hợp tác với hơn 300 tổ chức quốc tế; đã ký hơn 90 hiệp định thương mại song phương, gần 60 hiệp định khuyến khích và bảo hộ đầu tư; đàm phán, ký kết và thực thi 19 Hiệp định thương mại tự do (FTA) song phương và đa phương với hầu hết các nền kinh tế lớn trên thế giới; trong đó 16 FTA đã có hiệu lực với hơn 60 đối tác, phủ rộng khắp các châu lục với tổng GDP chiếm gần 90% GDP toàn cầu, đưa Việt Nam trở thành một trong những nước dẫn đầu khu vực về tham gia các khuôn khổ hợp tác kinh tế song phương và đa phương.", "o": ["Nước ta có quan hệ hợp tác kinh tế với 189/193 quốc gia và vùng lãnh thổ.", "Việc ký kết các hiệp định thương mại song phương và đa phương giúp Việt Nam mở rộng hoạt động kinh tế đối ngoại.", "Kinh tế đối ngoại là yếu tố giữ vai trò quan trọng góp phần thúc đẩy tăng trưởng và phát triển kinh tế.", "Trong tiến trình hội nhập kinh tế quốc tế, nước ta thường chú trọng đến liên kết với các quốc gia có trình độ phát triển tương đồng."], "a": [true, true, true, false], "e": "Đáp án: a) Đúng; b) Đúng; c) Đúng; d) Sai.", "nguon": "Đề nguồn: 09_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 9.docx · Phần II câu 4 · khoá: gạch chân, khớp file ĐÁP ÁN"}]}, {"id": "L12-HK2-10", "loai": "khoi", "khoi": 12, "hoc_ki": 2, "bo": "HK2", "ten_bo": "học kì II", "so_de": 10, "ten": "Lớp 12 · học kì II · Đề 10", "pham_vi": "Đề nguồn «CUỐI NĂM › 10 ĐỀ» · file nguồn: 10_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 10.docx", "thoi_gian": 50, "cau_truc": "24 câu trắc nghiệm + 4 câu đúng/sai (mỗi câu 4 ý)", "status": "cho_duyet", "khoa": {"khớp 2 nguồn": 27, "đã tự giải lại": 1}, "sua": "Câu 5 (Luật Bình đẳng giới, cản trở người khác tham gia hoạt động giáo dục sức khoẻ): lĩnh vực y tế (B). Ngân hàng bài (B11-10-K09) cùng khoá B; khoá C trong đề này lệch.", "cau": [{"id": "L12-HK2-10-C01", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Chủ thể nào đóng vai trò quan trọng trong việc tạo ra hàng hoá cho xã hội, phục vụ nhu cầu tiêu dùng?", "o": ["Chủ thể trung gian.", "Doanh nghiệp Nhà nước.", "Các điểm bán hàng.", "Chủ thể sản xuất."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: 10_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 10.docx · Phần I câu 1 · khoá: gạch chân, khớp file ĐÁP ÁN"}, {"id": "L12-HK2-10-C02", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Các cá nhân, tổ chức sử dụng đúng đắn các quyền của mình, làm những gì pháp luật cho phép làm là", "o": ["tuân thủ pháp luật.", "sử dụng pháp luật.", "thi hành pháp luật.", "áp dụng pháp luật."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: 10_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 10.docx · Phần I câu 2 · khoá: gạch chân, khớp file ĐÁP ÁN"}, {"id": "L12-HK2-10-C03", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "thất nghiệp xuất hiện do có sự mất cân đối giữa cung và cầu lao động, sự dịch chuyển cơ cấu giữa các ngành trong nền kinh tế hoặc sự thay đổi phương thức sản xuất trong một ngành được gọi là", "o": ["thất nghiệp thời vụ.", "thất nghiệp cơ cấu.", "thất nghiệp chu kì.", "thất nghiệp tự nguyện."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: 10_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 10.docx · Phần I câu 3 · khoá: gạch chân, khớp file ĐÁP ÁN"}, {"id": "L12-HK2-10-C04", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Việc chủ thể sản xuất kinh doanh không ngừng rèn luyện kỹ năng, nâng cao hiểu biết về lĩnh vực mình kinh doanh là thể hiện năng lực nào dưới đây?", "o": ["Năng lực trải nghiệm.", "Năng lực sống thử.", "Năng lực học tập.", "Năng lực lãnh đạo."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: 10_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 10.docx · Phần I câu 4 · khoá: gạch chân, khớp file ĐÁP ÁN"}, {"id": "L12-HK2-10-C05", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Theo quy định của Luật bình đẳng giới, hành vi cản trở, xúi giục người khác không tham gia các hoạt động giáo dục sức khoẻ vì định kiến giới là hành vi vi phạm pháp luật về bình đẳng giới trong lĩnh vực nào dưới đây?", "o": ["Văn hoá.", "Y tế.", "Giáo dục và đào tạo.", "Hôn nhân và gia đình."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: 10_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 10.docx · Phần I câu 5 · khoá: ĐÃ TỰ GIẢI LẠI (đối chiếu SGK)"}, {"id": "L12-HK2-10-C06", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Theo quy định của pháp luật, tại thời điểm tổ chức bầu cử, cử tri không vi phạm quyền và nghĩa vụ của công dân về bầu cử khi", "o": ["độc lập lựa chọn ứng cử viên.", "công khai nội dung đã viết vào phiếu bầu.", "tự ý bỏ phiếu thay người khác.", "ủy quyền thực hiện nghĩa vụ bầu cử."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: 10_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 10.docx · Phần I câu 6 · khoá: gạch chân, khớp file ĐÁP ÁN"}, {"id": "L12-HK2-10-C07", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Cụm từ GDP/người là một trong những chỉ tiêu thể hiện tốc độ tăng trưởng kinh tế nó thể hiện nội dung nào dưới đây?", "o": ["Tổng sản phẩm quốc dân.", "Tổng sản phẩm quốc nội theo đầu người.", "Tổng sản phẩm quốc dân theo đầu người.", "Tổng sản phẩm quốc nội."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: 10_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 10.docx · Phần I câu 7 · khoá: gạch chân, khớp file ĐÁP ÁN"}, {"id": "L12-HK2-10-C08", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Loại hình bảo hiểm nào dưới đây, trong đó hoạt động của tổ chức bảo hiểm chấp nhận rủi ro của người được bảo hiểm trên cơ sở bên mua bảo hiểm đóng phí bảo hiểm để tổ chức bảo hiểm bồi thường, trả tiền bảo hiểm khi xảy ra sự kiện bảo hiểm theo thoả thuận trong hợp đồng bảo hiểm đã được hai bên kí kết.", "o": ["Bảo hiểm ý tế.", "Bảo hiểm thất nghiệp.", "Bảo hiểm thương mại.", "Bảo hiểm xã hội."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: 10_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 10.docx · Phần I câu 8 · khoá: gạch chân, khớp file ĐÁP ÁN"}, {"id": "L12-HK2-10-C09", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Theo quy định của pháp luật, khi chủ sở hữu quyết định từ bỏ quyền sở hữu tài sản của mình là đã thực hiện quyền nào dưới đây?", "o": ["Quyền chiếm hữu.", "Quyền sử dụng.", "Quyền chiếm đoạt.", "Quyền định đoạt."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: 10_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 10.docx · Phần I câu 9 · khoá: gạch chân, khớp file ĐÁP ÁN"}, {"id": "L12-HK2-10-C10", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Hình thức sản xuất kinh doanh với các thành viên có tài sản chung, cùng đóng góp công sức để sản xuất kinh doanh được gọi là gì?", "o": ["Mô hình kinh tế hộ gia đình.", "Mô hình kinh tế khác.", "Mô hình kinh tế hợp tác xã.", "Mô hình kinh tế doanh nghiệp."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: 10_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 10.docx · Phần I câu 10 · khoá: gạch chân, khớp file ĐÁP ÁN"}, {"id": "L12-HK2-10-C11", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Về mặt kinh tế, Hiến pháp 2013 khẳng định mô hình kinh tế của nước ta hiện nay là mô hình kinh tế thị trường định hướng", "o": ["tư bản chủ nghĩa.", "xã hội chủ nghĩa.", "chuyên chế tư bản.", "cộng sản chủ nghĩa."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: 10_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 10.docx · Phần I câu 11 · khoá: gạch chân, khớp file ĐÁP ÁN"}, {"id": "L12-HK2-10-C12", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Theo quy định của pháp luật, hành vi nào dưới đây vi phạm quyền bất khả xâm phạm về chỗ ở của công dân?", "o": ["Tự ý mở điện thoại của bạn.", "Đe dọa đánh người.", "Tự ý vào nhà người khác.", "Tung ảnh nóng của bạn lên facebook."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: 10_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 10.docx · Phần I câu 12 · khoá: gạch chân, khớp file ĐÁP ÁN"}, {"id": "L12-HK2-10-C13", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Theo quy định Điều 157 của Bộ luật Hình sự, người nào bắt, giữ hoặc giam người trái pháp luật, nếu không thuộc trường hợp quy định tại Điều 153 và Điều 377 của Bộ luật này, phải chịu trách nhiệm pháp lí nào sau đây?", "o": ["Phạt cải tạo không giam giữ đến 03 năm hoặc phạt tù từ 06 tháng đến 03 năm.", "Phạt cải tạo không giam giữ đến 03 năm hoặc phạt tù từ 02 năm đến 07 năm.", "Phạt cải tạo không giam giữ đến 03 năm hoặc phạt tù từ 07 năm đến 10 năm.", "Phạt cải tạo không giam giữ đến 03 năm hoặc phạt tù từ 05 năm đến 12 năm"], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: 10_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 10.docx · Phần I câu 13 · khoá: gạch chân, khớp file ĐÁP ÁN"}, {"id": "L12-HK2-10-C14", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Sự thỏa thuận giữa người bán sức lao động và người mua sức lao động về tiền công, tiền lương và các điều kiện làm việc khác là nội dung của khái niệm nào sau đây?", "o": ["Thị trường lao động.", "Thị trường tài chính.", "Thị trường tiền tệ.", "Thị trường công nghệ."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: 10_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 10.docx · Phần I câu 14 · khoá: gạch chân, khớp file ĐÁP ÁN"}, {"id": "L12-HK2-10-C15", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Cửa hàng của chị H được cấp giấy phép bán đường sữa, bánh kẹo. Nhận thấy nhu cầu về thức ăn nhanh trên thị trường tăng cao nên chị H đã bán thêm mặt hàng này mà không khai báo cơ quan chức năng. Hành vi của chị H là biểu hiện nào của tính hai mặt trong cạnh tranh?", "o": ["Cạnh tranh trực tuyến.", "cạnh tranh tiêu cực.", "cạnh tranh lành mạnh.", "cạnh tranh không lành mạnh."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: 10_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 10.docx · Phần I câu 15 · khoá: gạch chân, khớp file ĐÁP ÁN"}, {"id": "L12-HK2-10-C16", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đọc thông tin và trả lời các câu hỏi 16, 17\nBà H, ở tỉnh D, sau khi dừng tham gia bảo hiểm xã hội (BHXH) bắt buộc đã bỏ số tiền hơn 40 triệu đồng đóng BHXH tự nguyện những năm còn thiếu để được hưởng lương hưu tâm sự, chia sẻ: “Lúc trước làm việc, tôi cũng có tham gia BHXH, do điều kiện tôi xin nghỉ và đã hưởng một lần. Số tiền nhận khi đó cũng giúp tôi làm được một số việc nhưng cũng chẳng được bao lâu. Đến khi sau này đi làm lại và tham gia BHXH, lúc gần nghỉ việc do hết tuổi lao động, quá trình tham gia BHXH của mình chỉ được 14 năm 02 tháng chưa đủ điều kiện để hưởng chế độ hưu trí. Tôi đã suy nghĩ, rút kinh nghiệm lần trước nên đã quyết định đóng BHXH tự nguyện số năm còn thiếu để hưởng lương hưu”. Tiền lương hưu hàng tháng cũng đủ trang trải cho cuộc sống hàng ngày, mình còn được cấp thẻ bảo hiểm y tế quyền lợi cao hơn so với lúc đi làm để đi khám bệnh, mà lớn tuổi rồi sức khỏe xuống có khi ở bệnh viện nhiều hơn ở nhà. Nên tính ra việc nhận lương hưu nó bảo đảm hơn cho bản thân mình khi về già”.\nBà H là đối tượng đã tham gia những loại hình bảo hiểm nào dưới đây?", "o": ["Bảo hiểm y tế, bảo hiểm xã hội và bảo hiểm thất nghiệp.", "Bảo hiểm thất nghiệp, bảo hiểm xã hội tự nguyện và bắt buộc.", "Bảo hiểm xã hội tự nguyện, bắt buộc và bảo hiểm y tế.", "Bảo hiểm thân thể, tải sản và bảo hiểm thương mại."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: 10_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 10.docx · Phần I câu 16 · khoá: gạch chân, khớp file ĐÁP ÁN"}, {"id": "L12-HK2-10-C17", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đọc thông tin và trả lời các câu hỏi 16, 17\nBà H, ở tỉnh D, sau khi dừng tham gia bảo hiểm xã hội (BHXH) bắt buộc đã bỏ số tiền hơn 40 triệu đồng đóng BHXH tự nguyện những năm còn thiếu để được hưởng lương hưu tâm sự, chia sẻ: “Lúc trước làm việc, tôi cũng có tham gia BHXH, do điều kiện tôi xin nghỉ và đã hưởng một lần. Số tiền nhận khi đó cũng giúp tôi làm được một số việc nhưng cũng chẳng được bao lâu. Đến khi sau này đi làm lại và tham gia BHXH, lúc gần nghỉ việc do hết tuổi lao động, quá trình tham gia BHXH của mình chỉ được 14 năm 02 tháng chưa đủ điều kiện để hưởng chế độ hưu trí. Tôi đã suy nghĩ, rút kinh nghiệm lần trước nên đã quyết định đóng BHXH tự nguyện số năm còn thiếu để hưởng lương hưu”. Tiền lương hưu hàng tháng cũng đủ trang trải cho cuộc sống hàng ngày, mình còn được cấp thẻ bảo hiểm y tế quyền lợi cao hơn so với lúc đi làm để đi khám bệnh, mà lớn tuổi rồi sức khỏe xuống có khi ở bệnh viện nhiều hơn ở nhà. Nên tính ra việc nhận lương hưu nó bảo đảm hơn cho bản thân mình khi về già”.\nNội dung nào dưới đây không thể hiện vai trò của bảo hiểm đối với bà H?", "o": ["Được chăm sóc sức khỏe trọn đời.", "Được hưởng trợ cấp ốm đau.", "Ổn định thu nhập khi về già.", "Được hưởng chế độ tử tuất."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: 10_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 10.docx · Phần I câu 17 · khoá: gạch chân, khớp file ĐÁP ÁN"}, {"id": "L12-HK2-10-C18", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Việc cân đối các khoản thu và chi nhằm đáp ứng nhu cầu vật chất, tinh thần của các thành viên sao cho phù hợp với các nguồn thu nhập của gia đình là nội dung của khái niệm nào dưới đây?", "o": ["Quản lí thu, chi nội bộ.", "Quản lí thu, chi đối ngoại.", "Quản lí thu, chi đối nội.", "Quản lí thu, chi trong gia đình."], "a": 3, "e": "Đáp án D.", "nguon": "Đề nguồn: 10_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 10.docx · Phần I câu 18 · khoá: gạch chân, khớp file ĐÁP ÁN"}, {"id": "L12-HK2-10-C19", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Nội dung nào dưới đây không thể hiện sự cần thiết phải quản lý thu, chi trong gia đình?", "o": ["Điều chỉnh hành vi tiêu dùng.", "Thiết lập mục tiêu tài chính.", "Chi tiêu tự do mất kiểm soát.", "Kiểm soát các nguồn thu nhập."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: 10_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 10.docx · Phần I câu 19 · khoá: gạch chân, khớp file ĐÁP ÁN"}, {"id": "L12-HK2-10-C20", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Một trong những quyền của công dân trong bảo vệ và chăm sóc sức khỏe là được", "o": ["từ chối công tác phòng chống dịch truyền nhiễm.", "hướng dẫn chăm sóc sức khỏe bản thân.", "xuyên tạc bệnh lý người khác nếu mâu thuẫn.", "công khai mọi thông tin cá nhân người bệnh."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: 10_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 10.docx · Phần I câu 20 · khoá: gạch chân, khớp file ĐÁP ÁN"}, {"id": "L12-HK2-10-C21", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Thanh tra Sở Y tế Y phát hiện phòng khám đa khoa của bà H bán thuốc hết hạn sử dụng với tổng giá trị số thuốc được xác định là 28 triệu đồng. Theo quy định của pháp luật, hành vi bán thuốc hết hạn sử dụng của bà H phải chịu trách nhiệm pháp lí nào sau đây?", "o": ["Cảnh cáo và buộc tiêu hủy toàn bộ số thuốc hết hạn sử dụng.", "Phạt tiền, tước quyền sử dụng chứng chỉ hành nghề có thời hạn và buộc tiêu hủy toàn bộ số thuốc hết hạn sử dụng.", "Phạt tiền, buộc tiêu hủy toàn bộ số thuốc hết hạn sử dụng, thu hồi giấy phép hoạt động đối với phòng khám của bà H.", "Phạt tiền, và buộc tiêu hủy toàn bộ số thuốc hết hạn sử dụng và thu hồi chứng chỉ hành nghề vĩnh viễn đối với bà H."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: 10_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 10.docx · Phần I câu 21 · khoá: gạch chân, khớp file ĐÁP ÁN"}, {"id": "L12-HK2-10-C22", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đọc thông tin và trả lời các câu hỏi 22,23,24\nNước X và Y kí kết với nhau hiệp định đầu tư, theo đó nhà đầu tư của nước X và nước Y được hưởng những quyền lợi, ưu đãi và thực hiện những nghĩa vụ trên lãnh thổ của nhau như các nhà đầu tư trong nước mình, không có sự phân biệt đối xử nào. Tuy nhiên, nước X sau đó ban hành luật trái với hiệp định đã kí kết, trong đó hạn chế một số ưu đãi của nhà đầu tư nước Y trên lãnh thổ của mình.\nNhà đầu tư của nước X và nước Y được hưởng những quyền lợi, ưu đãi và thực hiện những nghĩa vụ trên lãnh thổ của nhau như các nhà đầu tư trong nước mình, không có sự phân biệt đối xử nào là thể hiện chế độ", "o": ["đối xử tối huệ quốc.", "đối xử đặc biệt.", "đối xử quốc gia.", "đối xử qua lại."], "a": 2, "e": "Đáp án C.", "nguon": "Đề nguồn: 10_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 10.docx · Phần I câu 22 · khoá: gạch chân, khớp file ĐÁP ÁN"}, {"id": "L12-HK2-10-C23", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đọc thông tin và trả lời các câu hỏi 22,23,24\nNước X và Y kí kết với nhau hiệp định đầu tư, theo đó nhà đầu tư của nước X và nước Y được hưởng những quyền lợi, ưu đãi và thực hiện những nghĩa vụ trên lãnh thổ của nhau như các nhà đầu tư trong nước mình, không có sự phân biệt đối xử nào. Tuy nhiên, nước X sau đó ban hành luật trái với hiệp định đã kí kết, trong đó hạn chế một số ưu đãi của nhà đầu tư nước Y trên lãnh thổ của mình.\nHiệp định đầu tư giữa nước X và nước Y là thể hiện hình thức hội nhập kinh tế quốc tế", "o": ["song phương.", "khu vực.", "toàn cầu.", "toàn diện."], "a": 0, "e": "Đáp án A.", "nguon": "Đề nguồn: 10_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 10.docx · Phần I câu 23 · khoá: gạch chân, khớp file ĐÁP ÁN"}, {"id": "L12-HK2-10-C24", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "tn4", "status": "cho_duyet", "q": "Đọc thông tin và trả lời các câu hỏi 22,23,24\nNước X và Y kí kết với nhau hiệp định đầu tư, theo đó nhà đầu tư của nước X và nước Y được hưởng những quyền lợi, ưu đãi và thực hiện những nghĩa vụ trên lãnh thổ của nhau như các nhà đầu tư trong nước mình, không có sự phân biệt đối xử nào. Tuy nhiên, nước X sau đó ban hành luật trái với hiệp định đã kí kết, trong đó hạn chế một số ưu đãi của nhà đầu tư nước Y trên lãnh thổ của mình.\nNước X ban hành luật trái với hiệp định đã ký kết là vi phạm nguyên tắc nào dưới đây của pháp luật quốc tế?", "o": ["Nguyên tắc bình đẳng về chủ quyền các nước.", "Nguyên tắc tận tâm, thiện chí thực hiện cam kết.", "Nguyên tắc giải quyết bằng biện pháp hòa bình.", "Nguyên tắc không can thiệp công việc nội bộ."], "a": 1, "e": "Đáp án B.", "nguon": "Đề nguồn: 10_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 10.docx · Phần I câu 24 · khoá: gạch chân, khớp file ĐÁP ÁN"}, {"id": "L12-HK2-10-C25", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "dung_sai", "status": "cho_duyet", "q": "Hiệp định thương mại tự do Việt Nam – Hàn Quốc (VKFTA) được ký kết ngày 5/5/2015 và chính thức có hiệu lực từ ngày 20/12/2015, hiệp định đã mở ra cơ hội thu hút vốn đầu tư nước ngoài từ các doanh nghiệp Hàn Quốc vào Việt Nam. Tính đến nay công ty S đã đầu tư Việt Nam đạt khoảng trên 17 tỷ USD, hàng năm tạo ra trên 170.000 việc làm với mức thu nhập ổn định. Đến nay, công ty S đã xuất khẩu 54,4 tỷ USD, chiếm 25,4% kim ngạch xuất khẩu của cả nước. Bên cạnh đó công ty S luôn chú trọng đến yếu tố con người, ngoài những quy định liên quan đến vấn đề nghỉ ngơi xen kẽ giờ làm việc cho toàn thể nhân viên, công ty S còn đưa ra giải pháp đó là, trong 8 tiếng làm việc chính thức của nhân viên, cứ sau 2 giờ, những nhân viên làm việc trực tiếp tại xưởng sản xuất lại có 10 phút giải lao tại xưởng. Thời gian nghỉ để ăn giữa ca là 60 phút, hàng năm tất cả các nhân viên đều được tham gia chương trình khám sức khỏe tổng quát định kỳ.", "o": ["Hiệp định thương mại tự do Việt Nam – Hàn Quốc là biểu hiện của hình thức hợp tác song phương.", "Đầu tư trực tiếp nước ngoài FDI diễn ra ở cả hình thức hợp tác song phương, khu vực và toàn cầu.", "Công ty S coi trọng yếu tố con người trong phát triển là phù hợp với trách nhiệm đạo đức của doanh nghiệp.", "Công ty S đã thực hiện tốt quyền của công dân trong bảo vệ và chăm sóc sức khỏe."], "a": [true, false, true, false], "e": "Đáp án: a) Đúng; b) Sai; c) Đúng; d) Sai.", "nguon": "Đề nguồn: 10_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 10.docx · Phần II câu 1 · khoá: gạch chân, khớp file ĐÁP ÁN"}, {"id": "L12-HK2-10-C26", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "dung_sai", "status": "cho_duyet", "q": "Nhận thấy nhu cầu về sử dụng rau rạch của người dân ngày càng tăng, chị B quyết định nghỉ việc tại công ty để tiến hành hoạt động kinh doanh rau sạch. Từ số tiền tiết kiệm của chị B và thế chấp ngôi nhà đang ở, mở một cửa hàng ngay tại thị trấn. Với phương châm đặt chất lượng lên hàng đầu, luôn cam kết với khách hàng về chất lượng sản phẩm vì vậy chỉ sau 2 năm đi vào hoạt động, cửa hàng của chị B đã có một lượng khách hàng lớn tin tưởng và thường xuyên sử dụng sản phẩm do cửa hàng cung cấp. Lợi nhuận có được từ việc kinh doanh, ngoài việc trang trải chi phí sinh hoạt cho bản thân và gia đình, chị B còn tích cực tài trợ cho các hoạt động thiện nguyện giúp đỡ các học sinh có hoàn cảnh khó khăn. Để có nguồn nguyên liệu an toàn và ổn định, chị đã hướng dẫn cho bà con nông dân quy trình sản xuất rau sạch và cam kết bao tiêu sản phẩm nhờ đó không chỉ mang lại hiệu quả kinh doanh cho cửa hàng mà còn góp phần giải quyết nhiều việc làm cho lao động nông thôn.", "o": ["Phương châm đặt chất lượng sản phẩm lên hàng đầu, luôn cam kết với khách hàng về chất lượng sản phẩm là thể hiện việc phân tích các điều kiện kinh doanh.", "Cửa hàng kinh doanh của chị B ngày càng hoạt động hiệu quả có nguyên nhân chủ quan là chị luôn thực hiện tốt trách nhiệm kinh doanh.", "Việc chị B giúp đỡ các học sinh có hoàn cảnh có khó khăn trong học tập là phù hợp với trách nhiệm pháp lý của mỗi doanh nghiệp.", "Đánh giá đúng về yếu tố khách hàng và thị trường là yếu tố giúp chị B kinh doanh thành công."], "a": [false, true, false, true], "e": "Đáp án: a) Sai; b) Đúng; c) Sai; d) Đúng.", "nguon": "Đề nguồn: 10_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 10.docx · Phần II câu 2 · khoá: gạch chân, khớp file ĐÁP ÁN"}, {"id": "L12-HK2-10-C27", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "dung_sai", "status": "cho_duyet", "q": "Trên cùng địa bàn một huyện có anh D là chủ doanh nghiệp kinh doanh thức ăn chăn nuôi; anh K là giám đốc một công ty tư nhân. Để tăng vốn kinh doanh, anh K chỉ đạo chị P là kế toán kê khai không đầy đủ số tiền thuế phải nộp của công ty nên anh K đã bị cơ quan chức năng xử phạt. Nghi ngờ anh V là nhân viên tố cáo hành vi của mình, anh K cố tình trì hoãn đóng bảo hiểm xã hội cho anh V như đã cam kết. Bức xúc, anh V tự ý nghỉ việc ở công ty của anh K và sang làm việc cho anh D. Một lần chứng kiến anh D bị cơ quan chức năng xử phạt về hành vi cung cấp sản phẩm không đảm bảo đúng tiêu chuẩn đã công bố, anh V đã kể lại sự việc cho vợ mình là chị T. Sau đó chị T đã viết bài đăng lên mạng xã hội vu khống công ty anh D vi phạm Luật lao động không tổ chức khám sức khỏe định kỳ cho công nhân khiến uy tín của công ty bị ảnh hưởng.", "o": ["Anh D và anh K đều phải chịu trách nhiệm pháp lý về hành vi vi phạm của mình trong kinh doanh.", "Anh D cung cấp sản phẩm không đảm bảo đúng tiêu chuẩn đã công bố là vi phạm trách nhiệm xã hội về pháp lý và kinh tế.", "Hành vi cố tình không đóng bảo hiểm xã hội của anh K cho anh V là vi phạm quyền của công dân về đảm bảo an sinh xã hội.", "Chị P không vi phạm nghĩa vụ của công dân trong việc thực hiện pháp luật về thuế."], "a": [true, true, true, false], "e": "Đáp án: a) Đúng; b) Đúng; c) Đúng; d) Sai.", "nguon": "Đề nguồn: 10_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 10.docx · Phần II câu 3 · khoá: gạch chân, khớp file ĐÁP ÁN"}, {"id": "L12-HK2-10-C28", "khoi": 12, "phan": "nguon", "bai": "", "muc_do": 0, "dang": "dung_sai", "status": "cho_duyet", "q": "Nước T và nước V đã ký kết hiệp định thương mại từ nhiều năm trước và cả hai nước đều là thành viên của tổ chức thương mại thế giới (WTO). Trong một lần tàu X là tàu thương mại của nước T đi qua lãnh hải của nước V không phải xin phép, trên cơ sở quyền qua lại vô hại. Đang đi theo tuyến hành lang mà nước V ấn định cho tàu thuyền nước ngoài, tàu X bỗng thay đổi hành trình, không đi theo tuyến đường ấn định nữa. Tại một khu vực khác trong lãnh hải nước V, tàu X dừng lại, chuyển xăng dầu buôn lậu từ tàu của mình sang hai tàu khác. Lực lượng cảnh sát biển nước P đã đuổi theo, bắt giữ tàu X cùng toàn bộ thuỷ thủ trên tàu. Tàu X được đưa vào bờ biển nước P để Xử lí vi phạm.", "o": ["Chỉ các nước có ký hiệp định thương mại với nhau thì tàu thuyền thương mại của hai nước này mới được đi vào khu vực lãnh hải của nhau.", "Việc bắt giữ tàu X cùng toàn bộ thủy thủ tàu là phù hợp với quyền chủ quyền của quốc gia ven biển.", "Hiệp định thương mại giữa nước T và nước V không phải là căn cứ để giải quyết vấn đề xâm phạm chủ quyền quốc gia giữa nước T và nước V.", "Nước T có quyền khởi kiện lên tổ chức WTO để kiện nước V về hành vi bắt giữ tàu thương mại đã vi phạm nguyên tắc tự do hóa thương mại của WTO."], "a": [false, false, true, false], "e": "Đáp án: a) Sai; b) Sai; c) Đúng; d) Sai.", "nguon": "Đề nguồn: 10_ĐỀ GV (có đáp án) - 10 ĐỀ - ĐỀ 10.docx · Phần II câu 4 · khoá: gạch chân, khớp file ĐÁP ÁN"}]}];
